		GetCompactBlock = 12,
		CompactBlock = 13,
		StemTransaction = 14,
		Transaction = 15,
		TxHashSetRequest = 16,
		TxHashSetArchive = 17,
		BanReason = 18,
		GetTransaction = 19,
		TransactionKernel = 20,
		GetOutputBitmapSegment = 21,
		OutputBitmapSegment = 22,
		GetOutputSegment = 23,
		OutputSegment = 24,
		GetRangeProofSegment = 25,
		RangeProofSegment = 26,
		GetKernelSegment = 27,
