        }
        query unsafety_check_result_for_const_arg(key: (LocalDefId, DefId)) -> &'tcx mir::UnsafetyCheckResult {
            desc {
                |tcx| "unsafety-checking the const argument `{}`",
                tcx.def_path_str(key.0.to_def_id())
            }
        }

