        query typeck(key: LocalDefId) -> &'tcx ty::TypeckResults<'tcx> {
            desc { |tcx| "type-checking `{}`", tcx.def_path_str(key.to_def_id()) }
            cache_on_disk_if { true }
        }
        query typeck_const_arg(
            key: (LocalDefId, DefId)
