        /// instead of invoking this query directly.
        query upstream_monomorphizations_for(def_id: DefId)
            -> Option<&'tcx FxHashMap<SubstsRef<'tcx>, CrateNum>> {
                desc { |tcx|
                    "collecting available upstream monomorphizations for `{}`",
