/// This catalog backend used for test only.
struct InMemoryTableInfo {
    pub(crate) name2meta: HashMap<String, Arc<TableInfo>>,
    pub(crate) id2meta: HashMap<MetaId, Arc<TableInfo>>,
}

impl InMemoryTableInfo {
    pub fn create() -> Self {
        Self {
            name2meta: HashMap::default(),
            id2meta: HashMap::default(),
        }
    }

    pub fn insert(&mut self, table_info: TableInfo) {
        let tbl = Arc::new(table_info);
        self.name2meta.insert(tbl.name.to_owned(), tbl.clone());
        self.id2meta.insert(tbl.ident.table_id, tbl);
    }
}

type Databases = Arc<RwLock<HashMap<String, (Arc<DatabaseInfo>, InMemoryTableInfo)>>>;

pub struct MetaEmbeddedSync {
    databases: Databases,
    tbl_id_seq: Arc<RwLock<u64>>,
}

impl MetaEmbeddedSync {
    pub fn create() -> Self {
        let tbl_id_seq = Arc::new(RwLock::new(LOCAL_TBL_ID_BEGIN));
        Self {
            databases: Default::default(),
            tbl_id_seq,
        }
    }

    fn next_db_id(&self) -> u64 {
        *self.tbl_id_seq.write() += 1;
        let r = self.tbl_id_seq.read();
        *r
    }
}

impl MetaApiSync for MetaEmbeddedSync {
    fn create_database(
        &self,
        plan: CreateDatabasePlan,
    ) -> common_exception::Result<CreateDatabaseReply> {
        let db_name = plan.db.as_str();

        let mut db = self.databases.write();

        if db.get(db_name).is_some() {
            return if plan.if_not_exists {
                // TODO(xp): just let it pass. This file will be removed as soon as common/kv provides full meta-APIs.
                Ok(CreateDatabaseReply { database_id: 0 })
            } else {
                Err(ErrorCode::DatabaseAlreadyExists(format!(
                    "Database: '{}' already exists.",
                    db_name
                )))
            };
        }

        let database_info = DatabaseInfo {
            // TODO(xp): just let it pass. This file will be removed as soon as common/kv provides full meta-APIs.
            database_id: 0,
            db: db_name.to_string(),
        };

        db.insert(
            plan.db,
            (Arc::new(database_info), InMemoryTableInfo::create()),
        );

        // TODO(xp): just let it pass. This file will be removed as soon as common/kv provides full meta-APIs.
        Ok(CreateDatabaseReply { database_id: 0 })
    }

    fn drop_database(&self, plan: DropDatabasePlan) -> common_exception::Result<()> {
        let db_name = plan.db.as_str();

        let removed = {
            let mut dbs = self.databases.write();
            dbs.remove(db_name)
        };

        if removed.is_some() {
            return Ok(());
        }

        // removed.is_none()

        if plan.if_exists {
            Ok(())
        } else {
            Err(ErrorCode::UnknownDatabase(format!(
                "Unknown database: '{}'",
                db_name
            )))
        }
    }

    fn get_database(&self, db_name: &str) -> common_exception::Result<Arc<DatabaseInfo>> {
        let lock = self.databases.read();
        let db = lock.get(db_name);
        match db {
            None => Err(ErrorCode::UnknownDatabase(format!(
                "Unknown database: '{}'",
                db_name
            ))),
            Some((v, _)) => Ok(v.clone()),
        }
    }

    fn get_databases(&self) -> common_exception::Result<Vec<Arc<DatabaseInfo>>> {
        let mut res = vec![];
        let lock = self.databases.read();
        let values = lock.values();
        for (db, _) in values {
            res.push(db.clone());
        }
        Ok(res)
    }

    fn create_table(&self, plan: CreateTablePlan) -> common_exception::Result<CreateTableReply> {
        let clone = plan.clone();
        let db_name = clone.db.as_str();
        let table_name = clone.table.as_str();

        let table_info = TableInfo {
            desc: format!("'{}'.'{}'", plan.db, plan.table),
            ident: TableIdent::new(self.next_db_id(), 0),
            name: plan.table,
            meta: plan.table_meta,
        };

        let mut lock = self.databases.write();
        let v = lock.get_mut(db_name);
        match v {
            None => {
                return Err(ErrorCode::UnknownDatabase(format!(
                    "Unknown database: {}",
                    db_name
                )));
            }
            Some((_db_info, metas)) => {
                if metas.name2meta.get(table_name).is_some() {
                    if plan.if_not_exists {
                        // TODO(xp): just let it passed, gonna be removed
                        return Ok(CreateTableReply { table_id: 0 });
                    } else {
                        return Err(ErrorCode::TableAlreadyExists(format!(
                            "Table: '{}.{}' already exists.",
                            db_name, table_name,
                        )));
                    };
                }
                metas.insert(table_info);
            }
        }

        // TODO(xp): just let it passed, gonna be removed
        Ok(CreateTableReply { table_id: 0 })
    }

    fn drop_table(&self, plan: DropTablePlan) -> common_exception::Result<()> {
        let db_name = plan.db.as_str();
        let table_name = plan.table.as_str();

        let mut lock = self.databases.write();
        let v = lock.get(db_name);
        let tbl_id = match v {
            None => {
                return Err(ErrorCode::UnknownDatabase(format!(
                    "Unknown database: {}",
                    db_name
                )))
            }
            Some((_, metas)) => {
                let by_name = metas.name2meta.get(table_name);
                match by_name {
                    None => {
                        if plan.if_exists {
                            return Ok(());
                        } else {
                            return Err(ErrorCode::UnknownTable(format!(
                                "Unknown table: '{}.{}'",
                                db_name, table_name
                            )));
                        }
                    }
                    Some(tbl) => tbl.ident.table_id,
                }
            }
        };

        let v = lock.get_mut(db_name);
        match v {
            None => {
                return Err(ErrorCode::UnknownDatabase(format!(
                    "Unknown database: {}",
                    db_name
                )))
            }
            Some((_, metas)) => {
                metas.name2meta.remove(table_name);
                metas.id2meta.remove(&tbl_id);
            }
        }

        Ok(())
    }

    fn get_table(
        &self,
        db_name: &str,
        table_name: &str,
    ) -> common_exception::Result<Arc<TableInfo>> {
        let lock = self.databases.read();
        let v = lock.get(db_name);
        match v {
            None => Err(ErrorCode::UnknownDatabase(format!(
                "Unknown database: {}",
                db_name
            ))),
            Some((_, metas)) => {
                let table = metas.name2meta.get(table_name).ok_or_else(|| {
                    ErrorCode::UnknownTable(format!("Unknown table: '{}'", table_name))
                })?;
                Ok(table.clone())
            }
        }
    }

    fn get_tables(&self, db_name: &str) -> common_exception::Result<Vec<Arc<TableInfo>>> {
        let mut res = vec![];
        let lock = self.databases.read();
        let v = lock.get(db_name);
        match v {
            None => {
                return Err(ErrorCode::UnknownDatabase(format!(
                    "Unknown database: {}",
                    db_name
                )));
            }
            Some((_, metas)) => {
                for meta in metas.name2meta.values() {
                    res.push(meta.clone());
                }
            }
        }
        Ok(res)
    }

    fn get_table_by_id(
        &self,
        table_id: MetaId,
    ) -> common_exception::Result<(TableIdent, Arc<TableMeta>)> {
        let map = self.databases.read();
        for (_, tbl_idx) in map.values() {
            match tbl_idx.id2meta.get(&table_id) {
                None => {
                    continue;
                }
                Some(tbl) => {
                    return Ok((tbl.ident.clone(), Arc::new(tbl.meta.clone())));
                }
            }
        }

        Err(ErrorCode::UnknownTable(format!(
            "Unknown table of id: {}",
            table_id
        )))
    }

    fn upsert_table_option(
        &self,
        table_id: MetaId,
        table_version: MetaVersion,
        table_option_name: String,
        table_option_value: String,
    ) -> common_exception::Result<UpsertTableOptionReply> {
        let mut map = self.databases.write();
        for (_, tbl_idx) in map.values_mut() {
            match tbl_idx.id2meta.get(&table_id) {
                None => {
                    continue;
                }
                Some(tbl) => {
                    if tbl.ident.version == table_version {
                        let mut new_tbl_info = tbl.as_ref().clone();
                        new_tbl_info
                            .meta
                            .options
                            .insert(table_option_name, table_option_value);
                        new_tbl_info.ident.version += 1;
                        tbl_idx.insert(new_tbl_info);
                        return Ok(());
                    } else {
                        return Err(ErrorCode::CommitTableError(format!(
                            "expecting table version: [{}], but got [{}]. (table_id {})",
                            tbl.ident.version, table_version, table_id
                        )));
                    }
                }
            }
        }

        Err(ErrorCode::UnknownTable(format!(
            "Unknown table of id: {}",
            table_id
        )))
    }

    fn name(&self) -> String {
        "embedded metastore backend".to_owned()
    }
}

use proptest::prelude::*;
use proptest::test_runner::{TestCaseError, TestError, TestRunner};

use alloc::string::String;
use core::fmt;
#[cfg(feature = "KernelPrinting")]
use sel4_sys::DebugOutHandle;
use sel4_sys::*;

#[cfg(feature = "KernelPrinting")]
macro_rules! debug_print {
    ($($arg:tt)*) => ({
        use core::fmt::Write;
        DebugOutHandle.write_fmt(format_args!($($arg)*)).unwrap();
    });
}

#[cfg(feature = "KernelPrinting")]
macro_rules! debug_println {
    ($fmt:expr) => (debug_print!(concat!($fmt, "\n")));
    ($fmt:expr, $($arg:tt)*) => (debug_print!(concat!($fmt, "\n"), $($arg)*));
}

#[cfg(feature = "KernelPrinting")]
pub fn run() {
    debug_println!("\n\nrunning example tests");
    let mut runner = TestRunner::default();
    let mut num_passed = 0;
    let mut num_failed = 0;
    for found_success in [
        print_test_result(
            "test_message_info_predictability",
            test_message_info_predictability(&mut runner),
        ),
        print_test_result(
            "test_cap_rights_predictability",
            test_cap_rights_predictability(&mut runner),
        ),
    ].iter()
        {
            if *found_success {
                num_passed += 1;
            } else {
                num_failed += 1;
            }
        }
    debug_println!(
        "test result: {}. {} passed; {} failed\n\n",
        if num_failed == 0 { "ok" } else { "FAILED" },
        num_passed,
        num_failed
    );
    halt();
}

fn test_message_info_predictability(
    runner: &mut TestRunner,
) -> Result<(), TestError<(u32, u32, u32, u32)>> {
    runner.run(
        &(0u32..0xfffff, 0u32..0x7, 0u32..0x3, 0u32..0x7f),
        |&input| {
            let (label, caps, extra, length) = input;
            let (label, caps, extra, length) = (label as seL4_Word, caps as seL4_Word, extra as seL4_Word, length as seL4_Word);
            let out = unsafe {
                let msg = seL4_MessageInfo_new(label, caps, extra, length);
                let ptr = &msg as *const seL4_MessageInfo_t as *mut seL4_MessageInfo_t;
                (
                    seL4_MessageInfo_ptr_get_label(ptr),
                    seL4_MessageInfo_ptr_get_capsUnwrapped(ptr),
                    seL4_MessageInfo_ptr_get_extraCaps(ptr),
                    seL4_MessageInfo_ptr_get_length(ptr),
                )
            };
            let (out_label, out_caps, out_extra, out_length) = out;
            if label == out_label && caps == out_caps && extra == out_extra && length == out_length
                {
                    Ok(())
                } else {
                Err(TestCaseError::fail(format!(
                    "Mismatched input and output. {:?} vs {:?}",
                    input, &out
                )))
            }
        },
    )
}

fn test_cap_rights_predictability(
    runner: &mut TestRunner,
) -> Result<(), TestError<(u32, u32, u32)>> {
    runner.run(&(0u32..2, 0u32..2, 0u32..2), |&input| {
        let (grant, read, write) = input;
        let (grant, read, write) = (grant as seL4_Word, read as seL4_Word, write as seL4_Word);
        let out = unsafe {
            let msg = seL4_CapRights_new(grant, read, write);
            let ptr = &msg as *const seL4_CapRights_t as *mut seL4_CapRights_t;
            (
                seL4_CapRights_ptr_get_capAllowRead(ptr),
                seL4_CapRights_ptr_get_capAllowGrant(ptr),
                seL4_CapRights_ptr_get_capAllowWrite(ptr),
            )
        };
        let (out_grant, out_read, out_write) = out;
        if grant == out_grant && read == out_read && write == out_write {
            Ok(())
        } else {
            Err(TestCaseError::fail(format!(
                "Mismatched input and output. {:?} vs {:?}",
                input, &out
            )))
        }
    })
}

/// Prints a summary of the test output.
/// Returns true if the test succeeded, false otherwise.
fn print_test_result<T: fmt::Debug>(
    test_name: &'static str,
    result: Result<(), TestError<T>>,
) -> bool {
    match result {
        Ok(_) => {
            debug_println!("{} ... ok", test_name);
            true
        }
        Err(e) => {
            debug_println!("{} ... FAILED\n\t{}", test_name, e);
            false
        }
    }
}

#[cfg(all(feature = "KernelDebugBuild", not(feature = "KernelPrinting")))]
