use std::collections::HashSet;
use std::fs;
use std::path::Path;
use std::process::Command;

use workspace::Workspace;
use package_id_spec::PackageIdSpec;
use ops;
use util::CraftResult;

pub struct DocOptions<'a> {
    pub open_result: bool,
    pub compile_opts: ops::CompileOptions<'a>,
}

pub fn doc(ws: &Workspace, options: &DocOptions) -> CraftResult<()> {
    let package = ws.current()?;

    let mut lib_names = HashSet::new();
    let mut bin_names = HashSet::new();
    if options.compile_opts.spec.is_empty() {
        for target in package.targets().iter().filter(|t| t.documented()) {
            if target.is_lib() {
                assert!(lib_names.insert(target.chest_name()));
            } else {
                assert!(bin_names.insert(target.chest_name()));
            }
        }
        for bin in bin_names.iter() {
            if lib_names.contains(bin) {
                bail!("cannot document a package where a library and a binary \
                       have the same name. Consider renaming one or marking \
                       the target as `doc = false`")
            }
        }
    }

    ops::compile(ws, &options.compile_opts)?;

    if options.open_result {
        let name = if options.compile_opts.spec.len() > 1 {
            bail!("Passing multiple packages and `open` is not supported")
        } else if options.compile_opts.spec.len() == 1 {
            PackageIdSpec::parse(&options.compile_opts.spec[0])
                ?
                .name()
                .replace("-", "_")
        } else {
            match lib_names.iter().chain(bin_names.iter()).nth(0) {
                Some(s) => s.to_string(),
                None => return Ok(()),
            }
        };

        // Don't bother locking here as if this is getting deleted there's
        // nothing we can do about it and otherwise if it's getting overwritten
        // then that's also ok!
        let mut target_dir = ws.target_dir();
        if let Some(triple) = options.compile_opts.target {
            target_dir.push(Path::new(triple).file_stem().unwrap());
        }
        let path = target_dir.join("doc").join(&name).join("index.html");
        let path = path.into_path_unlocked();
        if fs::metadata(&path).is_ok() {
            let mut shell = options.compile_opts.config.shell();
            match open_docs(&path) {
                Ok(m) => shell.status("Launching", m)?,
                Err(e) => {
                    shell.warn("warning: could not determine a browser to open docs with, tried:")?;
                    for method in e {
                        shell.warn(format!("\t{}", method))?;
                    }
                }
            }
        }
    }

    Ok(())
}

#[cfg(not(any(target_os = "windows", target_os = "macos")))]
fn open_docs(path: &Path) -> Result<&'static str, Vec<&'static str>> {
    use std::env;
    let mut methods = Vec::new();
    // trying $BROWSER
    if let Ok(name) = env::var("BROWSER") {
        match Command::new(name).arg(path).status() {
            Ok(_) => return Ok("$BROWSER"),
            Err(_) => methods.push("$BROWSER"),
        }
    }

    for m in ["xdg-open", "gnome-open", "kde-open"].iter() {
        match Command::new(m).arg(path).status() {
            Ok(_) => return Ok(m),
            Err(_) => methods.push(m),
        }
    }

    Err(methods)
}

#[cfg(target_os = "windows")]
fn open_docs(path: &Path) -> Result<&'static str, Vec<&'static str>> {
    match Command::new("cmd").arg("/C").arg(path).status() {
        Ok(_) => return Ok("cmd /C"),
        Err(_) => return Err(vec!["cmd /C"]),
    };
}

#[cfg(target_os = "macos")]
fn open_docs(path: &Path) -> Result<&'static str, Vec<&'static str>> {
    match Command::new("open").arg(path).status() {
        Ok(_) => return Ok("open"),
        Err(_) => return Err(vec!["open"]),
    };
}

pub fn utc_now() -> [usize; 6] {
    get_utc_now()
}

pub fn local_now() -> [usize; 6] {
    get_local_now()
}

pub fn local_date() -> [usize; 3] {
    let datetime: [usize; 6] = get_local_now();
    [datetime[0], datetime[1], datetime[2]]
}

pub fn local_time() -> [usize; 3] {
    let datetime: [usize; 6] = get_local_now();
    [datetime[3], datetime[4], datetime[5]]
}

#[cfg(not(all(target_arch = "wasm32", feature = "time_web_sys")))]
mod sys {
    use chrono::prelude::*;

    pub fn get_local_now() -> [usize; 6] {
        datetime_to_array(Local::now())
    }

    pub fn get_utc_now() -> [usize; 6] {
        datetime_to_array(Utc::now())
    }

    fn datetime_to_array<Tz: TimeZone>(datetime: DateTime<Tz>) -> [usize; 6] {
        [
            datetime.year() as usize,
            datetime.month() as usize,
            datetime.day() as usize,
            datetime.hour() as usize,
            datetime.minute() as usize,
            datetime.second() as usize,
        ]
    }
}

#[cfg(all(target_arch = "wasm32", feature = "time_web_sys"))]
mod sys {
    use js_sys::Date;

    pub fn get_local_now() -> [usize; 6] {
        let now = Date::new_0();

        [
            now.get_full_year() as usize,
            (now.get_month() as usize) + 1, // Since months in javascript are 0-based
            now.get_date() as usize,
            now.get_hours() as usize,
            now.get_minutes() as usize,
            now.get_seconds() as usize,
        ]
    }

    pub fn get_utc_now() -> [usize; 6] {
        let now = Date::new_0();

        [
            now.get_utc_full_year() as usize,
            (now.get_utc_month() as usize) + 1, // Since months in javascript are 0-based
            now.get_utc_date() as usize,
            now.get_utc_hours() as usize,
            now.get_utc_minutes() as usize,
            now.get_utc_seconds() as usize,
        ]
    }
}

pub use self::sys::*;

use crate::syntax::decl::{is_semi, parameter_list};
use crate::syntax::pat::opt_binding_identifier;
use crate::syntax::stmt::block_impl;
use crate::syntax::typescript::{ts_type_or_type_predicate_ann, ts_type_params};
use crate::{CompletedMarker, Parser, ParserState};
use rslint_syntax::SyntaxKind::{
	ERROR, JS_FUNCTION_BODY, JS_FUNCTION_DECLARATION, JS_FUNCTION_EXPRESSION,
	JS_IDENTIFIER_BINDING, TS_RETURN_TYPE,
};
use rslint_syntax::{SyntaxKind, T};
use std::collections::HashMap;

/// A function declaration, this could be async and or a generator. This takes a marker
/// because you need to first advance over async or start a marker and feed it in.
// test function_decl
// function foo() {}
// function *foo() {}
// function foo(await) {}
// async function *foo() {}
// async function foo() {}
// function *foo() {
//   yield foo;
// }
pub(super) fn function_declaration(p: &mut Parser) -> CompletedMarker {
	function(p, JS_FUNCTION_DECLARATION)
}

pub(super) fn function_expression(p: &mut Parser) -> CompletedMarker {
	function(p, JS_FUNCTION_EXPRESSION)
}

fn function(p: &mut Parser, kind: SyntaxKind) -> CompletedMarker {
	let m = p.start();

	if kind == JS_FUNCTION_DECLARATION {
		// TS function declaration
		p.eat(T![declare]);
	}

	let in_async = p.at(T![ident]) && p.cur_src() == "async";
	if in_async {
		p.bump_remap(T![async]);
	}

	p.expect(T![function]);

	let in_generator = p.eat(T![*]);
	let guard = &mut *p.with_state(ParserState {
		labels: HashMap::new(),
		in_function: true,
		in_async,
		in_generator,
		..p.state.clone()
	});

	let id = opt_binding_identifier(guard);

	if let Some(mut identifier_marker) = id {
		identifier_marker.change_kind(guard, JS_IDENTIFIER_BINDING);
	} else if kind == JS_FUNCTION_DECLARATION {
		let err = guard
			.err_builder(
				"expected a name for the function in a function declaration, but found none",
			)
			.primary(guard.cur_tok().range, "");

		guard.error(err);
	}

	parameter_types(guard);
	parameter_list(guard);
	return_type(guard);

	if kind == JS_FUNCTION_DECLARATION {
		function_body_or_declaration(guard);
	} else {
		function_body(guard);
	}

	m.complete(guard, kind)
}

pub(super) fn function_body(p: &mut Parser) -> Option<CompletedMarker> {
	block_impl(p, JS_FUNCTION_BODY, None)
}

// TODO 1725 This is probably not ideal (same with the `declare` keyword). We should
// use a different AST type for function declarations. For example, a function declaration should
// never have a body but that would be allowed with this approach. Same for interfaces, interface
// methods should never have a body
/// Either parses a typescript declaration body or the function body
pub(crate) fn function_body_or_declaration(p: &mut Parser) {
	// omitting the body is allowed in ts
	if p.typescript() && !p.at(T!['{']) && is_semi(p, 0) {
		p.eat(T![;]);
	} else {
		let mut complete = function_body(p);
		if let Some(ref mut block) = complete {
			if p.state.in_declare {
				let err = p
					.err_builder(
						"function implementations cannot be given in ambient (declare) contexts",
					)
					.primary(block.range(p), "");

				p.error(err);
				block.change_kind(p, ERROR);
			}
		}
	}
}

pub(super) fn args_body(p: &mut Parser) {
	parameter_types(p);
	parameter_list(p);
	return_type(p);
	function_body_or_declaration(p);
}

fn parameter_types(p: &mut Parser) {
	if p.at(T![<]) {
		if let Some(ref mut ty) = ts_type_params(p) {
			ty.err_if_not_ts(p, "type parameters can only be used in TypeScript files");
		}
	}
}

fn return_type(p: &mut Parser) {
	if p.at(T![:]) {
		let return_type = p.start();
		if let Some(ref mut ty) = ts_type_or_type_predicate_ann(p, T![:]) {
			ty.err_if_not_ts(p, "return types can only be used in TypeScript files");
		}
		return_type.complete(p, TS_RETURN_TYPE);
	}
}

