macro_rules! parse_dispatch {
    ($event: expr, $name: expr) => {
        serde_json::from_value($event).map_err(|_| PandaError::InvalidPayloadFormat($name))
    };
}

#[derive(Debug)]
pub(crate) enum Event {
    // Discord events
    Dispatch(DispatchEvent), // op: 0
    Reconnect,               // op: 7
    InvalidSession(bool),    // op: 9
    Hello(u64),              // op: 10
    HeartbeatACK,            // op: 11
    Close(PandaError),
}

#[derive(Debug)]
pub(crate) enum DispatchEvent {
    Ready(Ready),
    Resumed,
    Reconnect,
    ChannelCreate(ChannelCreate),
    ChannelUpdate(ChannelUpdate),
    ChannelDelete(ChannelDelete),
    ChannelPinsUpdate(ChannelPinsUpdate),

    // guild
    GuildCreate(GuildCreate),
    GuildUpdate(GuildUpdate),
    GuildDelete(GuildDelete),
    GuildBanAdd(GuildBanAdd),
    GuildBanRemove(GuildBanRemove),
    GuildEmojisUpdate(GuildEmojisUpdate),
    GuildIntegrationsUpdate(GuildIntegrationsUpdate),
    GuildMemberAdd(GuildMemberAdd),
    GuildMemberRemove(GuildMemberRemove),
    GuildMemberUpdate(GuildMemberUpdate),
    GuildMembersChunk(GuildMembersChunk),
    GuildRoleCreate(GuildRoleCreate),
    GuildRoleUpdate(GuildRoleUpdate),
    GuildRoleDelete(GuildRoleDelete),

    // message
    MessageCreate(MessageCreate),
    MessageUpdate(MessageUpdate),
    MessageDelete(MessageDelete),
    MessageDeleteBulk(MessageDeleteBulk),
    MessageReactionAdd(MessageReactionAdd),
    MessageReactionRemove(MessageReactionRemove),
    MessageReactionRemoveAll(MessageReactionRemoveAll),
    MessageReactionRemoveEmoji(MessageReactionRemoveEmoji),

    // presence
    PresenceUpdate(PresenceUpdate),
    TypingStart(TypingStart),
    UserUpdate(UserUpdate),

    // voice
    VoiceStateUpdate(VoiceStateUpdate),
    VoiceServerUpdate(VoiceServerUpdate),
}

impl TryFrom<Payload> for Event {
    type Error = PandaError;

    fn try_from(p: Payload) -> Result<Event> {
        match p.op {
            Opcode::Dispatch => Ok(Event::Dispatch(handle_dispatch(p)?)),
            Opcode::Reconnect => Ok(Event::Reconnect),
            Opcode::InvalidSessionData => {
                let d =
                    p.d.ok_or_else(|| PandaError::InvalidPayloadFormat("INVALID SESSION DATA"))?;
                let resumable = match d {
                    Value::Bool(v) => v,
                    _ => return Err(PandaError::InvalidPayloadFormat("INVALID SESSION DATA")),
                };

                Ok(Event::InvalidSession(resumable))
            }
            Opcode::Hello => {
                #[derive(serde::Deserialize)]
                struct Hello {
                    heartbeat_interval: u64,
                }
                let d = p.d.ok_or_else(|| PandaError::InvalidPayloadFormat("HELLO"))?;
                let hello: Hello = serde_json::from_value(d).unwrap();

                Ok(Event::Hello(hello.heartbeat_interval))
            }
            Opcode::HeartbeatACK => Ok(Event::HeartbeatACK),
            _ => Err(PandaError::UnexpectedPayloadReceived),
        }
    }
}

///
fn handle_dispatch(p: Payload) -> Result<DispatchEvent> {
    let d = p.d.ok_or_else(|| PandaError::InvalidPayloadFormat("D"))?;
    let t = p.t.ok_or_else(|| PandaError::InvalidPayloadFormat("T"))?;

    match t.as_str() {
        "READY" => {
            let event = parse_dispatch!(d, "READY")?;
            Ok(DispatchEvent::Ready(event))
        }
        "RESUMED" => Ok(DispatchEvent::Resumed),
        "RECONNECT" => Ok(DispatchEvent::Reconnect),
        // Channel
        "CHANNEL_CREATE" => {
            let event = parse_dispatch!(d, "CHANNEL_CREATE")?;
            Ok(DispatchEvent::ChannelCreate(event))
        }
        "CHANNEL_UPDATE" => {
            let event = parse_dispatch!(d, "CHANNEL_CREATE")?;
            Ok(DispatchEvent::ChannelUpdate(event))
        }
        "CHANNEL_DELETE" => {
            let event = parse_dispatch!(d, "CHANNEL_CREATE")?;
            Ok(DispatchEvent::ChannelDelete(event))
        }
        "CHANNEL_PINS_UPDATE" => {
            let event = parse_dispatch!(d, "CHANNEL_PINS_UPDATE")?;
            Ok(DispatchEvent::ChannelPinsUpdate(event))
        }

        // Guild
        "GUILD_CREATE" => {
            let event = parse_dispatch!(d, "GUILD_CREATE")?;
            Ok(DispatchEvent::GuildCreate(event))
        }
        "GUILD_UPDATE" => {
            let event = parse_dispatch!(d, "GUILD_UPDATE")?;
            Ok(DispatchEvent::GuildUpdate(event))
        }
        "GUILD_DELETE" => {
            let event = parse_dispatch!(d, "GUILD_DELETE")?;
            Ok(DispatchEvent::GuildDelete(event))
        }
        "GUILD_BAN_ADD" => {
            let event = parse_dispatch!(d, "GUILD_BAN_ADD")?;
            Ok(DispatchEvent::GuildBanAdd(event))
        }
        "GUILD_BAN_REMOVE" => {
            let event = parse_dispatch!(d, "GUILD_BAN_REMOVE")?;
            Ok(DispatchEvent::GuildBanRemove(event))
        }
        "GUILD_EMOJIS_UPDATE" => {
            let event = parse_dispatch!(d, "GUILD_EMOJIS_UPDATE")?;
            Ok(DispatchEvent::GuildEmojisUpdate(event))
        }
        "GUILD_INTEGRATIONS_UPDATE" => {
            let event = parse_dispatch!(d, "GUILD_INTEGRATIONS_UPDATE")?;
            Ok(DispatchEvent::GuildIntegrationsUpdate(event))
        }
        "GUILD_MEMBER_ADD" => {
            let event = parse_dispatch!(d, "GUILD_MEMBER_ADD")?;
            Ok(DispatchEvent::GuildMemberAdd(event))
        }
        "GUILD_MEMBER_UPDATE" => {
            let event = parse_dispatch!(d, "GUILD_MEMBER_UPDATE")?;
            Ok(DispatchEvent::GuildMemberUpdate(event))
        }
        "GUILD_MEMBER_REMOVE" => {
            let event = parse_dispatch!(d, "GUILD_MEMBER_REMOVE")?;
            Ok(DispatchEvent::GuildMemberRemove(event))
        }
        "GUILD_MEMBER_CHUNK" => {
            let event = parse_dispatch!(d, "GUILD_MEMBER_CHUNK")?;
            Ok(DispatchEvent::GuildMembersChunk(event))
        }
        "GUILD_ROLE_CREATE" => {
            let event = parse_dispatch!(d, "GUILD_ROLE_CREATE")?;
            Ok(DispatchEvent::GuildRoleCreate(event))
        }
        "GUILD_ROLE_UPDATE" => {
            let event = parse_dispatch!(d, "GUILD_ROLE_CREATE")?;
            Ok(DispatchEvent::GuildRoleUpdate(event))
        }
        "GUILD_ROLE_DELETE" => {
            let event = parse_dispatch!(d, "GUILD_ROLE_DELETE")?;
            Ok(DispatchEvent::GuildRoleDelete(event))
        }

        // Message
        "MESSAGE_CREATE" => {
            let event = parse_dispatch!(d, "MESSAGE_CREATE")?;
            Ok(DispatchEvent::MessageCreate(event))
        }
        "MESSAGE_UPDATE" => {
            let event = parse_dispatch!(d, "MESSAGE_UPDATE")?;
            Ok(DispatchEvent::MessageUpdate(event))
        }
        "MESSAGE_DELETE" => {
            let event = parse_dispatch!(d, "MESSAGE_DELETE")?;
            Ok(DispatchEvent::MessageDelete(event))
        }
        "MESSAGE_DELETE_BULK" => {
            let event = parse_dispatch!(d, "MESSAGE_DELETE_BULK")?;
            Ok(DispatchEvent::MessageDeleteBulk(event))
        }
        "MESSAGE_REACTION_ADD" => {
            let event = parse_dispatch!(d, "MESSAGE_REACTION_ADD")?;
            Ok(DispatchEvent::MessageReactionAdd(event))
        }
        "MESSAGE_REACTION_REMOVE" => {
            let event = parse_dispatch!(d, "MESSAGE_REACTION_REMOVE")?;
            Ok(DispatchEvent::MessageReactionRemove(event))
        }
        "MESSAGE_REACTION_REMOVE_ALL" => {
            let event = parse_dispatch!(d, "MESSAGE_REACTION_REMOVE_ALL")?;
            Ok(DispatchEvent::MessageReactionRemoveAll(event))
        }
        "MESSAGE_REACTION_REMOVE_EMOJI" => {
            let event = parse_dispatch!(d, "MESSAGE_REACTION_REMOVE_EMOJI")?;
            Ok(DispatchEvent::MessageReactionRemoveEmoji(event))
        }

        // Presence
        "PRESENCE_UPDATE" => {
            let event = parse_dispatch!(d, "PRESENCE_UPDATE")?;
            Ok(DispatchEvent::PresenceUpdate(event))
        }
        "TYPING_START" => {
            let event = parse_dispatch!(d, "TYPING_START")?;
            Ok(DispatchEvent::TypingStart(event))
        }
        "USER_UPDATE" => {
            let event = parse_dispatch!(d, "USER_UPDATE")?;
            Ok(DispatchEvent::UserUpdate(event))
        }

        // Voice
        "VOICE_STATE_UPDATE" => {
            let event = parse_dispatch!(d, "VOICE_STATE_UPDATE")?;
            Ok(DispatchEvent::VoiceStateUpdate(event))
        }
        "VOICE_SERVER_UPDATE" => {
            let event = parse_dispatch!(d, "VOICE_SERVER_UPDATE")?;
            Ok(DispatchEvent::VoiceServerUpdate(event))
        }
        _ => Err(PandaError::InvalidPayloadFormat("Unkown D event")),
    }
}

// From clients/src/main/java/org/apache/kafka/common/feature/Features.java

use super::base_version_range::{BaseVersionRange, BaseVersionRangeError};
use super::finalized_version_range::FinalizedVersionRange;
use super::supported_version_range::SupportedVersionRange;
use std::collections::HashMap;
use std::fmt;
use thiserror::Error;
use tracing::debug;

#[derive(Debug, Clone, PartialEq)]
pub enum VersionRangeType {
    Supported(HashMap<String, SupportedVersionRange>),
    Finalized(HashMap<String, FinalizedVersionRange>),
}

impl fmt::Display for VersionRangeType {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let collection_str: String = match &self {
            // RAFKA TODO: Consider printing which type of Version Range is being used.
            Self::Supported(supported) => supported
                .iter()
                .map(|(key, val)| format!("({} -> {})", key, val))
                .collect::<Vec<String>>()
                .join(", "),
            Self::Finalized(finalized) => finalized
                .iter()
                .map(|(key, val)| format!("({} -> {})", key, val))
                .collect::<Vec<String>>()
                .join(", "),
        };
        write!(f, "{}", collection_str)
    }
}

impl VersionRangeType {
    /// Returns the internal HashMap is empty status
    pub fn is_empty(&self) -> bool {
        match self {
            Self::Supported(supported) => supported.is_empty(),
            Self::Finalized(finalized) => finalized.is_empty(),
        }
    }

    /// Tries to fetch an item by key in the underlying finalized store
    pub fn get_finalized_key(&self, key: &str) -> Option<&FinalizedVersionRange> {
        match self {
            Self::Supported(_) => {
                // RAFKA TODO: Maybe use Traits and this wouldn't happen
                panic!("Attempt to fetch Finalized key from SupportedVersionRange")
            },
            Self::Finalized(finalized) => finalized.get(key),
        }
    }

    /// Tries to fetch an item by key in the underlying supported store
    pub fn get_supported_key(&self, key: &str) -> Option<&SupportedVersionRange> {
        match self {
            Self::Supported(supported) => supported.get(key),
            Self::Finalized(_) => {
                // RAFKA TODO: Maybe use Traits and this wouldn't happen
                panic!("Attempt to fetch Finalized key from SupportedVersionRange")
            },
        }
    }

    /// Attempts to return the a VersionRangeType from a string containing json
    pub fn try_from_json_string_as_finalized(input: &str) -> Result<Self, BaseVersionRangeError> {
        debug!("Attempting to build VersionRangeType from String: {}", input);
        match serde_json::from_str(input)? {
            serde_json::Value::Object(data) => {
                let mut res: HashMap<String, FinalizedVersionRange> = HashMap::new();
                for (feature_name, feature_map) in &data {
                    debug!("Processing feature {}", feature_name);
                    res.insert(
                        feature_name.to_string(),
                        FinalizedVersionRange::try_from_json(feature_map)?,
                    );
                }
                Ok(Self::Finalized(res))
            },
            serde_json::Value::Null => {
                // The features may be empty
                let res: HashMap<String, FinalizedVersionRange> = HashMap::new();
                Ok(Self::Finalized(res))
            },
            _ => Err(BaseVersionRangeError::IncorrectJsonFormat),
        }
    }
}

/// Represents an immutable dictionary with key being feature name, and value being
/// either Supported or Finalized VersionRanges
#[derive(Debug, Clone, PartialEq)]
pub struct Features {
    pub features: VersionRangeType,
}

#[derive(Debug, Error)]
pub enum FeaturesError {
    #[error("Provided features can not be empty")]
    EmptyVersionRangeType,
    #[error("Features map can not be absent in: {0}")]
    FeaturesMapEmpty(String),
    #[error("Features map is invalid, .features value is malformed.")]
    FeaturesMapInvalid(String),
    #[error("BaseVersionRange {0:?}")]
    BaseVersionRange(#[from] BaseVersionRangeError),
}

impl Features {
    /// Creates a Features struct of type SupportedVersionRange
    pub fn supported_features(features: HashMap<String, SupportedVersionRange>) -> Self {
        Self { features: VersionRangeType::Supported(features) }
    }

    /// Creates a Features struct of type FinalizedVersionRange
    pub fn finalized_features(features: HashMap<String, FinalizedVersionRange>) -> Self {
        Self { features: VersionRangeType::Finalized(features) }
    }

    pub fn is_empty(&self) -> bool {
        self.features.is_empty()
    }

    /// Looks up an item from the features HashMap and returns an Optional found VersionRangeType
    pub fn get_finalized(&self, feature: &str) -> Option<&FinalizedVersionRange> {
        self.features.get_finalized_key(feature)
    }

    /// Looks up an item from the features HashMap and returns an Optional found VersionRangeType
    pub fn get_supported(&self, feature: &str) -> Option<&SupportedVersionRange> {
        self.features.get_supported_key(feature)
    }

    pub fn empty_supported_features() -> Self {
        let res: HashMap<String, SupportedVersionRange> = HashMap::new();
        Self { features: VersionRangeType::Supported(res) }
    }

    pub fn empty_finalized_features() -> Self {
        let res: HashMap<String, FinalizedVersionRange> = HashMap::new();
        Self { features: VersionRangeType::Finalized(res) }
    }

    /// Attemps to parse the "features" value, which contains an internal JSON that should map into
    /// the features vector
    pub fn parse_finalized_features_json_value(
        input: &serde_json::Value,
        features_key: &str,
    ) -> Result<Self, FeaturesError> {
        match input[features_key].as_str() {
            Some(val) => {
                debug!("Decoding features value from json");
                Ok(Features {
                    features: VersionRangeType::try_from_json_string_as_finalized(&val)?,
                })
            },
            None => Err(FeaturesError::FeaturesMapEmpty(input.to_string())),
        }
    }
}

impl fmt::Display for Features {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Features{}", &self.features)
    }
}

