            let mut a = a;
            let mut c = a.accept().unwrap();
            assert_eq!(c.read_to_end(), Ok(vec!()));
            c.write(&[1]).unwrap();
        });

        let mut s = TcpStream::connect(addr).unwrap();
        assert!(s.inner.close_write().is_ok());
        assert!(s.write(&[1]).is_err());
        assert_eq!(s.read_to_end(), Ok(vec!(1)));
    }

    #[test]
    fn accept_timeout() {
        let addr = next_test_ip4();
        let mut a = TcpListener::bind(addr).unwrap().listen().unwrap();

        a.set_timeout(Some(10));

        // Make sure we time out once and future invocations also time out
        let err = a.accept().err().unwrap();
        assert_eq!(err.kind, TimedOut);
        let err = a.accept().err().unwrap();
        assert_eq!(err.kind, TimedOut);

        // Also make sure that even though the timeout is expired that we will
        // continue to receive any pending connections.
        //
        // FIXME: freebsd apparently never sees the pending connection, but
        //        testing manually always works. Need to investigate this
        //        flakiness.
        if !cfg!(target_os = "freebsd") {
            let (tx, rx) = channel();
            let _t = thread::spawn(move|| {
                tx.send(TcpStream::connect(addr).unwrap()).unwrap();
            });
            let _l = rx.recv().unwrap();
            for i in 0..1001 {
                match a.accept() {
                    Ok(..) => break,
                    Err(ref e) if e.kind == TimedOut => {}
                    Err(e) => panic!("error: {}", e),
                }
                ::thread::yield_now();
                if i == 1000 { panic!("should have a pending connection") }
            }
        }

        // Unset the timeout and make sure that this always blocks.
        a.set_timeout(None);
        let _t = thread::spawn(move|| {
            drop(TcpStream::connect(addr).unwrap());
        });
        a.accept().unwrap();
    }

    #[test]
    fn close_readwrite_smoke() {
        let addr = next_test_ip4();
        let a = TcpListener::bind(addr).listen().unwrap();
        let (_tx, rx) = channel::<()>();
        thread::spawn(move|| {
            let mut a = a;
            let _s = a.accept().unwrap();
            let _ = rx.recv().unwrap();
        });

        let mut b = [0];
        let mut s = TcpStream::connect(addr).unwrap();
        let mut s2 = s.clone();

        // closing should prevent reads/writes
        s.close_write().unwrap();
        assert!(s.write(&[0]).is_err());
        s.close_read().unwrap();
        assert!(s.read(&mut b).is_err());

        // closing should affect previous handles
        assert!(s2.write(&[0]).is_err());
        assert!(s2.read(&mut b).is_err());

        // closing should affect new handles
        let mut s3 = s.clone();
        assert!(s3.write(&[0]).is_err());
        assert!(s3.read(&mut b).is_err());

        // make sure these don't die
        let _ = s2.close_read();
        let _ = s2.close_write();
        let _ = s3.close_read();
        let _ = s3.close_write();
    }

    #[test]
    fn close_read_wakes_up() {
        let addr = next_test_ip4();
        let a = TcpListener::bind(addr).listen().unwrap();
        let (_tx, rx) = channel::<()>();
        thread::spawn(move|| {
            let mut a = a;
            let _s = a.accept().unwrap();
            let _ = rx.recv().unwrap();
        });

        let mut s = TcpStream::connect(addr).unwrap();
        let s2 = s.clone();
        let (tx, rx) = channel();
        let _t = thread::spawn(move|| {
            let mut s2 = s2;
            assert!(s2.read(&mut [0]).is_err());
            tx.send(()).unwrap();
        });
        // this should wake up the child task
        s.close_read().unwrap();

        // this test will never finish if the child doesn't wake up
        rx.recv().unwrap();
    }

    #[test]
    fn readwrite_timeouts() {
        let addr = next_test_ip6();
        let mut a = TcpListener::bind(addr).listen().unwrap();
        let (tx, rx) = channel::<()>();
        thread::spawn(move|| {
            let mut s = TcpStream::connect(addr).unwrap();
            rx.recv().unwrap();
            assert!(s.write(&[0]).is_ok());
            let _ = rx.recv();
        });

        let mut s = a.accept().unwrap();
        s.set_timeout(Some(20));
        assert_eq!(s.read(&mut [0]).err().unwrap().kind, TimedOut);
        assert_eq!(s.read(&mut [0]).err().unwrap().kind, TimedOut);

        s.set_timeout(Some(20));
        for i in 0..1001 {
            match s.write(&[0; 128 * 1024]) {
                Ok(()) | Err(IoError { kind: ShortWrite(..), .. }) => {},
                Err(IoError { kind: TimedOut, .. }) => break,
                Err(e) => panic!("{}", e),
           }
           if i == 1000 { panic!("should have filled up?!"); }
        }
        assert_eq!(s.write(&[0]).err().unwrap().kind, TimedOut);

        tx.send(()).unwrap();
        s.set_timeout(None);
        assert_eq!(s.read(&mut [0, 0]), Ok(1));
    }

    #[test]
    fn read_timeouts() {
        let addr = next_test_ip6();
        let mut a = TcpListener::bind(addr).listen().unwrap();
        let (tx, rx) = channel::<()>();
        thread::spawn(move|| {
            let mut s = TcpStream::connect(addr).unwrap();
            rx.recv().unwrap();
            let mut amt = 0;
            while amt < 100 * 128 * 1024 {
                match s.read(&mut [0;128 * 1024]) {
                    Ok(n) => { amt += n; }
                    Err(e) => panic!("{}", e),
                }
            }
            let _ = rx.recv();
        });

        let mut s = a.accept().unwrap();
        s.set_read_timeout(Some(20));
        assert_eq!(s.read(&mut [0]).err().unwrap().kind, TimedOut);
        assert_eq!(s.read(&mut [0]).err().unwrap().kind, TimedOut);

        tx.send(()).unwrap();
        for _ in 0..100 {
            assert!(s.write(&[0;128 * 1024]).is_ok());
        }
    }

    #[test]
    fn write_timeouts() {
        let addr = next_test_ip6();
        let mut a = TcpListener::bind(addr).listen().unwrap();
        let (tx, rx) = channel::<()>();
        thread::spawn(move|| {
            let mut s = TcpStream::connect(addr).unwrap();
            rx.recv().unwrap();
            assert!(s.write(&[0]).is_ok());
            let _ = rx.recv();
        });

        let mut s = a.accept().unwrap();
        s.set_write_timeout(Some(20));
        for i in 0..1001 {
            match s.write(&[0; 128 * 1024]) {
                Ok(()) | Err(IoError { kind: ShortWrite(..), .. }) => {},
                Err(IoError { kind: TimedOut, .. }) => break,
                Err(e) => panic!("{}", e),
           }
           if i == 1000 { panic!("should have filled up?!"); }
        }
        assert_eq!(s.write(&[0]).err().unwrap().kind, TimedOut);

        tx.send(()).unwrap();
        assert!(s.read(&mut [0]).is_ok());
    }

    #[test]
    fn timeout_concurrent_read() {
        let addr = next_test_ip6();
        let mut a = TcpListener::bind(addr).listen().unwrap();
        let (tx, rx) = channel::<()>();
        thread::spawn(move|| {
            let mut s = TcpStream::connect(addr).unwrap();
            rx.recv().unwrap();
            assert_eq!(s.write(&[0]), Ok(()));
            let _ = rx.recv();
        });

        let mut s = a.accept().unwrap();
        let s2 = s.clone();
        let (tx2, rx2) = channel();
        let _t = thread::spawn(move|| {
            let mut s2 = s2;
            assert_eq!(s2.read(&mut [0]), Ok(1));
            tx2.send(()).unwrap();
        });

        s.set_read_timeout(Some(20));
        assert_eq!(s.read(&mut [0]).err().unwrap().kind, TimedOut);
        tx.send(()).unwrap();

        rx2.recv().unwrap();
    }

    #[test]
    fn clone_while_reading() {
        let addr = next_test_ip6();
        let listen = TcpListener::bind(addr);
        let mut accept = listen.listen().unwrap();

        // Enqueue a task to write to a socket
        let (tx, rx) = channel();
        let (txdone, rxdone) = channel();
        let txdone2 = txdone.clone();
        let _t = thread::spawn(move|| {
            let mut tcp = TcpStream::connect(addr).unwrap();
            rx.recv().unwrap();
            tcp.write_u8(0).unwrap();
            txdone2.send(()).unwrap();
        });

        // Spawn off a reading clone
        let tcp = accept.accept().unwrap();
        let tcp2 = tcp.clone();
        let txdone3 = txdone.clone();
        let _t = thread::spawn(move|| {
            let mut tcp2 = tcp2;
            tcp2.read_u8().unwrap();
            txdone3.send(()).unwrap();
        });

        // Try to ensure that the reading clone is indeed reading
        for _ in 0..50 {
            ::thread::yield_now();
        }

        // clone the handle again while it's reading, then let it finish the
        // read.
        let _ = tcp.clone();
        tx.send(()).unwrap();
        rxdone.recv().unwrap();
        rxdone.recv().unwrap();
    }

    #[test]
    fn clone_accept_smoke() {
        let addr = next_test_ip4();
        let l = TcpListener::bind(addr);
        let mut a = l.listen().unwrap();
        let mut a2 = a.clone();

        let _t = thread::spawn(move|| {
            let _ = TcpStream::connect(addr);
        });
        let _t = thread::spawn(move|| {
            let _ = TcpStream::connect(addr);
        });

        assert!(a.accept().is_ok());
        assert!(a2.accept().is_ok());
    }

    #[test]
    fn clone_accept_concurrent() {
        let addr = next_test_ip4();
        let l = TcpListener::bind(addr);
        let a = l.listen().unwrap();
        let a2 = a.clone();

        let (tx, rx) = channel();
        let tx2 = tx.clone();

        let _t = thread::spawn(move|| {
            let mut a = a;
            tx.send(a.accept()).unwrap();
        });
        let _t = thread::spawn(move|| {
            let mut a = a2;
            tx2.send(a.accept()).unwrap();
        });

        let _t = thread::spawn(move|| {
            let _ = TcpStream::connect(addr);
        });
        let _t = thread::spawn(move|| {
            let _ = TcpStream::connect(addr);
        });

        assert!(rx.recv().unwrap().is_ok());
        assert!(rx.recv().unwrap().is_ok());
    }

    #[test]
    fn close_accept_smoke() {
        let addr = next_test_ip4();
        let l = TcpListener::bind(addr);
        let mut a = l.listen().unwrap();

        a.close_accept().unwrap();
        assert_eq!(a.accept().err().unwrap().kind, EndOfFile);
    }

    #[test]
    fn close_accept_concurrent() {
        let addr = next_test_ip4();
        let l = TcpListener::bind(addr);
        let a = l.listen().unwrap();
        let mut a2 = a.clone();

        let (tx, rx) = channel();
        let _t = thread::spawn(move|| {
            let mut a = a;
            tx.send(a.accept()).unwrap();
        });
        a2.close_accept().unwrap();

        assert_eq!(rx.recv().unwrap().err().unwrap().kind, EndOfFile);
    }
}

use ffi;
use CefRc;
use Browser;
use CBool;
use Void;
use Is;
use Interface;

use unsafe_downcast_mut;
use cast_to_interface;
use std::mem::transmute;

use std::ops::{Deref, DerefMut};

pub type Rect = ffi::cef_rect_t;
pub type Point = ffi::cef_point_t;
pub type Size = ffi::cef_size_t;
pub type CursorHandle = *const ::libc::c_void;
pub type DragOperationsMask = ffi::cef_drag_operations_mask_t;

#[repr(C)]
pub struct DragData {
    vtable: ffi::cef_drag_data_t
}

unsafe impl Is<ffi::cef_base_t> for DragData {}
unsafe impl Interface<ffi::cef_drag_data_t> for DragData {}

#[repr(C)]
pub struct ScreenInfo {
    available_rect: Rect,
    depth: i32,
    depth_per_component: i32,
    device_scale_factor: f32,
    is_monochrome: CBool,
    rect: Rect
}

#[test]
fn check_screen_info_size() {
    use std::mem::size_of;
    assert!(size_of::<ScreenInfo>() == size_of::<ffi::cef_screen_info_t>());
}

#[derive(Copy, Clone)]
pub enum PaintElementType {
    View,
    Popup
}

#[derive(Copy, Clone)]
pub enum CursorDirection {
    East,
    North,
    NorthEast,
    NorthWest,
    South,
    SouthEast,
    SouthWest,
    West
}

#[derive(Copy, Clone)]
pub enum CursorBidirection {
    NorthSouth,
    NorthEastSouthWest,
    NorthWestSouthEast
}

pub struct CustomCursorInfo<'a> {
    pub hotspot: Point,
    pub image_scale_factor: f32,
    pub buffer: &'a mut[u8], // size.width * size.height * 4
    pub size: Size,
}
pub enum Cursor<'a> {
    Pointer,
    Cross,
    Hand,
    IBeam,
    Wait,
    Help,
    ResizeDir(CursorDirection),
    ResizeBidir(CursorBidirection),
    ColumnResize,
    RowResize,
    MiddlePanning,
    Panning(CursorDirection),
    Move,
    VerticalText,
    Cell,
    ContextMenu,
    Alias,
    Progress,
    NoDrop,
    Copy,
    None,
    NotAllowed,
    ZoomIn,
    ZoomOut,
    Grab,
    Grabbing,
    Custom(CustomCursorInfo<'a>)
}
#[allow(unused_variables)]
pub trait RenderHandler : 'static {
    fn get_root_screen_rect(&mut self, browser: CefRc<Browser>) -> Option<Rect> { None }
    fn get_view_rect(&mut self, browser: CefRc<Browser>) -> Option<Rect>;
    fn get_screen_point(&mut self, browser: CefRc<Browser>, view_point: (i32, i32)) -> Option<(i32, i32)> { None }
    fn get_screen_info(&mut self, browser: CefRc<Browser>) -> Option<ScreenInfo> { None }
    fn on_popup_show(&mut self, browser: CefRc<Browser>) {}
    fn on_popup_hide(&mut self, browser: CefRc<Browser>) {}
    fn on_popup_size(&mut self, browser: CefRc<Browser>, rect: &Rect) {}
    fn on_paint(&mut self,
                browser: CefRc<Browser>,
                _type: PaintElementType,
                dirty_rects: &[Rect],
                buffer: &[u8], //width * height * 4
                width: i32,
                height: i32);
    fn on_cursor_change(&mut self,
                        browser: CefRc<Browser>,
                        cursor_handle: CursorHandle,
                        cursor: &Cursor) {}
    fn start_dragging(&mut self,
                      browser: CefRc<Browser>,
                      drag_data: CefRc<DragData>,
                      allowed_ops: DragOperationsMask,
                      pos: (i32, i32)) -> bool { false }
    fn update_drag_cursor(&mut self, browser: CefRc<Browser>, operation: DragOperationsMask) {}
    fn on_scroll_offset_changed(&mut self, browser: CefRc<Browser>) {}
}

impl RenderHandler for Void {
    fn get_view_rect(&mut self, _: CefRc<Browser>) -> Option<Rect> {
        unreachable!()
    }
    fn on_paint(&mut self,
                _: CefRc<Browser>,
                _: PaintElementType,
                _: &[Rect],
                _: &[u8], //width * height * 4
                _: i32,
                _: i32) {
        unreachable!()
    }

}

#[repr(C)]
pub struct RenderHandlerWrapper<T : RenderHandler> {
    vtable: ffi::cef_render_handler_t,
    callback: T
}

impl<T : RenderHandler> Deref for RenderHandlerWrapper<T> {
    type Target = T;
    fn deref<'a>(&'a self) -> &'a T {
        &self.callback
    }
}

impl<T : RenderHandler> DerefMut for RenderHandlerWrapper<T> {
    fn deref_mut<'a>(&'a mut self) -> &'a mut T {
        &mut self.callback
    }
}

unsafe impl<T: RenderHandler> Is<ffi::cef_base_t> for RenderHandlerWrapper<T> {}
unsafe impl<T: RenderHandler> Is<ffi::cef_render_handler_t> for RenderHandlerWrapper<T> {}

impl<T : RenderHandler> RenderHandlerWrapper<T> {
    pub fn new(wrapped: T) -> CefRc<RenderHandlerWrapper<T>> {
        #[stdcall_win]
        extern fn get_root_screen_rect<T : RenderHandler>(
            _self: *mut ffi::cef_render_handler_t,
            browser: *mut ffi::cef_browser_t,
            rect: *mut ffi::cef_rect_t) -> ::libc::c_int
        {
            unsafe {
                let this: &mut RenderHandlerWrapper<T> = unsafe_downcast_mut(&mut *_self);
                let browser: CefRc<Browser> = cast_to_interface(browser);
                let rect: &mut ffi::cef_rect_t = transmute(rect);
                match this.callback.get_root_screen_rect(browser) {
                    Some(new_rect) => {
                        *rect = new_rect;
                        1
                    },
                    None => 0
                }
            }
        }
        #[stdcall_win]
        extern fn get_view_rect<T : RenderHandler>(
            _self: *mut ffi::cef_render_handler_t,
            browser: *mut ffi::cef_browser_t,
            rect: *mut ffi::cef_rect_t) -> ::libc::c_int
        {
            unsafe {
                let this: &mut RenderHandlerWrapper<T> = unsafe_downcast_mut(&mut *_self);
                let browser: CefRc<Browser> = cast_to_interface(browser);
                match this.callback.get_view_rect(browser) {
                    Some(new_rect) => {
                        *rect = new_rect;
                        1
                    },
                    None => 0
                }
            }
        }
       #[stdcall_win]
        extern fn get_screen_point<T : RenderHandler>(
            _self: *mut ffi::cef_render_handler_t,
            browser: *mut ffi::cef_browser_t,
            view_x: ::libc::c_int,
            view_y: ::libc::c_int,
            screen_x: *mut ::libc::c_int,
            screen_y: *mut ::libc::c_int) -> ::libc::c_int
        {
            unsafe {
                let this: &mut RenderHandlerWrapper<T> = unsafe_downcast_mut(&mut *_self);
                let browser: CefRc<Browser> = cast_to_interface(browser);
                match this.callback.get_screen_point(browser, (view_x, view_y)) {
                    Some((x, y)) => {
                        *screen_x = x;
                        *screen_y = y;
                        1
                    },
                    None => 0
                }
            }
        }
        #[stdcall_win]
        extern fn get_screen_info<T : RenderHandler>(
            _self: *mut ffi::cef_render_handler_t,
            browser: *mut ffi::cef_browser_t,
            screen_info: *mut ffi::cef_screen_info_t) -> ::libc::c_int
        {
            unsafe {
                let this: &mut RenderHandlerWrapper<T> = unsafe_downcast_mut(&mut *_self);
                let browser: CefRc<Browser> = cast_to_interface(browser);
                match this.callback.get_screen_info(browser) {
                    Some(info) => {
                        *screen_info = transmute(info);
                        1
                    },
                    None => 0
                }
            }
        }
        #[stdcall_win]
        extern fn on_popup_show<T : RenderHandler>(
            _self: *mut ffi::cef_render_handler_t,
            browser: *mut ffi::cef_browser_t,
            show: ::libc::c_int)
        {
            unsafe {
                let this: &mut RenderHandlerWrapper<T> = unsafe_downcast_mut(&mut *_self);
                let browser: CefRc<Browser> = cast_to_interface(browser);
                match show {
                    0 => this.callback.on_popup_hide(browser),
                    _ => this.callback.on_popup_show(browser)
                }
            }
        }
        #[stdcall_win]
        extern fn on_popup_size<T : RenderHandler>(
            _self: *mut ffi::cef_render_handler_t,
            browser: *mut ffi::Struct__cef_browser_t,
            rect: *const ffi::cef_rect_t)
        {
            unsafe {
                let this: &mut RenderHandlerWrapper<T> = unsafe_downcast_mut(&mut *_self);
                let browser: CefRc<Browser> = cast_to_interface(browser);
                this.callback.on_popup_size(browser, &*rect)
            }
        }
        #[stdcall_win]
        extern fn on_paint<T : RenderHandler>(
            _self: *mut ffi::cef_render_handler_t,
            browser: *mut ffi::cef_browser_t,
            _type: ffi::cef_paint_element_type_t,
            dirty_rects_count: ::libc::size_t,
            dirty_rects: *const ffi::cef_rect_t,
            buffer: *const ::libc::c_void,
            width: ::libc::c_int,
            height: ::libc::c_int)
        {
            use std::slice::from_raw_parts;
            unsafe {
                let this: &mut RenderHandlerWrapper<T> = unsafe_downcast_mut(&mut *_self);
                let browser: CefRc<Browser> = cast_to_interface(browser);
                let _type = match _type {
                    ffi::PET_VIEW => PaintElementType::View,
                    ffi::PET_POPUP => PaintElementType::Popup,
                    _ => unreachable!()
                };
                let dirty_rects = from_raw_parts(dirty_rects, dirty_rects_count as usize);
                let buffer = buffer as *const u8;
                let buffer = from_raw_parts(buffer, (width * height * 4) as usize);
                this.callback.on_paint(browser, _type, dirty_rects, buffer, width, height);
            }
