    #[test]
    fn test_from_system_time() {
        use std::time::Duration;

        let epoch = Utc.ymd(1970, 1, 1).and_hms(0, 0, 0);

        // SystemTime -> DateTime<Utc>
        assert_eq!(DateTime::<Utc>::from(UNIX_EPOCH), epoch);
        assert_eq!(DateTime::<Utc>::from(UNIX_EPOCH + Duration::new(999_999_999, 999_999_999)),
                   Utc.ymd(2001, 9, 9).and_hms_nano(1, 46, 39, 999_999_999));
        assert_eq!(DateTime::<Utc>::from(UNIX_EPOCH - Duration::new(999_999_999, 999_999_999)),
                   Utc.ymd(1938, 4, 24).and_hms_nano(22, 13, 20, 1));

        // DateTime<Utc> -> SystemTime
        assert_eq!(SystemTime::from(epoch), UNIX_EPOCH);
        assert_eq!(SystemTime::from(Utc.ymd(2001, 9, 9).and_hms_nano(1, 46, 39, 999_999_999)),
                   UNIX_EPOCH + Duration::new(999_999_999, 999_999_999));
        assert_eq!(SystemTime::from(Utc.ymd(1938, 4, 24).and_hms_nano(22, 13, 20, 1)),
                   UNIX_EPOCH - Duration::new(999_999_999, 999_999_999));

        // DateTime<any tz> -> SystemTime (via `with_timezone`)
        #[cfg(feature="clock")] {
            assert_eq!(SystemTime::from(epoch.with_timezone(&Local)), UNIX_EPOCH);
        }
        assert_eq!(SystemTime::from(epoch.with_timezone(&FixedOffset::east(32400))), UNIX_EPOCH);
        assert_eq!(SystemTime::from(epoch.with_timezone(&FixedOffset::west(28800))), UNIX_EPOCH);
    }

    #[test]
    fn test_datetime_format_alignment() {
        let datetime = Utc.ymd(2007, 01, 02);

        // Item::Literal
        let percent = datetime.format("%%");
        assert_eq!("  %", format!("{:>3}", percent));
        assert_eq!("%  ", format!("{:<3}", percent));
        assert_eq!(" % ", format!("{:^3}", percent));

        // Item::Numeric
        let year = datetime.format("%Y");
        assert_eq!("  2007", format!("{:>6}", year));
        assert_eq!("2007  ", format!("{:<6}", year));
        assert_eq!(" 2007 ", format!("{:^6}", year));

        // Item::Fixed
        let tz = datetime.format("%Z");
        assert_eq!("  UTC", format!("{:>5}", tz));
        assert_eq!("UTC  ", format!("{:<5}", tz));
        assert_eq!(" UTC ", format!("{:^5}", tz));

        // [Item::Numeric, Item::Space, Item::Literal, Item::Space, Item::Numeric]
        let ymd = datetime.format("%Y %B %d");
        let ymd_formatted = "2007 January 02";
        assert_eq!(format!("  {}", ymd_formatted), format!("{:>17}", ymd));
        assert_eq!(format!("{}  ", ymd_formatted), format!("{:<17}", ymd));
        assert_eq!(format!(" {} ", ymd_formatted), format!("{:^17}", ymd));
    }
}

use hashes::{sha256d};
use byte::{BytesExt, LE};
use crate::consensus::Encodable;
use crate::crypto::byte_util::UInt256;
use crate::hashes::Hash;

#[inline]
fn ceil_log2(mut x: i32) -> i32 {
    let mut r = if x & (x - 1) != 0 { 1 } else { 0 };
    loop {
        x >>= 1;
        if x == 0 {
            break;
        }
        r += 1;
    }
    r
}

#[derive(Clone, Debug)]
pub struct MerkleTree<'a> {
    pub tree_element_count: u32,
    pub hashes: &'a [u8],
    pub flags: &'a [u8],
}

impl<'a> MerkleTree<'a> {
    pub fn has_root(&self, desired_merkle_root: UInt256) -> bool {
        if self.tree_element_count == 0 {
            return true;
        }
        if let Some(root) = self.merkle_root() {
            if root == desired_merkle_root {
                return true;
            }
        }
        return false;
    }

    pub fn merkle_root(&self) -> Option<UInt256> {
        let hash_idx = &mut 0;
        let flag_idx = &mut 0;
        self.walk_hash_idx(
            hash_idx,
            flag_idx,
            0,
            |hash, _flag | hash,
            |left, right| {
                let mut buffer: Vec<u8> = Vec::with_capacity(64);
                left.consensus_encode(&mut buffer).unwrap();
                if right.is_none() { left.clone() } else { right.unwrap() }.consensus_encode(&mut buffer).unwrap();
                let hash = sha256d::Hash::hash(&buffer);
                let value = hash.into_inner();
                Some(UInt256(value))
            })
    }

    pub fn walk_hash_idx<
        BL: Fn(UInt256, Option<UInt256>) -> Option<UInt256> + Copy,
        LL: Fn(Option<UInt256>, bool) -> Option<UInt256> + Copy>(
        &self, hash_idx: &mut i32, flag_idx: &mut i32,
        depth: i32, leaf: LL, branch: BL) -> Option<UInt256> {
        let flags_length = self.flags.len() as i32;
        let hashes_length = self.hashes.len() as i32;
        if *flag_idx / 8 >= flags_length || (*hash_idx + 1) * 32 > hashes_length {
            return leaf(None, false);
        }
        let flag = self.flags[(*flag_idx / 8) as usize] & (1 << (*flag_idx % 8)) != 0;
        *flag_idx += 1;
        if !flag || depth == ceil_log2(self.tree_element_count as i32) {
            let off = &mut (32*(*hash_idx) as usize);
            let hash = match self.hashes.read_with::<UInt256>(off, LE) {
                Ok(data) => data,
                Err(_err) => { return None; }
            };
            *hash_idx += 1;
            return leaf(Some(hash), flag);
        }
        let left = self.walk_hash_idx(hash_idx, flag_idx, depth + 1, leaf, branch);
        let right = self.walk_hash_idx(hash_idx, flag_idx, depth + 1, leaf, branch);
        branch(left.unwrap(), right)
    }
}

pub struct HuffmanEncoder<W: Write> {
    state: State,
    output: BitWriter<W>,
    char_to_code: HashMap<Char, Code>,
    char_to_weight: HashMap<Char, u64>,
    max_char_length: usize,
}

impl<W: Write> HuffmanEncoder<W> {
    pub fn new(output: W, max_char_length: usize) -> Self {
        HuffmanEncoder {
            state: State::Initial,
            output: BitWriter::new(output),
            char_to_code: HashMap::new(),
            char_to_weight: HashMap::new(),
            max_char_length: max_char_length,
        }
    }

    pub fn analyze<R>(&mut self, input: R) -> Result<u64>
        where R: Read
    {
        assert_eq!(State::Initial, self.state);

        let mut input = BitReader::new(input);
        let mut bytes_read = 0;

        while let Some(ch) = read_char(&mut input, self.max_char_length) {
            self.char_to_weight.entry(ch.clone()).or_insert(0);
            self.char_to_weight.get_mut(&ch).map(|mut w| *w += 1);
            bytes_read += ch.len() as u64;
        }

        Ok(bytes_read * 8)
    }

    pub fn analyze_finish(&mut self) -> Result<()> {
        assert_eq!(State::Initial, self.state);
        self.state = State::Analyzed;

        let leaves = self.compute_leaves();
        let tree = self.build_tree(leaves);
        self.build_dictionary(tree);
        self.write_header()
    }

    pub fn compress<R>(&mut self, input: R) -> Result<u64>
        where R: Read
    {
        assert_eq!(State::Analyzed, self.state);

        let mut input = BitReader::new(input);
        let mut bits_written = 0;

        while let Some(ch) = read_char(&mut input, self.max_char_length) {
            let code = self.char_to_code.get(&ch).unwrap();

            assert!(code.length <= max_code_length());
            for i in 0..code.length {
                let shifted_one = 1 << i;
                let data = (code.data & shifted_one) > 0;
                try!(self.output.write_bit(data));
                bits_written += 1;
            }
        }

        Ok(bits_written)
    }

    pub fn compress_finish(&mut self) -> Result<()> {
        assert_eq!(State::Analyzed, self.state);
        self.state = State::Compressed;

        self.output.flush()
    }

    pub fn position(&self) -> u64 {
        self.output.position()
    }

    pub fn get_output_ref(&self) -> &W {
        self.output.get_ref()
    }

    pub fn get_output_mut(&mut self) -> &mut W {
        self.output.get_mut()
    }

    pub fn get_writer_mut(&mut self) -> &mut BitWriter<W> {
        &mut self.output
    }

    fn compute_leaves(&mut self) -> Vec<Tree> {
        let mut leaves: Vec<Tree> = Vec::with_capacity(self.char_to_weight.len());

        for (ref ch, &weight) in &self.char_to_weight {
            let data: NodeData = NodeData {
                chars: hashset!{(*ch).clone()},
                weight: weight,
            };
            leaves.push(BinaryTree::new_leaf(data));
        }

        leaves.sort_by_key(|tree| tree.data().unwrap().weight);
        leaves.reverse();
        leaves
    }

    fn build_tree(&self, leaves: Vec<Tree>) -> Tree {
        let mut level = VecDeque::from(leaves);

        if level.is_empty() {
            return BinaryTree::new_empty();
        }

        let new_level = |level: &VecDeque<Tree>| -> VecDeque<Tree> {
            let length = level.len() / 2 + 1;
            VecDeque::with_capacity(length)
        };

        let mut next_level = new_level(&level);

        loop {
            let found_root = next_level.is_empty() && level.len() == 1;
            if found_root {
                break;
            } else {
                self.build_next_level(&level, &mut next_level);
                level = next_level;
                next_level = new_level(&level);
            }
        }

        level[0].clone()
    }

    fn build_next_level(&self, level: &VecDeque<Tree>, next_level: &mut VecDeque<Tree>) {
        let n = level.len();
        let mut level_length = n;

        while level_length > 0 {
            let i = level_length - 1;
            let last_node_in_level = i == 0;
            let new_parent_has_same_weight = match next_level.front() {
                Some(tree) => tree.data().unwrap().weight <= level[i].data().unwrap().weight,
                None => false,
            };
            if last_node_in_level || new_parent_has_same_weight {
                let head = next_level.pop_front().unwrap();
                let parent = self.new_parent(&level[i], &head);
                next_level.push_front(parent);
                if last_node_in_level {
                    break;
                }
                level_length -= 1;
            } else {
                let parent = self.new_parent(&level[i], &level[i - 1]);
                next_level.push_front(parent);
                level_length -= 2;
            }
        }
    }

    fn new_parent(&self, left: &Tree, right: &Tree) -> Tree {
        let left_chars = &left.data().unwrap().chars;
        let right_chars = &right.data().unwrap().chars;

        let chars = left_chars.union(right_chars).cloned().collect::<HashSet<Char>>();
        let weight = left.data().unwrap().weight + right.data().unwrap().weight;

        let data = NodeData {
            chars: chars,
            weight: weight,
        };

        Tree::new(data, left, right)
    }

    fn build_dictionary(&mut self, tree: Tree) {
        if let Some(data) = tree.data() {
            for ref ch in &data.chars {
                let code = self.compute_code(ch, &tree);
                let ch: Char = (*ch).clone();
                self.char_to_code.insert(ch, code);
            }
        }

        assert!(self.char_to_code.len() <= self.max_possible_chars());
    }

    fn compute_code(&self, ch: CharSlice, tree: &Tree) -> Code {
        let mut tree = tree.clone();
        let mut code = BitSet::new();
        let mut length: CodeLength = 0;

        loop {
            if tree.left_data().is_some() && tree.left_data().unwrap().chars.contains(ch) {
                tree = tree.left();
            } else if tree.right_data().is_some() && tree.right_data().unwrap().chars.contains(ch) {
                code.insert(length as usize);
                tree = tree.right();
            } else {
                break;
            }
            length += 1;
        }

        assert!(tree.is_leaf());

        if length == 0 {
            length = 1; // FIXME
        }

        assert!(length > 0);
        assert!(length <= max_code_length());

        let data = code.as_slice()[0] as CodeData;

        Code {
            length: length,
            data: data,
        }
    }

    fn write_header(&mut self) -> Result<()> {
        let dict_length = self.char_to_code.len() as DictLength;
        try!(self.output.write_u16(dict_length));

        for (ref ch, code) in &self.char_to_code {
            let data_with_marker: CodeData = Self::pack_data(&code);
            assert!(code.data != data_with_marker);
            try!(self.output.write_u16(data_with_marker));
            try!(self.output.write_u8(ch.len() as u8));
            for i in ch.iter() {
                try!(self.output.write_u8(*i));
            }
        }

        Ok(())
    }

    fn pack_data(code: &Code) -> CodeData {
        let shifted_one = 1 << code.length;
        let result = code.data | shifted_one;
        result
    }

    fn max_possible_chars(&self) -> usize {
        1 << (self.max_char_length * 8)
    }
}

impl<W: Write> Drop for HuffmanEncoder<W> {
    fn drop(&mut self) {
        if self.state == State::Analyzed {
            let _ = self.compress_finish();
        }
    }
}

use std::sync::{Arc, Mutex};

use super::Canvas;
use super::glwrap::{GlTexture, TexFilters};



///////////////////////////////////////////////////////////////////////////////////////////////////// Texture

#[derive(Clone, Debug)]
pub enum Texture {
	None,
	Static (StaticTexture),
	Dynamic (DynTexture),
	Sub (SubTexture),
}


impl Texture {

	pub fn new_static(cnv: &Canvas, filters: TexFilters) -> Texture {
		// Create a new OpenGl texture and upload the canvas contents to it
		let gl_tex = GlTexture::new(filters);
		gl_tex.upload_canvas(cnv);

		Texture::Static (StaticTexture {
			gl_tex,
			w: cnv.width(),
			h: cnv.height(),
		})
	}

	pub fn new_static_from_file<P>(path: P, filters: TexFilters) -> Result<Texture, String>
	where
		P: AsRef<std::path::Path>
	{
		// Load a file and create a static texture
		let cnv = Canvas::from_file(path)?;
		Ok(Texture::new_static(&cnv, filters))
	}

	pub fn new_dynamic(w: u32, h: u32, filters: TexFilters) -> Texture {
		// Create an empty canvas
		let cnv = Arc::new(Mutex::new(Canvas::new(w, h, None)));

		// Create a new dynamic texture
		Texture::new_dynamic_from_canvas(&cnv, filters)
	}

	pub fn new_dynamic_from_canvas(cnv: &Arc<Mutex<Canvas>>, filters: TexFilters) -> Texture {
		// Create a GlTexture
		let gl_tex = GlTexture::new(filters);

		// Create a new dynamic texture
		Texture::Dynamic (DynTexture::new(gl_tex, Arc::clone(cnv)))
	}

	pub fn new_dynamic_from_file<P>(path: P, filters: TexFilters) -> Result<Texture, String>
	where
		P: AsRef<std::path::Path>
	{
		// Load a canvas from a file
		let cnv = Arc::new(Mutex::new(Canvas::from_file(path)?));

		// Create a new dynamic texture
		Ok(Texture::new_dynamic_from_canvas(&cnv, filters))
	}

	pub fn new_sub(parent: &Arc<Texture>, x: u32, y: u32, w: u32, h: u32) -> Texture {
		// Create a sub-texture
		Texture::Sub(SubTexture::new(parent, x, y, w, h))
	}

	pub fn get_underlying(&self) -> &GlTexture {
		// Get the underlying Gl texture
		match self {
			Texture::None => unimplemented!(),
			Texture::Static (tex) => &tex.gl_tex,
			Texture::Dynamic (tex) => &tex.gl_tex,
			Texture::Sub (tex) => tex.parent.get_underlying(),
		}
	}

	pub fn bind(&self) {
		// Bind the underlying Gl texture
		self.get_underlying().bind();

		// Some texture types (i.e. Dynamic) require updating on bind
		match self {
			Texture::Dynamic (tex) => tex.bound(),
			_ => {},
		}
	}

	pub fn get_uv(&self) -> (f32, f32, f32, f32) {
		// Get the UV bounds of the texture
		use Texture::*;
		match self {
			Texture::None => unimplemented!(),
			Static (_) |
			Dynamic (_) => (0.0, 0.0, 1.0, 1.0),
			Sub (sub) => sub.get_uv(),
		}
	}

	pub fn size(&self) -> (u32, u32) {
		// Get the texture size
		use Texture::*;
		match self {
			Texture::None => unimplemented!(),
			Static (tex) => (tex.w, tex.h),
			Dynamic (tex) => tex.cnv.lock().unwrap().size(),
			Sub (tex) => (tex.w, tex.h),
		}
	}

	pub fn get_canvas(&self) -> Arc<Mutex<Canvas>> {
		// Get a reference to the underlying Canvas, if applicable
		match self {
			Texture::Dynamic (dt) => dt.get_canvas(),

			_ => unimplemented!(),
		}
	}
}


///////////////////////////////////////////////////////////////////////////////////////////////////// StaticTexture

#[derive(Clone, Debug)]
pub struct StaticTexture {
	gl_tex: GlTexture,
	w: u32,
	h: u32,
}

impl StaticTexture {
}

///////////////////////////////////////////////////////////////////////////////////////////////////// DynTexture

#[derive(Clone, Debug)]
pub struct DynTexture {
	cnv: Arc<Mutex<Canvas>>,
	gl_tex: GlTexture,
}

impl DynTexture {
	fn new(gl_tex: GlTexture, cnv: Arc<Mutex<Canvas>>) -> DynTexture {
		DynTexture {
			gl_tex,
			cnv,
		}
	}

	pub fn get_canvas(&self) -> Arc<Mutex<Canvas>> {
		Arc::clone(&self.cnv)
	}

	fn bound(&self) {
		// The texture was just bound
		// Update it if the canvas is dirty
		let mut cnv = self.cnv.lock().unwrap();
		if cnv.dirty() {
			// Upload
			self.gl_tex.upload_canvas(&cnv);
			cnv.set_dirty(false);
		}
	}
}


///////////////////////////////////////////////////////////////////////////////////////////////////// SubTexture

#[derive(Clone, Debug)]
pub struct SubTexture {
	parent: Arc<Texture>,
	x: u32,
	y: u32,
	w: u32,
	h: u32,
}

impl SubTexture {
	fn new(parent: &Arc<Texture>, x: u32, y: u32, w: u32, h: u32) -> SubTexture {
		SubTexture {
			parent: Arc::clone(parent),
			x,
			y,
			w,
			h,
		}
	}

	fn get_uv(&self) -> (f32, f32, f32, f32) {
		// Get our parent size and UV
		let (pw, ph) = self.parent.size();
		let (pu1, pv1, pu2, pv2) = self.parent.get_uv();

		// Calc parent's du and dv
		let pdu = (pu2-pu1)/pw as f32;
		let pdv = (pv2-pv1)/ph as f32;

		// Calc our own
		let u1 = pu1 + self.x as f32 * pdu;
		let v1 = pv1 + self.y as f32 * pdv;
		let u2 = u1 + self.w as f32 * pdu;
		let v2 = v1 + self.h as f32 * pdv;

		(u1, v1, u2, v2)
	}
}

