impl Address{
    pub async fn load(&mut self,context: &dyn ContextTrait, wallet_id:&str,chain_type: &str)->Result<(),WalletError>{
        let wallet_rb = context.db().wallets_db();
        let wrapper = wallet_rb.new_wrapper()
