/// Define the appearance of each token.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum TokenStyle {
    // TODO: add TopArcs, SideSquares, TopSquares, SideLines, TopLines, etc.
    // See https://boardgamegeek.com/image/5033873/18611867 for ideas.
    SideArcs {
        bg: Colour,
        fg: Colour,
        text: Colour,
    },
    TopArcs {
        bg: Colour,
        fg: Colour,
        text: Colour,
    },
    TopSquares {
        bg: Colour,
        fg: Colour,
        text: Colour,
    },
    TopLines {
        bg: Colour,
        fg: Colour,
        text: Colour,
    },
    TopTriangles {
        bg: Colour,
        fg: Colour,
        text: Colour,
    },
    TripleTriangles {
        bg: Colour,
        fg: Colour,
        text: Colour,
    },
    TribandV {
        sides: Colour,
        middle: Colour,
        text: Colour,
    },
    TribandH {
        sides: Colour,
        middle: Colour,
        text: Colour,
    },
    TricolourV {
        left: Colour,
        middle: Colour,
        right: Colour,
        text: Colour,
    },
    TricolourH {
        top: Colour,
        middle: Colour,
        bottom: Colour,
        text: Colour,
    },
}

impl TokenStyle {
    fn draw_background(&self, hex: &Hex, ctx: &Context) {
        use TokenStyle::*;

        let radius = hex.theme.token_space_radius.absolute(hex);
        let rmax = 1.1 * radius;
        let dx = 0.45 * radius;

        match self {
            SideArcs { fg, bg, .. } => {
                bg.apply_colour(ctx);
                ctx.fill_preserve().unwrap();

                ctx.clip_preserve();
                ctx.new_path();
                ctx.arc(-1.5 * radius, 0.0, 1.0 * radius, 0.0, 2.0 * PI);
                ctx.arc(1.5 * radius, 0.0, 1.0 * radius, 0.0, 2.0 * PI);

                fg.apply_colour(ctx);
                ctx.fill().unwrap();
            }
            TopArcs { fg, bg, .. } => {
                bg.apply_colour(ctx);
                ctx.fill_preserve().unwrap();

                ctx.clip_preserve();
                ctx.new_path();
                ctx.arc(0.0, -1.5 * radius, 1.0 * radius, 0.0, 2.0 * PI);
                ctx.arc(0.0, 1.5 * radius, 1.0 * radius, 0.0, 2.0 * PI);

                fg.apply_colour(ctx);
                ctx.fill().unwrap();
            }
            TopSquares { fg, bg, .. } => {
                bg.apply_colour(ctx);
                ctx.fill_preserve().unwrap();
                ctx.clip_preserve();
                ctx.new_path();
                ctx.move_to(-0.4 * radius, -dx);
                ctx.line_to(0.4 * radius, -dx);
                ctx.line_to(0.4 * radius, -rmax);
                ctx.line_to(-0.4 * radius, -rmax);
                fg.apply_colour(ctx);
                ctx.fill().unwrap();
                ctx.new_path();
                ctx.move_to(-0.4 * radius, dx);
                ctx.line_to(0.4 * radius, dx);
                ctx.line_to(0.4 * radius, rmax);
                ctx.line_to(-0.4 * radius, rmax);
                fg.apply_colour(ctx);
                ctx.fill().unwrap();
            }
            TopLines { fg, bg, .. } => {
                bg.apply_colour(ctx);
                ctx.fill_preserve().unwrap();
                ctx.clip_preserve();
                ctx.new_path();
                ctx.move_to(-0.5 * radius, -dx);
                ctx.line_to(-0.3 * radius, -dx);
                ctx.line_to(-0.3 * radius, -rmax);
                ctx.line_to(-0.5 * radius, -rmax);
                ctx.move_to(-0.1 * radius, -dx);
                ctx.line_to(0.1 * radius, -dx);
                ctx.line_to(0.1 * radius, -rmax);
                ctx.line_to(-0.1 * radius, -rmax);
                ctx.move_to(0.5 * radius, -dx);
                ctx.line_to(0.3 * radius, -dx);
                ctx.line_to(0.3 * radius, -rmax);
                ctx.line_to(0.5 * radius, -rmax);
                fg.apply_colour(ctx);
                ctx.fill().unwrap();
                ctx.new_path();
                ctx.move_to(-0.5 * radius, dx);
                ctx.line_to(-0.3 * radius, dx);
                ctx.line_to(-0.3 * radius, rmax);
                ctx.line_to(-0.5 * radius, rmax);
                ctx.move_to(-0.1 * radius, dx);
                ctx.line_to(0.1 * radius, dx);
                ctx.line_to(0.1 * radius, rmax);
                ctx.line_to(-0.1 * radius, rmax);
                ctx.move_to(0.5 * radius, dx);
                ctx.line_to(0.3 * radius, dx);
                ctx.line_to(0.3 * radius, rmax);
                ctx.line_to(0.5 * radius, rmax);
                fg.apply_colour(ctx);
                ctx.fill().unwrap();
            }
            TopTriangles { fg, bg, .. } => {
                bg.apply_colour(ctx);
                ctx.fill_preserve().unwrap();
                ctx.clip_preserve();
                ctx.new_path();
                ctx.move_to(-dx, -rmax);
                ctx.line_to(0.0, -dx);
                ctx.line_to(dx, -rmax);
                fg.apply_colour(ctx);
                ctx.fill().unwrap();
                ctx.new_path();
                ctx.move_to(-dx, rmax);
                ctx.line_to(0.0, dx);
                ctx.line_to(dx, rmax);
                fg.apply_colour(ctx);
                ctx.fill().unwrap();
            }
            TripleTriangles { fg, bg, .. } => {
                bg.apply_colour(ctx);
                ctx.fill_preserve().unwrap();
                ctx.clip_preserve();
                ctx.new_path();
                ctx.move_to(-1.5 * radius, -rmax);
                ctx.line_to(-0.3 * radius, -dx);
                ctx.line_to(-0.3 * radius, -rmax);
                ctx.line_to(0.0, -0.5 * radius);
                ctx.line_to(0.3 * radius, -rmax);
                ctx.line_to(0.3 * radius, -dx);
                ctx.line_to(1.5 * radius, -rmax);
                fg.apply_colour(ctx);
                ctx.fill().unwrap();
                ctx.new_path();
                ctx.move_to(-1.5 * radius, rmax);
                ctx.line_to(-0.3 * radius, dx);
                ctx.line_to(-0.3 * radius, rmax);
                ctx.line_to(0.0, 0.5 * radius);
                ctx.line_to(0.3 * radius, rmax);
                ctx.line_to(0.3 * radius, dx);
                ctx.line_to(1.5 * radius, rmax);
                fg.apply_colour(ctx);
                ctx.fill().unwrap();
            }
            TribandV { sides, middle, .. } => {
                sides.apply_colour(ctx);
                ctx.fill_preserve().unwrap();
                ctx.clip_preserve();
                ctx.new_path();
                ctx.move_to(-dx, rmax);
                ctx.line_to(-dx, -rmax);
                ctx.line_to(dx, -rmax);
                ctx.line_to(dx, rmax);
                ctx.line_to(-dx, rmax);
                middle.apply_colour(ctx);
                ctx.fill().unwrap();
            }
            TribandH { sides, middle, .. } => {
                sides.apply_colour(ctx);
                ctx.fill_preserve().unwrap();
                ctx.clip_preserve();
                ctx.new_path();
                ctx.move_to(rmax, -dx);
                ctx.line_to(-rmax, -dx);
                ctx.line_to(-rmax, dx);
                ctx.line_to(rmax, dx);
                ctx.line_to(rmax, -dx);
                middle.apply_colour(ctx);
                ctx.fill().unwrap();
            }
            TricolourV {
                left,
                middle,
                right,
                ..
            } => {
                // Fill the entire region with the middle colour.
                middle.apply_colour(ctx);
                ctx.fill_preserve().unwrap();
                ctx.clip_preserve();
                // Define the left region and fill with the left colour.
                ctx.new_path();
                ctx.move_to(-rmax, -rmax);
                ctx.line_to(-rmax, rmax);
                ctx.line_to(-dx, rmax);
                ctx.line_to(-dx, -rmax);
                left.apply_colour(ctx);
                ctx.fill().unwrap();
                // Define the right region and fill with the right colour.
                ctx.new_path();
                ctx.move_to(rmax, -rmax);
                ctx.line_to(rmax, rmax);
                ctx.line_to(dx, rmax);
                ctx.line_to(dx, -rmax);
                right.apply_colour(ctx);
                ctx.fill().unwrap();
            }
            TricolourH {
                top,
                middle,
                bottom,
                ..
            } => {
                // Fill the entire region with the middle colour.
                middle.apply_colour(ctx);
                ctx.fill_preserve().unwrap();
                ctx.clip_preserve();
                // Define the top region and fill with the top colour.
                ctx.new_path();
                ctx.move_to(-rmax, -dx);
                ctx.line_to(-rmax, -rmax);
                ctx.line_to(rmax, -rmax);
                ctx.line_to(rmax, -dx);
                top.apply_colour(ctx);
                ctx.fill().unwrap();
                // Define the bottom region and fill with the bottom colour.
                ctx.new_path();
                ctx.move_to(-rmax, dx);
                ctx.line_to(-rmax, rmax);
                ctx.line_to(rmax, rmax);
                ctx.line_to(rmax, dx);
                bottom.apply_colour(ctx);
                ctx.fill().unwrap();
            }
        }
    }

    pub fn text_colour(&self) -> &Colour {
        use TokenStyle::*;

        match self {
            SideArcs { text, .. } => text,
            TopArcs { text, .. } => text,
            TopSquares { text, .. } => text,
            TopLines { text, .. } => text,
            TopTriangles { text, .. } => text,
            TripleTriangles { text, .. } => text,
            TribandV { text, .. } => text,
            TribandH { text, .. } => text,
            TricolourV { text, .. } => text,
            TricolourH { text, .. } => text,
        }
    }
}

impl Token {
    pub fn new(style: TokenStyle) -> Self {
        Self {
            style,
            x_pcnt: 50,
            y_pcnt: 50,
        }
    }

    pub fn shift_text(mut self, x_pcnt: usize, y_pcnt: usize) -> Self {
        self.x_pcnt = x_pcnt;
        self.y_pcnt = y_pcnt;
        self
    }

    fn draw_text(&self, hex: &Hex, ctx: &Context, text: &str) {
        // Draw the token text using the appropriate theme settings.
        let mut labeller = hex.theme.token_label.labeller(ctx, hex);

        // Ensure the text is centred and has the desired colour.
        labeller.halign(n18hex::theme::AlignH::Centre);
        labeller.valign(n18hex::theme::AlignV::Middle);
        labeller.colour(*self.style.text_colour());

        // Identify the location of the text centre, noting that the current
        // point is the token centre.
        let (x, y) = ctx.current_point().unwrap();
        let radius = hex.theme.token_space_radius.absolute(hex);
        let dx = radius * ((self.x_pcnt as f64 - 50.0) / 50.0);
        let dy = radius * ((self.y_pcnt as f64 - 50.0) / 50.0);
        let text_centre = n18hex::Coord::from((x + dx, y + dy));

        labeller.draw(text, text_centre);
    }

    /// Draws the token so that it fills the current path.
    ///
    /// Define the token boundary before calling this function.
    pub fn draw(&self, hex: &Hex, ctx: &Context, text: &str, rotn: f64) {
        // Locate the centre of the token.
        let (x0, y0, x1, y1) = ctx.fill_extents().unwrap();
        let x = 0.5 * (x0 + x1);
        let y = 0.5 * (y0 + y1);

        let m = ctx.matrix();
        ctx.save().unwrap();

        // NOTE: move to the token centre and apply the inverse rotation.
        ctx.translate(x, y);
        ctx.rotate(-rotn);

        let stroke_path = ctx.copy_path().unwrap();
        self.style.draw_background(hex, ctx);
        self.draw_text(hex, ctx, text);

        // Redraw the outer black circle.
        ctx.new_path();
        ctx.append_path(&stroke_path);
        hex.theme.token_space_inner.apply_line_and_stroke(ctx, hex);
        ctx.stroke_preserve().unwrap();

        ctx.restore().unwrap();
        ctx.set_matrix(m);
    }
}

use nu_engine::{eval_block, CallExt};
use nu_protocol::ast::Call;
use nu_protocol::engine::{CaptureBlock, Command, EngineState, Stack};
use nu_protocol::{
    Category, Example, IntoInterruptiblePipelineData, PipelineData, Signature, Span, SyntaxShape,
    Value,
};

#[derive(Clone)]
pub struct Each;

impl Command for Each {
    fn name(&self) -> &str {
        "each"
    }

    fn usage(&self) -> &str {
        "Run a block on each element of input"
    }

    fn signature(&self) -> nu_protocol::Signature {
        Signature::build("each")
            .required(
                "block",
                SyntaxShape::Block(Some(vec![SyntaxShape::Any])),
                "the block to run",
            )
            .switch("keep-empty", "keep empty result cells", Some('k'))
            .switch("numbered", "iterate with an index", Some('n'))
            .category(Category::Filters)
    }

    fn examples(&self) -> Vec<Example> {
        let stream_test_1 = vec![
            Value::Int {
                val: 2,
                span: Span::test_data(),
            },
            Value::Int {
                val: 4,
                span: Span::test_data(),
            },
            Value::Int {
                val: 6,
                span: Span::test_data(),
            },
        ];

        let stream_test_2 = vec![
            Value::Nothing {
                span: Span::test_data(),
            },
            Value::String {
                val: "found 2!".to_string(),
                span: Span::test_data(),
            },
            Value::Nothing {
                span: Span::test_data(),
            },
        ];

        vec![
            Example {
                example: "[1 2 3] | each { |it| 2 * $it }",
                description: "Multiplies elements in list",
                result: Some(Value::List {
                    vals: stream_test_1,
                    span: Span::test_data(),
                }),
            },
            Example {
                example: r#"[1 2 3] | each { |it| if $it == 2 { echo "found 2!"} }"#,
                description: "Iterate over each element, keeping only values that succeed",
                result: Some(Value::List {
                    vals: vec![Value::String {
                        val: "found 2!".to_string(),
                        span: Span::test_data(),
                    }],
                    span: Span::test_data(),
                }),
            },
            Example {
                example: r#"[1 2 3] | each --keep-empty { |it| if $it == 2 { echo "found 2!"} }"#,
                description: "Iterate over each element, keeping all results",
                result: Some(Value::List {
                    vals: stream_test_2,
                    span: Span::test_data(),
                }),
            },
        ]
    }

    fn run(
        &self,
        engine_state: &EngineState,
        stack: &mut Stack,
        call: &Call,
        input: PipelineData,
    ) -> Result<nu_protocol::PipelineData, nu_protocol::ShellError> {
        let capture_block: CaptureBlock = call.req(engine_state, stack, 0)?;

        let numbered = call.has_flag("numbered");
        let keep_empty = call.has_flag("keep-empty");

        let ctrlc = engine_state.ctrlc.clone();
        let outer_ctrlc = engine_state.ctrlc.clone();
        let engine_state = engine_state.clone();
        let block = engine_state.get_block(capture_block.block_id).clone();
        let mut stack = stack.captures_to_stack(&capture_block.captures);
        let orig_env_vars = stack.env_vars.clone();
        let orig_env_hidden = stack.env_hidden.clone();
        let span = call.head;
        let redirect_stdout = call.redirect_stdout;
        let redirect_stderr = call.redirect_stderr;

        match input {
            PipelineData::Value(Value::Range { .. }, ..)
            | PipelineData::Value(Value::List { .. }, ..)
            | PipelineData::ListStream { .. } => Ok(input
                .into_iter()
                .enumerate()
                .map(move |(idx, x)| {
                    stack.with_env(&orig_env_vars, &orig_env_hidden);

                    if let Some(var) = block.signature.get_positional(0) {
                        if let Some(var_id) = &var.var_id {
                            if numbered {
                                stack.add_var(
                                    *var_id,
                                    Value::Record {
                                        cols: vec!["index".into(), "item".into()],
                                        vals: vec![
                                            Value::Int {
                                                val: idx as i64,
                                                span,
                                            },
                                            x,
                                        ],
                                        span,
                                    },
                                );
                            } else {
                                stack.add_var(*var_id, x);
                            }
                        }
                    }

                    match eval_block(
                        &engine_state,
                        &mut stack,
                        &block,
                        PipelineData::new(span),
                        redirect_stdout,
                        redirect_stderr,
                    ) {
                        Ok(v) => v.into_value(span),
                        Err(error) => Value::Error { error },
                    }
                })
                .into_pipeline_data(ctrlc)),
            PipelineData::RawStream(stream, ..) => Ok(stream
                .into_iter()
                .enumerate()
                .map(move |(idx, x)| {
                    stack.with_env(&orig_env_vars, &orig_env_hidden);

                    let x = match x {
                        Ok(x) => x,
                        Err(err) => return Value::Error { error: err },
                    };

                    if let Some(var) = block.signature.get_positional(0) {
                        if let Some(var_id) = &var.var_id {
                            if numbered {
                                stack.add_var(
                                    *var_id,
                                    Value::Record {
                                        cols: vec!["index".into(), "item".into()],
                                        vals: vec![
                                            Value::Int {
                                                val: idx as i64,
                                                span,
                                            },
                                            x,
                                        ],
                                        span,
                                    },
                                );
                            } else {
                                stack.add_var(*var_id, x);
                            }
                        }
                    }

                    match eval_block(
                        &engine_state,
                        &mut stack,
                        &block,
                        PipelineData::new(span),
                        redirect_stdout,
                        redirect_stderr,
                    ) {
                        Ok(v) => v.into_value(span),
                        Err(error) => Value::Error { error },
                    }
                })
                .into_pipeline_data(ctrlc)),
            PipelineData::Value(x, ..) => {
                if let Some(var) = block.signature.get_positional(0) {
                    if let Some(var_id) = &var.var_id {
                        stack.add_var(*var_id, x);
                    }
                }

                eval_block(
                    &engine_state,
                    &mut stack,
                    &block,
                    PipelineData::new(span),
                    redirect_stdout,
                    redirect_stderr,
                )
            }
        }
        .and_then(|x| {
            x.filter(
                move |x| if !keep_empty { !x.is_nothing() } else { true },
                outer_ctrlc,
            )
        })
    }
}

