use arena_deserializer::serde::Deserialize;
use typing_defs_rust::typing_defs_core::Ty;

pub fn into_types<'a>(
    arena: &'a bumpalo::Bump,
    chunks: impl Iterator<Item = Vec<u8>>,
) -> impl Iterator<Item = Ty<'a>> {
    let op = bincode::config::Options::with_native_endian(bincode::options());
    chunks.map(move |bs| {
        let mut de = bincode::de::Deserializer::from_slice(&bs, op);
        to_type(arena, &bs, &mut de)
    })
}

fn to_type<'a, 'de>(
    arena: &'a bumpalo::Bump,
    bs: &[u8],
    de: impl serde::Deserializer<'de>,
) -> Ty<'a> {
    let de = arena_deserializer::ArenaDeserializer::new(arena, de);
    let ty = Ty::deserialize(de);
    ty.unwrap_or_else(|_| panic!("cannot deserialize Ty from: {:?}", bs))
}

#[cfg(test)]
mod tests {
    use super::*;

    use serde_json::{json, value::Value as Json};

    fn roundtrip(js: &[Json]) -> Vec<Json> {
        trait JsonRoundtrip: AsMut<Vec<Json>> {
            fn on_type(&mut self, ty: &Ty<'_>) {
                let j = serde_json::to_value(ty).unwrap_or_else(|_| json!(""));
                self.as_mut().push(j);
            }
        }

        impl JsonRoundtrip for Vec<Json> {}

        let mut act: Vec<Json> = Vec::new();
        let arena = bumpalo::Bump::new();
        let chunks = js
            .iter()
            .map(|j| serde_json::to_string(j).unwrap().into_bytes());
        for chunk in chunks {
            let mut de = serde_json::Deserializer::from_slice(&chunk);
            let ty = to_type(&arena, &chunk, &mut de);
            act.on_type(&ty)
        }
        act
    }

    #[test]
    fn de_ser_single_tprim() {
        let js = vec![json!([
          {"Rwitness": {
            "Tiny": {
              "file": "tmp|dir/file.php",
              "span": 123,
            },
          }},
          {"Tprim"
          : "Tnull"},
        ])];
        assert_eq!(roundtrip(&js), js);
    }

    #[test]
    fn de_ser_single_function_hint() {
        let (span1, span2, span3) = (347446144140693i64, 347446144141315i64, 347446144141700i64);
        let js = vec![
            // function higher_order((function(int): void) $_): void {}
            json!([
              {"Rhint":{"Tiny":{"file":"|f2.php","span": span1}}},
              {"Tfun": {
                "flags": 0,
                "ifc_decl": {"FDPolicied":"PUBLIC"},
                "implicit_params": {
                  "capability": {
                    "CapDefaults": {"Tiny":{"file":"|f2.php","span": span1}}
                  }
                },
                "params": [{
                  "flags":0,
                  "name":null,
                  "pos":{"Tiny":{"file":"|f2.php","span": span2}},
                  "type_": {
                    "enforced":"Unenforced",
                    "type_":[{"Rhint":{"Tiny":{"file":"|f2.php","span": span2}}},{"Tprim":"Tint"}]
                  }
                }],
                "ret": {
                  "enforced":"Unenforced",
                  "type_": [{"Rhint":{"Tiny":{"file":"|f2.php","span": span3}}},{"Tprim":"Tvoid"}]
                },
                "tparams": [],
                "where_constraints":[]}
              },
            ]),
        ];
        assert_eq!(roundtrip(&js), js);
    }

    #[test]
    fn de_ser_const_vec_arraykey_eq_vec_string_and_int() {
        // JSONs of types in: const vec<arraykey> AK = vec["4", 7];
        let js = vec![
            json!([{"Rwitness":{"Tiny":{"file":"|f.php","span":26388480394827i64}}},{"Tclass":[[{"Tiny":{"file":"|f.php","span":26388480394827i64}},"\\HH\\vec"],"Nonexact",[[{"Rhint":{"Tiny":{"file":"|f.php","span":26388480393864i64}}},{"Tprim":"Tarraykey"}]]]}]),
            json!([{"Rwitness":{"Tiny":{"file":"|f.php","span":26388480395075i64}}},{"Tprim":"Tstring"}]),
            json!([{"Rwitness":{"Tiny":{"file":"|f.php","span":26388480395393i64}}},{"Tprim":"Tint"}]),
        ];
        assert_eq!(roundtrip(&js), js);
    }
}

use crate::{
    component::graph::State,
    layout::LayoutState,
    rendering::{Backend, PathBuilder, RenderContext},
    settings::Gradient,
};

pub(in crate::rendering) fn render(
    context: &mut RenderContext<'_, impl Backend>,
    [width, height]: [f32; 2],
    component: &State,
    _layout_state: &LayoutState,
) {
    let old_transform = context.transform;
    context.scale(height);
    let width = width / height;

    const GRID_LINE_WIDTH: f32 = 0.015;
    const LINE_WIDTH: f32 = 0.025;
    const CIRCLE_RADIUS: f32 = 0.035;

    context.render_rectangle(
        [0.0, 0.0],
        [width, component.middle],
        &Gradient::Plain(component.top_background_color),
    );
    context.render_rectangle(
        [0.0, component.middle],
        [width, 1.0],
        &Gradient::Plain(component.bottom_background_color),
    );

    for &y in &component.horizontal_grid_lines {
        context.render_rectangle(
            [0.0, y - GRID_LINE_WIDTH],
            [width, y + GRID_LINE_WIDTH],
            &Gradient::Plain(component.grid_lines_color),
        );
    }

    for &x in &component.vertical_grid_lines {
        context.render_rectangle(
            [width * x - GRID_LINE_WIDTH, 0.0],
            [width * x + GRID_LINE_WIDTH, 1.0],
            &Gradient::Plain(component.grid_lines_color),
        );
    }

    let len = if component.is_live_delta_active {
        let p1 = &component.points[component.points.len() - 2];
        let p2 = &component.points[component.points.len() - 1];

        let mut builder = context.backend.path_builder();
        builder.move_to(width * p1.x, component.middle);
        builder.line_to(width * p1.x, p1.y);
        builder.line_to(width * p2.x, p2.y);
        builder.line_to(width * p2.x, component.middle);
        builder.close();
        let partial_fill_path = builder.finish(context.backend);
        context.render_path(&partial_fill_path, component.partial_fill_color);
        context.free_path(partial_fill_path);

        component.points.len() - 1
    } else {
        component.points.len()
    };

    let mut builder = context.backend.path_builder();
    builder.move_to(0.0, component.middle);
    for p in &component.points[..len] {
        builder.line_to(width * p.x, p.y);
    }
    builder.line_to(width * component.points[len - 1].x, component.middle);
    builder.close();
    let fill_path = builder.finish(context.backend);
    context.render_path(&fill_path, component.complete_fill_color);
    context.free_path(fill_path);

    for points in component.points.windows(2) {
        let mut builder = context.backend.path_builder();
        builder.move_to(width * points[0].x, points[0].y);
        builder.line_to(width * points[1].x, points[1].y);

        let color = if points[1].is_best_segment {
            component.best_segment_color
        } else {
            component.graph_lines_color
        };

        let line_path = builder.finish(context.backend);
        context.render_stroke_path(&line_path, color, LINE_WIDTH);
        context.free_path(line_path);
    }

    for (i, point) in component.points.iter().enumerate().skip(1) {
        if i != component.points.len() - 1 || !component.is_live_delta_active {
            let color = if point.is_best_segment {
                component.best_segment_color
            } else {
                component.graph_lines_color
            };

            let circle_path = context
                .backend
                .build_circle(width * point.x, point.y, CIRCLE_RADIUS);
            context.render_path(&circle_path, color);
            context.free_path(circle_path);
        }
    }

    context.transform = old_transform;
}

// Support using the library without the standard library
#![cfg_attr(not(feature = "std"), no_std)]

#[cfg(feature = "std")]
use std::{
    fmt,
    io::{Error, ErrorKind},
};

use core::str::FromStr;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Command {
    pub sender: Sender,
    pub address: u8,
    pub data: Option<u16>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Sender {
    Master,
    Slave,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Address {
    /// Setpoint temperature controller
    SetpointTempControl = 0x00,

    /// Internal temperature
    InternalTemp = 0x01,

    /// Error report
    ErrorReport = 0x05,

    /// Warning message
    WarningMessage = 0x06,

    /// Setting process temperature
    SetProcessTemp = 0x09,

    /// Temperature control mode
    TempControlMode = 0x13,

    /// Temperature control
    TempControl = 0x14,

    /// Operating lock
    OperationLock = 0x17,

    /// Process temperature actual value setting mode
    ProcessTempActualSettingMode = 0x19,
}

impl Address {
    pub fn from_u8(x: u8) -> Option<Self> {
        use self::Address::*;
        match x {
            0x00 => Some(SetpointTempControl),
            0x01 => Some(InternalTemp),
            0x05 => Some(ErrorReport),
            0x06 => Some(WarningMessage),
            0x09 => Some(SetProcessTemp),
            0x13 => Some(TempControlMode),
            0x14 => Some(TempControl),
            0x17 => Some(OperationLock),
            0x19 => Some(ProcessTempActualSettingMode),
            _ => None,
        }
    }
}

impl Into<u8> for Address {
    fn into(self: Address) -> u8 {
        self as u8
    }
}

impl Into<u8> for Sender {
    fn into(self: Sender) -> u8 {
        use self::Sender::*;
        match self {
            Master => b'M',
            Slave => b'S',
        }
    }
}

const EMPTY_DATA: [u8; 4] = [b'*'; 4];

const fn byte_cmd_msg(sender: u8, addr: [u8; 2], data: [u8; 4]) -> [u8; 10] {
    [
        b'{', sender, addr[0], addr[1], data[0], data[1], data[2], data[3], b'\r', b'\n',
    ]
}

impl Command {
    pub fn into_bytes(self) -> [u8; 10] {
        let addr: [u8; 2] = [
            to_upper_hex(self.address / 16),
            to_upper_hex(self.address % 16),
        ];
        let mut data = EMPTY_DATA;
        if let Some(d) = self.data {
            let hi = (d >> 8) as u8;
            let lo = d as u8;
            data[0] = to_upper_hex(hi / 16);
            data[1] = to_upper_hex(hi % 16);
            data[2] = to_upper_hex(lo / 16);
            data[3] = to_upper_hex(lo % 16);
        }
        byte_cmd_msg(self.sender.into(), addr, data)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ParseError {
    /// Invalid message length
    MessageLength,
    /// Non-ASCII str
    NonAsciiStr,
    /// Invalid sender
    Sender,
    /// Invalid command data
    CommandData,
    /// Invalid command address
    Address,
}

#[cfg(feature = "std")]
impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        use self::ParseError::*;
        match *self {
            MessageLength => write!(f, "Invalid message length"),
            NonAsciiStr => write!(f, "Non-ASCII str"),
            Sender => write!(f, "Invalid sender"),
            CommandData => write!(f, "Invalid command data"),
            Address => write!(f, "Invalid command address"),
        }
    }
}

#[cfg(feature = "std")]
impl std::error::Error for ParseError {}

#[cfg(feature = "std")]
impl From<ParseError> for Error {
    fn from(e: ParseError) -> Error {
        Error::new(ErrorKind::InvalidData, e)
    }
}

impl FromStr for Command {
    type Err = ParseError;
    fn from_str(s: &str) -> Result<Self, ParseError> {
        if s.len() != 10 {
            return Err(ParseError::MessageLength);
        }
        if !s.is_ascii() {
            return Err(ParseError::NonAsciiStr);
        }

        let (_start, tail) = s.split_at(1);
        let (sender, tail) = tail.split_at(1);
        let (addr, tail) = tail.split_at(2);
        let (data, _) = tail.split_at(4);

        let sender = match sender {
            "M" => Sender::Master,
            "S" => Sender::Slave,
            _ => {
                return Err(ParseError::Sender);
            }
        };

        let data = match data {
            "****" => None,
            _ => Some(u16::from_str_radix(data, 16).map_err(|_| ParseError::CommandData)?),
        };

        let address = u8::from_str_radix(addr, 16).map_err(|_| ParseError::Address)?;

        Ok(Command {
            sender,
            address,
            data,
        })
    }
}

// TODO: replace this conversation with other methods
// as soon as there is something available within core.
fn to_upper_hex(x: u8) -> u8 {
    match x {
        0..=9 => b'0' + x,
        10..=15 => b'A' + (x - 10),
        _ => unreachable!(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::Sender::*;

    #[test]
    fn from_str_with_invalid_len() {
        assert!(Command::from_str("{M31*****\r\n").is_err());
        assert!(Command::from_str("{M31***\r\n").is_err());
    }

    #[test]
    fn from_bad_str() {
        let msg = "{�ۿ�3";
        assert!(Command::from_str(msg).is_err());
    }

    #[test]
    fn from_str_with_bad_sender() {
        assert!(Command::from_str("{X31****\r\n").is_err());
    }

    #[test]
    fn from_str_with_bad_data() {
        assert!(Command::from_str("{M310z00\r\n").is_err());
    }

    #[test]
    fn from_str_with_bad_address() {
        assert!(Command::from_str("{MTT0000\r\n").is_err());
    }

    #[test]
    fn from_str() {
        let cmd = Command::from_str("{M31****\r\n").unwrap();
        assert_eq!(cmd.sender, Sender::Master);
        assert_eq!(cmd.address, 0x31);
        assert_eq!(cmd.data, None);

        let cmd = Command::from_str("{S223219\r\n").unwrap();
        assert_eq!(cmd.sender, Sender::Slave);
        assert_eq!(cmd.address, 0x22);
        assert_eq!(cmd.data, Some(0x3219));
    }

    #[test]
    fn encode_start_char() {
        assert_eq!(
            Command {
                sender: Master,
                address: 0x31,
                data: None,
            }
            .into_bytes()[0],
            '{' as u8
        );
    }

    #[test]
    fn sender_into_u8() {
        let x: u8 = Master.into();
        assert_eq!(x, b'M');
        let x: u8 = Slave.into();
        assert_eq!(x, b'S');
    }

    #[test]
    fn encode_sender() {
        let address = 0x31;
        let data = None;
        assert_eq!(
            Command {
                sender: Master,
                address,
                data,
            }
            .into_bytes()[1],
            'M' as u8
        );
        assert_eq!(
            Command {
                sender: Slave,
                address,
                data,
            }
            .into_bytes()[1],
            'S' as u8
        );
    }

    #[test]
    fn test_to_upper_hex() {
        assert_eq!(to_upper_hex(0) as char, '0');
        assert_eq!(to_upper_hex(9) as char, '9');
        assert_eq!(to_upper_hex(10) as char, 'A');
        assert_eq!(to_upper_hex(15) as char, 'F');
    }

    #[test]
    fn encode_address() {
        let data = None;
        let sender = Slave;
        let cmd = Command {
            sender,
            address: 0x31,
            data,
        }
        .into_bytes();
        assert_eq!(cmd[2], '3' as u8);
        assert_eq!(cmd[3], '1' as u8);

        let cmd = Command {
            sender,
            address: 0x7,
            data,
        }
        .into_bytes();
        assert_eq!(cmd[2], '0' as u8);
        assert_eq!(cmd[3], '7' as u8);

        let cmd = Command {
            sender,
            address: 255,
            data,
        }
        .into_bytes();
        assert_eq!(cmd[2], 'F' as u8);
        assert_eq!(cmd[3], 'F' as u8);
    }

    #[test]
    fn encode_data() {
        let address = 0x19;
        let sender = Slave;

        let cmd = Command {
            sender,
            address,
            data: Some(1),
        }
        .into_bytes();
        assert_eq!(&cmd[4..8], b"0001");

        let cmd = Command {
            sender,
            address,
            data: Some(0xab),
        }
        .into_bytes();
        assert_eq!(&cmd[4..8], b"00AB");

        let cmd = Command {
            sender,
            address,
            data: Some(core::u16::MAX),
        }
        .into_bytes();
        assert_eq!(&cmd[4..8], b"FFFF");

        let cmd = Command {
            sender,
            address,
            data: None,
        }
        .into_bytes();
        assert_eq!(&cmd[4..8], b"****");
    }

    #[test]
    fn encode_delimiters() {
        let cmd = Command {
            sender: Master,
            address: 0x22,
            data: None,
        }
        .into_bytes();
        assert_eq!(&cmd[8..10], b"\r\n");
    }

    #[test]
    fn encode_complete_command() {
        let cmd = Command {
            sender: Sender::Master,
            address: 0x09,
            data: Some(0x05E8),
        }
        .into_bytes();
        assert_eq!(cmd, *b"{M0905E8\r\n");

        let cmd = Command {
            sender: Sender::Slave,
            address: 0x19,
            data: Some(0x0001),
        }
        .into_bytes();
        assert_eq!(cmd, *b"{S190001\r\n");
    }

    #[test]
    fn encode_address_enum() {
        use self::Address::*;
        let expected = &[
            (SetpointTempControl, 0x00),
            (InternalTemp, 0x01),
            (ErrorReport, 0x05),
            (WarningMessage, 0x06),
            (SetProcessTemp, 0x09),
            (TempControlMode, 0x13),
            (TempControl, 0x14),
            (OperationLock, 0x17),
            (ProcessTempActualSettingMode, 0x19),
        ];
        for (addr, nr) in expected {
            assert_eq!(*addr as u8, *nr);
        }
        let byte: u8 = Address::OperationLock.into();
        assert_eq!(byte, 0x17);
    }

    #[test]
    fn decode_address_enum() {
        use self::Address::*;
        let expected = &[
            (SetpointTempControl, 0x00),
            (InternalTemp, 0x01),
            (ErrorReport, 0x05),
            (WarningMessage, 0x06),
            (SetProcessTemp, 0x09),
            (TempControlMode, 0x13),
            (TempControl, 0x14),
            (OperationLock, 0x17),
            (ProcessTempActualSettingMode, 0x19),
        ];
        for (addr, nr) in expected {
            assert_eq!(Address::from_u8(*nr).unwrap(), *addr);
        }
        assert!(Address::from_u8(255).is_none());
    }
}

