}

use std::collections::HashMap;

use chrono::{TimeZone, Utc};
use rand::{Rng, thread_rng};
use rand::distributions::Alphanumeric;
use rand::seq::SliceRandom;
use serde_json::{json, Map, Value};
use uuid::Uuid;

use crate::field_kinds::FieldKind;
use crate::object_definitions::ObjectDefinition;

pub fn string() -> String {
    thread_rng().sample_iter(&Alphanumeric).take(20).collect()
}

pub fn u64() -> u64 {
    thread_rng().gen_range(0, 10000)
}

pub fn float() -> f64 {
    thread_rng().gen_range(0.0, 1000.0)
}

pub fn boolean() -> bool {
    thread_rng().gen()
}

pub fn datetime() -> String {
    let offset = thread_rng().gen_range(0, 10000000);
    let point = Utc.timestamp(offset * 60 * 24, 0);
    point.to_rfc3339()
}

pub fn string_matching_pattern(pattern: &str) -> String {
    let p;
    let need_filter;
    if has_anchors(pattern) {
        p = remove_anchors(pattern);
        need_filter = true;
    } else {
        p = pattern.to_owned();
        need_filter = false;
    }

    let mut parser = regex_syntax::ParserBuilder::new()
        .unicode(false)
        .build();

    let hir = parser.parse(&p).unwrap();
    let gen = rand_regex::Regex::with_hir(hir, 5).unwrap();

    if need_filter {
        let filter_regex = regex::Regex::new(pattern).unwrap();
        thread_rng()
            .sample_iter::<String, _>(&gen)
            .filter(|s| filter_regex.is_match(s))
            .next()
            .unwrap()
    } else {
        thread_rng().sample(&gen)
    }
}

pub fn element_from_collection<T>(v: &Vec<T>) -> &T {
    v.choose(&mut thread_rng()).unwrap()
}

pub fn value_of_kind(k: &FieldKind, reference_map: Option<&HashMap<String, ObjectDefinition>>) -> Value {
    match k {
        FieldKind::Str => json!(string()),
        FieldKind::Int => json!(u64()),
        FieldKind::Float => json!(float()),
        FieldKind::Bool => json!(boolean()),
        FieldKind::Object => random_object(),
        FieldKind::Null => json!(()),
        FieldKind::OneOf(kinds) => {
            let kind = element_from_collection(kinds);
            value_of_kind(kind, reference_map)
        }
        FieldKind::Reference(s) => reference_map
            .unwrap()[s]
            .generate_json(reference_map)
            .unwrap(),
        FieldKind::ListOf(field_kinds) => {
            field_kinds
                .iter()
                .flat_map(|k| values_of_kind(k, thread_rng().gen_range(0, 10), reference_map))
                .collect()
        }
    }
}

pub fn values_of_kind(k: &FieldKind, count: u64, reference_map: Option<&HashMap<String, ObjectDefinition>>) -> Vec<Value> {
    (0..count).map(|_| value_of_kind(k, reference_map)).collect()
}

pub fn uuid4() -> String {
    Uuid::new_v4().to_string()
}

fn random_object() -> Value {
    let domain_of_values = FieldKind::OneOf(vec![FieldKind::Int, FieldKind::Str, FieldKind::Bool]);
    let m = (0..10)
        .map(|_| (string(), value_of_kind(&domain_of_values, None)))
        .collect::<Map<String, Value>>();
    Value::Object(m)
}

fn has_anchors(pattern: &str) -> bool {
    pattern.contains("^") || pattern.contains("$")
}

fn remove_anchors(pattern: &str) -> String {
    pattern.replace("^", "").replace("$", "")
}

#[cfg(test)]
mod tests {
    use chrono::DateTime;

    use super::*;

    #[test]
    fn generates_random_datetime() {
        for _ in 0..100 {
            let d = datetime();
            let dt = d.parse::<DateTime<Utc>>();
            assert!(dt.is_ok());
        }
    }

    #[test]
    fn regex_with_anchors() {
        let s = r"^[a-z]+(-[a-z0-9]+)*$";
        let expr = regex::Regex::new(s).unwrap();

        for _ in 0..100 {
            let r = string_matching_pattern(s);
            assert!(expr.is_match(&r));
        }
    }

    #[test]
    fn regex_without_anchors() {
        let s = r"[a-z]+(-[a-z0-9]+)*";
        let expr = regex::Regex::new(s).unwrap();

        for _ in 0..100 {
            let r = string_matching_pattern(s);
            assert!(expr.is_match(&r));
        }
    }

    #[test]
    fn anchor_presence() {
        assert!(has_anchors("^"));
        assert!(has_anchors("$"));
    }

    #[test]
    fn choice_from_collection() {
        let v = vec![1, 2, 3, 4, 5, 6];
        for _ in 0..100 {
            let c = element_from_collection(&v);
            assert!(*c >= 1 && *c <= 6);
        }
    }

    #[test]
    fn values_for_kind() {
        let kind = FieldKind::OneOf(vec![FieldKind::Str, FieldKind::Int, FieldKind::Object]);
        for _ in 0..100 {
            let v = value_of_kind(&kind, None);
            assert!(v.is_string() || v.is_number() || v.is_object());
        }
    }

    #[test]
    fn list_generation() {
        let values = value_of_kind(&FieldKind::ListOf(vec![FieldKind::Str, FieldKind::Int]), None);
        values.as_array().unwrap().iter().for_each(|v| {
            assert!(v.is_string() || v.is_number())
        });
    }
}

//! Fonts with `UTF16` support.
use super::legacy::NOTHING_TO_DISPLAY;
pub use super::basic::{BASIC_UTF16, BasicFonts};
pub use super::block::{BLOCK_UTF16, BlockFonts};
pub use super::box_chars::{BOX_UTF16, BoxFonts};
pub use super::greek::{GREEK_UTF16, GreekFonts};
pub use super::hiragana::{HIRAGANA_UTF16, HiraganaFonts};
pub use super::latin::{LATIN_UTF16, LatinFonts};
pub use super::misc::{MISC_UTF16, MiscFonts};
pub use super::sga::{SGA_UTF16, SgaFonts};

/// A single 8x8 font which supports `UTF-16` encoding/decoding.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct FontUtf16(pub u16, pub [u8; 8]);

impl FontUtf16 {
    /// Return the utf16 value as `u16`.
    pub fn utf16(&self) -> u16 {
        self.0
    }
    /// Return the `[u8; 8]`-representation for this font.
    pub fn byte_array(&self) -> [u8; 8] {
        self.1
    }

    /// Returns a `bool` indicating whether this font renders as a whitespace (all `0`).
    pub fn is_whitespace(&self) -> bool {
        self.1 == NOTHING_TO_DISPLAY
    }

    /// Consumes the current `FontUtf16` and returns the inner `(u16, [u8; 8])` tuple.
    pub fn into_inner(self) -> (u16, [u8; 8]) {
        self.into()
    }
}

impl Into<u16> for FontUtf16 {
    fn into(self) -> u16 {
        self.0
    }
}

impl Into<[u8; 8]> for FontUtf16 {
    fn into(self) -> [u8; 8] {
        self.1
    }
}

impl Into<(u16, [u8; 8])> for FontUtf16 {
    fn into(self) -> (u16, [u8; 8]) {
        (self.0, self.1)
    }
}

/// A trait for collections of `FontUtf16`, which provide methods for retrieving
/// the `[u8; 8]` by key, using the corresponding Unicode value, encoded as UTF-16 (`u16`).
pub trait Utf16Fonts {
    fn get(&self, key: u16) -> Option<[u8; 8]>;
    fn get_font(&self, key: u16) -> Option<FontUtf16>;
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn font_utf16_converts_into_u16() {
        let my_font = FontUtf16('á' as u16, [110u8; 8]);
        let utf16: u16 = my_font.into();
        assert_eq!(utf16, 'á' as u16);
    }

    #[test]
    fn font_utf16_converts_into_byte_array() {
        let my_font = FontUtf16('C' as u16, NOTHING_TO_DISPLAY);
        let byte_array: [u8; 8] = my_font.into();
        assert_eq!(byte_array, NOTHING_TO_DISPLAY);
    }

    #[test]
    fn font_utf16_converts_into_inner_tuple() {
        let my_font = FontUtf16('Á' as u16, [110u8; 8]);
        let font_tuple: (u16, [u8; 8]) = my_font.into();
        assert_eq!(font_tuple, ('Á' as u16, [110u8; 8]));
    }

    #[test]
    fn font_utf16_api_method_utf16_returns_u16() {
        let my_font = FontUtf16('ñ' as u16, [0x20; 8]);
        assert_eq!(my_font.utf16(), 'ñ' as u16);
    }

    #[test]
    fn font_utf16_api_method_byte_array_returns_array_with_8_bytes() {
        let my_font = FontUtf16('Ñ' as u16, [0x20; 8]);
        assert_eq!(my_font.byte_array(), [0x20; 8]);
    }

    #[test]
    fn font_utf16_api_method_to_string_returns_string_from_utf16() {
        let my_font = FontUtf16('Ñ' as u16, [0x20; 8]);
        assert_eq!(my_font.to_string(), "Ñ".to_string());
    }

    #[test]
    fn font_utf16_api_method_is_whitespace_returns_bool() {
        let my_font = FontUtf16('Ñ' as u16, [0x20; 8]);
        assert_eq!(my_font.is_whitespace(), false);
        let my_font = FontUtf16('Ñ' as u16, NOTHING_TO_DISPLAY);
        assert!(my_font.is_whitespace());
    }

    #[test]
    fn font_utf16_api_method_into_inner_returns_inner_tuple() {
        let my_font = FontUtf16('Á' as u16, [110u8; 8]);
        assert_eq!(my_font.into_inner(), ('Á' as u16, [110u8; 8]));
    }
}

//! Teensy 4.0 specific APIs
//!
//! Use [`into_pins`](fn.into_pins.html) to constrain the processor pads into the pins available on the Teensy 4.0.
//! If you cannot safely acquire all processor pads, use the unsafe [`Pins::new`](struct.Pins.html#method.new)
//! method to generate pins.
//!
//! | Pin  | Pad ID   |  Alt0    |  Alt1        |  Alt2        |  Alt3     |  Alt4        |  Alt5            |  Alt6        |  Alt7   |  Alt8   |  Alt9   |
//! | ---- | -------- | -------- | ------------ | ------------ | --------- | ------------ | ---------------- | ------------ | ------- | ------- | ------- |
//! |  34  |`SD_B0_03`|          |`FlexPWM1_1_B`|              |           |  `SPI1_SDI`  |                  |              |         |         |         |
//! |  35  |`SD_B0_02`|          |`FlexPWM1_1_A`|              |           |  `SPI1_SDO`  |                  |              |         |         |         |
//! |  36  |`SD_B0_01`|          |`FlexPWM1_0_B`|  `I2C3_SDA`  |           |  `SPI1_PCS0` |                  |              |         |         |         |
//! |  37  |`SD_B0_00`|          |`FlexPWM1_0_A`|  `I2C3_SCL`  |           |  `SPI1_SCK`  |                  |              |         |         |         |
//! |  38  |`SD_B0_05`|          |`FlexPWM1_2_B`|  `UART8_RX`  |           |              |                  |              |         |         |         |
//! |  39  |`SD_B0_04`|          |`FlexPWM1_2_A`|  `UART8_TX`  |           |              |                  |              |         |         |         |

pub use crate::common::*;
use crate::iomuxc::{sd_b0::*, ErasedPad};

