use std::error;
use std::fmt;
use std::ops::Deref;

#[derive(Debug)]
pub enum Error {
    Simple(String),
    Cause(String, Box<dyn error::Error>),
}

impl From<Box<dyn error::Error>> for Error {
    fn from(error: Box<dyn error::Error>) -> Self {
        Error::Cause(String::from("an error occurred"), error)
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match *self {
            Error::Simple(ref m) => writeln!(f, "{}", m),
            Error::Cause(ref m, ref e) => writeln!(f, "{}: {}", m, e),
        }
    }
}

impl error::Error for Error {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match &self {
            Error::Simple(_) => None,
            Error::Cause(_, ref e) => Some(e.deref()),
        }
    }
}

use {
    crate::ident_type::IdentType,
    anyhow::{bail, Context},
    std::convert::TryFrom,
};

#[derive(Clone)]
pub enum Shell {
    Bash,
    Elvish,
    Fish,
    PowerShell,
    Zsh,
}

impl Shell {
    pub const SHELLS: [&'static str; 5] = ["bash", "elvish", "fish", "pwsh", "zsh"];

    fn ident_check<'a>(&self, s: &'a str, ident_type: &IdentType) -> anyhow::Result<&'a str> {
        let re = ident_type.re(self);
        if re.is_match(s) {
            Ok(s)
        } else {
            bail!(
                "`{}` is not a valid identifier, it must conform to this regex: `{}`",
                s,
                re.to_string(),
            )
        }
    }

    fn str_escape(&self, s: &str) -> String {
        let mut s = s.replace(
            '\'',
            match self {
                Self::Fish => "\\'",
                Self::Bash | Self::Elvish | Self::Zsh => r#"'"'"'"#,
                Self::PowerShell => "''",
            },
        );
        s.insert(0, '\'');
        s.push('\'');
        s
    }

    fn array_escape(&self, xs: &[&str]) -> String {
        let mut s = match self {
            Self::Fish => String::new(),
            Self::Bash | Self::Zsh => "(".into(),
            Self::Elvish => "[".into(),
            Self::PowerShell => "@(".into(),
        };
        let len = xs.len();
        for (idx, x) in xs.iter().enumerate() {
            s.push_str(&self.str_escape(x));
            if idx < len - 1 {
                if let Self::PowerShell = self {
                    s.push(',');
                }
                s.push(' ');
            }
        }
        match self {
            Self::Bash | Self::PowerShell | Self::Zsh => s.push(')'),
            Self::Elvish => s.push(']'),
            _ => {}
        }
        s
    }

    fn assignment(&self, var_ident: &str, val: &str) -> String {
        match self {
            Self::Fish => format!("set {} {}", var_ident, val),
            Self::Bash | Self::Zsh => format!("{}={}", var_ident, val),
            Self::Elvish => format!("{} = {}", var_ident, val),
            Self::PowerShell => format!(
                "Set-Variable -Name {} -Value {}",
                self.str_escape(var_ident),
                val
            ),
        }
    }

    // NOTE: In the future we could add an option to use associative arrays instead of arrays for
    // elvish and powershell.
    fn parse_(
        &self,
        matches: &clap::ArgMatches,
        var_prefix: Option<&str>,
        // Subcommands are recursive, used to mantain the subcommand prefix for variables.
        subcommands_prefixes: Option<Vec<&str>>,
    ) -> anyhow::Result<String> {
        let vprefix = {
            let mut s = String::new();
            if let Some(vprefix) = var_prefix {
                s = self.ident_check(vprefix, &IdentType::Head)?.into();
            }
            s
        };

        let subcommands_ident = if let Some(ref xs) = subcommands_prefixes {
            format!("{}_", xs.join("_"))
        } else {
            String::new()
        };
        let subcommands_ident = if subcommands_ident.is_empty() {
            subcommands_ident
        } else {
            self.ident_check(&subcommands_ident, &IdentType::Tail)?
                .into()
        };

        let mut buffer = String::new();

        if subcommands_prefixes.is_none() {
            buffer.push_str(
                &self.assignment(&format!("{}success", vprefix), &self.str_escape("true")),
            );
            buffer.push('\n');
        }

        if let Some(ref usage) = matches.usage {
            let clap_usage = self.str_escape(usage);
            buffer.push_str(&self.assignment(
                &format!("{}{}usage", vprefix, subcommands_ident),
                &clap_usage,
            ));
            buffer.push('\n');
        }

        if let Some(ref subcommand) = matches.subcommand {
            let clap_subcommand = self.str_escape(&subcommand.name);
            buffer.push_str(&self.assignment(
                &format!("{}{}subcommand", vprefix, subcommands_ident),
                &clap_subcommand,
            ));
            buffer.push('\n');

            let mut subcommands_prefixes = subcommands_prefixes.unwrap_or_default();
            subcommands_prefixes.push(&subcommand.name);
            buffer.push_str(&self.parse_(
                &subcommand.matches,
                var_prefix,
                Some(subcommands_prefixes),
            )?)
        }

        for (name, arg) in &matches.args {
            let arg_name = self.ident_check(name, &IdentType::Tail)?;

            let clap_occurs = self.str_escape(&arg.occurs.to_string());
            buffer.push_str(&self.assignment(
                &format!("{}{}{}_occurs", vprefix, subcommands_ident, arg_name),
                &clap_occurs,
            ));
            buffer.push('\n');

            let clap_indices = arg
                .indices
                .iter()
                .map(|x| x.to_string())
                .collect::<Vec<_>>();
            let clap_indices = clap_indices.iter().map(|x| x.as_str()).collect::<Vec<_>>();
            let clap_indices = self.array_escape(&clap_indices);
            buffer.push_str(&self.assignment(
                &format!("{}{}{}_indices", vprefix, subcommands_ident, arg_name),
                &clap_indices,
            ));
            buffer.push('\n');

            let mut clap_vals = Vec::new();
            for val in &arg.vals {
                clap_vals.push(val.to_str().context("String contains invalid UTF-8 data")?);
            }
            let clap_vals = self.array_escape(&clap_vals);
            buffer.push_str(&self.assignment(
                &format!("{}{}{}_vals", vprefix, subcommands_ident, arg_name),
                &clap_vals,
            ));
            buffer.push('\n');
        }

        Ok(buffer)
    }

    pub fn parse(
        &self,
        matches: clap::ArgMatches,
        var_prefix: Option<&str>,
    ) -> anyhow::Result<String> {
        Ok(self.parse_(&matches, var_prefix, None)?.trim_end().into())
    }
}

impl TryFrom<&str> for Shell {
    type Error = anyhow::Error;

    fn try_from(s: &str) -> anyhow::Result<Self> {
        match s {
            "bash" => Ok(Shell::Bash),
            "elvish" => Ok(Shell::Elvish),
            "fish" => Ok(Shell::Fish),
            "pwsh" => Ok(Shell::PowerShell),
            "zsh" => Ok(Shell::Zsh),
            _ => bail!("Shell must be one of {:?}", Shell::SHELLS),
        }
    }
}

impl<'a> Into<clap::Shell> for &'a Shell {
    fn into(self) -> clap::Shell {
        match *self {
            Shell::Bash => clap::Shell::Bash,
            Shell::Elvish => clap::Shell::Elvish,
            Shell::Fish => clap::Shell::Fish,
            Shell::PowerShell => clap::Shell::PowerShell,
            Shell::Zsh => clap::Shell::Zsh,
        }
    }
}

use std::{collections::HashSet, ffi::OsString, fs, io, lazy::SyncLazy, ops::Range, path::Path};

use image::{imageops, io::Reader as ImageReader, ImageBuffer, ImageError, ImageFormat, Rgba, RgbaImage};
use indicatif::ProgressIterator;
use itertools::{iproduct, izip};
use path_macro::path;
use rayon::iter::{ParallelBridge, ParallelIterator};
use regex::Regex;

use crate::{cache::error::CacheResult, renderers::scale};

static RE: SyncLazy<Regex> = SyncLazy::new(|| Regex::new(r"(?P<p>\d+)(?:_)(?P<i>\d+)(?:_)(?P<j>\d+)(?:\.png)").expect("Regex is cursed."));

/// Given a folder and a range of zoom levels, recursively creates tiles for all zoom levels.
pub fn render_zoom_levels(folder: impl AsRef<Path> + Send + Sync, mapid: i32, range: Range<i8>, backfill: [u8; 4]) -> CacheResult<()> {
    let zoom_levels = range.rev();
    for zoom in zoom_levels {
        fs::create_dir_all(path!(folder / format!("{mapid}/{zoom}")))?;

        let new_tile_coordinates = get_future_filenames(&folder, mapid, zoom + 1)?.into_iter();

        let func = |(p, i, j)| {
            let img = make_tile(&folder, mapid, zoom, p, i, j, backfill).unwrap();
            let filename = path!(folder / format!("{mapid}/{zoom}/{p}_{i}_{j}.png"));
            img.save(filename).unwrap();
        };

        new_tile_coordinates.progress().par_bridge().for_each(func);
    }
    Ok(())
}

fn to_coordinates(text: OsString) -> CacheResult<(i32, i32, i32)> {
    let caps = RE.captures(text.to_str().unwrap()).unwrap();
    let p = caps.name("p").unwrap().as_str().parse::<i32>()?;
    let i = caps.name("i").unwrap().as_str().parse::<i32>()?;
    let j = caps.name("j").unwrap().as_str().parse::<i32>()?;
    Ok((p, i, j))
}

fn make_tile(
    folder: impl AsRef<Path>,
    mapid: i32,
    target_zoom: i8,
    target_plane: i32,
    target_i: i32,
    target_j: i32,
    backfill: [u8; 4],
) -> CacheResult<ImageBuffer<Rgba<u8>, Vec<u8>>> {
    let mut base = RgbaImage::from_fn(512, 512, |_, _| Rgba(backfill));

    let files = get_files(folder, mapid, target_zoom, target_plane, target_i, target_j);

    for ((di, dj), img) in files {
        match img {
            Ok(f) => {
                let img = f.into_rgba8();
                imageops::overlay(&mut base, &img, (256 * di) as i64, 256 * (1 - dj) as i64);
            }
            // can be missing; if so, swallow
            Err(ImageError::IoError(ref e)) if e.kind() == io::ErrorKind::NotFound => {}
            Err(other_error) => return Err(other_error.into()),
        }
    }
    let scaled = scale::resize_half(base);
    Ok(scaled)
}

fn get_files(
    folder: impl AsRef<Path>,
    mapid: i32,
    target_zoom: i8,
    target_plane: i32,
    target_i: i32,
    target_j: i32,
) -> [((i32, i32), Result<image::DynamicImage, ImageError>); 4] {
    [(0, 0), (0, 1), (1, 0), (1, 1)].map(|(di, dj)| {
        let i = (target_i << 1) + di;
        let j = (target_j << 1) + dj;
        let zoom = target_zoom + 1;
        let filename = path!(folder / format!("{mapid}/{zoom}/{target_plane}_{i}_{j}.png"));
        ((di, dj), image::open(filename))
    })
}

fn get_future_filenames(folder: impl AsRef<Path>, mapid: i32, zoom: i8) -> CacheResult<HashSet<(i32, i32, i32)>> {
    let dir = path!(folder / format!("{mapid}/{zoom}"));

    let new_tiles = fs::read_dir(&dir)?
        .collect::<io::Result<Vec<_>>>()?
        .into_iter()
        .map(|entry| entry.file_name())
        .map(to_coordinates)
        .collect::<CacheResult<Vec<_>>>()?
        .into_iter()
        .map(|(p, i, j)| (p, i >> 1, j >> 1))
        .collect::<HashSet<_>>();

    Ok(new_tiles)
}

use sdl2::audio::{AudioCallback, AudioDevice, AudioSpecDesired};
use sdl2::keyboard::Keycode;
use sdl2::pixels::Color;
use sdl2::rect::Rect;
use sdl2::render::Canvas;
use sdl2::Sdl;
use sdl2::video::Window;

use crate::vm::Vm;

pub struct Ui {
    pub canvas: Canvas<Window>,
    device: AudioDevice<SquareWave>
}

struct SquareWave {
    phase_inc: f32,
    phase: f32,
    volume: f32,
}

impl AudioCallback for SquareWave {
    type Channel = f32;

    fn callback(&mut self, out: &mut [f32]) {
        // Generate a square wave
        for x in out.iter_mut() {
            *x = if self.phase <= 0.5 { self.volume } else { -self.volume };
            self.phase = (self.phase + self.phase_inc) % 1.0;
        }
    }
}

impl Ui {
    /// Creates a new `Ui` instance with default state
    pub fn init(sdl_context: &Sdl, scale: u32) -> Ui {
        let video_subsystem = sdl_context.video().unwrap();
        let window = video_subsystem.window("chip-8", 64 * scale, 32 * scale)
            .position_centered()
            .opengl()
            .build()
            .unwrap();
        let mut canvas = window.into_canvas().build().unwrap();

        canvas.set_draw_color(Color::RGB(0, 0, 0));
        canvas.clear();
        canvas.present();


        let audio_subsystem = sdl_context.audio().unwrap();
        let desired_spec = AudioSpecDesired {
            freq: Some(44000),
            channels: Some(1),      // mono
            samples: None,          // default sample size
        };

        let device = audio_subsystem.open_playback(None, &desired_spec, |spec| {
            // Initialize the audio callback
            SquareWave {
                phase_inc: 440.0 / spec.freq as f32,
                phase: 0.0,
                volume: 0.25,
            }
        }).unwrap();

        Ui {
            canvas,
            device
        }
    }

    pub fn set_key_pressed(&mut self, vm: &mut Vm, keycode: Keycode) {
        match keycode {
            Keycode::Num1 => { vm.key_states[0x1] = true; }
            Keycode::Num2 => { vm.key_states[0x2] = true; }
            Keycode::Num3 => { vm.key_states[0x3] = true; }
            Keycode::Q => { vm.key_states[0x4] = true; }
            Keycode::W => { vm.key_states[0x5] = true; }
            Keycode::E => { vm.key_states[0x6] = true; }
            Keycode::A => { vm.key_states[0x7] = true; }
            Keycode::S => { vm.key_states[0x8] = true; }
            Keycode::D => { vm.key_states[0x9] = true; }
            Keycode::Z => { vm.key_states[0xA] = true; }
            Keycode::X => { vm.key_states[0x0] = true; }
            Keycode::C => { vm.key_states[0xB] = true; }
            Keycode::Num4 => { vm.key_states[0xC] = true; }
            Keycode::R => { vm.key_states[0xD] = true; }
            Keycode::F => { vm.key_states[0xE] = true; }
            Keycode::V => { vm.key_states[0xF] = true; }
            _ => {}
        }
    }

    pub fn set_key_released(&mut self, vm: &mut Vm, keycode: Keycode) {
        match keycode {
            Keycode::Num1 => { vm.key_states[0x1] = false; }
            Keycode::Num2 => { vm.key_states[0x2] = false; }
            Keycode::Num3 => { vm.key_states[0x3] = false; }
            Keycode::Q => { vm.key_states[0x4] = false; }
            Keycode::W => { vm.key_states[0x5] = false; }
            Keycode::E => { vm.key_states[0x6] = false; }
            Keycode::A => { vm.key_states[0x7] = false; }
            Keycode::S => { vm.key_states[0x8] = false; }
            Keycode::D => { vm.key_states[0x9] = false; }
            Keycode::Z => { vm.key_states[0xA] = false; }
            Keycode::X => { vm.key_states[0x0] = false; }
            Keycode::C => { vm.key_states[0xB] = false; }
            Keycode::Num4 => { vm.key_states[0xC] = false; }
            Keycode::R => { vm.key_states[0xD] = false; }
            Keycode::F => { vm.key_states[0xE] = false; }
            Keycode::V => { vm.key_states[0xF] = false; }
            _ => {}
        }
    }

    /// Draws the CPU's display to the canvas
    pub fn draw_canvas(&mut self, vm: &mut Vm, scale: u32) {
        for i in 0..64 * 32 {
            let current_pixel = vm.screen[i];
            let x = (i % 64) * scale as usize;
            let y = (i / 64) * scale as usize;

            self.canvas.set_draw_color(Color::RGB(0, 0, 0));
            if current_pixel == 1 {
                self.canvas.set_draw_color(Color::RGB(255, 255, 255));
            }
            let _ = self.canvas.fill_rect(Rect::new(x as i32, y as i32, scale, scale));
        }
        self.canvas.present();
    }

    /// Plays a square wave sound
    pub fn play_sound(&mut self) {
        self.device.resume();
    }

    /// Stops the sound
    pub fn stop_sound(&mut self) {
        self.device.pause();
    }
}

use crate::*;
use helium_proto::RoutingInformation;
use link_packet::LinkPacket;
use service::{
    gateway::{Response as GatewayResponse, Service as GatewayService, Streaming},
    router::Service as RouterService,
};
use slog::{debug, info, o, warn, Logger};
use std::{collections::HashMap, sync::Arc, time::Duration};
use tokio::{
    sync::mpsc::{Receiver, Sender},
    time,
};

pub mod filter;
pub mod routing;

pub use helium_proto::Region;
pub use routing::Routing;

pub struct Router {
    downlinks: Sender<LinkPacket>,
    uplinks: Receiver<LinkPacket>,
    region: Region,
    keypair: Arc<Keypair>,
    gateways: Vec<KeyedUri>,
    routing_height: u64,
    clients: HashMap<u32, Routing>,
    default_client: RouterService,
}

impl Router {
    pub fn new(
        downlinks: Sender<LinkPacket>,
        uplinks: Receiver<LinkPacket>,
        settings: &Settings,
    ) -> Result<Self> {
        let gateways = settings.gateways.clone();
        let router_settings = settings.router.clone();
        let default_client =
            RouterService::new(router_settings.uri, Some(router_settings.public_key))?;
        Ok(Self {
            keypair: settings.keypair.clone(),
            region: settings.region,
            uplinks,
            downlinks,
            gateways,
            routing_height: 0,
            clients: HashMap::new(),
            default_client,
        })
    }

    pub async fn run(&mut self, shutdown: triggered::Listener, logger: &Logger) -> Result {
        let logger = logger.new(o!("module" => "router"));
        info!(logger, "starting");
        loop {
            let mut gateway = GatewayService::random_new(&self.gateways)?;
            info!(logger, "selected gateway";
                "public_key" => gateway.verifier.to_string(),
                "uri" => gateway.uri.to_string());
            tokio::select! {
                    _ = shutdown.clone() => {
                        info!(logger, "shutting down");
                        return Ok(())
                    },
                    routing_stream = gateway.routing(self.routing_height) => {
                        match routing_stream {
                            Ok(stream) => self.run_with_routing_stream(stream, shutdown.clone(), &logger).await?,
                            Err(err) => {
                                warn!(logger, "routing error: {:?}", err);
                                time::sleep(Duration::from_secs(5)).await;
                            }
                        }
                    }
            }
        }
    }

    async fn run_with_routing_stream(
        &mut self,
        mut routing_stream: Streaming,
        shutdown: triggered::Listener,
        logger: &Logger,
    ) -> Result {
        loop {
            tokio::select! {
                _ = shutdown.clone() => {
                    info!(logger, "shutting down");
                    return Ok(())
                },
                routing = routing_stream.message() => match routing {
                    Ok(Some(response)) => self.handle_routing_update(&logger, &response),
                    Ok(None) => {return Ok(())},
                    Err(err) => {
                        info!(logger, "routing error: {:?}", err);
                        return Ok(())
                    }
                },
                uplink = self.uplinks.recv() => match uplink {
                    Some(packet) => match self.handle_uplink(&logger, packet).await {
                        Ok(()) =>  (),
                        Err(err) => warn!(logger, "ignoring failed uplink {:?}", err)
                    },
                    None => warn!(logger, "ignoring closed downlinks channel"),
                },
            }
        }
    }

    fn handle_routing_update(&mut self, logger: &Logger, response: &GatewayResponse) {
        let update_height = response.height();
        if update_height <= self.routing_height {
            warn!(
                logger,
                "router returned invalid height {:?} while at {:?}",
                update_height,
                self.routing_height
            );
            return;
        }
        let routings = match response.routings() {
            Ok(v) => v,
            Err(err) => {
                warn!(logger, "error decoding routing {:?}", err);
                return;
            }
        };
        for routing in routings {
            match routing::Routing::from_proto(routing) {
                Ok(client) => {
                    self.clients.insert(routing.oui, client);
                }
                Err(err) => warn!(logger, "failed to construct router client: {:?}", err),
            }
        }
        self.routing_height = update_height;
        info!(
            logger,
            "updated routing to height {:?}", self.routing_height
        )
    }

    async fn handle_uplink(&mut self, logger: &Logger, uplink: LinkPacket) -> Result {
        if uplink.packet.routing.is_none() {
            info!(logger, "ignoring, no routing data");
            return Ok(());
        };
        let gateway_mac = uplink.gateway_mac;
        let message = uplink.to_state_channel_message(&self.keypair, self.region)?;
        for mut client in self.router_clients_for_uplink(&uplink) {
            let downlinks = self.downlinks.clone();
            let message = message.clone();
            let logger = logger.clone();
            info!(logger, "routing packet to: {}", client.uri);
            tokio::spawn(async move {
                match client.route(message).await {
                    Ok(response) => {
                        debug!(logger, "response from router {:?}", response);
                        if let Some(downlink) =
                            LinkPacket::from_state_channel_message(response, gateway_mac)
                        {
                            match downlinks.send(downlink).await {
                                Ok(()) => (),
                                Err(_) => {
                                    warn!(logger, "failed to push downlink")
                                }
                            }
                        }
                    }
                    Err(err) => warn!(logger, "ignoring uplink error: {:?}", err),
                }
            });
        }
        Ok(())
    }

    fn router_clients_for_uplink(&self, uplink: &LinkPacket) -> Vec<RouterService> {
        match &uplink.packet.routing {
            Some(RoutingInformation {
                data: Some(routing_data),
            }) => {
                let found: Vec<RouterService> = self
                    .clients
                    .values()
                    .filter(|&routing| routing.matches_routing_data(&routing_data))
                    .flat_map(|routing| routing.clients.clone())
                    .collect();
                if found.is_empty() {
                    vec![self.default_client.clone()]
                } else {
                    found
                }
            }
            _ => vec![],
        }
    }
}

