use tui::widgets::ListState;

use crate::utils::numbers::get_random_to;

pub struct StatefulList<String> {
    pub state: ListState,
    pub items: Vec<String>,
}

impl<String> StatefulList<String> {
    pub fn with_items(items: Vec<String>) -> StatefulList<String> {
        StatefulList {
            state: ListState::default(),
            items,
        }
    }

    pub fn next_random(&mut self) -> Option<usize> {
        let number_of_names: i32 = self.items.len() as i32;
        if number_of_names < 1 {
            return None;
        }
        Some(get_random_to(number_of_names) as usize)
    }

    pub fn next(&mut self) {
        let i = match self.state.selected() {
            Some(i) => {
                if i >= self.items.len() - 1 {
                    0
                } else {
                    i + 1
                }
            }
            None => 0,
        };
        self.state.select(Some(i));
    }

    pub fn previous(&mut self) {
        let i = match self.state.selected() {
            Some(i) => {
                if i == 0 {
                    self.items.len() - 1
                } else {
                    i - 1
                }
            }
            None => 0,
        };
        self.state.select(Some(i));
    }

    pub fn unselect(&mut self) {
        self.state.select(None);
    }

    pub fn remove(&mut self, index: usize) -> String {
        self.items.remove(index)
    }
}

use crate::app::App;
use crate::colors::ColorScheme;
use crate::helpers::ID;
use crate::render::{DrawOptions, Renderable, OUTLINE_THICKNESS};
use ezgui::{Color, Drawable, GeomBatch, GfxCtx, Line, Prerender, Text};
use geom::{Angle, ArrowCap, Distance, PolyLine, Polygon, Pt2D};
use map_model::{Map, TurnType};
use sim::{CarID, CarStatus, DrawCarInput, VehicleType};

const CAR_WIDTH: Distance = Distance::const_meters(1.75);

pub struct DrawCar {
    pub id: CarID,
    body: PolyLine,
    body_polygon: Polygon,
    zorder: isize,

    draw_default: Drawable,
}

impl DrawCar {
    pub fn new(input: DrawCarInput, map: &Map, prerender: &Prerender, cs: &ColorScheme) -> DrawCar {
        let mut draw_default = GeomBatch::new();

        // Wheels
        for side in vec![
            input.body.shift_right(CAR_WIDTH / 2.0).unwrap(),
            input.body.shift_left(CAR_WIDTH / 2.0).unwrap(),
        ] {
            let len = side.length();
            if len <= Distance::meters(2.0) {
                // The original body may be fine, but sometimes shifting drastically shortens the
                // length due to miter threshold chopping. Just give up on wheels in that case
                // instead of crashing.
                continue;
            }
            draw_default.push(
                cs.bike_frame,
                side.exact_slice(Distance::meters(0.5), Distance::meters(1.0))
                    .make_polygons(OUTLINE_THICKNESS / 2.0),
            );
            draw_default.push(
                cs.bike_frame,
                side.exact_slice(len - Distance::meters(2.0), len - Distance::meters(1.5))
                    .make_polygons(OUTLINE_THICKNESS / 2.0),
            );
        }

        let body_polygon = {
            let len = input.body.length();
            let front_corner = len - Distance::meters(1.0);
            let thick_line = input
                .body
                .exact_slice(Distance::ZERO, front_corner)
                .make_polygons(CAR_WIDTH);

            let (corner_pt, corner_angle) = input.body.dist_along(front_corner);
            let (tip_pt, tip_angle) = input.body.dist_along(len);
            let front = Polygon::new(&vec![
                corner_pt.project_away(CAR_WIDTH / 2.0, corner_angle.rotate_degs(90.0)),
                corner_pt.project_away(CAR_WIDTH / 2.0, corner_angle.rotate_degs(-90.0)),
                tip_pt.project_away(CAR_WIDTH / 4.0, tip_angle.rotate_degs(-90.0)),
                tip_pt.project_away(CAR_WIDTH / 4.0, tip_angle.rotate_degs(90.0)),
            ]);
            front.union(thick_line)
        };

        draw_default.push(zoomed_color_car(&input, cs), body_polygon.clone());
        if input.status == CarStatus::Parked {
            draw_default.append(
                GeomBatch::mapspace_svg(prerender, "../data/system/assets/map/parked_car.svg")
                    .scale(0.01)
                    .centered_on(input.body.middle()),
            );
        }

        {
            let arrow_len = 0.8 * CAR_WIDTH;
            let arrow_thickness = Distance::meters(0.5);

            if let Some(t) = input.waiting_for_turn {
                match map.get_t(t).turn_type {
                    TurnType::Left => {
                        let (pos, angle) = input
                            .body
                            .dist_along(input.body.length() - Distance::meters(2.5));

                        draw_default.push(
                            cs.turn_arrow,
                            PolyLine::new(vec![
                                pos.project_away(arrow_len / 2.0, angle.rotate_degs(90.0)),
                                pos.project_away(arrow_len / 2.0, angle.rotate_degs(-90.0)),
                            ])
                            .make_arrow(arrow_thickness, ArrowCap::Triangle)
                            .unwrap(),
                        );
                    }
                    TurnType::Right => {
                        let (pos, angle) = input
                            .body
                            .dist_along(input.body.length() - Distance::meters(2.5));

                        draw_default.push(
                            cs.turn_arrow,
                            PolyLine::new(vec![
                                pos.project_away(arrow_len / 2.0, angle.rotate_degs(-90.0)),
                                pos.project_away(arrow_len / 2.0, angle.rotate_degs(90.0)),
                            ])
                            .make_arrow(arrow_thickness, ArrowCap::Triangle)
                            .unwrap(),
                        );
                    }
                    TurnType::Straight | TurnType::LaneChangeLeft | TurnType::LaneChangeRight => {}
                    TurnType::Crosswalk | TurnType::SharedSidewalkCorner => unreachable!(),
                }

                // Always draw the brake light
                let (pos, angle) = input.body.dist_along(Distance::meters(0.5));
                // TODO rounded
                let window_length_gap = Distance::meters(0.2);
                let window_thickness = Distance::meters(0.3);
                draw_default.push(
                    cs.brake_light,
                    thick_line_from_angle(
                        window_thickness,
                        CAR_WIDTH - window_length_gap * 2.0,
                        pos.project_away(
                            CAR_WIDTH / 2.0 - window_length_gap,
                            angle.rotate_degs(-90.0),
                        ),
                        angle.rotate_degs(90.0),
                    ),
                );
            }
        }

        if let Some(line) = input.label {
            // TODO Would rotation make any sense? Or at least adjust position/size while turning.
            // Buses are a constant length, so hardcoding this is fine.
            draw_default.append(
                Text::from(Line(line).fg(cs.bus_label))
                    .render_to_batch(prerender)
                    .scale(0.07)
                    .centered_on(input.body.dist_along(Distance::meters(9.0)).0),
            );
        }

        DrawCar {
            id: input.id,
            body: input.body,
            body_polygon,
            zorder: input.on.get_zorder(map),
            draw_default: prerender.upload(draw_default),
        }
    }
}

impl Renderable for DrawCar {
    fn get_id(&self) -> ID {
        ID::Car(self.id)
    }

    fn draw(&self, g: &mut GfxCtx, _: &App, _: &DrawOptions) {
        g.redraw(&self.draw_default);
    }

    fn get_outline(&self, _: &Map) -> Polygon {
        self.body
            .to_thick_boundary(CAR_WIDTH, OUTLINE_THICKNESS)
            .unwrap_or_else(|| self.body_polygon.clone())
    }

    fn contains_pt(&self, pt: Pt2D, _: &Map) -> bool {
        self.body_polygon.contains_pt(pt)
    }

    fn get_zorder(&self) -> isize {
        self.zorder
    }
}

fn thick_line_from_angle(
    thickness: Distance,
    line_length: Distance,
    pt: Pt2D,
    angle: Angle,
) -> Polygon {
    let pt2 = pt.project_away(line_length, angle);
    // Shouldn't ever fail for a single line
    PolyLine::new(vec![pt, pt2]).make_polygons(thickness)
}

fn zoomed_color_car(input: &DrawCarInput, cs: &ColorScheme) -> Color {
    if input.id.1 == VehicleType::Bus {
        cs.bus_body
    } else {
        match input.status {
            CarStatus::Moving => cs.rotating_color_agents(input.id.0),
            CarStatus::Parked => cs.parked_car,
        }
    }
}

use kdtree::*;

enum PointsWereOnSide {
    Left,
    Right,
    Both,
}

struct PartitionPointHelper {
    points_were_on_side: PointsWereOnSide,
    index_of_splitter: usize,
}

fn partition_sliding_midpoint_helper<T: KdtreePointTrait>(
    vec: &mut [T],
    midpoint_value: f64,
    partition_on_dimension: usize,
) -> PartitionPointHelper {
    let mut closest_index = 0;
    let mut closest_distance = (vec[0].dims()[partition_on_dimension] - midpoint_value).abs();

    const HAS_POINTS_ON_LEFT_SIDE: i32 = 0b01;
    const HAS_POINTS_ON_RIGHT_SIDE: i32 = 0b10;
    const HAS_POINTS_ON_BOTH_SIDES: i32 = HAS_POINTS_ON_RIGHT_SIDE | HAS_POINTS_ON_LEFT_SIDE;
    let mut has_points_on_sides = 0;

    for i in 0..vec.len() {
        let p = vec.get(i).unwrap();
        if p.dims()[partition_on_dimension] <= midpoint_value {
            has_points_on_sides |= HAS_POINTS_ON_LEFT_SIDE;
        } else {
            has_points_on_sides |= HAS_POINTS_ON_RIGHT_SIDE;
        }

        let dist = (p.dims()[partition_on_dimension] - midpoint_value).abs();

        if dist < closest_distance {
            closest_distance = dist;
            closest_index = i;
        }
    }

    if has_points_on_sides != HAS_POINTS_ON_BOTH_SIDES {
        return PartitionPointHelper {
            index_of_splitter: closest_index,
            points_were_on_side: if has_points_on_sides == HAS_POINTS_ON_LEFT_SIDE {
                PointsWereOnSide::Left
            } else {
                PointsWereOnSide::Right
            },
        };
    }
    return PartitionPointHelper {
        index_of_splitter: closest_index,
        points_were_on_side: PointsWereOnSide::Both,
    };
}

pub fn partition_sliding_midpoint<T: KdtreePointTrait>(
    vec: &mut [T],
    midpoint_value: f64,
    partition_on_dimension: usize,
) -> usize {
    let vec_len = vec.len();
    debug_assert!(vec[0].dims().len() > partition_on_dimension);

    if vec.len() == 1 {
        return 0;
    }

    let partition_point_data =
        partition_sliding_midpoint_helper(vec, midpoint_value, partition_on_dimension);

    match partition_point_data.points_were_on_side {
        PointsWereOnSide::Left => {
            vec.swap(partition_point_data.index_of_splitter, vec_len - 1);
            vec_len - 1
        }
        PointsWereOnSide::Right => {
            vec.swap(partition_point_data.index_of_splitter, 0);
            0
        }
        PointsWereOnSide::Both => {
            let index_of_splitting_point = partition_kdtree(
                vec,
                partition_point_data.index_of_splitter,
                partition_on_dimension,
            );
            index_of_splitting_point
        }
    }
}

fn partition_kdtree<T: KdtreePointTrait>(
    vec: &mut [T],
    index_of_splitting_point: usize,
    partition_on_dimension: usize,
) -> usize {
    if vec.len() == 1 {
        return 0;
    }

    let pivot = vec[index_of_splitting_point].dims()[partition_on_dimension];
    let vec_len = vec.len();

    vec.swap(index_of_splitting_point, vec_len - 1);

    let mut left = 0usize;
    let mut right = vec.len() - 2;
    let mut last_succesful_swap = vec.len() - 1;

    //variant of Lomuto algo.
    loop {
        while left <= right && vec[left].dims()[partition_on_dimension] <= pivot {
            left += 1;
        }

        while right > left && vec[right].dims()[partition_on_dimension] > pivot {
            right -= 1;
        }

        if right > left {
            vec.swap(left, right);
            last_succesful_swap = right;

            left += 1;
            right -= 1;
        } else {
            break;
        }
    }

    if last_succesful_swap == vec_len - 1 && vec[right].dims()[partition_on_dimension] > pivot {
        vec.swap(right, last_succesful_swap);
        last_succesful_swap = right;
    } else if vec[left].dims()[partition_on_dimension] > pivot {
        vec.swap(left, vec_len - 1);
        last_succesful_swap = left;
    } else {
        vec.swap(last_succesful_swap, vec_len - 1);
    }

    last_succesful_swap
}

#[cfg(test)]
mod tests {
    use kdtree::test_common::*;
    use kdtree::*;

    use rand::distributions::{IndependentSample, Range};
    use rand::*;

    use super::partition_kdtree;
    use super::*;

    #[test]
    fn parition_kdtree_works() {
        let p1 = Point2WithId::new(0, 1., 4.);
        let p2 = Point2WithId::new(1, 2., 6.);
        let p3 = Point2WithId::new(2, 3., 8.);
        let p4 = Point2WithId::new(3, 0., 8.);
        let p5 = Point2WithId::new(4, -1., 8.);
        let p6 = Point2WithId::new(5, 3., 8.);
        let p7 = Point2WithId::new(6, 4., 8.);

        let vec = vec![p1, p2, p3, p4, p5, p6, p7];
        assert_eq!(1, partition_kdtree(&mut vec.clone(), 3, 0));

        assert_eq!(6, partition_kdtree(&mut vec.clone(), 6, 0));

        assert_eq!(0, partition_kdtree(&mut vec.clone(), 4, 0));

        assert_eq!(5, partition_kdtree(&mut vec.clone(), 2, 0));
    }

    quickcheck! {
        fn partition_kdtree_qc(xs: Vec<f64>) -> bool {
            let mut vec : Vec<Point1WithId> = vec![];

            for i in 0 .. xs.len() {
                let p = Point1WithId::new(i as i32, xs[i]);
                vec.push(p);
            }

            if xs.len() == 0 {
                return true;
            }
            let between = Range::new(0, xs.len());
            let mut rng = thread_rng();

            for _ in 0 .. 5 {
                let random_splitting_index = between.ind_sample(&mut rng);

                let mut vec = vec.clone();

                let index_of_splitting_point = partition_kdtree(&mut vec, random_splitting_index, 0);
                return assert_partition(&vec, index_of_splitting_point);
            }

            true
        }
    }

    #[test]
    fn partition_given_midpoint_exactly_in_between_points_returns_smaller_index() {
        let p1 = Point2WithId::new(1, 2., 4.);
        let p2 = Point2WithId::new(1, 4., 6.);
        let mut vec = vec![p1, p2];

        assert_eq!(0, partition_sliding_midpoint(&mut vec, 3., 0));
        assert_eq!(0, partition_sliding_midpoint(&mut vec, 5., 1));
    }

    #[test]
    fn partition_given_midpoint_which_has_all_points_on_one_side_slides_split_plane_and_returns_index_to_closest_element(
    ) {
        let p1 = Point2WithId::new(1, 2., 4.);
        let p2 = Point2WithId::new(2, 4., 6.);
        let p3 = Point2WithId::new(3, 3., 7.);
        let p4 = Point2WithId::new(4, 0., 8.);
        let mut vec = vec![p1, p2, p3];

        assert_eq!(0, partition_sliding_midpoint(&mut vec, 1.9, 0));
        assert_eq!(1, vec[0].id);
        assert_eq!(2, vec[1].id);
        assert_eq!(3, vec[2].id);

        let mut vec = vec![p1, p2, p3];
        assert_eq!(0, partition_sliding_midpoint(&mut vec, -5000., 0));
        assert_eq!(1, vec[0].id);
        assert_eq!(2, vec[1].id);
        assert_eq!(3, vec[2].id);

        let mut vec = vec![p1, p2, p3];
        assert_eq!(2, partition_sliding_midpoint(&mut vec, 10., 0));
        assert_eq!(1, vec[0].id);
        assert_eq!(3, vec[1].id);
        assert_eq!(2, vec[2].id);

        let mut vec = vec![p1, p2, p3];
        assert_eq!(2, partition_sliding_midpoint(&mut vec, 10., 1));
        assert_eq!(1, vec[0].id);
        assert_eq!(2, vec[1].id);
        assert_eq!(3, vec[2].id);

        let mut vec = vec![p1, p2, p3, p4];
        assert_eq!(0, partition_sliding_midpoint(&mut vec, -5000., 0));
        assert_eq!(4, vec[0].id);
        assert_eq!(2, vec[1].id);
        assert_eq!(3, vec[2].id);
        assert_eq!(1, vec[3].id);
    }

    fn assert_partition(v: &Vec<Point1WithId>, index_of_splitting_point: usize) -> bool {
        let pivot = v[index_of_splitting_point].dims()[0];

        for i in 0..index_of_splitting_point {
            if v[i].dims()[0] > pivot {
                return false;
            }
        }

        for i in index_of_splitting_point + 1..v.len() {
            if v[i].dims()[0] < pivot {
                return false;
            }
        }

        true
    }
}

use criterion::{black_box, criterion_group, criterion_main, Criterion};
use encoding_rs::WINDOWS_874;
use rand::seq::SliceRandom;

const ALL_THAI_CHARS: &str =
    "กขฃคฅฆงจฉชซฌญฎฏฐฑฒณดตถทธนบปผฝพฟภมยรฤลฦวศษสหฬอฮฯะัาำิีึืฺุู฿เแโใไๅๆ็่้๊๋์ํ๎๏๐๑๒๓๔๕๖๗๘๙๚๛";

fn prepare_input(len: usize) -> String {
    let mut characters: Vec<char> = (32..127).map(|i| std::char::from_u32(i).unwrap()).collect();
    characters.extend(ALL_THAI_CHARS.chars());
    let mut out = Vec::with_capacity(len);
    while out.len() < len {
        out.extend(characters.iter().copied());
    }
    out.truncate(len);
    let mut rng = &mut rand::thread_rng();
    out.as_mut_slice().shuffle(&mut rng);
    out.into_iter().collect()
}

pub fn criterion_benchmark(c: &mut Criterion) {
    let message = prepare_input(2_000_000);
    let encoded = tis620::encode(&message).unwrap();
    let encoded2 = WINDOWS_874.encode(black_box(&message)).0;
    assert_eq!(encoded.as_slice(), encoded2.as_ref());
    let decoded = tis620::decode(&encoded).unwrap();
    let decoded2 = WINDOWS_874.decode(&encoded).0;
    assert_eq!(decoded, decoded2);
    drop(encoded2);
    drop(decoded);
    drop(decoded2);
    c.bench_function("tis620::encode", |b| {
        b.iter(|| tis620::encode(black_box(&message)).unwrap())
    });
    c.bench_function("WINDOWS_874::encode", |b| {
        b.iter(|| WINDOWS_874.encode(black_box(&message)))
    });
    c.bench_function("tis620::decode", |b| {
        b.iter(|| tis620::decode(black_box(&encoded)).unwrap())
    });
    c.bench_function("WINDOWS_874::decode", |b| {
        b.iter(|| WINDOWS_874.decode(black_box(&encoded)))
    });
}

criterion_group!(benches, criterion_benchmark);
criterion_main!(benches);

