use std::iter::Once;

struct Solution;

impl Solution {
    // f(left, right) = max(f(left, mid) + f(mid, right) + nums[i] * nums[mid] * nums[j])
    pub fn max_coins(mut nums: Vec<i32>) -> i32 {
        let n = nums.len();
        let mut rec = vec![vec![0; n + 2]; n + 2];
        let val = (1..=1)
            .chain(nums.drain(..))
            .chain(1..=1)
            .collect::<Vec<i32>>();

        for i in (0..n).rev() {
            for j in (i + 2)..(n + 2) {
                for k in (i + 1)..j {
                    rec[i][j] = rec[i][j].max(val[i] * val[k] * val[j] + rec[i][k] + rec[k][j])
                }
            }
        }
        rec[0][n + 1]
    }
}

#[test]
fn leetcode312_t1() {
    let nums = vec![3, 1, 5, 8];
    assert_eq!(Solution::max_coins(nums), 167);
}

use num::complex::Complex;
use std::collections::{HashMap,HashSet};

type Location = Complex<i32>;

fn get_manhatan_distance(location_a: &Location, location_b: &Location) -> i32 {
    i32::abs(location_a.re - location_b.re) + i32::abs(location_a.im - location_b.im)
}

fn get_map_edges(locations: &Vec<Location>) -> (i32, i32, i32, i32) {
    (
        locations.iter().map(|l| l.re).min().unwrap(),
        locations.iter().map(|l| l.re).max().unwrap(),
        locations.iter().map(|l| l.im).min().unwrap(),
        locations.iter().map(|l| l.im).max().unwrap(),
    )
}

fn find_closest_location(map_location: &Location, locations: &Vec<Location>) -> Option<usize> {
    let mut closest = None;
    let mut closest_distance = i32::MAX;
    for (index, location) in locations.iter().enumerate() {
        let distance = get_manhatan_distance(&map_location, location);
        if distance < closest_distance {
            closest = Some(index);
            closest_distance = distance;
        } else if distance == closest_distance {
            closest = None;
        }
    }
    closest
}

fn part1(locations: &Vec<Location>) -> usize {
    let (start_x, end_x, start_y, end_y) = get_map_edges(locations);
    let mut map_locations: HashMap<Location, Option<usize>> = HashMap::new();
    let mut location_counts: Vec<usize> = (0..locations.len()).map(|_| 0).collect();
    for map_location_x in start_x..(end_x + 1) {
        for map_location_y in start_y..(end_y + 1) {
            let map_location = Complex::new(map_location_x, map_location_y);
            let closest = find_closest_location(&map_location, locations);
            *map_locations.entry(map_location).or_insert(None) = closest;
            if let Some(location) = closest {
                location_counts[location] += 1;
            }
        }
    }
    let mut edge_locations = HashSet::new();
    for y in start_y..end_y {
        edge_locations.insert(map_locations[&Complex::new(start_x, y)]);
        edge_locations.insert(map_locations[&Complex::new(end_x, y)]);
    }
    for x in start_x..end_x {
        edge_locations.insert(map_locations[&Complex::new(x, start_y)]);
        edge_locations.insert(map_locations[&Complex::new(x, end_y)]);
    }
    location_counts
        .into_iter()
        .enumerate()
        .filter(|(index, _)| !edge_locations.contains(&Some(*index)))
        .map(|pair| pair.1)
        .max()
        .unwrap()
}

const MAX_DISTANCE: i32 = 10_000;
fn part2(locations: &Vec<Location>) -> usize {
    let (start_x, end_x, start_y, end_y) = get_map_edges(locations);
    let mut valid_locations_count = 0;
    for map_location_x in start_x..(end_x + 1) {
        for map_location_y in start_y..(end_y + 1) {
            let map_location = Complex::new(map_location_x, map_location_y);
            let total_distances: i32 = locations
                .iter()
                .map(|location| get_manhatan_distance(&map_location, location))
                .sum();
            if total_distances < MAX_DISTANCE {
                valid_locations_count += 1;
            }
        }
    }
    valid_locations_count
}

fn solve(locations: &Vec<Location>) -> (usize, usize) {
    (part1(locations), part2(locations))
}

fn get_input(file_path: &String) -> Vec<Location> {
    std::fs::read_to_string(file_path)
        .expect("Error reading input file!")
        .lines()
        .map(|line| {
            let mut split = line.split(',');
            Complex::new(
                split.next().unwrap().trim().parse().unwrap(),
                split.next().unwrap().trim().parse().unwrap(),
            )
        })
        .collect()
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 2 {
        panic!("Please, add input file path as parameter");
    }
    let now = std::time::Instant::now();
    let (part1_result, part2_result) = solve(&get_input(&args[1]));
    let end = now.elapsed().as_secs_f32();
    println!("P1: {}", part1_result);
    println!("P2: {}", part2_result);
    println!();
    println!("Time: {:7}", end);
}

use crate::eat_type;
use crate::parse_expr;
use crate::parse_ident_type;
use crate::parser::Parser;
use crate::ParserError;

use whistle_ast::IdentImport;
use whistle_ast::IdentTyped;
use whistle_ast::IdentVal;
use whistle_ast::Primary;

use whistle_common::Keyword;
use whistle_common::Punc;
use whistle_common::Token;

pub fn parse_ident(parser: &mut Parser) -> Result<String, ParserError> {
  eat_type!(parser, Token::Ident)
}

pub fn parse_ident_typed(parser: &mut Parser) -> Result<IdentTyped, ParserError> {
  let ident = parse_ident(parser)?;
  parser.eat_tok(Token::Punc(Punc::Colon))?;
  let type_ident = parse_ident_type(parser)?;
  Ok(IdentTyped { ident, type_ident })
}

pub fn parse_ident_import(parser: &mut Parser) -> Result<IdentImport, ParserError> {
  let ident = parse_ident(parser)?;
  if parser.eat_tok(Token::Keyword(Keyword::As)).is_ok() {
    let as_ident = parse_ident(parser)?;
    return Ok(IdentImport {
      ident,
      as_ident: Some(as_ident),
    });
  }
  Ok(IdentImport {
    ident,
    as_ident: None,
  })
}

pub fn parse_ident_val(parser: &mut Parser, ident: String) -> Result<Primary, ParserError> {
  parse_ident(parser)?;
  let mut prim = Vec::new();
  while parser.within() {
    prim.push(match parser.peek()? {
      Token::Punc(Punc::Dot) => parse_selector(parser)?,
      Token::Punc(Punc::LeftParen) => parse_arguments(parser)?,
      _ => break,
    })
  }
  Ok(Primary::IdentVal { ident, prim })
}

pub fn parse_selector(parser: &mut Parser) -> Result<IdentVal, ParserError> {
  parser.eat_tok(Token::Punc(Punc::Dot))?;
  let ident = parse_ident(parser)?;
  Ok(IdentVal::Selector(ident))
}

pub fn parse_arguments(parser: &mut Parser) -> Result<IdentVal, ParserError> {
  parser.eat_tok(Token::Punc(Punc::LeftParen))?;
  let args = parser.eat_repeat(
    parse_expr,
    Some(Token::Punc(Punc::Comma)),
    Token::Punc(Punc::RightParen),
  )?;
  parser.eat_tok(Token::Punc(Punc::RightParen))?;
  Ok(IdentVal::Arguments(args))
}

use crate::{Animatable, Animation, BoundedAnimation};
use std::time::Duration;

/// An animation that never changes.
///
/// This likely isn't very useful, besides the potential as a default. Its main
/// purpose is to demonstrate the properties of the most fundamental animation
/// possible.
#[derive(Debug)]
#[repr(transparent)]
pub struct Constant<V>
where
    V: Animatable,
{
    value: V,
}

impl<V> Animation<V> for Constant<V>
where
    V: Animatable,
{
    fn sample(&self, _elapsed: Duration) -> V {
        self.value
    }
}

impl<V> BoundedAnimation<V> for Constant<V>
where
    V: Animatable,
{
    fn duration(&self) -> Duration {
        // The `duration` is the period over which the animation changes, and
        // since `Constant` never changes, this is just zero.
        Duration::ZERO
    }
}

impl<V> Constant<V>
where
    V: Animatable,
{
    pub fn new(value: V) -> Self {
        Self { value }
    }
}

impl<V> Default for Constant<V>
where
    V: Animatable + Default,
{
    fn default() -> Self {
        Self::new(V::default())
    }
}

