//! Transforms which fuse loops to reduce memory movement and prevent unncessary
//! traversals of data.

use ast::*;
use ast::ExprKind::*;
use ast::Type::*;
use ast::BuilderKind::*;
use ast::LiteralKind::*;
use error::*;
use annotations::*;
use exprs;

use super::inliner::inline_apply;

use util::SymbolGenerator;

/// Fuses loops where one for loop takes another as it's input, which prevents intermediate results
/// from being materialized.
pub struct VerticalLoopFusion;

/// Fuses for loops over the same vector in a zip into a single for loop which produces a vector of
/// structs directly.
///
/// Some examples:
///
/// for(zip(
///     result(for(a, appender, ...))
///     result(for(a, appender, ...))
/// ), ...)
///
/// will become for(result(for(a, ...))) where the nested for will produce a vector of structs with
/// two elements.
///
/// Caveats:
///     - Like all Zip-based transforms, this function currently assumes that the output of each
///     expression in the Zip is the same length.
///
pub fn fuse_loops_horizontal(expr: &mut Expr<Type>) {
    expr.transform(&mut |ref mut expr| {
        let mut sym_gen = SymbolGenerator::from_expression(expr);
        if let For{iters: ref all_iters, builder: ref outer_bldr, func: ref outer_func} = expr.kind {
            if all_iters.len() > 1 {
                // Vector of tuples containing the params and expressions of functions in nested lambdas.
                let mut lambdas = vec![];
                let mut common_data = None;
                // Used to check if the same rows of each output are touched by the outer for.
                let first_iter = (&all_iters[0].start, &all_iters[0].end, &all_iters[0].stride);
                // First, check if all the lambdas are over the same vector and have a pattern we can merge.
                // Below, for each iterator in the for loop, we checked if each nested for loop is
                // over the same vector and has the same Iter parameters (i.e., same start, end, stride).
                if all_iters.iter().all(|ref iter| {
                    if (&iter.start, &iter.end, &iter.stride) == first_iter {
                        // Make sure each nested for loop follows the ``result(for(a, appender, ...)) pattern.
                        if let Res{builder: ref res_bldr} = iter.data.kind {
                            if let For{iters: ref iters2, builder: ref bldr2, func: ref lambda} = res_bldr.kind {
                                if common_data.is_none() {
                                    common_data = Some(iters2.clone());
                                }
                                if iters2 == common_data.as_ref().unwrap() {
                                    if let NewBuilder(_) = bldr2.kind {
                                        if let Builder(ref kind, _) = bldr2.ty {
                                            if let Appender(_) = *kind {
                                                if let Lambda{params: ref args, ref body} = lambda.kind {
                                                    if let Merge{ref builder, ref value} = body.kind {
                                                        if let Ident(ref n) = builder.kind {
                                                            if *n == args[0].name {
                                                                // Save the arguments and expressions for the function so
                                                                // they can be used for fusion later.
                                                                lambdas.push((args.clone(), value.clone()));
                                                                return true
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                    // The pattern doesn't match for some Iter -- abort the transform.
                    return false
                }) {
                    // All Iters are over the same range and same vector, with a pattern we can
                    // transform. Produce the new expression by zipping the functions of each
                    // nested for into a single merge into a struct.

                    // Zip the expressions to create an appender whose merge (value) type is a struct.
                    let merge_type = Struct(lambdas.iter().map(|ref e| e.1.ty.clone()).collect::<Vec<_>>());
                    // TODO(Deepak): Fix this to something meaningful.
                    let builder_type = Builder(Appender(Box::new(merge_type.clone())), Annotations::new());
                    // The element type remains unchanged.
                    let func_elem_type = lambdas[0].0[2].ty.clone();

                    // Parameters for the new fused function. Symbols names are generated using symbol
                    // names for the builder and element from an existing function.
                    let new_params = vec![
                        Parameter{ty: builder_type.clone(), name: sym_gen.new_symbol(&lambdas[0].0[0].name.name)},
                        Parameter{ty: Scalar(ScalarKind::I64), name: sym_gen.new_symbol(&lambdas[0].0[1].name.name)},
                        Parameter{ty: func_elem_type.clone(), name: sym_gen.new_symbol(&lambdas[0].0[2].name.name)},
                    ];

                    // Generate Ident expressions for the new symbols and substitute them in the
                    // functions' merge expressions.
                    let new_bldr_expr = Expr {
                        ty: builder_type.clone(),
                        kind: Ident(new_params[0].name.clone()),
                        annotations: Annotations::new(),
                    };
                    let new_index_expr = Expr {
                        ty: Scalar(ScalarKind::I64),
                        kind: Ident(new_params[1].name.clone()),
                        annotations: Annotations::new(),
                    };
                    let new_elem_expr = Expr {
                        ty: func_elem_type.clone(),
                        kind: Ident(new_params[2].name.clone()),
                        annotations: Annotations::new(),
                    };
                    for &mut (ref mut args, ref mut expr) in lambdas.iter_mut() {
                        expr.substitute(&args[0].name, &new_bldr_expr);
                        expr.substitute(&args[1].name, &new_index_expr);
                        expr.substitute(&args[2].name, &new_elem_expr);
                    }

                    // Build up the new expression. The new expression merges structs into an
                    // appender, where each struct field is an expression which was merged into an
                    // appender in one of the original functions. For example, if there were two
                    // zipped fors in the original expression with lambdas |b1,e1| merge(b1,
                    // e1+1) and |b2,e2| merge(b2, e2+2), the new expression would be merge(b,
                    // {e+1,e+2}) into a new builder b of type appender[{i32,i32}]. e1, e2, and e
                    // refer to the same element in the expressions above since we check to ensure
                    // each zipped for is over the same input data.
                    let new_merge_expr = Expr{
                        ty: builder_type.clone(),
                        kind: Merge{
                            builder: Box::new(new_bldr_expr),
                            value: Box::new(Expr{
                                ty: merge_type.clone(),
                                kind: MakeStruct{elems: lambdas.iter().map(|ref lambda| *lambda.1.clone()).collect::<Vec<_>>()},
                                annotations: Annotations::new(),
                            })
                        },
                        annotations: Annotations::new(),
                    };
                    let new_func = Expr{
                        ty: Function(new_params.iter().map(|ref p| p.ty.clone()).collect::<Vec<_>>(), Box::new(builder_type.clone())),
                        kind: Lambda{params: new_params, body: Box::new(new_merge_expr)},
                        annotations: Annotations::new(),
                    };
                    let new_iter_expr = Expr{
                        ty: Vector(Box::new(merge_type.clone())),
                        kind: Res{builder: Box::new(Expr{
                            ty: builder_type.clone(),
                            kind: For{iters: common_data.unwrap(), builder: Box::new(Expr{ty: builder_type.clone(), kind: NewBuilder(None), annotations: Annotations::new()}), func: Box::new(new_func)},
                            annotations: Annotations::new(),
                        })},
                        annotations: Annotations::new(),
                    };

                    // TODO(shoumik): Any way to avoid the clones here?
                    return Some(Expr{
                        ty: expr.ty.clone(),
                        kind: For{iters: vec![Iter{
                            data: Box::new(new_iter_expr),
                            start: all_iters[0].start.clone(),
                            end: all_iters[0].end.clone(),
                            stride: all_iters[0].stride.clone(),
                            kind: all_iters[0].kind.clone(),
                        }], builder: outer_bldr.clone(), func: outer_func.clone()},
                        annotations: Annotations::new(),
                    });
                }
            }
        }
        None
    });
}

/// Fuses loops where one for loop takes another as it's input, which prevents intermediate results
/// from being materialized.
pub fn fuse_loops_vertical(expr: &mut Expr<Type>) {
    expr.transform_and_continue_res(&mut |ref mut expr| {
        let mut sym_gen = SymbolGenerator::from_expression(expr);
        if let For { iters: ref all_iters, builder: ref bldr1, func: ref nested } = expr.kind {
            if all_iters.len() == 1 {
                let ref iter1 = all_iters[0];
                if let Res { builder: ref res_bldr } = iter1.data.kind {
                    if let For { iters: ref iters2, builder: ref bldr2, func: ref lambda, } = res_bldr.kind {
                        if iters2.iter().all(|ref i| consumes_all(&i)) {
                            if let NewBuilder(_) = bldr2.kind {
                                if let Builder(ref kind, _) = bldr2.ty {
                                    if let Appender(_) = *kind {
                                        let mut e = exprs::for_expr(iters2.clone(), *bldr1.clone(), replace_builder(lambda, nested, &mut sym_gen)?, false)?;
                                        e.annotations = expr.annotations.clone();
                                        return Ok((Some(e), true));
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        Ok((None, true))
    });
}

/// Given an iterator, returns whether the iterator consumes every element of its data vector.
fn consumes_all(iter: &Iter<Type>) -> bool {
    if let &Iter {
               start: None,
               end: None,
               stride: None,
               ..
           } = iter {
        return true;
    } else if let &Iter {
                      ref data,
                      start: Some(ref start),
                      end: Some(ref end),
                      stride: Some(ref stride),
                      ..
                  } = iter {
        // Checks if the stride is 1 and an entire vector represented by a symbol is consumed.
        if let (&Literal(I64Literal(1)),
                &Literal(I64Literal(0)),
                &Ident(ref name),
                &Length { data: ref v }) = (&stride.kind, &start.kind, &data.kind, &end.kind) {
            if let Ident(ref vsym) = v.kind {
                return vsym == name;
            }
        }
        // Checks if an entire vector literal is consumed.
        if let (&Literal(I64Literal(1)), &Literal(I64Literal(0)), &MakeVector { ref elems }) =
            (&stride.kind, &start.kind, &data.kind) {
            let num_elems = elems.len() as i64;
            if let Literal(I64Literal(x)) = end.kind {
                return num_elems == x;
            }
        }
    }
    false
}

/// Given a lambda which takes a builder and an argument, returns a new function which takes a new
/// builder type and calls nested on the values it would've merged into its old builder. This
/// allows us to "compose" merge functions and avoid creating intermediate results.
fn replace_builder(lambda: &Expr<Type>,
                   nested: &Expr<Type>,
                   sym_gen: &mut SymbolGenerator)
                   -> WeldResult<Expr<Type>> {

    // Tests whether an identifier and symbol refer to the same value by
    // comparing the symbols.
    fn same_iden(a: &ExprKind<Type>, b: &Symbol) -> bool {
        if let Ident(ref symbol) = *a {
            symbol == b
        } else {
            false
        }
    }

    if let Lambda { params: ref args, ref body } = lambda.kind {
        if let Lambda { params: ref nested_args, .. } = nested.kind {
            let mut new_body = *body.clone();
            let ref old_bldr = args[0];
            let ref old_index = args[1];
            let ref old_arg = args[2];
            let new_bldr_sym = sym_gen.new_symbol(&old_bldr.name.name);
            let new_index_sym = sym_gen.new_symbol(&old_index.name.name);
            let new_bldr = exprs::ident_expr(new_bldr_sym.clone(), nested_args[0].ty.clone())?;
            let new_index = exprs::ident_expr(new_index_sym.clone(), nested_args[1].ty.clone())?;

            // Fix expressions to use the new builder.
            new_body.transform_and_continue_res(&mut |ref mut e| match e.kind {
                Merge { ref builder, ref value } if same_iden(&(*builder).kind, &old_bldr.name) => {
                    let params: Vec<Expr<Type>> = vec![new_bldr.clone(), new_index.clone(), *value.clone()];
                    let mut expr = exprs::apply_expr(nested.clone(), params)?;
                    inline_apply(&mut expr);
                    Ok((Some(expr), true))
                }
                For { iters: ref data, builder: ref bldr, ref func } if same_iden(&(*bldr).kind, &old_bldr.name) => {
                    let expr = exprs::for_expr(data.clone(), new_bldr.clone(), replace_builder(func, nested, sym_gen)?, false)?;
                    Ok((Some(expr), false))
                }
                Ident(ref mut symbol) if *symbol == old_bldr.name => {
                    Ok((Some(new_bldr.clone()), false))
                }
                Ident(ref mut symbol) if *symbol == old_index.name => {
                    Ok((Some(new_index.clone()), false))
                }
                _ => Ok((None, true)),
            });

            // Fix types to make sure the return type propagates through all subexpressions.
            match_types(&new_bldr.ty, &mut new_body);

            let new_params = vec![Parameter {
                                      ty: new_bldr.ty.clone(),
                                      name: new_bldr_sym.clone(),
                                  },
                                  Parameter {
                                      ty: Scalar(ScalarKind::I64),
                                      name: new_index_sym.clone(),
                                  },
                                  Parameter {
                                      ty: old_arg.ty.clone(),
                                      name: old_arg.name.clone(),
                                  }];
            return exprs::lambda_expr(new_params, new_body);
        }
    }
    return weld_err!("Inconsistency in replace_builder");
}

/// Given a root type, forces each expression to return that type. TODO For now, only supporting
/// expressions which can be builders. We might want to factor this out to be somewhere else.
fn match_types(root_ty: &Type, expr: &mut Expr<Type>) {
    expr.ty = root_ty.clone();
    match expr.kind {
        If { ref mut on_true, ref mut on_false, ..} => {
            match_types(root_ty, on_true);
            match_types(root_ty, on_false);
        }
        Select { ref mut on_true, ref mut on_false, ..} => {
            match_types(root_ty, on_true);
            match_types(root_ty, on_false);
        }
        Let { ref mut body, ..} => {
            match_types(root_ty, body);
        }
        _ => {}
    };
}

//! This module is a hack to get around the lack of the 
//! `__truncdfsf2` function in the `compiler_builtins` crate.
//! See this: <https://github.com/rust-lang-nursery/compiler-builtins/pull/262>
//!
//! This code was taken from this commit from above-linked pull request to the compiler_builtins crate:
//! <https://github.com/rust-lang-nursery/compiler-builtins/commit/baab4fd89cdd945e46fed31166e5dcad7224ed87>
//! 
//! Unfortunately, it was later reverted since it caused failures on ARM, so I don't know how else to resolve this. 
//! 
//! ----------------------------------------------------------------------------------
//! 
//! In addition, PR #358 caused various compiler_builtins traits to be private, so we cannot use them any more. 
//! See here: <https://github.com/rust-lang/compiler-builtins/pull/358> 
//! 
//! Thus, we copy the contents and implementation of the Float, Int, and CastInto traits here
//! in the modules at the end of this file. This isn't a great solution, but it's easy, and temporary anyways. 
//! 

use self::float::Float;
use self::int::{CastInto, Int};

/// Generic conversion from a wider to a narrower IEEE-754 floating-point type
#[allow(dead_code)]
fn truncate<F: Float, R: Float>(a: F) -> R
where
    F::Int: CastInto<u64>,
    u64: CastInto<F::Int>,
    F::Int: CastInto<u32>,
    u32: CastInto<F::Int>,
    u32: CastInto<R::Int>,
    R::Int: CastInto<u32>,
    F::Int: CastInto<R::Int>,
{
    let src_one = F::Int::ONE;
    let src_bits = F::BITS;
    let src_sign_bits = F::SIGNIFICAND_BITS;
    let src_exp_bias = F::EXPONENT_BIAS;
    let src_min_normal = F::IMPLICIT_BIT;
    let src_infinity = F::EXPONENT_MASK;
    let src_sign_mask = F::SIGN_MASK as F::Int;
    let src_abs_mask = src_sign_mask - src_one;
    let src_qnan = F::SIGNIFICAND_MASK;
    let src_nan_code = src_qnan - src_one;

    let dst_bits = R::BITS;
    let dst_sign_bits = R::SIGNIFICAND_BITS;
    let dst_inf_exp = R::EXPONENT_MAX;
    let dst_exp_bias = R::EXPONENT_BIAS;

    let dst_zero = R::Int::ZERO;
    let dst_one = R::Int::ONE;
    let dst_qnan = R::SIGNIFICAND_MASK;
    let dst_nan_code = dst_qnan - dst_one;

    let round_mask = (src_one << src_sign_bits - dst_sign_bits) - src_one;
    let half = src_one << src_sign_bits - dst_sign_bits - 1;
    let underflow_exp = src_exp_bias + 1 - dst_exp_bias;
    let overflow_exp = src_exp_bias + dst_inf_exp - dst_exp_bias;
    let underflow: F::Int = underflow_exp.cast(); // << src_sign_bits;
    let overflow: F::Int = overflow_exp.cast(); //<< src_sign_bits;

    let a_abs = a.repr() & src_abs_mask;
    let sign = a.repr() & src_sign_mask;
    let mut abs_result: R::Int;

    let src_underflow = underflow << src_sign_bits;
    let src_overflow = overflow << src_sign_bits;

    if a_abs.wrapping_sub(src_underflow) < a_abs.wrapping_sub(src_overflow) {
        // The exponent of a is within the range of normal numbers
        let bias_delta: R::Int = (src_exp_bias - dst_exp_bias).cast();
        abs_result = a_abs.cast();
        abs_result = abs_result >> src_sign_bits - dst_sign_bits;
        abs_result = abs_result - bias_delta.wrapping_shl(dst_sign_bits);
        let round_bits: F::Int = a_abs & round_mask;
        abs_result += if round_bits > half {
            dst_one
        } else {
            abs_result & dst_one
        };
    } else if a_abs > src_infinity {
        // a is NaN.
        // Conjure the result by beginning with infinity, setting the qNaN
        // bit and inserting the (truncated) trailing NaN field
        let nan_result: R::Int = (a_abs & src_nan_code).cast();
        abs_result = dst_inf_exp.cast();
        abs_result = abs_result.wrapping_shl(dst_sign_bits);
        abs_result |= dst_qnan;
        abs_result |= (nan_result >> (src_sign_bits - dst_sign_bits)) & dst_nan_code;
    } else if a_abs >= src_overflow {
        // a overflows to infinity.
        abs_result = dst_inf_exp.cast();
        abs_result = abs_result.wrapping_shl(dst_sign_bits);
    } else {
        // a underflows on conversion to the destination type or is an exact
        // zero. The result may be a denormal or zero. Extract the exponent
        // to get the shift amount for the denormalization.
        let a_exp = a_abs >> src_sign_bits;
        let mut shift: u32 = a_exp.cast();
        shift = src_exp_bias - dst_exp_bias - shift + 1;

        let significand = (a.repr() & src_sign_mask) | src_min_normal;
        if shift > src_sign_bits {
            abs_result = dst_zero;
        } else {
            let sticky = significand << src_bits - shift;
            let mut denormalized_significand: R::Int = significand.cast();
            let sticky_shift: u32 = sticky.cast();
            denormalized_significand = denormalized_significand >> (shift | sticky_shift);
            abs_result = denormalized_significand >> src_sign_bits - dst_sign_bits;
            let round_bits = denormalized_significand & round_mask.cast();
            if round_bits > half.cast() {
                abs_result += dst_one; // Round to nearest
            } else if round_bits == half.cast() {
                abs_result += abs_result & dst_one; // Ties to even
            }
        }
    }
    // Finally apply the sign bit
    let s = sign >> src_bits - dst_bits;
    R::from_repr(abs_result | s.cast())
}

#[no_mangle]
pub extern "C" fn  __truncdfsf2(a: f64) -> f32 {
    truncate(a)
}

#[cfg(target_arch = "arm")]
#[no_mangle]
pub extern "C" fn  __truncdfsf2vfp(a: f64) -> f32 {
    a as f32
}


/// This module is taken directly from `compiler_builtins/src/float/mod.rs`.
mod float {
    use core::mem;
    use core::ops;

    use super::int::Int;

    /// Trait for some basic operations on floats
    pub(crate) trait Float:
        Copy
        + PartialEq
        + PartialOrd
        + ops::AddAssign
        + ops::MulAssign
        + ops::Add<Output = Self>
        + ops::Sub<Output = Self>
        + ops::Div<Output = Self>
        + ops::Rem<Output = Self>
    {
        /// A uint of the same with as the float
        type Int: Int;

        /// A int of the same with as the float
        type SignedInt: Int;

        const ZERO: Self;
        const ONE: Self;

        /// The bitwidth of the float type
        const BITS: u32;

        /// The bitwidth of the significand
        const SIGNIFICAND_BITS: u32;

        /// The bitwidth of the exponent
        const EXPONENT_BITS: u32 = Self::BITS - Self::SIGNIFICAND_BITS - 1;

        /// The maximum value of the exponent
        const EXPONENT_MAX: u32 = (1 << Self::EXPONENT_BITS) - 1;

        /// The exponent bias value
        const EXPONENT_BIAS: u32 = Self::EXPONENT_MAX >> 1;

        /// A mask for the sign bit
        const SIGN_MASK: Self::Int;

        /// A mask for the significand
        const SIGNIFICAND_MASK: Self::Int;

        // The implicit bit of the float format
        const IMPLICIT_BIT: Self::Int;

        /// A mask for the exponent
        const EXPONENT_MASK: Self::Int;

        /// Returns `self` transmuted to `Self::Int`
        fn repr(self) -> Self::Int;

        /// Returns `self` transmuted to `Self::SignedInt`
        fn signed_repr(self) -> Self::SignedInt;

        #[cfg(test)]
        /// Checks if two floats have the same bit representation. *Except* for NaNs! NaN can be
        /// represented in multiple different ways. This method returns `true` if two NaNs are
        /// compared.
        fn eq_repr(self, rhs: Self) -> bool;

        /// Returns a `Self::Int` transmuted back to `Self`
        fn from_repr(a: Self::Int) -> Self;

        /// Constructs a `Self` from its parts. Inputs are treated as bits and shifted into position.
        fn from_parts(sign: bool, exponent: Self::Int, significand: Self::Int) -> Self;

        /// Returns (normalized exponent, normalized significand)
        fn normalize(significand: Self::Int) -> (i32, Self::Int);
    }

    // Some of this can be removed if RFC Issue #1424 is resolved
    // https://github.com/rust-lang/rfcs/issues/1424
    macro_rules! float_impl {
        ($ty:ident, $ity:ident, $sity:ident, $bits:expr, $significand_bits:expr) => {
            impl Float for $ty {
                type Int = $ity;
                type SignedInt = $sity;
                const ZERO: Self = 0.0;
                const ONE: Self = 1.0;

                const BITS: u32 = $bits;
                const SIGNIFICAND_BITS: u32 = $significand_bits;

                const SIGN_MASK: Self::Int = 1 << (Self::BITS - 1);
                const SIGNIFICAND_MASK: Self::Int = (1 << Self::SIGNIFICAND_BITS) - 1;
                const IMPLICIT_BIT: Self::Int = 1 << Self::SIGNIFICAND_BITS;
                const EXPONENT_MASK: Self::Int = !(Self::SIGN_MASK | Self::SIGNIFICAND_MASK);

                fn repr(self) -> Self::Int {
                    unsafe
                     { mem::transmute(self) }
                }
                fn signed_repr(self) -> Self::SignedInt {
                    unsafe { mem::transmute(self) }
                }
                #[cfg(test)]
                fn eq_repr(self, rhs: Self) -> bool {
                    if self.is_nan() && rhs.is_nan() {
                        true
                    } else {
                        self.repr() == rhs.repr()
                    }
                }
                fn from_repr(a: Self::Int) -> Self {
                    unsafe { mem::transmute(a) }
                }
                fn from_parts(sign: bool, exponent: Self::Int, significand: Self::Int) -> Self {
                    Self::from_repr(
                        ((sign as Self::Int) << (Self::BITS - 1))
                            | ((exponent << Self::SIGNIFICAND_BITS) & Self::EXPONENT_MASK)
                            | (significand & Self::SIGNIFICAND_MASK),
                    )
                }
                fn normalize(significand: Self::Int) -> (i32, Self::Int) {
                    let shift = significand
                        .leading_zeros()
                        .wrapping_sub((Self::Int::ONE << Self::SIGNIFICAND_BITS).leading_zeros());
                    (
                        1i32.wrapping_sub(shift as i32),
                        significand << shift as Self::Int,
                    )
                }
            }
        };
    }

    float_impl!(f32, u32, i32, 32, 23);
    float_impl!(f64, u64, i64, 64, 52);
}


/// This module is taken directly from `compiler_builtins/src/in/mod.rs`.
mod int {
    use core::ops;

    /// Trait for some basic operations on integers
    pub(crate) trait Int:
        Copy
        + PartialEq
        + PartialOrd
        + ops::AddAssign
        + ops::BitAndAssign
        + ops::BitOrAssign
        + ops::ShlAssign<i32>
        + ops::ShrAssign<u32>
        + ops::Add<Output = Self>
        + ops::Sub<Output = Self>
        + ops::Div<Output = Self>
        + ops::Shl<u32, Output = Self>
        + ops::Shr<u32, Output = Self>
        + ops::BitOr<Output = Self>
        + ops::BitXor<Output = Self>
        + ops::BitAnd<Output = Self>
        + ops::Not<Output = Self>
    {
        /// Type with the same width but other signedness
        type OtherSign: Int;
        /// Unsigned version of Self
        type UnsignedInt: Int;

        /// The bitwidth of the int type
        const BITS: u32;

        const ZERO: Self;
        const ONE: Self;

        /// Extracts the sign from self and returns a tuple.
        ///
        /// # Examples
        ///
        /// ```rust,ignore
        /// let i = -25_i32;
        /// let (sign, u) = i.extract_sign();
        /// assert_eq!(sign, true);
        /// assert_eq!(u, 25_u32);
        /// ```
        fn extract_sign(self) -> (bool, Self::UnsignedInt);

        fn unsigned(self) -> Self::UnsignedInt;
        fn from_unsigned(unsigned: Self::UnsignedInt) -> Self;

        fn from_bool(b: bool) -> Self;

        // copied from primitive integers, but put in a trait
        fn max_value() -> Self;
        fn min_value() -> Self;
        fn wrapping_add(self, other: Self) -> Self;
        fn wrapping_mul(self, other: Self) -> Self;
        fn wrapping_sub(self, other: Self) -> Self;
        fn wrapping_shl(self, other: u32) -> Self;
        fn overflowing_add(self, other: Self) -> (Self, bool);
        fn aborting_div(self, other: Self) -> Self;
        fn aborting_rem(self, other: Self) -> Self;
        fn leading_zeros(self) -> u32;
    }

    macro_rules! int_impl_common {
        ($ty:ty, $bits:expr) => {
            const BITS: u32 = $bits;

            const ZERO: Self = 0;
            const ONE: Self = 1;

            fn from_bool(b: bool) -> Self {
                b as $ty
            }

            fn max_value() -> Self {
                <Self>::max_value()
            }

            fn min_value() -> Self {
                <Self>::min_value()
            }

            fn wrapping_add(self, other: Self) -> Self {
                <Self>::wrapping_add(self, other)
            }

            fn wrapping_mul(self, other: Self) -> Self {
                <Self>::wrapping_mul(self, other)
            }

            fn wrapping_sub(self, other: Self) -> Self {
                <Self>::wrapping_sub(self, other)
            }

            fn wrapping_shl(self, other: u32) -> Self {
                <Self>::wrapping_shl(self, other)
            }

            fn overflowing_add(self, other: Self) -> (Self, bool) {
                <Self>::overflowing_add(self, other)
            }

            fn aborting_div(self, other: Self) -> Self {
                <Self>::checked_div(self, other).unwrap()
            }

            fn aborting_rem(self, other: Self) -> Self {
                <Self>::checked_rem(self, other).unwrap()
            }

            fn leading_zeros(self) -> u32 {
                <Self>::leading_zeros(self)
            }
        };
    }

    macro_rules! int_impl {
        ($ity:ty, $uty:ty, $bits:expr) => {
            impl Int for $uty {
                type OtherSign = $ity;
                type UnsignedInt = $uty;

                fn extract_sign(self) -> (bool, $uty) {
                    (false, self)
                }

                fn unsigned(self) -> $uty {
                    self
                }

                fn from_unsigned(me: $uty) -> Self {
                    me
                }

                int_impl_common!($uty, $bits);
            }

            impl Int for $ity {
                type OtherSign = $uty;
                type UnsignedInt = $uty;

                fn extract_sign(self) -> (bool, $uty) {
                    if self < 0 {
                        (true, (!(self as $uty)).wrapping_add(1))
                    } else {
                        (false, self as $uty)
                    }
                }

                fn unsigned(self) -> $uty {
                    self as $uty
                }

                fn from_unsigned(me: $uty) -> Self {
                    me as $ity
                }

                int_impl_common!($ity, $bits);
            }
        };
    }

    int_impl!(i16, u16, 16);
    int_impl!(i32, u32, 32);
    int_impl!(i64, u64, 64);
    int_impl!(i128, u128, 128);



    /// Trait to express (possibly lossy) casting of integers
    pub(crate) trait CastInto<T: Copy>: Copy {
        fn cast(self) -> T;
    }

    macro_rules! cast_into {
        ($ty:ty) => {
            cast_into!($ty; usize, isize, u32, i32, u64, i64, u128, i128);
        };
        ($ty:ty; $($into:ty),*) => {$(
            impl CastInto<$into> for $ty {
                fn cast(self) -> $into {
                    self as $into
                }
            }
        )*};
    }

    cast_into!(u32);
    cast_into!(i32);
    cast_into!(u64);
    cast_into!(i64);
    cast_into!(u128);
    cast_into!(i128);
}

use std::collections::HashMap;
use std::env;
use std::fs;
use std::path::Path;

use serde_json::Value;

// https://html.spec.whatwg.org/entities.json
const NAMED_ENTITIES_JSON: &str = include_str!("resources/named_html_entities.json");

fn main() {
    let named_entitites_json: Value = serde_json::from_str(NAMED_ENTITIES_JSON).unwrap();
    let named_entities: HashMap<&str, &str> = named_entitites_json
        .as_object()
        .unwrap()
        .iter()
        .map(|(name, v)| {
            let chars = v
                .as_object()
                .unwrap()
                .get("characters")
                .unwrap()
                .as_str()
                .unwrap();
            (name.as_str(), chars)
        })
        .collect();

    // construct named_entities.rs
    let mut named_entities_rs = String::new();
    named_entities_rs.push_str(
        "use std::collections::HashMap;
    pub fn get_named_entities() -> HashMap<String, String> {
        HashMap::from([\n",
    );
    for (name, chars) in named_entities {
        let name = &name[1..name.len() - 1];
        named_entities_rs.push_str(&format!(
            "    (\"{}\".to_string(), \"{}\".to_string()),\n",
            name,
            chars.escape_unicode()
        ))
    }
    named_entities_rs.push_str(
        "])
    }",
    );

    let out_dir = env::var_os("OUT_DIR").unwrap();
    let dest_path = Path::new(&out_dir).join("entities.rs");
    fs::write(&dest_path, named_entities_rs).unwrap();
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-changed=resources/named_html_entities.json");
}

