            let mut context = Context::default();
            context.artifact.abi.events.insert(
                "Foo".into(),
                vec![Event {
                    name: "Foo".into(),
                    inputs: vec![EventParam {
                        name: String::new(),
                        kind: ParamType::Bool,
                        indexed: false,
