                    }

                    if let Ok(data) = log.clone().decode(
                        &Contract::artifact()
                            .abi
                            .event("Bar")
                            .expect("generated event decode")
                    ) {
                        return Ok(Event::Bar(data));
                    }

                    #invalid_data
                }
            }
        });
    }

