pub trait CFReleasable {
    fn retain(&self) -> Self;
    fn release(&self);
}

impl CFReleasable for CGContextRef {
    #[inline] fn retain(&self) -> Self {
        unsafe { CGContextRetain(*self); }
        *self
    }

    #[inline] fn release(&self) {
        unsafe { CGContextRelease(*self); }
    }
}

impl CFReleasable for CGColorRef {
    #[inline] fn retain(&self) -> Self {
        unsafe { CGColorRetain(*self); }
        *self
    }

    #[inline] fn release(&self) {
        unsafe { CGColorRelease(*self); }
    }
}

impl CFReleasable for CGColorSpaceRef {
    #[inline] fn retain(&self) -> Self {
        unsafe { CGColorSpaceRetain(*self); }
        *self
    }

    #[inline] fn release(&self) {
        unsafe { CGColorSpaceRelease(*self); }
    }
}

impl CFReleasable for CGMutablePathRef {
    #[inline] fn retain(&self) -> Self {
        unsafe { CGPathRetain(*self); }
        *self
    }

    #[inline] fn release(&self) {
        unsafe { CGPathRelease(*self); }
    }
}

pub struct CFRef<T: CFReleasable>(T);

impl<T: CFReleasable> Clone for CFRef<T> {
    #[inline] fn clone(&self) -> CFRef<T> {
        CFRef(self.0.retain())
    }
}

impl<T: CFReleasable> Deref for CFRef<T> {
    type Target = T;

    #[inline] fn deref(&self) -> &T { &self.0 }
}

impl<T: CFReleasable> Drop for CFRef<T> {
    fn drop(&mut self) {
        self.release();
    }
}

impl<T: CFReleasable> From<T> for CFRef<T> {
    fn from(val: T) -> CFRef<T> { CFRef(val) }
}

use crossbeam::channel;
use rayon::{ThreadPool, ThreadPoolBuilder};

/// Search executor whether search request are single thread or multithread.
///
/// We don't expose Rayon thread pool directly here for several reasons.
///
/// First dependency hell. It is not a good idea to expose the
/// API of a dependency, knowing it might conflict with a different version
/// used by the client. Second, we may stop using rayon in the future.
pub enum Executor {
    /// Single thread variant of an Executor
    SingleThread,
    /// Thread pool variant of an Executor
    ThreadPool(ThreadPool),
}

impl Executor {
    /// Creates an Executor that performs all task in the caller thread.
    pub fn single_thread() -> Executor {
        Executor::SingleThread
    }

    /// Creates an Executor that dispatches the tasks in a thread pool.
    pub fn multi_thread(num_threads: usize, prefix: &'static str) -> crate::Result<Executor> {
        let pool = ThreadPoolBuilder::new()
            .num_threads(num_threads)
            .thread_name(move |num| format!("{}{}", prefix, num))
            .build()?;
        Ok(Executor::ThreadPool(pool))
    }

    /// Perform a map in the thread pool.
    ///
    /// Regardless of the executor (`SingleThread` or `ThreadPool`), panics in the task
    /// will propagate to the caller.
    pub fn map<
        A: Send,
        R: Send,
        AIterator: Iterator<Item = A>,
        F: Sized + Sync + Fn(A) -> crate::Result<R>,
    >(
        &self,
        f: F,
        args: AIterator,
    ) -> crate::Result<Vec<R>> {
        match self {
            Executor::SingleThread => args.map(f).collect::<crate::Result<_>>(),
            Executor::ThreadPool(pool) => {
                let args_with_indices: Vec<(usize, A)> = args.enumerate().collect();
                let num_fruits = args_with_indices.len();
                let fruit_receiver = {
                    let (fruit_sender, fruit_receiver) = channel::unbounded();
                    pool.scope(|scope| {
                        for arg_with_idx in args_with_indices {
                            scope.spawn(|_| {
                                let (idx, arg) = arg_with_idx;
                                let fruit = f(arg);
                                if let Err(err) = fruit_sender.send((idx, fruit)) {
                                    error!("Failed to send search task. It probably means all search threads have panicked. {:?}", err);
                                }
                            });
                        }
                    });
                    fruit_receiver
                    // This ends the scope of fruit_sender.
                    // This is important as it makes it possible for the fruit_receiver iteration to
                    // terminate.
                };
                // This is lame, but safe.
                let mut results_with_position = Vec::with_capacity(num_fruits);
                for (pos, fruit_res) in fruit_receiver {
                    let fruit = fruit_res?;
                    results_with_position.push((pos, fruit));
                }
                results_with_position.sort_by_key(|(pos, _)| *pos);
                assert_eq!(results_with_position.len(), num_fruits);
                Ok(results_with_position
                    .into_iter()
                    .map(|(_, fruit)| fruit)
                    .collect::<Vec<_>>())
            }
        }
    }
}

#[cfg(test)]
mod tests {

    use super::Executor;

    #[test]
    #[should_panic(expected = "panic should propagate")]
    fn test_panic_propagates_single_thread() {
        let _result: Vec<usize> = Executor::single_thread()
            .map(
                |_| {
                    panic!("panic should propagate");
                },
                vec![0].into_iter(),
            )
            .unwrap();
    }

    #[test]
    #[should_panic] //< unfortunately the panic message is not propagated
    fn test_panic_propagates_multi_thread() {
        let _result: Vec<usize> = Executor::multi_thread(1, "search-test")
            .unwrap()
            .map(
                |_| {
                    panic!("panic should propagate");
                },
                vec![0].into_iter(),
            )
            .unwrap();
    }

    #[test]
    fn test_map_singlethread() {
        let result: Vec<usize> = Executor::single_thread()
            .map(|i| Ok(i * 2), 0..1_000)
            .unwrap();
        assert_eq!(result.len(), 1_000);
        for i in 0..1_000 {
            assert_eq!(result[i], i * 2);
        }
    }

    #[test]
    fn test_map_multithread() {
        let result: Vec<usize> = Executor::multi_thread(3, "search-test")
            .unwrap()
            .map(|i| Ok(i * 2), 0..10)
            .unwrap();
        assert_eq!(result.len(), 10);
        for i in 0..10 {
            assert_eq!(result[i], i * 2);
        }
    }
}

use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};

use crossbeam_channel::{bounded, Receiver, Sender, TryRecvError};

use crate::error::Result;

use super::{play::play, Command, PlayState};

pub struct Player {
    cmd_tx: Sender<Command>,
    state_rx: Receiver<PlayState>,
    abort_request: Arc<AtomicBool>,
}

impl Drop for Player {
    fn drop(&mut self) {
        log::info!("Player Dropped");
    }
}

unsafe impl Send for Player {}
unsafe impl Sync for Player {}

impl Default for Player {
    fn default() -> Self {
        let (cmd_tx, _cmd_rx) = bounded::<Command>(2);
        let (_state_tx, state_rx) = bounded::<PlayState>(1);
        let abort_request = Arc::new(AtomicBool::new(false));
        Self {
            cmd_tx,
            state_rx,
            abort_request,
        }
    }
}
impl Player {
    pub fn play(&mut self, file: impl Into<String>) -> Result<()> {
        let (cmd_tx, cmd_rx) = bounded::<Command>(2);
        let (state_tx, state_rx) = bounded::<PlayState>(1);

        self.cmd_tx = cmd_tx;
        self.state_rx = state_rx;
        self.abort_request = Arc::new(AtomicBool::new(false));

        play(file.into(), cmd_rx, state_tx, self.abort_request.clone())?;
        Ok(())
    }

    pub fn play_finished(&self) -> bool {
        self.abort_request.load(Ordering::Relaxed)
    }

    pub fn set_play_finished(&self) {
        self.abort_request.store(true, Ordering::Relaxed);
    }

    pub fn set_pause(&self, pause: bool) {
        log::info!("play service pause");
        if let Err(e) = self.cmd_tx.try_send(Command::Pause(pause)) {
            log::error!("发送 Command::Pause 失败, E: {}", e.to_string());
        }
    }

    pub fn set_mute(&self, mute: bool) {
        log::info!("play service pause");
        if let Err(e) = self.cmd_tx.try_send(Command::Mute(mute)) {
            log::error!("发送 Command::Pause 失败, E: {}", e.to_string());
        }
    }

    pub fn set_volume(&self, volume: f32) {
        log::info!("play service set volume: {volume}");
        if let Err(e) = self.cmd_tx.try_send(Command::Volume(volume)) {
            log::error!(
                "try_send cmd Volume({}) failed, E: {}",
                volume,
                e.to_string()
            );
        }
    }

    pub fn try_recv_state(&mut self) -> Option<PlayState> {
        match self.state_rx.try_recv() {
            Ok(state) => Some(state),
            Err(TryRecvError::Empty) => None,
            Err(TryRecvError::Disconnected) => {
                log::info!("player state Disconnected");
                // self.set_abort_request(true);
                None
            }
        }
    }
}

