                ]
            }
        "#;

        let json: LsblkJson = serde_json::from_str(&data).unwrap();

        let cmp = LsblkJson {
            blockdevices: vec![
                LsblkInner {
                    pkname: None,
                    kname: "vda".into(),
                    path: "/dev/vda".into(),
                },
                LsblkInner {
                    pkname: Some("vda".into()),
                    kname: "vda1".into(),
                    path: "/dev/vda1".into(),
                },
                LsblkInner {
                    pkname: Some("vda".into()),
                    kname: "vda2".into(),
                    path: "/dev/vda2".into(),
                },
                LsblkInner {
                    pkname: Some("vda".into()),
                    kname: "vda3".into(),
                    path: "/dev/vda3".into(),
                },
            ],
        };

        assert_eq!(cmp, json);
    }
}

//! Immediate mode UI.
//!
//! Spiritual successor of megaui library, but fully skinnable and configurable.
//!
//! The UI entrypoint is `root_ui()` call.
//! ```ignore
//! root_ui().label(None, "hello megaui");
//! if root_ui().button(None, "Push me") {
//!    println!("pushed");
//! }
//! ```
//! This will draw a label and a button one after each other right on top of the
//! screen.

