async fn add_connection(
    name: String,
    url: String,
    username: String,
    password: String,
    phrase: String,
) -> Message {
    if name.is_empty() {
        return Message::SetConnectionError("name of connection is required".to_string());
    } else if url.is_empty() {
        return Message::SetConnectionError("node url is required".to_string());
    } else if username.is_empty() {
        return Message::SetConnectionError("username is required".to_string());
    } else if password.is_empty() {
        return Message::SetConnectionError("password is required".to_string());
    }

    let rq_client = RqClient::new(
        url.clone(),
        username.clone(),
        password.clone(),
        phrase.clone(),
    );

    let response_connection = rq_client.get_wallet_info().await;

    if let Err(connection_error) = response_connection {
        return Message::SetConnectionError(connection_error.to_string());
    }

    if let Some(err_msg) = response_connection.unwrap().error {
        return Message::SetConnectionError(err_msg.message);
    }

    let connection_db = ConnectionDB::new().await;

    let mut connections = connection_db.get_connections();

    connections.push(ConnectNodeModel::from((
        name, url, username, password, phrase,
    )));

    let connection_db_string_result = serde_json::to_string(&connections);

    if let Err(serde_error) = connection_db_string_result {
        return Message::SetConnectionError(serde_error.to_string());
    }

    let response_result = connection_db.insert_model(
        "connections".to_string(),
        connection_db_string_result.unwrap(),
    );

    if let Err(response) = response_result {
        Message::SetConnectionError(response.to_string())
    } else {
        let connections_and_locked = get_connections_dto(connections).await;

        Message::GetConnections(connections_and_locked)
    }
}

async fn get_info(node: ConnectNodeDto) -> Message {
    let rq_client = RqClient::new(
        node.address.clone(),
        node.username.clone(),
        node.password.clone(),
        node.phrase.clone(),
    );

    let info_result = rq_client.get_wallet_info().await;

    if let Ok(info) = info_result {
        if let Some(err_msg) = info.error {
            return Message::SetConnectionError(err_msg.message);
        }
        Message::ShowInfo(info.result)
    } else {
        Message::SetConnectionError("Error to get node info".to_string())
    }
}

async fn delete_connection(name: String) -> Message {
    let connection_db = ConnectionDB::new().await;

    let connections = connection_db.get_connections();

    let connections_filtered = connections
        .into_iter()
        .filter(|c| *c.name != name)
        .collect::<Vec<ConnectNodeModel>>();

    let connection_db_string_result = serde_json::to_string(&connections_filtered);

    if let Err(serde_error) = connection_db_string_result {
        return Message::SetConnectionError(serde_error.to_string());
    }

    let response_result = connection_db.insert_model(
        "connections".to_string(),
        connection_db_string_result.unwrap(),
    );

    if let Err(response) = response_result {
        Message::SetConnectionError(response.to_string())
    } else {
        let connections_and_locked = get_connections_dto(connections_filtered).await;

        Message::GetConnections(connections_and_locked)
    }
}

async fn list_accounts(node: ConnectNodeDto) -> Message {
    let rq_client = RqClient::new(
        node.address.clone(),
        node.username.clone(),
        node.password.clone(),
        node.phrase.clone(),
    );

    let accounts_and_addresses_stream = stream::iter(node.accounts.clone());

    let accounts_and_addresses_stream = accounts_and_addresses_stream.then(|a| async {
        let addresses_result = rq_client.get_addresses(a.account.clone()).await;

        let empty_account = AccountAddresses::from((String::from(""), vec![]));

        if let Ok(addresses) = addresses_result {
            if let Some(_err_msg) = addresses.error {
                return empty_account;
            }
            AccountAddresses::from((a.account, addresses.result))
        } else {
            empty_account
        }
    });

    let accounts_and_addresses = accounts_and_addresses_stream
        .collect::<Vec<AccountAddresses>>()
        .await;

    let accounts_and_addresses_filtered = accounts_and_addresses
        .to_vec()
        .into_iter()
        .filter(|aa| !aa.account.is_empty())
        .collect::<Vec<AccountAddresses>>();

    if accounts_and_addresses_filtered.is_empty() {
        return Message::SetConnectionError("Not accounts found in this node".to_string());
    }

    Message::ShowAccounts(accounts_and_addresses_filtered, node)
}

async fn lock_wallet(node: ConnectNodeDto) -> Message {
    let rq_client = RqClient::new(
        node.address.clone(),
        node.username.clone(),
        node.password.clone(),
        node.phrase.clone(),
    );

    let locked_result = rq_client.lock_wallet().await;

    if let Err(locked_error) = locked_result {
        return Message::SetConnectionError(locked_error.to_string());
    }

    if let Some(locked_error) = locked_result.unwrap().error {
        Message::SetConnectionError(locked_error.message)
    } else {
        let connection_db = ConnectionDB::new().await;

        let connections = connection_db.get_connections();

        let connections_and_locked = get_connections_dto(connections).await;

        Message::GetConnections(connections_and_locked)
    }
}

async fn unlock_wallet(node: ConnectNodeDto, time: String, staking_only: bool) -> Message {
    let rq_client = RqClient::new(
        node.address.clone(),
        node.username.clone(),
        node.password.clone(),
        node.phrase.clone(),
    );

    let response_result = rq_client
        .unlock_wallet(time.parse::<u32>().unwrap(), staking_only)
        .await;

    if let Ok(response) = response_result {
        if let Some(err_msg) = response.error {
            return Message::SetConnectionError(err_msg.message);
        }
        let connection_db = ConnectionDB::new().await;

        let connections = connection_db.get_connections();

        let connections_and_locked = get_connections_dto(connections).await;
        Message::GetConnections(connections_and_locked)
    } else {
        Message::SetConnectionError("Fail connecting with the rpc".to_string())
    }
}

async fn get_transactions(account: String, node: ConnectNodeDto) -> Message {
    let rq_client = RqClient::new(
        node.address.clone(),
        node.username.clone(),
        node.password.clone(),
        node.phrase.clone(),
    );

    let response_result = rq_client.listing_transaction(account).await;

    if let Ok(response) = response_result {
        if let Some(err_msg) = response.error {
            return Message::SetConnectionError(err_msg.message);
        }

        Message::GetTransactions(response.result.to_vec())
    } else {
        Message::SetConnectionError("Fail connecting with the rpc".to_string())
    }
}

use jssat_ir::frontend::{builder::*, ir::*};

// might be vaguely useful in the future as tutorial code or something
#[allow(dead_code)]
pub fn traverse(_source: String) -> IR {
    let mut builder = ProgramBuilder::new();

    let host_defined = builder.dealer.deal("host_defined");
    let call = builder.dealer.deal("call");

    let print_stub = {
        let (mut print_stub, [any]) = builder.start_function();

        let print = builder.external_function(
            "jssatrt_print_any",
            [FFIValueType::Runtime, FFIValueType::Any],
            Returns::Void,
        );

        let mut block = print_stub.start_block_main();
        let runtime = block.get_runtime();
        block.call_external_function(print, [runtime, any]);
        print_stub.end_block(block.ret(None));

        builder.end_function(print_stub)
    };

    let sum = {
        let (mut sum, [n]) = builder.start_function();

        /*
        def sum(n):
            total = 0
            for i in range(0, n):
                total += i
            return total

        sum(n):
            Entry():
                i = 0
                total = 0
                jmp Check(i, total)
            Check(ci, ctotal):
                should_iterate = ci < n
                if (should_iterate)
                    jmp Loop(ci, ctotal)
                else
                    jmp End(ctotal)
            Loop(li, ltotal):
                print(li)
                total2 = ltotal + li
                i2 = li + 1
                jmp Check(i2, total2)
            End(etotal):
                ret etotal
        */
        let mut entry = sum.start_block_main();
        let (mut check, [ci, ctotal]) = sum.start_block();
        let (mut bloop, [li, ltotal]) = sum.start_block();
        let (end, [etotal]) = sum.start_block();

        let check_sig = check.signature();

        {
            let i = entry.make_number_decimal(0);
            let total = entry.make_number_decimal(0);
            sum.end_block(entry.jmp(check.signature(), [i, total]));
        }
        {
            let should_iterate = check.compare_less_than(ci, n);
            sum.end_block(check.jmpif(
                should_iterate,
                bloop.signature(),
                [ci, ctotal],
                end.signature(),
                [ctotal],
            ));
        }
        {
            bloop.call(print_stub, [li]);
            let total2 = bloop.add(ltotal, li);
            let one = bloop.make_number_decimal(1);
            let i2 = bloop.add(li, one);
            sum.end_block(bloop.jmp(check_sig, [i2, total2]));
        }
        {
            sum.end_block(end.ret(Some(etotal)));
        }

        builder.end_function(sum)
    };

    let print_is_cool_and_key = {
        let (mut func, [record]) = builder.start_function();

        let mut block = func.start_block_main();

        let key = block.make_string(builder.constant_str_utf16("key"));
        let prop_at_key = block.record_get_prop(record, key);
        let prop_at_slot = block.record_get_atom(record, host_defined);
        let call_it = block.record_get_atom(record, call);
        block.call(print_stub, [prop_at_key]);
        block.call(print_stub, [prop_at_slot]);
        block.call_virt(call_it, [key]);

        func.end_block(block.ret(None));
        builder.end_function(func)
    };

    let _main = {
        let mut main = builder.start_function_main();

        let mut block = main.start_block_main();

        // TODO: make compiling `sum` and hello world a test
        let hello_world = builder.constant_str_utf16("Hello, World!");
        let hello_world = block.make_string(hello_world);
        block.call(print_stub, [hello_world]);
        let max = block.make_number_decimal(3);
        block.call(sum, [max]);

        let obj = block.record_new();
        let key = block.make_string(builder.constant_str_utf16("key"));
        let value = block.make_number_decimal(69);
        block.record_set_prop(obj, key, value);
        let value = block.make_number_decimal(1);
        block.record_set_atom(obj, host_defined, value);
        let fnptr = block.make_fnptr(print_stub.id);
        block.record_set_atom(obj, call, fnptr);

        block.call(print_is_cool_and_key, [obj]);

        main.end_block(block.ret(None));

        builder.end_function(main)
    };

    builder.finish()
}

