mod r {
    use {
        std::env::{var},
        uptic::{Uptic}
    };

    fn process(data: &Uptic) -> String {
        let (d, h, m) =
            (if data.days != 0 { format!("\x1b[1;93m{}\x1b[0;97m\x1b[0;97m, ", data.days)
            } else { "".to_string() },
            if data.hours != 0 { format!("\x1b[1;94m{}\x1b[0;97m\x1b[0;97m, ", data.hours)
            } else { "".to_string() },
            if data.minutes != 0 { format!("\x1b[1;95m{}\x1b[0;97mm", data.minutes)
            } else { "".to_string() });

        format!("{}{}{}", d, h, m)
    }

    pub fn init(data: &Uptic) {
        let (user, mut lang, disp, term, desk) =
            (var("USER").unwrap(),
             var("LANG").unwrap(),
             var("DISPLAY").unwrap(),
             var("TERM").unwrap(),
             var("DESKTOP_SESSION").unwrap());

        let tty = disp.clone();

        if user.len() != 0 {
            print!("\x1b[1;94m{}\x1b[0m ", user);
        }

        if disp.len() != 0 {
            print!("\x1b[0;97m-> \x1b[1;91m{} ", tty);
            print!("\x1b[0;97md(\x1b[0;95m{}\x1b[0;97m) ", disp);
        }

        if lang.len() == 0 {
            lang = var("LANGUAGE").unwrap();
        } print!("l(\x1b[1;97m{}\x1b[0;97m) ", lang);

        print!("u({})\x1b[0;97m)", process(data));

        if term.len() != 0 {
            print!(" \x1b[1;93m{}\x1b[0;97m ", term);
        }

        if desk.len() != 0 {
            println!(" d(\x1b[1;90m{}\x1b[0;97m)", desk);
        }
    }
}

fn main() {
    r::init(&uptic::Uptic::default());
}

//! [AppHandle] contains the state Yew keeps to bootstrap a component in an isolated scope.

use std::ops::Deref;
use std::rc::Rc;

use web_sys::Element;

use crate::dom_bundle::BSubtree;
use crate::html::{BaseComponent, NodeRef, Scope, Scoped};

/// An instance of an application.
#[derive(Debug)]
#[cfg_attr(documenting, doc(cfg(feature = "csr")))]
pub struct AppHandle<COMP: BaseComponent> {
    /// `Scope` holder
    pub(crate) scope: Scope<COMP>,
}

impl<COMP> AppHandle<COMP>
where
    COMP: BaseComponent,
{
    /// The main entry point of a Yew program which also allows passing properties. It works
    /// similarly to the `program` function in Elm. You should provide an initial model, `update`
    /// function which will update the state of the model and a `view` function which
    /// will render the model to a virtual DOM tree.
    pub(crate) fn mount_with_props(host: Element, props: Rc<COMP::Properties>) -> Self {
        clear_element(&host);
        let app = Self {
            scope: Scope::new(None),
        };
        let hosting_root = BSubtree::create_root(&host);
        app.scope.mount_in_place(
            hosting_root,
            host,
            NodeRef::default(),
            NodeRef::default(),
            props,
        );

        app
    }

    /// Schedule the app for destruction
    pub fn destroy(self) {
        self.scope.destroy(false)
    }
}

impl<COMP> Deref for AppHandle<COMP>
where
    COMP: BaseComponent,
{
    type Target = Scope<COMP>;

    fn deref(&self) -> &Self::Target {
        &self.scope
    }
}

/// Removes anything from the given element.
fn clear_element(host: &Element) {
    while let Some(child) = host.last_child() {
        host.remove_child(&child).expect("can't remove a child");
    }
}

