use super::{decode_number, EOByte, EOChar, EOInt, EOShort, EOThree, EO_BREAK_CHAR};
use std::{cell::Cell, cmp};

/// used for reading byte streams
///
/// This struct is for parsing numbers and string out of an EO
/// encoded data stream such as a data file or a data packet.
///
/// # Example
/// The following example shows a server application reading the
/// Init request data.
/// ```
/// use eo::data::StreamReader;
///
/// // EO Init Request
/// let buf = [
///     162, 190, 2, 1, 1, 29, 113, 8, 50, 57, 48, 49, 49, 51, 50,
/// ];
/// let reader = StreamReader::new(&buf);
/// let challenge = reader.get_three();
/// let version_major = reader.get_char();
/// let version_minor = reader.get_char();
/// let version_build = reader.get_char();
/// reader.seek(1); // unknown char
/// let hdid = reader.get_prefix_string();
///
/// println!(
///     "Client Request\nChallenge: {}\nVersion: {}.{}.{}\nHDID: {}",
///     challenge, version_major, version_minor, version_build, hdid
/// );
/// ```
pub struct StreamReader<'a> {
    data: &'a [EOByte],
    position: Cell<usize>,
}

impl<'a> StreamReader<'a> {
    /// Creates a [StreamReader] for an existing `&[EOByte]`
    pub fn new(data: &'a [EOByte]) -> Self {
        Self {
            data,
            position: Cell::new(0),
        }
    }
    /// returns the length of the data stream
    pub fn length(&self) -> usize {
        self.data.len()
    }
    /// returns the amount of bytes left in the data stream
    pub fn remaining(&self) -> usize {
        self.length() - self.position.get()
    }
    /// returns a true if you have reached the end of the data stream
    ///
    /// # Example
    /// ```
    /// use eo::data::StreamReader;
    ///
    /// let buf = [
    ///     255, 255, 255, 255, 255, 255
    /// ];
    /// let reader = StreamReader::new(&buf);
    /// while !reader.eof() {
    ///     println!("{}", reader.get_byte());
    /// }
    /// ```
    pub fn eof(&self) -> bool {
        self.position.get() >= self.data.len()
    }
    /// returns a single [EOByte] from the data stream
    ///
    /// increases the read position by 1
    pub fn get_byte(&self) -> EOByte {
        let position = self.position.get();
        let number = self.data[position];
        self.position.set(position + 1);
        number
    }
    /// returns a single byte from the data stream decoded into an [EOChar]
    ///
    /// increases the read position by 1
    pub fn get_char(&self) -> EOChar {
        let position = self.position.get();
        let number = decode_number(&self.data[position..position + 1]);
        self.position.set(position + 1);
        number as EOChar
    }
    /// returns two bytes from the data stream decoded into an [EOShort]
    ///
    /// increases the read position by 2
    /// decodes two bytes using the [decode_number] method
    pub fn get_short(&self) -> EOShort {
        let position = self.position.get();
        let number = decode_number(&self.data[position..position + 2]);
        self.position.set(position + 2);
        number as EOShort
    }
    /// returns three bytes from the data stream decoded into an [EOThree]
    pub fn get_three(&self) -> EOThree {
        let position = self.position.get();
        let number = decode_number(&self.data[position..position + 3]);
        self.position.set(position + 3);
        number as EOThree
    }
    /// returns four bytes from the data stream decoded into an [EOInt]
    pub fn get_int(&self) -> EOInt {
        let position = self.position.get();
        let number = decode_number(&self.data[position..position + 4]);
        self.position.set(position + 4);
        number as EOInt
    }
    /// returns a UTF-8 encoded string of length `length` from the data stream
    pub fn get_fixed_string(&self, length: usize) -> String {
        if self.remaining() >= length {
            let bytes_to_read = self.get_vec(length);
            String::from_utf8(bytes_to_read).expect("Failed to convert byte array to string")
        } else {
            String::from("")
        }
    }
    /// returns a UTF-8 encoded string from the current read position to the next "break string" (0xff)
    pub fn get_break_string(&self) -> String {
        let position_of_break_char = {
            let mut temp_position = 0;
            for i in self.position.get()..self.data.len() {
                if self.data[i] == EO_BREAK_CHAR {
                    temp_position = i;
                    break;
                }
            }
            temp_position
        };

        let string = self.get_fixed_string(position_of_break_char - self.position.get());
        self.position.set(self.position.get() + 1);
        string
    }
    /// reads the next byte as a length and uses that length to get a fixed string in UTF-8 encoding
    pub fn get_prefix_string(&self) -> String {
        let length = self.get_char() as usize;
        self.get_fixed_string(length)
    }
    /// returns a UTF-8 encoded string from the current read position to the end of the data stream
    pub fn get_end_string(&self) -> String {
        self.get_fixed_string(self.remaining())
    }
    /// moves the read position forward by `length`
    pub fn seek(&self, length: usize) {
        self.position.set(self.position.get() + length);
    }
    /// returns a Vec<EOByte> of the desired length
    pub fn get_vec(&self, length: usize) -> Vec<EOByte> {
        let position = self.position.get();
        let buf = &self.data[position..cmp::min(self.length(), position + length)];
        self.position.set(position + length);
        buf.to_vec()
    }
}

#[cfg(test)]
mod tests {
    use super::{StreamReader, EO_BREAK_CHAR};
    #[test]
    fn get_byte() {
        let bytes = [0];
        let reader = StreamReader::new(&bytes);
        assert_eq!(reader.get_byte(), bytes[0]);
    }
    #[test]
    fn get_char() {
        let bytes = [1];
        let reader = StreamReader::new(&bytes);
        assert_eq!(reader.get_char(), 0);
    }
    #[test]
    fn get_short_one_byte() {
        let bytes = [2, 254];
        let reader = StreamReader::new(&bytes);
        assert_eq!(reader.get_short(), 1);
    }
    #[test]
    fn get_short_two_bytes() {
        let bytes = [1, 2];
        let reader = StreamReader::new(&bytes);
        assert_eq!(reader.get_short(), 253);
    }
    #[test]
    fn get_three_one_byte() {
        let bytes = [2, 254, 254];
        let reader = StreamReader::new(&bytes);
        assert_eq!(reader.get_three(), 1);
    }
    #[test]
    fn get_three_two_bytes() {
        let bytes = [1, 2, 254];
        let reader = StreamReader::new(&bytes);
        assert_eq!(reader.get_three(), 253);
    }
    #[test]
    fn get_three_three_bytes() {
        let bytes = [1, 1, 2];
        let reader = StreamReader::new(&bytes);
        assert_eq!(reader.get_three(), 64009);
    }
    #[test]
    fn get_int_one_byte() {
        let bytes = [2, 254, 254, 254];
        let reader = StreamReader::new(&bytes);
        assert_eq!(reader.get_int(), 1);
    }
    #[test]
    fn get_int_two_bytes() {
        let bytes = [1, 2, 254, 254];
        let reader = StreamReader::new(&bytes);
        assert_eq!(reader.get_int(), 253);
    }
    #[test]
    fn get_int_three_bytes() {
        let bytes = [1, 1, 2, 254];
        let reader = StreamReader::new(&bytes);
        assert_eq!(reader.get_int(), 64009);
    }
    #[test]
    fn get_int_four_bytes() {
        let bytes = [1, 1, 1, 2];
        let reader = StreamReader::new(&bytes);
        assert_eq!(reader.get_int(), 16194277);
    }
    #[test]
    fn get_fixed_string() {
        let bytes = [
            0x48, 0x65, 0x6C, 0x6C, 0x6F, 0x2C, 0x20, 0x77, 0x6F, 0x72, 0x6C, 0x64, 0x21,
        ];
        let reader = StreamReader::new(&bytes);
        assert_eq!(reader.get_fixed_string(13), "Hello, world!");
    }
    #[test]
    fn get_break_string() {
        let bytes = [
            0x48,
            0x65,
            0x6C,
            0x6C,
            0x6F,
            0x2C,
            0x20,
            0x77,
            0x6F,
            0x72,
            0x6C,
            0x64,
            0x21,
            EO_BREAK_CHAR,
        ];
        let reader = StreamReader::new(&bytes);
        assert_eq!(reader.get_break_string(), "Hello, world!");
    }
    #[test]
    fn get_prefix_string() {
        let bytes = [
            0xE, 0x48, 0x65, 0x6C, 0x6C, 0x6F, 0x2C, 0x20, 0x77, 0x6F, 0x72, 0x6C, 0x64, 0x21,
        ];
        let reader = StreamReader::new(&bytes);
        assert_eq!(reader.get_prefix_string(), "Hello, world!");
    }
    #[test]
    fn length() {
        let reader = StreamReader::new(&[255]);
        assert_eq!(reader.length(), 1);

        let reader = StreamReader::new(&[255, 255, 255]);
        assert_eq!(reader.length(), 3);
    }
    #[test]
    fn seek() {
        let reader = StreamReader::new(&[1, 2]);
        assert_eq!(reader.position.get(), 0);
        reader.seek(2);
        assert_eq!(reader.position.get(), 2);
    }
    #[test]
    fn eof() {
        let reader = StreamReader::new(&[1]);
        assert_eq!(reader.eof(), false);
        reader.get_byte();
        assert_eq!(reader.eof(), true);
    }
    #[test]
    fn get_vec() {
        let reader = StreamReader::new(&[1, 2, 3, 4, 5]);
        let buf = reader.get_vec(3);
        assert_eq!(buf, vec![1, 2, 3]);
        let buf = reader.get_vec(2);
        assert_eq!(buf, vec![4, 5]);
    }
}

use crate::types::Type;
use crate::{Decl, Expr, ExprKind, Pat, PatKind, SortedRecord};
use sml_util::interner::Symbol;
use sml_util::pretty_print::{PrettyPrinter, Print};

use std::collections::HashMap;

impl<T: Print> Print for &SortedRecord<T> {
    fn print<'a, 'b>(&self, pp: &'a mut PrettyPrinter<'b>) -> &'a mut PrettyPrinter<'b> {
        if let Symbol::Tuple(_) = self[0].label {
            pp.text("(");
            for (idx, row) in self.iter().enumerate() {
                pp.print(&row.data);
                if idx != self.len() - 1 {
                    pp.text(", ");
                }
            }
            pp.text(")")
        } else {
            pp.text("{");
            for (idx, row) in self.iter().enumerate() {
                pp.print(&row.label).text("= ").print(&row.data);
                if idx != self.len() - 1 {
                    pp.text(", ");
                }
            }
            pp.text("}")
        }
    }
}

impl<'a> Print for Pat<'a> {
    fn print<'c, 'b>(&self, pp: &'c mut PrettyPrinter<'b>) -> &'c mut PrettyPrinter<'b> {
        match &self.kind {
            PatKind::App(con, Some(pat)) => pp.print(&con.name).text(" ").print(pat),
            PatKind::App(con, None) => pp.print(&con.name),
            PatKind::Const(constant) => pp.print(&constant),
            PatKind::Record(record) => pp.print(&record),
            PatKind::Var(sym) => pp.print(sym),
            PatKind::Wild => pp.text("_"),
        }
    }
}

impl<'a> Print for Expr<'a> {
    fn print<'b, 'c>(&self, pp: &'b mut PrettyPrinter<'c>) -> &'b mut PrettyPrinter<'c> {
        use ExprKind::*;
        match &self.kind {
            App(e1, e2) => pp.print(e1).text(" ").print(e2),
            Case(casee, rules) => pp.nest(2, |pp| {
                pp.line().text("case ").print(&casee.0).nest(2, |pp| {
                    pp.line()
                        .text("of ")
                        .print(&rules[0].pat)
                        .text(" => ")
                        .print(&rules[0].expr)
                });
                for rule in rules.iter().skip(1) {
                    pp.nest(3, |pp| {
                        pp.line().nest(2, |pp| {
                            pp.text("| ")
                                .print(&rule.pat)
                                .text(" => ")
                                .print(&rule.expr)
                        })
                    });
                }
                pp
            }),
            Con(con, _) => pp.print(&con.name),
            Const(c) => pp.print(&c),
            Handle(tryy, sym, handler) => pp
                .print(tryy)
                .text("handle ")
                .print(sym)
                .text(" with ")
                .print(handler),
            Lambda(lam) => pp.text("fn ").print(&lam.arg).text(" => ").print(&lam.body),
            Let(decls, body) => pp.nest(2, |pp| {
                pp.line()
                    .text("let")
                    .nest(2, |pp| {
                        for decl in decls {
                            pp.print(decl);
                        }
                        pp
                    })
                    .line()
                    .text("in ")
                    .nest(2, |pp| pp.line().print(body))
                    .line()
                    .text("end")
            }),
            List(exprs) => {
                pp.text("[");
                for (idx, expr) in exprs.iter().enumerate() {
                    pp.print(expr);
                    if idx != exprs.len().saturating_sub(1) {
                        pp.text(", ");
                    }
                }
                pp.text("]")
            }
            Primitive(sym) => pp.print(sym),
            Raise(e) => pp.text("raise ").print(e),
            Record(rows) => {
                let rec = SortedRecord::new_unchecked(rows.clone());
                pp.print(&&rec)
            }
            Selector(ex, sym) => pp.text("#").print(sym).text(" ").print(ex),
            Seq(exprs) => {
                pp.text("(");
                for (idx, expr) in exprs.iter().enumerate() {
                    pp.print(expr);
                    if idx != exprs.len().saturating_sub(1) {
                        pp.text("; ");
                    }
                }
                pp.text(")")
            }
            Var(s, _) => pp.print(s),
        }
    }
}

impl<'a> Print for Type<'a> {
    fn print<'c, 'b>(&self, pp: &'c mut PrettyPrinter<'b>) -> &'c mut PrettyPrinter<'b> {
        let mut map = HashMap::new();
        self.print_rename(pp, &mut map)
    }
}

impl<'a> Type<'a> {
    pub fn print_rename<'b, 'c>(
        &self,
        pp: &'b mut PrettyPrinter<'c>,
        map: &mut HashMap<usize, String>,
    ) -> &'b mut PrettyPrinter<'c> {
        match self {
            Type::Con(tycon, args) => {
                if tycon == &crate::builtin::tycons::T_ARROW {
                    pp.text("(");
                    args[0].print_rename(pp, map).text(" -> ");
                    args[1].print_rename(pp, map).text(")")
                } else {
                    for arg in args {
                        arg.print_rename(pp, map).text(" ");
                    }
                    pp.print(&tycon.name)
                }
            }
            Type::Record(fields) => {
                if let Symbol::Tuple(_) = fields[0].label {
                    pp.text("(");
                    for (idx, row) in fields.iter().enumerate() {
                        row.data.print_rename(pp, map);
                        if idx != fields.rows.len() - 1 {
                            pp.text(" * ");
                        }
                    }
                    pp.text(")")
                } else {
                    pp.text("{");
                    for (idx, row) in fields.iter().enumerate() {
                        pp.print(&row.label).text(": ");
                        row.data.print_rename(pp, map);
                        if idx != fields.rows.len() - 1 {
                            pp.text(", ");
                        }
                    }
                    pp.text("}")
                }
            }
            Type::Var(tyvar) => match tyvar.ty() {
                Some(bound) => bound.print_rename(pp, map),
                None => match map.get(&tyvar.id) {
                    Some(s) => pp.text(s),
                    None => {
                        let x = map.len();
                        let last = ((x % 26) as u8 + b'a' as u8) as char;
                        let name = format!(
                            "'{}",
                            (0..x / 26)
                                .map(|_| 'z')
                                .chain(std::iter::once(last))
                                .collect::<String>()
                        );
                        pp.text(&format!("{}#{}", name, tyvar.id));
                        // pp.text(&name);
                        map.insert(tyvar.id, name);
                        pp
                    }
                },
            },
            Type::Flex(flex) => match flex.ty() {
                Some(ty) => ty.print_rename(pp, map),
                None => {
                    pp.text("{");
                    for row in flex.constraints.iter() {
                        pp.print(&row.label).text(": ");
                        row.data.print_rename(pp, map);
                        pp.text(", ");
                    }
                    pp.text("... }")
                }
            },
        }
    }
}

fn print_tyvars<'b, 'c>(
    ids: &[usize],
    map: &mut HashMap<usize, String>,
    pp: &'b mut PrettyPrinter<'c>,
) -> &'b mut PrettyPrinter<'c> {
    match ids.len() {
        0 => pp,
        1 => {
            map.insert(ids[0], "'a".into());
            pp.text("'a ")
        }
        _ => {
            pp.text("(");
            for (idx, tyvar) in ids.iter().enumerate() {
                let last = ((idx % 26) as u8 + b'a' as u8) as char;
                let name = format!(
                    "'{}",
                    (0..idx / 26)
                        .map(|_| 'z')
                        .chain(std::iter::once(last))
                        .collect::<String>()
                );
                pp.text(&name);
                map.insert(*tyvar, name);
                if idx != ids.len() - 1 {
                    pp.text(", ");
                }
            }
            pp.text(") ")
        }
    }
}

impl<'a> Print for Decl<'a> {
    fn print<'b, 'c>(&self, pp: &'b mut PrettyPrinter<'c>) -> &'b mut PrettyPrinter<'c> {
        let mut map = HashMap::new();
        match self {
            Decl::Val(vars, var, expr) => {
                pp.line().text("val ");
                print_tyvars(&vars, &mut map, pp)
                    .print(var)
                    .text(": ")
                    .print(expr.ty)
                    .text(" = ")
                    .print(expr)
            }
            Decl::Fun(vars, binds) => {
                for (name, lam) in binds {
                    pp.line().text("val ");
                    print_tyvars(&vars, &mut map, pp)
                        .print(name)
                        .text(": ")
                        // .print(&Type::Con(
                        //     crate::builtin::tycons::T_ARROW,
                        //     vec![lam.ty, lam.body.ty],
                        // ))
                        .text(" = ")
                        .text("fn (")
                        .print(&lam.arg)
                        .text(": ")
                        .print(lam.ty)
                        .text(") => ")
                        .print(&lam.body);
                }
                pp
            }
            Decl::Exn(con, Some(ty)) => pp
                .line()
                .text("exception ")
                .print(&con.name)
                .text(" of ")
                .print(*ty),
            Decl::Exn(con, None) => pp.text("exception ").print(&con.name),
            Decl::Datatype(dts) => {
                for dt in dts {
                    pp.line().text("datatype ");
                    print_tyvars(&dt.tyvars, &mut map, pp)
                        .print(&dt.tycon.name)
                        .text(" = ");

                    for (idx, con) in dt.constructors.iter().enumerate() {
                        match con {
                            (con, Some(ty)) => {
                                pp.print(&con.name).text(" of ");
                                ty.print_rename(pp, &mut map);
                            }
                            (con, None) => {
                                pp.print(&con.name);
                            }
                        }
                        if idx != dt.constructors.len().saturating_sub(1) {
                            pp.text(" | ");
                        }
                    }
                }
                pp
            }
        }
    }
}

