//! CLI tool to read Cretonne IR files and compile them into native code.

use capstone::prelude::*;
use cretonne_codegen::isa::TargetIsa;
use cretonne_codegen::print_errors::pretty_error;
use cretonne_codegen::settings::FlagsOrIsa;
use cretonne_codegen::Context;
use cretonne_codegen::{binemit, ir};
use cretonne_reader::parse_test;
use std::path::Path;
use std::path::PathBuf;
use utils::{parse_sets_and_isa, read_to_string};

struct PrintRelocs {
    flag_print: bool,
}

impl binemit::RelocSink for PrintRelocs {
    fn reloc_ebb(
        &mut self,
        where_: binemit::CodeOffset,
        r: binemit::Reloc,
        offset: binemit::CodeOffset,
    ) {
        if self.flag_print {
            println!("reloc_ebb: {} {} at {}", r, offset, where_);
        }
    }

    fn reloc_external(
        &mut self,
        where_: binemit::CodeOffset,
        r: binemit::Reloc,
        name: &ir::ExternalName,
        addend: binemit::Addend,
    ) {
        if self.flag_print {
            println!("reloc_ebb: {} {} {} at {}", r, name, addend, where_);
        }
    }

    fn reloc_jt(&mut self, where_: binemit::CodeOffset, r: binemit::Reloc, jt: ir::JumpTable) {
        if self.flag_print {
            println!("reloc_ebb: {} {} at {}", r, jt, where_);
        }
    }
}

struct PrintTraps {
    flag_print: bool,
}

impl binemit::TrapSink for PrintTraps {
    fn trap(&mut self, offset: binemit::CodeOffset, _srcloc: ir::SourceLoc, code: ir::TrapCode) {
        if self.flag_print {
            println!("trap: {} at {}", code, offset);
        }
    }
}

pub fn run(
    files: Vec<String>,
    flag_print: bool,
    flag_set: &[String],
    flag_isa: &str,
) -> Result<(), String> {
    let parsed = parse_sets_and_isa(flag_set, flag_isa)?;

    for filename in files {
        let path = Path::new(&filename);
        let name = String::from(path.as_os_str().to_string_lossy());
        handle_module(flag_print, &path.to_path_buf(), &name, parsed.as_fisa())?;
    }
    Ok(())
}

fn handle_module(
    flag_print: bool,
    path: &PathBuf,
    name: &str,
    fisa: FlagsOrIsa,
) -> Result<(), String> {
    let buffer = read_to_string(&path).map_err(
        |e| format!("{}: {}", name, e),
    )?;
    let test_file = parse_test(&buffer).map_err(|e| format!("{}: {}", name, e))?;

    // If we have an isa from the command-line, use that. Otherwise if the
    // file contains a unique isa, use that.
    let isa = if let Some(isa) = fisa.isa {
        isa
    } else if let Some(isa) = test_file.isa_spec.unique_isa() {
        isa
    } else {
        return Err(String::from("compilation requires a target isa"));
    };

    for (func, _) in test_file.functions {
        let mut context = Context::new();
        context.func = func;

        // Compile and encode the result to machine code.
        let mut mem = Vec::new();
        let mut relocs = PrintRelocs { flag_print };
        let mut traps = PrintTraps { flag_print };
        context
            .compile_and_emit(isa, &mut mem, &mut relocs, &mut traps)
            .map_err(|err| pretty_error(&context.func, Some(isa), err))?;

        if flag_print {
            println!("{}", context.func.display(isa));
        }

        if flag_print {
            print!(".byte ");
            let mut first = true;
            for byte in &mem {
                if first {
                    first = false;
                } else {
                    print!(", ");
                }
                print!("{}", byte);
            }
            println!();

            let cs = get_disassembler(isa)?;

            println!("\nDisassembly:");
            let insns = cs.disasm_all(&mem, 0x0).unwrap();
            for i in insns.iter() {
                println!("{}", i);
            }
        }
    }

    Ok(())
}

fn get_disassembler(isa: &TargetIsa) -> Result<Capstone, String> {
    let cs = match isa.name() {
        "riscv" => return Err(String::from("No disassembler for RiscV")),
        "x86" => {
            if isa.flags().is_64bit() {
                Capstone::new()
                    .x86()
                    .mode(arch::x86::ArchMode::Mode64)
                    .build()
            } else {
                Capstone::new()
                    .x86()
                    .mode(arch::x86::ArchMode::Mode32)
                    .build()
            }
        }
        "arm32" => Capstone::new().arm().mode(arch::arm::ArchMode::Arm).build(),
        "arm64" => {
            Capstone::new()
                .arm64()
                .mode(arch::arm64::ArchMode::Arm)
                .build()
        }
        _ => return Err(String::from("Unknown ISA")),
    };

    cs.map_err(|err| err.to_string())
}

impl Solution {
    pub fn k_length_apart(nums: Vec<i32>, k: i32) -> bool {
        let mut i = 0;
        while i < nums.len() && nums[i] != 1 {
            i += 1;
        }
        let mut prev = i;
        for j in (i + 1)..nums.len() {
            if nums[j] == 1 {
                if j - prev - 1 < k as usize {
                    return false;
                }
                prev = j;
            }
        }
        true
    }
}

/*
The reallocation routine operates in cycles. In each cycle, it finds the memory
bank with the most blocks (ties won by the lowest-numbered memory bank) and
redistributes those blocks among the banks. To do this, it removes all of the
blocks from the selected bank, then moves to the next (by index) memory bank
and inserts one of the blocks. It continues doing this until it runs out of
blocks; if it reaches the last memory bank, it wraps around to the first one.

The debugger would like to know how many redistributions can be done before a
blocks-in-banks configuration is produced that has been seen before.
*/

use std::collections::HashMap;

#[derive(Debug, Clone, Eq, PartialEq, Hash)]
struct Configuration {
    banks: Vec<usize>,
}

impl Configuration {
    pub fn redistribute(&mut self) {
        let idx = self.source_idx();
        let len = self.banks.len();
        let count = self.banks[idx];
        self.banks[idx] = 0;
        for i in 0..count {
            self.banks[(idx + i + 1) % len] += 1;
        }
    }

    fn source_idx(&self) -> usize {
        let mut idx = 0;
        let mut val = self.banks[0];
        for i in 1..self.banks.len() {
            if self.banks[i] > val {
                idx = i;
                val = self.banks[i];
            }
        }
        idx
    }
}

struct ChainLength {
    repeating: usize,
    total: usize,
}

fn chain_length(seed: Configuration) -> ChainLength {
    let mut seen = HashMap::new();

    let mut conf = seed;
    let mut count = 0;
    while !seen.contains_key(&conf) {
        count += 1;
        seen.insert(conf.clone(), count);
        conf.redistribute();
    }

    ChainLength {
        total: count,
        repeating: count - seen[&conf] + 1,
    }
}

#[cfg(test)]
mod test {
    use super::*;

    #[test]
    fn small() {
        let seed = Configuration { banks: vec![0, 2, 7, 0] };
        let len = chain_length(seed);
        assert_eq!(len.total, 5);
        assert_eq!(len.repeating, 4);
    }

    #[test]
    fn main() {
        let seed = Configuration { banks: vec![2, 8, 8, 5, 4, 2, 3, 1, 5, 5, 1, 2, 15, 13, 5, 14] };
        let len = chain_length(seed);
        assert_eq!(len.total, 3156);
        assert_eq!(len.repeating, 1610);
    }
}

