struct Triangle { length : f64, height : f64 }

trait HasArea {
    fn area(&self) -> f64;
}

impl HasArea for Rectangle {
    fn area(&self) -> f64 {
        self.length * self.height
    }
}

fn print_debug<T: Debug>(t: &T){
    println!("{:?}", t);
}

fn area<T: HasArea>(t: &T) -> f64{
    t.area()
}

