#![crate_name = "query_mapper"]
mod query_mapper {
/// A macro that will execute a given SQL query and return a Vector $T of a given
/// struct (wrapped in a Result<$T>) with columns in the result set mapped to
/// fields in the struct.
///
/// The macro comes in two forms: 
/// 
/// The first one takes a struct ($T) and a list of
/// fields ($member), and it will use the field names to map to columns  in the result
/// set with the same name.
///
/// The second one is like the first, but allows you to specify custom mapping between
/// each field and column in the form $member => $key , with $member being the field name
/// in the struct and $key being the column name in the result set
///
/// # Example
///
/// ``` 
/// # #[macro_use] extern crate query_mapper;
/// # extern crate postgres;
/// use postgres::{Connection, SslMode};
///
/// struct Person {
///    id: i32,
///    name: String
/// }
/// # fn main() {
/// # let conn_uri = "postgres://postgres:password@localhost";
/// 
/// let conn = match Connection::connect(conn_uri, &SslMode::None) { Ok(c) => c, Err(m) => return () };
/// 
/// let prepared_sql_string = "SELECT id, name FROM person";
///
/// let result = query_map!(conn, prepared_sql_string, &[],
///     Person { id, name }
/// );
///
/// match result {
///     Ok(r) => {
///         for person in r.iter() {
///             println!("id: {}, name: {}", person.id, person.name);
///     }
/// },
///     Err(m) => println!("{:?}", m),
/// };
///
/// let result2 = query_map!(conn, prepared_sql_string, &[], 
///     Person { id => "id", name => "name" }
/// );
///
/// match result2 {
///     Ok(r) => {
///         for person in r.iter() {
///             println!("id: {}, name: {}", person.id, person.name);
///         }
///     },
///     Err(m) => println!("{:?}", m),
/// };
/// 
/// # }
/// ```
#[macro_export]
macro_rules! query_map {
    // Macro  will auto map struct $T with members $member, asuming that
    // the columns returned by the query match the field names in the struct. 
    // Must pass in all fields in the struct as idents
    ($conn:ident, $query:expr, $params:expr, $T:ident{ $($member:ident),* }) => {
        {
            match $conn.prepare($query) {
                Ok(statement) => {
                    match statement.query($params) {
                        Ok(result) => { 
                            Ok(result.map(|row:postgres::Row| { 
                                $T { $( $member: row.get(stringify!($member)) ),*} 
                            }).collect::<Vec<$T>>()) 
                        },
                        Err(message) => Err(message)
                    }
                },
                Err(message) => Err(message)            
            }
        }
    };
    // Similar to above, but each field is mapped to an expression which should be
    // a string. This allows you specify custom column mapping when column
    // names don't match field names
    ($conn:ident, $query:expr, $params:expr, $T:ident{ $($member:ident => $key:expr),* }) =>{
        {
            match $conn.prepare($query) {
                Ok(statement) => {
                    match statement.query($params) {
                        Ok(result) => {
                            Ok(result.map(|row:postgres::Row| {
                                $T { $( $member: row.get($key) ),* }
                            }).collect::<Vec<$T>>())
                        },
                        Err(message) => Err(message)
                    }
                },
                Err(message) => Err(message)
            }           
        }
    }
}
}

use futures::{future, stream, StreamExt};
use mit_commit::CommitMessage;

use crate::model::{Lints, Problem};

/// Lint a commit message
///
/// # Examples
///
/// ```rust
/// use mit_commit::CommitMessage;
/// use mit_lint::{async_lint, lint, Lints};
/// use tokio::runtime::Runtime;
/// let rt = Runtime::new().unwrap();
/// let actual = rt.block_on(async {
///     async_lint(
///         &CommitMessage::from("An example commit message"),
///         Lints::available().clone(),
///     )
///     .await
/// });
/// assert!(!actual.is_empty());
/// ```
///
/// ```rust
/// use mit_commit::CommitMessage;
/// use tokio::runtime::Runtime;
/// use mit_lint::{Problem, Code, Lints, Lint, async_lint};
///
/// let message:String = "x".repeat(73).into();
/// let expected = vec![Problem::new(
///     "Your subject is longer than 72 characters".into(),
///     "It's important to keep the subject of the commit less than 72 characters because when you look at the git log, that's where it truncates the message. This means that people won't get the entirety of the information in your commit.\n\nPlease keep the subject line 72 characters or under"
///         .into(),
///     Code::SubjectLongerThan72Characters,&message.clone().into(),
/// Some(vec![("Too long".to_string(), 73, 1)]),Some("https://git-scm.com/book/en/v2/Distributed-Git-Contributing-to-a-Project#_commit_guidelines".parse().unwrap()),
/// )];
/// let rt = Runtime::new().unwrap();
/// let actual = rt.block_on(async {
///     async_lint(&CommitMessage::from(message), Lints::new(vec![Lint::SubjectLongerThan72Characters].into_iter().collect())).await
/// });
/// assert_eq!(
///     actual, expected,
///     "Expected {:?}, found {:?}",
///     expected, actual
/// );
/// ```
pub async fn async_lint(commit_message: &CommitMessage<'_>, lints: Lints) -> Vec<Problem> {
    stream::iter(lints.into_iter())
        .filter_map(|lint| future::ready(lint.lint(commit_message)))
        .collect::<Vec<Problem>>()
        .await
}

use std::sync::{
    atomic::{AtomicBool, Ordering::Relaxed},
    mpsc::{sync_channel, Receiver, SyncSender},
};

use crate::*;

static ID_GEN: AtomicUsize = AtomicUsize::new(0);

/// An event that happened to a key that a subscriber is interested in.
#[derive(Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum Event {
    /// A new complete (key, value) pair
    Insert(Arc<[u8]>, IVec),
    /// A deleted key
    Remove(Arc<[u8]>),
}

impl Event {
    /// Return a reference to the key that this `Event` refers to
    pub fn key(&self) -> &[u8] {
        match self {
            Event::Insert(k, ..) | Event::Remove(k) => &*k,
        }
    }
}

impl Clone for Event {
    fn clone(&self) -> Self {
        use self::Event::*;

        match self {
            Insert(k, v) => Insert(k.clone(), v.clone()),
            Remove(k) => Remove(k.clone()),
        }
    }
}

type Senders = Vec<(usize, SyncSender<OneShot<Event>>)>;

/// A subscriber listening on a specified prefix
pub struct Subscriber {
    id: usize,
    rx: Receiver<OneShot<Event>>,
    home: Arc<RwLock<Senders>>,
}

impl Drop for Subscriber {
    fn drop(&mut self) {
        let mut w_senders = self.home.write();
        w_senders.retain(|(id, _)| *id != self.id);
    }
}

impl Iterator for Subscriber {
    type Item = Event;

    fn next(&mut self) -> Option<Event> {
        loop {
            let future_rx = self.rx.recv().ok()?;
            match future_rx.wait() {
                Some(event) => return Some(event),
                None => continue,
            }
        }
    }
}

#[derive(Debug, Default)]
pub(crate) struct Subscriptions {
    watched: RwLock<BTreeMap<Vec<u8>, Arc<RwLock<Senders>>>>,
    ever_used: AtomicBool,
}

impl Subscriptions {
    pub(crate) fn register(&self, prefix: &[u8]) -> Subscriber {
        self.ever_used.store(true, Relaxed);
        let r_mu = {
            let r_mu = self.watched.read();
            if r_mu.contains_key(prefix) {
                r_mu
            } else {
                drop(r_mu);
                let mut w_mu = self.watched.write();
                if !w_mu.contains_key(prefix) {
                    let old = w_mu
                        .insert(prefix.to_vec(), Arc::new(RwLock::new(vec![])));
                    assert!(old.is_none());
                }
                drop(w_mu);
                self.watched.read()
            }
        };

        let (tx, rx) = sync_channel(1024);

        let arc_senders = &r_mu[prefix];
        let mut w_senders = arc_senders.write();

        let id = ID_GEN.fetch_add(1, Relaxed);

        w_senders.push((id, tx));

        Subscriber { id, rx, home: arc_senders.clone() }
    }

    pub(crate) fn reserve<R: AsRef<[u8]>>(
        &self,
        key: R,
    ) -> Option<ReservedBroadcast> {
        if !self.ever_used.load(Relaxed) {
            return None;
        }

        let r_mu = self.watched.read();
        let prefixes = r_mu.iter().filter(|(k, _)| key.as_ref().starts_with(k));

        let mut subscribers = vec![];

        for (_, subs_rwl) in prefixes {
            let subs = subs_rwl.read();

            for (_id, sender) in subs.iter() {
                let (tx, rx) = OneShot::pair();
                if sender.send(rx).is_err() {
                    continue;
                }
                subscribers.push(tx);
            }
        }

        if subscribers.is_empty() {
            None
        } else {
            Some(ReservedBroadcast { subscribers })
        }
    }
}

pub(crate) struct ReservedBroadcast {
    subscribers: Vec<OneShotFiller<Event>>,
}

impl ReservedBroadcast {
    pub fn complete(self, event: Event) {
        let len = self.subscribers.len();
        let mut iter = self.subscribers.into_iter();

        let mut sent = 0;

        while sent + 1 < len {
            sent += 1;
            let tx = iter.next().unwrap();
            tx.fill(event.clone());
        }

        if len != 0 {
            let tx = iter.next().unwrap();
            tx.fill(event);
        }
    }
}

#[test]
fn basic_subscription() {
    let subs = Subscriptions::default();

    let mut s2 = subs.register(&[0]);
    let mut s3 = subs.register(&[0, 1]);
    let mut s4 = subs.register(&[1, 2]);

    let r1 = subs.reserve(b"awft");
    assert!(r1.is_none());

    let mut s1 = subs.register(&[]);

    let k2: Arc<[u8]> = vec![].into();
    let r2 = subs.reserve(&k2).unwrap();
    r2.complete(Event::Insert(k2.clone(), IVec::from(k2.clone())));

    let k3: Arc<[u8]> = vec![0].into();
    let r3 = subs.reserve(&k3).unwrap();
    r3.complete(Event::Insert(k3.clone(), IVec::from(k3.clone())));

    let k4: Arc<[u8]> = vec![0, 1].into();
    let r4 = subs.reserve(&k4).unwrap();
    r4.complete(Event::Remove(k4.clone()));

    let k5: Arc<[u8]> = vec![0, 1, 2].into();
    let r5 = subs.reserve(&k5).unwrap();
    r5.complete(Event::Insert(k5.clone(), IVec::from(k5.clone())));

    let k6: Arc<[u8]> = vec![1, 1, 2].into();
    let r6 = subs.reserve(&k6).unwrap();
    r6.complete(Event::Remove(k6.clone()));

    let k7: Arc<[u8]> = vec![1, 1, 2].into();
    let r7 = subs.reserve(&k7).unwrap();
    drop(r7);

    let k8: Arc<[u8]> = vec![1, 2, 2].into();
    let r8 = subs.reserve(&k8).unwrap();
    r8.complete(Event::Insert(k8.clone(), IVec::from(k8.clone())));

    assert_eq!(s1.next().unwrap().key(), &*k2);
    assert_eq!(s1.next().unwrap().key(), &*k3);
    assert_eq!(s1.next().unwrap().key(), &*k4);
    assert_eq!(s1.next().unwrap().key(), &*k5);
    assert_eq!(s1.next().unwrap().key(), &*k6);
    assert_eq!(s1.next().unwrap().key(), &*k8);

    assert_eq!(s2.next().unwrap().key(), &*k3);
    assert_eq!(s2.next().unwrap().key(), &*k4);
    assert_eq!(s2.next().unwrap().key(), &*k5);

    assert_eq!(s3.next().unwrap().key(), &*k4);
    assert_eq!(s3.next().unwrap().key(), &*k5);

    assert_eq!(s4.next().unwrap().key(), &*k8);
}

