use std::str;

use crate::core::{LinePositionIterKind, QualRecordPosition, SearchPos, SeqRecordPosition};
use crate::LinePositionIter;
use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct LineStore {
    start: usize,
    end: usize,
    seq_pos: Vec<usize>,
    // TODO: performance impact of storing quality positions?
    qual_pos: Vec<usize>,
}

impl SeqRecordPosition for LineStore {
    type SeqLinesKind = LinePositionIterKind;

    #[inline]
    fn init(&mut self) {
        self.seq_pos.clear();
        self.qual_pos.clear();
    }

    #[inline]
    fn set_record_start(&mut self, pos: usize) {
        self.start = pos;
    }

    #[inline]
    fn record_start(&self) -> usize {
        self.start
    }

    #[inline]
    fn set_seq_start(&mut self, pos: usize) {
        self.seq_pos.push(pos);
    }

    #[inline]
    fn add_seq_line_start(&mut self, pos: usize) {
        self.seq_pos.push(pos);
    }

    #[inline]
    fn seq_start(&self) -> usize {
        self.seq_pos[0]
    }

    #[inline]
    fn seq_starts(&self) -> &[usize] {
        self.seq_pos.split_last().unwrap().1
    }

    #[inline]
    fn seq_end(&self) -> usize {
        self.sep_pos()
    }

    #[inline]
    fn set_record_end(&mut self, end: usize, has_line: bool) {
        self.end = end;
        if has_line {
            if self.has_qual() {
                self.qual_pos.push(end);
            } else {
                self.seq_pos.push(end);
            }
        }
    }

    #[inline]
    fn record_end(&self) -> usize {
        self.end
    }

    #[inline]
    fn num_lines(&self) -> usize {
        self.seq_pos.len() + self.qual_pos.len()
    }

    #[inline]
    fn num_seq_lines(&self) -> usize {
        debug_assert!(self.seq_pos.len() > 0);
        self.seq_pos.len() - 1
    }

    #[inline]
    fn seq_lines<'s>(&'s self, buffer: &'s [u8]) -> LinePositionIter<'s> {
        debug_assert!(self.seq_pos.len() > 0);
        LinePositionIter::new(buffer, &self.seq_pos)
    }

    #[inline]
    fn apply_offset(&mut self, offset: isize, _: Option<SearchPos>) {
        self.start = (self.start as isize + offset) as usize;
        for s in &mut self.seq_pos {
            *s = (*s as isize + offset) as usize;
        }
        for s in &mut self.qual_pos {
            *s = (*s as isize + offset) as usize;
        }
    }

    #[inline]
    fn line_offset(&self, _: SearchPos, has_line: bool) -> usize {
        self.seq_pos.len() + self.qual_pos.len() - !has_line as usize
    }
}

impl QualRecordPosition for LineStore {
    type QualLinesKind = LinePositionIterKind;

    #[inline]
    fn set_sep_pos(&mut self, pos: usize, has_line: bool) {
        // in order to obtain proper slices when iterating,
        // we also need the end position of the sequence
        if has_line {
            self.seq_pos.push(pos);
        }
    }

    #[inline]
    fn sep_pos(&self) -> usize {
        *self.seq_pos.last().unwrap()
    }

    #[inline]
    fn set_qual_start(&mut self, pos: usize) {
        self.qual_pos.push(pos);
    }

    #[inline]
    fn add_qual_line_start(&mut self, pos: usize) {
        self.qual_pos.push(pos);
    }

    #[inline]
    fn qual_start(&self) -> usize {
        *self.qual_pos.first().unwrap()
    }

    #[inline]
    fn qual_starts(&self) -> &[usize] {
        self.qual_pos.split_last().unwrap().1
    }

    #[inline]
    fn has_qual(&self) -> bool {
        !self.qual_pos.is_empty()
    }

    #[inline]
    fn num_qual_lines(&self) -> usize {
        self.qual_pos.len().checked_sub(1).unwrap_or(0)
    }

    #[inline]
    fn qual_lines<'s>(&'s self, buffer: &'s [u8]) -> LinePositionIter<'s> {
        debug_assert!(self.qual_pos.len() > 0);
        LinePositionIter::new(buffer, &self.qual_pos)
    }
}

use super::*;

/// Pin type with dynamic mode
///
/// - `P` is port name: `A` for GPIOA, `B` for GPIOB, etc.
/// - `N` is pin number: from `0` to `15`.
pub struct DynamicPin<const P: char, const N: u8> {
    /// Current pin mode
    pub(crate) mode: Dynamic,
}

/// Tracks the current pin state for dynamic pins
pub enum Dynamic {
    InputFloating,
    InputPullUp,
    InputPullDown,
    OutputPushPull,
    OutputOpenDrain,
}

#[derive(Debug, PartialEq)]
pub enum PinModeError {
    IncorrectMode,
}

impl Dynamic {
    pub fn is_input(&self) -> bool {
        use Dynamic::*;
        match self {
            InputFloating | InputPullUp | InputPullDown | OutputOpenDrain => true,
            OutputPushPull => false,
        }
    }
    pub fn is_output(&self) -> bool {
        use Dynamic::*;
        match self {
            InputFloating | InputPullUp | InputPullDown => false,
            OutputPushPull | OutputOpenDrain => true,
        }
    }
}

// For convertion simplify
struct Unknown;

impl<const P: char, const N: u8> DynamicPin<P, N> {
    pub const fn new(mode: Dynamic) -> Self {
        Self { mode }
    }

    #[inline]
    pub fn make_pull_up_input(&mut self) {
        // NOTE(unsafe), we have a mutable reference to the current pin
        Pin::<Unknown, P, N>::new().into_pull_up_input();
        self.mode = Dynamic::InputPullUp;
    }
    #[inline]
    pub fn make_pull_down_input(&mut self) {
        // NOTE(unsafe), we have a mutable reference to the current pin
        Pin::<Unknown, P, N>::new().into_pull_down_input();
        self.mode = Dynamic::InputPullDown;
    }
    #[inline]
    pub fn make_floating_input(&mut self) {
        // NOTE(unsafe), we have a mutable reference to the current pin
        Pin::<Unknown, P, N>::new().into_floating_input();
        self.mode = Dynamic::InputFloating;
    }
    #[inline]
    pub fn make_push_pull_output(&mut self) {
        // NOTE(unsafe), we have a mutable reference to the current pin
        Pin::<Unknown, P, N>::new().into_push_pull_output();
        self.mode = Dynamic::OutputPushPull;
    }
    #[inline]
    pub fn make_push_pull_output_in_state(&mut self, state: PinState) {
        // NOTE(unsafe), we have a mutable reference to the current pin
        Pin::<Unknown, P, N>::new().into_push_pull_output_in_state(state);
        self.mode = Dynamic::OutputPushPull;
    }
    #[inline]
    pub fn make_open_drain_output(&mut self) {
        // NOTE(unsafe), we have a mutable reference to the current pin
        Pin::<Unknown, P, N>::new().into_open_drain_output();
        self.mode = Dynamic::OutputOpenDrain;
    }
    #[inline]
    pub fn make_open_drain_output_in_state(&mut self, state: PinState) {
        // NOTE(unsafe), we have a mutable reference to the current pin
        Pin::<Unknown, P, N>::new().into_open_drain_output_in_state(state);
        self.mode = Dynamic::OutputOpenDrain;
    }

    pub fn set_high(&mut self) -> Result<(), PinModeError> {
        if self.mode.is_output() {
            Pin::<Unknown, P, N>::new()._set_state(PinState::High);
            Ok(())
        } else {
            Err(PinModeError::IncorrectMode)
        }
    }
    pub fn set_low(&mut self) -> Result<(), PinModeError> {
        if self.mode.is_output() {
            Pin::<Unknown, P, N>::new()._set_state(PinState::Low);
            Ok(())
        } else {
            Err(PinModeError::IncorrectMode)
        }
    }

    pub fn is_high(&self) -> Result<bool, PinModeError> {
        self.is_low().map(|b| !b)
    }
    pub fn is_low(&self) -> Result<bool, PinModeError> {
        if self.mode.is_input() {
            Ok(Pin::<Unknown, P, N>::new()._is_low())
        } else {
            Err(PinModeError::IncorrectMode)
        }
    }
}

