            },
        ];

        let tree = parse(tokens).unwrap();

        assert_eq!("(== 5 (> 4 2))", format!("{}", tree));
    }

    #[test]
    fn test_reader() {
        let first = Token {
            t: TokenType::Number,
            lexeme: String::new(),
            literal: Some(TokenLiteral::Number(5.0)),
            line: 1,
        };
        let second = Token {
            t: TokenType::EqualEqual,
            lexeme: String::new(),
            literal: None,
            line: 2,
        };
        let third = Token {
            t: TokenType::Nil,
            lexeme: String::new(),
            literal: None,
            line: 3,
        };
        let tokens = vec![first.clone(), second.clone(), third.clone()];

        let mut reader = Reader::new(tokens);

        assert_eq!(1, reader.line());
        assert_eq!(Some(first.t), reader.peek_type());
        assert_eq!(Some(first), reader.advance());

        assert_eq!(1, reader.line());
        assert_eq!(Some(second.t), reader.peek_type());
        assert_eq!(Some(second), reader.advance());

        assert_eq!(2, reader.line());
        assert_eq!(Some(third.t), reader.peek_type());
        assert_eq!(Some(third), reader.advance());

        assert_eq!(3, reader.line());
        assert_eq!(None, reader.peek_type());
        assert_eq!(None, reader.advance());
    }

    #[test]
    fn test_syncronize_on_error_with_semicolon() {
        let stop_token = Token {
            t: TokenType::Number,
            lexeme: String::new(),
            literal: None,
            line: 3,
        };
        let tokens = vec![
            Token {
                t: TokenType::Plus,
                lexeme: "+".to_owned(),
                literal: None,
                line: 3,
            },
            Token {
                t: TokenType::Number,
                lexeme: String::new(),
                literal: None,
                line: 3,
            },
            Token {
                t: TokenType::Semicolon,
                lexeme: String::new(),
                literal: None,
                line: 3,
            },
            stop_token.clone(),
        ];
        let mut reader = Reader::new(tokens);

        let res = parse_with_reader(&mut reader);

        assert!(res.is_err());
        assert_eq!(Some(stop_token), reader.advance());
    }

    #[test]
    fn test_syncronize_on_error_with_fun() {
        let stop_token = Token {
            t: TokenType::Fun,
            lexeme: String::new(),
            literal: None,
            line: 3,
        };
        let tokens = vec![
            Token {
                t: TokenType::Plus,
                lexeme: "+".to_owned(),
                literal: None,
                line: 3,
            },
            Token {
                t: TokenType::Number,
                lexeme: String::new(),
                literal: None,
                line: 3,
            },
            stop_token.clone(),
        ];
        let mut reader = Reader::new(tokens);

        let res = parse_with_reader(&mut reader);

        assert!(res.is_err());
        assert_eq!(Some(stop_token), reader.advance());
    }

    #[test]
    fn test_error_format() {
        assert_eq!(
            "[line 3] Error: expect ')' after expression",
            format!("{}", Error::RightParenExpected { line: 3 })
        );
        assert_eq!(
            "[line 3] Error: unexpected token: \"foo\"",
            format!(
                "{}",
                Error::UnexpectedToken {
                    line: 3,
                    lexeme: "foo".to_owned()
                }
            )
        );
        assert_eq!(
            "[line 3] Error: expression expected",
            format!("{}", Error::ExpressionExpected { line: 3 })
        );
    }
}

use std::fs;

use clap::Shell;

include!("src/hyperfine/app.rs");

fn main() {
    let min_version = "1.39";

    match version_check::is_min_version(min_version) {
        Some(true) => {}
        // rustc version too small or can't figure it out
        _ => {
            eprintln!("'hyperfine' requires rustc >= {}", min_version);
            std::process::exit(1);
        }
    }

    let var = std::env::var_os("SHELL_COMPLETIONS_DIR").or_else(|| std::env::var_os("OUT_DIR"));
    let outdir = match var {
        None => return,
        Some(outdir) => outdir,
    };
    fs::create_dir_all(&outdir).unwrap();

    let mut app = build_app();
    app.gen_completions("hyperfine", Shell::Bash, &outdir);
    app.gen_completions("hyperfine", Shell::Fish, &outdir);
    app.gen_completions("hyperfine", Shell::Zsh, &outdir);
    app.gen_completions("hyperfine", Shell::PowerShell, &outdir);
}

extern crate gl;
extern crate sdl2;
#[macro_use]
extern crate failure;

pub mod render_gl;
pub mod resources;

use failure::err_msg;
use crate::resources::Resources;
use std::path::Path;

fn main() {
    if let Err(e) = run() {
        println!("{}", failure_to_string(e));
    }
}

fn run() -> Result<(), failure::Error> {
    let res = Resources::from_relative_exe_path(Path::new("assets-08")).unwrap();

    let sdl = sdl2::init().map_err(err_msg)?;
    let video_subsystem = sdl.video().map_err(err_msg)?;

    let gl_attr = video_subsystem.gl_attr();

    gl_attr.set_context_profile(sdl2::video::GLProfile::Core);
    gl_attr.set_context_version(4, 1);

    let window = video_subsystem
        .window("Game", 900, 700)
        .opengl()
        .resizable()
        .build()?;

    let _gl_context = window.gl_create_context().map_err(err_msg)?;
    let gl = gl::Gl::load_with(|s| {
        video_subsystem.gl_get_proc_address(s) as *const std::os::raw::c_void
    });

    // set up shader program

    let shader_program = render_gl::Program::from_res(&gl, &res, "shaders/triangle")?;

    // set up vertex buffer object

    let vertices: Vec<f32> = vec![
        // positions      // colors
        0.5, -0.5, 0.0, 1.0, 0.0, 0.0, // bottom right
        -0.5, -0.5, 0.0, 0.0, 1.0, 0.0, // bottom left
        0.0, 0.5, 0.0, 0.0, 0.0, 1.0, // top
    ];

    let mut vbo: gl::types::GLuint = 0;
    unsafe {
        gl.GenBuffers(1, &mut vbo);
    }

    unsafe {
        gl.BindBuffer(gl::ARRAY_BUFFER, vbo);
        gl.BufferData(
            gl::ARRAY_BUFFER, // target
            (vertices.len() * std::mem::size_of::<f32>()) as gl::types::GLsizeiptr, // size of data in bytes
            vertices.as_ptr() as *const gl::types::GLvoid, // pointer to data
            gl::STATIC_DRAW, // usage
        );
        gl.BindBuffer(gl::ARRAY_BUFFER, 0);
    }

    // set up vertex array object

    let mut vao: gl::types::GLuint = 0;
    unsafe {
        gl.GenVertexArrays(1, &mut vao);
    }

    unsafe {
        gl.BindVertexArray(vao);
        gl.BindBuffer(gl::ARRAY_BUFFER, vbo);

        gl.EnableVertexAttribArray(0); // this is "layout (location = 0)" in vertex shader
        gl.VertexAttribPointer(
            0, // index of the generic vertex attribute ("layout (location = 0)")
            3, // the number of components per generic vertex attribute
            gl::FLOAT, // data type
            gl::FALSE, // normalized (int-to-float conversion)
            (6 * std::mem::size_of::<f32>()) as gl::types::GLint, // stride (byte offset between consecutive attributes)
            std::ptr::null() // offset of the first component
        );
        gl.EnableVertexAttribArray(1); // this is "layout (location = 0)" in vertex shader
        gl.VertexAttribPointer(
            1, // index of the generic vertex attribute ("layout (location = 0)")
            3, // the number of components per generic vertex attribute
            gl::FLOAT, // data type
            gl::FALSE, // normalized (int-to-float conversion)
            (6 * std::mem::size_of::<f32>()) as gl::types::GLint, // stride (byte offset between consecutive attributes)
            (3 * std::mem::size_of::<f32>()) as *const gl::types::GLvoid // offset of the first component
        );

        gl.BindBuffer(gl::ARRAY_BUFFER, 0);
        gl.BindVertexArray(0);
    }

    // set up shared state for window

    unsafe {
        gl.Viewport(0, 0, 900, 700);
        gl.ClearColor(0.3, 0.3, 0.5, 1.0);
    }

    // main loop

    let mut event_pump = sdl.event_pump().map_err(err_msg)?;
    'main: loop {
        for event in event_pump.poll_iter() {
            match event {
                sdl2::event::Event::Quit { .. } => break 'main,
                _ => {}
            }
        }

        unsafe {
            gl.Clear(gl::COLOR_BUFFER_BIT);
        }

        // draw triangle

        shader_program.set_used();
        unsafe {
            gl.BindVertexArray(vao);
            gl.DrawArrays(
                gl::TRIANGLES, // mode
                0,             // starting index in the enabled arrays
                3,             // number of indices to be rendered
            );
        }

        window.gl_swap_window();
    }

    Ok(())
}

pub fn failure_to_string(e: failure::Error) -> String {
    use std::fmt::Write;

    let mut result = String::new();

    for (i, cause) in e
        .iter_chain()
        .collect::<Vec<_>>()
        .into_iter()
        .rev()
        .enumerate()
    {
        if i > 0 {
            let _ = writeln!(&mut result, "   Which caused the following issue:");
        }
        let _ = write!(&mut result, "{}", cause);
        if let Some(backtrace) = cause.backtrace() {
            let backtrace_str = format!("{}", backtrace);
            if backtrace_str.len() > 0 {
                let _ = writeln!(&mut result, " This happened at {}", backtrace);
            } else {
                let _ = writeln!(&mut result);
            }
        } else {
            let _ = writeln!(&mut result);
        }
    }

    result
}

use super::number_stats::{NumberStats, NumberStatsOutput};
use std::collections::BTreeMap;
use tangram_app_common::monitor_event::PredictOutput;

#[derive(Debug, serde::Serialize, serde::Deserialize, Clone)]
#[serde(tag = "type")]
pub enum ProductionPredictionStats {
	#[serde(rename = "regression")]
	Regression(RegressionProductionPredictionStats),
	#[serde(rename = "binary_classification")]
	BinaryClassification(ClassificationProductionPredictionStats),
	#[serde(rename = "multiclass_classification")]
	MulticlassClassification(ClassificationProductionPredictionStats),
}

#[derive(Debug, serde::Serialize, serde::Deserialize, Clone)]
pub struct RegressionProductionPredictionStats {
	stats: Option<NumberStats>,
}

#[derive(Debug, serde::Serialize, serde::Deserialize, Clone)]
pub struct ClassificationProductionPredictionStats {
	pub histogram: BTreeMap<String, u64>,
}

#[derive(Debug)]
pub enum ProductionPredictionStatsOutput {
	Regression(RegressionProductionPredictionStatsOutput),
	BinaryClassification(ClassificationProductionPredictionStatsOutput),
	MulticlassClassification(ClassificationProductionPredictionStatsOutput),
}

#[derive(Debug)]
pub struct RegressionProductionPredictionStatsOutput {
	pub stats: Option<NumberStatsOutput>,
}

#[derive(Debug)]
pub struct ClassificationProductionPredictionStatsOutput {
	pub histogram: Vec<(String, u64)>,
}

impl ProductionPredictionStats {
	pub fn new(model: tangram_model::ModelReader) -> ProductionPredictionStats {
		match model.inner() {
			tangram_model::ModelInnerReader::Regressor(_) => {
				ProductionPredictionStats::Regression(RegressionProductionPredictionStats::new())
			}
			tangram_model::ModelInnerReader::BinaryClassifier(binary_classifier) => {
				let binary_classifier = binary_classifier.read();
				ProductionPredictionStats::BinaryClassification(
					ClassificationProductionPredictionStats::new(vec![
						binary_classifier.negative_class().to_owned(),
						binary_classifier.positive_class().to_owned(),
					]),
				)
			}
			tangram_model::ModelInnerReader::MulticlassClassifier(multiclass_classifier) => {
				let multiclass_classifier = multiclass_classifier.read();
				ProductionPredictionStats::MulticlassClassification(
					ClassificationProductionPredictionStats::new(
						multiclass_classifier
							.classes()
							.iter()
							.map(ToOwned::to_owned)
							.collect(),
					),
				)
			}
		}
	}

	pub fn update(&mut self, value: PredictOutput) {
		match self {
			ProductionPredictionStats::Regression(stats) => stats.update(value),
			ProductionPredictionStats::BinaryClassification(stats) => stats.update(value),
			ProductionPredictionStats::MulticlassClassification(stats) => stats.update(value),
		}
	}

	pub fn merge(&mut self, other: ProductionPredictionStats) {
		match self {
			ProductionPredictionStats::Regression(this) => {
				if let ProductionPredictionStats::Regression(other) = other {
					this.merge(other)
				}
			}
			ProductionPredictionStats::BinaryClassification(this) => {
				if let ProductionPredictionStats::BinaryClassification(other) = other {
					this.merge(other)
				}
			}
			ProductionPredictionStats::MulticlassClassification(this) => {
				if let ProductionPredictionStats::MulticlassClassification(other) = other {
					this.merge(other)
				}
			}
		}
	}

	pub fn finalize(self) -> ProductionPredictionStatsOutput {
		match self {
			ProductionPredictionStats::Regression(stats) => {
				ProductionPredictionStatsOutput::Regression(stats.finalize())
			}
			ProductionPredictionStats::BinaryClassification(stats) => {
				ProductionPredictionStatsOutput::BinaryClassification(stats.finalize())
			}
			ProductionPredictionStats::MulticlassClassification(stats) => {
				ProductionPredictionStatsOutput::MulticlassClassification(stats.finalize())
			}
		}
	}
}

impl RegressionProductionPredictionStats {
	fn new() -> RegressionProductionPredictionStats {
		RegressionProductionPredictionStats { stats: None }
	}

	pub fn update(&mut self, value: PredictOutput) {
		let value = match value {
			PredictOutput::Regression(value) => value,
			_ => unreachable!(),
		};
		match &mut self.stats {
			None => {
				self.stats.replace(NumberStats::new(value.value));
			}
			Some(stats) => stats.update(value.value),
		};
	}

	pub fn merge(&mut self, other: RegressionProductionPredictionStats) {
		match &mut self.stats {
			None => self.stats = other.stats,
			Some(stats) => {
				if let Some(other) = other.stats {
					stats.merge(other)
				}
			}
		};
	}

	pub fn finalize(self) -> RegressionProductionPredictionStatsOutput {
		let stats = self.stats.map(|s| s.finalize());
		RegressionProductionPredictionStatsOutput { stats }
	}
}

impl ClassificationProductionPredictionStats {
	pub fn new(classes: Vec<String>) -> ClassificationProductionPredictionStats {
		let histogram = classes.into_iter().map(|class| (class, 0)).collect();
		ClassificationProductionPredictionStats { histogram }
	}

	pub fn update(&mut self, value: PredictOutput) {
		let class_name = match value {
			PredictOutput::BinaryClassification(value) => value.class_name,
			PredictOutput::MulticlassClassification(value) => value.class_name,
			_ => unreachable!(),
		};
		if let Some(count) = self.histogram.get_mut(&class_name) {
			*count += 1;
		}
	}

	pub fn merge(&mut self, other: ClassificationProductionPredictionStats) {
		for (value, count) in other.histogram.into_iter() {
			*self.histogram.entry(value).or_insert(0) += count;
		}
	}

	pub fn finalize(self) -> ClassificationProductionPredictionStatsOutput {
		ClassificationProductionPredictionStatsOutput {
			histogram: self.histogram.into_iter().collect(),
		}
	}
}

use std::env;
use std::path::{Path, PathBuf};

#[cfg(feature = "bundled")]
fn build_libevent(libevent_path: impl AsRef<std::path::Path>) -> PathBuf {
    let mut config = cmake::Config::new(libevent_path);

    if !cfg!(feature = "threading") {
        config.define("EVENT__DISABLE_THREAD_SUPPORT", "ON");
    } else {
        config.define("EVENT__DISABLE_THREAD_SUPPORT", "OFF");
    }

    if cfg!(feature = "openssl") || cfg!(feature = "openssl_bundled") {
        config.define("EVENT__DISABLE_OPENSSL", "OFF");

        if cfg!(feature = "openssl_bundled") {
            if !cfg!(feature = "threading") {
                unimplemented!(
                    "feature `openssl_bundled` without feature `threading` \
                    not currently supported as `CMAKE_USE_PTHREADS_INIT` gets injected \
                    into libevent cmake build, causing build failures"
                );
            }

            println!("cargo:rustc-link-lib=static=ssl");
            println!("cargo:rustc-link-lib=static=crypto");
        } else {
            println!("cargo:rustc-link-lib=ssl");
            println!("cargo:rustc-link-lib=crypto");
        }

        config.register_dep("openssl");

        let openssl_root = if let Ok(root) = env::var("DEP_OPENSSL_ROOT") {
            root
        } else {
            let include_str = env::var("DEP_OPENSSL_INCLUDE").unwrap();
            let include_dir = std::path::Path::new(&include_str);
            let root_dir = format!("{}", include_dir.parent().unwrap().display());
            env::set_var("DEP_OPENSSL_ROOT", &root_dir);
            root_dir
        };

        config.define("OPENSSL_ROOT_DIR", openssl_root);
    } else {
        config.define("EVENT__DISABLE_OPENSSL", "ON");
    }

    // TODO: Or just both and decide elsewhere?
    if cfg!(feature = "static") {
        config.define("EVENT__LIBRARY_TYPE", "STATIC");
    } else {
        config.define("EVENT__LIBRARY_TYPE", "SHARED");
    }

    // Disable unnecessary dev-only features
    {
        config
            .define("EVENT__DISABLE_BENCHMARK", "ON")
            .define("EVENT__DISABLE_TESTS", "ON")
            .define("EVENT__DISABLE_REGRESS", "ON")
            .define("EVENT__DISABLE_SAMPLES", "ON");

        // TODO: Address policy warnings for cross-compilation?
        /*config.define("CMAKE_POLICY_DEFAULT_CMP0056", "NEW")
        .define("CMAKE_POLICY_DEFAULT_CMP0066", "NEW")*/
    }

    // TODO: Can we tap into "-vv" cargo argument?
    if cfg!(feature = "verbose_build") {
        config.very_verbose(true);
    }

    let dst = config.build();

    println!("cargo:rustc-link-search={}/lib", dst.display());

    // Library 'event' is considered deprecated, so link each sub-component
    // individually.
    println!("cargo:rustc-link-lib=static=event_core");
    println!("cargo:rustc-link-lib=static=event_extra");

    if cfg!(feature = "openssl") || cfg!(feature = "openssl_bundled") {
        println!("cargo:rustc-link-lib=static=event_openssl");
    }

    if cfg!(feature = "threading") {
        println!("cargo:rustc-link-lib=static=event_pthreads");
    }

    println!("cargo:include={}/include", dst.display());

    dst
}

#[cfg(not(feature = "bundled"))]
fn run_pkg_config() -> Option<Vec<String>> {
    use std::collections::HashSet;

    let mut pkg = pkg_config::Config::new();
    pkg.cargo_metadata(true)
        .atleast_version("2")
        .statik(cfg!(feature = "static"));

    let mut include_paths = HashSet::new();

    if let Ok(mut lib) = pkg.probe("libevent_core").or_else(|_| pkg.probe("libevent")) {
        include_paths.extend(lib.include_paths.drain(..));
    } else {
        return None;
    }

    {
        match pkg.probe("libevent_extra") {
            Ok(mut lib) => include_paths.extend(lib.include_paths.drain(..)),
            Err(e) => println!("Failed to find libevent_extra: {:?}", e),
        }
    }

    if cfg!(feature = "openssl") {
        let mut lib = pkg.cargo_metadata(true).probe("libevent_openssl").unwrap();
        include_paths.extend(lib.include_paths.drain(..));
    }

    if cfg!(feature = "threading") {
        let mut lib = pkg.cargo_metadata(true).probe("libevent_pthreads").unwrap();
        include_paths.extend(lib.include_paths.drain(..));
    }

    let include_paths = include_paths
        .drain()
        .map(|path| {
            let path_s = path.into_os_string().into_string().unwrap();
            println!("cargo:include={}", &path_s);
            path_s
        })
        .collect();

    Some(include_paths)
}

#[cfg(feature = "bundled")]
fn find_libevent() -> Option<Vec<String>> {
    use std::process::Command;

    if !Path::new("libevent/.git").exists() {
        let _ = Command::new("git")
            .args(&["submodule", "update", "--init"])
            .status();
    } else {
        let _ = Command::new("git")
            .args(&["submodule", "update", "--recursive"])
            .status();
    }

    Some(vec![format!(
        "{}/include",
        build_libevent("libevent").display()
    )])
}
#[cfg(not(feature = "bundled"))]
fn find_libevent() -> Option<Vec<String>> {
    run_pkg_config()
}

#[cfg(feature = "buildtime_bindgen")]
fn generate_bindings(include_paths: Vec<String>, out_path: impl AsRef<Path>) {
    println!("cargo:rerun-if-changed=libevent");
    println!("cargo:rerun-if-changed=wrapper.h");

    let target = env::var("TARGET").unwrap();
    let host = env::var("HOST").unwrap();

    let mut builder = bindgen::Builder::default();

    if cfg!(feature = "verbose_build") {
        builder = builder.clang_arg("-v");
    }

    if target != host {
        // TODO: Is it necessary to specify target in clang_arg?
        // Ref: https://github.com/rust-lang/rust-bindgen/issues/1780
    }

    // Let bindgen know about all include paths that were found.
    for path in include_paths {
        builder = builder.clang_arg(format!("-I{}", path));
    }

    let bindings = builder
        .header("wrapper.h")
        .header("libevent/include/event2/http.h")
        .header("libevent/include/event2/buffer.h")
        .header("libevent/include/event2/bufferevent.h")
        .header("libevent/include/event2/bufferevent_ssl.h")
        // Enable for more readable bindings
        // .rustfmt_bindings(true)
        // Fixes a bug with a duplicated const
        .blacklist_item("IPPORT_RESERVED")
        .generate()
        .expect("Failed to generate bindings");

    bindings
        .write_to_file(out_path.as_ref().join("bindings.rs"))
        .expect("Failed to write bindings");
}

#[cfg(not(feature = "buildtime_bindgen"))]
fn generate_bindings(_include_paths: Vec<String>, out_path: impl AsRef<Path>) {
    use std::fs;
    let in_path = env::var("LIBEVENT_SYS_BINDINGS_FILE")
        .expect("LIBEVENT_SYS_BINDINGS_FILE should be populated if buildtime_bindgen feature is not enabled");
    fs::copy(in_path, out_path.as_ref().join("bindings.rs"))
        .expect("Failed to copy bindings to output destination");
}

fn main() {
    if cfg!(feature = "verbose_build") {
        for (key, val) in env::vars() {
            println!("{}: {}", key, val);
        }
        let args: Vec<String> = env::args().collect();
        println!("args: {:?}", args);
    }

    let include_paths = find_libevent().expect("No include paths for libevent found");

    let out_path = PathBuf::from(env::var("OUT_DIR").unwrap());
    generate_bindings(include_paths, out_path);
}

