use std::borrow::Cow;

use reqwest::Url;
use serde::Deserialize;

use crate::helpers::window;
use crate::Result;

#[derive(Debug, Clone, PartialEq, Deserialize)]
pub(crate) struct Manifest {
    pub site_title: String,
    pub endpoint: String,
    pub asset_base_url: String,
}

impl Manifest {
    pub(crate) async fn fetch() -> Result<Self> {
        let href = window().location().href().expect("href is not available.");

        let base_url = reqwest::Url::parse(&href).expect("href is not valid.");
        let url = base_url.join("manifest.toml").unwrap();

        let manifest_str = reqwest::get(url).await?.text().await?;

        Ok(toml::from_str(manifest_str.as_str())?)
    }

    pub fn get_asset_url<S: AsRef<str>>(&self, partial: S) -> Result<String> {
        let url_base: Cow<'_, str> = if !self.asset_base_url.ends_with('/') {
            format!("{}/", self.asset_base_url).into()
        } else {
            self.asset_base_url.as_str().into()
        };

        let url = Url::parse(url_base.as_ref())?;

        Ok(url.join(partial.as_ref())?.into_string())
    }
}

//! Lexes source code and parses delimiters according to a simple
//! regex-based parser.

use std::borrow::Borrow;
use std::ffi::OsStr;

use crate::lines::NewlinePositions;
use crate::positions::SingleLineSpan;
use crate::syntax::Syntax;
use regex::Regex;
use typed_arena::Arena;

pub struct Language {
    pub name: String,
    atom_patterns: Vec<Regex>,
    comment_patterns: Vec<Regex>,
    open_delimiter_pattern: Regex,
    close_delimiter_pattern: Regex,
}

pub fn from_extension(extension: &OsStr) -> Option<Language> {
    match extension.to_string_lossy().borrow() {
        "clj" => Some(Language {
            name: "Clojure".into(),
            atom_patterns: vec![
                // Numbers
                Regex::new(r"[0-9]+").unwrap(),
                // Symbols (e.g. variable names)
                Regex::new(r":?[a-zA-Z0-9_>+=-]+").unwrap(),
                // Operators
                Regex::new(r"[`'~@&]").unwrap(),
                // Double-quoted strings
                Regex::new(r#""((\\.)|[^"])*""#).unwrap(),
            ],
            comment_patterns: vec![Regex::new(r";.*").unwrap()],
            open_delimiter_pattern: Regex::new(r"(\[|\{|\()").unwrap(),
            close_delimiter_pattern: Regex::new(r"(\]|\}|\))").unwrap(),
        }),
        "css" => Some(Language {
            name: "CSS".into(),
            atom_patterns: vec![
                // Numbers
                Regex::new(r"[0-9]+").unwrap(),
                // Symbols
                Regex::new(r"[.a-zA-Z0-9_]+").unwrap(),
                // Punctuation
                Regex::new(r"[:;]").unwrap(),
                // Double-quoted strings
                Regex::new(r#""((\\.)|[^"])*""#).unwrap(),
                // Single quoted strings
                Regex::new(r"'((\\')|[^'])*'").unwrap(),
            ],
            comment_patterns: vec![
                // Multi-line comments
                Regex::new(r"/\*(?s:.)*?\*/").unwrap(),
            ],
            open_delimiter_pattern: Regex::new(r"(\[|\{|\()").unwrap(),
            close_delimiter_pattern: Regex::new(r"(\]|\}|\))").unwrap(),
        }),
        "el" => Some(Language {
            name: "Emacs Lisp".into(),
            atom_patterns: vec![
                // Numbers
                Regex::new(r"[0-9]+").unwrap(),
                // Symbols (e.g. variable names)
                Regex::new(r"[a-zA-Z0-9_?:/*+=<>-]+").unwrap(),
                // Operators
                Regex::new(r"[`',#.&@]").unwrap(),
                // Double-quoted strings
                Regex::new(r#""((\\.)|[^"])*""#).unwrap(),
            ],
            comment_patterns: vec![Regex::new(r";.*").unwrap()],
            open_delimiter_pattern: Regex::new(r"(\[|\{|\()").unwrap(),
            close_delimiter_pattern: Regex::new(r"(\]|\}|\))").unwrap(),
        }),
        "go" => Some(Language {
            name: "Go".into(),
            atom_patterns: vec![
                // Numbers
                Regex::new(r"[0-9]+").unwrap(),
                // Symbols (e.g. variable names)
                Regex::new(r"[.a-zA-Z0-9_]+").unwrap(),
                // Two character operators
                Regex::new(r"(!=|:=|&&|\|\|)").unwrap(),
                // Single character operators
                Regex::new(r"[.;:,=&!*+-]").unwrap(),
                // Double-quoted strings
                Regex::new(r#""((\\.)|[^"])*""#).unwrap(),
            ],
            comment_patterns: vec![
                // Single line comments
                Regex::new("//.*(\n|$)").unwrap(),
                // Multi-line comments
                Regex::new(r"/\*(?s:.)*?\*/").unwrap(),
            ],
            open_delimiter_pattern: Regex::new(r"(\[|\{|\()").unwrap(),
            close_delimiter_pattern: Regex::new(r"(\]|\}|\))").unwrap(),
        }),
        "js" => Some(Language {
            name: "JavaScript".into(),
            atom_patterns: vec![
                // Numbers
                Regex::new(r"[0-9]+").unwrap(),
                // Symbols (e.g. variable names)
                Regex::new(r"[.a-zA-Z0-9_]+").unwrap(),
                // Two character operators
                Regex::new(r"(&&|\|\||\+\+|--|\*\*)").unwrap(),
                // Single character operators
                Regex::new(r"[=<>/*+?:;,-]").unwrap(),
                // Double-quoted strings
                Regex::new(r#""((\\.)|[^"])*""#).unwrap(),
                // Single quoted strings
                Regex::new(r"'((\\')|[^'])*'").unwrap(),
                // Backtick strings
                Regex::new(r"`((\\`)|[^`])*1`").unwrap(),
            ],
            comment_patterns: vec![
                // Single line comments
                Regex::new("//.*(\n|$)").unwrap(),
                // Multi-line comments
                Regex::new(r"/\*(?s:.)*?\*/").unwrap(),
            ],
            open_delimiter_pattern: Regex::new(r"(\[|\{|\()").unwrap(),
            close_delimiter_pattern: Regex::new(r"(\]|\}|\))").unwrap(),
        }),
        "json" => Some(Language {
            name: "JSON".into(),
            atom_patterns: vec![
                // Numbers
                Regex::new(r"[0-9]+").unwrap(),
                // Booleans
                Regex::new(r"(true)|(false)|(null)").unwrap(),
                // Punctuation
                Regex::new(r"[:,]").unwrap(),
                // Double-quoted strings
                Regex::new(r#""((\\.)|[^"])*""#).unwrap(),
            ],
            comment_patterns: vec![],
            open_delimiter_pattern: Regex::new(r"(\[|\{)").unwrap(),
            close_delimiter_pattern: Regex::new(r"(\]|\})").unwrap(),
        }),
        "ml" | "mli" => Some(Language {
            name: "OCaml".into(),
            atom_patterns: vec![
                // Numbers
                Regex::new(r"[0-9]+").unwrap(),
                // Symbols (e.g. variable names)
                Regex::new(r"[.a-zA-Z0-9_]+").unwrap(),
                // Two character operators
                Regex::new(r"(->|<-|:=|&&|\|\|)").unwrap(),
                // Single character operators
                Regex::new(r"[?~=<>/*+,&|:;'#!-]").unwrap(),
                // Double-quoted strings
                Regex::new(r#""((\\.)|[^"])*""#).unwrap(),
            ],
            comment_patterns: vec![
                // Multi-line comments
                Regex::new(r"\(\*(?s:.)*?\*\)").unwrap(),
            ],
            open_delimiter_pattern: Regex::new(r"(\[|\{|\()").unwrap(),
            close_delimiter_pattern: Regex::new(r"(\]|\}|\))").unwrap(),
        }),
        "rs" => Some(Language {
            name: "Rust".into(),
            atom_patterns: vec![
                // Numbers
                Regex::new(r"[0-9]+").unwrap(),
                // Single quoted character 'a' or '\n', trying to avoid matching
                // lifetimes.
                Regex::new(r"'..?'").unwrap(),
                // Lifetimes
                Regex::new(r"'[a-z_]+").unwrap(),
                // Bindings in macros.
                Regex::new(r"\$[a-z_]+").unwrap(),
                // Symbols (e.g. variable names)
                Regex::new(r"[a-zA-Z0-9_]+!?").unwrap(),
                // Two character operators
                Regex::new(r"(::|&&|\|\||\.\.|=>|<=|>=|==|!=|->)").unwrap(),
                // Single character operators
                // | is a delimiter for lambdas, but also used in pattern matching.
                Regex::new(r"[.&=<>/*+:;,|#!?$-]").unwrap(),
                // Double-quoted strings
                Regex::new(r#""((\\.)|[^"])*""#).unwrap(),
            ],
            comment_patterns: vec![
                // Single line comments
                Regex::new("//.*(\n|$)").unwrap(),
                // Multi-line comments
                Regex::new(r"/\*(?s:.)*?\*/").unwrap(),
            ],
            open_delimiter_pattern: Regex::new(r"(\[|\{|\()").unwrap(),
            close_delimiter_pattern: Regex::new(r"(\]|\}|\))").unwrap(),
        }),
        _ => None,
    }
}

/// Parse `s` according to `lang`.
pub fn parse<'a>(arena: &'a Arena<Syntax<'a>>, s: &str, lang: &Language) -> Vec<&'a Syntax<'a>> {
    let nl_pos = NewlinePositions::from(s);
    parse_from(arena, s, &nl_pos, lang, &mut ParseState::new())
}

enum LexKind {
    Comment,
    Atom,
    OpenDelimiter,
    CloseDelimiter,
}

fn parse_from<'a>(
    arena: &'a Arena<Syntax<'a>>,
    s: &str,
    nl_pos: &NewlinePositions,
    lang: &Language,
    state: &mut ParseState,
) -> Vec<&'a Syntax<'a>> {
    let mut result: Vec<&'a Syntax<'a>> = vec![];

    while state.str_i < s.len() {
        let mut current_match: Option<(LexKind, regex::Match)> = None;

        for pattern in &lang.comment_patterns {
            if let Some(m) = pattern.find(&s[state.str_i..]) {
                match current_match {
                    Some((_, prev_m)) if prev_m.start() <= m.start() => {}
                    _ => {
                        current_match = Some((LexKind::Comment, m));
                    }
                }
            }
        }

        for pattern in &lang.atom_patterns {
            if let Some(m) = pattern.find(&s[state.str_i..]) {
                match current_match {
                    Some((_, prev_m)) if prev_m.start() <= m.start() => {}
                    _ => {
                        current_match = Some((LexKind::Atom, m));
                    }
                }
            }
        }

        if let Some(m) = lang.open_delimiter_pattern.find(&s[state.str_i..]) {
            match current_match {
                Some((_, prev_m)) if prev_m.start() <= m.start() => {}
                _ => {
                    current_match = Some((LexKind::OpenDelimiter, m));
                }
            }
        };

        if let Some(m) = lang.close_delimiter_pattern.find(&s[state.str_i..]) {
            match current_match {
                Some((_, prev_m)) if prev_m.start() <= m.start() => {}
                _ => {
                    current_match = Some((LexKind::CloseDelimiter, m));
                }
            }
        };

        match current_match {
            Some((match_kind, m)) => match match_kind {
                LexKind::Comment => {
                    let atom = Syntax::new_comment(
                        arena,
                        nl_pos.from_offsets(state.str_i + m.start(), state.str_i + m.end()),
                        m.as_str(),
                    );
                    result.push(atom);
                    state.str_i += m.end();
                }
                LexKind::Atom => {
                    let atom = Syntax::new_atom(
                        arena,
                        nl_pos.from_offsets(state.str_i + m.start(), state.str_i + m.end()),
                        m.as_str(),
                    );
                    result.push(atom);
                    state.str_i += m.end();
                }
                LexKind::OpenDelimiter => {
                    let start = state.str_i;

                    state.str_i += m.end();
                    let children = parse_from(arena, s, nl_pos, lang, state);
                    let (close_brace, close_pos) = state.close_brace.take().unwrap_or((
                        "UNCLOSED".into(),
                        nl_pos.from_offsets(state.str_i, state.str_i + 1),
                    ));

                    let open_pos = nl_pos.from_offsets(start + m.start(), start + m.end());
                    let items = Syntax::new_list(
                        arena,
                        m.as_str(),
                        open_pos,
                        children,
                        &close_brace,
                        close_pos,
                    );
                    result.push(items);
                }
                LexKind::CloseDelimiter => {
                    state.close_brace = Some((
                        m.as_str().into(),
                        nl_pos.from_offsets(state.str_i + m.start(), state.str_i + m.end()),
                    ));
                    state.str_i += m.end();
                    return result;
                }
            },
            None => break,
        };
    }

    result
}

#[derive(Debug, Clone)]
struct ParseState {
    str_i: usize,
    close_brace: Option<(String, Vec<SingleLineSpan>)>,
}

impl ParseState {
    fn new() -> Self {
        ParseState {
            str_i: 0,
            close_brace: None,
        }
    }
}

