//! Handles translation of callees as well as other call-related
//! things.  Callees are a superset of normal rust values and sometimes
//! have different representations.  In particular, top-level fn items
//! and methods are represented as just a fn ptr and not a full
//! closure.

pub use self::CalleeData::*;

use arena::TypedArena;
use llvm::{self, ValueRef, get_params};
use rustc::hir::def_id::DefId;
use rustc::ty::subst::Substs;
use rustc::traits;
use abi::{Abi, FnType};
use attributes;
use base;
use base::*;
use build::*;
use closure;
use common::{self, Block, Result, CrateContext, FunctionContext, SharedCrateContext};
use consts;
use debuginfo::DebugLoc;
use declare;
use meth;
use monomorphize::{self, Instance};
use trans_item::TransItem;
use type_of;
use Disr;
use rustc::ty::{self, Ty, TypeFoldable};
use rustc::hir;

use syntax_pos::DUMMY_SP;

#[derive(Debug)]
pub enum CalleeData {
    /// Constructor for enum variant/tuple-like-struct.
    NamedTupleConstructor(Disr),

    /// Function pointer.
    Fn(ValueRef),

    Intrinsic,

    /// Trait object found in the vtable at that index.
    Virtual(usize)
}

#[derive(Debug)]
pub struct Callee<'tcx> {
    pub data: CalleeData,
    pub ty: Ty<'tcx>
}

impl<'tcx> Callee<'tcx> {
    /// Function pointer.
    pub fn ptr(llfn: ValueRef, ty: Ty<'tcx>) -> Callee<'tcx> {
        Callee {
            data: Fn(llfn),
            ty: ty
        }
    }

    /// Trait or impl method call.
    pub fn method_call<'blk>(bcx: Block<'blk, 'tcx>,
                             method_call: ty::MethodCall)
                             -> Callee<'tcx> {
        let method = bcx.tcx().tables().method_map[&method_call];
        Callee::method(bcx, method)
    }

    /// Trait or impl method.
    pub fn method<'blk>(bcx: Block<'blk, 'tcx>,
                        method: ty::MethodCallee<'tcx>) -> Callee<'tcx> {
        let substs = bcx.fcx.monomorphize(&method.substs);
        Callee::def(bcx.ccx(), method.def_id, substs)
    }

    /// Function or method definition.
    pub fn def<'a>(ccx: &CrateContext<'a, 'tcx>,
                   def_id: DefId,
                   substs: &'tcx Substs<'tcx>)
                   -> Callee<'tcx> {
        let tcx = ccx.tcx();

        if let Some(trait_id) = tcx.trait_of_item(def_id) {
            return Callee::trait_method(ccx, trait_id, def_id, substs);
        }

        let fn_ty = def_ty(ccx.shared(), def_id, substs);
        if let ty::TyFnDef(.., f) = fn_ty.sty {
            if f.abi == Abi::RustIntrinsic || f.abi == Abi::PlatformIntrinsic {
                return Callee {
                    data: Intrinsic,
                    ty: fn_ty
                };
            }
        }

        // FIXME(eddyb) Detect ADT constructors more efficiently.
        if let Some(adt_def) = fn_ty.fn_ret().skip_binder().ty_adt_def() {
            if let Some(v) = adt_def.variants.iter().find(|v| def_id == v.did) {
                return Callee {
                    data: NamedTupleConstructor(Disr::from(v.disr_val)),
                    ty: fn_ty
                };
            }
        }

        let (llfn, ty) = get_fn(ccx, def_id, substs);
        Callee::ptr(llfn, ty)
    }

    /// Trait method, which has to be resolved to an impl method.
    pub fn trait_method<'a>(ccx: &CrateContext<'a, 'tcx>,
                            trait_id: DefId,
                            def_id: DefId,
                            substs: &'tcx Substs<'tcx>)
                            -> Callee<'tcx> {
        let tcx = ccx.tcx();

        let trait_ref = ty::TraitRef::from_method(tcx, trait_id, substs);
        let trait_ref = tcx.normalize_associated_type(&ty::Binder(trait_ref));
        match common::fulfill_obligation(ccx.shared(), DUMMY_SP, trait_ref) {
            traits::VtableImpl(vtable_impl) => {
                let name = tcx.item_name(def_id);
                let (def_id, substs) = traits::find_method(tcx, name, substs, &vtable_impl);

                // Translate the function, bypassing Callee::def.
                // That is because default methods have the same ID as the
                // trait method used to look up the impl method that ended
                // up here, so calling Callee::def would infinitely recurse.
                let (llfn, ty) = get_fn(ccx, def_id, substs);
                Callee::ptr(llfn, ty)
            }
            traits::VtableClosure(vtable_closure) => {
                // The substitutions should have no type parameters remaining
                // after passing through fulfill_obligation
                let trait_closure_kind = tcx.lang_items.fn_trait_kind(trait_id).unwrap();
                let instance = Instance::new(def_id, substs);
                let llfn = closure::trans_closure_method(ccx,
                                                         vtable_closure.closure_def_id,
                                                         vtable_closure.substs,
                                                         instance,
                                                         trait_closure_kind);

                let method_ty = def_ty(ccx.shared(), def_id, substs);
                Callee::ptr(llfn, method_ty)
            }
            traits::VtableFnPointer(vtable_fn_pointer) => {
                let trait_closure_kind = tcx.lang_items.fn_trait_kind(trait_id).unwrap();
                let instance = Instance::new(def_id, substs);
                let llfn = trans_fn_pointer_shim(ccx, instance,
                                                 trait_closure_kind,
                                                 vtable_fn_pointer.fn_ty);

                let method_ty = def_ty(ccx.shared(), def_id, substs);
                Callee::ptr(llfn, method_ty)
            }
            traits::VtableObject(ref data) => {
                Callee {
                    data: Virtual(tcx.get_vtable_index_of_object_method(data, def_id)),
                    ty: def_ty(ccx.shared(), def_id, substs)
                }
            }
            vtable => {
                bug!("resolved vtable bad vtable {:?} in trans", vtable);
            }
        }
    }

    /// Get the abi::FnType for a direct call. Mainly deals with the fact
    /// that a Virtual call doesn't take the vtable, like its shim does.
    /// The extra argument types are for variadic (extern "C") functions.
    pub fn direct_fn_type<'a>(&self, ccx: &CrateContext<'a, 'tcx>,
                              extra_args: &[Ty<'tcx>]) -> FnType {
        let abi = self.ty.fn_abi();
        let sig = ccx.tcx().erase_late_bound_regions_and_normalize(self.ty.fn_sig());
        let mut fn_ty = FnType::unadjusted(ccx, abi, &sig, extra_args);
        if let Virtual(_) = self.data {
            // Don't pass the vtable, it's not an argument of the virtual fn.
            fn_ty.args[1].ignore();
        }
        fn_ty.adjust_for_abi(ccx, abi, &sig);
        fn_ty
    }

    /// This behemoth of a function translates function calls. Unfortunately, in
    /// order to generate more efficient LLVM output at -O0, it has quite a complex
    /// signature (refactoring this into two functions seems like a good idea).
    ///
    /// In particular, for lang items, it is invoked with a dest of None, and in
    /// that case the return value contains the result of the fn. The lang item must
    /// not return a structural type or else all heck breaks loose.
    ///
    /// For non-lang items, `dest` is always Some, and hence the result is written
    /// into memory somewhere. Nonetheless we return the actual return value of the
    /// function.
    pub fn call<'a, 'blk>(self, bcx: Block<'blk, 'tcx>,
                          debug_loc: DebugLoc,
                          args: &[ValueRef],
                          dest: Option<ValueRef>)
                          -> Result<'blk, 'tcx> {
        trans_call_inner(bcx, debug_loc, self, args, dest)
    }

    /// Turn the callee into a function pointer.
    pub fn reify<'a>(self, ccx: &CrateContext<'a, 'tcx>) -> ValueRef {
        match self.data {
            Fn(llfn) => llfn,
            Virtual(_) => meth::trans_object_shim(ccx, self),
            NamedTupleConstructor(disr) => match self.ty.sty {
                ty::TyFnDef(def_id, substs, _) => {
                    let instance = Instance::new(def_id, substs);
                    if let Some(&llfn) = ccx.instances().borrow().get(&instance) {
                        return llfn;
                    }

                    let sym = ccx.symbol_map().get_or_compute(ccx.shared(),
                                                              TransItem::Fn(instance));
                    assert!(!ccx.codegen_unit().contains_item(&TransItem::Fn(instance)));
                    let lldecl = declare::define_internal_fn(ccx, &sym, self.ty);
                    base::trans_ctor_shim(ccx, def_id, substs, disr, lldecl);
                    ccx.instances().borrow_mut().insert(instance, lldecl);

                    lldecl
                }
                _ => bug!("expected fn item type, found {}", self.ty)
            },
            Intrinsic => bug!("intrinsic {} getting reified", self.ty)
        }
    }
}

/// Given a DefId and some Substs, produces the monomorphic item type.
fn def_ty<'a, 'tcx>(shared: &SharedCrateContext<'a, 'tcx>,
                    def_id: DefId,
                    substs: &'tcx Substs<'tcx>)
                    -> Ty<'tcx> {
    let ty = shared.tcx().item_type(def_id);
    monomorphize::apply_param_substs(shared, substs, &ty)
}

/// Translates an adapter that implements the `Fn` trait for a fn
/// pointer. This is basically the equivalent of something like:
///
/// ```
/// impl<'a> Fn(&'a int) -> &'a int for fn(&int) -> &int {
///     extern "rust-abi" fn call(&self, args: (&'a int,)) -> &'a int {
///         (*self)(args.0)
///     }
/// }
/// ```
///
/// but for the bare function type given.
fn trans_fn_pointer_shim<'a, 'tcx>(
    ccx: &'a CrateContext<'a, 'tcx>,
    method_instance: Instance<'tcx>,
    closure_kind: ty::ClosureKind,
    bare_fn_ty: Ty<'tcx>)
    -> ValueRef
{
    let _icx = push_ctxt("trans_fn_pointer_shim");
    let tcx = ccx.tcx();

    // Normalize the type for better caching.
    let bare_fn_ty = tcx.normalize_associated_type(&bare_fn_ty);

    // If this is an impl of `Fn` or `FnMut` trait, the receiver is `&self`.
    let is_by_ref = match closure_kind {
        ty::ClosureKind::Fn | ty::ClosureKind::FnMut => true,
        ty::ClosureKind::FnOnce => false,
    };

    let llfnpointer = match bare_fn_ty.sty {
        ty::TyFnDef(def_id, substs, _) => {
            // Function definitions have to be turned into a pointer.
            let llfn = Callee::def(ccx, def_id, substs).reify(ccx);
            if !is_by_ref {
                // A by-value fn item is ignored, so the shim has
                // the same signature as the original function.
                return llfn;
            }
            Some(llfn)
        }
        _ => None
    };

    let bare_fn_ty_maybe_ref = if is_by_ref {
        tcx.mk_imm_ref(tcx.mk_region(ty::ReErased), bare_fn_ty)
    } else {
        bare_fn_ty
    };

    // Check if we already trans'd this shim.
    if let Some(&llval) = ccx.fn_pointer_shims().borrow().get(&bare_fn_ty_maybe_ref) {
        return llval;
    }

    debug!("trans_fn_pointer_shim(bare_fn_ty={:?})",
           bare_fn_ty);

    // Construct the "tuply" version of `bare_fn_ty`. It takes two arguments: `self`,
    // which is the fn pointer, and `args`, which is the arguments tuple.
    let sig = match bare_fn_ty.sty {
        ty::TyFnDef(..,
                    &ty::BareFnTy { unsafety: hir::Unsafety::Normal,
                                    abi: Abi::Rust,
                                    ref sig }) |
        ty::TyFnPtr(&ty::BareFnTy { unsafety: hir::Unsafety::Normal,
                                    abi: Abi::Rust,
                                    ref sig }) => sig,

        _ => {
            bug!("trans_fn_pointer_shim invoked on invalid type: {}",
                 bare_fn_ty);
        }
    };
    let sig = tcx.erase_late_bound_regions_and_normalize(sig);
    let tuple_input_ty = tcx.intern_tup(&sig.inputs[..]);
    let sig = ty::FnSig {
        inputs: vec![bare_fn_ty_maybe_ref,
                     tuple_input_ty],
        output: sig.output,
        variadic: false
    };
    let fn_ty = FnType::new(ccx, Abi::RustCall, &sig, &[]);
    let tuple_fn_ty = tcx.mk_fn_ptr(tcx.mk_bare_fn(ty::BareFnTy {
        unsafety: hir::Unsafety::Normal,
        abi: Abi::RustCall,
        sig: ty::Binder(sig)
    }));
    debug!("tuple_fn_ty: {:?}", tuple_fn_ty);

    //
    let function_name = method_instance.symbol_name(ccx.shared());
    let llfn = declare::define_internal_fn(ccx, &function_name, tuple_fn_ty);
    attributes::set_frame_pointer_elimination(ccx, llfn);
    //
    let (block_arena, fcx): (TypedArena<_>, FunctionContext);
    block_arena = TypedArena::new();
    fcx = FunctionContext::new(ccx, llfn, fn_ty, None, &block_arena);
    let mut bcx = fcx.init(false);

    let llargs = get_params(fcx.llfn);

    let self_idx = fcx.fn_ty.ret.is_indirect() as usize;
    let llfnpointer = llfnpointer.unwrap_or_else(|| {
        // the first argument (`self`) will be ptr to the fn pointer
        if is_by_ref {
            Load(bcx, llargs[self_idx])
        } else {
            llargs[self_idx]
        }
    });

    let dest = fcx.llretslotptr.get();

    let callee = Callee {
        data: Fn(llfnpointer),
        ty: bare_fn_ty
    };
    bcx = callee.call(bcx, DebugLoc::None, &llargs[(self_idx + 1)..], dest).bcx;

    fcx.finish(bcx, DebugLoc::None);

    ccx.fn_pointer_shims().borrow_mut().insert(bare_fn_ty_maybe_ref, llfn);

    llfn
}

/// Translates a reference to a fn/method item, monomorphizing and
/// inlining as it goes.
///
/// # Parameters
///
/// - `ccx`: the crate context
/// - `def_id`: def id of the fn or method item being referenced
/// - `substs`: values for each of the fn/method's parameters
fn get_fn<'a, 'tcx>(ccx: &CrateContext<'a, 'tcx>,
                    def_id: DefId,
                    substs: &'tcx Substs<'tcx>)
                    -> (ValueRef, Ty<'tcx>) {
    let tcx = ccx.tcx();

    debug!("get_fn(def_id={:?}, substs={:?})", def_id, substs);

    assert!(!substs.needs_infer());
    assert!(!substs.has_escaping_regions());
    assert!(!substs.has_param_types());

    let substs = tcx.normalize_associated_type(&substs);
    let instance = Instance::new(def_id, substs);
    let item_ty = ccx.tcx().item_type(def_id);
    let fn_ty = monomorphize::apply_param_substs(ccx.shared(), substs, &item_ty);

    if let Some(&llfn) = ccx.instances().borrow().get(&instance) {
        return (llfn, fn_ty);
    }

    let sym = ccx.symbol_map().get_or_compute(ccx.shared(),
                                              TransItem::Fn(instance));
    debug!("get_fn({:?}: {:?}) => {}", instance, fn_ty, sym);

    // This is subtle and surprising, but sometimes we have to bitcast
    // the resulting fn pointer.  The reason has to do with external
    // functions.  If you have two crates that both bind the same C
    // library, they may not use precisely the same types: for
    // example, they will probably each declare their own structs,
    // which are distinct types from LLVM's point of view (nominal
    // types).
    //
    // Now, if those two crates are linked into an application, and
    // they contain inlined code, you can wind up with a situation
    // where both of those functions wind up being loaded into this
    // application simultaneously. In that case, the same function
    // (from LLVM's point of view) requires two types. But of course
    // LLVM won't allow one function to have two types.
    //
    // What we currently do, therefore, is declare the function with
    // one of the two types (whichever happens to come first) and then
    // bitcast as needed when the function is referenced to make sure
    // it has the type we expect.
    //
    // This can occur on either a crate-local or crate-external
    // reference. It also occurs when testing libcore and in some
    // other weird situations. Annoying.

    let fn_ptr_ty = match fn_ty.sty {
        ty::TyFnDef(.., fty) => {
            // Create a fn pointer with the substituted signature.
            tcx.mk_fn_ptr(fty)
        }
        _ => bug!("expected fn item type, found {}", fn_ty)
    };
    let llptrty = type_of::type_of(ccx, fn_ptr_ty);

    let llfn = if let Some(llfn) = declare::get_declared_value(ccx, &sym) {
        if common::val_ty(llfn) != llptrty {
            debug!("get_fn: casting {:?} to {:?}", llfn, llptrty);
            consts::ptrcast(llfn, llptrty)
        } else {
            debug!("get_fn: not casting pointer!");
            llfn
        }
    } else {
        let llfn = declare::declare_fn(ccx, &sym, fn_ty);
        assert_eq!(common::val_ty(llfn), llptrty);
        debug!("get_fn: not casting pointer!");

        let attrs = ccx.tcx().get_attrs(def_id);
        attributes::from_fn_attrs(ccx, &attrs, llfn);

        let is_local_def = ccx.shared().translation_items().borrow()
                              .contains(&TransItem::Fn(instance));
        if is_local_def {
            // FIXME(eddyb) Doubt all extern fn should allow unwinding.
            attributes::unwind(llfn, true);
            unsafe {
                llvm::LLVMRustSetLinkage(llfn, llvm::Linkage::ExternalLinkage);
            }
        }

        llfn
    };

    ccx.instances().borrow_mut().insert(instance, llfn);

    (llfn, fn_ty)
}

// ______________________________________________________________________
// Translating calls

fn trans_call_inner<'a, 'blk, 'tcx>(bcx: Block<'blk, 'tcx>,
                                    debug_loc: DebugLoc,
                                    callee: Callee<'tcx>,
                                    args: &[ValueRef],
                                    opt_llretslot: Option<ValueRef>)
                                    -> Result<'blk, 'tcx> {
    // Introduce a temporary cleanup scope that will contain cleanups
    // for the arguments while they are being evaluated. The purpose
    // this cleanup is to ensure that, should a panic occur while
    // evaluating argument N, the values for arguments 0...N-1 are all
    // cleaned up. If no panic occurs, the values are handed off to
    // the callee, and hence none of the cleanups in this temporary
    // scope will ever execute.
    let fcx = bcx.fcx;
    let ccx = fcx.ccx;

    let fn_ret = callee.ty.fn_ret();
    let fn_ty = callee.direct_fn_type(ccx, &[]);

    let mut callee = match callee.data {
        NamedTupleConstructor(_) | Intrinsic => {
            bug!("{:?} calls should not go through Callee::call", callee);
        }
        f => f
    };

    // If there no destination, return must be direct, with no cast.
    if opt_llretslot.is_none() {
        assert!(!fn_ty.ret.is_indirect() && fn_ty.ret.cast.is_none());
    }

    let mut llargs = Vec::new();

    if fn_ty.ret.is_indirect() {
        let mut llretslot = opt_llretslot.unwrap();
        if let Some(ty) = fn_ty.ret.cast {
            llretslot = PointerCast(bcx, llretslot, ty.ptr_to());
        }
        llargs.push(llretslot);
    }

    match callee {
        Virtual(idx) => {
            llargs.push(args[0]);

            let fn_ptr = meth::get_virtual_method(bcx, args[1], idx);
            let llty = fn_ty.llvm_type(bcx.ccx()).ptr_to();
            callee = Fn(PointerCast(bcx, fn_ptr, llty));
            llargs.extend_from_slice(&args[2..]);
        }
        _ => llargs.extend_from_slice(args)
    }

    let llfn = match callee {
        Fn(f) => f,
        _ => bug!("expected fn pointer callee, found {:?}", callee)
    };

    let (llret, bcx) = base::invoke(bcx, llfn, &llargs, debug_loc);
    if !bcx.unreachable.get() {
        fn_ty.apply_attrs_callsite(llret);

        // If the function we just called does not use an outpointer,
        // store the result into the rust outpointer. Cast the outpointer
        // type to match because some ABIs will use a different type than
        // the Rust type. e.g., a {u32,u32} struct could be returned as
        // u64.
        if !fn_ty.ret.is_indirect() {
            if let Some(llretslot) = opt_llretslot {
                fn_ty.ret.store(&bcx.build(), llret, llretslot);
            }
        }
    }

    if fn_ret.0.is_never() {
        Unreachable(bcx);
    }

    Result::new(bcx, llret)
}

extern crate num_traits;
use num_traits::{Float, One, Zero};

extern crate rand;
use rand::SeedableRng;

extern crate rand_chacha;
use rand_chacha::ChaCha8Rng;

use std::cell::{Ref, RefMut, RefCell};
use std::iter::Sum;
use std::rc::Rc;

use crate::visitor::Visitor;
use crate::store::{PointStore, NodeStore};
use crate::tree::{Cut, Node};

/// Random cut tree data structure on nodes and points.
///
/// A random cut tree contains leaf nodes and internal nodes.
/// [`Leaf`](crate::Leaf) nodes live at the leaves of the tree and mainly
/// represent a data point in the tree. [`Internal`](`crate::Internal`) nodes
/// mainly contain a [`BoundingBox`](`crate::BoundingBox`) on all of the points
/// in its subtree as well as a random [`Cut`] on that bounding box.
///
/// To store these nodes and points, a random cut tree contains a node store
/// and a point store. The [`NodeStore`] contains all of the nodes of the tree
/// of type `Leaf` or `Internal`. The [`PointStore`] contains the data points or
/// vectors stored in the leaves of the tree. In some cases it is sufficient for
/// a `Tree` to uniquely own its point store. In other cases, such as the case
/// where we want share points across multiple trees in a forest, this tree's
/// point store may live outside of this tree.
///
/// # Examples
///
/// ```
/// use random_cut_forest::Tree;
/// use random_cut_forest::tree::{AddResult, DeleteResult};
///
/// // create a new random cut tree with its own point store
/// let mut tree: Tree<f32> = Tree::new();
///
/// // add some (two-dimensional) data points to the tree
/// let result = tree.add_point(vec![0.0, 0.0]);
/// tree.add_point(vec![1.0, 2.0]);
/// tree.add_point(vec![0.2, 1.5]);
/// ```
pub struct Tree<T> {
    point_store: Rc<RefCell<PointStore<T>>>,
    node_store: NodeStore<T>,
    root_node: Option<usize>,
    rng: ChaCha8Rng,
}


impl<T> Tree<T>
    where T: Float + Sum
{

    /// Create a new `Tree` with a shared point store.
    ///
    /// Given a reference counted (shared) point store, create a new tree that
    /// gets points from this point store.
    ///
    /// # Examples
    ///
    /// ```
    /// extern crate slab;
    ///
    /// // create a shared point store
    /// use slab::Slab;
    /// use std::cell::RefCell;
    /// use std::rc::Rc;
    /// let point_store = Rc::new(RefCell::new(Slab::new()));
    ///
    /// use random_cut_forest::Tree;
    /// let tree: Tree<f32> = Tree::new_with_point_store(point_store);
    /// ```
    pub fn new_with_point_store(point_store: Rc<RefCell<PointStore<T>>>) -> Self {
        Tree {
            point_store: point_store.clone(),
            node_store: NodeStore::new(),
            root_node: None,
            rng: ChaCha8Rng::from_entropy(),
        }
    }

    /// Create a new `Tree`.
    ///
    /// The created tree will have its own private point store.
    ///
    /// # Examples
    ///
    /// ```
    /// use random_cut_forest::Tree;
    ///
    /// let tree: Tree<f32> = Tree::new();
    /// ```
    pub fn new() -> Self {
        Tree::new_with_point_store(Rc::new(RefCell::new(PointStore::new())))
    }

    /// Re-initializes the tree's random number generator with a seed.
    ///
    /// On construction, the tree's random number generator is initialized
    /// using the host system's random number generator. This function
    /// reconstructs a random number generator from a specified seed.
    ///
    /// Random cut trees use the [`ChaCha8Rng`][cha] random number generator.
    /// It has fast initialization, high throughput and relatively small memory
    /// footprint.
    ///
    /// # Examples
    ///
    /// ```
    /// use random_cut_forest::Tree;
    ///
    /// let mut tree: Tree<f32> = Tree::new();
    /// tree.seed(42);
    /// ```
    ///
    /// [cha]: https://rust-random.github.io/rand/rand_chacha/struct.ChaCha8Rng.html
    pub fn seed(&mut self, seed: u64) {
        self.rng = ChaCha8Rng::seed_from_u64(seed);
    }

    /// Return the number of points in the tree's point store.
    ///
    /// It is important to note that if this is a shared point store then this
    /// function returns the total number of points in the point store. This
    /// number is not directly related to the number of points used by this
    /// particular tree.
    ///
    /// # Examples
    ///
    /// ```
    /// use random_cut_forest::Tree;
    ///
    /// // create a tree with a private point store
    /// let mut tree: Tree<f32> = Tree::new();
    /// assert_eq!(tree.num_points(), 0);
    ///
    /// tree.add_point(vec![0.0, 0.0]);
    /// assert_eq!(tree.num_points(), 1);
    /// ```
    pub fn num_points(&self) -> usize {
        let store = self.point_store.borrow();
        store.len()
    }

    /// Returns the mass of the tree.
    ///
    /// The mass of the tree is equal to the sum of the masses of the nodes.
    /// This quantity is tracked during point addition and deletion such that
    /// the mass of the root node is always equal to the mass of the tree.
    ///
    /// # Examples
    ///
    /// ```
    /// use random_cut_forest::Tree;
    ///
    /// let mut tree: Tree<f32> = Tree::new();
    /// assert_eq!(tree.mass(), 0);
    ///
    /// tree.add_point(vec![0.0, 0.0]);
    /// assert_eq!(tree.mass(), 1);
    ///
    /// tree.add_point(vec![1.0, 1.0]);
    /// assert_eq!(tree.mass(), 2);
    ///
    /// tree.add_point(vec![0.0, 0.0]);
    /// assert_eq!(tree.mass(), 3);
    /// ```
    pub fn mass(&self) -> u32 {
        match self.root_node {
            None => 0,
            Some(key) => self.node_store.get(key).unwrap().mass(),
        }
    }

    /// Returns an iterator on nodes.
    ///
    /// Given a query point, a random cut tree iteration begins at the root node
    /// of the tree and returns a branch to the leaf node which is approximately
    /// closest to a query point in the L1-norm. (Relative to the random cuts
    /// chosen in the tree.)
    ///
    /// Note that this is not the path used by scoring [`Visitor`] types. The
    /// function [`Tree::traverse`] correctly applies a `Visitor` starting
    /// at the nearest leaf node and traverses up the tree to the root node.
    ///
    /// See [`NodeIterator`] for more information.
    ///
    /// # Examples
    ///
    /// ```
    /// use random_cut_forest::{Node, Tree};
    ///
    /// let mut tree: Tree<f32> = Tree::new();
    /// tree.seed(0);  // seed this test to fix a random cut
    /// tree.add_point(vec![0.0, 1.0]);
    ///
    /// // check that we recover the only node in the tree
    /// let query = vec![0.1, 0.9];
    /// let nodes: Vec<&Node<f32>> = tree.iter(&query).collect();
    /// assert_eq!(nodes.len(), 1);
    ///
    /// // after adding a second point the traversal should contain the
    /// // point closest to the query in the L1 norm
    /// tree.add_point(vec![-1.0, -2.0]);
    /// let nodes: Vec<&Node<f32>> = tree.iter(&query).collect();
    /// assert_eq!(nodes.len(), 2);
    ///
    /// // a traversal implements iter, so we can use it in a loop
    /// for node in tree.iter(&query) {
    ///     println!("mass = {}", node.mass());
    /// }
    /// ```
    pub fn iter<'a>(&'a self, point: &'a Vec<T>) -> NodeIterator<'a, T> {
        NodeIterator::new(self, point)
    }

    /// Apply a visitor to a tree traversal with a query point.
    ///
    /// Given a query point and a visitor, we apply the visitor to the nodes
    /// of the tree starting at the leaf nearest to the query and traversing up
    /// the tree to the root node.
    ///
    /// See the [`Visitor`] trait for more information.
    pub fn traverse<'a, U, V>(
        &'a self,
        point: &'a Vec<T>,
        visitor: &mut V,
    ) -> U where V: Visitor<T, Output=U> {
        match self.root_node() {
            Some(node_key) => return self.traverse_helper(point, visitor, node_key, Zero::zero()),
            None => panic!("Attempting to score on an empty tree")
        }
    }

    #[inline(always)]
    fn traverse_helper<'a, U, V>(
        &'a self,
        point: &'a Vec<T>,
        visitor: &mut V,
        node_key: usize,
        depth: T,
    ) -> U where V: Visitor<T, Output=U> {
        match self.get_node(node_key) {
            Node::Leaf(leaf) => visitor.accept_leaf(&leaf, depth),
            Node::Internal(node) => {
                let next_node_key = if Cut::is_left_of(point, node.cut()) {
                    node.left()
                } else {
                    node.right()
                };
                self.traverse_helper(point, visitor, next_node_key, depth + One::one());
                visitor.accept(&node, depth);
            }
        }
        visitor.get_result()
    }

    // =========================================================================
    // Helper Functions
    //
    // Mostly used by tree_point_addition and tree_point_deletion.
    // =========================================================================
    #[inline(always)]
    pub fn root_node(&self) -> Option<usize> { self.root_node }

    #[inline(always)]
    pub fn set_root_node(&mut self, root_key: Option<usize>) {
        self.root_node = root_key;
    }

    #[inline(always)]
    pub fn borrow_point_store(&self) -> Ref<PointStore<T>> { self.point_store.borrow() }

    #[inline(always)]
    pub fn borrow_mut_point_store(&self) -> RefMut<PointStore<T>> { self.point_store.borrow_mut() }

    #[inline(always)]
    pub fn node_store(&self) -> &NodeStore<T> { &self.node_store }

    #[inline(always)]
    pub fn node_store_mut(&mut self) -> &mut NodeStore<T> { &mut self.node_store }

    #[inline(always)]
    pub fn rng_mut(&mut self) -> &mut ChaCha8Rng { &mut self.rng }

    #[inline(always)]
    pub fn get_node(&self, node_key: usize) -> &Node<T> {
        self.node_store().get(node_key).unwrap()
    }

    #[inline(always)]
    pub fn get_node_mut(&mut self, node_key: usize) -> &mut Node<T> {
        self.node_store_mut().get_mut(node_key).unwrap()
    }

    #[inline(always)]
    pub fn get_parent(&self, node_key: usize) -> Option<usize> {
        self.get_node(node_key).parent()
    }
}

/// A type for traversing nodes from root to the nearest leaf.
///
/// Given an input data point/vector, this type traces the path from the root
/// node of a tree to the leaf node nearest to the input. Returned by
/// [`Tree::traverse`].
///
/// Note that this is not the path used by scoring [`Visitor`] types. The
/// function [`Tree::traverse`] correctly applies a `Visitor` starting
/// at the nearest leaf node and traverses up the tree to the root node.
pub struct NodeIterator<'a, T> {
    tree: &'a Tree<T>,
    point: &'a Vec<T>,
    current_node_key: Option<usize>,
}

impl<'a, T> NodeIterator<'a, T>
    where T: Float + Sum
{

    /// Create a new node traverser from a tree and a query point.
    ///
    /// # Examples
    ///
    /// ```
    /// use random_cut_forest::Tree;
    /// use random_cut_forest::tree::NodeIterator;
    ///
    /// let mut tree = Tree::new();
    /// let point = vec![0.0, 0.0];
    ///
    /// // create a new node traverser from a tree and a query point
    /// let mut node_traverser = NodeIterator::new(&tree, &point);
    /// ```
    pub fn new(tree: &'a Tree<T>, point: &'a Vec<T>) -> Self {
        NodeIterator {
            tree: tree,
            point: point,
            current_node_key: tree.root_node(),
        }
    }

    /// Return the key of the next node in a traversal.
    fn next_node_key(&mut self, node: &Node<T>) -> Option<usize> {
        match node {
            Node::Leaf(_) => None,
            Node::Internal(node) => {
                if Cut::is_left_of(self.point, node.cut()) {
                    Some(node.left())
                } else {
                    Some(node.right())
                }
            }
        }
    }
}

impl<'a, T> Iterator for NodeIterator<'a, T>
    where T: Float + Sum
{
    type Item = &'a Node<T>;

    fn next(&mut self) -> Option<&'a Node<T>> {
        match self.current_node_key {
            Some(node_key) => {
                let node = self.tree.node_store().get(node_key).unwrap();
                self.current_node_key = self.next_node_key(node);
                Some(node)
            },
            None => None
        }
    }
}


#[cfg(test)]
mod tests {
    use rand::Rng;
    use rand_distr::StandardNormal;

    use crate::tree::{AddResult, DeleteResult, Node};
    use super::*;

    fn generate_random_normal(dimension: usize, num_points: usize) -> Vec<Vec<f32>> {
        let mut points: Vec<Vec<f32>> = Vec::with_capacity(num_points);
        let mut rng = rand::thread_rng();
        for _ in 0..num_points {
            let mut point: Vec<f32> = Vec::with_capacity(dimension);
            for _ in 0..dimension {
                point.push(rng.sample(StandardNormal));
            }
            points.push(point);
        }
        points
    }

    #[test]
    fn test_node_iteration() {
        let mut tree: Tree<f32> = Tree::new();
        let query = vec![10.0, 10.0, 10.0, 10.0];
        let nodes: Vec<&Node<f32>> = tree.iter(&query).collect();
        assert_eq!(nodes.len(), 0);

        // add a bunch of N(0,1) points to the tree including the query point
        for point in generate_random_normal(4, 32) {
            tree.add_point(point);
        }
        tree.add_point(query.clone());

        // traverse the tree. the leaf node should contain the query point
        for node in tree.iter(&query) {
            match node {
                Node::Internal(_) => (),
                Node::Leaf(n) => {
                    let store = tree.borrow_point_store();
                    let point = store.get(n.point()).unwrap();
                    assert_eq!(*point, query);
                }
            }
        }
    }

    #[test]
    fn test_store_sizes() {
        let mut tree: Tree<f32> = Tree::new();
        assert_eq!(tree.num_points(), 0);
        assert_eq!(tree.node_store().len(), 0);

        tree.add_point(vec![-1.0, -1.0]);
        assert_eq!(tree.num_points(), 1);
        assert_eq!(tree.node_store().len(), 1);

        // add points
        let points = vec![vec![0.0, 0.0], vec![1.0, 1.0], vec![2.0, 2.0], vec![3.0, 3.0]];
        for (i, point) in points.iter().enumerate() {
            let result = tree.add_point(point.clone());
            assert!(std::matches!(result, AddResult::AddedPoint {..}));
            assert_eq!(tree.num_points(), i + 2);
            assert_eq!(tree.node_store().len(), 2*i + 3);
        }

        // re-add points
        let num_points = tree.num_points();
        for point in points.iter()  {
            let result = tree.add_point(point.clone());
            assert!(std::matches!(result, AddResult::MassIncreased {..}));
            assert_eq!(tree.num_points(), num_points);
            assert_eq!(tree.node_store().len(), 2*num_points - 1);
        }

        // delete points: check mass decrease
        for point in points.iter() {
            let result = tree.delete_point(point);
            assert!(std::matches!(result, DeleteResult::MassDecreased {..}));
            assert_eq!(tree.num_points(), num_points);
            assert_eq!(tree.node_store().len(), 2*num_points - 1);
        }

        // delete points: check deleted
        for (i, point) in points.iter().enumerate() {
            let result = tree.delete_point(point);
            assert!(std::matches!(result, DeleteResult::DeletedPoint {..}));
            assert_eq!(tree.num_points(), num_points - (i + 1));
            assert_eq!(tree.node_store().len(), 2*(num_points - (i+1)) - 1);
        }
    }

    /// Traverses the tree to check if the node masses are consistent
    fn check_node_masses<T: Float + Sum>(tree: &Tree<T>, node_idx: usize) -> u32
    {
        let node = tree.node_store().get(node_idx).unwrap();
        let mass = node.mass();
        match node {
            Node::Internal(internal) => {
                let left_mass = check_node_masses(tree, internal.left());
                let right_mass = check_node_masses(tree, internal.right());
                assert_eq!(mass, left_mass + right_mass);
                mass
            }
            Node::Leaf(_) => {
                mass
            }
        }
    }

    #[test]
    fn test_tree_mass() {
        let mut tree: Tree<f32> = Tree::new();
        assert_eq!(tree.mass(), 0);

        // add points and check
        let points = vec![vec![0.0, 0.0], vec![1.0, 1.0], vec![2.0, 2.0], vec![3.0, 3.0]];
        for (i, point) in points.iter().enumerate() {
            tree.add_point(point.clone());
            assert_eq!(tree.mass(), i as u32 + 1);
            check_node_masses(&tree, tree.root_node().unwrap());
        }

        // delete points and check
        let mass = tree.mass();
        for (i, point) in points.iter().enumerate() {
            tree.delete_point(point);
            assert_eq!(tree.mass(), mass - i as u32 - 1);
            if let Some(root_key) = tree.root_node() {
                check_node_masses(&tree, root_key);
            }
        }
   }
}

//! # OpenTelemetry Span Processor Interface
//!
//! Span processor is an interface which allows hooks for span start and end method
//! invocations. The span processors are invoked only when
//! [`is_recording`] is true.
//!
//! Built-in span processors are responsible for batching and conversion of spans to
//! exportable representation and passing batches to exporters.
//!
//! Span processors can be registered directly on SDK [`Provider`] and they are
//! invoked in the same order as they were registered.
//!
//! All `Tracer` instances created by a `Provider` share the same span processors.
//! Changes to this collection reflect in all `Tracer` instances.
//!
//! The following diagram shows `SpanProcessor`'s relationship to other components
//! in the SDK:
//!
//! ```ascii
//!   +-----+--------------+   +-----------------------+   +-------------------+
//!   |     |              |   |                       |   |                   |
//!   |     |              |   | (Batch)SpanProcessor  |   |    SpanExporter   |
//!   |     |              +---> (Simple)SpanProcessor +--->  (JaegerExporter) |
//!   |     |              |   |                       |   |                   |
//!   | SDK | Tracer.span()|   +-----------------------+   +-------------------+
//!   |     | Span.end()   |
//!   |     |              |   +---------------------+
//!   |     |              |   |                     |
//!   |     |              +---> ZPagesProcessor     |
//!   |     |              |   |                     |
//!   +-----+--------------+   +---------------------+
//! ```
//!
//! [`is_recording`]: trait.Span.html#is_recording
//! [`Provider`]: trait.Provider.html

use crate::exporter;
use std::sync::Arc;

/// `SpanProcessor`s allow finished spans to be processed.
pub trait SpanProcessor: Send + Sync + std::fmt::Debug {
    /// `on_start` method is invoked when a `Span` is started.
    fn on_start(&self, span: Arc<exporter::trace::SpanData>);
    /// `on_end` method is invoked when a `Span` is ended.
    fn on_end(&self, span: Arc<exporter::trace::SpanData>);
    /// Shutdown is invoked when SDK shuts down. Use this call to cleanup any
    /// processor data. No calls to `on_start` and `on_end` method is invoked
    /// after `shutdown` call is made.
    fn shutdown(&self);
}

