// A battery of tests to ensure destructors of unboxed closure environments
// run at the right times.

#![feature(unboxed_closures)]

static mut DROP_COUNT: uint = 0;

fn drop_count() -> uint {
    unsafe {
        DROP_COUNT
    }
}

struct Droppable {
    x: int,
}

impl Droppable {
    fn new() -> Droppable {
        Droppable {
            x: 1
        }
    }
}

impl Drop for Droppable {
    fn drop(&mut self) {
        unsafe {
            DROP_COUNT += 1
        }
    }
}

fn a<F:Fn(int, int) -> int>(f: F) -> int {
    f(1, 2)
}

fn b<F:FnMut(int, int) -> int>(mut f: F) -> int {
    f(3, 4)
}

fn c<F:FnOnce(int, int) -> int>(f: F) -> int {
    f(5, 6)
}

fn test_fn() {
    {
        a(move |a: int, b| { a + b });
    }
    assert_eq!(drop_count(), 0);

    {
        let z = &Droppable::new();
        a(move |a: int, b| { z; a + b });
        assert_eq!(drop_count(), 0);
    }
    assert_eq!(drop_count(), 1);

    {
        let z = &Droppable::new();
        let zz = &Droppable::new();
        a(move |a: int, b| { z; zz; a + b });
        assert_eq!(drop_count(), 1);
    }
    assert_eq!(drop_count(), 3);
}

fn test_fn_mut() {
    {
        b(move |a: int, b| { a + b });
    }
    assert_eq!(drop_count(), 3);

    {
        let z = &Droppable::new();
        b(move |a: int, b| { z; a + b });
        assert_eq!(drop_count(), 3);
    }
    assert_eq!(drop_count(), 4);

    {
        let z = &Droppable::new();
        let zz = &Droppable::new();
        b(move |a: int, b| { z; zz; a + b });
        assert_eq!(drop_count(), 4);
    }
    assert_eq!(drop_count(), 6);
}

fn test_fn_once() {
    {
        c(move |a: int, b| { a + b });
    }
    assert_eq!(drop_count(), 6);

    {
        let z = Droppable::new();
        c(move |a: int, b| { z; a + b });
        assert_eq!(drop_count(), 7);
    }
    assert_eq!(drop_count(), 7);

    {
        let z = Droppable::new();
        let zz = Droppable::new();
        c(move |a: int, b| { z; zz; a + b });
        assert_eq!(drop_count(), 9);
    }
    assert_eq!(drop_count(), 9);
}

fn main() {
    test_fn();
    test_fn_mut();
    test_fn_once();
}

//! Uses `builder` and filesystem watch code to repeatedly
//! evaluate and build a given Nix file.

use crate::builder;
use crate::daemon::LoopHandlerEvent;
use crate::error::BuildError;
use crate::pathreduction::reduce_paths;
use crate::project::roots;
use crate::project::roots::Roots;
use crate::project::Project;
use crate::watch::{DebugMessage, EventError, Reason, Watch};
use crate::NixFile;
use crossbeam_channel as chan;
use slog_scope::{debug, warn};
use std::path::PathBuf;

/// Builder events sent back over `BuildLoop.tx`.
#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Event {
    /// Demarks a stream of events from recent history becoming live
    SectionEnd,
    /// A build has started
    Started {
        /// The shell.nix file for the building project
        nix_file: NixFile,
        /// The reason the build started
        reason: Reason,
    },
    /// A build completed successfully
    Completed {
        /// The shell.nix file for the building project
        nix_file: NixFile,
        /// The result of the build
        result: BuildResults,
    },
    /// A build command returned a failing exit status
    Failure {
        /// The shell.nix file for the building project
        nix_file: NixFile,
        /// The error that exited the build
        failure: BuildError,
    },
}

/// Results of a single, successful build.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct BuildResults {
    /// See `build::Info.outputPaths
    pub output_paths: builder::OutputPaths<roots::RootPath>,
}

/// The BuildLoop repeatedly builds the Nix expression in
/// `project` each time a source file influencing
/// a previous build changes.
/// Additionally, we create GC roots for the build results.
pub struct BuildLoop<'a> {
    /// Project to be built.
    project: &'a Project,
    /// Watches all input files for changes.
    /// As new input files are discovered, they are added to the watchlist.
    watch: Watch,
}

impl<'a> BuildLoop<'a> {
    /// Instatiate a new BuildLoop. Uses an internal filesystem
    /// watching implementation.
    pub fn new(project: &'a Project) -> BuildLoop<'a> {
        BuildLoop {
            project,
            watch: Watch::try_new().expect("Failed to initialize watch"),
        }
    }

    /// Loop forever, watching the filesystem for changes. Blocks.
    /// Sends `Event`s over `Self.tx` once they happen.
    /// When new filesystem changes are detected while a build is
    /// still running, it is finished first before starting a new build.
    #[allow(clippy::drop_copy, clippy::zero_ptr)] // triggered by `select!`
    pub fn forever(&mut self, tx: chan::Sender<LoopHandlerEvent>, rx_ping: chan::Receiver<()>) {
        let translate_reason = |rsn| match rsn {
            Ok(rsn) => rsn,
            // we should continue and just cite an unknown reason
            Err(EventError::EventHasNoFilePath(msg)) => {
                warn!(
                    "event has no file path; possible issue with the watcher?";
                    "message" => ?msg
                );
                // can’t Clone `Event`s, so we return the Debug output here
                Reason::UnknownEvent(DebugMessage::from(format!("{:#?}", msg)))
            }
            Err(EventError::RxNoEventReceived) => {
                panic!("The file watcher died!");
            }
        };

        // The project has just been added, so run the builder in the first iteration
        let mut output_paths = self.once_with_send(
            &tx,
            Event::Started {
                nix_file: self.project.nix_file.clone(),
                reason: Reason::ProjectAdded(self.project.nix_file.clone()),
            },
        );

        // Drain pings initially: we're going to trigger a first build anyway
        rx_ping.try_iter().for_each(drop);

        let rx_notify = self.watch.rx.clone();

        loop {
            let reason = chan::select! {
                recv(rx_notify) -> msg => match msg {
                    Ok(msg) => {
                        match self.watch.process(msg) {
                            Some(rsn) => {
                                Some(Event::Started{
                                    nix_file: self.project.nix_file.clone(),
                                    reason: translate_reason(rsn)
                                })
                            },
                            None => {
                                // No relevant file events
                                None
                            }
                        }
                    }
                    // TODO: can we just ignore Err?
                    Err(_) => None
                },
                recv(rx_ping) -> msg => match (msg, &output_paths) {
                    (Ok(()), Some(output_paths)) => {
                        // TODO: why is this check done here?
                        if !output_paths.shell_gc_root_is_dir() {
                            Some(Event::Started{
                                nix_file: self.project.nix_file.clone(),
                                reason: Reason::PingReceived
                            })
                        }
                        else { None }
                    },
                    // TODO: can we just ignore these two cases?
                    (Ok(()), None) => None,
                    (Err(_), _) => None
                }
            };

            // If there is some reason to build, run the build!
            if let Some(rsn) = reason {
                output_paths = self.once_with_send(&tx, rsn)
            }
        }
    }

    fn once_with_send(
        &mut self,
        tx: &chan::Sender<LoopHandlerEvent>,
        reason: Event,
    ) -> Option<builder::OutputPaths<roots::RootPath>> {
        let send = |msg| {
            tx.send(LoopHandlerEvent::from(msg))
                .expect("Failed to send an event")
        };
        send(reason);
        match self.once() {
            Ok(result) => {
                send(Event::Completed {
                    nix_file: self.project.nix_file.clone(),
                    result: result.clone(),
                });
                Some(result.output_paths)
            }
            Err(e) => {
                if e.is_actionable() {
                    send(Event::Failure {
                        nix_file: self.project.nix_file.clone(),
                        failure: e,
                    })
                } else {
                    panic!("Unrecoverable error:\n{:#?}", e);
                }
                None
            }
        }
    }

    /// Execute a single build of the environment.
    ///
    /// This will create GC roots and expand the file watch list for
    /// the evaluation.
    pub fn once(&mut self) -> Result<BuildResults, BuildError> {
        let run_result = builder::run(&self.project.nix_file, &self.project.cas)?;
        self.register_paths(&run_result.referenced_paths)?;
        self.root_result(run_result.result)
    }

    fn register_paths(&mut self, paths: &[PathBuf]) -> Result<(), notify::Error> {
        let original_paths_len = paths.len();
        let paths = reduce_paths(&paths);
        debug!("paths reduced"; "from" => original_paths_len, "to" => paths.len());

        // add all new (reduced) nix sources to the input source watchlist
        self.watch.extend(paths.into_iter().collect::<Vec<_>>())?;

        Ok(())
    }

    fn root_result(&mut self, build: builder::RootedPath) -> Result<BuildResults, BuildError> {
        let roots = Roots::from_project(&self.project);

        Ok(BuildResults {
            output_paths: roots.create_roots(build).map_err(BuildError::io)?,
        })
    }
}

use crate::GqlValue;

use super::GqlInputType;

impl GqlInputType for bool {
    fn from_gql_value(value: Option<GqlValue>) -> Result<Self, String> {
        match value {
            Some(value) => match value {
                GqlValue::Boolean(v) => Ok(v),
                invalid_value => Err(format!(
                    "Expected type: boolean, but found: {}",
                    invalid_value.to_string()
                )),
            },
            None => Err("Expected type: boolean, but not found".to_string()),
        }
    }

    fn to_gql_value(&self) -> GqlValue {
        GqlValue::Boolean(*self)
    }
}

//! Handling of a player's "view."
//!
//! This module includes systems and components
//! which handle sending new data as
//! a player moves through the world.
//!
//! When a player crosses a chunk boundary, its
//! view has changed: some chunks are no longer visible,
//! while others now are. To account for this, we
//! must send the new chunks, unload the old
//! chunks on the client, send new entities, and
//! delete old ones.
//!
//! This is handled as follows:
//! * A system queries all position components which have changed
//! and adds a `CrossedChunk` component to these entities.
//! * Other systems query for added `CrossedChunk` components
//! and perform updates on these players' views.

use crate::Player;
use ahash::AHashMap;
use feather_core::chunk::Chunk;
use feather_core::network::packets::{ChunkData, DestroyEntities, UnloadChunk};
use feather_core::util::{ChunkPosition, Position};
use feather_server_types::{
    BumpVec, ChunkCrossEvent, ChunkLoadEvent, ChunkSendEvent, EntityClientRemoveEvent, EntityId,
    EntitySendEvent, Game, HoldChunkRequest, LoadChunkRequest, Network, PlayerJoinEvent,
    PreviousPosition, ReleaseChunkRequest, SpawnPacketCreator,
};
use fecs::{Entity, IntoQuery, Read, World};
use itertools::Either;
use parking_lot::RwLock;
use smallvec::SmallVec;
use std::iter;
use std::ops::Add;
use std::sync::Arc;

/// System which polls for updated positions and
/// calls `Game::on_chunk_cross()` accordingly.
#[fecs::system]
pub fn check_crossed_chunks(world: &mut World, game: &mut Game) {
    let mut crossed = BumpVec::new_in(game.bump());
    for (entity, (pos, prev_pos)) in
        <(Read<Position>, Read<PreviousPosition>)>::query().iter_entities(world.inner())
    {
        if pos.chunk() != prev_pos.0.chunk() {
            crossed.push((entity, pos.chunk(), prev_pos.0.chunk()));
        }
    }

    for (entity, new, old) in crossed {
        game.handle(
            world,
            ChunkCrossEvent {
                entity,
                old: Some(old),
                new,
            },
        );
    }
}

/// Triggers a chunk cross when a new player joins.
#[fecs::event_handler]
pub fn on_player_join_trigger_chunk_cross(
    event: &PlayerJoinEvent,
    game: &mut Game,
    world: &mut World,
) {
    let chunk = world.get::<Position>(event.player).chunk();
    game.handle(
        world,
        ChunkCrossEvent {
            old: None,
            new: chunk,
            entity: event.player,
        },
    );
}

/// System which sends new chunks and unloads old chunks on the client
/// when the view is updated.
#[fecs::event_handler]
pub fn on_chunk_cross_update_chunks(
    event: &ChunkCrossEvent,
    game: &mut Game,
    #[default] chunks_to_send: &mut ChunksToSend,
    world: &mut World,
) {
    if world.try_get::<Player>(event.entity).is_none() {
        return;
    }

    // The client likes it if we send closer chunks first,
    // so we'll sort by the Manhattan distance to the player.
    let mut pending_send = BumpVec::new_in(game.bump());
    pending_send.extend(find_new_chunks(
        event.old,
        event.new,
        game.config.server.view_distance,
    ));
    pending_send.sort_unstable_by_key(|chunk| chunk.manhattan_distance_to(event.new));

    for chunk in pending_send {
        send_chunk_to_player(game, world, chunks_to_send, event.entity, chunk);
    }

    for chunk in find_old_chunks(event.old, event.new, game.config.server.view_distance) {
        unload_chunk_for_player(game, world, chunk, event.entity);
    }
}

/// System which sends new entities and removes old entities
/// when a player crosses into a new view.
#[fecs::event_handler]
pub fn on_chunk_cross_update_entities(event: &ChunkCrossEvent, game: &mut Game, world: &mut World) {
    let network = match world.try_get::<Network>(event.entity) {
        Some(net) => net,
        None => return, // not a player
    };

    // Send newly visible entities.
    let mut sends_to_trigger = vec![];
    for other in find_new_chunks(event.old, event.new, game.config.server.view_distance)
        .flat_map(|chunk| game.chunk_entities.entities_in_chunk(chunk))
        .filter(|other| **other != event.entity)
    // don't send player to themselves!
    {
        if let Some(creator) = world.try_get::<SpawnPacketCreator>(*other) {
            let accessor = world
                .entity(*other)
                .expect("entity in chunk entities does not exist");
            let packet = creator.get(&accessor);

            network.send_boxed(packet);
            sends_to_trigger.push((*other, event.entity));
        }

        // if this `other` is a player, also send `entity` to other
        if let Some(network) = world.try_get::<Network>(*other) {
            if let Some(creator) = world.try_get::<SpawnPacketCreator>(event.entity) {
                let accessor = world.entity(event.entity).expect("entity does not exist");
                let packet = creator.get(&accessor);

                network.send_boxed(packet);
                sends_to_trigger.push((event.entity, *other));
            }
        }
    }

    // Tell the client to despawn entities which are no longer visible.
    let mut to_client_remove_trigger = vec![];
    to_client_remove_trigger.extend(
        find_old_chunks(event.old, event.new, game.config.server.view_distance)
            .flat_map(|chunk| game.chunk_entities.entities_in_chunk(chunk))
            .map(|other| (*other, event.entity)),
    );

    // Despawn this entity on other visible clients.
    find_old_chunks(event.old, event.new, game.config.server.view_distance)
        .flat_map(|chunk| game.chunk_entities.entities_in_chunk(chunk))
        .filter_map(|entity| world.try_get::<Network>(*entity).map(|net| (*entity, net)))
        .for_each(|(other, network)| {
            let packet = DestroyEntities {
                entity_ids: vec![world.get::<EntityId>(event.entity).0],
            };
            network.send(packet);
            to_client_remove_trigger.push((event.entity, other));
        });

    let to_destroy = to_client_remove_trigger
        .iter()
        .filter_map(|(other, _)| world.try_get::<EntityId>(*other).map(|id| id.0))
        .collect::<Vec<_>>();

    if !to_destroy.is_empty() {
        let packet = DestroyEntities {
            entity_ids: to_destroy,
        };
        network.send(packet);
    }

    drop(network);

    // Trigger on_entity_send
    for (entity, client) in sends_to_trigger {
        game.handle(world, EntitySendEvent { entity, client });
    }

    // Trigger on_entity_client_remove
    for (other, to) in to_client_remove_trigger {
        game.handle(
            world,
            EntityClientRemoveEvent {
                entity: other,
                client: to,
            },
        );
    }
}

/// Returns new chunks visible from a new chunk position.
fn find_new_chunks(
    old: Option<ChunkPosition>,
    new: ChunkPosition,
    view_distance: u8,
) -> impl Iterator<Item = ChunkPosition> {
    let within_view_distance = chunks_within_view_distance(new, view_distance);
    if let Some(old) = old {
        Either::Left(within_view_distance.filter(move |chunk| {
            (chunk.x - old.x).abs() >= view_distance as i32
                || (chunk.z - old.z).abs() >= view_distance as i32
        }))
    } else {
        Either::Right(within_view_distance)
    }
}

/// Returns chunks which are no longer visible from a new chunk position.
fn find_old_chunks(
    old: Option<ChunkPosition>,
    new: ChunkPosition,
    view_distance: u8,
) -> impl Iterator<Item = ChunkPosition> {
    if let Some(old) = old {
        Either::Left(
            chunks_within_view_distance(old, view_distance).filter(move |chunk| {
                (chunk.x - new.x).abs() >= view_distance as i32
                    || (chunk.z - new.z).abs() >= view_distance as i32
            }),
        )
    } else {
        Either::Right(iter::empty())
    }
}

/// Finds all chunks within the view distance of a given chunk.
fn chunks_within_view_distance(
    chunk: ChunkPosition,
    view_distance: u8,
) -> impl Iterator<Item = ChunkPosition> {
    let view_distance = i32::from(view_distance);

    (-view_distance..=view_distance).flat_map(move |x| {
        (-view_distance..=view_distance).map(move |z| chunk.add(ChunkPosition::new(x, z)))
    })
}

/// Resource containing a mapping from chunks -> sets of players indicating
/// which chunks are pending to send to a given player.
#[derive(Default)]
pub struct ChunksToSend(AHashMap<ChunkPosition, SmallVec<[Entity; 2]>>);

/// Asynchronously sends a chunk to a player.
fn send_chunk_to_player(
    game: &mut Game,
    world: &mut World,
    chunks_to_send: &mut ChunksToSend,
    player: Entity,
    chunk_pos: ChunkPosition,
) {
    if !world.is_alive(player) {
        return;
    }

    // Ensure that the chunk isn't unloaded while the player has it loaded.
    game.handle(
        world,
        HoldChunkRequest {
            player,
            chunk: chunk_pos,
        },
    );

    // If the chunk is already loaded, send it. Otherwise, we need to
    // queue it for loading.
    if let Some(chunk) = game.chunk_map.chunk_handle_at(chunk_pos) {
        world.get::<Network>(player).send(create_chunk_data(chunk));
        game.handle(
            world,
            ChunkSendEvent {
                player,
                chunk: chunk_pos,
            },
        );
    } else {
        let contains = chunks_to_send.0.contains_key(&chunk_pos);

        let vec = match chunks_to_send.0.get_mut(&chunk_pos) {
            Some(vec) => vec,
            None => {
                chunks_to_send.0.insert(chunk_pos, SmallVec::new());
                chunks_to_send.0.get_mut(&chunk_pos).unwrap()
            }
        };
        vec.push(player);

        if !contains {
            // Queue chunk for loading if it isn't already.
            game.handle(world, LoadChunkRequest { chunk: chunk_pos });
        }
    }
}

/// Unloads a chunk on a client.
fn unload_chunk_for_player(
    game: &mut Game,
    world: &mut World,
    chunk: ChunkPosition,
    player: Entity,
) {
    // Release hold on chunk so it can be unloaded on the server
    game.handle(world, ReleaseChunkRequest { player, chunk });

    // Send Unload Chunk packet.
    world.get::<Network>(player).send(UnloadChunk {
        chunk_x: chunk.x,
        chunk_z: chunk.z,
    });
}

/// System which sends chunks to pending players when a chunk is loaded.
#[fecs::event_handler]
pub fn on_chunk_load_send_to_clients(
    event: &ChunkLoadEvent,
    game: &mut Game,
    world: &mut World,
    chunks_to_send: &mut ChunksToSend,
) {
    if let Some(players) = chunks_to_send.0.get(&event.chunk) {
        let chunk = game
            .chunk_map
            .chunk_handle_at(event.chunk)
            .expect("chunk not loaded, but load event was triggered");
        for player in players {
            if !world.is_alive(*player) {
                continue;
            }

            world
                .get::<Network>(*player)
                .send(create_chunk_data(Arc::clone(&chunk)));
            game.handle(
                world,
                ChunkSendEvent {
                    chunk: event.chunk,
                    player: *player,
                },
            );
        }
    }

    chunks_to_send.0.remove(&event.chunk);
}

/// Creates a chunk data packet for the given chunk.
fn create_chunk_data(chunk: Arc<RwLock<Chunk>>) -> ChunkData {
    ChunkData { chunk }
}

