use super::{Counter, DisjointSet, IdMap};

impl DisjointSet {
    pub fn new() -> Self {
        DisjointSet {
            counter: Counter::new(),
            nodes: IdMap::new(),
        }
    }

    pub fn add(&mut self) -> u32 {
        let ret = self.counter.next();
        self.nodes.insert(ret, (ret, 0));
        ret
    }

    pub fn union(&mut self, left: u32, right: u32) -> u32 {
        let (l_root, l_rank) = self.find(left);
        let (r_root, r_rank) = self.find(right);

        if l_root == r_root {
            l_root // either left or right is fine
        } else if l_rank < r_rank {
            self.nodes.insert(l_root, (r_root, l_rank));
            l_root
        } else if l_rank > r_rank {
            self.nodes.insert(r_root, (l_root, r_rank));
            r_root
        } else {
            self.nodes.insert(l_root, (r_root, r_rank + 1));
            l_root
        }
    }

    fn find(&mut self, id: u32) -> (u32, u8) {
        let mut prev = id;
        let mut path = Vec::with_capacity(4); // i.e. "large enough for practical purposes"
        loop {
            let (parent, rank) = *self.nodes.get(&prev).unwrap();
            if prev == parent {
                let ret = (parent, rank);
                for node in path {
                    // path compression
                    self.nodes.insert(node, ret);
                }
                return ret;
            }
            path.push(prev);
            prev = parent;
        }
    }

    pub fn is_same_set(&mut self, left: u32, right: u32) -> bool {
        self.find(left).0 == self.find(right).0
    }
}

#[test]
pub fn test() {
    use std::iter;

    let mut sets = DisjointSet::new();
    for _ in iter::repeat(0).take(5) {
        let ret = sets.add();
        assert!(sets.is_same_set(ret, ret));
    }

    sets.union(0, 1);
    assert!(sets.is_same_set(0, 1));
    assert!(!sets.is_same_set(0, 2));
    assert!(!sets.is_same_set(0, 3));
    assert!(!sets.is_same_set(0, 4));
    assert!(!sets.is_same_set(1, 2));
    assert!(!sets.is_same_set(1, 3));
    assert!(!sets.is_same_set(1, 4));

    sets.union(3, 4);
    assert!(sets.is_same_set(3, 4));
    assert!(!sets.is_same_set(3, 0));
    assert!(!sets.is_same_set(3, 1));
    assert!(!sets.is_same_set(3, 2));
    assert!(!sets.is_same_set(4, 0));
    assert!(!sets.is_same_set(4, 1));
    assert!(!sets.is_same_set(4, 2));

    // 3 is alone
    assert!(!sets.is_same_set(2, 0));
    assert!(!sets.is_same_set(2, 1));
    assert!(!sets.is_same_set(2, 3));
    assert!(!sets.is_same_set(2, 4));

    sets.union(1, 4);
    assert!(sets.is_same_set(0, 1));
    assert!(sets.is_same_set(0, 3));
    assert!(sets.is_same_set(0, 4));
    assert!(sets.is_same_set(1, 0));
    assert!(sets.is_same_set(1, 3));
    assert!(sets.is_same_set(1, 4));
    assert!(sets.is_same_set(3, 0));
    assert!(sets.is_same_set(3, 1));
    assert!(sets.is_same_set(3, 4));
    assert!(sets.is_same_set(4, 0));
    assert!(sets.is_same_set(4, 1));
    assert!(sets.is_same_set(4, 3));
    assert!(!sets.is_same_set(2, 0));
    assert!(!sets.is_same_set(2, 1));
    assert!(!sets.is_same_set(2, 3));
    assert!(!sets.is_same_set(2, 0));
    assert!(!sets.is_same_set(2, 4));
}

use pb_jelly_gen::GenProtos;
use std::{env, fs};

#[cfg(feature = "bench_prost")]
use prost_build;

#[cfg(feature = "bench_rust_protobuf")]
use protoc_rust::Customize;

fn main() -> std::io::Result<()> {
    // Tell Cargo only re-run our build script if something in protos changes
    // println!("cargo:rerun-if-changed=protos");

    // Generate protobuf-rust bindings
    GenProtos::builder()
        .out_path("../gen/pb-jelly")
        .src_path("../proto/packages")
        .include_path("../proto/includes")
        .gen_protos();

    // compile the protos we use for bench marking, if we want to benchmark against PROST!
    if cfg!(feature = "bench_prost") {
        let mut crate_path = env!("CARGO_MANIFEST_DIR").to_owned();
        crate_path.push_str("/../gen/prost");
        fs::create_dir_all(&crate_path)?;
        env::set_var("OUT_DIR", crate_path);

        #[cfg(feature = "bench_prost")]
        prost_build::compile_protos(
            &["../proto/packages/pbtest/bench.proto"],
            &["../proto/packages", "../proto/includes"],
        )
        .unwrap();
    }

    // compile the protos we use for bench marking, if we want to benchmark against rust_protobuf
    if cfg!(feature = "bench_rust_protobuf") {
        let mut crate_path = env!("CARGO_MANIFEST_DIR").to_owned();
        crate_path.push_str("/../gen/rust_protobuf");
        fs::create_dir_all(&crate_path)?;

        #[cfg(feature = "bench_rust_protobuf")]
        protoc_rust::Codegen::new()
            .out_dir("../gen/rust_protobuf")
            .inputs(&["../proto/packages/pbtest/bench.proto"])
            .include("../proto/includes")
            .include("../proto/packages")
            .customize(Customize {
                carllerche_bytes_for_bytes: Some(true),
                ..Default::default()
            })
            .run()
            .expect("failed to generate rust_protobuf protos!");
    }

    Ok(())
}

use gtk::prelude::*;
use libhandy::traits::LeafletExt;
use libhandy::NavigationDirection;
use std::rc::Rc;

use crate::app::components::{EventListener, ListenerComponent};
use crate::app::state::ScreenName;
use crate::app::{AppEvent, BrowserEvent};

use super::{factory::ScreenFactory, home::HomePane, NavigationModel};

pub struct Navigation {
    model: Rc<NavigationModel>,
    leaflet: libhandy::Leaflet,
    navigation_stack: gtk::Stack,
    home_stack_sidebar: gtk::StackSidebar,
    back_button: gtk::Button,
    screen_factory: ScreenFactory,
    children: Vec<Box<dyn ListenerComponent>>,
}

impl Navigation {
    pub fn new(
        model: NavigationModel,
        leaflet: libhandy::Leaflet,
        back_button: gtk::Button,
        navigation_stack: gtk::Stack,
        home_stack_sidebar: gtk::StackSidebar,
        screen_factory: ScreenFactory,
    ) -> Self {
        let model = Rc::new(model);

        Self::connect_back_button(&back_button, &leaflet, &model);

        leaflet.connect_folded_notify(clone!(@weak back_button, @weak model => move |leaflet| {
            Self::update_back_button(&back_button, leaflet, &model);
        }));

        leaflet.connect_visible_child_name_notify(
            clone!(@weak back_button, @weak model => move |leaflet| {
                Self::update_back_button(&back_button, leaflet, &model);
            }),
        );

        Self {
            model,
            leaflet,
            navigation_stack,
            home_stack_sidebar,
            back_button,
            screen_factory,
            children: vec![],
        }
    }

    fn update_back_button(
        back_button: &gtk::Button,
        leaflet: &libhandy::Leaflet,
        model: &Rc<NavigationModel>,
    ) {
        let is_main = leaflet
            .visible_child_name()
            .map(|s| s.as_str() == "main")
            .unwrap_or(false);
        back_button.set_sensitive(leaflet.is_folded() && is_main || model.can_go_back());
    }

    fn connect_back_button(
        back_button: &gtk::Button,
        leaflet: &libhandy::Leaflet,
        model: &Rc<NavigationModel>,
    ) {
        back_button.connect_clicked(clone!(@weak leaflet, @weak model => move |_| {
            let is_main = leaflet.visible_child_name().map(|s| s.as_str() == "main").unwrap_or(false);
            let folded = leaflet.is_folded();
            let can_go_back = model.can_go_back();
            match (folded && is_main, can_go_back) {
                (_, true) => {
                    model.go_back();
                }
                (true, false) => {
                    leaflet.navigate(NavigationDirection::Back);
                }
                (false, false) => {}
            }
        }));
    }

    fn make_home(&self) -> Box<dyn ListenerComponent> {
        let home = HomePane::new(self.home_stack_sidebar.clone(), &self.screen_factory);

        home.connect_navigated(
            clone!(@weak self.model as model, @weak self.leaflet as leaflet => move || {
                leaflet.navigate(NavigationDirection::Forward);
                model.go_home();
            }),
        );

        Box::new(home)
    }

    fn push_screen(&mut self, name: &ScreenName) {
        println!("{}", name.identifier());

        let component: Box<dyn ListenerComponent> = match name {
            ScreenName::Home => self.make_home(),
            ScreenName::AlbumDetails(id) => {
                Box::new(self.screen_factory.make_album_details(id.to_owned()))
            }
            ScreenName::Search => Box::new(self.screen_factory.make_search_results()),
            ScreenName::Artist(id) => {
                Box::new(self.screen_factory.make_artist_details(id.to_owned()))
            }
            ScreenName::PlaylistDetails(id) => {
                Box::new(self.screen_factory.make_playlist_details(id.to_owned()))
            }
            ScreenName::User(id) => Box::new(self.screen_factory.make_user_details(id.to_owned())),
        };

        let widget = component.get_root_widget();
        widget.show_all();

        self.navigation_stack
            .add_named(widget, name.identifier().as_ref());
        self.children.push(component);
        self.navigation_stack
            .set_visible_child_name(name.identifier().as_ref());
    }

    fn pop(&mut self) {
        let children = &mut self.children;
        let popped = children.pop();

        let name = self.model.visible_child_name();
        self.navigation_stack
            .set_visible_child_name(name.identifier().as_ref());

        if let Some(child) = popped {
            self.navigation_stack.remove(child.get_root_widget());
        }
    }

    fn pop_to(&mut self, screen: &ScreenName) {
        self.navigation_stack
            .set_visible_child_name(screen.identifier().as_ref());
        let remainder = self.children.split_off(self.model.children_count());
        for widget in remainder {
            self.navigation_stack.remove(widget.get_root_widget());
        }
    }

    fn do_update_back_button(&self) {
        Self::update_back_button(&self.back_button, &self.leaflet, &self.model);
    }
}

impl EventListener for Navigation {
    fn on_event(&mut self, event: &AppEvent) {
        match event {
            AppEvent::Started => {
                self.push_screen(&ScreenName::Home);
                self.do_update_back_button();
            }
            AppEvent::BrowserEvent(BrowserEvent::NavigationPushed(name)) => {
                self.push_screen(name);
                self.do_update_back_button();
            }
            AppEvent::BrowserEvent(BrowserEvent::NavigationPopped) => {
                self.pop();
                self.do_update_back_button();
            }
            AppEvent::BrowserEvent(BrowserEvent::NavigationPoppedTo(name)) => {
                self.pop_to(name);
                self.do_update_back_button();
            }
            _ => {}
        };
        for child in self.children.iter_mut() {
            child.on_event(event);
        }
    }
}

