		let (ins, outs) = match slate.tx.as_ref() {
			Some(t) => (t.body.inputs.clone(), t.body.outputs.clone()),
			None => return None,
		};
		for i in ins.iter() {
			ret_vec.push(CommitsV4 {
				f: i.features.into(),
				c: i.commit,
				p: None,
			});
		}
		for o in outs.iter() {
			ret_vec.push(CommitsV4 {
				f: o.features.into(),
				c: o.commit,
				p: Some(o.proof),
			});
		}
		Some(ret_vec)
	}
