//! Queue family and groups.

use crate::queue::QueueType;
use crate::Backend;

use std::any::Any;
use std::fmt::Debug;

/// General information about a queue family, available upon adapter discovery.
///
/// Note that a backend can expose multiple queue families with the same properties.
///
/// Can be obtained from an [adapter][crate::adapter::Adapter] through its
/// [`queue_families`][crate::adapter::Adapter::queue_families] field.
pub trait QueueFamily: Debug + Any + Send + Sync {
    /// Returns the type of queues.
    fn queue_type(&self) -> QueueType;
    /// Returns maximum number of queues created from this family.
    fn max_queues(&self) -> usize;
    /// Returns the queue family ID.
    fn id(&self) -> QueueFamilyId;
}

/// Identifier for a queue family of a physical device.
#[derive(Debug, Copy, Clone, PartialEq, Eq, Hash)]
#[cfg_attr(feature = "serde", derive(Serialize, Deserialize))]
pub struct QueueFamilyId(pub usize);

/// Bare-metal queue group.
///
/// Denotes all queues created from one queue family.
#[derive(Debug)]
pub struct QueueGroup<B: Backend> {
    /// Family index for the queues in this group.
    pub family: QueueFamilyId,
    /// List of queues.
    pub queues: Vec<B::CommandQueue>,
}

impl<B: Backend> QueueGroup<B> {
    /// Create a new, empty queue group for a queue family.
    pub fn new(family: QueueFamilyId) -> Self {
        QueueGroup {
            family,
            queues: Vec::new(),
        }
    }

    /// Add a command queue to the group.
    ///
    /// The queue needs to be created from this queue family.
    pub fn add_queue(&mut self, queue: B::CommandQueue) {
        self.queues.push(queue);
    }
}

//! Safe [Vorbis](http://www.vorbis.com/) decoder implementation in pure Rust.
//!
//! The decoder is low-level and can only decode Vorbis packets directly (not wrapped in any
//! containers like Ogg).
//!
//! # Example
//!
//! ```rust,no_run
//! use std::io::Cursor;
//! use vorbis::{BitReader, Decoder};
//!
//! let ident_packet = &[]; // Replace with real data.
//! let comment_packet = &[]; // Replace with real data.
//! let setup_packet = &[]; // Replace with real data.
//!
//! let mut builder = Decoder::builder();
//! builder.read_ident_packet(&mut BitReader::new(Cursor::new(ident_packet)))
//!         .expect("Couldn't read ident packet");
//! builder.read_comment_packet(&mut BitReader::new(Cursor::new(comment_packet)))
//!         .expect("Couldn't read comment packet");
//! builder.read_setup_packet(&mut BitReader::new(Cursor::new(setup_packet)))
//!         .expect("Couldn't read setup packet");
//! let mut decoder = builder.build();
//!
//! let mut sample_buf = Vec::with_capacity(decoder.header().frame_lens().long() * decoder.header().channel_count());
//!
//! loop {
//!     let audio_packet = &[]; // Replace with real data.
//!     decoder.decode(&mut BitReader::new(Cursor::new(audio_packet)))
//!             .expect("Couldn't decode audio packet");
//!     if decoder.samples().is_empty() {
//!         continue;
//!     }
//!     sample_buf.truncate(0);
//!     sample_buf.extend(decoder.samples().interleave()
//!             .map(|s| (s * 32767.0 + 0.5).floor() as i16));
//!
//!     // Do something with the sample_buf.
//! }
//! ```

