fn trace_benchmark_group<F: Fn(&sdk::Tracer) -> ()>(c: &mut Criterion, name: &str, f: F) {
    let mut group = c.benchmark_group(name);

    group.bench_function("always-sample", |b| {
        let always_sample = sdk::Provider::builder()
            .with_config(sdk::Config {
                default_sampler: Box::new(sdk::Sampler::Always),
                ..Default::default()
            })
            .build()
            .get_tracer("always-sample");

        b.iter(|| f(&always_sample));
    });

    group.bench_function("never-sample", |b| {
        let never_sample = sdk::Provider::builder()
            .with_config(sdk::Config {
                default_sampler: Box::new(sdk::Sampler::Never),
                ..Default::default()
            })
            .build()
            .get_tracer("never-sample");
        b.iter(|| f(&never_sample));
    });

    group.finish();
}

criterion_group!(benches, criterion_benchmark);
criterion_main!(benches);

use std::env;

use tokio::runtime::Runtime;

use hubcaps::repositories::{OrgRepoType, OrganizationRepoListOptions};
use hubcaps::{Credentials, Github, Result};

fn main() -> Result<()> {
    pretty_env_logger::init();
    match env::var("GITHUB_TOKEN").ok() {
        Some(token) => {
            let mut rt = Runtime::new()?;
            let github = Github::new(
                concat!(env!("CARGO_PKG_NAME"), "/", env!("CARGO_PKG_VERSION")),
                Credentials::Token(token),
            );

            let options = OrganizationRepoListOptions::builder()
                .repo_type(OrgRepoType::Forks)
                .build();

            println!("Forks in the rust-lang organization:");

            for repo in rt.block_on(github.org_repos("rust-lang").list(&options))? {
                println!("{}", repo.name)
            }

            println!("");

            println!("My organizations:");
            for org in rt.block_on(github.orgs().list())? {
                println!("{}", org.login)
            }

            println!("");

            println!("softprops' organizations:");
            for org in rt.block_on(github.user_orgs("softprops").list())? {
                println!("{}", org.login)
            }
            Ok(())
        }
        _ => Err("example missing GITHUB_TOKEN".into()),
    }
}

