extern crate soup;
extern crate url;
extern crate image;

use soup::prelude::*;
use url::{Url, ParseError};
use std::path::PathBuf;
// use image::io::Reader;

#[derive(Debug)]
pub struct ImgMeta {
    pub url: Option<Url>,
    pub filename: Option<String>,
    pub extension: Option<String>,
    pub local_path: Option<String>,
}

pub struct ImgProc {
    target: String,
    tmp_dir_path: PathBuf,
    bw: bool,
    max_size: u32,
}

impl ImgProc {
    pub fn new(target: String, tmp_dir_path: PathBuf, max_size: u32, bw: bool) -> Self {
        Self {
            target,
            tmp_dir_path,
            bw,
            max_size,
        }
    }

    fn absolute_checker(&self, img_url: &str) -> Url {
        // Make sure URL is absolute and add it to urls vector;
        match Url::parse(&img_url) {
            Ok(url) => { url },  // Already absolute, send to vector
            Err(e) => {
                match e {
                    ParseError::RelativeUrlWithoutBase => {
                        // println!("Relative URL: {}", &image_url);
                        let target_url = Url::parse(&self.target);  // Second parsing
                        let absolute_url = target_url.unwrap().join(&img_url)
                            .expect("Can't make absolute URL of image");

                        absolute_url
                    },  // Relative URL error
                    _ => panic!("{:?}", e)
                }  // match error
            }  // if error
        }  // match url parse
    }

    fn img_opt(&self, original: &[u8]) -> anyhow::Result<Vec<u8>> {
        let img = image::load_from_memory(original)
            .expect("Image optimization failed in loading original file");

        let mut thumb = img.thumbnail(self.max_size as u32, self.max_size as u32);

        if self.bw {
            thumb = image::DynamicImage::ImageLuma8(thumb.into_luma8());
        };

        let mut bytes: Vec<u8> = Vec::new();
        thumb.write_to(&mut bytes, image::ImageOutputFormat::Png)?;
        Ok(bytes)
    }

    pub async fn extract(&self, content: String) -> anyhow::Result<Vec<ImgMeta>> {
        let mut metas = Vec::new();
        let soup = Soup::new(&content);

        for img in soup.tag("img").find_all() {
            // Get image absolute URL
            let image_url = img.get("src").expect("Couldn't find `src` attribute");
            let image_url = self.absolute_checker(&image_url);

            // Make HTTP request for target file
            let response = reqwest::get(image_url.as_str()).await?;

            // Getting filename
            let filename = response
                .url()
                .path_segments()
                .and_then(|segments| segments.last())
                .and_then(|name| if name.is_empty() { None } else { Some(name) })
                .unwrap_or("tmp_img.jpg")
                .to_string();

            // println!("Image to download: '{:?}'", filename);

            // Locate destination
            let local_abs_path = self.tmp_dir_path.join(&filename);

            let local_abs_pathstr = local_abs_path
                .clone()
                .into_os_string()
                .into_string()
                .expect("Error converting local abs path to string.");

            // Get extension
            let ext: Option<String> = match local_abs_path.extension() {
                Some(file_ext) => {
                    let extension = file_ext
                        .to_os_string()
                        .into_string()
                        .unwrap();

                    // let point_ext = format!(".{}", extension.clone());
                    // let new_filename = &filename.replace(&point_ext, "");
                    // filename = new_filename.to_string();

                    Some(extension)
                },
                None => None  // No extension
            };

            // Copy file to temp dir
            let mut destination = std::fs::File::create(local_abs_path.clone())?;
            let bytes = &response.bytes().await?[..];

            // (very UGLY) optimization
            let guess = image::io::Reader::open(local_abs_pathstr.clone())?
                .with_guessed_format()?
                .into_dimensions();

            let dimensions = match guess {
                Ok(guessed) => {
                    println!("{:?}", &guessed);
                    guessed
                },
                Err(_) => (0,0)
            };

            let thumbnail;

            if (dimensions.0 > self.max_size) || (dimensions.1 > self.max_size) {
                thumbnail = self.img_opt(bytes)?;
            } else {
                thumbnail = bytes.to_vec();
            }

            let mut bytes = &thumbnail[..];

            // Save on disk
            std::io::copy(&mut bytes, &mut destination).expect("Failed to copy image to dest.");

            // Return meta object
            let meta = ImgMeta {
                url: Some(image_url),
                filename: Some(filename),
                extension: ext, // Some(file_ext)
                local_path: Some(local_abs_pathstr),
            };

            metas.push(meta);
        };  // for img in soup

        // println!("Image metas: {:?}", metas);
        Ok(metas)
    }  // extract
}

//! rsw new

use anyhow::Result;
use regex::Regex;
use std::process::Command;

use crate::config::NewOptions;
use crate::core::RswInfo;
use crate::template::Template;
use crate::utils::{self, get_root, path_exists, print, write_file};

pub struct Create {
    name: String,
    config: NewOptions,
    template: Option<String>,
    mode: Option<String>,
}

/// wasm-pack new
///
/// <https://rustwasm.github.io/docs/wasm-pack/commands/new.html>
impl Create {
    pub fn new(
        config: NewOptions,
        name: String,
        template: Option<String>,
        mode: Option<String>,
    ) -> Create {
        Create {
            name,
            config,
            template,
            mode,
        }
    }
    pub fn init(&self) {
        // println!("{:?}", self.config);
        let name = self.name.as_str();
        let (name2, scope) = utils::get_pkg(name);

        let scope2 = format!("@{}", scope);

        self.check_scope(&scope2);

        let mut args = vec!["new", &name2];
        let arg_tpl = self.template.as_deref();
        let arg_mode = self.mode.as_deref();
        let arg_use = self.config.using.as_ref().unwrap();
        let user_dirs = self.config.dir.as_ref().unwrap();

        self.check_crate();

        // --template: https://rustwasm.github.io/docs/wasm-pack/commands/new.html#template
        if !arg_tpl.is_none() {
            args.push("--template");
            args.push(arg_tpl.unwrap());
        }

        // --mode: https://rustwasm.github.io/docs/wasm-pack/commands/new.html#mode
        if !arg_mode.is_none() {
            args.push("--mode");
            args.push(arg_mode.unwrap());
        }

        // wasm-pack
        if arg_use == "wasm-pack" || !arg_tpl.is_none() {
            self.wp_cmd(&args, &scope2);
        }

        // built-in template
        if arg_use == "rsw" {
            self.create_crate().unwrap();
        }

        // custom template
        if arg_use == "user" {
            if user_dirs.is_empty() {
                self.wp_cmd(&args, &scope2);
            } else {
                self.user_crate(user_dirs);
            }
        }

        print(RswInfo::CrateNewOk(name.into()));
    }
    fn check_scope(&self, scope: &String) {
        if scope != "@" {
            let scope_dir = get_root().join(scope);
            if !path_exists(scope_dir.as_path()) {
                std::fs::create_dir(&scope_dir).unwrap();
            }
        }
    }
    fn check_crate(&self) {
        let name = &self.name;
        let path = get_root().join(name);
        if utils::path_exists(path.as_path()) {
            print(RswInfo::CrateNewExist(name.into()));
            std::process::exit(1);
        }
    }
    fn wp_cmd(&self, args: &Vec<&str>, scope: &String) {
        let mut scope_dir = get_root();
        if scope != "@" {
            scope_dir = scope_dir.join(scope);
        }
        Command::new("wasm-pack")
            .current_dir(scope_dir)
            .args(args)
            .status()
            .expect("failed to execute process");
    }
    fn create_crate(&self) -> Result<()> {
        let target = get_root().join(&self.name);
        let root = std::path::Path::new(&target);
        let template = Template::new(&root);

        let (name, _) = utils::get_pkg(&self.name);
        let re = Regex::new(r"(?P<name>rsw-template)").unwrap();
        let cargo = re.replace(std::str::from_utf8(&template.cargo).unwrap(), name);
        let readme = re.replace(std::str::from_utf8(&template.readme).unwrap(), &self.name);

        write_file(root, "README.md", readme.as_bytes())?;
        write_file(root, "Cargo.toml", &cargo.as_bytes())?;
        write_file(root, "src/lib.rs", &template.lib)?;

        Ok(())
    }
    fn user_crate(&self, dir: &str) {
        let root = get_root();
        let source = root.join(dir);
        if !path_exists(source.as_path()) {
            print(RswInfo::ConfigNewDir(dir.into(), source));
            std::process::exit(1);
        }
        utils::copy_dirs(root.join(dir), root.join(&self.name)).unwrap();
    }
}

