use crate::Trait;
use sp_std::vec::Vec;

pub fn get_slice<T: Trait, B: Clone>(
    vec: Vec<B>,
    start_position: u64,
    batch_size: u64,
) -> Vec<B> {
    // the # max nr of items in the vector
    let n = vec.len();

    // compute the range end_position
    // if the computed range end_position is larger than n, use n, else, use computed value
    let end_position = start_position as usize + batch_size as usize;
    let end_position = if end_position > n { n } else { end_position };

    // create range
    let range = start_position as usize..end_position;

    // retrieve ciphers in range
    let slice = vec
        .get(range)
        .expect("tried to retrieve ciphers in a range which doesn't exist!");
    slice.to_vec()
}

//! Parses command line options of ssup
use std::process::Command;

use clap::{crate_authors, crate_description, crate_version, AppSettings, Clap};

const TEMPLATE: &str = "

   █████  █████  █████ ████ ████████ 
  ███░░  ███░░  ░░███ ░███ ░░███░░███
░░░█████ ░█████  ░███ ░███  ░███ ░███
  ░░░░███░░░░███ ░███ ░███  ░███ ░███
  ██████ ██████  ░░████████ ░███████ 
░░░░░░░  ░░░░░    ░░░░░░░░  ░███░░░  
                            ░███     
                            █████    
                           ░░░░░     
{bin} {version} - {author}
{about}

{usage-heading}
{usage}

{all-args}
";

#[derive(Clap)]
#[clap(author = crate_authors!(), version=crate_version!(), about=crate_description!(), help_template=TEMPLATE)]
#[clap(setting = AppSettings::ColoredHelp, setting = AppSettings::DeriveDisplayOrder)]
pub struct Opts {
    /// Optional title for the notification
    #[clap(short, long, default_value = "Ssup!")]
    pub title: String,

    /// Notify with this message
    #[clap(short, long)]
    pub message: String,

    /// Choose where to send the notification to
    #[clap(short, long, possible_values=&["local", "telegram"], default_value="local")]
    pub destination: String,

    /// {Telegram specific option} Chat id to which notification should be sent
    #[clap(long, required_if_eq("destination", "telegram"))]
    pub chat_id: Option<String>,

    /// {Telegram specific option } Optionally specify Telegram bot token in command instead of reading from env
    #[clap(long)]
    pub bot_token: Option<String>,

    /// Specify a command/executable to run and notify when it finishes
    #[clap()]
    pub command: Option<String>,
}

pub fn parse_opts() -> Opts {
    Opts::parse()
}

impl Opts {
    pub fn run_command(&self) -> Option<bool> {
        // TODO: Do this in a separate thread / async
        match &self.command {
            Some(run) => {
                // let split_cmd: Vec<&str> = run.split(' ').collect();
                // let executable = split_cmd[0];
                let split_cmd: Vec<String> = shlex::Shlex::new(run).by_ref().collect();
                let mut cmd = Command::new(&split_cmd[0]);
                if split_cmd.len() > 1 {
                    cmd.args(&split_cmd[1..]);
                }

                Some(
                    cmd.status()
                        .expect("Could not parse command exit status")
                        .success(),
                )
            }
            _ => None,
        }
    }
}

