//! A [Latin square](https://en.wikipedia.org/wiki/Latin_square) is a
//!  n × n array filled with n different symbols, each occurring exactly once in
//! each row and exactly once in each column.

use crate::ExactCover;
use core::iter;
use std::collections::HashSet;

/// Instance of a Latin square puzzle.
#[derive(Debug)]
pub struct LatinSquare {
    /// The list of possible positions + values that could solve the Latin
    /// square puzzle.
    pub possibilities: Vec<Possibility>,
    /// The list of constraints that must be satisfied for this Latin square
    /// puzzle.
    pub constraints: Vec<Constraint>,
}

impl LatinSquare {
    /// Create a new Latin square puzzle.
    ///
    /// The puzzle has dimensions `side_length` × `side_length` and the given
    /// list of filled values.
    pub fn new(side_length: usize, filled_values: impl IntoIterator<Item = Possibility>) -> Self {
        let filled_values: Vec<_> = filled_values
            .into_iter()
            .inspect(|poss| {
                debug_assert!(
                    0 < poss.value && poss.value <= side_length,
                    "Symbol values should be in range (0..side_length)"
                )
            })
            .collect();

        let satisfied: HashSet<_> = filled_values
            .iter()
            .copied()
            .flat_map(Possibility::satisfied_constraints)
            .collect();

        let filled_coordinates: HashSet<_> = filled_values
            .iter()
            .map(|poss| (poss.row, poss.column))
            .collect();

        let possibilities: Vec<_> = Possibility::all(side_length)
            .filter(|poss| !filled_coordinates.contains(&(poss.row, poss.column)))
            .collect();

        let constraints = Constraint::all(side_length)
            .filter(|cons| !satisfied.contains(cons))
            .collect();

        Self {
            possibilities,
            constraints,
        }
    }
}

impl ExactCover for LatinSquare {
    type Constraint = Constraint;
    type Possibility = Possibility;

    fn satisfies(&self, poss: &Self::Possibility, cons: &Self::Constraint) -> bool {
        poss.satisfies(cons)
    }

    fn is_optional(&self, _cons: &Self::Constraint) -> bool {
        false
    }

    fn possibilities(&self) -> &[Self::Possibility] {
        &self.possibilities
    }

    fn constraints(&self) -> &[Self::Constraint] {
        &self.constraints
    }
}

/// A position and value for a box inside of a Latin square puzzle.
#[derive(Debug, Copy, Clone, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct Possibility {
    /// The row position of the box.
    ///
    /// The values ranges from 0 to `side_length - 1`.
    pub row: usize,

    /// The column position of the box.
    ///
    /// The values ranges from 0 to `side_length - 1`.
    pub column: usize,

    /// The value present inside of the box.
    ///
    /// The values ranges from 1 to `side_length`.
    pub value: usize,
}

impl Possibility {
    /// Return an iterator over all possible `Possibility`s for the given
    /// `side_length`.
    pub fn all(side_length: usize) -> impl Iterator<Item = Self> {
        crate::util::three_combination_iter([side_length, side_length, side_length + 1], [0, 0, 1])
            .map(|[column, row, value]| Possibility { row, column, value })
    }

    /// Return an iterator over all `Constraint`s that are satisfied by this
    /// `Possibility`.
    pub fn satisfied_constraints(self) -> impl Iterator<Item = Constraint> {
        iter::successors(
            Some(Constraint::RowNumber {
                row: self.row,
                value: self.value,
            }),
            move |cons| match cons {
                Constraint::RowNumber { .. } => Some(Constraint::ColumnNumber {
                    column: self.column,
                    value: self.value,
                }),
                Constraint::ColumnNumber { .. } => Some(Constraint::RowColumn {
                    row: self.row,
                    column: self.column,
                }),
                Constraint::RowColumn { .. } => None,
            },
        )
    }

    /// Return true if this `Possibility` satisfies the given `Constraint`.
    pub fn satisfies(&self, constraint: &Constraint) -> bool {
        use Constraint::*;

        match constraint {
            RowNumber { row, value } => self.row == *row && self.value == *value,
            ColumnNumber { column, value } => self.column == *column && self.value == *value,
            RowColumn { row, column } => self.row == *row && self.column == *column,
        }
    }
}

/// A condition which must be satisfied in order to solve a Latin square puzzle.
#[derive(Debug, Copy, Clone, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Constraint {
    /// A condition that each row should only have a single instance of a
    /// numeric value.
    RowNumber {
        /// The row index
        row: usize,
        /// The unique numeric value
        value: usize,
    },
    /// A condition that each column should only have a single instance of a
    /// numeric value.
    ColumnNumber {
        /// The column index
        column: usize,
        /// The unique numeric value
        value: usize,
    },
    /// A condition that each row, column pair should exist exactly once.
    RowColumn {
        /// The row index
        row: usize,
        /// The column index
        column: usize,
    },
}

impl Constraint {
    /// Return an iterator over all possibly `Constraint`s for the given
    /// `side_length`.
    pub fn all(side_length: usize) -> impl Iterator<Item = Constraint> {
        let row_number_it =
            crate::util::two_combination_iter([side_length, side_length + 1], [0, 1])
                .map(|[row, value]| Constraint::RowNumber { row, value });

        let column_number_it =
            crate::util::two_combination_iter([side_length, side_length + 1], [0, 1])
                .map(|[column, value]| Constraint::ColumnNumber { column, value });

        let row_column_it = crate::util::two_combination_iter([side_length, side_length], [0, 0])
            .map(|[row, column]| Constraint::RowColumn { row, column });

        row_number_it.chain(column_number_it).chain(row_column_it)
    }
}

#[cfg(test)]
pub(crate) mod tests {
    use super::*;

    pub(crate) fn p(row: usize, column: usize, value: usize) -> Possibility {
        Possibility { row, column, value }
    }

    fn c_row(row: usize, value: usize) -> Constraint {
        Constraint::RowNumber { row, value }
    }

    fn c_col(column: usize, value: usize) -> Constraint {
        Constraint::ColumnNumber { column, value }
    }

    fn c_row_col(row: usize, column: usize) -> Constraint {
        Constraint::RowColumn { row, column }
    }

    #[test]
    fn check_all_possibilities() {
        let some_possibilities: Vec<_> = Possibility::all(2).collect();

        assert_eq!(
            &some_possibilities,
            &[
                p(0, 0, 1),
                p(0, 0, 2),
                p(1, 0, 1),
                p(1, 0, 2),
                p(0, 1, 1),
                p(0, 1, 2),
                p(1, 1, 1),
                p(1, 1, 2),
            ]
        );
    }

    #[test]
    fn check_generated_possibilities_constraints() {
        let mut square = LatinSquare::new(2, vec![p(0, 0, 1), p(0, 1, 2)]);

        square.possibilities.sort();
        assert_eq!(
            square.possibilities,
            vec![p(1, 0, 1), p(1, 0, 2), p(1, 1, 1), p(1, 1, 2)]
        );
        square.constraints.sort();
        assert_eq!(
            square.constraints,
            vec![
                c_row(1, 1),
                c_row(1, 2),
                c_col(0, 2),
                c_col(1, 1),
                c_row_col(1, 0),
                c_row_col(1, 1)
            ]
        );
    }

    #[test]
    fn solve_small_latin_square() {
        let square = LatinSquare::new(2, vec![p(0, 0, 1), p(0, 1, 2)]);
        let mut solver = square.solver();
        let solutions = solver.all_solutions();

        assert_eq!(solutions.len(), 1);
        assert_eq!(solutions[0], vec![&p(1, 0, 2), &p(1, 1, 1)]);
    }

    #[test]
    fn solve_multi_solution_latin_square() {
        let square = LatinSquare::new(2, vec![]);
        let mut solver = square.solver();
        let solutions = solver.all_solutions();

        assert_eq!(solutions.len(), 2);

        assert_eq!(
            solutions[0],
            vec![&p(0, 0, 1), &p(0, 1, 2), &p(1, 1, 1), &p(1, 0, 2)]
        );
        assert_eq!(
            solutions[1],
            vec![&p(0, 1, 1), &p(0, 0, 2), &p(1, 0, 1), &p(1, 1, 2)]
        );
    }

    #[test]
    fn solve_impossible_latin_square() {
        let square = LatinSquare::new(2, vec![p(0, 0, 1), p(0, 1, 1)]);
        let mut solver = square.solver();
        let solutions = solver.all_solutions();

        assert_eq!(solutions.len(), 0);
    }
}

use alloc::{vec::Vec};

use ckb_std::{ckb_constants::Source, high_level::*};
use ckb_std::ckb_types::{bytes::Bytes, prelude::*};

use crate::error::Error;

pub const TIME_INFO_CELL_DATA_LEN: u8 = 5;
pub const TIME_INFO_CELL_DATA_N: u8 = 12;

pub fn get_script_hash_cell_count(script_hash: [u8; 32], source: Source) -> usize {
    QueryIter::new(load_cell_type_hash, source).
        filter(|type_hash| {
            match type_hash {
                Some(type_script_hash) => *type_script_hash == script_hash,
                None => false
            }
        }).
        count()
}

pub fn get_position_of_cell_with_type_script(
    script_hash: [u8; 32],
    source: Source,
) -> Option<usize> {
    QueryIter::new(load_cell_type_hash, source).position(|type_script_op| match type_script_op {
        Some(type_script) => type_script == script_hash,
        None => false,
    })
}

pub fn load_cell_data(script_hash: [u8; 32], source: Source) -> Result<Vec<u8>, Error> {
    let cell_index = match get_position_of_cell_with_type_script(script_hash, source) {
        Some(position) => position,
        None => return match source {
            Source::Input | Source::GroupInput => Err(Error::InvalidTimeInfoInput),
            Source::Output | Source::GroupOutput => Err(Error::InvalidTImeInfoOutput),
            _ => Err(Error::ItemMissing),
        },
    };
    match ckb_std::high_level::load_cell_data(cell_index, source) {
        Ok(cell_data) => Ok(cell_data),
        Err(sys_err) => Err(Error::from(sys_err)),
    }
}

pub fn get_timestamp_from_cell_data(cell_data: &Vec<u8>) -> u32 {
    let mut buf = [0_u8; 4];
    buf.copy_from_slice(&(cell_data.as_slice()[1..]));
    u32::from_be_bytes(buf)
}

pub fn cell_args_check(script_hash: [u8; 32]) -> Result<(), Error> {
    let script = load_script()?;
    let script_args: Bytes = script.args().unpack();
    if script_args.is_empty() {
        return Err(Error::InvalidArgument);
    }

    let cell_index = match get_position_of_cell_with_type_script(script_hash, Source::Input) {
        Some(position) => position,
        None => return Err(Error::InvalidTimeInfoInput),
    };
    let input_cell_data = load_cell(cell_index, Source::Input)?;
    let input_script = match input_cell_data.type_().to_opt() {
        Some(type_script) => type_script,
        None => return Err(Error::InvalidTimeInfoInput),
    };
    let input_script_args: Bytes = input_script.args().unpack();

    if input_script_args[..] != script_args[..] {
        return Err(Error::InvalidArgument);
    }
    Ok(())
}

pub fn timestamp_check(last_timestamp: u32, current_timestamp: u32) -> Result<(), Error> {
    if current_timestamp <= last_timestamp {
        return Err(Error::InvalidTimestamp);
    }
    Ok(())
}

pub fn input_cell_since_check(timestamp: u32) -> Result<(), Error> {
    let since_base: u64 = 1 << 62;
    if QueryIter::new(load_input_since, Source::GroupInput).
        any(|since| since != since_base + timestamp as u64) {
        return Err(Error::InvalidTimeSince);
    }
    Ok(())
}

//! # Signal generators
//!
//! Those generators can be used as a sound source.
//! 
//! ## Example
//!
//! Here we will create simple sinusoidal generator with the frequency of 440Hz.
//! And next we will use it to generate few samples
//!
//! ```rust
//! use sounds::generators::sine;
//! 
//! let mut gen = sine(44_000, 440.0);
//! let sample1 = gen.next_sample();
//! let sample2 = gen.next_sample();
//! ```

use std::f32::consts::PI;
use rand;
use rand::distributions::{Normal, Distribution};


/// Signal Generator. 
pub struct SignalGen<F>
where
    F: Fn(f32) -> f32,
{
    sample_rate: f32,
    sample_clock: f32,
    signal: F,
}

impl<F> SignalGen<F>
where
    F: Fn(f32) -> f32,
{
    /// Create a new generator from provided function
    pub fn new(sample_rate: u32, signal: F) -> SignalGen<F> {
        SignalGen { 
            sample_rate: sample_rate as f32, 
            sample_clock: 0.0, 
            signal 
        }
    }

    /// Generate next signal sample.
    pub fn next_sample(&mut self) -> f32 {
        self.sample_clock = (self.sample_clock + 1.0) % self.sample_rate;
        (self.signal)(self.sample_clock / self.sample_rate)
    }
}

/// Create generator of sinusoidal signal with the given frequency in Hz.
pub fn sine(sample_rate: u32, freq: f32) -> SignalGen<impl Fn(f32) -> f32> {
    let w = 2.0 * PI * freq;
    SignalGen::new(sample_rate, move |i| (i*w).sin())
}

/// Periodic triangle signal.
pub fn triangle(sample_rate: u32, freq: f32) -> SignalGen<impl Fn(f32) -> f32> {
   let w = 2.0 * freq;
   SignalGen::new(sample_rate, move |i| (i*w) % 2.0 - 1.0)
}

/// Periodic square signal.
pub fn square(sample_rate: u32, freq: f32) -> SignalGen<impl Fn(f32) -> f32> {
   let w = freq;
   SignalGen::new(
       sample_rate,
       move |i| {
        let a = w * i % 1.;
        if a < -0.5 || (a > 0.0 && a < 0.5) {
            1.0
        } else {
            -1.0
        }
    })
}

///// A chirp is a signal in which frequency increases with time.
//pub fn chirp(start_freq: f64, end_freq: f64, time: f64) -> SignalGen<impl Fn(f64) -> Complex64> {
//    let slope = (end_freq - start_freq) / time;
//    SignalGen::new(move |i| {
//        if i < 0. || i > time {
//            Complex::new(0., 0.)
//        } else {
//            let f = slope * i + start_freq;
//            let w = 2.0 * PI * f * i;
//            Complex::new(0., w).exp()
//        }
//    })
//}

/// A real noise (without imaginary part)
pub fn noise(sample_rate: u32) -> SignalGen<impl Fn(f32) -> f32> {
   let normal = Normal::new(0.0, 0.3);
   SignalGen::new(sample_rate, move |_| {
       normal.sample(&mut rand::thread_rng()) as f32
   })
}

