macro_rules! gcd {
    ($bencher:ident, $pair:ident, $type:ty) => {{
        let (ref lhs, ref rhs): ($type, $type) = $pair.into();
        $bencher.iter(move || black_box(lhs).gcd(black_box(rhs)))
    }};
}

fn gcd(c: &mut Criterion) {
