            Ok(Default::default())
        }
    }
}

use std::collections::BTreeSet;
use std::process::Command;

fn main() {
    let example_to_run = std::env::args().nth(1);
    let examples = std::fs::read_dir("examples").unwrap();
    let examples = examples
        .filter_map(|e| {
            let e = e.unwrap();
            let path = e.path();
            let dir = e.metadata().unwrap().is_dir();
            if let Some("wat") = path.extension().and_then(|s| s.to_str()) {
                return None;
            }

            Some((path.file_stem().unwrap().to_str().unwrap().to_owned(), dir))
        })
        .collect::<BTreeSet<_>>();

    println!("======== Building libwasmtime.a ===========");
    run(Command::new("cargo")
        .args(&["build"])
        .current_dir("crates/c-api"));

    for (example, is_dir) in examples {
        if example == "README" {
            continue;
        }
        if let Some(example_to_run) = &example_to_run {
            if !example.contains(&example_to_run[..]) {
                continue;
            }
        }
        if is_dir {
            println!("======== Rust wasm file `{}` ============", example);
            let target = if example == "fib-debug" {
                "wasm32-unknown-unknown"
            } else {
                "wasm32-wasi"
            };
            run(Command::new("cargo")
                .arg("build")
                .arg("-p")
                .arg(format!("example-{}-wasm", example))
                .arg("--target")
                .arg(target));
        }
        println!("======== Rust example `{}` ============", example);
        run(Command::new("cargo")
            .arg("run")
            .arg("--example")
            .arg(&example));

        println!("======== C/C++ example `{}` ============", example);
        for extension in ["c", "cc"].iter() {
            let mut cmd = cc::Build::new()
                .opt_level(0)
                .cargo_metadata(false)
                .target(env!("TARGET"))
                .host(env!("TARGET"))
                .include("crates/c-api/include")
                .include("crates/c-api/wasm-c-api/include")
                .define("WASM_API_EXTERN", Some("")) // static linkage, not dynamic
                .warnings(false)
                .get_compiler()
                .to_command();

            let file = if is_dir {
                format!("examples/{}/main.{}", example, extension)
            } else {
                format!("examples/{}.{}", example, extension)
            };

            if extension == &"cc" && !std::path::Path::new(&file).exists() {
                // cc files are optional so we can skip them.
                continue;
            }

            cmd.arg(file);
            let exe = if cfg!(windows) {
                cmd.arg("target/debug/wasmtime.lib")
                    .arg("ws2_32.lib")
                    .arg("advapi32.lib")
                    .arg("userenv.lib")
                    .arg("ntdll.lib")
                    .arg("shell32.lib")
                    .arg("ole32.lib");
                "./main.exe"
            } else {
                cmd.arg("target/debug/libwasmtime.a").arg("-o").arg("foo");
                "./foo"
            };
            if cfg!(target_os = "linux") {
                cmd.arg("-lpthread").arg("-ldl").arg("-lm");
            }
            run(&mut cmd);

            run(&mut Command::new(exe));
        }
    }
}

fn run(cmd: &mut Command) {
    let s = cmd.status().unwrap();
    if !s.success() {
        eprintln!("failed to run {:?}", cmd);
        eprintln!("status: {}", s);
        std::process::exit(1);
    }
}

use super::*;
use crate::ast::TypeAst;
use std::sync::Arc;

/// The Hydrator takes an AST representing a type (i.e. a type annotation
/// for a function argument) and returns a Type for that annotation.
///
/// If a valid Type cannot be constructed it returns an error.
///
/// It keeps track of any type variables created. This is useful for:
///
/// - Determining if a generic type variable should be made into an
///   unbound type varable during type instantiation.
/// - Ensuring that the same type is constructed if the programmer
///   uses the same name for a type variable multiple times.
///
#[derive(Debug)]
pub struct Hydrator {
    created_type_variables: im::HashMap<String, Arc<Type>>,
    created_type_variable_ids: im::HashSet<usize>,
    permit_new_type_variables: bool,
    permit_holes: bool,
}

#[derive(Debug)]
pub struct ScopeResetData {
    created_type_variables: im::HashMap<String, Arc<Type>>,
    created_type_variable_ids: im::HashSet<usize>,
}

impl Default for Hydrator {
    fn default() -> Self {
        Self::new()
    }
}

impl Hydrator {
    pub fn new() -> Self {
        Self {
            created_type_variables: im::hashmap![],
            created_type_variable_ids: im::hashset![],
            permit_new_type_variables: true,
            permit_holes: false,
        }
    }

    pub fn open_new_scope(&mut self) -> ScopeResetData {
        let created_type_variables = self.created_type_variables.clone();
        let created_type_variable_ids = self.created_type_variable_ids.clone();
        ScopeResetData {
            created_type_variables,
            created_type_variable_ids,
        }
    }

    pub fn close_scope(&mut self, data: ScopeResetData) {
        self.created_type_variables = data.created_type_variables;
        self.created_type_variable_ids = data.created_type_variable_ids;
    }

    pub fn disallow_new_type_variables(&mut self) {
        self.permit_new_type_variables = false
    }

    pub fn permit_holes(&mut self, flag: bool) {
        self.permit_holes = flag
    }

    pub fn is_created_generic_type(&self, id: &usize) -> bool {
        self.created_type_variable_ids.contains(id)
    }

    pub fn type_from_option_ast<'a, 'b>(
        &mut self,
        ast: &Option<TypeAst>,
        environment: &mut Environment<'a, 'b>,
    ) -> Result<Arc<Type>, Error> {
        match ast {
            Some(ast) => self.type_from_ast(ast, environment),
            None => Ok(environment.new_unbound_var(environment.level)),
        }
    }

    /// Construct a Type from an AST Type annotation.
    ///
    pub fn type_from_ast<'a, 'b>(
        &mut self,
        ast: &TypeAst,
        environment: &mut Environment<'a, 'b>,
    ) -> Result<Arc<Type>, Error> {
        match ast {
            TypeAst::Constructor {
                location,
                module,
                name,
                arguments: args,
            } => {
                // Hydrate the type argument AST into types
                let mut argument_types = Vec::with_capacity(args.len());
                for t in args {
                    let typ = self.type_from_ast(t, environment)?;
                    argument_types.push((t.location(), typ));
                }

                // Look up the constructor
                let TypeConstructor {
                    parameters,
                    typ: return_type,
                    ..
                } = environment
                    .get_type_constructor(module, name)
                    .map_err(|e| convert_get_type_constructor_error(e, location))?
                    .clone();

                // Register the type constructor as being used if it is unqualifed.
                // We do not track use of qualified type constructors as they may be
                // used in another module.
                if module.is_none() {
                    environment.increment_usage(name);
                }

                // Ensure that the correct number of arguments have been given to the constructor
                if args.len() != parameters.len() {
                    return Err(Error::IncorrectTypeArity {
                        location: *location,
                        name: name.to_string(),
                        expected: parameters.len(),
                        given: args.len(),
                    });
                }

                // Instantiate the constructor type for this specific usage
                let mut type_vars = hashmap![];
                let parameter_types: Vec<_> = parameters
                    .into_iter()
                    .map(|typ| environment.instantiate(typ, 0, &mut type_vars, self))
                    .collect();

                let return_type = environment.instantiate(return_type, 0, &mut type_vars, self);

                // Unify argument types with instantiated parameter types so that the correct types
                // are inserted into the return type
                for (parameter, (location, argument)) in
                    parameter_types.into_iter().zip(argument_types)
                {
                    environment
                        .unify(parameter, argument)
                        .map_err(|e| convert_unify_error(e, location))?;
                }

                Ok(return_type)
            }

            TypeAst::Tuple { elems, .. } => Ok(tuple(
                elems
                    .iter()
                    .map(|t| self.type_from_ast(t, environment))
                    .try_collect()?,
            )),

            TypeAst::Fn {
                arguments: args,
                return_: retrn,
                ..
            } => {
                let args = args
                    .iter()
                    .map(|t| self.type_from_ast(t, environment))
                    .try_collect()?;
                let retrn = self.type_from_ast(retrn, environment)?;
                Ok(fn_(args, retrn))
            }

            TypeAst::Var { name, location, .. } => match self.created_type_variables.get(name) {
                Some(var) => Ok(var.clone()),

                None if self.permit_new_type_variables => {
                    let var = environment.new_generic_var();
                    let _ = self
                        .created_type_variable_ids
                        .insert(environment.previous_uid());
                    let _ = self
                        .created_type_variables
                        .insert(name.clone(), var.clone());
                    Ok(var)
                }

                None => Err(Error::UnknownType {
                    name: name.to_string(),
                    location: *location,
                    types: environment
                        .module_types
                        .keys()
                        .map(|t| t.to_string())
                        .collect(),
                }),
            },

            TypeAst::Hole { .. } if self.permit_holes => {
                Ok(environment.new_unbound_var(environment.level))
            }

            TypeAst::Hole { location, .. } => Err(Error::UnexpectedTypeHole {
                location: *location,
            }),
        }
    }
}

//! A [`super::Chain`] which keeps only the data needed to recover the state of its subject in the
//! event of a transaction failure.

use async_trait::async_trait;
use destream::de;
use futures::future::TryFutureExt;
use futures::join;

use tc_error::*;
use tc_transact::fs::{Persist, Store};
use tc_transact::{IntoView, Transact, Transaction, TxnId};
use tcgeneric::TCPathBuf;

use crate::fs;
use crate::scalar::{Link, Value};
use crate::state::{State, StateView};
use crate::txn::Txn;

use super::data::History;
use super::{ChainBlock, ChainInstance, ChainType, Schema, Subject, NULL_HASH};

/// A [`super::Chain`] which keeps only the data needed to recover the state of its subject in the
/// event of a transaction failure.
#[derive(Clone)]
pub struct SyncChain {
    schema: Schema,
    subject: Subject,
    history: History,
}

#[async_trait]
impl ChainInstance for SyncChain {
    async fn append_delete(&self, txn_id: TxnId, path: TCPathBuf, key: Value) -> TCResult<()> {
        let mut block = self.history.write_latest(txn_id).await?;
        block.clear_until(&txn_id);
        block.append_delete(txn_id, path, key);
        Ok(())
    }

    async fn append_put(
        &self,
        txn: &Txn,
        path: TCPathBuf,
        key: Value,
        value: State,
    ) -> TCResult<()> {
        {
            let mut block = self.history.write_latest(*txn.id()).await?;
            block.clear_until(txn.id());
        }

        self.history.append_put(txn, path, key, value).await
    }

    async fn last_commit(&self, txn_id: TxnId) -> TCResult<Option<TxnId>> {
        self.history.last_commit(txn_id).await
    }

    fn subject(&self) -> &Subject {
        &self.subject
    }

    async fn replicate(&self, txn: &Txn, source: Link) -> TCResult<()> {
        let subject = txn.get(source, Value::None).await?;
        self.subject.restore(txn, subject).await?;

        let mut block = self.history.write_latest(*txn.id()).await?;
        *block = ChainBlock::with_txn(NULL_HASH, *txn.id());

        Ok(())
    }

    async fn write_ahead(&self, txn_id: &TxnId) {
        self.history.commit(txn_id).await
    }
}

#[async_trait]
impl Persist<fs::Dir> for SyncChain {
    type Schema = Schema;
    type Store = fs::Dir;
    type Txn = Txn;

    fn schema(&self) -> &Schema {
        &self.schema
    }

    async fn load(txn: &Txn, schema: Self::Schema, dir: fs::Dir) -> TCResult<Self> {
        let is_new = dir.is_empty(txn.id()).await?;

        let subject = Subject::load(txn, schema.clone(), &dir).await?;

        let history = if is_new {
            History::create(*txn.id(), dir, ChainType::Sync).await?
        } else {
            History::load(txn, (), dir).await?
        };

        let latest = history.latest_block_id(txn.id()).await?;
        if latest > 0 {
            return Err(TCError::internal(format!(
                "a SyncChain can only have one block, found {}",
                latest
            )));
        }

        history.apply_last(txn, &subject).await?;

        Ok(SyncChain {
            schema,
            subject,
            history,
        })
    }
}

#[async_trait]
impl Transact for SyncChain {
    async fn commit(&self, txn_id: &TxnId) {
        self.subject.commit(txn_id).await;
    }

    async fn finalize(&self, txn_id: &TxnId) {
        join!(self.subject.finalize(txn_id), self.history.finalize(txn_id));
    }
}

#[async_trait]
impl<'en> IntoView<'en, fs::Dir> for SyncChain {
    type Txn = Txn;
    type View = (Schema, StateView<'en>);

    async fn into_view(self, txn: Self::Txn) -> TCResult<Self::View> {
        Ok((self.schema, self.subject.into_view(txn).await?))
    }
}

struct ChainVisitor {
    txn: Txn,
}

#[async_trait]
impl de::Visitor for ChainVisitor {
    type Value = SyncChain;

    fn expecting() -> &'static str {
        "a SyncChain"
    }

    async fn visit_seq<A: de::SeqAccess>(self, mut seq: A) -> Result<Self::Value, A::Error> {
        let history = History::create(*self.txn.id(), self.txn.context().clone(), ChainType::Sync)
            .map_err(de::Error::custom)
            .await?;

        let schema = seq
            .next_element(())
            .await?
            .ok_or_else(|| de::Error::invalid_length(0, "a SyncChain schema"))?;

        let subject = seq
            .next_element(self.txn)
            .await?
            .ok_or_else(|| de::Error::invalid_length(1, "the subject of a SyncChain"))?;

        Ok(SyncChain {
            schema,
            subject,
            history,
        })
    }
}

#[async_trait]
impl de::FromStream for SyncChain {
    type Context = Txn;

    async fn from_stream<D: de::Decoder>(txn: Txn, decoder: &mut D) -> Result<Self, D::Error> {
        let visitor = ChainVisitor { txn };
        decoder.decode_seq(visitor).await
    }
}

extern crate getopts;

use std::{env, process};
use getopts::Options;
use std::net::{SocketAddrV4, Ipv4Addr};

mod wol {
    extern crate regex;

    use wol::regex::Regex;

    use std::error::Error;
    use std::str::FromStr;
    use std::net::{UdpSocket, SocketAddrV4, Ipv4Addr};

    #[cfg(test)]
    mod test {
        use super::{build_packet, send_packet, Mac, ParseError};
        use std::net::{SocketAddrV4, Ipv4Addr};

        #[test]
        fn can_parse_valid_mac() {
            assert_eq!("ff:ff:ff:ff:ff:ff".parse::<Mac>().unwrap(),
                       Mac(255, 255, 255, 255, 255, 255));
            assert_eq!("FF:FF:FF:FF:FF:FF".parse::<Mac>().unwrap(),
                       Mac(255, 255, 255, 255, 255, 255));
            assert_eq!("00:00:00:00:00:00".parse::<Mac>().unwrap(),
                       Mac(0, 0, 0, 0, 0, 0));
        }

        #[test]
        fn return_error_for_invalid_mac() {
            let macs = vec![":::::", "ff:ff:ff:ff:ff:fg", "ff:ff:ff:ff:ff:ff:ff"];
            for m in macs {
                match m.parse::<Mac>() {
                    Err(e) => assert_eq!(e, ParseError::InvalidInput),
                    Ok(_) => unreachable!(),
                };
            }
        }

        #[test]
        fn can_build_magic_packet() {
            let mac: Mac = "ff:ff:ff:ff:ff:ff".parse().unwrap();
            assert_eq!(build_packet(&mac).unwrap().is_empty(), false);
            assert_eq!(build_packet(&mac).unwrap().len(), 102);
            assert_eq!(build_packet(&mac).unwrap(), vec![255; 102]);
        }

        #[test]
        fn can_send_packet_loopback() {
            let raddr = SocketAddrV4::new(Ipv4Addr::new(127, 0, 0, 1), 9);
            assert_eq!(send_packet(&vec![0xff; 102], &raddr).unwrap(), true);
        }
    }

    #[derive(Debug)]
    pub enum WolError {
        InvalidBufferLength,
        InvalidPacketSize,
    }

    #[derive(Debug, PartialEq)]
    pub enum ParseError {
        FailedConversion,
        InvalidInput,
        InvalidLength,
    }

    #[derive(Debug, PartialEq)]
    pub struct Mac(u8, u8, u8, u8, u8, u8);

    impl Mac {
        pub fn new(a: (u8, u8, u8, u8, u8, u8)) -> Mac {
            Mac(a.0, a.1, a.2, a.3, a.4, a.5)
        }

        fn as_bytes(&self) -> [u8; 6] {
            [self.0, self.1, self.2, self.3, self.4, self.5]
        }
    }

    impl FromStr for Mac {
        type Err = ParseError;

        fn from_str(s: &str) -> Result<Self, Self::Err> {
            let valid_mac = {
                Regex::new("^([0-9A-Fa-f]{2}:){5}([0-9A-Fa-f]{2})$").unwrap()
            };

            if valid_mac.is_match(s) {
                match s.split(':')
                    .map(|e| u8::from_str_radix(e, 16))
                    .collect::<Result<Vec<_>, _>>() {
                    Ok(r) => {
                        if r.len() == 6 {
                            Ok(Mac::new((r[0], r[1], r[2], r[3], r[4], r[5])))
                        } else {
                            Err(ParseError::InvalidLength)
                        }
                    }
                    Err(_) => Err(ParseError::FailedConversion),
                }
            } else {
                Err(ParseError::InvalidInput)
            }
        }
    }

    pub fn build_packet(mac: &Mac) -> Result<Vec<u8>, WolError> {
        let mut packet = vec![0xff; 6];
        let payload = mac.as_bytes();

        match payload.len() {
            6 => {
                for _ in 0..16 {
                    packet.extend_from_slice(&payload);
                }
            }
            _ => return Err(WolError::InvalidBufferLength),
        }

        match packet.len() {
            102 => return Ok(packet),
            _ => return Err(WolError::InvalidPacketSize),
        }
    }

    pub fn send_packet(p: &[u8], r: &SocketAddrV4) -> Result<bool, Box<Error>> {
        let laddr = SocketAddrV4::new(Ipv4Addr::new(0, 0, 0, 0), 0);
        let socket = try!(UdpSocket::bind(laddr));

        try!(socket.send_to(&p[0..102], r));

        Ok(true)
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut opts: Options = Options::new();

    opts.optopt("m", "mac", "MAC address in the form FF:FF:FF:FF:FF:FF", "")
        .optopt("b", "bcast", "broadcast address", "")
        .optflag("h", "help", "display this help");

    let name = args[0].clone();

    let usage = format!("Usage: {}", opts.usage(&(name + " [options]")));

    let exit = |msg: &str, code: i32| -> ! {
        println!("{}", msg);
        process::exit(code);
    };

    let matches = opts.parse(&args[1..])
        .unwrap_or_else(|e| exit(&format!("could not parse args: {:?}", e), 1));

    if matches.opt_present("help") {
        exit(&usage, 0);
    }

    let mac: wol::Mac = match matches.opt_str("mac") {
        Some(m) => {
            m.parse()
                .unwrap_or_else(|e| exit(&format!("could not parse mac: {:?}", e), 1))
        }
        None => exit(&usage, 0),
    };

    let bcast: Ipv4Addr = match matches.opt_str("bcast") {
        Some(b) => {
            b.parse()
                .unwrap_or_else(|e| exit(&format!("could not parse ip: {:?}", e), 1))
        }
        None => exit(&usage, 0),
    };

    let magic_packet = wol::build_packet(&mac)
        .unwrap_or_else(|e| exit(&format!("could not build packet: {:?}", e), 1));

    let raddr = SocketAddrV4::new(bcast, 9);

    match wol::send_packet(&magic_packet, &raddr) {
        Ok(_) => println!("packet sent Ok"),
        Err(e) => exit(&format!("could not send request: {:?}", e), 1),
    };
}

