    fn can_get_bytes() {
        // fetch wasm module
        let wasm_path = wasm_path("import.wasm");

        let expected_data = fs::read(&wasm_path).unwrap();

        let wasm_module = read_all_wasm_module(&wasm_path).unwrap();

        assert_eq!(expected_data, wasm_module);
    }
