#[derive(Clone)]
pub struct Prometheus {
    url: Url,
    client: reqwest::Client,
}

pub struct MatrixResponse {
    inner: HashMap<String, TimeSeries>,
}

pub struct TimeSeries {
    inner: Vec<(u64, f64)>,
}

impl Prometheus {
    pub fn new(ip: &str) -> Self {
        let url = format!("http://{}:9091", ip)
            .parse()
            .expect("Failed to parse prometheus url");
        let client = reqwest::Client::new();
        Self { url, client }
    }

    fn query_range(
        &self,
        query: String,
        start: &Duration,
        end: &Duration,
        step: u64,
    ) -> Result<MatrixResponse> {
        let url = self
            .url
            .join(&format!(
                "api/datasources/proxy/1/api/v1/query_range?query={}&start={}&end={}&step={}",
                query,
                start.as_secs(),
                end.as_secs(),
                step
            ))
            .expect("Failed to make query_range url");

        let mut response = self
            .client
            .get(url.clone())
            .send()
            .map_err(|e| format_err!("Failed to query prometheus: {:?}", e))?;

        // We don't check HTTP error code here
        // Prometheus supplies error status in json response along with error text

        let response: PrometheusResponse = response.json().map_err(|e| {
            format_err!("Failed to parse prometheus response: {:?}. Url: {}", e, url)
        })?;

        match response.data {
            Some(data) => MatrixResponse::from_prometheus(data),
            None => bail!(
                "Prometheus query failed: {} {}",
                response.error_type,
                response.error
            ),
        }
    }
    pub fn query_range_avg(
        &self,
        query: String,
        start: &Duration,
        end: &Duration,
        step: u64,
    ) -> Result<f64> {
        let response = self.query_range(query, start, end, step)?;
        response
            .avg()
            .ok_or_else(|| format_err!("Failed to compute avg"))
    }
}

impl MatrixResponse {
    pub fn avg(&self) -> Option<f64> {
        if self.inner.is_empty() {
            return None;
        }
        let mut sum = 0.;
        let mut count = 0usize;
        for time_series in self.inner.values() {
            if let Some(ts_avg) = time_series.avg() {
                sum += ts_avg;
                count += 1;
            }
        }
        if count == 0 {
            None
        } else {
            Some(sum / (count as f64))
        }
    }
}

impl TimeSeries {
    pub fn get(&self) -> &[(u64, f64)] {
        &self.inner
    }

    pub fn avg(&self) -> Option<f64> {
        let mut sum = 0.;
        let mut count = 0usize;
        for (_, v) in self.inner.iter() {
            if !v.is_normal() {
                // Some time series can return NaN (for example, latency query that has division in
                // it). If we include this NaN in sum, it will 'poison' it - if one
                // of values is NaN, sum will be NaN too, and avg will be NaN
                // Instead of poisoning, we simply ignore NaN values when calculating avg
                continue;
            }
            sum += *v;
            count += 1;
        }
        if count == 0 {
            None
        } else {
            Some(sum / (count as f64))
        }
    }
}

#[derive(Debug, Deserialize)]
struct PrometheusResponse {
    data: Option<PrometheusData>,
    #[serde(default)]
    error: String,
    #[serde(alias = "errorType")]
    #[serde(default)]
    error_type: String,
    status: String,
}

#[derive(Debug, Deserialize)]
struct PrometheusData {
    result: Vec<PrometheusResult>,
}

#[derive(Debug, Deserialize)]
struct PrometheusResult {
    metric: PrometheusMetric,
    values: Vec<(u64, String)>,
}

#[derive(Debug, Deserialize)]
struct PrometheusMetric {
    op: Option<String>,
    peer_id: String,
}

impl MatrixResponse {
    fn from_prometheus(data: PrometheusData) -> Result<Self> {
        let mut inner = HashMap::new();
        for entry in data.result {
            let peer_id = entry.metric.peer_id;
            if entry.values.is_empty() {
                continue;
            }
            let time_series = TimeSeries::from_prometheus(entry.values)?;
            inner.insert(peer_id, time_series);
        }
        Ok(Self { inner })
    }
}

impl TimeSeries {
    fn from_prometheus(values: Vec<(u64, String)>) -> Result<Self> {
        let mut inner = vec![];
        for (ts, value) in values {
            let value = value.parse().map_err(|e| {
                format_err!("Failed to parse entry in prometheus time series: {:?}", e)
            })?;
            inner.push((ts, value));
        }
        Ok(TimeSeries { inner })
    }
}

use crate::{util::Nil, Int};
use std::{cmp::Ordering, fmt, hash, ptr};

/// A nonowning collection interface to a buffer of elements stored contiguously
/// in memory.
///
/// See [documentation](https://developer.apple.com/documentation/swift/unsafebufferpointer).
#[repr(C)]
pub struct UnsafeBufferPointer<T> {
    // SAFETY: This is equivalent in memory representation to
    // `UnsafePointer<T>?` in Swift.
    start: *const T,

    count: Int,
}

impl<T> Clone for UnsafeBufferPointer<T> {
    #[inline]
    fn clone(&self) -> Self {
        *self
    }
}

impl<T> Copy for UnsafeBufferPointer<T> {}

impl<T> From<&[T]> for UnsafeBufferPointer<T> {
    #[inline]
    fn from(slice: &[T]) -> Self {
        Self {
            start: slice.as_ptr(),
            count: slice.len() as Int,
        }
    }
}

impl<T> From<&mut [T]> for UnsafeBufferPointer<T> {
    #[inline]
    fn from(slice: &mut [T]) -> Self {
        (slice as &[T]).into()
    }
}

impl<T> fmt::Debug for UnsafeBufferPointer<T> {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        f.debug_struct("UnsafeBufferPointer")
            .field("start", Nil::fmt_debug_ptr(&self.start))
            .field("count", &self.count)
            .finish()
    }
}

impl<T> fmt::Pointer for UnsafeBufferPointer<T> {
    #[inline]
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        self.start.fmt(f)
    }
}

impl<T> PartialEq for UnsafeBufferPointer<T> {
    #[inline]
    fn eq(&self, other: &Self) -> bool {
        self.start == other.start && self.count == other.count
    }
}

impl<T> Eq for UnsafeBufferPointer<T> {}

impl<T> PartialOrd for UnsafeBufferPointer<T> {
    #[inline]
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl<T> Ord for UnsafeBufferPointer<T> {
    #[inline]
    fn cmp(&self, other: &Self) -> Ordering {
        match self.start.cmp(&other.start) {
            Ordering::Equal => self.count.cmp(&other.count),
            ordering => ordering,
        }
    }
}

impl<T> hash::Hash for UnsafeBufferPointer<T> {
    #[inline]
    fn hash<H: hash::Hasher>(&self, state: &mut H) {
        self.start.hash(state);
        self.count.hash(state);
    }
}

impl<T> UnsafeBufferPointer<T> {
    /// Returns the number of elements in the buffer.
    ///
    /// See [documentation](https://developer.apple.com/documentation/swift/unsafebufferpointer/2943791-count).
    #[inline]
    pub fn count(&self) -> Int {
        self.count
    }
}

impl<T> UnsafeBufferPointer<T> {
    /// Returns the number of elements in the buffer as an unsigned integer.
    #[inline]
    pub fn len(&self) -> usize {
        // TODO: Implement `is_empty`.
        #![allow(clippy::len_without_is_empty)]

        self.count as usize
    }

    /// Converts the buffer pointer to a slice pointer.
    #[inline]
    pub fn as_slice_ptr(self) -> *const [T] {
        ptr::slice_from_raw_parts(self.start, self.len())
    }

    // TODO: `as_slice`
}

/// A nonowning collection interface to a buffer of mutable elements stored
/// contiguously in memory.
///
/// See [documentation](https://developer.apple.com/documentation/swift/unsafemutablebufferpointer).
#[repr(C)]
pub struct UnsafeMutableBufferPointer<T> {
    // SAFETY: This is equivalent in memory representation to
    // `UnsafeMutablePointer<T>?` in Swift.
    start: *mut T,

    count: Int,
}

impl<T> Clone for UnsafeMutableBufferPointer<T> {
    #[inline]
    fn clone(&self) -> Self {
        *self
    }
}

impl<T> Copy for UnsafeMutableBufferPointer<T> {}

