impl<T> fmt::Debug for UnsafeMutableBufferPointer<T> {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        f.debug_struct("UnsafeMutableBufferPointer")
            .field("start", Nil::fmt_debug_mut_ptr(&self.start))
