use super::*;

async fn command(fw_ctx: &FwContext, message: &Message, args: &str) -> CommandResult {
    message.reply(fw_ctx, args.to_string()).await?;
    Ok(())
}

fn cmd<'a>(
    fw_ctx: &'a FwContext,
    message: &'a Arc<Message>,
    args: &'a str,
) -> Pin<Box<dyn Future<Output = CommandResult> + Send + 'a>> {
    Box::pin(command(fw_ctx, message, args))
}

fn find_command<'a, 'b>(
    prefix: &str,
    fw: &'a StandardFramework,
    command: &'b str,
) -> Option<(&'a Command, &'b str)> {
    fw.root_group
        .find_command(command.strip_prefix(prefix).unwrap())
}

fn assert_cmd_is(
    prefix: &str,
    fw: &StandardFramework,
    command: &str,
    expected_command_name: &str,
    expected_args: &str,
) {
    let (cmd, args) = find_command(prefix, fw, command).expect("Command not found");

    assert_eq!(cmd.name.as_ref(), expected_command_name);
    assert_eq!(args, expected_args);
}

#[test]
fn test_find_command() {
    let framework = StandardFramework::default()
        .configure(|c| c.prefix("!"))
        .group(|g| {
            g.name("Hello")
                .command(|| Command::new("aaa", cmd as CommandCodeFn))
                .command(|| Command::new("bbbccc", cmd as CommandCodeFn))
                .subgroup(|g| {
                    g.name("bbb")
                        .command(|| Command::new("ccc", cmd as CommandCodeFn).alias("eee"))
                        .command(|| Command::new("ccceee", cmd as CommandCodeFn))
                        .default_command(|| Command::new("ddd", cmd as CommandCodeFn))
                })
        });
    assert_cmd_is("!", &framework, "!aaa", "aaa", "");
    assert_cmd_is("!", &framework, "!bbb ccc", "ccc", "");
    assert_cmd_is("!", &framework, "!bbb", "ddd", "");
    assert_cmd_is("!", &framework, "!bbb ddd", "ddd", "ddd");
    assert_cmd_is("!", &framework, "!bbbccc", "bbbccc", "");
    assert_cmd_is("!", &framework, "!bbbccc ", "bbbccc", "");
    assert_cmd_is("!", &framework, "!bbb eee", "ccc", "");
    assert_cmd_is("!", &framework, "!bbb ccceee", "ccceee", "");
}

//! Type definition within a schema

use super::{field, Field, TypeName, ValueType};
use crate::{
    error::{Error, ErrorKind},
    msg::Tag,
};
use anomaly::{fail, format_err};
use serde::Deserialize;

/// Definition of a particular type in the schema
#[derive(Clone, Debug, Deserialize, Eq, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct Definition {
    /// Name of the type this definition is for
    type_name: TypeName,

    /// Fields in this type definition
    #[serde(deserialize_with = "field::deserialize_vec")]
    fields: Vec<Field>,
}

impl Definition {
    /// Create a new schema [`Definition`] with the given type name and fields
    pub fn new(type_name: TypeName, fields: impl Into<Vec<Field>>) -> Result<Self, Error> {
        let fields = fields.into();

        if let Err(e) = field::validate(&fields) {
            fail!(ErrorKind::Parse, "{}", e);
        }

        Ok(Self { type_name, fields })
    }

    /// Get the [`TypeName`] defined by this schema.
    pub fn type_name(&self) -> &TypeName {
        &self.type_name
    }

    /// Get a list of [`Field`] types in this schema.
    pub fn fields(&self) -> &[Field] {
        self.fields.as_slice()
    }

    /// Get a [`Field`] by its [`TypeName`]
    pub fn get_field(&self, field_name: &TypeName) -> Option<&Field> {
        self.fields.iter().find(|field| field.name() == field_name)
    }

    /// Get the [`Tag`] for a [`Field`], ensuring is of the given [`ValueType`]
    pub fn get_field_tag(
        &self,
        field_name: &TypeName,
        value_type: ValueType,
    ) -> Result<Tag, Error> {
        let field = self.get_field(field_name).ok_or_else(|| {
            format_err!(
                ErrorKind::Type,
                "field name not found in `{}` schema: `{}`",
                &self.type_name,
                field_name
            )
        })?;

        if field.value_type() != value_type {
            fail!(
                ErrorKind::Type,
                "field `{}` of `{}` is not an {} (expected {})",
                field_name,
                &self.type_name,
                value_type,
                field.value_type()
            );
        }

        Ok(field.tag())
    }
}

