/**
 * draws an oscillator
 *
 * KEYS
 * a                 : toggle oscillation animation
 * 1/2               : frequency -/+
 * arrow left/right  : phi -/+
 * s                 : save png
 */
use nannou::prelude::*;

fn main() {
    nannou::app(model).update(update).run();
}

struct Model {
    point_count: usize,
    freq: f32,
    phi: f32,
    angle: f32,
    x: f32,
    y: f32,
    do_draw_animation: bool,
}

fn model(app: &App) -> Model {
    let _window = app
        .new_window()
        .with_dimensions(800, 400)
        .view(view)
        .key_pressed(key_pressed)
        .build()
        .unwrap();

    Model {
        point_count: 20,
        freq: 1.0,
        phi: 0.0,
        angle: 0.0,
        x: 0.0,
        y: 0.0,
        do_draw_animation: true,
    }
}

fn update(app: &App, model: &mut Model, _update: Update) {
    if model.do_draw_animation {
        model.point_count = app.window_rect().w() as usize - 250;
        let t = fmod(app.elapsed_frames() as f32 / model.point_count as f32, 1.0);
        model.angle = map_range(t, 0.0, 1.0, 0.0, TAU);
        model.x = (model.angle * model.freq + deg_to_rad(model.phi)).cos();
        model.x *= 100.0 - 125.0;
        model.y = (model.angle * model.freq + deg_to_rad(model.phi)).sin();
        model.y = model.y * 100.0;
    } else {
        model.point_count = app.window_rect().w() as usize;
    }
}

fn view(app: &App, model: &Model, frame: &Frame) {
    let draw = app.draw();
    let win = app.window_rect();

    draw.background().color(WHITE);

    let x_start = if model.do_draw_animation {
        win.left() + 250.0
    } else {
        win.left()
    };

    let vertices = (0..model.point_count)
        .map(|i| {
            let angle = map_range(i, 0, model.point_count, 0.0, TAU);
            let mut y = (angle * model.freq + deg_to_rad(model.phi)).sin();
            y *= 100.0;
            pt2(x_start + i as f32, y)
        })
        .enumerate()
        .map(|(_i, p)| {
            let rgba = rgba(0.0, 0.0, 0.0, 1.0);
            (p, rgba)
        });

    // Draw the sine wave.
    draw.polyline().weight(2.0).colored_points(vertices);

    if model.do_draw_animation {
        // Circle
        draw.ellipse()
            .x_y(win.left() + 125.0, 0.0)
            .radius(100.0)
            .stroke(rgb(0.0, 0.0, 0.0))
            .no_fill();

        // Lines
        let mut c = rgba(0.0, 0.0, 0.0, 0.5);
        draw.line()
            .start(pt2(x_start, -100.0))
            .end(pt2(x_start, 100.0))
            .color(c);
        draw.line()
            .start(pt2(x_start, 0.0))
            .end(pt2(x_start + model.point_count as f32, 0.0))
            .color(c);
        draw.line()
            .start(pt2(x_start - 225.0, 0.0))
            .end(pt2(x_start - 25.0, 0.0))
            .color(c);
        draw.line()
            .start(pt2(x_start - 125.0, -100.0))
            .end(pt2(x_start - 125.0, 100.0))
            .color(c);
        draw.line()
            .start(pt2(x_start + model.x, model.y))
            .end(pt2(x_start - 125.0, 0.0))
            .color(c);

        let t = fmod(app.elapsed_frames() as f32 / model.point_count as f32, 1.0);

        c = rgba(0.0, 0.5, 0.63, 1.0);
        draw.line()
            .start(pt2(x_start + t * model.point_count as f32, model.y))
            .end(pt2(x_start + t * model.point_count as f32, 0.0))
            .stroke_weight(2.0)
            .color(c);
        draw.line()
            .start(pt2(x_start + model.x, model.y))
            .end(pt2(x_start + model.x, 0.0))
            .stroke_weight(2.0)
            .color(c);

        let phi_x = deg_to_rad(model.phi).cos() * 100.0 - 125.0;
        let phi_y = deg_to_rad(model.phi).sin() * 100.0;

        // phi line
        c = rgba(0.0, 0.0, 0.0, 0.5);
        draw.line()
            .start(pt2(x_start - 125.0, 0.0))
            .end(pt2(x_start + phi_x, phi_y))
            .stroke_weight(1.0)
            .color(c);

        // phi dots
        c = rgba(0.0, 0.0, 0.0, 1.0);
        draw.ellipse()
            .x_y(x_start, phi_y)
            .radius(4.0)
            .color(c)
            .stroke(rgb(1.0, 1.0, 1.0))
            .stroke_weight(2.0);
        draw.ellipse()
            .x_y(x_start + phi_x, phi_y)
            .radius(4.0)
            .color(c)
            .stroke(rgb(1.0, 1.0, 1.0))
            .stroke_weight(2.0);

        // dot on curve
        draw.ellipse()
            .x_y(x_start + t * model.point_count as f32, model.y)
            .radius(5.0)
            .color(c)
            .stroke(rgb(1.0, 1.0, 1.0))
            .stroke_weight(2.0);

        // dot on circle
        draw.ellipse()
            .x_y(x_start + model.x, model.y)
            .radius(5.0)
            .color(c)
            .stroke(rgb(1.0, 1.0, 1.0))
            .stroke_weight(2.0);
    }

    // Write the result of our drawing to the window's frame.
    draw.to_frame(app, &frame).unwrap();
}

fn key_pressed(_app: &App, model: &mut Model, key: Key) {
    match key {
        Key::Key1 => {
            model.freq -= 1.0;
        }
        Key::Key2 => {
            model.freq += 1.0;
        }
        Key::A => {
            model.do_draw_animation = !model.do_draw_animation;
        }
        Key::Left => {
            model.phi -= 15.0;
        }
        Key::Right => {
            model.phi += 15.0;
        }
        _other_key => {}
    }
    model.freq = model.freq.max(1.0);
}

use rafx::render_feature_prepare_job_predule::*;

use super::*;
use crate::phases::WireframeRenderPhase;
use rafx::api::{RafxBufferDef, RafxDeviceContext, RafxMemoryUsage, RafxResourceType};
use rafx::framework::ResourceContext;

pub struct Debug3DPrepareJob {
    resource_context: ResourceContext,
    device_context: RafxDeviceContext,
}

impl Debug3DPrepareJob {
    pub fn new<'prepare>(
        prepare_context: &RenderJobPrepareContext<'prepare>,
        frame_packet: Box<Debug3DFramePacket>,
        submit_packet: Box<Debug3DSubmitPacket>,
    ) -> Arc<dyn RenderFeaturePrepareJob<'prepare> + 'prepare> {
        Arc::new(PrepareJob::new(
            Self {
                resource_context: prepare_context.resource_context.clone(),
                device_context: prepare_context.device_context.clone(),
            },
            frame_packet,
            submit_packet,
        ))
    }
}

impl<'prepare> PrepareJobEntryPoints<'prepare> for Debug3DPrepareJob {
    fn begin_per_frame_prepare(
        &self,
        context: &PreparePerFrameContext<'prepare, '_, Self>,
    ) {
        let mut per_frame_submit_data = Debug3DPerFrameSubmitData::default();

        //
        // Gather the raw draw data
        //
        let line_lists = &context.per_frame_data().line_lists;
        for line_list in line_lists.iter() {
            let vertex_buffer_first_element = per_frame_submit_data.vertex_list.len() as u32;

            for vertex_pos in &line_list.points {
                per_frame_submit_data.vertex_list.push(Debug3DVertex {
                    pos: (*vertex_pos).into(),
                    color: line_list.color.into(),
                });
            }

            per_frame_submit_data.draw_calls.push(Debug3DDrawCall {
                first_element: vertex_buffer_first_element,
                count: line_list.points.len() as u32,
            });
        }

        // We would probably want to support multiple buffers at some point

        let dyn_resource_allocator_set = self.resource_context.create_dyn_resource_allocator_set();
        per_frame_submit_data.vertex_buffer = if !per_frame_submit_data.draw_calls.is_empty() {
            let vertex_buffer_size = per_frame_submit_data.vertex_list.len() as u64
                * std::mem::size_of::<Debug3DVertex>() as u64;

            let vertex_buffer = self
                .device_context
                .create_buffer(&RafxBufferDef {
                    size: vertex_buffer_size,
                    memory_usage: RafxMemoryUsage::CpuToGpu,
                    resource_type: RafxResourceType::VERTEX_BUFFER,
                    ..Default::default()
                })
                .unwrap();

            vertex_buffer
                .copy_to_host_visible_buffer(per_frame_submit_data.vertex_list.as_slice())
                .unwrap();

            Some(dyn_resource_allocator_set.insert_buffer(vertex_buffer))
        } else {
            None
        };

        context
            .submit_packet()
            .per_frame_submit_data()
            .set(per_frame_submit_data);
    }

    fn end_per_view_prepare(
        &self,
        context: &PreparePerViewContext<'prepare, '_, Self>,
    ) {
        let per_frame_data = context.per_frame_data();
        if per_frame_data.debug3d_material_pass.is_none() {
            return;
        }

        let debug3d_material_pass = per_frame_data.debug3d_material_pass.as_ref().unwrap();
        let per_view_descriptor_set_layout = &debug3d_material_pass
            .get_raw()
            .descriptor_set_layouts[shaders::debug_vert::PER_FRAME_DATA_DESCRIPTOR_SET_INDEX];

        let view = context.view();
        let debug3d_view = Debug3DUniformBufferObject {
            view_proj: (view.projection_matrix() * view.view_matrix()).to_cols_array_2d(),
        };

        let mut descriptor_set_allocator = self.resource_context.create_descriptor_set_allocator();
        context
            .view_submit_packet()
            .per_view_submit_data()
            .set(Debug3DPerViewSubmitData {
                descriptor_set_arc: descriptor_set_allocator
                    .create_descriptor_set_with_writer(
                        per_view_descriptor_set_layout,
                        shaders::debug_vert::DescriptorSet0Args {
                            per_frame_data: &debug3d_view,
                        },
                    )
                    .ok(),
            });

        context
            .view_submit_packet()
            .push_submit_node::<WireframeRenderPhase>((), 0, 0.);
    }

    fn feature_debug_constants(&self) -> &'static RenderFeatureDebugConstants {
        super::render_feature_debug_constants()
    }

    fn feature_index(&self) -> RenderFeatureIndex {
        super::render_feature_index()
    }

    type RenderObjectInstanceJobContextT = DefaultJobContext;
    type RenderObjectInstancePerViewJobContextT = DefaultJobContext;

    type FramePacketDataT = Debug3DRenderFeatureTypes;
    type SubmitPacketDataT = Debug3DRenderFeatureTypes;
}

