    fn from(t: SystemTime) -> Self {
        Seconds::from(t.duration_since(SystemTime::UNIX_EPOCH).unwrap())
    }
}

use crate::model::{PropertyType, EntityType, DataType};
use std::sync::Arc;
use crate::api::EntityTypeManager;

#[allow(dead_code)]
pub struct EntityTypeBuilder {
    type_name: String,
    components: Vec<String>,
    behaviours: Vec<String>,
    properties: Vec<PropertyType>
}

#[allow(dead_code)]
impl EntityTypeBuilder {
    pub fn new<S: Into<String>>(type_name: S) -> EntityTypeBuilder {
        EntityTypeBuilder {
            type_name: type_name.into(),
            components: Vec::new(),
            behaviours: Vec::new(),
            properties: Vec::new(),
        }
    }

    pub fn component<'a, S: Into<String>>(&'a mut self, component_name: S) -> &'a mut EntityTypeBuilder {
        self.components.push(component_name.into());
        self
    }

    pub fn behaviour<'a, S: Into<String>>(&'a mut self, behaviour_name: S) -> &'a mut EntityTypeBuilder {
        self.behaviours.push(behaviour_name.into());
        self
    }

    pub fn property<'a, S: Into<String>>(&'a mut self, property_name: S, data_type: DataType) -> &'a mut EntityTypeBuilder {
        self.properties.push(PropertyType::new(property_name.into(), data_type));
        self
    }

    pub fn string_property<'a, S: Into<String>>(&'a mut self, property_name: S) -> &'a mut EntityTypeBuilder {
        self.properties.push(PropertyType::new(property_name.into(), DataType::String));
        self
    }

    pub fn bool_property<'a, S: Into<String>>(&'a mut self, property_name: S) -> &'a mut EntityTypeBuilder {
        self.properties.push(PropertyType::new(property_name.into(), DataType::Bool));
        self
    }

    pub fn number_property<'a, S: Into<String>>(&'a mut self, property_name: S) -> &'a mut EntityTypeBuilder {
        self.properties.push(PropertyType::new(property_name.into(), DataType::Number));
        self
    }

    pub fn build<'a>(&'a mut self) -> EntityType {
        EntityType::new(
            self.type_name.clone(),
            self.components.to_vec(),
            self.behaviours.to_vec(),
            self.properties.to_vec()
        )
    }

    pub fn register<'a>(&'a mut self, entity_type_manager: Arc<dyn EntityTypeManager>) -> EntityType {
        let entity_type = self.build();
        entity_type_manager.register(entity_type.clone());
        entity_type
    }

}

/*!
`crypto_secretbox_xsalsa20poly1305`, a particular
combination of Salsa20 and Poly1305 specified in
[Cryptography in NaCl](http://nacl.cr.yp.to/valid.html).

This function is conjectured to meet the standard notions of privacy and
authenticity.
*/
use libc::{c_ulonglong, c_int};
use std::intrinsics::volatile_set_memory;
use utils::marshal;
use randombytes::randombytes_into;

#[link(name = "sodium")]
extern {
    fn crypto_secretbox_xsalsa20poly1305(c: *mut u8,
                                         m: *const u8,
                                         mlen: c_ulonglong,
                                         n: *const u8,
                                         k: *const u8) -> c_int;
    fn crypto_secretbox_xsalsa20poly1305_open(m: *mut u8,
                                              c: *const u8,
                                              clen: c_ulonglong,
                                              n: *const u8,
                                              k: *const u8) -> c_int;
}

pub const KEYBYTES: uint = 32;
pub const NONCEBYTES: uint = 24;

/**
 * `Key` for symmetric authenticated encryption
 *
 * When a `Key` goes out of scope its contents
 * will be zeroed out
 */
pub struct Key(pub [u8, ..KEYBYTES]);

newtype_drop!(Key)
newtype_clone!(Key)

/**
 * `Nonce` for symmetric authenticated encryption
 */
pub struct Nonce(pub [u8, ..NONCEBYTES]);

newtype_clone!(Nonce)

const ZEROBYTES: uint = 32;
const BOXZEROBYTES: uint = 16;

/**
 * `gen_key()` randomly generates a secret key
 *
 * THREAD SAFETY: `gen_key()` is thread-safe provided that you have
 * called `sodiumoxide::init()` once before using any other function
 * from sodiumoxide.
 */
pub fn gen_key() -> Key {
    let mut key = [0, ..KEYBYTES];
    randombytes_into(&mut key);
    Key(key)
}

/**
 * `gen_nonce()` randomly generates a nonce
 *
 * THREAD SAFETY: `gen_key()` is thread-safe provided that you have
 * called `sodiumoxide::init()` once before using any other function
 * from sodiumoxide.
 */
pub fn gen_nonce() -> Nonce {
    let mut nonce = [0, ..NONCEBYTES];
    randombytes_into(&mut nonce);
    Nonce(nonce)
}

/**
 * `seal()` encrypts and authenticates a message `m` using a secret key `k` and a
 * nonce `n`.  It returns a ciphertext `c`.
 */
pub fn seal(m: &[u8],
            &Nonce(n): &Nonce,
            &Key(k): &Key) -> Vec<u8> {
    let (c, _) = marshal(m, ZEROBYTES, BOXZEROBYTES, |dst, src, len| {
        unsafe {
            crypto_secretbox_xsalsa20poly1305(dst, src, len, n.as_ptr(), k.as_ptr())
        }
    });
    c
}

/**
 * `open()` verifies and decrypts a ciphertext `c` using a secret key `k` and a nonce `n`.
 * It returns a plaintext `Some(m)`.
 * If the ciphertext fails verification, `open()` returns `None`.
 */
pub fn open(c: &[u8],
            &Nonce(n): &Nonce,
            &Key(k): &Key) -> Option<Vec<u8>> {
    if c.len() < BOXZEROBYTES {
        return None
    }
    let (m, ret) = marshal(c, BOXZEROBYTES, ZEROBYTES, |dst, src, len| {
        unsafe {
            crypto_secretbox_xsalsa20poly1305_open(dst,
                                                   src,
                                                   len,
                                                   n.as_ptr(),
                                                   k.as_ptr())
        }
    });
    if ret == 0 {
        Some(m)
    } else {
        None
    }
}

#[test]
fn test_seal_open() {
    use randombytes::randombytes;
    for i in range(0, 256u) {
        let k = gen_key();
        let m = randombytes(i);
        let n = gen_nonce();
        let c = seal(m.as_slice(), &n, &k);
        let opened = open(c.as_slice(), &n, &k);
        assert!(Some(m) == opened);
    }
}

#[test]
fn test_seal_open_tamper() {
    use randombytes::randombytes;
    for i in range(0, 32u) {
        let k = gen_key();
        let m = randombytes(i);
        let n = gen_nonce();
        let mut cv = seal(m.as_slice(), &n, &k);
        let c = cv.as_mut_slice();
        for i in range(0, c.len()) {
            c[i] ^= 0x20;
            assert!(None == open(c, &n, &k));
            c[i] ^= 0x20;
        }
    }
}

