#[derive(Clone)]
pub struct StructField {
    pub field: Field,
    pub default: bool,
}
impl StructField {
    pub fn eq(&self, name: &Ident) -> bool {
        self.field.ident.clone().unwrap().to_string() == name.to_string()
    }
    pub fn ty(&self) -> Type {
        self.field.ty.clone()
    }

    pub fn new(field: Field, default: bool) -> Self {
        Self {
            field: field,
            default: default,
        }
    }

    pub fn constraint_tokens(self) -> Option<TokenStream> {
        if !self.default {
            let dependency = self.field.ty;
            Some(quote! { curds_core_abstraction::dependency_injection::ServiceGenerator<#dependency> })
        }
        else {
            None
        }
    }

    pub fn generator_tokens(self) -> Option<TokenStream> {
        if !self.default {
            let dependency = self.field.ty;
            Some(quote! { curds_core_abstraction::dependency_injection::ServiceGenerator::<#dependency>::generate(provider) })
        }
        else {
            None
        }
    }

    pub fn argument_tokens(self) -> Option<TokenStream> {
        if !self.default {
            let name = self.field.ident.unwrap();
            let ty = self.field.ty;

            Some(quote! { #name: #ty })
        }
        else {
            None
        }
    }

    pub fn initializer_tokens(self) -> TokenStream {
        let name = self.field.ident.unwrap();
        if self.default {
            quote! { #name: std::default::Default::default() }
        }
        else {
            quote! { #name: #name }
        }
    }

    pub fn scope_tokens(self) -> TokenStream {
        let name = self.field.ident.unwrap();
        if self.default {
            quote! { #name: std::default::Default::default() }
        }
        else {
            quote! { #name: self.#name.clone() }
        }
    }
}

impl ToTokens for StructField {
    fn to_tokens(&self, tokens: &mut TokenStream) {
        self.field.to_tokens(tokens)
    }
}

use std::collections::HashMap;
use std::io::Read;

#[derive(Debug)]
struct Cave {
    connected: Vec<usize>,
    large: bool,
}

fn count_paths(
    caves: &Vec<Cave>,
    visited: &mut Vec<u8>,
    multi_visited: bool,
    pos: usize,
    start: usize,
    end: usize,
) -> u32 {
    let cave = &caves[pos];
    let second_visit = visited[pos] >= 1 && !cave.large;

    if pos == end {
        1
    } else if second_visit && (multi_visited || pos == start) {
        0
    } else {
        let multi_visited = multi_visited || second_visit;
        visited[pos] += 1;
        let paths = cave.connected.iter().map(|&new_pos| {
            count_paths(caves, visited, multi_visited, new_pos, start, end)
        }).sum();
        visited[pos] -= 1;
        paths
    }
}

fn main() {
    let mut input = String::new();
    std::io::stdin().read_to_string(&mut input).unwrap();

    let mut cave_indexes = HashMap::new();
    let mut caves = Vec::new();

    for line in input.lines() {
        let words: Vec<_> = line.split('-').collect();
        for &word in &words {
            if !cave_indexes.contains_key(word) {
                cave_indexes.insert(word, caves.len());

                caves.push(Cave {
                    connected: Vec::new(),
                    large: word.chars().next().unwrap().is_ascii_uppercase(),
                });
            }
        }

        let a = cave_indexes[words[0]];
        let b = cave_indexes[words[1]];
        caves[a].connected.push(b);
        caves[b].connected.push(a);
    }

    let start = cave_indexes["start"];
    let end = cave_indexes["end"];

    println!("{}", count_paths(&caves, &mut vec![0; caves.len()], false, start, start, end));
}

