/// Represents a non-leaf node in the B-tree sample structure
#[derive(Debug)]
pub struct Trunk<S> {
    checkpoints: Checkpoints<S>,
    children: Children<S>,
}

impl<S: Ord> Node<S> for Trunk<S> {
    fn record_sample(
        &mut self,
        sample: S,
        maximal_gap: u64,
        following: &mut Checkpoint<S>,
    ) -> RecordResult<S, Self> {
        match &mut self.children {
            Children::Leafs(leafs) => Trunk::generic_record_sample(
                &mut self.checkpoints,
                leafs,
                sample,
                maximal_gap,
                following,
            ),
            Children::Trunks(trunks) => Trunk::generic_record_sample(
                &mut self.checkpoints,
                trunks,
                sample,
                maximal_gap,
                following,
            ),
        }
    }

    fn insert_max_checkpoint(&mut self, checkpoint: Checkpoint<S>) -> InsertResult<S, Self> {
        match &mut self.children {
            Children::Leafs(leafs) => {
                Trunk::generic_insert_max_checkpoint(&mut self.checkpoints, leafs, checkpoint)
            }
            Children::Trunks(trunks) => {
                Trunk::generic_insert_max_checkpoint(&mut self.checkpoints, trunks, checkpoint)
            }
        }
    }

    fn nodes_to_children(nodes: Nodes<Self>) -> Children<S> {
        Children::Trunks(nodes)
    }

    fn take_from_root(root: &mut Root<S>) -> Self {
        match Root::take_from_root(root) {
            Root::Trunk(trunk) => trunk,
            _ => unreachable!("Invalid root node state"),
        }
    }
}

impl<S: Ord> Trunk<S> {
    fn generic_record_sample<N: Node<S>>(
        checkpoints: &mut Checkpoints<S>,
        nodes: &mut Nodes<N>,
        sample: S,
        maximal_gap: u64,
        following: &mut Checkpoint<S>,
    ) -> RecordResult<S, Self> {
        let (pos, following) = checkpoints.find_insertion_pos(&sample, following);

        use InsertResult::*;
        use RecordResult::*;

        let node = &mut nodes[pos];
        match node.record_sample(sample, maximal_gap, following) {
            // Explicit pass-through to convert `RecordResult<S, N>` into `RecordResult<S, Self>`
            Inserted(Done) => Inserted(Done),
            UpdatedInPlace => UpdatedInPlace,
            Inserted(Pending(med_checkpoint, right_node)) => {
                Inserted(Self::generic_insert_checkpoint(
                    checkpoints,
                    nodes,
                    med_checkpoint,
                    Box::new(right_node),
                    pos,
                ))
            }
        }
    }

    fn generic_insert_max_checkpoint<N: Node<S>>(
        checkpoints: &mut Checkpoints<S>,
        nodes: &mut Nodes<N>,
        checkpoint: Checkpoint<S>,
    ) -> InsertResult<S, Self> {
        use InsertResult::*;

        let last = nodes.last_mut().expect("nodes is not empty");
        match last.insert_max_checkpoint(checkpoint) {
            // Explicit pass-through to convert `InsertResult<S, N>` into `InsertResult<S, Self>`
            Done => Done,
            Pending(med_checkpoint, right_node) => Self::generic_insert_checkpoint(
                checkpoints,
                nodes,
                med_checkpoint,
                Box::new(right_node),
                checkpoints.len(),
            ),
        }
    }
}

impl<S> Trunk<S> {
    pub fn with_median<N: Node<S>>(
        left_node: Box<N>,
        med_checkpoint: Checkpoint<S>,
        right_node: Box<N>,
    ) -> Self {
        let mut nodes: Nodes<N> = ArrayVec::new();
        nodes.push(left_node);
        nodes.push(right_node);

        let mut checkpoints = Checkpoints::new();
        checkpoints.push(med_checkpoint);

        Self::with_children(checkpoints, nodes)
    }

    fn with_children<N: Node<S>>(checkpoints: Checkpoints<S>, nodes: Nodes<N>) -> Self {
        debug_assert_eq!(checkpoints.len() + 1, nodes.len());
        let children = N::nodes_to_children(nodes);
        Trunk {
            checkpoints,
            children,
        }
    }

    /// Insert a new checkpoint into this node. If the node is full, it will be split it into
    /// (left, median, right). Self will become left and the other two values will be returned.
    fn generic_insert_checkpoint<N: Node<S>>(
        checkpoints: &mut Checkpoints<S>,
        nodes: &mut Nodes<N>,
        med_checkpoint: Checkpoint<S>,
        right_node: Box<N>,
        pos: usize,
    ) -> InsertResult<S, Self> {
        use InsertResult::*;

        match checkpoints.insert_checkpoint(med_checkpoint, pos) {
            Done => {
                nodes.insert(pos + 1, right_node);
                Done
            }
            Pending(new_med_checkpoint, right_checkpoints) => {
                let med_pos = nodes.len() / 2;
                let mut right_children: Nodes<N>;
                if pos < med_pos {
                    right_children = nodes.drain(med_pos..).collect();
                    nodes.insert(pos + 1, right_node);
                } else {
                    right_children = nodes.drain(med_pos + 1..).collect();
                    right_children.insert(pos - med_pos, right_node);
                }

                Pending(
                    new_med_checkpoint,
                    Self::with_children(right_checkpoints, right_children),
                )
            }
        }
    }

    #[cfg(test)]
    pub fn depth(&self) -> usize {
        match &self.children {
            Children::Leafs(_) => 2,
            Children::Trunks(trunks) => 1 + trunks[0].depth(),
        }
    }
}

use syn::Fields;

use crate::config::*;

pub fn derive_struct_impl(
    name: syn::Ident,
    mut generics: syn::Generics,
    container: syn::DataStruct,
    config: &Config,
) -> proc_macro2::TokenStream {
    let mut list = vec![];
    let crate_root = &config.crate_root;

    for param in generics.type_params_mut() {
        param.colon_token = Some(Default::default());
        param.bounds = {
            let mut punct = syn::punctuated::Punctuated::new();
            punct.push(
                syn::TraitBound {
                    paren_token: None,
                    modifier: syn::TraitBoundModifier::None,
                    lifetimes: None,
                    path: {
                        let mut path = crate_root.clone();
                        path.segments.push(syn::PathSegment {
                            ident: quote::format_ident!("Decode"),
                            arguments: syn::PathArguments::None,
                        });

                        path
                    },
                }
                .into(),
            );

            punct
        };
    }

    let (impl_generics, ty_generics, where_clause) = generics.split_for_impl();

    let decode_impl = if config.delegate {
        let ty = &container.fields.iter().next().unwrap().ty;
        quote! {
            <#ty as #crate_root::Decode>::decode_with_tag(decoder, tag).map(Self)
        }
    } else if config.set {
        let field_names = container.fields.iter().map(|field| field.ident.clone());
        let field_names2 = field_names.clone();
        let field_names3 = field_names.clone();
        let required_field_names = container
            .fields
            .iter()
            .filter(|field| !FieldConfig::new(field, config).is_option_type())
            .map(|field| field.ident.clone());
        let (field_type_names, field_type_defs): (Vec<_>, Vec<_>) = container
            .fields
            .iter()
            .enumerate()
            .map(|(i, field)| {
                let ty = config
                    .option_type
                    .map_to_inner_type(&field.ty)
                    .unwrap_or(&field.ty);
                let tag = FieldConfig::new(field, config).tag(i);
                let name = quote::format_ident!("Field{}", i);

                (
                    name.clone(),
                    quote! {
                        #[derive(#crate_root::Decode, #crate_root::Encode)]
                        #[rasn(delegate)]
                        pub struct #name(#ty);

                        impl #crate_root::AsnType for #name {
                            const TAG: Tag = #tag;
                        }
                    },
                )
            })
            .unzip();

        let choice_name = quote::format_ident!("{}Fields", name);

        let choice_def = quote! {
            #[derive(#crate_root::AsnType, #crate_root::Decode, #crate_root::Encode)]
            #[rasn(choice)]
            enum #choice_name {
                #(#field_type_names(#field_type_names)),*
            }
        };

        let set_init = match container.fields {
            syn::Fields::Unit => quote!(),
            syn::Fields::Unnamed(_) => quote!(( #(#field_names3),* )),
            syn::Fields::Named(_) => quote!({ #(#field_names3),* }),
        };

        quote! {
            #choice_def
            #(#field_type_defs)*

            decoder.decode_set::<#choice_name, _, _>(tag, |fields| {
                #(let mut #field_names = None;)*

                for field in fields {
                    match field {
                        #(#choice_name::#field_type_names(value) => {
                            if #field_names2.replace(value.0).is_some() {
                                return Err(rasn::de::Error::duplicate_field(stringify!(#field_names2)))
                            }
                        })*
                    }
                }

                #(let #required_field_names = #required_field_names.ok_or_else(|| #crate_root::de::Error::missing_field("#required_field_names"))?;)*

                Ok(Self #set_init)
            })
        }
    } else {
        for (i, field) in container.fields.iter().enumerate() {
            let field_config = FieldConfig::new(field, config);

            list.push(field_config.decode(&name, i));
        }

        let fields = match container.fields {
            Fields::Named(_) => quote!({ #(#list),* }),
            Fields::Unnamed(_) => quote!(( #(#list),* )),
            Fields::Unit => quote!(),
        };

        quote! {
            decoder.decode_sequence(tag, |decoder| {
                Ok(Self #fields)
            })
        }
    };

    quote! {
        impl #impl_generics #crate_root::Decode for #name #ty_generics #where_clause {
            fn decode_with_tag<D: #crate_root::Decoder>(decoder: &mut D, tag: #crate_root::Tag) -> Result<Self, D::Error> {
                #decode_impl
            }
        }
    }
}

pub fn derive_enum_impl(
    name: syn::Ident,
    mut generics: syn::Generics,
    container: syn::DataEnum,
    config: &Config,
) -> proc_macro2::TokenStream {
    let crate_root = &config.crate_root;
    let decode_with_tag = if config.enumerated {
        let variants = container.variants.iter().map(|v| {
            let ident = &v.ident;
            quote!(i if i == (#name::#ident as isize).into() => #name::#ident,)
        });

        quote! {
            let integer = decoder.decode_enumerated(tag)?;

            Ok(match integer {
                #(#variants)*
                _ => return Err(#crate_root::de::Error::custom("Invalid enumerated disrciminant."))
            })

        }
    } else {
        quote! {
            decoder.decode_explicit_prefix(tag)
        }
    };

    let decode = if config.choice {
        let variants = container
            .variants
            .iter()
            .enumerate()
            .map(|(i, v)| VariantConfig::new(v, config).decode(&name, i));

        let name = syn::LitStr::new(&name.to_string(), proc_macro2::Span::call_site());
        Some(quote! {
            fn decode<D: #crate_root::Decoder>(decoder: &mut D) -> Result<Self, D::Error> {
                #(#variants);*
                Err(#crate_root::de::Error::no_valid_choice(#name))
            }
        })
    } else {
        None
    };

    let crate_root = &config.crate_root;

    for param in generics.type_params_mut() {
        param.colon_token = Some(Default::default());
        param.bounds = {
            let mut punct = syn::punctuated::Punctuated::new();
            punct.push(
                syn::TraitBound {
                    paren_token: None,
                    modifier: syn::TraitBoundModifier::None,
                    lifetimes: None,
                    path: {
                        let mut path = crate_root.clone();
                        path.segments.push(syn::PathSegment {
                            ident: quote::format_ident!("Decode"),
                            arguments: syn::PathArguments::None,
                        });

                        path
                    },
                }
                .into(),
            );

            punct
        };
    }

    let (impl_generics, ty_generics, where_clause) = generics.split_for_impl();

    quote! {
        impl #impl_generics #crate_root::Decode for #name #ty_generics #where_clause {
            fn decode_with_tag<D: #crate_root::Decoder>(decoder: &mut D, tag: #crate_root::Tag) -> Result<Self, D::Error> {
                #decode_with_tag
            }

            #decode
        }
    }
}

