use crate::error::ServerError;
use entities::{Account, DbVersion, Operation};
use r2d2_sqlite::SqliteConnectionManager;
use rusqlite::{params, NO_PARAMS};
use std::fs;
use std::fs::DirEntry;
use std::path::Path;

pub type Pool = r2d2::Pool<SqliteConnectionManager>;

#[derive(Clone)]
pub struct Database {
    pool: Pool,
}

impl Database {
    pub fn new<P: AsRef<Path>>(path: P) -> Self {
        let manager = SqliteConnectionManager::file(path);
        let pool = Pool::new(manager).unwrap();

        Database { pool }
    }

    pub fn insert_operation(&self, operation: &Operation) -> Result<(), ServerError> {
        let conn = self.pool.get()?;
        let mut stmt = conn.prepare("INSERT INTO OPERATION(FROM_ACCOUNT, TO_ACCOUNT, COMMENT, AMOUNT, DATETIME) VALUES (?, ?, ?, ?, ?);")?;
        let rows_updated = stmt.execute(params![
            operation.from,
            operation.to,
            operation.comment,
            operation.amount,
            operation.datetime
        ])?;

        if rows_updated != 1 {
            return Err(ServerError::DBError(
                "Wrong number of lines inserted.".to_owned(),
            ));
        }

        Ok(())
    }

    pub fn update_balance(&self, account_name: &str, delta: i64) -> Result<(), ServerError> {
        let conn = self.pool.get()?;
        let mut stmt = conn.prepare("UPDATE ACCOUNT SET BALANCE = BALANCE + ? WHERE NAME = ?;")?;
        let rows_updated = stmt.execute(params![delta, account_name])?;

        if rows_updated != 1 {
            return Err(ServerError::DBError(
                "Wrong number of lines updated.".to_owned(),
            ));
        }

        Ok(())
    }

    pub fn get_secret(&self) -> Result<String, ServerError> {
        let conn = self.pool.get()?;
        let mut stmt = conn.prepare("SELECT TOKEN FROM SECRET LIMIT 1")?;
        let secret = stmt.query_row(NO_PARAMS, |row| Ok(row.get(0)?))?;

        Ok(secret)
    }

    pub fn get_accounts(&self) -> Result<Vec<Account>, ServerError> {
        let conn = self.pool.get()?;
        let mut stmt = conn.prepare("SELECT NAME, BALANCE FROM ACCOUNT")?;
        let accounts = stmt
            .query_map(NO_PARAMS, |row| {
                Ok(Account {
                    name: row.get(0)?,
                    balance: row.get(1)?,
                })
            })
            .and_then(Iterator::collect)?;

        Ok(accounts)
    }

    pub fn add_account(&self, account: &Account) -> Result<(), ServerError> {
        let conn = self.pool.get()?;
        let mut stmt = conn.prepare("INSERT INTO ACCOUNT (NAME, BALANCE) VALUES (?, ?)")?;
        let rows_updated = stmt.execute(params![account.name, account.balance])?;

        if rows_updated != 1 {
            Err(ServerError::DBError(
                "Wrong number of lines inserted.".to_owned(),
            ))
        } else {
            Ok(())
        }
    }

    pub fn current_db_version(&self) -> Result<DbVersion, ServerError> {
        let conn = self.pool.get()?;
        let mut stmt =
            conn.prepare("SELECT VERSION, DEPLOY_AT FROM DB_VERSION ORDER BY VERSION DESC")?;
        let db_version = stmt.query_row(NO_PARAMS, |row| {
            Ok(DbVersion {
                version: row.get(0)?,
                deploy_at: row.get(1)?,
            })
        })?;

        Ok(db_version)
    }

    pub fn execute(&self, sql: &str) -> Result<(), ServerError> {
        let conn = self.pool.get()?;
        conn.execute_batch(sql)?;

        Ok(())
    }

    pub fn migrate<P: AsRef<Path>>(&self, path: P) -> Result<(), ServerError> {
        let mut migrations: Vec<DirEntry> = fs::read_dir(path)?.map(|dir| dir.unwrap()).collect();

        migrations.sort_by_key(|dir| dir.file_name());

        let current_version = match self.current_db_version() {
            Ok(version) => Some(version),
            Err(_) => {
                info!("No database version found. Initializing...");
                None
            }
        };

        for migration in migrations {
            let file_string = migration.file_name().into_string()?;
            let file_name = file_string.split('.').next();
            if match (file_name, &current_version) {
                (Some(file_name), Some(version)) => file_name > &version.version[..],
                (Some(_), None) => true,
                (None, _) => false,
            } {
                info!("Applying database migration {:?}.", migration.file_name());
                let sql = fs::read_to_string(migration.path())?;
                self.execute(&sql)?;
            }
        }

        info!("The database is now the latest version.");

        Ok(())
    }
}

use std::time::Duration;

use async_trait::async_trait;
use image::{AnimationDecoder, Frame};
use log::{debug, info};
use serde::Deserialize;

use crate::{Part, PartCache, PartChannel, RenderError, widgets::message::GifMessage};

#[derive(Clone, Debug, Deserialize)]
pub struct GifWidget {
    // TODO:
    pub url: String,
}

impl GifWidget {
    async fn load_gif(&self, url: &str) -> Result<Vec<Frame>, RenderError> {
        info!("GifWidget - Loading GIF from '{}'...", self.url);
        let bytes = reqwest::Client::default()
            .get(url)
            .send()
            .await?
            .bytes()
            .await?;

        let frames = image::codecs::gif::GifDecoder::new(bytes.as_ref())?
            .into_frames()
            .collect_frames()?;
        debug!("GifWidget - Frame count: {}", frames.len());

        Ok(frames)
    }
}

#[async_trait]
impl Part for GifWidget {
    async fn start(
        &mut self,
        cache: PartCache,
        id: usize,
        mut channel: PartChannel,
    ) -> Result<(), crate::RenderError> {
        info!("GifWidget({}) started.", id);
        let mut frames = self.load_gif(&self.url).await.unwrap_or_default();
        let mut i = 0;
        loop {
            if !frames.is_empty() {
                let img = frames[i].buffer().clone();

                if let Ok(mut write_guard) = cache.write() {
                    (*write_guard).image = Some(img);
                }
            }

            let d = if frames.is_empty() {
                Duration::from_secs(86400)
            } else {
                let (numer, denom) = frames[i].delay().numer_denom_ms();
                let delay = ((numer as f64 * 1000f64) / (denom as f64)) as u64;
                Duration::from_micros(delay)
            };
            if let Some(msg) = self.try_read::<GifMessage>(&mut channel, d).await {
                debug!("Gif widget {} got message '{:#?}'", id, msg);
                if let Ok(f) = self.load_gif(&msg.url).await {
                    frames = f;
                    i = 0;
                }
            }

            i = if frames.is_empty() {
                0
            } else {
                (i + 1) % frames.len()
            }
        }
    }
}

use crate::pyndarray::NdArrayD;
use facet_core::ndarray::{Data, NdArray};
use pyo3::{exceptions::PyValueError, prelude::*, types::PyDict, wrap_pyfunction};

use std::{
    collections::HashMap,
    io::{BufRead, BufReader},
};

/// The column names in `labels` will be treated as row labels instead of data points.
///
/// Column names in `ignore` will be ignored.
///
/// Returns a dict with the loaded data.
///
/// Data and labels are loaded separately, but corresponding rows maintain their indices.
///
/// ```python
/// # obtain the label, row pairs after loading the dataset
/// for label, row in zip(dataset["labels"], dataset["data"].iter_cols()):
///     print(label, row)
/// ```
#[pyfunction(labels = "[].to_vec()", ignore = "[].to_vec()", ignore_error = "false")]
pub fn load_csv<'a, 'py>(
    py: Python<'py>,
    fname: &'a str,
    labels: Vec<&'a str>,
    ignore: Vec<&'a str>,
    ignore_error: bool,
) -> PyResult<&'py PyDict> {
    let mut column_indices: HashMap<String, usize> = HashMap::new();
    let mut label_columns = Vec::with_capacity(1);
    let mut ignored_columns = Vec::new();
    let mut columns: Vec<String> = Vec::new();
    let mut data = Data::new();

    let f = std::fs::OpenOptions::new()
        .read(true)
        .create(false)
        .open(fname)
        .map_err(|err| {
            PyValueError::new_err(format!(
                "Failed to open file [{}] for reading  {:?}",
                fname, err
            ))
        })?;

    let mut lines = BufReader::new(f).lines();

    // TODO: allow no header
    match lines.next() {
        Some(Ok(head)) => {
            for (i, item) in head.split(',').enumerate() {
                columns.push(item.to_string());
                column_indices.insert(item.to_string(), i);
                if labels.iter().any(|l| *l == item) {
                    label_columns.push(i);
                }
                if ignore.iter().any(|l| *l == item) {
                    ignored_columns.push(i);
                }
            }
        }
        _ => {
            todo!("no data read")
        }
    }

    let mut labels = Vec::new();
    let mut rows = 0;
    while let Some(Ok(line)) = lines.next() {
        rows += 1;
        let mut skipit = label_columns.iter();
        let mut skipind = skipit.next();
        let mut ignoreit = ignored_columns.iter();
        let mut ignoreind = ignoreit.next();
        let mut rowlabels = Vec::new();
        for (i, item) in line.split(',').enumerate() {
            if Some(&i) == ignoreind {
                ignoreind = ignoreit.next();
                continue;
            }
            if Some(&i) == skipind {
                skipind = skipit.next();
                rowlabels.push(item.to_string());
            } else {
                match item.parse() {
                    Ok(d) => data.push(d),
                    Err(err) if !ignore_error => {
                        return Err(PyValueError::new_err(format!(
                            "Failed to parse data point in row: {}, col: {} item: {} error: {}",
                            rows, i, item, err
                        )));
                    }
                    _ => data.push(f32::NAN),
                }
            }
        }
        labels.push(rowlabels)
    }

    let data = NdArrayD {
        inner: NdArray::new_with_values(vec![rows as u32, (data.len() / rows) as u32], data)
            .map_err(|err| {
                PyValueError::new_err(format!("failed to build nd array of data {}", err))
            })?,
    };

    let res = PyDict::new(py);
    match label_columns.len() {
        1 => {
            res.set_item("labels", labels.into_iter().flatten().collect::<Vec<_>>())?;
        }
        _ => {
            res.set_item("labels", labels)?;
        }
    }
    res.set_item("columns", columns)?;
    res.set_item("data", Py::new(py, data)?)?;

    Ok(res)
}

pub fn setup_module(_py: Python, m: &PyModule) -> PyResult<()> {
    m.add_function(wrap_pyfunction!(load_csv, m)?)?;
    Ok(())
}

use anyhow::{anyhow, bail, Result};
use quote::ToTokens;
use std::collections::HashMap;
use syn::ReturnType;

use crate::helpers::get_docs;
use crate::{
    function::{self, ParserType},
    impl_::{parse_attribute, ParsedAttribute, PropAttrTy, RenameRule, Visibility},
};
use proc_macro2::{Ident, Span, TokenStream};
use quote::quote;
use syn::{punctuated::Punctuated, FnArg, ImplItemMethod, Lit, Pat, Token, Type};

#[derive(Debug, Clone)]
pub enum Arg {
    Receiver(MethodType),
    Typed(function::Arg),
}

#[derive(Debug)]
pub struct AttrArgs {
    pub defaults: HashMap<String, Lit>,
    pub optional: Option<String>,
    pub visibility: Visibility,
}

#[derive(Debug, Clone)]
pub struct Method {
    /// Method name
    pub name: String,
    /// extern "C" function ident
    pub ident: String,
    /// Rust internal function ident
    pub orig_ident: String,
    pub docs: Vec<String>,
    pub args: Vec<Arg>,
    pub optional: Option<String>,
    pub output: Option<(String, bool)>,
    pub _static: bool,
    pub visibility: Visibility,
}

pub struct ParsedMethod {
    pub tokens: TokenStream,
    pub method: Method,
    pub property: Option<(String, PropAttrTy)>,
    pub constructor: bool,
}

#[derive(Debug, Clone, Copy)]
pub enum MethodType {
    Receiver { mutable: bool },
    ReceiverClassObject,
    Static,
}

impl ParsedMethod {
    pub fn new(
        tokens: TokenStream,
        method: Method,
        property: Option<(String, PropAttrTy)>,
        constructor: bool,
    ) -> Self {
        Self {
            tokens,
            method,
            property,
            constructor,
        }
    }
}

pub fn parser(
    struct_ty: &Type,
    mut input: ImplItemMethod,
    rename_rule: RenameRule,
) -> Result<ParsedMethod> {
    let mut defaults = HashMap::new();
    let mut optional = None;
    let mut visibility = Visibility::Public;
    let mut as_prop = None;
    let mut identifier = None;
    let mut is_constructor = false;
    let docs = get_docs(&input.attrs);

    for attr in input.attrs.iter() {
        if let Some(attr) = parse_attribute(attr)? {
            match attr {
                ParsedAttribute::Default(list) => defaults = list,
                ParsedAttribute::Optional(name) => optional = Some(name),
                ParsedAttribute::Visibility(vis) => visibility = vis,
                ParsedAttribute::Rename(ident) => identifier = Some(ident),
                ParsedAttribute::Property { prop_name, ty } => {
                    if as_prop.is_some() {
                        bail!(
                            "Only one `#[getter]` and/or `#[setter]` attribute may be used per method."
                        );
                    }

                    let prop_name = prop_name.unwrap_or_else(|| {
                        input
                            .sig
                            .ident
                            .to_token_stream()
                            .to_string()
                            .trim_start_matches("get_")
                            .trim_start_matches("set_")
                            .to_string()
                    });
                    as_prop = Some((prop_name, ty))
                }
                ParsedAttribute::Constructor => is_constructor = true,
                _ => bail!("Invalid attribute for method."),
            }
        }
    }

    input.attrs.clear();

    let ident = &input.sig.ident;
    let name = identifier.unwrap_or_else(|| rename_rule.rename(ident.to_string()));
    if name == "__construct" {
        is_constructor = true;
    }

    if is_constructor && (!matches!(visibility, Visibility::Public) || as_prop.is_some()) {
        bail!("`#[constructor]` attribute cannot be combined with the visibility or getter/setter attributes.");
    }

    let bail = if is_constructor {
        quote! { return ConstructorResult::ArgError; }
    } else {
        quote! { return; }
    };
    let internal_ident = Ident::new(&format!("_internal_php_{}", ident), Span::call_site());
    let args = build_args(struct_ty, &mut input.sig.inputs, &defaults)?;
    let optional = function::find_optional_parameter(
        args.iter().filter_map(|arg| match arg {
            Arg::Typed(arg) => Some(arg),
            _ => None,
        }),
        optional,
    );
    let (arg_definitions, method_type) = build_arg_definitions(&args);
    let arg_parser = build_arg_parser(
        args.iter(),
        &optional,
        &bail,
        match method_type {
            MethodType::Static => ParserType::StaticMethod,
            _ => ParserType::Method,
        },
    )?;
    let arg_accessors = build_arg_accessors(&args, &bail);

    let func = if is_constructor {
        quote! {
            #input

            #[doc(hidden)]
            pub fn #internal_ident(
                ex: &mut ::ext_php_rs::zend::ExecuteData
            ) -> ::ext_php_rs::class::ConstructorResult<Self> {
                use ::ext_php_rs::convert::IntoZval;
                use ::ext_php_rs::class::ConstructorResult;

                #(#arg_definitions)*
                #arg_parser

                Self::#ident(#(#arg_accessors,)*).into()
            }
        }
    } else {
        let this = match method_type {
            MethodType::Receiver { .. } => quote! { this. },
            MethodType::ReceiverClassObject | MethodType::Static => quote! { Self:: },
        };

        quote! {
            #input

            #[doc(hidden)]
            pub extern "C" fn #internal_ident(
                ex: &mut ::ext_php_rs::zend::ExecuteData,
                retval: &mut ::ext_php_rs::types::Zval
            ) {
                use ::ext_php_rs::convert::IntoZval;

                #(#arg_definitions)*
                #arg_parser

                let result = #this #ident(#(#arg_accessors,)*);

                if let Err(e) = result.set_zval(retval, false) {
                    let e: ::ext_php_rs::exception::PhpException = e.into();
                    e.throw().expect("Failed to throw exception");
                }
            }
        }
    };

    let method = Method {
        name,
        ident: internal_ident.to_string(),
        orig_ident: ident.to_string(),
        docs,
        args,
        optional,
        output: get_return_type(struct_ty, &input.sig.output)?,
        _static: matches!(method_type, MethodType::Static),
        visibility,
    };

    Ok(ParsedMethod::new(func, method, as_prop, is_constructor))
}

pub fn get_return_type(self_ty: &Type, output_type: &ReturnType) -> Result<Option<(String, bool)>> {
    Ok(match output_type {
        ReturnType::Default => None,
        ReturnType::Type(_, ty) => {
            let mut ty = ty.clone();
            replace_self(self_ty, &mut ty);
            crate::function::Arg::from_type("".to_string(), &ty, None, true)
                .map(|arg| (arg.ty, arg.nullable))
        }
    })
}

/// Takes a type `ty` and replaces all instances of `Self` with the type
/// `self_ty`.
fn replace_self(self_ty: &Type, ty: &mut Type) {
    match ty {
        Type::Array(syn::TypeArray { elem, .. }) => replace_self(self_ty, elem),
        Type::BareFn(syn::TypeBareFn { inputs, output, .. }) => {
            for input in inputs {
                replace_self(self_ty, &mut input.ty);
            }
            if let ReturnType::Type(_, ty) = output {
                replace_self(self_ty, ty);
            }
        }
        Type::Group(syn::TypeGroup { elem, .. }) => replace_self(self_ty, elem),
        Type::Paren(syn::TypeParen { elem, .. }) => replace_self(self_ty, elem),
        Type::Path(syn::TypePath { qself, path }) => {
            if let Some(syn::QSelf { ty, .. }) = qself {
                replace_self(self_ty, ty);
            }
            for seg in &mut path.segments {
                if seg.ident == "Self" {
                    seg.ident =
                        Ident::new(&self_ty.to_token_stream().to_string(), Span::call_site());
                }
                match &mut seg.arguments {
                    syn::PathArguments::AngleBracketed(syn::AngleBracketedGenericArguments {
                        args,
                        ..
                    }) => {
                        for arg in args {
                            if let syn::GenericArgument::Type(ty) = arg {
                                replace_self(self_ty, ty);
                            }
                        }
                    }
                    syn::PathArguments::Parenthesized(syn::ParenthesizedGenericArguments {
                        inputs,
                        output,
                        ..
                    }) => {
                        for input in inputs {
                            replace_self(self_ty, input);
                        }

                        if let ReturnType::Type(_, ty) = output {
                            replace_self(self_ty, ty);
                        }
                    }
                    _ => {}
                }
            }
        }
        Type::Ptr(syn::TypePtr { elem, .. }) => replace_self(self_ty, elem),
        Type::Reference(syn::TypeReference { elem, .. }) => replace_self(self_ty, elem),
        Type::Slice(syn::TypeSlice { elem, .. }) => replace_self(self_ty, elem),
        Type::Tuple(syn::TypeTuple { elems, .. }) => {
            for elem in elems {
                replace_self(self_ty, elem);
            }
        }
        _ => {}
    }
}

fn build_args(
    struct_ty: &Type,
    inputs: &mut Punctuated<FnArg, Token![,]>,
    defaults: &HashMap<String, Lit>,
) -> Result<Vec<Arg>> {
    inputs
        .iter_mut()
        .map(|arg| match arg {
            FnArg::Receiver(receiver) => {
                if receiver.reference.is_none() {
                    bail!("`self` parameter must be a reference.");
                }
                Ok(Arg::Receiver(MethodType::Receiver {
                    mutable: receiver.mutability.is_some(),
                }))
            }
            FnArg::Typed(ty) => {
                let mut this = false;
                let attrs = std::mem::take(&mut ty.attrs);
                for attr in attrs.into_iter() {
                    if let Some(attr) = parse_attribute(&attr)? {
                        match attr {
                            ParsedAttribute::This => this = true,
                            _ => bail!("Invalid attribute for argument."),
                        }
                    }
                }

                if this {
                    Ok(Arg::Receiver(MethodType::ReceiverClassObject))
                } else {
                    let name = match &*ty.pat {
                        Pat::Ident(pat) => pat.ident.to_string(),
                        _ => bail!("Invalid parameter type."),
                    };
                    let default = defaults.get(&name);
                    let mut ty = ty.ty.clone();
                    replace_self(struct_ty, &mut ty);

                    Ok(Arg::Typed(
                        crate::function::Arg::from_type(name.clone(), &ty, default, false)
                            .ok_or_else(|| anyhow!("Invalid parameter type for `{}`.", name))?,
                    ))
                }
            }
        })
        .collect()
}

fn build_arg_definitions(args: &[Arg]) -> (Vec<TokenStream>, MethodType) {
    let mut method_type = MethodType::Static;

    (
        args.iter()
            .filter_map(|ty| match ty {
                Arg::Receiver(t) => {
                    method_type = *t;
                    None
                }
                Arg::Typed(arg) => {
                    let ident = arg.get_name_ident();
                    let definition = arg.get_arg_definition();
                    Some(quote! {
                        let mut #ident = #definition;
                    })
                }
            })
            .collect(),
        method_type,
    )
}

fn build_arg_parser<'a>(
    args: impl Iterator<Item = &'a Arg>,
    optional: &Option<String>,
    ret: &TokenStream,
    ty: ParserType,
) -> Result<TokenStream> {
    function::build_arg_parser(
        args.filter_map(|arg| match arg {
            Arg::Typed(arg) => Some(arg),
            _ => None,
        }),
        optional,
        ret,
        ty,
    )
}

fn build_arg_accessors(args: &[Arg], ret: &TokenStream) -> Vec<TokenStream> {
    args.iter()
        .filter_map(|arg| match arg {
            Arg::Typed(arg) => Some(arg.get_accessor(ret)),
            Arg::Receiver(MethodType::ReceiverClassObject) => Some(quote! { this }),
            _ => None,
        })
        .collect()
}

impl Method {
    #[inline]
    pub fn get_name_ident(&self) -> Ident {
        Ident::new(&self.ident, Span::call_site())
    }

    pub fn get_arg_definitions(&self) -> impl Iterator<Item = TokenStream> + '_ {
        self.args.iter().filter_map(move |arg| match arg {
            Arg::Typed(arg) => {
                let def = arg.get_arg_definition();
                let prelude = self.optional.as_ref().and_then(|opt| {
                    if opt.eq(&arg.name) {
                        Some(quote! { .not_required() })
                    } else {
                        None
                    }
                });
                Some(quote! { #prelude.arg(#def) })
            }
            _ => None,
        })
    }

    pub fn get_builder(&self, class_path: &Ident) -> TokenStream {
        let name = &self.name;
        let name_ident = self.get_name_ident();
        let args = self.get_arg_definitions();
        let output = self.output.as_ref().map(|(ty, nullable)| {
            let ty: Type = syn::parse_str(ty).unwrap();

            // TODO allow reference returns?
            quote! {
                .returns(<#ty as ::ext_php_rs::convert::IntoZval>::TYPE, false, #nullable)
            }
        });

        quote! {
            ::ext_php_rs::builders::FunctionBuilder::new(#name, #class_path :: #name_ident)
                #(#args)*
                #output
                .build()
        }
    }

    pub fn get_flags(&self) -> TokenStream {
        let mut flags = vec![match self.visibility {
            Visibility::Public => quote! { Public },
            Visibility::Protected => quote! { Protected },
            Visibility::Private => quote! { Private },
        }];

        if self._static {
            flags.push(quote! { Static });
        }

        flags
            .iter()
            .map(|flag| quote! { ::ext_php_rs::flags::MethodFlags::#flag })
            .collect::<Punctuated<TokenStream, Token![|]>>()
            .to_token_stream()
    }
}

use cassandra_protocol::error;
use cassandra_protocol::frame::Frame;
use std::sync::Arc;

use crate::cluster::topology::Node;
use crate::cluster::ConnectionManager;
use crate::retry::{QueryInfo, RetryDecision, RetrySession};
use crate::transport::CdrsTransport;

/// Mid-level interface for sending frames to the cluster. Uses a query plan to route frame to
/// appropriate node, and retry policy for error handling. Returns `None` if no nodes were present
/// in the query plan.
pub async fn send_frame<T: CdrsTransport + 'static, CM: ConnectionManager<T> + 'static>(
    query_plan: impl Iterator<Item = Arc<Node<T, CM>>>,
    frame: &Frame,
    is_idempotent: bool,
    mut retry_session: Box<dyn RetrySession + Send + Sync>,
) -> Option<error::Result<Frame>> {
    'next_node: for node in query_plan {
        loop {
            let transport = node.persistent_connection().await;
            match transport {
                Ok(transport) => match transport.write_frame(frame).await {
                    Ok(frame) => return Some(Ok(frame)),
                    Err(error) => {
                        let query_info = QueryInfo {
                            error: &error,
                            is_idempotent,
                        };

                        match retry_session.decide(query_info) {
                            RetryDecision::RetrySameNode => continue,
                            RetryDecision::RetryNextNode => continue 'next_node,
                            RetryDecision::DontRetry => return Some(Err(error)),
                        }
                    }
                },
                Err(error) => return Some(Err(error)),
            }
        }
    }

    None
}

use crate::address::address::Address;
use crate::array::CArray;
use crate::data::CData;
use crate::error::CError;
use crate::option::COption;
use crate::panic::*;
use crate::ptr::*;
use crate::value::Value;
use cardano_serialization_lib::{
  crypto::DataHash as RDataHash, TransactionOutput as RTransactionOutput,
  TransactionOutputs as RTransactionOutputs,
};
use std::convert::{TryFrom, TryInto};

#[repr(C)]
#[derive(Copy, Clone)]
pub struct DataHash([u8; 32]);

impl From<RDataHash> for DataHash {
  fn from(hash: RDataHash) -> Self {
    Self(hash.to_bytes().try_into().unwrap())
  }
}

impl From<DataHash> for RDataHash {
  fn from(hash: DataHash) -> Self {
    hash.0.into()
  }
}

#[no_mangle]
pub unsafe extern "C" fn cardano_data_hash_to_bytes(
  data_hash: DataHash, result: &mut CData, error: &mut CError,
) -> bool {
  handle_exception(|| {
    let data_hash: RDataHash = data_hash.into();
    data_hash.to_bytes().into()
  })
  .response(result, error)
}

#[no_mangle]
pub unsafe extern "C" fn cardano_data_hash_from_bytes(
  data: CData, result: &mut DataHash, error: &mut CError,
) -> bool {
  handle_exception_result(|| {
    data
      .unowned()
      .and_then(|bytes| RDataHash::from_bytes(bytes.to_vec()).into_result())
      .map(|data_hash| data_hash.into())
  })
  .response(result, error)
}

#[repr(C)]
#[derive(Copy, Clone)]
pub struct TransactionOutput {
  address: Address,
  amount: Value,
  data_hash: COption<DataHash>,
}

impl Free for TransactionOutput {
  unsafe fn free(&mut self) {
    self.address.free();
    self.amount.free();
  }
}

impl TryFrom<TransactionOutput> for RTransactionOutput {
  type Error = CError;

  fn try_from(transaction_output: TransactionOutput) -> Result<Self> {
    transaction_output
      .address
      .try_into()
      .zip(transaction_output.amount.try_into())
      .map(|(address, amount)| {
        let mut to = Self::new(&address, &amount);
        let data_hash: Option<DataHash> = transaction_output.data_hash.into();
        data_hash.map(|data_hash| to.set_data_hash(&data_hash.into()));
        to
      })
  }
}

impl TryFrom<RTransactionOutput> for TransactionOutput {
  type Error = CError;

  fn try_from(transaction_output: RTransactionOutput) -> Result<Self> {
    transaction_output
      .address()
      .try_into()
      .zip(transaction_output.amount().try_into())
      .map(|(address, amount)| Self {
        address,
        amount,
        data_hash: transaction_output
          .data_hash()
          .map(|data_hash| data_hash.into())
          .into(),
      })
  }
}

#[no_mangle]
pub unsafe extern "C" fn cardano_transaction_output_to_bytes(
  transaction_output: TransactionOutput, result: &mut CData, error: &mut CError,
) -> bool {
  handle_exception_result(|| {
    transaction_output
      .try_into()
      .map(|transaction_output: RTransactionOutput| transaction_output.to_bytes())
      .map(|bytes| bytes.into())
  })
  .response(result, error)
}

#[no_mangle]
pub unsafe extern "C" fn cardano_transaction_output_from_bytes(
  data: CData, result: &mut TransactionOutput, error: &mut CError,
) -> bool {
  handle_exception_result(|| {
    data
      .unowned()
      .and_then(|bytes| RTransactionOutput::from_bytes(bytes.to_vec()).into_result())
      .and_then(|transaction_output| transaction_output.try_into())
  })
  .response(result, error)
}

#[no_mangle]
pub unsafe extern "C" fn cardano_transaction_output_clone(
  transaction_output: TransactionOutput, result: &mut TransactionOutput, error: &mut CError,
) -> bool {
  handle_exception(|| transaction_output.clone()).response(result, error)
}

#[no_mangle]
pub unsafe extern "C" fn cardano_transaction_output_free(
  transaction_output: &mut TransactionOutput,
) {
  transaction_output.free();
}

pub type TransactionOutputs = CArray<TransactionOutput>;

impl TryFrom<TransactionOutputs> for RTransactionOutputs {
  type Error = CError;

  fn try_from(transaction_outputs: TransactionOutputs) -> Result<Self> {
    let vec = unsafe { transaction_outputs.unowned()? };
    let mut transaction_outputs = Self::new();
    for transaction_output in vec.to_vec() {
      let transaction_output = transaction_output.try_into()?;
      transaction_outputs.add(&transaction_output);
    }
    Ok(transaction_outputs)
  }
}

impl TryFrom<RTransactionOutputs> for TransactionOutputs {
  type Error = CError;

  fn try_from(transaction_outputs: RTransactionOutputs) -> Result<Self> {
    (0..transaction_outputs.len())
      .map(|index| transaction_outputs.get(index))
      .map(|transaction_output| transaction_output.try_into())
      .collect::<Result<Vec<TransactionOutput>>>()
      .map(|transaction_outputs| transaction_outputs.into())
  }
}

#[no_mangle]
pub unsafe extern "C" fn cardano_transaction_outputs_free(
  transaction_outputs: &mut TransactionOutputs,
) {
  transaction_outputs.free();
}

//! Module with common error types.

mod ganache;
mod parity;
pub(crate) mod revert;

use crate::transaction::TransactionResult;
use ethcontract_common::abi::{Error as AbiError, Event, Function};
use ethcontract_common::abiext::EventExt;
pub use ethcontract_common::errors::*;
use secp256k1::Error as Secp256k1Error;
use std::num::ParseIntError;
use thiserror::Error;
use uint::FromDecStrErr;
use web3::contract::Error as Web3ContractError;
use web3::error::Error as Web3Error;
use web3::types::{Log, TransactionReceipt, H256};

/// Error that can occur while locating a deployed contract.
#[derive(Debug, Error)]
pub enum DeployError {
    /// An error occured while performing a web3 call.
    #[error("web3 error: {0}")]
    Web3(#[from] Web3Error),

    /// No previously deployed contract could be found on the network being used
    /// by the current `web3` provider.
    #[error("could not find deployed contract for network {0}")]
    NotFound(String),

    /// Error linking a contract with a deployed library.
    #[error("could not link library {0}")]
    Link(#[from] LinkError),

    /// Attempted to deploy a contract when empty bytecode. This can happen when
    /// attempting to deploy a contract that is actually an interface.
    #[error("can not deploy contract with empty bytecode")]
    EmptyBytecode,

    /// An error occured encoding deployment parameters with the contract ABI.
    #[error("error ABI ecoding deployment parameters: {0}")]
    Abi(#[from] AbiError),

    /// Error executing contract deployment transaction.
    #[error("error executing contract deployment transaction: {0}")]
    Tx(#[from] ExecutionError),

    /// Transaction was unable to confirm and is still pending. The contract
    /// address cannot be determined.
    #[error("contract deployment transaction pending: {0}")]
    Pending(H256),
}

/// Error that can occur while executing a contract call or transaction.
#[derive(Debug, Error)]
pub enum ExecutionError {
    /// An error occured while performing a web3 call.
    #[error("web3 error: {0}")]
    Web3(Web3Error),

    /// An error occured while ABI decoding the result of a contract method
    /// call.
    #[error("abi decode error: {0}")]
    AbiDecode(#[from] Web3ContractError),

    /// An error occured while parsing chain ID received from a Web3 call.
    #[error("parse chain ID error: {0}")]
    Parse(#[from] ParseIntError),

    /// An error indicating that an attempt was made to build or send a locally
    /// signed transaction to a node without any local accounts.
    #[error("no local accounts")]
    NoLocalAccounts,

    /// A contract call reverted.
    #[error("contract call reverted with message: {0:?}")]
    Revert(Option<String>),

    /// A contract call executed an invalid opcode.
    #[error("contract call executed an invalid opcode")]
    InvalidOpcode,

    /// A contract transaction failed to confirm within the block timeout limit.
    #[error("transaction confirmation timed-out")]
    ConfirmTimeout(Box<TransactionResult>),

    /// Transaction failure (e.g. out of gas or revert).
    #[error("transaction failed: {:?}", .0.transaction_hash)]
    Failure(Box<TransactionReceipt>),

    /// Failed to find a transaction by hash.
    #[error("missing transaction {0:?}")]
    MissingTransaction(H256),

    /// Failed to get a block for a pending transaction that has not yet been
    /// mined.
    #[error("pending transaction {0:?}, not yet part of a block")]
    PendingTransaction(H256),

    /// A removed log was received when querying past logs.
    #[error("unexepected removed log when querying past logs")]
    RemovedLog(Box<Log>),

    /// A stream ended unexpectedly.
    #[error("log stream ended unexpectedly")]
    StreamEndedUnexpectedly,
}

impl From<Web3Error> for ExecutionError {
    fn from(err: Web3Error) -> Self {
        if let Web3Error::Rpc(jsonrpc_err) = &err {
            if let Some(err) = ganache::get_encoded_error(&jsonrpc_err) {
                return err;
            }
            if let Some(err) = parity::get_encoded_error(&jsonrpc_err) {
                return err;
            }
        }

        ExecutionError::Web3(err)
    }
}

impl From<AbiError> for ExecutionError {
    fn from(err: AbiError) -> Self {
        ExecutionError::AbiDecode(err.into())
    }
}

/// Error that can occur while executing a contract call or transaction.
#[derive(Debug, Error)]
#[error("method '{signature}' failure: {inner}")]
pub struct MethodError {
    /// The signature of the failed method.
    pub signature: String,

    /// The inner execution error that for the method transaction that failed.
    #[source]
    pub inner: ExecutionError,
}

impl MethodError {
    /// Create a new `MethodError` from an ABI function specification and an
    /// inner `ExecutionError`.
    pub fn new<I: Into<ExecutionError>>(function: &Function, inner: I) -> Self {
        MethodError::from_parts(function.signature(), inner.into())
    }

    /// Create a `MethodError` from its signature and inner `ExecutionError`.
    pub fn from_parts(signature: String, inner: ExecutionError) -> Self {
        MethodError { signature, inner }
    }
}

/// Error that can occur while streaming contract events.
#[derive(Debug, Error)]
#[error("event '{signature}' failure: {inner}")]
pub struct EventError {
    /// The signature of the failed event.
    pub signature: String,

    /// The inner execution error that for the method transaction that failed.
    #[source]
    pub inner: ExecutionError,
}

impl EventError {
    /// Create a new `EventError` from an ABI function specification and an
    /// inner `ExecutionError`.
    pub fn new<I: Into<ExecutionError>>(event: &Event, inner: I) -> Self {
        EventError::from_parts(event.abi_signature(), inner.into())
    }

    /// Create a `EventError` from its signature and inner `ExecutionError`.
    pub fn from_parts(signature: String, inner: ExecutionError) -> Self {
        EventError { signature, inner }
    }
}

/// An error indicating an invalid private key. Private keys for secp256k1 must
/// be exactly 32 bytes and fall within the range `[1, n)` where `n` is the
/// order of the generator point of the curve.
#[derive(Debug, Error)]
#[error("invalid private key")]
pub struct InvalidPrivateKey;

impl From<Secp256k1Error> for InvalidPrivateKey {
    fn from(err: Secp256k1Error) -> Self {
        match err {
            Secp256k1Error::InvalidSecretKey => {}
            _ => {
                // NOTE: Assert that we never try to make this conversion with
                //   errors not related to `SecretKey`.
                debug_assert!(false, "invalid conversion to InvalidPrivateKey error");
            }
        }
        InvalidPrivateKey
    }
}

/// The error type that is returned when conversion to or from a 256-bit integer
/// fails.
#[derive(Clone, Copy, Debug, Error)]
#[error("output of range integer conversion attempted")]
pub struct TryFromBigIntError;

/// The error type that is returned when parsing a 256-bit signed integer.
#[derive(Clone, Copy, Debug, Error)]
pub enum ParseI256Error {
    /// Error that occurs when an invalid digit is encountered while parsing.
    #[error("invalid digit found in string")]
    InvalidDigit,

    /// Error that occurs when the number is too large or too small (negative)
    /// and does not fit in a 256-bit signed integer.
    #[error("number does not fit in 256-bit integer")]
    IntegerOverflow,
}

impl From<FromDecStrErr> for ParseI256Error {
    fn from(err: FromDecStrErr) -> Self {
        match err {
            FromDecStrErr::InvalidCharacter => ParseI256Error::InvalidDigit,
            FromDecStrErr::InvalidLength => ParseI256Error::IntegerOverflow,
        }
    }
}

