impl Facade for AdcFacade {
    async fn handle_request(&self, method: String, args: Value) -> Result<Value, Error> {
        match method.as_ref() {
            "GetResolution" => {
                let result = self.get_resolution(args).await?;
                Ok(to_value(result)?)
            }
            "GetSample" => {
                let result = self.get_sample(args).await?;
                Ok(to_value(result)?)
