        // instead of expecting it to be passed in. The random id is a temporary
        // workaround.
        let mut rng = thread_rng();
        let id = rng.gen::<u64>();

        let (project_names, project_idents): (Vec<String>, Vec<String>) =
            project_tuples.iter().cloned().unzip();

        conn.execute(
            "SELECT insert_group_v1($1, $2, $3)",
            &[&(id as i64), &project_names, &project_idents],
        ).map_err(Error::GroupCreate)?;

        let mut projects = RepeatedField::new();

        for (name, ident) in project_tuples {
            let mut project = Project::new();
            project.set_name(name);
            project.set_ident(ident);
            project.set_state(ProjectState::NotStarted);
            projects.push(project);
        }

        let mut group = Group::new();
        group.set_id(id);
        group.set_state(GroupState::Pending);
        group.set_projects(projects);

        debug!("Group created: {:?}", group);

        Ok(group)
    }

    pub fn get_group(&self, msg: &GroupGet) -> Result<Option<Group>> {
        let group_id = msg.get_group_id();

        let conn = self.pool.get_shard(0)?;
        let rows = &conn.query("SELECT * FROM get_group_v1($1)", &[&(group_id as i64)])
            .map_err(Error::GroupGet)?;

        if rows.is_empty() {
            warn!("Group id {} not found", group_id);
            return Ok(None);
        }

        assert!(rows.len() == 1); // should never have more than one

        let mut group = self.row_to_group(&rows.get(0))?;

        let project_rows = &conn.query(
            "SELECT * FROM get_projects_for_group_v1($1)",
            &[&(group_id as i64)],
        ).map_err(Error::GroupGet)?;

        assert!(project_rows.len() > 0); // should at least have one
        let projects = self.rows_to_projects(&project_rows)?;

        group.set_projects(projects);
        Ok(Some(group))
    }

    fn row_to_package(&self, row: &postgres::rows::Row) -> Result<Package> {
        let mut package = Package::new();

        let name: String = row.get("ident");
        package.set_ident(name);

        let deps: Vec<String> = row.get("deps");

        let mut pb_deps = RepeatedField::new();

        for dep in deps {
            pb_deps.push(dep);
        }

        package.set_deps(pb_deps);

        Ok(package)
    }

    fn row_to_group(&self, row: &postgres::rows::Row) -> Result<Group> {
        let mut group = Group::new();

        let id: i64 = row.get("id");
        group.set_id(id as u64);
        let js: String = row.get("group_state");
        let group_state = match &js[..] {
            "Dispatching" => GroupState::Dispatching,
            "Pending" => GroupState::Pending,
            "Complete" => GroupState::Complete,
            "Failed" => GroupState::Failed,
            _ => return Err(Error::UnknownGroupState),
        };
        group.set_state(group_state);

        let created_at = row.get::<&str, DateTime<UTC>>("created_at");
        group.set_created_at(created_at.to_rfc3339());

        Ok(group)
    }

    fn row_to_project(&self, row: &postgres::rows::Row) -> Result<Project> {
        let mut project = Project::new();

        let name: String = row.get("project_name");
        let ident: String = row.get("project_ident");
        let state: String = row.get("project_state");
        let job_id: i64 = row.get("job_id");

        let project_state = match &state[..] {
            "NotStarted" => ProjectState::NotStarted,
            "InProgress" => ProjectState::InProgress,
            "Success" => ProjectState::Success,
            "Failure" => ProjectState::Failure,
            "Skipped" => ProjectState::Skipped,
            _ => return Err(Error::UnknownProjectState),
        };

        project.set_name(name);
        project.set_ident(ident);
        project.set_state(project_state);
        project.set_job_id(job_id as u64);

        Ok(project)
    }

    fn rows_to_projects(&self, rows: &postgres::rows::Rows) -> Result<RepeatedField<Project>> {
        let mut projects = RepeatedField::new();

        for row in rows {
            let project = self.row_to_project(&row)?;
            projects.push(project);
        }

        Ok(projects)
    }

    pub fn set_group_state(&self, group_id: u64, group_state: GroupState) -> Result<()> {
        let conn = self.pool.get_shard(0)?;
        let state = match group_state {
            GroupState::Dispatching => "Dispatching",
            GroupState::Pending => "Pending",
            GroupState::Complete => "Complete",
            GroupState::Failed => "Failed",
        };
        conn.execute(
            "SELECT set_group_state_v1($1, $2)",
            &[&(group_id as i64), &state],
        ).map_err(Error::GroupSetState)?;
        Ok(())
    }

    pub fn set_group_project_state(
        &self,
        group_id: u64,
        project_name: &str,
        project_state: ProjectState,
    ) -> Result<()> {
        let conn = self.pool.get_shard(0)?;
        let state = match project_state {
            ProjectState::NotStarted => "NotStarted",
            ProjectState::InProgress => "InProgress",
            ProjectState::Success => "Success",
            ProjectState::Failure => "Failure",
            ProjectState::Skipped => "Skipped",
        };
        conn.execute(
            "SELECT set_project_name_state_v1($1, $2, $3)",
            &[&(group_id as i64), &project_name, &state],
        ).map_err(Error::ProjectSetState)?;
        Ok(())
    }

    pub fn set_group_job_state(&self, job: &Job) -> Result<()> {
        let conn = self.pool.get_shard(0)?;
        let rows = &conn.query(
            "SELECT * FROM find_project_v1($1, $2)",
            &[&(job.get_owner_id() as i64), &job.get_project().get_name()],
        ).map_err(Error::ProjectSetState)?;

        // No rows means this job might not be one we care about
        if rows.is_empty() {
            warn!("No project found for job id: {}", job.get_id());
            return Err(Error::UnknownJobState);
        }

        assert!(rows.len() == 1); // should never have more than one
        let pid: i64 = rows.get(0).get("id");

        let state = match job.get_state() {
            JobState::Complete => "Success",
            JobState::Rejected => "NotStarted", // retry submission
            JobState::Failed => "Failure",
            _ => "InProgress",
        };

        if job.get_state() == JobState::Complete {
            let ident = job.get_package_ident().to_string();

            conn.execute(
                "SELECT set_project_state_ident_v1($1, $2, $3, $4)",
                &[&pid, &(job.get_id() as i64), &state, &ident],
            ).map_err(Error::ProjectSetState)?;
        } else {
            conn.execute(
                "SELECT set_project_state_v1($1, $2, $3)",
                &[&pid, &(job.get_id() as i64), &state],
            ).map_err(Error::ProjectSetState)?;
        };

        Ok(())
    }

    pub fn pending_groups(&self, count: i32) -> Result<Vec<Group>> {
        let mut groups = Vec::new();

        let conn = self.pool.get_shard(0)?;
        let group_rows = &conn.query("SELECT * FROM pending_groups_v1($1)", &[&count])
            .map_err(Error::GroupPending)?;

        for group_row in group_rows {
            let mut group = self.row_to_group(&group_row)?;

            let project_rows = &conn.query(
                "SELECT * FROM get_projects_for_group_v1($1)",
                &[&(group.get_id() as i64)],
            ).map_err(Error::GroupPending)?;
            let projects = self.rows_to_projects(&project_rows)?;

            group.set_projects(projects);
            groups.push(group);
        }

        Ok(groups)
    }
}

use std::collections::HashSet;
use std::fs::metadata;
use std::iter::FromIterator;
use std::path::Path;

use super::manifest::AssetManifest;

use crate::commands::kv;
use crate::commands::kv::bucket::directory_keys_only;
use crate::commands::kv::bucket::upload::upload_files;
use crate::commands::kv::bulk::delete::delete_bulk;
use crate::commands::kv::key::KeyList;
use crate::settings::global_user::GlobalUser;
use crate::settings::target::Target;
use crate::terminal::message;

pub fn sync(
    target: &Target,
    user: &GlobalUser,
    namespace_id: &str,
    path: &Path,
    verbose: bool,
) -> Result<AssetManifest, failure::Error> {
    kv::validate_target(target)?;
    // First, upload all changed files in given local directory (aka replace files
    // in Workers KV that are now stale).

    // Get remote keys, which contain the hash of the file (value) as the suffix.
    // Turn it into a HashSet. This will be used by upload() to figure out which
    // files to exclude from upload (because their current version already exists in
    // the Workers KV remote).
    let remote_keys_iter = KeyList::new(target, &user, namespace_id, None)?;
    let mut remote_keys: HashSet<String> = HashSet::new();
    for remote_key in remote_keys_iter {
        match remote_key {
            Ok(remote_key) => {
                remote_keys.insert(remote_key.name);
            }
            Err(e) => failure::bail!(kv::format_error(e)),
        }
    }
    // First, upload all existing files in given directory
    if verbose {
        message::info("Preparing to upload updated files...");
    }
    let asset_manifest = upload_files(
        target,
        &user,
        namespace_id,
        path,
        Some(&remote_keys),
        verbose,
    )?;

    // Now delete files from Workers KV that exist in remote but no longer exist locally.
    // Get local keys
    let local_keys_vec: Vec<String> = match &metadata(path) {
        Ok(file_type) if file_type.is_dir() => directory_keys_only(path),
        Ok(_) => failure::bail!("{} should be a directory", path.display()),
        Err(e) => failure::bail!("{}", e),
    }?;
    let local_keys: HashSet<_> = HashSet::from_iter(local_keys_vec.into_iter());

    // Find keys that are present in remote but not present in local, and
    // stage them for deletion.
    let keys_to_delete: Vec<_> = remote_keys
        .difference(&local_keys)
        .map(|key| key.to_owned())
        .collect();

    if !keys_to_delete.is_empty() {
        if verbose {
            message::info("Deleting stale files...");
        }
        delete_bulk(target, user, namespace_id, keys_to_delete)?;
    }

    message::success("Success");
    Ok(asset_manifest)
}

use rubigino::display::font::Character;
use rubigino::display::matrix::MAX72XX;
use rubigino::util;
use std::{thread, time};

fn main() {
    let delay = time::Duration::from_millis(250);

    let mut max: MAX72XX = MAX72XX::init().unwrap();
    max.clear().unwrap();

    let input: String = format!(" { } ", "Hello");

    for val in input.chars().rev() {
        let c: Character = Character::from(val);
        let mut input: [u8; 8] = c.encoding();
        util::rotate_cw(&mut input);
        for shift in 1..7 {
            util::shift_right(&mut input);
            max.write(&input).unwrap();
            thread::sleep(delay);
        }
    }
}

use crate::anyhow::Result;
use crate::runtime::AsyncKernel;
use crate::runtime::Block;
use crate::runtime::BlockMeta;
use crate::runtime::BlockMetaBuilder;
use crate::runtime::MessageIo;
use crate::runtime::MessageIoBuilder;
use crate::runtime::StreamIo;
use crate::runtime::StreamIoBuilder;
use crate::runtime::WorkIo;

pub struct NullSink<T: Send + 'static> {
    n_received: usize,
    _type: std::marker::PhantomData<T>,
}

impl<T: Send + 'static> NullSink<T> {
    pub fn new() -> Block {
        Block::new_async(
            BlockMetaBuilder::new("NullSink").build(),
            StreamIoBuilder::new()
                .add_input("in", std::mem::size_of::<T>())
                .build(),
            MessageIoBuilder::new().build(),
            NullSink::<T> {
                n_received: 0,
                _type: std::marker::PhantomData,
            },
        )
    }

    pub fn n_received(&self) -> usize {
        self.n_received
    }
}

#[async_trait]
impl<T: Send + 'static> AsyncKernel for NullSink<T> {
    async fn work(
        &mut self,
        io: &mut WorkIo,
        sio: &mut StreamIo,
        _mio: &mut MessageIo<Self>,
        _meta: &mut BlockMeta,
    ) -> Result<()> {
        let i = sio.input(0).slice::<u8>();

        let n = i.len() / std::mem::size_of::<T>();
        if n > 0 {
            self.n_received += n;
            sio.input(0).consume(n);
        }

        if sio.input(0).finished() {
            io.finished = true;
        }

        Ok(())
    }
}

//! Fuzz testing utilities related to AST pattern matching.

use peepmatic_runtime::PeepholeOptimizations;
use peepmatic_test_operator::TestOperator;
use std::path::Path;
use std::str;

// To avoid timeouts, don't deal with inputs larger than this.
const MAX_LEN: usize = 2048;

/// Attempt to interpret the given bytes as UTF-8 and then compile them as if
/// they were source text of our DSL.
pub fn compile(data: &[u8]) {
    if data.len() > MAX_LEN {
        return;
    }

    let source = match str::from_utf8(data) {
        Err(_) => return,
        Ok(s) => s,
    };

    let opt = match peepmatic::compile_str::<TestOperator>(source, Path::new("fuzz")) {
        Err(_) => return,
        Ok(o) => o,
    };

    // Should be able to serialize and deserialize the peephole optimizer.
    let opt_bytes = bincode::serialize(&opt).expect("should serialize peephole optimizations OK");
    let _: PeepholeOptimizations<TestOperator> =
        bincode::deserialize(&opt_bytes).expect("should deserialize peephole optimizations OK");

    // Compiling the same source text again should be deterministic.
    let opt2 = peepmatic::compile_str::<TestOperator>(source, Path::new("fuzz"))
        .expect("should be able to compile source text again, if it compiled OK the first time");
    let opt2_bytes =
        bincode::serialize(&opt2).expect("should serialize second peephole optimizations OK");
    assert_eq!(opt_bytes, opt2_bytes);
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn check_compile() {
        crate::check(|s: String| compile(s.as_bytes()));
    }

    #[test]
    fn regression_0() {
        compile(
            b"
            (=> (bor (bor $x $y) $y) $x)
            (=> (bor (bor $x $z) $y) $x)
        ",
        );
    }

    #[test]
    fn regression_1() {
        compile(
            b"
            (=> (bor (bor $x $y) 0) $x)
            (=> (bor $x 0) $x)
            (=> (bor $y $x) $x)
        ",
        );
    }

    #[test]
    fn regression_2() {
        compile(
            b"
            (=> (sshr $x 11111111110) $x)
        ",
        );
    }
}

