};

impl SelectBox {
    pub fn reset_bounds(&self, resize_info: &ResizeInfo) {
        self.bounds.set(self.elem.borrow().as_ref().map(|elem| {
            let rect = elem.get_bounding_client_rect();
            BoundsF64::new_from_dom_normalized(&rect, resize_info)
        }));
    }

    pub fn start_drag(&self, x: i32, y: i32) {
        self.drag
            .set(Some(Rc::new(Drag::new(x, y, 0.0, 0.0, true))));
    }

    pub fn try_move_drag(&self, x: i32, y: i32) {
        if let Some(drag) = self.drag.lock_ref().as_ref() {
            if let Some((_, diff)) = drag.update(x, y) {
                let resize_info = get_resize_info();
                let (diff_x, diff_y) = resize_info.get_px_normalized(diff.x as f64, diff.y as f64);

                self.transform_override.replace_with(|t| {
                    let mut t = t.clone();
                    t.add_translation_2d(diff_x * -1.0, diff_y * -1.0);

                    t
                });
            }
        }
    }

    pub fn try_end_drag(&self, _x: i32, _y: i32) -> Option<Transform> {
        if self.drag.lock_ref().is_some() {
            let _drag = self.drag.lock_mut().take().unwrap_ji();
            Some(self.transform_override.get_cloned())
        } else {
            None
        }
    }
}

use crate::feature::BondKind;

pub fn reconcile(
    left: BondKind, right: BondKind
) -> Option<(BondKind, BondKind)> {
    if left == right {
        if left == BondKind::Up || left == BondKind::Down {
            None
        } else {
            Some((left, right))
        }
    } else if left == BondKind::Up && right == BondKind::Down {
        Some((left, right))
    } else if left == BondKind::Down && right == BondKind::Up {
        Some((left, right))
    } else if left == BondKind::Elided {
        match right {
            BondKind::Up => Some((BondKind::Down, right)),
            BondKind::Down => Some((BondKind::Up, right)),
            _ => Some((right.clone(), right))
        }
    } else if right == BondKind::Elided {
        match left {
            BondKind::Up => Some((left, BondKind::Down)),
            BondKind::Down => Some((left, BondKind::Up)),
            _ => Some((left.clone(), left))
        }
    } else {
        None
    }
}

#[cfg(test)]
mod tests {
    use pretty_assertions::assert_eq;
    use super::*;

    #[test]
    fn single_double() {
        assert_eq!(
            reconcile(BondKind::Single, BondKind::Double),
            None
        )
    }

    #[test]
    fn up_up() {
        assert_eq!(
            reconcile(BondKind::Up, BondKind::Up),
            None
        )
    }

    #[test]
    fn down_down() {
        assert_eq!(
            reconcile(BondKind::Down, BondKind::Down),
            None
        )
    }

    #[test]
    fn elided_elided() {
        assert_eq!(
            reconcile(BondKind::Elided, BondKind::Elided),
            Some((BondKind::Elided, BondKind::Elided))
        )
    }

    #[test]
    fn elided_single() {
        assert_eq!(
            reconcile(BondKind::Elided, BondKind::Single),
            Some((BondKind::Single, BondKind::Single))
        )
    }

    #[test]
    fn elided_up() {
        assert_eq!(
            reconcile(BondKind::Elided, BondKind::Up),
            Some((BondKind::Down, BondKind::Up))
        )
    }

    #[test]
    fn elided_down() {
        assert_eq!(
            reconcile(BondKind::Elided, BondKind::Down),
            Some((BondKind::Up, BondKind::Down))
        )
    }

    #[test]
    fn up_elided() {
        assert_eq!(
            reconcile(BondKind::Up, BondKind::Elided),
            Some((BondKind::Up, BondKind::Down))
        )
    }

    #[test]
    fn down_elided() {
        assert_eq!(
            reconcile(BondKind::Down, BondKind::Elided),
            Some((BondKind::Down, BondKind::Up))
        )
    }

    #[test]
    fn up_down() {
        assert_eq!(
            reconcile(BondKind::Up, BondKind::Down),
            Some((BondKind::Up, BondKind::Down))
        )
    }

    #[test]
    fn down_up() {
        assert_eq!(
            reconcile(BondKind::Down, BondKind::Up),
            Some((BondKind::Down, BondKind::Up))
        )
    }

    #[test]
    fn single_elided() {
        assert_eq!(
            reconcile(BondKind::Single, BondKind::Elided),
            Some((BondKind::Single, BondKind::Single))
        )
    }
}

