use serde::de::{Deserialize, Deserializer, Error, SeqAccess, Visitor};
use serde::ser::{Serialize, SerializeTuple, Serializer};
use std::fmt;
use std::marker::PhantomData;

// serde doesn't know how to serialize big arrays out of the box
// see: https://github.com/serde-rs/serde/issues/631

pub trait BigArray<'de>: Sized {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer;
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>;
}

macro_rules! big_array {
    ($($len:expr,)+) => {
        $(
            impl<'de, T> BigArray<'de> for [T; $len]
                where T: Default + Copy + Serialize + Deserialize<'de>
            {
                fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
                    where S: Serializer
                {
                    let mut seq = serializer.serialize_tuple(self.len())?;
                    for elem in &self[..] {
                        seq.serialize_element(elem)?;
                    }
                    seq.end()
                }

                fn deserialize<D>(deserializer: D) -> Result<[T; $len], D::Error>
                    where D: Deserializer<'de>
                {
                    struct ArrayVisitor<T> {
                        element: PhantomData<T>,
                    }

                    impl<'de, T> Visitor<'de> for ArrayVisitor<T>
                        where T: Default + Copy + Deserialize<'de>
                    {
                        type Value = [T; $len];

                        fn expecting(&self, formatter: &mut fmt::Formatter) -> fmt::Result {
                            formatter.write_str(concat!("an array of length ", $len))
                        }

                        fn visit_seq<A>(self, mut seq: A) -> Result<[T; $len], A::Error>
                            where A: SeqAccess<'de>
                        {
                            let mut arr = [T::default(); $len];
                            for (i, element) in arr.iter_mut().enumerate() {
                                *element = seq.next_element()?.ok_or_else(|| Error::invalid_length(i, &self))?
                            }
                            Ok(arr)
                        }
                    }

                    let visitor = ArrayVisitor { element: PhantomData };
                    deserializer.deserialize_tuple($len, visitor)
                }
            }
        )+
    }
}

big_array! {
    40, 48, 50, 56, 64, 72, 96, 100, 128, 160, 192, 200, 224, 256, 384, 512,
    768, 1024, 2048, 4096, 8192, 16384, 32768, 65536,
}

fn parse_sub_packets(start: usize, get_bits: &dyn Fn(usize, usize) -> u64) -> (Vec<u64>, usize) {
    let mut pos = start;
    let length_type = get_bits(pos, 1);
    let (max_len, max_packet_count) = if length_type == 0 {
        let len = get_bits(pos + 1, 15) as usize;
        pos += 16;
        (len, u32::MAX)
    } else {
        let count = get_bits(pos + 1, 11) as u32;
        pos += 12;
        (usize::MAX, count)
    };
    let start_pos = pos;

    let mut nums = Vec::new();

    for count in 1.. {
        let (num, new_pos) = parse_packet(pos, get_bits);
        pos = new_pos;
        nums.push(num);
        if count >= max_packet_count || pos - start_pos >= max_len {
            break;
        }
    }

    (nums, pos)
}

fn parse_packet(start: usize, get_bits: &dyn Fn(usize, usize) -> u64) -> (u64, usize) {
    let type_id = get_bits(start + 3, 3);

    match type_id {
        0 => {
            let (nums, pos) = parse_sub_packets(start + 6, get_bits);
            (nums.into_iter().sum(), pos)
        }

        1 => {
            let (nums, pos) = parse_sub_packets(start + 6, get_bits);
            (nums.into_iter().product(), pos)
        }

        2 => {
            let (nums, pos) = parse_sub_packets(start + 6, get_bits);
            (nums.into_iter().min().unwrap(), pos)
        }

        3 => {
            let (nums, pos) = parse_sub_packets(start + 6, get_bits);
            (nums.into_iter().max().unwrap(), pos)
        }

        4 => {
            let mut pos = start + 6;
            let mut num = 0;
            let mut keep_going = true;

            while keep_going {
                keep_going = get_bits(pos, 1) == 1;
                num = num << 4 | get_bits(pos + 1, 4);
                pos += 5;
            }

            (num, pos)
        }

        5 => {
            let (nums, pos) = parse_sub_packets(start + 6, get_bits);
            (if nums[0] > nums[1] { 1 } else { 0 }, pos)
        }

        6 => {
            let (nums, pos) = parse_sub_packets(start + 6, get_bits);
            (if nums[0] < nums[1] { 1 } else { 0 }, pos)
        }

        7 => {
            let (nums, pos) = parse_sub_packets(start + 6, get_bits);
            (if nums[0] == nums[1] { 1 } else { 0 }, pos)
        }

        _ => panic!(),
    }
}

fn main() {
    let mut input = String::new();
    std::io::stdin().read_line(&mut input).unwrap();

    let data: Vec<_> = input.trim().chars().flat_map(|c| {
        let num = c.to_digit(16).unwrap();
        (0..4).map(move |i| (num >> 3 - i & 0b1) as u8)
    }).collect();

    let get_bits = move |start: usize, len: usize| {
        data.iter().skip(start).take(len).fold(0, |acc, &i| acc << 1 | i as u64)
    };

    println!("{}", parse_packet(0, &get_bits).0);
}

//!
//! The integer literal lexeme.
//!

use std::fmt;

///
/// The integer literal lexeme.
///
#[derive(Debug, Clone, PartialEq)]
pub enum Integer {
    /// An integer literal, like `42`.
    Decimal {
        /// The inner literal contents.
        inner: String,
    },
    /// A hexadecimal literal, like `0xffff`.
    Hexadecimal {
        /// The inner literal contents.
        inner: String,
    },
}

impl Integer {
    ///
    /// Creates a decimal value.
    ///
    pub fn new_decimal(inner: String) -> Self {
        Self::Decimal { inner }
    }

    ///
    /// Creates a hexadecimal value.
    ///
    pub fn new_hexadecimal(inner: String) -> Self {
        Self::Hexadecimal { inner }
    }

    ///
    /// Parses the value from the source code slice.
    ///
    pub fn parse(input: &str) -> Option<Self> {
        let decimal = regex::Regex::new("^[0-9]+$").expect("Regexp is valid");
        let hexadecimal = regex::Regex::new(r#"^0x[0-9a-fA-F]+$"#).expect("Regexp is valid");

        if decimal.is_match(input) {
            Some(Self::new_decimal(input.to_owned()))
        } else if hexadecimal.is_match(input) {
            Some(Self::new_hexadecimal(input.to_owned()))
        } else {
            None
        }
    }
}

impl fmt::Display for Integer {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Decimal { inner } => write!(f, "{}", inner),
            Self::Hexadecimal { inner } => write!(f, "{}", inner),
        }
    }
}

