use tokio::sync::broadcast;

use tokio_tungstenite::tungstenite::Message;

type UserMap = Arc<Mutex<HashMap<String, ()>>>;

#[derive(Clone)]
pub struct ChatRoom {
    user_map: UserMap,
    tx: broadcast::Sender<Message>
}

impl ChatRoom {
    pub fn new() -> Self {
        Self {
            user_map: Arc::new(Mutex::new(HashMap::new())),
            tx: broadcast::channel(100).0
        }
    }

    pub fn join(&self, username: String) -> Option<RoomReceiver> {
        let mut user_map = self.user_map.lock().unwrap();

        if user_map.contains_key(&username) {
            return None;
        }

        user_map.insert(username.clone(), ());

        drop(user_map);

        Some(RoomReceiver {
            username,
            user_map: self.user_map.clone(),
            rx: self.tx.subscribe()
        })
    }

    pub fn send(&self, msg: Message) {
        let _ = self.tx.send(msg);
    }
}

pub struct RoomReceiver {
    username: String,
    user_map: UserMap,
    rx: broadcast::Receiver<Message>
}

impl Deref for RoomReceiver {
    type Target = broadcast::Receiver<Message>;

    fn deref(&self) -> &Self::Target {
        &self.rx
    }
}

impl DerefMut for RoomReceiver {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.rx
    }
}

impl Drop for RoomReceiver {
    fn drop(&mut self) {
        self.user_map.lock().unwrap().remove(&self.username);
    }
}

use crate::system::Time;
use csfml_system_sys as ffi;

/// Utility type that measures the elapsed time.
///
/// Its provides the most precise time that the underlying OS can
/// achieve (generally microseconds or nanoseconds).
/// It also ensures monotonicity, which means that the returned time can never go backward,
/// even if the system time is changed.
///
/// # Usage example
/// ```
/// # use sfml::system::Clock;
/// let mut clock = Clock::start();
/// // ...
/// let time1 = clock.elapsed_time();
/// // ...
/// let time2 = clock.restart();
/// ```
///
/// The [`Time`] value returned by the clock can then be converted to
/// a number of seconds, milliseconds or even microseconds.
#[derive(Debug)]
pub struct Clock(*mut ffi::sfClock);

impl Clock {
    /// Creates a new Clock and starts it automatically.
    #[must_use]
    pub fn start() -> Clock {
        Clock(unsafe { ffi::sfClock_create() })
    }

    /// Gets the elapsed time.
    ///
    /// This function returns the time elapsed since the last call to [`restart`]
    /// (or the construction of the instance if [`restart`] has not been called).
    ///
    /// [`restart`]: Clock::restart
    #[must_use]
    pub fn elapsed_time(&self) -> Time {
        unsafe { Time::from_raw(ffi::sfClock_getElapsedTime(self.0)) }
    }

    /// Restarts the clock.
    ///
    /// This function puts the time counter back to zero.
    /// It also returns the time elapsed since the clock was started.
    pub fn restart(&mut self) -> Time {
        unsafe { Time::from_raw(ffi::sfClock_restart(self.0)) }
    }
}

impl Clone for Clock {
    fn clone(&self) -> Self {
        Clock(unsafe { ffi::sfClock_copy(self.0) })
    }
}

impl Drop for Clock {
    fn drop(&mut self) {
        unsafe { ffi::sfClock_destroy(self.0) }
    }
}

impl Default for Clock {
    /// Equivalent to `Clock::start()`.
    fn default() -> Self {
        Clock::start()
    }
}

use AsMutLua;
use AsLua;

use Push;
use PushGuard;
use LuaRead;

macro_rules! tuple_impl {
    ($ty:ident) => (
        impl<LU, $ty> Push<LU> for ($ty,) where LU: AsMutLua, $ty: Push<LU> {
            fn push_to_lua(self, lua: LU) -> PushGuard<LU> {
                self.0.push_to_lua(lua)
            }
        }

        impl<LU, $ty> LuaRead<LU> for ($ty,) where LU: AsMutLua, $ty: LuaRead<LU> {
            fn lua_read_at_position(lua: LU, index: i32) -> Result<($ty,), LU> {
                LuaRead::lua_read_at_position(lua, index).map(|v| (v,))
            }
        }
    );

    ($first:ident, $($other:ident),+) => (
        #[allow(non_snake_case)]
        impl<LU, $first: for<'a> Push<&'a mut LU>, $($other: for<'a> Push<&'a mut LU>),+>
            Push<LU> for ($first, $($other),+) where LU: AsMutLua
        {
            fn push_to_lua(self, mut lua: LU) -> PushGuard<LU> {
                match self {
                    ($first, $($other),+) => {
                        let mut total = $first.push_to_lua(&mut lua).forget();

                        $(
                            total += $other.push_to_lua(&mut lua).forget();
                        )+

                        PushGuard { lua: lua, size: total }
                    }
                }
            }
        }

        // TODO: what if T or U are also tuples? indices won't match
        #[allow(unused_assignments)]
        #[allow(non_snake_case)]
        impl<LU, $first: for<'a> LuaRead<&'a mut LU>, $($other: for<'a> LuaRead<&'a mut LU>),+>
            LuaRead<LU> for ($first, $($other),+) where LU: AsLua
        {
            fn lua_read_at_position(mut lua: LU, index: i32) -> Result<($first, $($other),+), LU> {
                let mut i = index;

                let $first: $first = match LuaRead::lua_read_at_position(&mut lua, i) {
                    Ok(v) => v,
                    Err(_) => return Err(lua)
                };

                i += 1;

                $(
                    let $other: $other = match LuaRead::lua_read_at_position(&mut lua, i) {
                        Ok(v) => v,
                        Err(_) => return Err(lua)
                    };
                    i += 1;
                )+

                Ok(($first, $($other),+))

            }
        }

        tuple_impl!($($other),+);
    );
}

