use std::{borrow::Borrow, marker::PhantomData};

use primitive_types::H256;
use rlp::{Decodable, Rlp};
use triedb::merkle::{MerkleNode, MerkleValue};

use anyhow::{anyhow, Result};
use log::*;

use super::inspectors::Inspector;

pub struct Walker<DB, T, I> {
    db: DB,
    pub inspector: I,
    _data: PhantomData<T>,
}

impl<DB, T, I> Walker<DB, T, I> {
    pub fn new(db: DB, inspector: I) -> Self {
        Self {
            db,
            inspector,
            _data: PhantomData,
        }
    }
}

impl<DB, T, I> Walker<DB, T, I>
where
    DB: Borrow<rocksdb::DB>,
    T: Decodable,
    I: Inspector<T>,
{
    pub fn traverse(&mut self, hash: H256) -> Result<()> {
        debug!("traversing {:?} ...", hash);
        if hash != triedb::empty_trie_hash() {
            let db = self.db.borrow();
            let bytes = db
                .get(hash)?
                .ok_or_else(|| anyhow!("hash {:?} not found in database"))?;
            trace!("raw bytes: {:?}", bytes);

            self.inspector.inspect_raw(hash, &bytes)?;

            let rlp = Rlp::new(bytes.as_slice());
            trace!("rlp: {:?}", rlp);
            let node = MerkleNode::decode(&rlp)?;
            debug!("node: {:?}", node);

            self.process_node(node)?;
        } else {
            debug!("skip empty trie");
        }

        Ok(())
    }

    fn process_node(&mut self, node: MerkleNode) -> Result<()> {
        match node {
            MerkleNode::Leaf(_nibbles, data) => {
                let rlp = Rlp::new(data);
                trace!("rlp: {:?}", rlp);
                let t = T::decode(&rlp)?;
                // TODO: debug T
                self.inspector.inspect_typed(&t)?;
                Ok(())
            }
            MerkleNode::Extension(_nibbles, value) => self.process_value(value),
            MerkleNode::Branch(values, mb_data) => {
                if let Some(data) = mb_data {
                    let rlp = Rlp::new(data);
                    trace!("rlp: {:?}", rlp);
                    let t = T::decode(&rlp)?;
                    // TODO: debug T
                    self.inspector.inspect_typed(&t)?;
                }
                for value in values {
                    self.process_value(value)?;
                }
                Ok(())
            }
        }
    }

    fn process_value(&mut self, value: MerkleValue) -> Result<()> {
        match value {
            MerkleValue::Empty => Ok(()),
            MerkleValue::Full(node) => self.process_node(*node),
            MerkleValue::Hash(hash) => self.traverse(hash),
        }
    }
}

extern crate icns;

use icns::{IconFamily, IconType, OSType};
use std::env::args;
use std::fs::File;
use std::io::{BufReader, BufWriter};
use std::process::exit;
use std::str::FromStr;

fn main() {

    // Read arguments
    let args: Vec<String> = args().collect();
    if args.len() != 3 {
        // Print program usage
        println!(r#"Usage:
    icnsutil <path to file.icns> <icon type>"#);
        exit(1);
    }

    // Read in ICNS and load icon family
    println!("[-] Reading input file \"{}\"...", args.get(1).unwrap());
    let file = BufReader::new(
        File::open(
            args.get(1).unwrap()
        ).unwrap()
    );
    let icon_family = IconFamily::read(file).unwrap();

    // Get icon type from string
    let icon_type = IconType::from_ostype(
        OSType::from_str(
            args.get(2).unwrap().as_str()
        ).unwrap()
    ).unwrap();

    // Extract PNG from icon family
    println!("[-] Extracting {:?} from icon family...", icon_type);
    let image = icon_family.get_icon_with_type(icon_type).unwrap();

    // Create output buffer
    println!("[-] Creating output buffer...");
    let output_filename = args.get(1).unwrap().replace(".icns", ".png");
    let output = BufWriter::new(
        File::create(&output_filename).unwrap()
    );

    // Write output PNG
    println!("[-] Writing output file \"{}\"...", &output_filename);
    image.write_png(output).unwrap();

    println!("[+] Done!");
}

