#[derive(Debug, Default)]
pub struct CompositeSurfaceCacheSystemCache {
    cached_surfaces: HashMap<Entity, String>,
}

pub type CompositeSurfaceCacheSystemResources<'a, CR> = (
    WorldRef,
    &'a mut CR,
    &'a EntityChanges,
    &'a mut CompositeSurfaceCacheSystemCache,
    Comp<&'a mut CompositeSurfaceCache>,
    Comp<&'a mut CompositeRenderable>,
);

pub fn composite_surface_cache_system<CR>(universe: &mut Universe)
where
    CR: CompositeRenderer + 'static,
{
    let (world, mut renderer, changes, mut cache, ..) =
        universe.query_resources::<CompositeSurfaceCacheSystemResources<CR>>();

    for entity in changes.despawned() {
        if let Some(name) = cache.cached_surfaces.remove(&entity) {
            renderer.destroy_surface(&name);
        }
    }

    for (entity, (surface, renderable)) in world
        .query::<(&mut CompositeSurfaceCache, &mut CompositeRenderable)>()
        .iter()
    {
        if surface.dirty {
            surface.dirty = false;
            if !renderer.has_surface(surface.name()) {
                renderer.create_surface(surface.name(), surface.width(), surface.height());
                cache
                    .cached_surfaces
                    .insert(entity, surface.name().to_owned());
            } else if let Some((width, height)) = renderer.get_surface_size(surface.name()) {
                if width != surface.width() || height != surface.height() {
                    renderer.destroy_surface(surface.name());
                    renderer.create_surface(surface.name(), surface.width(), surface.height());
                    cache
                        .cached_surfaces
                        .insert(entity, surface.name().to_owned());
                }
            }
            let commands = vec![
                Command::Store,
                Command::Draw(renderable.0.clone()),
                Command::Restore,
            ];
            if renderer.update_surface(surface.name(), commands).is_ok() {
                renderable.0 = Image {
                    image: surface.name().to_owned().into(),
                    source: None,
                    destination: None,
                    alignment: 0.0.into(),
                }
                .into();
            }
        }
    }
}

use super::*;

#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct DocumentBuilder {
    jsonapi: Option<JsonApiBuilder>,
    meta: Option<MetaOrAttrsBuilder>,
    links: Option<LinksBuilder>,
    data: Option<DataBuilder>,
}

impl Builder for DocumentBuilder {
    type Entity = Document;

    fn finish(self) -> Result<Self::Entity, ()> {
        Ok(Self::Entity {
            jsonapi: match self.jsonapi {
                None => None,
                Some(jsonapi) => Some(jsonapi.finish()?),
            },
            meta: match self.meta {
                None => None,
                Some(meta) => Some(meta.finish()?),
            },
            links: match self.links {
                None => None,
                Some(links) => Some(links.finish()?),
            },
            data: match self.data {
                None => None,
                Some(data) => Some(data.finish()?),
            },
        })
    }
}

impl DocumentBuilder {
    pub fn jsonapi<J: Into<JsonApiBuilder>>(self, jsonapi: J) -> Self {
        Self {
            jsonapi: Some(jsonapi.into()),
            ..self
        }
    }

    pub fn meta<M: Into<MetaOrAttrsBuilder>>(self, meta: M) -> Self {
        Self {
            meta: Some(meta.into()),
            ..self
        }
    }

    pub fn links<L: Into<LinksBuilder>>(self, links: L) -> Self {
        Self {
            links: Some(links.into()),
            ..self
        }
    }

    pub fn data<D: Into<DataBuilder>>(self, data: D) -> Self {
        Self {
            data: Some(data.into()),
            ..self
        }
    }

    pub fn meta1<N: ToString, V: Into<Value>>(self, name: N, meta1: V) -> Self {
        let meta = self.meta.unwrap_or_default().item(name, meta1);

        Self {
            meta: Some(meta),
            ..self
        }
    }

    pub fn link<N: ToString, L: Into<LinkBuilder>>(
        self,
        name: N,
        link: L,
    ) -> Self {
        let links = self.links.unwrap_or_default().link(name, link);

        Self {
            links: Some(links),
            ..self
        }
    }
}

impl From<Document> for DocumentBuilder {
    fn from(document: Document) -> Self {
        Self {
            jsonapi: document.jsonapi.map(|jsonapi| jsonapi.into()),
            meta: document.meta.map(|meta| meta.into()),
            links: document.links.map(|links| links.into()),
            data: document.data.map(|data| data.into()),
        }
    }
}

