                    type_: "qwerties".into(),
                    id: None,
                    meta: None,
                    links: None,
                    attributes: None,
                    relationships: None,
                }])),
            },
        );
    }

    #[test]
    fn with_meta1_implicit() {
        assert_eq!(
            DocumentBuilder::default()
                .meta1("foo", 123)
                .meta1("bar", "car")
                .unwrap(),
            Document {
                jsonapi: None,
                meta: Some({
                    let mut meta = MetaOrAttrs::new();
                    meta.insert("foo".into(), Value::Number(123.into()));
                    meta.insert("bar".into(), Value::String("car".into()));
                    meta
                }),
                links: None,
                data: None,
            },
        );
    }

    #[test]
    fn with_link_implicit_from_str() {
        assert_eq!(
            DocumentBuilder::default()
                .link("self", "http://self.com")
                .link("foo", "http://foo.com")
                .unwrap(),
            Document {
                jsonapi: None,
                meta: None,
                links: Some(Links {
                    other: {
                        let mut other = HashMap::new();
                        other.insert(
                            "foo".into(),
                            Link::String("http://foo.com".into()),
                        );
                        other
                    },
                    self_: Some(Link::String("http://self.com".into())),
                    related: None,
                    first: None,
                    last: None,
                    prev: None,
                    next: None,
                }),
                data: None,
            },
        );
    }

    #[test]
    fn implicit_from_entity() {
        let document = Document {
            jsonapi: Some(JsonApi {
                version: Some(Version::new(456)),
                meta: Some(meta()),
            }),
            meta: Some(meta()),
            links: Some(Links {
                other: HashMap::new(),
                self_: Some(Link::String("http://self.com".into())),
                related: Some(Link::String("http://related.com".into())),
                first: None,
                last: None,
                prev: None,
                next: None,
            }),
            data: Some(Data::Single(Resource {
                type_: "qwerties".into(),
                id: Some("123".into()),
                meta: None,
                links: None,
                attributes: None,
                relationships: None,
            })),
        };

        let builder: DocumentBuilder = document.clone().into();

        assert_eq!(builder.unwrap(), document);
    }

    #[test]
    fn with_meta_implicit_from_entity() {
        assert_eq!(
            DocumentBuilder::default().meta(meta()).unwrap(),
            Document {
                jsonapi: None,
                meta: Some(meta()),
                links: None,
                data: None,
            },
        );
    }

    #[test]
    fn with_links_implicit_from_entity() {
        assert_eq!(
            DocumentBuilder::default().links(links()).unwrap(),
            Document {
                jsonapi: None,
                meta: None,
                links: Some(links()),
                data: None,
            },
        );
    }
}

//!
//! `Utils` module
//! 

use syn::{Expr, parse2};
use syn::parse::ParseStream;
use proc_macro2::{TokenStream, TokenTree};
use quote::ToTokens;

use super::chain::{UnitResult, Unit};
use super::GroupDeterminer;

///
/// Returns true if given stream can be parsed as `Expr`.
/// 
pub fn is_valid_expr(input: TokenStream) -> bool {
    syn::parse2::<Expr>(input).is_ok()
}

///
/// Returns true if expr is {...}.
///
pub fn is_block_expr(expr: &Expr) -> bool {
    match *expr {
        Expr::Block(_) => true,
        _ => false,
    }
}

///
/// Parses input `ParseStream` until one of provided `GroupDeterminer`'s check will be valid or it reaches end.
/// 
pub fn parse_until(input: ParseStream, group_determiners: &[GroupDeterminer]) -> UnitResult {
    let mut tokens = TokenStream::new();
    let mut next_group = None;

    while !input.is_empty() && {
        let possible_group = group_determiners
            .into_iter()
            .find(|group| group.check_input(&input));
        possible_group.is_none()
            || possible_group
                .map(|group| 
                    !group
                        .check_parsed(tokens.clone())
                )
                .unwrap_or(false)
            || {
                next_group = possible_group;
                false
            }
    } {
        let next: TokenTree = input.parse()?;
        next.to_tokens(&mut tokens);
    }

    //
    // Parses group determiner's tokens. (for ex. => -> |> etc.)
    //
    let _ = next_group.as_ref().and_then(|group| group.erase_input(input).ok());

    Ok(Unit {
        expr: parse2(tokens)?,
        next_group_type: next_group.and_then(GroupDeterminer::get_group_type),
    })
}

//! Module exposing a test [Scenario] type to write Domain [Command]s
//! test cases using the [given-then-when canvas](https://www.agilealliance.org/glossary/gwt/).

use std::{fmt::Debug, hash::Hash};

use crate::{command, event, event::Store, message, test, test::store::EventStoreExt};

/// A test scenario that can be used to test a [Command] [Handler][command::Handler]
/// using a [given-then-when canvas](https://www.agilealliance.org/glossary/gwt/) approach.
pub struct Scenario;

impl Scenario {
    /// Sets the precondition state of the system for the [Scenario], which
    /// is expressed by a list of Domain [Event]s in an Event-sourced system.
    #[must_use]
    pub fn given<Id, Evt>(self, events: Vec<event::Persisted<Id, Evt>>) -> ScenarioGiven<Id, Evt>
    where
        Evt: message::Message,
    {
        ScenarioGiven { given: events }
    }

    /// Specifies the [Command] to test in the [Scenario], in the peculiar case
    /// of having a clean system.
    ///
    /// This is a shortcut for:
    /// ```text
    /// Scenario::given(vec![]).when(...)
    /// ```
    #[must_use]
    pub fn when<Id, Evt, Cmd>(self, command: command::Envelope<Cmd>) -> ScenarioWhen<Id, Evt, Cmd>
    where
        Evt: message::Message,
        Cmd: message::Message,
    {
        ScenarioWhen {
            given: Vec::default(),
            when: command,
        }
    }
}

#[doc(hidden)]
pub struct ScenarioGiven<Id, Evt>
where
    Evt: message::Message,
{
    given: Vec<event::Persisted<Id, Evt>>,
}

impl<Id, Evt> ScenarioGiven<Id, Evt>
where
    Evt: message::Message,
{
    /// Specifies the [Command] to test in the [Scenario].
    #[must_use]
    pub fn when<Cmd>(self, command: command::Envelope<Cmd>) -> ScenarioWhen<Id, Evt, Cmd>
    where
        Cmd: message::Message,
    {
        ScenarioWhen {
            given: self.given,
            when: command,
        }
    }
}

#[doc(hidden)]
pub struct ScenarioWhen<Id, Evt, Cmd>
where
    Evt: message::Message,
    Cmd: message::Message,
{
    given: Vec<event::Persisted<Id, Evt>>,
    when: command::Envelope<Cmd>,
}

impl<Id, Evt, Cmd> ScenarioWhen<Id, Evt, Cmd>
where
    Evt: message::Message,
    Cmd: message::Message,
{
    /// Sets the expectation on the result of the [Scenario] to be positive
    /// and produce a specified list of Domain [Event]s.
    #[must_use]
    pub fn then(self, events: Vec<event::Persisted<Id, Evt>>) -> ScenarioThen<Id, Evt, Cmd> {
        ScenarioThen {
            given: self.given,
            when: self.when,
            case: ScenarioThenCase::Produces(events),
        }
    }

    /// Sets the expectation on the result of the [Scenario] to return an error.
    #[must_use]
    pub fn then_fails(self) -> ScenarioThen<Id, Evt, Cmd> {
        ScenarioThen {
            given: self.given,
            when: self.when,
            case: ScenarioThenCase::Fails,
        }
    }
}

enum ScenarioThenCase<Id, Evt>
where
    Evt: message::Message,
{
    Produces(Vec<event::Persisted<Id, Evt>>),
    Fails,
}

#[doc(hidden)]
pub struct ScenarioThen<Id, Evt, Cmd>
where
    Evt: message::Message,
    Cmd: message::Message,
{
    given: Vec<event::Persisted<Id, Evt>>,
    when: command::Envelope<Cmd>,
    case: ScenarioThenCase<Id, Evt>,
}

impl<Id, Evt, Cmd> ScenarioThen<Id, Evt, Cmd>
where
    Id: Clone + Eq + Hash + Send + Sync + Debug,
    Evt: message::Message + Clone + PartialEq + Send + Sync + Debug,
    Cmd: message::Message,
{
    /// Executes the whole [Scenario] by constructing a Command [Handler]
    /// with the provided closure function and running the specified assertions.
    ///
    /// # Panics
    ///
    /// The method panics if the assertion fails.
    pub async fn assert_on<F, H>(self, handler_factory: F)
    where
        F: Fn(test::store::Tracking<test::store::InMemory<Id, Evt>>) -> H,
        H: command::Handler<Cmd>,
    {
        let event_store = test::store::InMemory::<Id, Evt>::default();
        let tracking_event_store = event_store.clone().with_recorded_events_tracking();

        for event in self.given {
            event_store
                .append(
                    event.stream_id,
                    event::StreamVersionExpected::MustBe(event.version - 1),
                    vec![event.event],
                )
                .await
                .expect("domain event in 'given' should be inserted in the event store");
        }

        let handler = handler_factory(tracking_event_store.clone());
        let result = handler.handle(self.when).await;

        match self.case {
            ScenarioThenCase::Produces(events) => {
                let recorded_events = tracking_event_store.recorded_events();
                assert_eq!(events, recorded_events);
            }
            ScenarioThenCase::Fails => assert!(result.is_err()),
        };
    }
}

