            .ok_or(CommonError::UnauthorizedCaller)?;

        context
            .service_data()
            .get_entry("params")
            .set(params.clone());

        match params.as_str() {
            "apply_error" => Err(CommonError::malformed_arguments("Error!")),
            "apply_panic" => panic!("Aaaa!"),
            _ => Ok(()),
        }
    }
}

