impl<'a, Connect> Display for &'a CellDisplay<Connect>
where
    &'a Connect: Connection,
{
    #[inline]
    fn wait(&mut self) -> crate::Result {
        self.lock_internal_immutable();

        let res = input::wait(self, &mut self.connection.as_ref().expect("Poisoned!"));

        self.io_lock.set(false);
        res
    }

    #[inline]
    fn send_request_raw(&mut self, req: RequestInfo) -> crate::Result<u16> {
        self.lock_internal_immutable();

        let result =
            output::send_request(self, &mut self.connection.as_ref().expect("Poisoned!"), req);

        self.io_lock.set(false);
        result
    }
}

#[cfg(feature = "async")]
impl<'a, Connect> AsyncDisplay for &'a CellDisplay<Connect>
where
    &'a Connect: AsyncConnection + Unpin,
{
    #[inline]
    fn poll_wait(&mut self, ctx: &mut Context<'_>) -> Poll<crate::Result> {
        let data = self.inner.borrow_mut();
        let mut wait_buffer = self.wait_buffer.borrow_mut();
        let workarounders = &data.workarounders;
        let (bytes, fds) = match wait_buffer
            .get_or_insert_with(|| {
                // try to lock
                self.lock_internal_immutable();
                WaitBuffer::default()
            })
            .poll_wait(
                &mut self.connection.as_ref().unwrap(),
                move |seq| workarounders.contains(&seq),
                ctx,
            ) {
            Poll::Pending => return Poll::Pending,
            Poll::Ready(res) => {
                drop(wait_buffer);
                self.wait_buffer.borrow_mut().take();
                self.io_lock.set(false);
                match res {
                    Ok(WaitBufferReturn { data, fds }) => (data, fds),
                    Err(e) => return Poll::Ready(Err(e)),
                }
            }
        };

        Poll::Ready(input::process_bytes(self, bytes, fds))
    }

    #[inline]
    fn begin_send_request_raw(
        &mut self,
        req: RequestInfo,
        _cx: &mut Context<'_>,
    ) -> PollOr<(), RequestInfo> {
        if self.try_lock_internal_immutable() {
            self.send_buffer.borrow_mut().fill_hole(req);
            PollOr::Ready(())
        } else {
            PollOr::Pending(req)
        }
    }

    #[inline]
    fn poll_send_request_raw(&mut self, cx: &mut Context<'_>) -> Poll<crate::Result<u16>> {
        let mut sbslot = self.send_buffer.borrow_mut();
        let mut send_buffer = mem::replace(&mut *sbslot, SendBuffer::OccupiedHole);
        let res = send_buffer.poll_send_request(
            self,
            &mut self.connection.as_ref().expect("Poisoned!"),
            cx,
        );
        *sbslot = send_buffer;
        if res.is_ready() {
            sbslot.dig_hole();
            self.io_lock.set(false);
        }
        match res {
            Poll::Ready(Ok(pr)) => Poll::Ready(Ok(output::finish_request(self, pr))),
            Poll::Ready(Err(e)) => Poll::Ready(Err(e)),
            Poll::Pending => Poll::Pending,
        }
    }
}

//! These tests should be run with `cargo test -- --test-threads 1 --nocapture`
//! this is done so you can see the output and the output doesn't mess with the automatically generated test output

#![feature(test)]

#[macro_use] extern crate aver;


#[test]
fn single_arg() {
  log_info!("this is a single arguement");
}

#[test]
fn multi_arg() {
  log_info!("these are ", "multiple ", "arguements");
}

#[test]
fn multi_type() {
  log_info!("does this have ", 3, " types? ", true);
}

#[test]
fn warning() {
  log_warn!("this is a warning that ", 3, " does not equal ", 4);
}

#[test]
fn error() {
  log_error!("this is an error!");
}

#[test]
fn fatal() {
  log_fatal!("this is an fatal!");
}

#[test]
fn should_not_print() {
  aver::set_log_level(aver::LogLevel::Fatal);
  log_error!("this should not print");
  aver::set_log_level(aver::LogLevel::Info);
}

#[test]
fn trace_and_debug_print() {
  aver::set_log_level(aver::LogLevel::All);
  log_trace!("this is a trace");
  log_debug!("this is a debug");
  aver::set_log_level(aver::LogLevel::Info);
}

#[test]
fn colors() {
  log!("\n"); // make it not print on the same line
  log!(aver::colors::grey(),    "grey ",    aver::colors::reset(), aver::colors::on_grey(),    "on grey",    aver::colors::reset(), "\n");
  log!(aver::colors::red(),     "red ",     aver::colors::reset(), aver::colors::on_red(),     "on red",     aver::colors::reset(), "\n");
  log!(aver::colors::yellow(),  "yellow ",  aver::colors::reset(), aver::colors::on_yellow(),  "on yellow",  aver::colors::reset(), "\n");
  log!(aver::colors::green(),   "green ",   aver::colors::reset(), aver::colors::on_green(),   "on green",   aver::colors::reset(), "\n");
  log!(aver::colors::cyan(),    "cyan ",    aver::colors::reset(), aver::colors::on_cyan(),    "on cyan",    aver::colors::reset(), "\n");
  log!(aver::colors::blue(),    "blue ",    aver::colors::reset(), aver::colors::on_blue(),    "on blue",    aver::colors::reset(), "\n");
  log!(aver::colors::magenta(), "magenta ", aver::colors::reset(), aver::colors::on_magenta(), "on magenta", aver::colors::reset(), "\n");
  log!(aver::colors::white(),   "white ",   aver::colors::reset(), aver::colors::on_white(),   "on white",   aver::colors::reset(), "\n");
  log!(aver::colors::red(), aver::colors::on_blue(), "red on blue ", aver::colors::reset(), "\n");
  log!(aver::colors::reset(),   "reset\n");
}

use crate::common::to_model;
use crate::error::into_c3p0_error;
use c3p0_common::json::Queries;
use c3p0_common::{C3p0Error, JsonCodec, Model};
use sqlx::query::Query;
use sqlx::{ColumnIndex, Database, Executor, IntoArguments};

pub trait ResultWithRowCount {
    fn rows_affected(&self) -> u64;
}

#[inline]
pub async fn batch_execute<'e, 'q: 'e, E, DB>(query: &'q str, executor: E) -> Result<(), C3p0Error>
where
    DB: Database,
    <DB as sqlx::database::HasArguments<'q>>::Arguments: sqlx::IntoArguments<'q, DB>,
    E: Executor<'e, Database = DB>,
{
    executor
        .execute(query)
        .await
        .map_err(into_c3p0_error)
        .map(|_| ())
}

#[inline]
pub async fn execute<'e, 'q: 'e, A, E, DB>(
    query: Query<'q, DB, A>,
    executor: E,
) -> Result<(), C3p0Error>
where
    DB: Database,
    A: 'q + IntoArguments<'q, DB>,
    E: Executor<'e, Database = DB>,
{
    query
        .execute(executor)
        .await
        .map_err(into_c3p0_error)
        .map(|_| ())
}

#[inline]
pub async fn fetch_one_optional_with_sql<'e, 'q: 'e, A, E, DB, DATA, CODEC: JsonCodec<DATA>>(
    query: Query<'q, DB, A>,
    executor: E,
    codec: &CODEC,
) -> Result<Option<Model<DATA>>, C3p0Error>
where
    DB: Database,
    A: 'q + IntoArguments<'q, DB>,
    E: Executor<'e, Database = DB>,
    DATA: Clone + serde::ser::Serialize + serde::de::DeserializeOwned + Send + Sync,
    for<'c> i32: sqlx::types::Type<DB> + sqlx::decode::Decode<'c, DB>,
    for<'c> i64: sqlx::types::Type<DB> + sqlx::decode::Decode<'c, DB>,
    for<'c> serde_json::value::Value: sqlx::types::Type<DB> + sqlx::decode::Decode<'c, DB>,
    usize: ColumnIndex<DB::Row>,
{
    query
        .fetch_optional(executor)
        .await
        .map_err(into_c3p0_error)?
        .map(|row| to_model(codec, &row, 0, 1, 2))
        .transpose()
}

#[inline]
