impl Solution {
    pub fn sorted_squares(nums: Vec<i32>) -> Vec<i32> {
        let n = nums.len();
        let mut left = 0;
        let mut right = n - 1;
        let mut result = vec![0_i32; n];
        let mut k = right;
        while left <= right {
            if nums[left].abs() < nums[right].abs() {
                result[k] = nums[right].pow(2);
                right -= 1;
            } else {
                result[k] =nums[left].pow( 2);
                left += 1;
            }
            if k > 0 {
                k -= 1;
            }
        }
        result
    }
}
