use rand::seq::SliceRandom;
use rand::thread_rng;
use std::time::Instant;
#[path = "../constants.rs"]
mod constants;



fn insertion_sort(vec: &mut Vec<i32>) {
    for index in 1..vec.len() {
        let mut j = index;
        while j > 0 && vec[j - 1] > vec[j] {
            vec.swap(j - 1, j);
            j -= 1;
        }
    }
}


fn main() {
    let mut rng = thread_rng();
    let mut int_vec = Vec::new();
    let max_num = constants::SIZE_OF_SORT_ARRAY;

    for num in 1..max_num {
        int_vec.push(num as i32);
    }

    let mut total_elapsed = 0;
    println!("Running {} times", constants::NUMBER_OF_RUNS);
    for i in 0..constants::NUMBER_OF_RUNS {
        int_vec.shuffle(&mut rng);
        let start = Instant::now();
        println!("{} run", i);

        insertion_sort(&mut int_vec);

        let elapsed = start.elapsed().as_micros();
        total_elapsed += elapsed;
    }
    let elapsed = total_elapsed / constants::NUMBER_OF_RUNS as u128;
    println!(
        "It took: {}.{} milliseconds in average to sort",
        elapsed / 1000,
        elapsed % 1000
    );
}

use std::fmt::Debug;
use std::hash::Hash;
use std::mem::size_of;

pub trait LFSRTrait: PartialEq + Eq + Clone + Hash + Debug {
    fn clock(&mut self) -> usize;
    fn multiclock(&mut self, clocks: usize) -> Vec<usize>;
    fn get(&self) -> Vec<usize>;
    fn set(&mut self, value: Vec<usize>);
    fn taps(&self) -> Vec<usize>;
    fn width(&self) -> usize;
}

fn width_in_usize_words(width: usize) -> usize {
    let usize_bytes = size_of::<usize>();
    let usize_bits = usize_bytes * 8;
    (width + usize_bits - 1) / usize_bits
}

fn calculate_tapmasks(width: usize, taps: Vec<usize>) -> Result<Vec<usize>, String> {
    let usize_bytes = size_of::<usize>();
    let usize_bits = usize_bytes * 8;
    let words = width_in_usize_words(width);

    let mut tapmasks = Vec::with_capacity(words);
    for _ in 0..words {
        tapmasks.push(0);
    }

    for tap in taps {
        if tap > width {
            return Err(format!("Tap {} was outside of register width {}.", tap, width));
        }
        tapmasks[(tap - 1) / usize_bits] |= (1 as usize) << (tap - 1);
    }
    Ok(tapmasks)
}

