// This program isn't necessarily meant to serve as an example of how to use
// walkdir, but rather, is a good example of how a basic `find` utility can be
// written using walkdir in a way that is both correct and as fast as possible.
// This includes doing things like block buffering when not printing to a tty,
// and correctly writing file paths to stdout without allocating on Unix.
//
// Additionally, this program is useful for demonstrating all of walkdir's
// features. That is, when new functionality is added, some demonstration of
// it should be added to this program.
//
// Finally, this can be useful for ad hoc benchmarking. e.g., See the --timeit
// and --count flags.

use std::error::Error;
use std::ffi::OsStr;
use std::io::{self, Write};
use std::path::{Path, PathBuf};
use std::process;
use std::result;
use std::time::Instant;

use bstr::BString;
use walkdir::{Depth, WalkDir};

type Result<T> = result::Result<T, Box<dyn Error>>;

macro_rules! err {
    ($($tt:tt)*) => { Err(From::from(format!($($tt)*))) }
}

fn main() {
    if let Err(err) = try_main() {
        eprintln!("{}", err);
        process::exit(1);
    }
}

fn try_main() -> Result<()> {
    let args = Args::parse()?;
    let mut stderr = io::stderr();

    let start = Instant::now();
    if args.count {
        print_count(&args, io::stdout(), &mut stderr)?;
    } else if atty::is(atty::Stream::Stdout) {
        print_paths(&args, io::stdout(), &mut stderr)?;
    } else {
        print_paths(&args, io::BufWriter::new(io::stdout()), &mut stderr)?;
    }
    if args.timeit {
        let since = Instant::now().duration_since(start);
        writeln!(stderr, "duration: {:?}", since)?;
    }
    Ok(())
}

fn print_count<W1, W2>(args: &Args, mut stdout: W1, mut stderr: W2) -> Result<()>
where
    W1: io::Write,
    W2: io::Write,
{
    let mut count: u64 = 0;
    for dir in &args.dirs {
        for result in args.walkdir(dir) {
            match result {
                Ok(_) => count += 1,
                Err(err) => {
                    if !args.ignore_errors {
                        writeln!(stderr, "ERROR: {}", err)?;
                    }
                }
            }
        }
    }
    writeln!(stdout, "{}", count)?;
    Ok(())
}

fn print_paths<W1, W2>(args: &Args, mut stdout: W1, mut stderr: W2) -> Result<()>
where
    W1: io::Write,
    W2: io::Write,
{
    for dir in &args.dirs {
        if args.tree {
            print_paths_tree(&args, &mut stdout, &mut stderr, dir)?;
        } else {
            print_paths_flat(&args, &mut stdout, &mut stderr, dir)?;
        }
    }
    Ok(())
}

fn print_paths_flat<W1, W2>(args: &Args, mut stdout: W1, mut stderr: W2, dir: &Path) -> Result<()>
where
    W1: io::Write,
    W2: io::Write,
{
    for result in args.walkdir(dir) {
        let dent = match result {
            Ok(dent) => dent,
            Err(err) => {
                if !args.ignore_errors {
                    writeln!(stderr, "ERROR: {}", err)?;
                }
                continue;
            }
        };
        write_path(&mut stdout, dent.path())?;
        stdout.write_all(b"\n")?;
    }
    Ok(())
}

fn print_paths_tree<W1, W2>(args: &Args, mut stdout: W1, mut stderr: W2, dir: &Path) -> Result<()>
where
    W1: io::Write,
    W2: io::Write,
{
    for result in args.walkdir(dir) {
        let dent = match result {
            Ok(dent) => dent,
            Err(err) => {
                if !args.ignore_errors {
                    writeln!(stderr, "ERROR: {}", err)?;
                }
                continue;
            }
        };
        stdout.write_all("  ".repeat(dent.depth()).as_bytes())?;
        write_os_str(&mut stdout, dent.file_name())?;
        stdout.write_all(b"\n")?;
    }
    Ok(())
}

#[derive(Debug)]
struct Args {
    dirs: Vec<PathBuf>,
    follow_links: bool,
    min_depth: Option<Depth>,
    max_depth: Option<Depth>,
    max_open: Option<usize>,
    tree: bool,
    ignore_errors: bool,
    sort: bool,
    depth_first: bool,
    same_file_system: bool,
    timeit: bool,
    count: bool,
}

impl Args {
    fn parse() -> Result<Args> {
        use clap::{crate_authors, crate_version, App, Arg};

        let parsed = App::new("List files using walkdir")
            .author(crate_authors!())
            .version(crate_version!())
            .max_term_width(100)
            .arg(Arg::with_name("dirs").multiple(true))
            .arg(
                Arg::with_name("follow-links")
                    .long("follow-links")
                    .short("L")
                    .help("Follow symbolic links."),
            )
            .arg(
                Arg::with_name("min-depth")
                    .long("min-depth")
                    .takes_value(true)
                    .help("Only show entries at or above this depth."),
            )
            .arg(
                Arg::with_name("max-depth")
                    .long("max-depth")
                    .takes_value(true)
                    .help("Only show entries at or below this depth."),
            )
            .arg(
                Arg::with_name("max-open")
                    .long("max-open")
                    .takes_value(true)
                    .default_value("10")
                    .help("Use at most this many open file descriptors."),
            )
            .arg(Arg::with_name("tree").long("tree").help("Show file paths in a tree."))
            .arg(
                Arg::with_name("ignore-errors")
                    .long("ignore-errors")
                    .short("q")
                    .help("Don't print error messages."),
            )
            .arg(Arg::with_name("sort").long("sort").help("Sort file paths lexicographically."))
            .arg(
                Arg::with_name("depth-first")
                    .long("depth-first")
                    .help("Show directory contents before the directory path."),
            )
            .arg(
                Arg::with_name("same-file-system")
                    .long("same-file-system")
                    .short("x")
                    .help("Only show paths on the same file system as the root."),
            )
            .arg(Arg::with_name("timeit").long("timeit").short("t").help("Print timing info."))
            .arg(
                Arg::with_name("count")
                    .long("count")
                    .short("c")
                    .help("Print only a total count of all file paths."),
            )
            .get_matches();

        let dirs = match parsed.values_of_os("dirs") {
            None => vec![PathBuf::from("./")],
            Some(dirs) => dirs.map(PathBuf::from).collect(),
        };
        Ok(Args {
            dirs,
            follow_links: parsed.is_present("follow-links"),
            min_depth: parse_usize(&parsed, "min-depth")?,
            max_depth: parse_usize(&parsed, "max-depth")?,
            max_open: parse_usize(&parsed, "max-open")?,
            tree: parsed.is_present("tree"),
            ignore_errors: parsed.is_present("ignore-errors"),
            sort: parsed.is_present("sort"),
            depth_first: parsed.is_present("depth-first"),
            same_file_system: parsed.is_present("same-file-system"),
            timeit: parsed.is_present("timeit"),
            count: parsed.is_present("count"),
        })
    }

    fn walkdir(&self, path: &Path) -> WalkDir {
        let mut walkdir = WalkDir::new(path)
            .follow_links(self.follow_links)
            .contents_first(self.depth_first)
            .same_file_system(self.same_file_system);
        if let Some(x) = self.min_depth {
            walkdir = walkdir.min_depth(x);
        }
        if let Some(x) = self.max_depth {
            walkdir = walkdir.max_depth(x);
        }
        if let Some(x) = self.max_open {
            walkdir = walkdir.max_open(x);
        }
        if self.sort {
            walkdir = walkdir.sort_by(|a, b| a.file_name().cmp(b.file_name()));
        }
        walkdir
    }
}

fn parse_usize(parsed: &clap::ArgMatches, flag: &str) -> Result<Option<usize>> {
    match parsed.value_of_lossy(flag) {
        None => Ok(None),
        Some(x) => {
            x.parse().map(Some).or_else(|e| err!("failed to parse --{} as a number: {}", flag, e))
        }
    }
}

fn write_path<W: io::Write>(wtr: W, path: &Path) -> io::Result<()> {
    write_os_str(wtr, path.as_os_str())
}

fn write_os_str<W: io::Write>(mut wtr: W, os: &OsStr) -> io::Result<()> {
    // On Unix, this is a no-op, and correctly prints raw paths. On Windows,
    // this lossily converts paths that originally contained invalid UTF-16
    // to paths that will ultimately contain only valid UTF-16. This doesn't
    // correctly print all possible paths, but on Windows, one can't print
    // invalid UTF-16 to a console anyway.
    wtr.write_all(BString::from_os_str_lossy(os).as_bytes())
}

use hyper::header::{CONTENT_TYPE, HOST};
use hyper::{Body, Request, Response, StatusCode};

use regex::Regex;

use serde_json::json;

use crate::errors::Result;
use crate::tiles::{get_data, get_tile_data};
use crate::utils::{decode, get_blank_image, get_data_format, DataFormat};

lazy_static! {
  static ref TILE_URL_RE: Regex = Regex::new(
    r"^/(?P<tile_path>.*)/tiles/(?P<z>\d+)/(?P<x>\d+)/(?P<y>\d+)\.(?P<format>[a-zA-Z]+)"
  )
  .unwrap();
  static ref META_URL_RE: Regex = Regex::new(r"^/(?P<tile_path>.*)/tiles.json").unwrap();
}

#[allow(dead_code)]
static INTERNAL_SERVER_ERROR: &[u8] = b"Internal Server Error";
static NOT_FOUND: &[u8] = b"Not Found";
static NO_CONTENT: &[u8] = b"";

fn not_found() -> Response<Body> {
  Response::builder()
    .status(StatusCode::NOT_FOUND)
    .body(NOT_FOUND.into())
    .unwrap()
}

fn no_content() -> Response<Body> {
  Response::builder()
    .status(StatusCode::NO_CONTENT)
    .body(NO_CONTENT.into())
    .unwrap()
}

#[allow(dead_code)]
fn server_error() -> Response<Body> {
  Response::builder()
    .status(StatusCode::INTERNAL_SERVER_ERROR)
    .body(INTERNAL_SERVER_ERROR.into())
    .unwrap()
}

fn get_host(req: &Request<Body>) -> Option<&str> {
  let host = req.uri().host();
  if host.is_some() {
    return host;
  }

  if let Some(host) = req.headers().get(HOST) {
    return Some(host.to_str().unwrap());
  }

  None
}

pub async fn get_service(request: Request<Body>) -> Result<Response<Body>> {
  let uri = request.uri();
  let path = uri.path();
  // println!("get_service {}", path);

  match TILE_URL_RE.captures(path) {
    Some(matches) => {
      let tile_path = matches.name("tile_path").unwrap().as_str().to_string();
      let tile_meta = get_data(&tile_path).unwrap();
      let z = matches.name("z").unwrap().as_str().parse::<u32>().unwrap();
      let x = matches.name("x").unwrap().as_str().parse::<u32>().unwrap();
      let y = matches.name("y").unwrap().as_str().parse::<u32>().unwrap();
      let y: u32 = (1 << z) - 1 - y;
      let data_format = matches.name("format").unwrap().as_str();
      // For future use
      let _query_string = match matches.name("query") {
        Some(q) => q.as_str(),
        None => "",
      };

      let response = Response::builder();

      return match data_format {
        "pbf" => match get_tile_data(&tile_meta.connection_pool.get().unwrap(), z, x, y) {
          Ok(data) => {
            let data_in_format = get_data_format(&data);
            return Ok(
              response
                .header(CONTENT_TYPE, DataFormat::Pbf.content_type())
                // .header("Cache-Control", "no-cache")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(decode(data, data_in_format).unwrap()))
                .unwrap(),
            );
          }
          Err(_) => Ok(no_content()),
        },
        _ => {
          let data = match get_tile_data(&tile_meta.connection_pool.get().unwrap(), z, x, y) {
            Ok(data) => data,
            Err(_) => get_blank_image(),
          };
          Ok(
            response
              .header(CONTENT_TYPE, DataFormat::new(data_format).content_type())
              // .header("Cache-Control", "no-cache")
              .header("Access-Control-Allow-Origin", "*")
              .body(Body::from(data))
              .unwrap(),
          )
        }
      };
    }
    None => {
      return match META_URL_RE.captures(path) {
        Some(matches) => {
          let host = get_host(&request).unwrap();
          let tile_path = matches.name("tile_path").unwrap().as_str();
          let tile_meta = get_data(&tile_path.to_string()).unwrap();
          let mut tile_meta_json = json!({
              "name":  if tile_meta.name.is_some() { tile_meta.name.clone() } else { Some(tile_meta.id.clone()) } ,
              "version": tile_meta.version,
              "tiles": vec![format!(
                  "http://{}/{}/tiles/{{z}}/{{x}}/{{y}}.{}",
                  host,
                  tile_path,
                  tile_meta.tile_format.format(),
              )],
              "tilejson": tile_meta.tilejson,
              "scheme": tile_meta.scheme,
              "id": tile_path.clone(),
              "format": tile_meta.tile_format,
              "bounds": tile_meta.bounds,
              "center": tile_meta.center,
              "minzoom": tile_meta.minzoom,
              "maxzoom": tile_meta.maxzoom,
              "description": tile_meta.description,
              "attribution": tile_meta.attribution,
              "type": tile_meta.layer_type,
              "legend": tile_meta.legend,
              "template": tile_meta.template,
          });
          if let Some(json_data) = &tile_meta.json {
            for (k, v) in json_data.as_object().unwrap() {
              tile_meta_json[k] = v.clone();
            }
          }

          return Ok(
            Response::builder()
              .header(CONTENT_TYPE, "application/json")
              .header("Access-Control-Allow-Origin", "*")
              .body(Body::from(serde_json::to_string(&tile_meta_json).unwrap()))
              .unwrap(),
          ); // TODO handle error
             // } else if path == "/reload" {
             // if allow_reload_api {
             // tilesets.reload();
             // return Ok(no_content());
             // } else {
             // return Ok(forbidden());
             // }
             // }
        }
        None => Ok(not_found()),
      };
    }
  };
}

