use middle::def_id::DefId;
use rustc_front::hir;
use rustc_front::util::IdVisitor;
use syntax::ast_util::{IdRange, IdRangeComputingVisitor, IdVisitingOperation};
use syntax::ptr::P;
use rustc_front::visit::Visitor;
use self::InlinedItem::*;

/// The data we save and restore about an inlined item or method.  This is not
/// part of the AST that we parse from a file, but it becomes part of the tree
/// that we trans.
#[derive(Clone, PartialEq, Eq, RustcEncodable, RustcDecodable, Hash, Debug)]
pub enum InlinedItem {
    Item(P<hir::Item>),
    TraitItem(DefId /* impl id */, P<hir::TraitItem>),
    ImplItem(DefId /* impl id */, P<hir::ImplItem>),
    Foreign(P<hir::ForeignItem>),
}

/// A borrowed version of `hir::InlinedItem`.
pub enum InlinedItemRef<'a> {
    Item(&'a hir::Item),
    TraitItem(DefId, &'a hir::TraitItem),
    ImplItem(DefId, &'a hir::ImplItem),
    Foreign(&'a hir::ForeignItem)
}

impl InlinedItem {
    pub fn visit<'ast,V>(&'ast self, visitor: &mut V)
        where V: Visitor<'ast>
    {
        match *self {
            Item(ref i) => visitor.visit_item(&**i),
            Foreign(ref i) => visitor.visit_foreign_item(&**i),
            TraitItem(_, ref ti) => visitor.visit_trait_item(ti),
            ImplItem(_, ref ii) => visitor.visit_impl_item(ii),
        }
    }

    pub fn visit_ids<O: IdVisitingOperation>(&self, operation: &mut O) {
        let mut id_visitor = IdVisitor {
            operation: operation,
            pass_through_items: true,
            visited_outermost: false,
        };
        self.visit(&mut id_visitor);
    }

    pub fn compute_id_range(&self) -> IdRange {
        let mut visitor = IdRangeComputingVisitor::new();
        self.visit_ids(&mut visitor);
        visitor.result()
    }
}

mod option {
    use super::recap::Ticket;
    use std::collections::HashMap;

    struct TicketStore {
        data: HashMap<u32, Ticket>,
    }

    impl TicketStore {
        pub fn new() -> TicketStore {
            TicketStore {
                data: HashMap::new(),
            }
        }

        pub fn save(&mut self, ticket: Ticket, id: u32) {
            self.data.insert(id, ticket);
        }

        /// Trying to implement `get` in the previous koan might have caused you
        /// some issues due to a signature mismatch: `get` on a HashMap returns
        /// an `Option<&Ticket>`, not a `&Ticket`.
        ///
        /// What is an Option?
        ///
        /// In a nutshell, Rust does not have `null`: if a function returns a
        /// `Ticket` there is no way for that `Ticket` not to be there.
        /// If there is indeed the possibility of the function not being able to
        /// return a `Ticket`, we need to express it in its return type.
        /// That's where `Option` comes in (`Option` as in `Option`al, or at
        /// least that how I think about it).
        /// `Option` is an enum:
        ///
        /// ```
        /// enum Option<T> {
        ///     Some(T),
        ///     None
        /// }
        /// ```
        /// `T` is a generic type parameter here: as we saw for HashMap, Rust
        /// allows you to be generic over the types in your container.
        /// The `None` variant means that the value is missing.
        /// The `Some` variant instead tells you that you have a value.
        ///
        /// There is no way you can use the value in an `Option` without first
        /// checking the variant, hence it is impossible to "forget" to handle
        /// `None` when writing code.
        /// The compiler obliges you to handle both the happy and the unhappy
        /// case.
        ///
        /// For more details on `Option`, there is an exhaustive introduction in
        /// the Rust book:
        /// https://doc.rust-lang.org/1.29.0/book/2018-edition/ch06-01-defining-an-enum.html#the-option-enum-and-its-advantages-over-null-values
        pub fn get(&self, id: &u32) -> Option<&Ticket> {
            self.data.get(id)
        }
    }

    #[cfg(test)]
    mod tests {
        use super::super::recap::{create_ticket, Status};
        use super::*;
        use fake::{Fake, Faker};

        #[test]
        fn a_ticket_with_a_home() {
            let ticket = generate_ticket(Status::ToDo);
            let mut store = TicketStore::new();
            let ticket_id = Faker.fake();

            store.save(ticket.clone(), ticket_id);

            // Notice that, even when a ticket with the specified id exists in
            // the store, it's returned as the `Some` variant of an
            // `Option<&Ticket>`.
            assert_eq!(store.get(&ticket_id), Some(&ticket));
        }

        /// We want our `get` method to return `None` now, instead of panicking
        /// when looking for
        /// an id to which there is no ticket associated.
        #[test]
        fn a_missing_ticket() {
            let ticket_store = TicketStore::new();
            let ticket_id = Faker.fake();

            assert_eq!(ticket_store.get(&ticket_id), None);
        }

        #[test]
        fn inserting_a_ticket_with_an_existing_id_overwrites_previous_ticket() {
            let first_ticket = generate_ticket(Status::ToDo);
            let second_ticket = generate_ticket(Status::ToDo);
            let mut store = TicketStore::new();
            let ticket_id = Faker.fake();

            store.save(first_ticket.clone(), ticket_id);
            assert_eq!(store.get(&ticket_id), Some(&first_ticket));

            store.save(second_ticket.clone(), ticket_id);
            assert_eq!(store.get(&ticket_id), Some(&second_ticket));
        }

        fn generate_ticket(status: Status) -> Ticket {
            let description = (0..3000).fake();
            let title = (1..50).fake();

            create_ticket(title, description, status)
        }
    }
}

use ::color::Color;

/// Sort neighboring colors in the image to be neighbors in the palette as well.
///
/// Fairly silly and useless, but makes the palette (especially of ordered dithered images)
/// look a lot more tidy.
pub fn sort_palette(palette: &Vec<Color>, image: &Vec<u8>) -> (Vec<Color>, Vec<u8>) {
    let num_colors = palette.len();
    let mut counts: Vec<usize> = (0..num_colors).map(|_| 0).collect();
    let mut neighbors: Vec<Vec<usize>> =
        (0..num_colors).map(|_| (0..num_colors).map(|_| 0).collect()).collect();
    let mut last_index = 0;
    for &index in image {
        let index = index as usize;
        counts[index] += 1;
        neighbors[last_index][index] += 1;
        neighbors[index][last_index] += 1;
        last_index = index;
    }
    let mut mapping = Vec::new();
    let mut best_index = 0;
    let mut best_count = 0;
    for (index, &count) in counts.iter().enumerate() {
        if count > best_count {
            best_index = index;
            best_count = count;
        }
    }
    mapping.push(best_index);
    let mut available: Vec<usize> = (0..num_colors).filter(|&i| i != best_index).collect();
    let mut prev_index = best_index;
    while available.len() > 0 {
        let mut best_index = available[0];
        let mut best_count = 0;
        for &index in &available {
            let count = neighbors[prev_index][index];
            if count > best_count {
                best_index = index;
                best_count = count;
            }
        }
        available.retain(|&i| i != best_index);
        mapping.push(best_index);
        prev_index = best_index;
    }
    let new_palette: Vec<Color> = mapping.iter().map(|&i| palette[i]).collect();
    let mut reverse_mapping: Vec<u8> = (0..palette.len()).map(|_| 0).collect();
    for (a, &b) in mapping.iter().enumerate() {
        reverse_mapping[b] = a as u8;
    }
    let new_image = image.iter().map(|&i| reverse_mapping[i as usize]).collect();
    (new_palette, new_image)
}

use std::sync::Arc;

use crate::{
    array::{Array, MutableArray},
    bitmap::MutableBitmap,
    datatypes::DataType,
    error::{ArrowError, Result},
};

use super::{FixedSizeBinaryArray, FixedSizeBinaryValues};

/// The Arrow's equivalent to a mutable `Vec<Option<[u8; size]>>`.
/// Converting a [`MutableFixedSizeBinaryArray`] into a [`FixedSizeBinaryArray`] is `O(1)`.
/// # Implementation
/// This struct does not allocate a validity until one is required (i.e. push a null to it).
#[derive(Debug)]
pub struct MutableFixedSizeBinaryArray {
    data_type: DataType,
    size: usize,
    values: Vec<u8>,
    validity: Option<MutableBitmap>,
}

impl From<MutableFixedSizeBinaryArray> for FixedSizeBinaryArray {
    fn from(other: MutableFixedSizeBinaryArray) -> Self {
        FixedSizeBinaryArray::new(
            other.data_type,
            other.values.into(),
            other.validity.map(|x| x.into()),
        )
    }
}

impl MutableFixedSizeBinaryArray {
    /// Canonical method to create a new [`MutableFixedSizeBinaryArray`].
    pub fn from_data(
        data_type: DataType,
        values: Vec<u8>,
        validity: Option<MutableBitmap>,
    ) -> Self {
        let size = FixedSizeBinaryArray::get_size(&data_type);
        assert_eq!(
            values.len() % size,
            0,
            "The len of values must be a multiple of size"
        );
        if let Some(validity) = &validity {
            assert_eq!(
                validity.len(),
                values.len() / size,
                "The len of the validity must be equal to values / size"
            );
        }
        Self {
            data_type,
            size,
            values,
            validity,
        }
    }

    /// Creates a new empty [`MutableFixedSizeBinaryArray`].
    pub fn new(size: usize) -> Self {
        Self::with_capacity(size, 0)
    }

    /// Creates a new [`MutableFixedSizeBinaryArray`] with capacity for `capacity` entries.
    pub fn with_capacity(size: usize, capacity: usize) -> Self {
        Self::from_data(
            DataType::FixedSizeBinary(size),
            Vec::<u8>::with_capacity(capacity * size),
            None,
        )
    }

    /// tries to push a new entry to [`MutableFixedSizeBinaryArray`].
    /// # Error
    /// Errors iff the size of `value` is not equal to its own size.
    #[inline]
    pub fn try_push<P: AsRef<[u8]>>(&mut self, value: Option<P>) -> Result<()> {
        match value {
            Some(bytes) => {
                let bytes = bytes.as_ref();
                if self.size != bytes.len() {
                    return Err(ArrowError::InvalidArgumentError(
                        "FixedSizeBinaryArray requires every item to be of its length".to_string(),
                    ));
                }
                self.values.extend_from_slice(bytes);

                match &mut self.validity {
                    Some(validity) => validity.push(true),
                    None => {}
                }
            }
            None => {
                self.values.resize(self.values.len() + self.size, 0);
                match &mut self.validity {
                    Some(validity) => validity.push(false),
                    None => self.init_validity(),
                }
            }
        }
        Ok(())
    }

    /// pushes a new entry to [`MutableFixedSizeBinaryArray`].
    /// # Panics
    /// Panics iff the size of `value` is not equal to its own size.
    #[inline]
    pub fn push<P: AsRef<[u8]>>(&mut self, value: Option<P>) {
        self.try_push(value).unwrap()
    }

    /// Creates a new [`MutableFixedSizeBinaryArray`] from an iterator of values.
    /// # Errors
    /// Errors iff the size of any of the `value` is not equal to its own size.
    pub fn try_from_iter<P: AsRef<[u8]>, I: IntoIterator<Item = Option<P>>>(
        iter: I,
        size: usize,
    ) -> Result<Self> {
        let iterator = iter.into_iter();
        let (lower, _) = iterator.size_hint();
        let mut primitive = Self::with_capacity(size, lower);
        for item in iterator {
            primitive.try_push(item)?
        }
        Ok(primitive)
    }

    /// returns the (fixed) size of the [`MutableFixedSizeBinaryArray`].
    #[inline]
    pub fn size(&self) -> usize {
        self.size
    }

    fn init_validity(&mut self) {
        let mut validity = MutableBitmap::new();
        validity.extend_constant(self.len(), true);
        validity.set(self.len() - 1, false);
        self.validity = Some(validity)
    }

    /// Returns the element at index `i` as `&[u8]`
    #[inline]
    pub fn value(&self, i: usize) -> &[u8] {
        &self.values[i * self.size..(i + 1) * self.size]
    }

    /// Returns the element at index `i` as `&[u8]`
    /// # Safety
    /// Assumes that the `i < self.len`.
    #[inline]
    pub unsafe fn value_unchecked(&self, i: usize) -> &[u8] {
        std::slice::from_raw_parts(self.values.as_ptr().add(i * self.size), self.size)
    }

    /// Shrinks the capacity of the [`MutableFixedSizeBinaryArray`] to fit its current length.
    pub fn shrink_to_fit(&mut self) {
        self.values.shrink_to_fit();
        if let Some(validity) = &mut self.validity {
            validity.shrink_to_fit()
        }
    }
}

/// Accessors
impl MutableFixedSizeBinaryArray {
    /// Returns its values.
    pub fn values(&self) -> &Vec<u8> {
        &self.values
    }

    /// Returns a mutable slice of values.
    pub fn values_mut_slice(&mut self) -> &mut [u8] {
        self.values.as_mut_slice()
    }
}

impl MutableArray for MutableFixedSizeBinaryArray {
    fn len(&self) -> usize {
        self.values.len() / self.size
    }

    fn validity(&self) -> Option<&MutableBitmap> {
        self.validity.as_ref()
    }

    fn as_box(&mut self) -> Box<dyn Array> {
        Box::new(FixedSizeBinaryArray::new(
            DataType::FixedSizeBinary(self.size),
            std::mem::take(&mut self.values).into(),
            std::mem::take(&mut self.validity).map(|x| x.into()),
        ))
    }

    fn as_arc(&mut self) -> Arc<dyn Array> {
        Arc::new(FixedSizeBinaryArray::new(
            DataType::FixedSizeBinary(self.size),
            std::mem::take(&mut self.values).into(),
            std::mem::take(&mut self.validity).map(|x| x.into()),
        ))
    }

    fn data_type(&self) -> &DataType {
        &self.data_type
    }

    fn as_any(&self) -> &dyn std::any::Any {
        self
    }

    fn as_mut_any(&mut self) -> &mut dyn std::any::Any {
        self
    }

    fn push_null(&mut self) {
        self.values.resize(self.values.len() + self.size, 0);
    }

    fn shrink_to_fit(&mut self) {
        self.shrink_to_fit()
    }
}

impl FixedSizeBinaryValues for MutableFixedSizeBinaryArray {
    #[inline]
    fn values(&self) -> &[u8] {
        &self.values
    }

    #[inline]
    fn size(&self) -> usize {
        self.size
    }
}

impl PartialEq for MutableFixedSizeBinaryArray {
    fn eq(&self, other: &Self) -> bool {
        self.iter().eq(other.iter())
    }
}

