//! The inspect mod defines the [`InspectAgent`], which is responsible for logging
//! relevant service activity to Inspect. Since this activity might happen
//! before agent lifecycle states are communicated (due to agent priority
//! ordering), the [`InspectAgent`] begins listening to requests immediately
//! after creation.

use crate::agent::Context;
use crate::agent::Payload;
use crate::base::SettingType;
use crate::blueprint_definition;
use crate::clock;
use crate::handler::base::{Payload as HandlerPayload, Request};
use crate::handler::device_storage::DeviceStorageAccess;
use crate::message::base::{filter, MessageEvent, MessengerType};
use crate::service;
use crate::service::TryFromWithClient;

use fuchsia_async as fasync;
use fuchsia_inspect::{self as inspect, component, Property};
use fuchsia_inspect_derive::{Inspect, WithInspect};
use futures::StreamExt;

use std::collections::{HashMap, VecDeque};
use std::sync::Arc;

blueprint_definition!("inspect", crate::agent::inspect::InspectAgent::create);

const INSPECT_REQUESTS_COUNT: usize = 25;

/// Information about a setting to be written to inspect.
#[derive(Inspect)]
struct SettingTypeInfo {
    /// Map from the name of the Request variant to a RequestTypeInfo that holds a list of
    /// recent requests.
    #[inspect(skip)]
    requests_by_type: HashMap<String, RequestTypeInfo>,

    /// Incrementing count for all requests of this setting type.
    ///
    /// Count is used across all request types to easily see the order that requests occurred in.
    #[inspect(skip)]
    count: u64,

    /// Node of this info.
    inspect_node: inspect::Node,
}

impl SettingTypeInfo {
    fn new() -> Self {
        Self { count: 0, requests_by_type: HashMap::new(), inspect_node: inspect::Node::default() }
    }
}

/// Information for all requests of a particular SettingType variant for a given setting type.
#[derive(Inspect)]
struct RequestTypeInfo {
    /// Last requests for inspect to save. Number of requests is defined by INSPECT_REQUESTS_COUNT.
    #[inspect(skip)]
    last_requests: VecDeque<RequestInfo>,

    /// Node of this info.
    inspect_node: inspect::Node,
}

impl RequestTypeInfo {
    fn new() -> Self {
        Self {
            last_requests: VecDeque::with_capacity(INSPECT_REQUESTS_COUNT),
            inspect_node: inspect::Node::default(),
        }
    }
}

/// Information about a request to be written to inspect.
#[derive(Inspect)]
struct RequestInfo {
    /// Debug string representation of this Request.
    request: inspect::StringProperty,

    /// Milliseconds since creation that this request arrived.
    timestamp: inspect::StringProperty,

    /// Node of this info.
    inspect_node: inspect::Node,
}

impl RequestInfo {
    fn new() -> Self {
        Self {
            request: inspect::StringProperty::default(),
            timestamp: inspect::StringProperty::default(),
            inspect_node: inspect::Node::default(),
        }
    }
}

/// The InspectAgent is responsible for listening to requests to the setting
/// handlers and recording the requests to Inspect.
pub(crate) struct InspectAgent {
    inspect_node: inspect::Node,
    /// Last requests for inspect to save.
    last_requests: HashMap<SettingType, SettingTypeInfo>,
}

impl DeviceStorageAccess for InspectAgent {
    const STORAGE_KEYS: &'static [&'static str] = &[];
}

impl InspectAgent {
    async fn create(context: Context) {
        // TODO(fxbug.dev/71295): Rename child node as switchboard is no longer in use.
        Self::create_with_node(context, component::inspector().root().create_child("switchboard"))
            .await;
    }

    async fn create_with_node(context: Context, node: inspect::Node) {
        let (_, message_rx) = context
            .delegate
            .create(MessengerType::Broker(Some(filter::Builder::single(
                filter::Condition::Custom(Arc::new(move |message| {
                    // Only catch setting handler requests.
                    matches!(
                        message.payload(),
                        service::Payload::Setting(HandlerPayload::Request(_))
                    )
                })),
            ))))
            .await
            .expect("should receive client");

        let mut agent = InspectAgent { inspect_node: node, last_requests: HashMap::new() };

        fasync::Task::spawn(async move {
            let event = message_rx.fuse();
            let agent_event = context.receptor.fuse();
            futures::pin_mut!(agent_event, event);

            loop {
                futures::select! {
                    message_event = event.select_next_some() => {
                        agent.process_message_event(message_event);
                    },
                    agent_message = agent_event.select_next_some() => {
                        if let MessageEvent::Message(
                                service::Payload::Agent(Payload::Invocation(_invocation)), client)
                                = agent_message {
                            // Since the agent runs at creation, there is no
                            // need to handle state here.
                            client.reply(Payload::Complete(Ok(())).into()).send().ack();
                        }
                    },
                }
            }
        })
        .detach();
    }

    /// Identfies [`service::message::MessageEvent`] that contains a [`Request`]
    /// for setting handlers and records the [`Request`].
    fn process_message_event(&mut self, event: service::message::MessageEvent) {
        if let Ok((HandlerPayload::Request(request), client)) =
            HandlerPayload::try_from_with_client(event)
        {
            for target in client.get_audience().flatten() {
                if let service::message::Audience::Address(service::Address::Handler(
                    setting_type,
                )) = target
                {
                    self.record_request(setting_type, &request);
                }
            }
        }
    }

    /// Write a request to inspect.
    fn record_request(&mut self, setting_type: SettingType, request: &Request) {
        let inspect_node = &self.inspect_node;
        let setting_type_info = self.last_requests.entry(setting_type).or_insert_with(|| {
            SettingTypeInfo::new()
                .with_inspect(&inspect_node, format!("{:?}", setting_type))
                // `with_inspect` will only return an error on types with
                // interior mutability. Since none are used here, this should be
                // fine.
                .expect("failed to create SettingTypeInfo inspect node")
        });

        let key = request.for_inspect().to_string();
        let setting_type_inspect_node = &setting_type_info.inspect_node;
        let request_type_info =
            setting_type_info.requests_by_type.entry(key.clone()).or_insert_with(|| {
                // `with_inspect` will only return an error on types with
                // interior mutability. Since none are used here, this
                // should be fine.
                RequestTypeInfo::new()
                    .with_inspect(setting_type_inspect_node, key)
                    .expect("failed to create RequestTypeInfo inspect node")
            });

        let last_requests = &mut request_type_info.last_requests;
        if last_requests.len() >= INSPECT_REQUESTS_COUNT {
            last_requests.pop_back();
        }

        let count = setting_type_info.count;
        setting_type_info.count += 1;
        let timestamp = clock::inspect_format_now();
        // std::u64::MAX maxes out at 20 digits.
        let request_info = RequestInfo::new()
            .with_inspect(&request_type_info.inspect_node, format!("{:020}", count))
            .expect("failed to create RequestInfo inspect node");
        request_info.request.set(&format!("{:?}", request));
        request_info.timestamp.set(&timestamp);
        last_requests.push_front(request_info);
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::display::types::SetDisplayInfo;
    use crate::intl::types::{IntlInfo, LocaleId, TemperatureUnit};
    use crate::service;

    use fuchsia_inspect::assert_data_tree;
    use fuchsia_inspect::testing::{AnyProperty, TreeAssertion};
    use fuchsia_zircon::Time;
    use std::collections::HashSet;

    /// The `RequestProcessor` handles sending a request through a MessageHub
    /// From caller to recipient. This is useful when testing brokers in
    /// between.
    struct RequestProcessor {
        delegate: service::message::Delegate,
    }

    impl RequestProcessor {
        fn new(delegate: service::message::Delegate) -> Self {
            RequestProcessor { delegate }
        }

        async fn send_and_receive(&self, setting_type: SettingType, setting_request: Request) {
            let (messenger, _) =
                self.delegate.create(MessengerType::Unbound).await.expect("should be created");
            let (_, mut receptor) = self
                .delegate
                .create(MessengerType::Addressable(service::Address::Handler(setting_type)))
                .await
                .expect("should be created");

            messenger
                .message(
                    HandlerPayload::Request(setting_request).into(),
                    service::message::Audience::Address(service::Address::Handler(setting_type)),
                )
                .send()
                .ack();

            receptor.next_payload().await.ok();
        }
    }

    async fn create_context() -> Context {
        Context::new(
            service::message::create_hub()
                .create(MessengerType::Unbound)
                .await
                .expect("should be present")
                .1,
            service::message::create_hub(),
            HashSet::new(),
            HashSet::new(),
            None,
        )
        .await
    }

    #[fuchsia_async::run_until_stalled(test)]
    async fn test_inspect() {
        // Set the clock so that timestamps will always be 0.
        clock::mock::set(Time::from_nanos(0));

        let inspector = inspect::Inspector::new();
        let inspect_node = inspector.root().create_child("switchboard");
        let context = create_context().await;

        let request_processor = RequestProcessor::new(context.delegate.clone());

        InspectAgent::create_with_node(context, inspect_node).await;

        // Send a few requests to make sure they get written to inspect properly.
        let turn_off_auto_brightness = Request::SetDisplayInfo(SetDisplayInfo {
            auto_brightness: Some(false),
            ..SetDisplayInfo::default()
        });
        request_processor
            .send_and_receive(SettingType::Display, turn_off_auto_brightness.clone())
            .await;

        request_processor.send_and_receive(SettingType::Display, turn_off_auto_brightness).await;

        request_processor
            .send_and_receive(
                SettingType::Intl,
                Request::SetIntlInfo(IntlInfo {
                    locales: Some(vec![LocaleId { id: "en-US".to_string() }]),
                    temperature_unit: Some(TemperatureUnit::Celsius),
                    time_zone_id: Some("UTC".to_string()),
                    hour_cycle: None,
                }),
            )
            .await;

        assert_data_tree!(inspector, root: {
            switchboard: {
                "Display": {
                    "SetDisplayInfo": {
                        "00000000000000000000": {
                            request: "SetDisplayInfo(SetDisplayInfo { \
                                manual_brightness_value: None, \
                                auto_brightness_value: None, \
                                auto_brightness: Some(false), \
                                screen_enabled: None, \
                                low_light_mode: None, \
                                theme: None \
                            })",
                            timestamp: "0.000000000",
                        },
                        "00000000000000000001": {
                            request: "SetDisplayInfo(SetDisplayInfo { \
                                manual_brightness_value: None, \
                                auto_brightness_value: None, \
                                auto_brightness: Some(false), \
                                screen_enabled: None, \
                                low_light_mode: None, \
                                theme: None \
                            })",
                            timestamp: "0.000000000",
                        },
                    },
                },
                "Intl": {
                    "SetIntlInfo": {
                        "00000000000000000000": {
                            request: "SetIntlInfo(IntlInfo { \
                                locales: Some([LocaleId { id: \"en-US\" }]), \
                                temperature_unit: Some(Celsius), \
                                time_zone_id: Some(\"UTC\"), \
                                hour_cycle: None })",
                            timestamp: "0.000000000",
                        }
                    },
                }
            }
        });
    }

    #[fuchsia_async::run_until_stalled(test)]
    async fn test_inspect_mixed_request_types() {
        // Set the clock so that timestamps will always be 0.
        clock::mock::set(Time::from_nanos(0));

        let inspector = inspect::Inspector::new();
        let inspect_node = inspector.root().create_child("switchboard");
        let context = create_context().await;

        let request_processor = RequestProcessor::new(context.delegate.clone());

        let _agent = InspectAgent::create_with_node(context, inspect_node).await;

        // Interlace different request types to make sure the counter is correct.
        request_processor
            .send_and_receive(
                SettingType::Display,
                Request::SetDisplayInfo(SetDisplayInfo {
                    auto_brightness: Some(false),
                    ..SetDisplayInfo::default()
                }),
            )
            .await;

        request_processor.send_and_receive(SettingType::Display, Request::Get).await;

        request_processor
            .send_and_receive(
                SettingType::Display,
                Request::SetDisplayInfo(SetDisplayInfo {
                    auto_brightness: Some(true),
                    ..SetDisplayInfo::default()
                }),
            )
            .await;

        request_processor.send_and_receive(SettingType::Display, Request::Get).await;

        assert_data_tree!(inspector, root: {
            switchboard: {
                "Display": {
                    "SetDisplayInfo": {
                        "00000000000000000000": {
                            request: "SetDisplayInfo(SetDisplayInfo { \
                                manual_brightness_value: None, \
                                auto_brightness_value: None, \
                                auto_brightness: Some(false), \
                                screen_enabled: None, \
                                low_light_mode: None, \
                                theme: None \
                            })",
                            timestamp: "0.000000000",
                        },
                        "00000000000000000002": {
                            request: "SetDisplayInfo(SetDisplayInfo { \
                                manual_brightness_value: None, \
                                auto_brightness_value: None, \
                                auto_brightness: Some(true), \
                                screen_enabled: None, \
                                low_light_mode: None, \
                                theme: None \
                            })",
                            timestamp: "0.000000000",
                        },
                    },
                    "Get": {
                        "00000000000000000001": {
                            request: "Get",
                            timestamp: "0.000000000",
                        },
                        "00000000000000000003": {
                            request: "Get",
                            timestamp: "0.000000000",
                        },
                    },
                },
            }
        });
    }

    #[fuchsia_async::run_until_stalled(test)]
    async fn inspect_queue_test() {
        // Set the clock so that timestamps will always be 0.
        clock::mock::set(Time::from_nanos(0));
        let inspector = inspect::Inspector::new();
        let inspect_node = inspector.root().create_child("switchboard");
        let context = create_context().await;
        let request_processor = RequestProcessor::new(context.delegate.clone());

        let _agent = InspectAgent::create_with_node(context, inspect_node).await;

        request_processor
            .send_and_receive(
                SettingType::Intl,
                Request::SetIntlInfo(IntlInfo {
                    locales: Some(vec![LocaleId { id: "en-US".to_string() }]),
                    temperature_unit: Some(TemperatureUnit::Celsius),
                    time_zone_id: Some("UTC".to_string()),
                    hour_cycle: None,
                }),
            )
            .await;

        // Send one more than the max requests to make sure they get pushed off the end of the queue
        for _ in 0..INSPECT_REQUESTS_COUNT + 1 {
            request_processor
                .send_and_receive(
                    SettingType::Display,
                    Request::SetDisplayInfo(SetDisplayInfo {
                        auto_brightness: Some(false),
                        ..SetDisplayInfo::default()
                    }),
                )
                .await;
        }

        // Ensures we have INSPECT_REQUESTS_COUNT items and that the queue dropped the earliest one
        // when hitting the limit.
        fn display_subtree_assertion() -> TreeAssertion {
            let mut tree_assertion = TreeAssertion::new("Display", true);
            let mut request_assertion = TreeAssertion::new("SetDisplayInfo", true);

            for i in 1..INSPECT_REQUESTS_COUNT + 1 {
                request_assertion
                    .add_child_assertion(TreeAssertion::new(&format!("{:020}", i), false));
            }
            tree_assertion.add_child_assertion(request_assertion);
            tree_assertion
        }

        assert_data_tree!(inspector, root: {
            switchboard: {
                display_subtree_assertion(),
                "Intl": {
                    "SetIntlInfo": {
                        "00000000000000000000": {
                            request: AnyProperty,
                            timestamp: "0.000000000",
                        }
                    }
                }
            }
        });
    }
}

use std::{
    time::Duration,
    sync::atomic::{AtomicU64, Ordering},
};

struct Query {
    total_queries: AtomicU64,
    total_fail: AtomicU64,
    total_time: AtomicU64,
    fail_time: AtomicU64,
    min_sucess_time: AtomicU64,
    max_sucess_time: AtomicU64,
    min_fail_time: AtomicU64,
    max_fail_time: AtomicU64,
    data: AtomicU64,
}

pub enum FullNodeNetworkTelemetryKind {
    Client,
    Service
}

pub struct FullNodeNetworkTelemetry {
    queries: lockfree::map::Map<String, Query>,
    kind: FullNodeNetworkTelemetryKind,
}

impl FullNodeNetworkTelemetry {

    pub fn new(kind: FullNodeNetworkTelemetryKind) -> Self {
        FullNodeNetworkTelemetry {
            queries: lockfree::map::Map::default(),
            kind,
        }
    }

    pub fn consumed_query(
        &self,
        query: String,
        success: bool,
        time: Duration,
        data: usize,
    ) {
        let time = time.as_millis() as u64;
        adnl::common::add_object_to_map_with_update(
            &self.queries,
            query,
            |found| if let Some(found) = found {
                found.total_queries.fetch_add(1, Ordering::Relaxed);
                if !success {
                    found.total_fail.fetch_add(1, Ordering::Relaxed);
                    found.fail_time.fetch_add(time, Ordering::Relaxed);
                    found.min_fail_time.fetch_min(time, Ordering::Relaxed);
                    found.max_fail_time.fetch_max(time, Ordering::Relaxed);
                }
                found.total_time.fetch_add(time, Ordering::Relaxed);
                found.min_sucess_time.fetch_min(time, Ordering::Relaxed);
                found.max_sucess_time.fetch_max(time, Ordering::Relaxed);
                found.data.fetch_add(data as u64, Ordering::Relaxed);
                Ok(None)
            } else {
                let q = Query {
                    total_queries: AtomicU64::new(1),
                    total_fail: AtomicU64::new(if !success {1} else {0}),
                    total_time: AtomicU64::new(time),
                    fail_time: AtomicU64::new(if !success {time} else {0}),
                    min_sucess_time: AtomicU64::new(time),
                    max_sucess_time: AtomicU64::new(time),
                    min_fail_time: AtomicU64::new(if !success {time} else {u64::MAX}),
                    max_fail_time: AtomicU64::new(if !success {time} else {0}),
                    data: AtomicU64::new(data as u64),
                };
                Ok(Some(q))
            }
        ).expect("Can't return error");
    }

    pub fn report(&self, update_period_sec: u64) -> String {
        let mut report = string_builder::Builder::default();
        let mut total_data = 0;
        let prefix = match self.kind {
            FullNodeNetworkTelemetryKind::Client => "↓", // "download"
            FullNodeNetworkTelemetryKind::Service => "↑", // "upload"
        };
        report.append(
            "                                   query       total       bytes  succeded   time: min   avg   max    failed    time: min   avg   max");
        for query in self.queries.iter() {

            let total_queries = query.val().total_queries.load(Ordering::Relaxed);
            if total_queries == 0 {
                report.append(format!("{} no one query", query.key())); // unexpected
                continue;
            }

            let total_fail = query.val().total_fail.load(Ordering::Relaxed);
            let total_time = query.val().total_time.load(Ordering::Relaxed);
            let fail_time = query.val().fail_time.load(Ordering::Relaxed);
            let min_sucess_time = query.val().min_sucess_time.load(Ordering::Relaxed);
            let max_sucess_time = query.val().max_sucess_time.load(Ordering::Relaxed);
            let min_fail_time = query.val().min_fail_time.load(Ordering::Relaxed);
            let max_fail_time = query.val().max_fail_time.load(Ordering::Relaxed);
            let data = query.val().data.load(Ordering::Relaxed);
            let total_succedded = total_queries - total_fail;
            let sucess_time = total_time - fail_time;
            total_data += data;

            if query.key().len() <= 39 {
                report.append(format!("\n{}{:>39}", prefix, query.key()));
            } else {
                report.append(format!(
                    "\n{}{}..{}",
                    prefix,
                    query.key().get(..7).unwrap_or_default(),
                    query.key().get(query.key().len() - 30..).unwrap_or_default(),
                ));
            }

            report.append(format!("  {:>10}  {:>10}", total_queries, data));
            if total_succedded > 0 {
                report.append(format!("{:>10}({:>3.0}%){:>6}{:>6}{:>6}",
                    total_succedded,
                    total_succedded as f64 / total_queries as f64 * 100_f64,
                    min_sucess_time,
                    if total_succedded > 0 { sucess_time / total_succedded } else { 0 },
                    max_sucess_time,
                ));
            } else {
                report.append("         0                        ");
            }
            if total_fail > 0 {
                report.append(format!("{:>10}({:>3.0}%) {:>6}{:>6}{:>6}", 
                    total_fail,
                    total_fail as f64 / total_queries as f64 * 100_f64,
                    min_fail_time,
                    if total_fail > 0 { fail_time / total_fail } else { 0 },
                    max_fail_time,
                ));
            } else {
                report.append("         0");
            }
            self.queries.remove(query.key());
        }
        report.append(format!("\nTotal: {} bytes", total_data));
        if update_period_sec != 0 {
            report.append(format!(", {} bytes/secons", total_data / update_period_sec));
        }

        report.string().expect("unexpected error while building full node service's telemetry report")
    }
}

use serde::Deserialize;
use wasm_bindgen::prelude::*;

#[wasm_bindgen]
extern "C" {
    #[wasm_bindgen(js_namespace = console)]
    fn info(s: &str);
}

/// Intermediate representation between JSON string and `interp_core::syntax::Expr` enum
#[derive(Debug, Deserialize)]
struct JsonAst {
    _type: String,
    val: serde_json::Value,
}

/// The `exec()` function executes program written in JSON
#[wasm_bindgen]
pub fn exec(err: &js_sys::Function, json_str: &str) {
    let json_ast = serde_json::from_str::<JsonAst>(json_str).unwrap_or_else(|_| {
        err.call1(
            &JsValue::NULL,
            &js_sys::Error::new("failed to convert JSON string into JsonAst"),
        )
        .ok();
        panic!(); // FIXME: consider setting panic hook
    });

    info(format!("_type: {}", json_ast._type).as_str());
    info(format!("val: {}", json_ast.val).as_str());

    // TODO: convert JsonAst into interp_core::syntax::Expr and reduce it
}

//! The stm32h7xx-hal implementation of the CountDown trait uses Hertz
//! for the Time type with the result that it's duration is capped to
//! 1000ms.
//!
//! This alternate implementation uses Duration instead, allowing for
//! much longer periods.

use stm32h7xx_hal as hal;
use hal::hal as embedded_hal;
use hal::pac::{
    TIM1, TIM12, TIM13, TIM14, TIM15, TIM16, TIM17, TIM2, TIM3, TIM4, TIM5,
    TIM6, TIM7, TIM8,
};


// - CountDownTimer -----------------------------------------------------------

pub struct CountDownTimer<TIMX> {
    timer: hal::timer::Timer::<TIMX>,
}

impl<TIMX> CountDownTimer<TIMX> {
    pub fn new(timer: hal::timer::Timer::<TIMX>) -> Self {
        Self {
            timer: timer
        }
    }
}


// - embedded_hal::timer::CountDown -------------------------------------------

macro_rules! impl_countdown {
    ($($TIMX:ident: ($cntType:ty),)+) => {
        $(
            impl embedded_hal::timer::Periodic for CountDownTimer<$TIMX> {}

            impl embedded_hal::timer::CountDown for CountDownTimer<$TIMX> {
                type Time = core::time::Duration;

                // TODO check for invalid values by using `cntType`
                fn start<T>(&mut self, timeout: T)
                where
                    T: Into<core::time::Duration>,
                {
                    // Pause
                    self.timer.pause();

                    // Reset counter
                    self.timer.reset_counter();

                    // UEV event occours on next overflow
                    self.timer.urs_counter_only();
                    self.timer.clear_irq();

                    // Set PSC and ARR
                    self.timer.set_timeout(timeout);

                    // Generate an update event to force an update of the ARR register. This ensures
                    // the first timer cycle is of the specified duration.
                    self.timer.apply_freq();

                    // Start counter
                    self.timer.resume()
                }

                fn wait(&mut self) -> nb::Result<(), void::Void> {
                    if self.timer.is_irq_clear() {
                        Err(nb::Error::WouldBlock)
                    } else {
                        self.timer.clear_irq();
                        Ok(())
                    }
                }
            }
        )+
    }
}

impl_countdown! {
    // Advanced-control
    TIM1: (u16),
    TIM8: (u16),

    // General-purpose
    TIM2: (u32),
    TIM3: (u16),
    TIM4: (u16),
    TIM5: (u32),

    // Basic
    TIM6: (u16),
    TIM7: (u16),

    // General-purpose
    TIM12: (u16),
    TIM13: (u16),
    TIM14: (u16),

    // General-purpose
    TIM15: (u16),
    TIM16: (u16),
    TIM17: (u16),
}

use std::{
    cell::RefCell,
    convert::TryInto,
    io::{self, Write},
};

use git_features::zlib::stream::deflate;

use crate::Sink;

impl Sink {
    /// Enable or disable compression. Compression is disabled by default
    pub fn compress(mut self, enable: bool) -> Self {
        if enable {
            self.compressor = Some(RefCell::new(deflate::Write::new(io::sink())));
        } else {
            self.compressor = None;
        }
        self
    }
}

impl crate::traits::Write for Sink {
    type Error = io::Error;

    fn write_stream(
        &self,
        kind: git_object::Kind,
        size: u64,
        mut from: impl io::Read,
    ) -> Result<git_hash::ObjectId, Self::Error> {
        let mut size = size.try_into().expect("object size to fit into usize");
        use git_features::hash::Sha1;
        let mut buf = [0u8; 8096];
        let header = git_object::encode::loose_header(kind, size);

        let possibly_compress = |buf: &[u8]| -> io::Result<()> {
            if let Some(compressor) = self.compressor.as_ref() {
                compressor.try_borrow_mut().expect("no recursion").write_all(buf)?;
            }
            Ok(())
        };
        match self.object_hash {
            git_hash::Kind::Sha1 => {
                let mut hasher = Sha1::default();
                hasher.update(&header);
                possibly_compress(&header)?;

                while size != 0 {
                    let bytes = size.min(buf.len());
                    from.read_exact(&mut buf[..bytes])?;
                    hasher.update(&buf[..bytes]);
                    possibly_compress(&buf[..bytes])?;
                    size -= bytes;
                }
                if let Some(compressor) = self.compressor.as_ref() {
                    let mut c = compressor.borrow_mut();
                    c.flush()?;
                    c.reset();
                }

                Ok(hasher.digest().into())
            }
        }
    }
}

