//! Worker is a process performing a long-running task.
use super::{Error, Result, SOCKET, WORKER_ID};
use futures::Future;
use tokio::net::UnixStream;

/// Worker process handler.
pub struct Worker<H, F>
where
    H: Fn(UnixStream, String) -> F,
    F: Future<Output = Result<()>>,
{
    handler: Option<H>,
    relaxed: bool,
}

impl<H, F> Worker<H, F>
where
    H: Fn(UnixStream, String) -> F,
    F: Future<Output = Result<()>>,
{
    /// Create a new worker.
    pub fn new() -> Self {
        Self {
            handler: None,
            relaxed: false,
        }
    }

    /// Set the relaxed flag.
    ///
    /// When a worker is relaxed it will start with or without a supervisor.
    ///
    /// The default is `false` so workers expect to be run in the context
    /// of a supervisor and it is an error if no worker id is available in
    /// the environment.
    ///
    /// When this flag is enabled and the required environment variables
    /// do not exist the worker does not attempt to connect to a supervisor.
    ///
    /// Use this mode of operation when a worker process can be run standalone
    /// or as a worker for a supervisor process.
    pub fn relaxed(mut self, flag: bool) -> Self {
        self.relaxed = flag;
        self
    }

    /// Set a client connection handler.
    ///
    /// The handler function receives the socket stream and opaque
    /// worker identifier and can communicate with the supervisor using
    /// the socket stream.
    pub fn client(mut self, handler: H) -> Self {
        self.handler = Some(handler);
        self
    }

    /// Start this worker running.
    pub async fn run(&self) -> Result<()> {
        if let Some(ref handler) = self.handler {
            if let Some(id) = std::env::var(WORKER_ID).ok() {
                // If we were given a socket path make the connection.
                if let Some(path) = std::env::var(SOCKET).ok() {
                    // Connect to the supervisor socket
                    let stream = UnixStream::connect(&path).await?;
                    (handler)(stream, id.to_string()).await?;
                }
            } else {
                if !self.relaxed {
                    return Err(Error::WorkerNoId);
                }
            }
        }
        Ok(())
    }
}

use pattern::Pattern;

use regex::{Captures, Regex};

pub struct TurnipPattern {
    pattern: String,
}

impl Pattern for TurnipPattern {
    fn to_regex(&self) -> Regex {
        let re = Regex::new(r":(\w+)").unwrap();

        let pattern = self.pattern.as_str();
        let regex = re.replace_all(pattern, |caps: &Captures| {
            format!("[\"']?(?P<{}>[^\"]+|[^']+|{})['\"]?",
                    &caps[1],
                    r"\-?[\w\.,]+")
        });

        Regex::new(regex.into_owned().as_str()).unwrap()
    }

    fn to_string(&self) -> String {
        self.pattern.clone()
    }
}

impl<'a> From<&'a str> for TurnipPattern {
    fn from(pattern: &'a str) -> Self {
        TurnipPattern { pattern: pattern.to_string() }
    }
}

#[cfg(test)]
mod test {
    use super::TurnipPattern;
    use pattern::Pattern;

    const SIMPLE_PATTERN: &str = "it's a beautiful day";
    const PATTERN_WITH_ARGUMENTS: &str = "I have a :home in :city";

    #[test]
    fn it_converts_a_simple_pattern_to_a_regex_matching_the_same_description() {
        let pattern = TurnipPattern::from(SIMPLE_PATTERN);

        let regex = pattern.to_regex();

        assert!(regex.is_match(SIMPLE_PATTERN));
    }

    #[test]
    fn it_converts_a_turnip_pattern_with_arguments_to_a_regex_matching_description_with_single_word_arguments() {
        let pattern = TurnipPattern::from(PATTERN_WITH_ARGUMENTS);

        let regex = pattern.to_regex();

        let description = "I have a house in Quebec";
        assert!(regex.is_match(description));
    }

    #[test]
    fn it_converts_a_turnip_pattern_with_arguments_to_a_regex_matching_description_with_single_quote_arguments() {
        let pattern = TurnipPattern::from(PATTERN_WITH_ARGUMENTS);

        let regex = pattern.to_regex();

        let description = "I have a house in 'Quebec City'";
        assert!(regex.is_match(description));
    }

    #[test]
    fn it_converts_a_turnip_pattern_with_arguments_to_a_regex_matching_description_with_double_quote_arguments() {
        let pattern = TurnipPattern::from(PATTERN_WITH_ARGUMENTS);

        let regex = pattern.to_regex();

        let description = "I have a \"beautiful appartment\" in Quebec";
        assert!(regex.is_match(description));
    }

    #[test]
    fn it_converts_a_turnip_pattern_with_arguments_to_a_regex_matching_description_with_unsigned_number_arguments() {
        let pattern = TurnipPattern::from(PATTERN_WITH_ARGUMENTS);

        let regex = pattern.to_regex();

        let description = "I have a home in -4";
        assert!(regex.is_match(description));
    }

    #[test]
    fn it_converts_a_turnip_pattern_with_arguments_to_a_regex_matching_description_with_signed_number_arguments() {
        let pattern = TurnipPattern::from(PATTERN_WITH_ARGUMENTS);

        let regex = pattern.to_regex();

        let description = "I have a home in 101";
        assert!(regex.is_match(description));
    }
}

use std::fs::File;
use std::io::Write;

// Scratch pad for glyphs: ⅞ g
const CHARACTER: char = 'b';
const SIZE: f32 = 20.0;

// cargo run --example simple --release
pub fn main() {
    // Loading and rasterization
    let font = include_bytes!("../resources/fonts/Roboto-Regular.ttf") as &[u8];
    let settings = fontdue::FontSettings {
        scale: SIZE,
        ..fontdue::FontSettings::default()
    };
    let font = fontdue::Font::from_bytes(font, settings).unwrap();
    let (metrics, bitmap) = font.rasterize(CHARACTER, SIZE);

    // Output
    let mut o = File::create("fontdue.pgm").unwrap();
    let _ = o.write(format!("P5\n{} {}\n255\n", metrics.width, metrics.height).as_bytes());
    let _ = o.write(&bitmap);
}

