use conrod_core::{
    image,
    mesh::{self, Mesh},
    render,
    text::rt,
    Rect, Scalar,
};
use std::collections::{HashMap, HashSet};
use wgpu::util::DeviceExt;

/// A loaded wgpu texture and it's width/height
pub struct Image {
    /// The immutable image type, represents the data loaded onto the GPU.
    ///
    /// Uses a dynamic format for flexibility on the kinds of images that might be loaded.
    pub texture: wgpu::Texture,
    /// The format of the `texture`.
    pub texture_format: wgpu::TextureFormat,
    /// The width of the image.
    pub width: u32,
    /// The height of the image.
    pub height: u32,
}

/// The data associated with a single vertex.
#[repr(C)]
#[derive(Clone, Copy, Debug, Default, PartialEq, PartialOrd)]
pub struct Vertex {
    /// The normalised position of the vertex within vector space.
    ///
    /// [-1.0, 1.0] is the leftmost, bottom position of the display.
    /// [1.0, -1.0] is the rightmost, top position of the display.
    pub position: [f32; 2],
    /// The coordinates of the texture used by this `Vertex`.
    ///
    /// [0.0, 0.0] is the leftmost, top position of the texture.
    /// [1.0, 1.0] is the rightmost, bottom position of the texture.
    pub tex_coords: [f32; 2],
    /// Linear sRGB with an alpha channel.
    pub rgba: [f32; 4],
    /// The mode with which the `Vertex` will be drawn within the fragment shader.
    ///
    /// `0` for rendering text.
    /// `1` for rendering an image.
    /// `2` for rendering non-textured 2D geometry.
    ///
    /// If any other value is given, the fragment shader will not output any color.
    pub mode: u32,
}

/// A helper type aimed at simplifying the rendering of conrod primitives via wgpu.
pub struct Renderer {
    vs_mod: wgpu::ShaderModule,
    fs_mod: wgpu::ShaderModule,
    glyph_cache_tex: wgpu::Texture,
    _default_image_tex: wgpu::Texture,
    default_bind_group: wgpu::BindGroup,
    sampler: wgpu::Sampler,
    mesh: Mesh,
    // The texture format of the output attachment.
    dst_format: wgpu::TextureFormat,
    // The sample count of the output attachment.
    dst_sample_count: u32,
    // In order to support a dynamic number of images we maintain a unique bind group for each.
    bind_groups: HashMap<image::Id, wgpu::BindGroup>,
    // We also need a unique
    render_pipelines: HashMap<wgpu::TextureComponentType, Pipeline>,
}

/// Data that must be unique per `wgpu::TextureComponentType`, i.e. bind group layout and render
/// pipeline.
struct Pipeline {
    bind_group_layout: wgpu::BindGroupLayout,
    render_pipeline: wgpu::RenderPipeline,
}

/// An command for uploading an individual glyph.
pub struct GlyphCacheCommand<'a> {
    /// The CPU buffer containing the pixel data.
    pub glyph_cache_pixel_buffer: &'a [u8],
    /// The GPU image to which the glyphs are cached.
    pub glyph_cache_texture: &'a wgpu::Texture,
    /// The width of the texture.
    pub width: u32,
    /// The height of the texture.
    pub height: u32,
}

/// A render produced by the `Renderer::render` method.
pub struct Render<'a> {
    pub vertex_buffer: wgpu::Buffer,
    pub commands: Vec<RenderPassCommand<'a>>,
}

/// A draw command that maps directly to the `wgpu::CommandEncoder` method. By returning
/// `RenderPassCommand`s, we can avoid consuming the entire `AutoCommandBufferBuilder` itself which might
/// not always be available from APIs that wrap Vulkan.
pub enum RenderPassCommand<'a> {
    /// Specify the rectangle to which drawing should be cropped.
    SetScissor {
        top_left: [u32; 2],
        dimensions: [u32; 2],
    },
    /// Draw the specified range of vertices.
    Draw { vertex_range: std::ops::Range<u32> },
    /// A new image requires drawing and in turn a new bind group requires setting.
    SetBindGroup { bind_group: &'a wgpu::BindGroup },
    /// An image requiring a different bind group layout requires drawing and in turn, we must set
    /// the necessary render pipeline.
    SetPipeline { pipeline: &'a wgpu::RenderPipeline },
}

const GLYPH_TEX_FORMAT: wgpu::TextureFormat = wgpu::TextureFormat::R8Unorm;
const GLYPH_TEX_COMPONENT_TY: wgpu::TextureComponentType = wgpu::TextureComponentType::Uint;
const DEFAULT_IMAGE_TEX_FORMAT: wgpu::TextureFormat = wgpu::TextureFormat::R8Unorm;

impl mesh::ImageDimensions for Image {
    fn dimensions(&self) -> [u32; 2] {
        [self.width, self.height]
    }
}

impl Image {
    pub fn texture_component_type(&self) -> wgpu::TextureComponentType {
        self.texture_format.into()
    }
}

impl Renderer {
    /// Construct a new `Renderer`.
    ///
    /// The `dst_sample_count` and `dst_format` refer to the associated properties of the output
    /// attachment to which the `Renderer` will draw. Note that if the `dst_sample_count` or
    /// `dst_format` change at runtime, the `Renderer` should be reconstructed.
    pub fn new(
        device: &wgpu::Device,
        dst_sample_count: u32,
        dst_format: wgpu::TextureFormat,
    ) -> Self {
        let glyph_cache_dims = mesh::DEFAULT_GLYPH_CACHE_DIMS;
        Self::with_glyph_cache_dimensions(device, dst_sample_count, dst_format, glyph_cache_dims)
    }

    /// Create a renderer with a specific size for the glyph cache.
    ///
    /// The `dst_sample_count` and `dst_format` refer to the associated properties of the output
    /// attachment to which the `Renderer` will draw. Note that if the `dst_sample_count` or
    /// `dst_format` change at runtime, the `Renderer` should be reconstructed.
    pub fn with_glyph_cache_dimensions(
        device: &wgpu::Device,
        dst_sample_count: u32,
        dst_format: wgpu::TextureFormat,
        glyph_cache_dims: [u32; 2],
    ) -> Self {
        assert_eq!(
            glyph_cache_dims[0] % 256,
            0,
            "wgpu glyph cache width must be multiple of 256"
        );

        // The mesh for converting primitives into vertices.
        let mesh = Mesh::with_glyph_cache_dimensions(glyph_cache_dims);

        // Load shader modules.
        let vs_mod = device.create_shader_module(wgpu::include_spirv!("shaders/vert.spv"));
        let fs_mod = device.create_shader_module(wgpu::include_spirv!("shaders/frag.spv"));

        // Create the glyph cache texture.
        let glyph_cache_tex_desc = glyph_cache_tex_desc(glyph_cache_dims);
        let glyph_cache_tex = device.create_texture(&glyph_cache_tex_desc);

        // Create the default image that is bound to `image_texture` along with a default bind
        // group for use in the case that there are no user supplied images.
        let default_image_tex_desc = default_image_tex_desc();
        let default_image_tex = device.create_texture(&default_image_tex_desc);

        // Create the sampler for sampling from the glyph cache and image textures.
        let sampler_desc = sampler_desc();
        let sampler = device.create_sampler(&sampler_desc);

        // Create at least one render pipeline for the default texture.
        let mut render_pipelines = HashMap::new();

        let default_tex_component_ty = DEFAULT_IMAGE_TEX_FORMAT.into();
        let bind_group_layout = bind_group_layout(device, default_tex_component_ty);
        let pipeline_layout = pipeline_layout(device, &bind_group_layout);
        let render_pipeline = render_pipeline(
            device,
            &pipeline_layout,
            &vs_mod,
            &fs_mod,
            dst_format,
            dst_sample_count,
        );
        let default_bind_group = bind_group(
            device,
            &bind_group_layout,
            &glyph_cache_tex,
            &sampler,
            &default_image_tex,
        );
        let default_pipeline = Pipeline {
            bind_group_layout,
            render_pipeline,
        };
        render_pipelines.insert(default_tex_component_ty, default_pipeline);

        // The empty set of bind groups to be associated with user images.
        let bind_groups = Default::default();

        Self {
            vs_mod,
            fs_mod,
            glyph_cache_tex,
            _default_image_tex: default_image_tex,
            default_bind_group,
            sampler,
            dst_format,
            dst_sample_count,
            bind_groups,
            render_pipelines,
            mesh,
        }
    }

    /// Produce an `Iterator` yielding `Command`s.
    pub fn commands(&self) -> mesh::Commands {
        self.mesh.commands()
    }

    /// Fill the inner vertex and command buffers by translating the given `primitives`.
    ///
    /// This method may return an `Option<GlyphCacheCommand>`, in which case the user should use
    /// the contained `glyph_cpu_buffer_pool` to write the pixel data to the GPU, and then use a
    /// `copy_buffer_to_image` command to write the data to the given `glyph_cache_texture` image.
    pub fn fill<'a, P>(
        &'a mut self,
        image_map: &image::Map<Image>,
        viewport: [f32; 4],
        scale_factor: f64,
        primitives: P,
    ) -> Result<Option<GlyphCacheCommand<'a>>, rt::gpu_cache::CacheWriteErr>
    where
        P: render::PrimitiveWalker,
    {
        // Convert the given primitives into vertices.
        let [vp_l, vp_t, vp_r, vp_b] = viewport;
        let lt = [vp_l as Scalar, vp_t as Scalar];
        let rb = [vp_r as Scalar, vp_b as Scalar];
        let viewport = Rect::from_corners(lt, rb);
        let fill = self
            .mesh
            .fill(viewport, scale_factor, image_map, primitives)?;

        // Check whether or not we need a glyph cache update.
        let glyph_cache_cmd = match fill.glyph_cache_requires_upload {
            false => None,
            true => {
                let (width, height) = self.mesh.glyph_cache().dimensions();
                Some(GlyphCacheCommand {
                    glyph_cache_pixel_buffer: self.mesh.glyph_cache_pixel_buffer(),
                    glyph_cache_texture: &self.glyph_cache_tex,
                    width,
                    height,
                })
            }
        };
        Ok(glyph_cache_cmd)
    }

    /// Converts the inner list of `Command`s generated via `fill` to a list of
    /// `RenderPassCommand`s that are easily digestible by a `wgpu::RenderPass` produced by a
    /// `wgpu::CommandEncoder`.
    pub fn render(&mut self, device: &wgpu::Device, image_map: &image::Map<Image>) -> Render {
        let Renderer {
            ref mut bind_groups,
            ref mut render_pipelines,
            ref mut mesh,
            ref vs_mod,
            ref fs_mod,
            ref default_bind_group,
            ref glyph_cache_tex,
            ref sampler,
            dst_format,
            dst_sample_count,
            ..
        } = *self;

        let mut commands = vec![];

        // Ensure we have:
        // - a bind group layout and render pipeline for each unique texture component type.
        // - a bind group ready for each image in the map.
        let default_tct = DEFAULT_IMAGE_TEX_FORMAT.into();
        let unique_tex_component_types: HashSet<_> = image_map
            .values()
            .map(|img| img.texture_component_type())
            .chain(Some(default_tct))
            .collect();
        bind_groups.retain(|k, _| image_map.contains_key(k));
        render_pipelines.retain(|tct, _| unique_tex_component_types.contains(tct));
        for (id, img) in image_map.iter() {
            // If we already have a bind group for this image move on.
            if bind_groups.contains_key(id) {
                continue;
            }

            // Retrieve the bind group layout and pipeline for the image's texture component type.
            let tct = img.texture_component_type();
            let pipeline = render_pipelines.entry(tct).or_insert_with(|| {
                let bind_group_layout = bind_group_layout(device, tct);
                let pipeline_layout = pipeline_layout(device, &bind_group_layout);
                let render_pipeline = render_pipeline(
                    device,
                    &pipeline_layout,
                    vs_mod,
                    fs_mod,
                    dst_format,
                    dst_sample_count,
                );
                Pipeline {
                    bind_group_layout,
                    render_pipeline,
                }
            });

            // Create the bind
            let bind_group = bind_group(
                device,
                &pipeline.bind_group_layout,
                &glyph_cache_tex,
                sampler,
                &img.texture,
            );
            bind_groups.insert(*id, bind_group);
        }

        // Prepare a single vertex buffer containing all vertices for all geometry.
        let vertices = mesh.vertices();
        let vertices_bytes = vertices_as_bytes(vertices);
        let usage = wgpu::BufferUsage::VERTEX;
        let vertex_buffer = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("conrod_buffer_init_descriptor"),
            contents: vertices_bytes,
            usage,
        });

        // Keep track of the currently set bind group.
        #[derive(PartialEq)]
        enum BindGroup {
            Default,
            Image(image::Id),
        }
        let mut bind_group = None;

        for command in mesh.commands() {
            match command {
                // Update the `scizzor` before continuing to draw.
                mesh::Command::Scizzor(s) => {
                    let top_left = [s.top_left[0] as u32, s.top_left[1] as u32];
                    let dimensions = s.dimensions;
                    let cmd = RenderPassCommand::SetScissor {
                        top_left,
                        dimensions,
                    };
                    commands.push(cmd);
                }

                // Draw to the target with the given `draw` command.
                mesh::Command::Draw(draw) => match draw {
                    // Draw text and plain 2D geometry.
                    mesh::Draw::Plain(vertex_range) => {
                        let vertex_count = vertex_range.len();
                        if vertex_count <= 0 {
                            continue;
                        }
                        // Ensure a render pipeline and bind group is set.
                        if bind_group.is_none() {
                            bind_group = Some(BindGroup::Default);
                            let pipeline = &render_pipelines[&default_tct].render_pipeline;
                            let cmd = RenderPassCommand::SetPipeline { pipeline };
                            commands.push(cmd);
                            let cmd = RenderPassCommand::SetBindGroup {
                                bind_group: default_bind_group,
                            };
                            commands.push(cmd);
                        }
                        let cmd = RenderPassCommand::Draw {
                            vertex_range: vertex_range.start as u32..vertex_range.end as u32,
                        };
                        commands.push(cmd);
                    }

                    // Draw an image whose texture data lies within the `image_map` at the
                    // given `id`.
                    mesh::Draw::Image(image_id, vertex_range) => {
                        let vertex_count = vertex_range.len();
                        if vertex_count == 0 {
                            continue;
                        }
                        // Ensure the bind group matches this image.
                        let expected_bind_group = Some(BindGroup::Image(image_id));
                        if bind_group != expected_bind_group {
                            // Check whether or not we need to switch pipelines.
                            let expected_tct = image_map[&image_id].texture_component_type();
                            let current_tct = bind_group.as_ref().map(|bg| match *bg {
                                BindGroup::Default => default_tct,
                                BindGroup::Image(id) => image_map[&id].texture_component_type(),
                            });
                            if current_tct != Some(expected_tct) {
                                let pipeline = &render_pipelines[&expected_tct].render_pipeline;
                                let cmd = RenderPassCommand::SetPipeline { pipeline };
                                commands.push(cmd);
                            }

                            // Now update the bind group and add the new bind group command.
                            bind_group = expected_bind_group;
                            let cmd = RenderPassCommand::SetBindGroup {
                                bind_group: &bind_groups[&image_id],
                            };
                            commands.push(cmd);
                        }
                        let cmd = RenderPassCommand::Draw {
                            vertex_range: vertex_range.start as u32..vertex_range.end as u32,
                        };
                        commands.push(cmd);
                    }
                },
            }
        }

        Render {
            vertex_buffer,
            commands,
        }
    }
}

impl<'a> GlyphCacheCommand<'a> {
    /// Creates a buffer on the GPU loaded with the updated pixel data.
    ///
    /// Created with `BufferUsage::COPY_SRC`, ready to be copied to the texture.
    ///
    /// TODO: In the future, we should consider re-using the same buffer and writing to it via
    /// `Buffer::map_write_async`. When asking about how to ensure that the write completes before
    /// the following `copy_buffer_to_texture` command, I was advised to just create a new buffer
    /// each time instead for now.
    /// EDIT:
    /// > if you try to map an existing buffer, it will give it to you only after all the gpu use
    /// > of the buffer is over. So you can't do it every frame reasonably
    pub fn create_buffer(&self, device: &wgpu::Device) -> wgpu::Buffer {
        device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("conrod_buffer_init_descriptor"),
            contents: &self.glyph_cache_pixel_buffer,
            usage: wgpu::BufferUsage::COPY_SRC,
        })
    }

    /// Create the copy view ready for copying the pixel data to the texture.
    pub fn buffer_copy_view<'b>(&self, buffer: &'b wgpu::Buffer) -> wgpu::BufferCopyView<'b> {
        wgpu::BufferCopyView {
            buffer,
            layout: wgpu::TextureDataLayout {
                offset: 0,
                bytes_per_row: self.width,
                rows_per_image: self.height,
            },
        }
    }

    /// Create the texture copy view ready for receiving the pixel data from the buffer.
    pub fn texture_copy_view(&self) -> wgpu::TextureCopyView {
        wgpu::TextureCopyView {
            texture: &self.glyph_cache_texture,
            mip_level: 0,
            origin: wgpu::Origin3d::ZERO,
        }
    }

    /// Encode the command for copying the buffer's pixel data to the glyph cache texture.
    pub fn encode(&self, buffer: &wgpu::Buffer, encoder: &mut wgpu::CommandEncoder) {
        let buffer_copy_view = self.buffer_copy_view(&buffer);
        let texture_copy_view = self.texture_copy_view();
        let extent = self.extent();
        encoder.copy_buffer_to_texture(buffer_copy_view, texture_copy_view, extent);
    }

    /// The extent required for the copy command.
    pub fn extent(&self) -> wgpu::Extent3d {
        wgpu::Extent3d {
            width: self.width,
            height: self.height,
            depth: 1,
        }
    }

    /// Short-hand for `create_buffer` and `encode` in succession.
    pub fn load_buffer_and_encode(&self, device: &wgpu::Device, e: &mut wgpu::CommandEncoder) {
        let buffer = self.create_buffer(&device);
        self.encode(&buffer, e);
    }
}

fn glyph_cache_tex_desc([width, height]: [u32; 2]) -> wgpu::TextureDescriptor<'static> {
    let depth = 1;
    let texture_extent = wgpu::Extent3d {
        width,
        height,
        depth,
    };
    wgpu::TextureDescriptor {
        label: Some("conrod_wgpu_glyph_cache_texture"),
        size: texture_extent,
        mip_level_count: 1,
        sample_count: 1,
        dimension: wgpu::TextureDimension::D2,
        format: GLYPH_TEX_FORMAT,
        usage: wgpu::TextureUsage::SAMPLED | wgpu::TextureUsage::COPY_DST,
    }
}

fn default_image_tex_desc() -> wgpu::TextureDescriptor<'static> {
    let width = 64;
    let height = 64;
    let depth = 1;
    let texture_extent = wgpu::Extent3d {
        width,
        height,
        depth,
    };
    wgpu::TextureDescriptor {
        label: Some("conrod_wgpu_image_texture"),
        size: texture_extent,
        mip_level_count: 1,
        sample_count: 1,
        dimension: wgpu::TextureDimension::D2,
        format: DEFAULT_IMAGE_TEX_FORMAT,
        usage: wgpu::TextureUsage::SAMPLED,
    }
}

fn sampler_desc() -> wgpu::SamplerDescriptor<'static> {
    wgpu::SamplerDescriptor {
        label: Some("conrod_sample_descriptor"),
        address_mode_u: wgpu::AddressMode::ClampToEdge,
        address_mode_v: wgpu::AddressMode::ClampToEdge,
        address_mode_w: wgpu::AddressMode::ClampToEdge,
        mag_filter: wgpu::FilterMode::Linear,
        min_filter: wgpu::FilterMode::Linear,
        mipmap_filter: wgpu::FilterMode::Linear,
        lod_min_clamp: -100.0,
        lod_max_clamp: 100.0,
        compare: Some(wgpu::CompareFunction::Always),
        anisotropy_clamp: None,
    }
}

fn bind_group_layout(
    device: &wgpu::Device,
    img_tex_component_ty: wgpu::TextureComponentType,
) -> wgpu::BindGroupLayout {
    let glyph_cache_texture_binding = wgpu::BindGroupLayoutEntry {
        binding: 0,
        visibility: wgpu::ShaderStage::FRAGMENT,
        ty: wgpu::BindingType::SampledTexture {
            multisampled: false,
            component_type: GLYPH_TEX_COMPONENT_TY,
            dimension: wgpu::TextureViewDimension::D2,
        },
        count: None,
    };
    let sampler_binding = wgpu::BindGroupLayoutEntry {
        binding: 1,
        visibility: wgpu::ShaderStage::FRAGMENT,
        ty: wgpu::BindingType::Sampler { comparison: true },
        count: None,
    };
    let image_texture_binding = wgpu::BindGroupLayoutEntry {
        binding: 2,
        visibility: wgpu::ShaderStage::FRAGMENT,
        ty: wgpu::BindingType::SampledTexture {
            multisampled: false,
            component_type: img_tex_component_ty,
            dimension: wgpu::TextureViewDimension::D2,
        },
        count: None,
    };
    let entries = &[
        glyph_cache_texture_binding,
        sampler_binding,
        image_texture_binding,
    ];
    let desc = wgpu::BindGroupLayoutDescriptor {
        label: Some("conrod_bind_group_layout"),
        entries,
    };
    device.create_bind_group_layout(&desc)
}

fn bind_group(
    device: &wgpu::Device,
    layout: &wgpu::BindGroupLayout,
    glyph_cache_tex: &wgpu::Texture,
    sampler: &wgpu::Sampler,
    image: &wgpu::Texture,
) -> wgpu::BindGroup {
    // Glyph cache texture view.
    let glyph_cache_tex_view = glyph_cache_tex.create_view(&wgpu::TextureViewDescriptor::default());
    let glyph_cache_tex_binding = wgpu::BindGroupEntry {
        binding: 0,
        resource: wgpu::BindingResource::TextureView(&glyph_cache_tex_view),
    };

    // Sampler binding.
    let sampler_binding = wgpu::BindGroupEntry {
        binding: 1,
        resource: wgpu::BindingResource::Sampler(&sampler),
    };

    // Image texture view.
    let image_tex_view = image.create_view(&wgpu::TextureViewDescriptor::default());
    let image_tex_binding = wgpu::BindGroupEntry {
        binding: 2,
        resource: wgpu::BindingResource::TextureView(&image_tex_view),
    };

    let entries = &[glyph_cache_tex_binding, sampler_binding, image_tex_binding];
    let label = Some("conrod_bind_group");
    let desc = wgpu::BindGroupDescriptor {
        label,
        layout,
        entries,
    };
    device.create_bind_group(&desc)
}

fn pipeline_layout(
    device: &wgpu::Device,
    bind_group_layout: &wgpu::BindGroupLayout,
) -> wgpu::PipelineLayout {
    let desc = wgpu::PipelineLayoutDescriptor {
        label: Some("conrod_pipeline_layout_descriptor"),
        bind_group_layouts: &[&bind_group_layout],
        push_constant_ranges: &[],
    };
    device.create_pipeline_layout(&desc)
}

fn vertex_attrs() -> [wgpu::VertexAttributeDescriptor; 4] {
    let position_offset = 0;
    let position_size = std::mem::size_of::<[f32; 2]>() as wgpu::BufferAddress;
    let tex_coords_offset = position_offset + position_size;
    let tex_coords_size = position_size;
    let rgba_offset = tex_coords_offset + tex_coords_size;
    let rgba_size = std::mem::size_of::<[f32; 4]>() as wgpu::BufferAddress;
    let mode_offset = rgba_offset + rgba_size;
    [
        // position
        wgpu::VertexAttributeDescriptor {
            format: wgpu::VertexFormat::Float2,
            offset: position_offset,
            shader_location: 0,
        },
        // tex_coords
        wgpu::VertexAttributeDescriptor {
            format: wgpu::VertexFormat::Float2,
            offset: tex_coords_offset,
            shader_location: 1,
        },
        // rgba
        wgpu::VertexAttributeDescriptor {
            format: wgpu::VertexFormat::Float4,
            offset: rgba_offset,
            shader_location: 2,
        },
        // mode
        wgpu::VertexAttributeDescriptor {
            format: wgpu::VertexFormat::Uint,
            offset: mode_offset,
            shader_location: 3,
        },
    ]
}

fn render_pipeline(
    device: &wgpu::Device,
    layout: &wgpu::PipelineLayout,
    vs_mod: &wgpu::ShaderModule,
    fs_mod: &wgpu::ShaderModule,
    dst_format: wgpu::TextureFormat,
    dst_sample_count: u32,
) -> wgpu::RenderPipeline {
    let vs_desc = wgpu::ProgrammableStageDescriptor {
        module: &vs_mod,
        entry_point: "main",
    };
    let fs_desc = wgpu::ProgrammableStageDescriptor {
        module: &fs_mod,
        entry_point: "main",
    };
    let raster_desc = wgpu::RasterizationStateDescriptor {
        front_face: wgpu::FrontFace::Ccw,
        cull_mode: wgpu::CullMode::None,
        ..Default::default()
    };
    let color_state_desc = wgpu::ColorStateDescriptor {
        format: dst_format,
        color_blend: wgpu::BlendDescriptor {
            src_factor: wgpu::BlendFactor::SrcAlpha,
            dst_factor: wgpu::BlendFactor::OneMinusSrcAlpha,
            operation: wgpu::BlendOperation::Add,
        },
        alpha_blend: wgpu::BlendDescriptor {
            src_factor: wgpu::BlendFactor::One,
            dst_factor: wgpu::BlendFactor::OneMinusSrcAlpha,
            operation: wgpu::BlendOperation::Add,
        },
        write_mask: wgpu::ColorWrite::ALL,
    };
    let vertex_attrs = vertex_attrs();
    let vertex_buffer_desc = wgpu::VertexBufferDescriptor {
        stride: std::mem::size_of::<Vertex>() as wgpu::BufferAddress,
        step_mode: wgpu::InputStepMode::Vertex,
        attributes: &vertex_attrs[..],
    };
    let vertex_state_desc = wgpu::VertexStateDescriptor {
        index_format: wgpu::IndexFormat::Uint16,
        vertex_buffers: &[vertex_buffer_desc],
    };
    let desc = wgpu::RenderPipelineDescriptor {
        label: Some("conrod_render_pipeline_descriptor"),
        layout: Some(layout),
        vertex_stage: vs_desc,
        fragment_stage: Some(fs_desc),
        rasterization_state: Some(raster_desc),
        primitive_topology: wgpu::PrimitiveTopology::TriangleList,
        color_states: &[color_state_desc],
        depth_stencil_state: None,
        vertex_state: vertex_state_desc,
        sample_count: dst_sample_count,
        sample_mask: !0,
        alpha_to_coverage_enabled: false,
    };
    device.create_render_pipeline(&desc)
}

fn vertices_as_bytes(s: &[mesh::Vertex]) -> &[u8] {
    let len = s.len() * std::mem::size_of::<mesh::Vertex>();
    let ptr = s.as_ptr() as *const u8;
    unsafe { std::slice::from_raw_parts(ptr, len) }
}

//! Parse an ASN.1 `Type`.
//!
//! This parser is not a complete implementation of the `Type` production in X.680, but is as
//! complete as is necessary to parse most SNMP MIB files. In the main output type, missing
//! productions are included as commentary.

use std::collections::HashMap;

use nom::{
    branch::alt,
    combinator::{map, opt, value},
    multi::separated_list1,
    sequence::{delimited, pair, preceded, separated_pair, terminated, tuple},
    IResult,
};
use num::{bigint::ToBigInt, integer::Integer, BigInt, Num};

use crate::parser::atoms::{identifier, kw, signed, sym, unsigned};

/// A representation of a complete ASN.1 type.
///
/// An ASN.1 type includes a "plain" type which is optionally constrained, and may optionally have
/// encoding tags attached. In all public APIs, the `ID` parameter is
/// [`Identifier`][crate::types::Identifier].
///
/// This type roughly corresponds to the **TaggedType** grammar production in ITU-T Rec X.680.
///
/// ## Example
///
/// The following ASN.1 type, occurring in the `MY-MIB` module definition where `ImportedType` has
/// been imported from `OTHER-MODULE`:
///
/// ```text
/// SEQUENCE {
///     fancy [APPLICATION 4] IMPLICIT INTEGER (16..42, SIZE(4)),
///     pants [18] ImportedType (SIZE(0..8)),
/// }
/// ```
///
/// Would be parsed as the following structure (of type `Type<Identifier>`):
///
/// ```text
/// Type {
///     ty: Builtin(Sequence([
///         (
///             Identifier("MY-MIB::fancy"),
///             Type {
///                 ty: Builtin(Integer(None)),
///                 constraint: Some(Constraint {
///                     size: Some([4]),
///                     value: Some([16..42])
///                 }),
///                 tag: Some(TypeTag(Implicit, Application, 4))
///             }
///         ),
///         (
///             Identifier("MY-MIB::pants"),
///             Type {
///                 ty: Referenced(
///                     Identifier("OTHER-MODULE::ImportedType"),
///                     None,
///                 ),
///                 constraint: Some(Constraint {
///                     size: Some([0..8]),
///                     value: None
///                 }),
///                 tag: Some(TypeTag(Unspecified, ContextSpecific, 18))
///             }
///         )
///     ])),
///     constraint: None,
///     tag: None
/// }
/// ```
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Type<ID>
where
    ID: PartialEq + Eq,
{
    /// The "plain" (unconstrained, untagged) type.
    pub ty: PlainType<ID>,
    /// The constraints applied to the type, if any. Currently supported are size constraints and
    /// value range constraints.
    pub constraint: Option<Constraint>,
    /// ASN.1 encoding tags applied to the type, if any.
    pub tag: Option<TypeTag>,
}

/// A representation of a plain ASN.1 type, excluding constraints and tagging.
///
/// This can be either a built-in, primitive ASN.1 type such as `INTEGER`, or a referenced type,
/// which is an identifier that refers to some other type (either well-known or user defined) that
/// is not built-in. In all public APIs, the `ID` parameter is
/// [`Identifier`][crate::types::Identifier].
///
/// This roughly corresponds to the **Type** grammar production in ITU-T Rec X.680, except that the
/// **ConstrainedType** variant is not used in order to reduce nesting; instead constraints are
/// represented by the `Type::constraint` field.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum PlainType<ID>
where
    ID: PartialEq + Eq,
{
    /// A built-in ASN.1 primitive type. The data member describes which built-in type it is.
    Builtin(BuiltinType<ID>),
    /// A referenced type. The data members are the identifier of the referent type, and optionally
    /// a set of named values, which may be present on any referenced type but are generally only
    /// used if the referent is an integer of some kind.
    Referenced(ID, Option<HashMap<String, BigInt>>),
    // Constrained,  <-- this is made non-recursive by moving constraints to Type
}

/// A representation of a built-in ASN.1 type.
///
/// This can express all of the ASN.1 built-in types that occur in SNMP MIB module definitions, but
/// excludes a significant a number of other built-in types that are (to the author's knowledge)
/// never found in MIBs. In all public APIs, the `ID` parameter is
/// [`Identifier`][crate::types::Identifier].
///
/// This type roughly corresponds to the **BuiltinType** grammar production in ITU-T Rec X.680,
/// except that the **PrefixedType** variant is deliberately not used in order to reduce nesting;
/// instead tags are represented by the `Type::tag` field.
///
/// The **BuiltinType** production defined in X.680 contains the following alternates that are not
/// supported here:
///
/// - **BitStringType** (`BIT STRING`) --- SMI defines and uses the well-known type `BITS` instead.
/// - **CharacterStringType** (`CHARACTER STRING`, `BMPString`, `GeneralString`, `GraphicString`,
///   `IA5String`, `ISO646String`, `NumericString`, `PrintableString`, `TeletextString`,
///   `T61String`, `UniversalString`, `UTF8String`, `VideotexString`, `VisibleString`)
/// - **DateType** (`DATE`)
/// - **DateTimeType** (`DATE-TIME`)
/// - **DurationType** (`DURATION`) --- SMI defines and uses the well-known type `TimeTicks`
///   instead.
/// - **EmbeddedPDVType** (`EMBEDDED PDV`)
/// - **EnumeratedType** (`ENUMERATED`) --- SMI uses `INTEGER` with named values instead.
/// - **ExternalType** (`EXTERNAL`)
/// - **InstanceOfType** (ITU-T Rec X.681)
/// - **IRIType** (`OID-IRI`)
/// - **ObjectClassFieldType** (ITU-T Rec X.681)
/// - **RealType** (`REAL`)
/// - **RelativeIRIType** (`RELATIVE-OID-IRI`)
/// - **RelativeOIDType** (`RELATIVE-OID`)
/// - **SetType** (`SET`)
/// - **SetOfType** (`SET OF`)
/// - **TimeType** (`TIME`)
/// - **TimeOfDayType** (`TIME-OF-DAY`)
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum BuiltinType<ID>
where
    ID: PartialEq + Eq,
{
    /// A `BOOLEAN`.
    Boolean,
    /// A `CHOICE` enum. The data member is the sequence of variant names and their types.
    Choice(Vec<(String, Type<ID>)>),
    /// An `INTEGER`. The data member is a map of named values keyed by their names, if one is
    /// provided. In SNMP MIBs, `INTEGER` with named values is used for C-style enum types instead
    /// of the more expected `ENUMERATION`.
    Integer(Option<HashMap<String, BigInt>>),
    /// The `NULL` type --- analogous to Rust's `()` (unit).
    Null,
    /// An `OBJECT IDENTIFIER`.
    ObjectIdentifier,
    /// An `OCTET STRING`.
    OctetString,
    /// A `SEQUENCE` --- analogous to a struct. The data member is the sequence of field identifiers
    /// and their types.
    Sequence(Vec<(ID, Type<ID>)>),
    /// A `SEQUENCE OF` --- analogous to a `Vec<T>`. The data member is the type of `T` (which must
    /// be boxed to keep `BuiltinType` a bounded size).
    SequenceOf(Box<Type<ID>>),
}

/// A constraint on an ASN.1 type.
///
/// The ASN.1 constraint grammar is extremely expressive, and this type only represents a very
/// small subset of it that appears in MIB module definitions. That subset specifically is
///
/// * Size constraints (which constrain the allowable length of variable-length types), and
/// * Value constraints (which constrain the allowable values out of the range of all possible
///   values the plain type may represent).
///
/// Additionally, union is the only supported set operation; intersection and exclusion is not
/// supported.
///
/// This roughly corresponds to the **Constraint** grammar production in ITU-T Rec X.680, except:
///
/// - **ConstraintSpec** may only be **SubtypeConstraint**,
/// - **ElementSetSpecs** may not include **AdditionalElementSetSpec**,
/// - **ElementSetSpec** may only be **Unions**,
/// - **Intersections** may only contain one **IntersectionElements**,
/// - **IntersectionElements** may only be **Elements**,
/// - **Elements** may only be **SubtypeElements**,
/// - **SubtypeElements** may only be **SingleValue**, **ValueRange**, or **SizeConstraint**.
///
/// ## Example
///
/// The ASN.1 constraint `(16..42, SIZE(4))` is parsed as the following structure:
///
/// ```
/// # use snmp_mib::parser::{Constraint, ConstraintRange};
/// Constraint {
///     size: Some(vec![ConstraintRange::Point(4.into())]),
///     value: Some(vec![ConstraintRange::Closed(16.into(), 42.into())]),
/// };
/// ```
///
/// The constraint `(-1 | 4 | 16)` is parsed as:
///
/// ```
/// # use snmp_mib::parser::{Constraint, ConstraintRange};
/// Constraint {
///     size: None,
///     value: Some(vec![
///         ConstraintRange::Point((-1).into()),
///         ConstraintRange::Point(4.into()),
///         ConstraintRange::Point(16.into()),
///     ]),
/// };
/// ```
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Constraint {
    /// If there is a size constraint, lists the allowable sizes. `None` means the size is
    /// unconstrained.
    pub size: Option<Vec<ConstraintRange>>,
    /// If there is a value constraint, lists the allowable values. `None` means the value is
    /// unconstrained.
    pub value: Option<Vec<ConstraintRange>>,
}

/// A value or range of values that are allowable for a constraint.
///
/// This corresponds to the **SingleValue** and **ValueRange** grammar productions in ITU-T Rec
/// X.680.
#[derive(Clone, PartialEq, Eq)]
pub enum ConstraintRange {
    /// A completely unbounded range; e.g. `MIN..MAX`.
    Full,
    /// A range with an upper bound only; e.g. `MIN..4`. The data member is the upper bound, which
    /// is inclusive.
    LessEq(BigInt),
    /// A range with a lower bound only; e.g. `-1..MAX`. The data member is the lower bound, which
    /// is inclusive.
    GreaterEq(BigInt),
    /// A range with both upper and lower bounds, e.g. `-1..48`. The data members are the lower and
    /// upper bounds, which are both inclusive.
    Closed(BigInt, BigInt),
    /// A singular allowable value, e.g. `16`. The data member is the allowable value. This is
    /// nearly always found in a set of multiple `ConstraintRange`s.
    Point(BigInt),
}

impl std::fmt::Debug for ConstraintRange {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> Result<(), std::fmt::Error> {
        match self {
            ConstraintRange::Full => write!(f, "MIN..MAX"),
            ConstraintRange::LessEq(u) => write!(f, "MIN..{}", u),
            ConstraintRange::GreaterEq(l) => write!(f, "{}..MAX", l),
            ConstraintRange::Closed(l, u) => write!(f, "{}..{}", l, u),
            ConstraintRange::Point(p) => write!(f, "{}", p),
        }
    }
}

/// Encoding tag information for an ASN.1 type.
///
/// The data members are the kind of tag, the class of tag, and the tag value itself.
///
/// This type, when used in the `tag` field of [`Type`], roughly corresponds to the **TaggedType**
/// grammar production in ITU-T Rec X.680. It would correspond to the **Tag** production except
/// that `IMPLICIT`/`EXPLICIT`/unspecified are also included.
///
/// ## Example
///
/// A field or type tagged `[APPLICATION 4] IMPLICIT` would have `Type::tag` ==
/// `TypeTag(TypeTagKind::Implicit, TypeTagClass::Application, 4)`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct TypeTag(pub TypeTagKind, pub TypeTagClass, pub u32);

/// The kind of an ASN.1 encoding tag.
///
/// The kind refers to whether the tag is specified to be `IMPLICIT`, `EXPLICIT`, or unspecified.
/// The effective tagging kind is always either implicit or explicit, and is determined by the
/// rules in ITU-T Rec X.680 § 31.2.7. The parser does not implement these rules; this type
/// strictly represents the specific, as-written syntax used in the type expression.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum TypeTagKind {
    /// The tag specified neither `EXPLICIT` nor `IMPLICIT`.
    Unspecified,
    /// The tag used the `IMPLICIT` keyword.
    Implicit,
    /// The tag used the `EXPLICIT` keyword.
    Explicit,
}

/// The class of an ASN.1 encoding tag.
///
/// In ASN.1, the tag class is a "namespace" for tag numbers. There are 4 such namespaces, one of
/// which (`UNIVERSAL`) is generally reserved for built-in types, but is user-expressible anyway.
/// Tags which do not specify any class are said to be "context-specific" class.
///
/// ## Examples
///
/// * `[APPLICATION 4]` would have the class `TypeTagClass::Application`.
/// * `[42]` would have the class `TypeTagClass::ContextSpecific`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum TypeTagClass {
    /// The tag class was specified as `UNIVERSAL`.
    Universal,
    /// The tag class was specified as `APPLICATION`.
    Application,
    /// The tag class was specified as `PRIVATE`.
    Private,
    /// The tag class was not specified, meaning it is context-specific.
    ContextSpecific,
}

//////////////////////////////////////////////////////////////////////////////////////////

impl<ID> Type<ID>
where
    ID: PartialEq + Eq,
{
    fn new(ty: PlainType<ID>, constraint: Option<Constraint>, tag: Option<TypeTag>) -> Self {
        Self {
            ty,
            constraint,
            tag,
        }
    }

    #[cfg(test)]
    fn plain(ty: PlainType<ID>) -> Self {
        Self::new(ty, None, None)
    }

    #[cfg(test)]
    fn with_constraint(self, constraint: Constraint) -> Self {
        Self {
            constraint: Some(constraint),
            ..self
        }
    }

    #[cfg(test)]
    fn with_tag(self, tag: TypeTag) -> Self {
        Self {
            tag: Some(tag),
            ..self
        }
    }
}

#[cfg(test)]
impl<ID> PlainType<ID>
where
    ID: PartialEq + Eq,
{
    fn into_type(self) -> Type<ID> {
        Type::plain(self)
    }
}

#[cfg(test)]
impl<ID> BuiltinType<ID>
where
    ID: PartialEq + Eq,
{
    fn into_plain(self) -> PlainType<ID> {
        PlainType::Builtin(self)
    }
}

impl Constraint {
    fn empty() -> Self {
        Self {
            size: None,
            value: None,
        }
    }

    #[cfg(test)]
    fn sizes<T: ToConstraintRange>(size: impl IntoIterator<Item = T>) -> Self {
        Self {
            size: Some(
                size.into_iter()
                    .map(ToConstraintRange::to_constraint_range)
                    .collect(),
            ),
            value: None,
        }
    }

    fn values<T: ToConstraintRange>(value: impl IntoIterator<Item = T>) -> Self {
        Self {
            size: None,
            value: Some(
                value
                    .into_iter()
                    .map(ToConstraintRange::to_constraint_range)
                    .collect(),
            ),
        }
    }

    #[cfg(test)]
    fn size(size: impl ToConstraintRange) -> Self {
        Self::sizes([size])
    }

    #[cfg(test)]
    fn value(value: impl ToConstraintRange) -> Self {
        Self::values([value])
    }

    fn union(self, other: Self) -> Self {
        let Self { size, value } = other;
        let union_option =
            |s: Option<Vec<ConstraintRange>>, o: Option<Vec<ConstraintRange>>| match (s, o) {
                (Some(mut s), Some(o)) => {
                    s.extend(o);
                    Some(s)
                }
                (Some(s), None) => Some(s),
                (None, Some(o)) => Some(o),
                (None, None) => None,
            };
        Self {
            size: union_option(self.size, size),
            value: union_option(self.value, value),
        }
    }
}

#[cfg(test)]
impl ConstraintRange {
    fn less_eq(u: impl ToBigInt + Integer) -> Self {
        ConstraintRange::LessEq(u.to_bigint().unwrap())
    }
    fn greater_eq(l: impl ToBigInt + Integer) -> Self {
        ConstraintRange::GreaterEq(l.to_bigint().unwrap())
    }
}

trait ToConstraintRange {
    fn to_constraint_range(self) -> ConstraintRange;
}

impl ToConstraintRange for ConstraintRange {
    fn to_constraint_range(self) -> ConstraintRange {
        self
    }
}

impl<T: ToBigInt + Integer> ToConstraintRange for (T,) {
    fn to_constraint_range(self) -> ConstraintRange {
        ConstraintRange::Point(self.0.to_bigint().unwrap())
    }
}

impl<L: ToBigInt + Integer, U: ToBigInt + Integer> ToConstraintRange for (L, U) {
    fn to_constraint_range(self) -> ConstraintRange {
        let (li, ui) = self;
        let (l, u) = (li.to_bigint().unwrap(), ui.to_bigint().unwrap());
        if l == u {
            ConstraintRange::Point(l)
        } else {
            ConstraintRange::Closed(l, u)
        }
    }
}

#[cfg(test)]
impl TypeTag {
    fn new(val: u32) -> Self {
        TypeTag(TypeTagKind::Unspecified, TypeTagClass::ContextSpecific, val)
    }
    fn implicit(self) -> Self {
        TypeTag(TypeTagKind::Implicit, self.1, self.2)
    }
    fn explicit(self) -> Self {
        TypeTag(TypeTagKind::Explicit, self.1, self.2)
    }
    fn universal(self) -> Self {
        TypeTag(self.0, TypeTagClass::Universal, self.2)
    }
    fn application(self) -> Self {
        TypeTag(self.0, TypeTagClass::Application, self.2)
    }
    fn private(self) -> Self {
        TypeTag(self.0, TypeTagClass::Private, self.2)
    }
}

//////////////////////////////////////////////////////////////////////////////////////////

pub(crate) fn asn_type(input: &str) -> IResult<&str, Type<String>> {
    asn_type_common(&builtin_type)(input)
}

/// Workaround for a compiler hang which occurs if asn_type is used inside a production that is
/// called from asn_type. This calls builtin_type_nonrec instead of builtin_type but is otherwise
/// identical.
fn asn_type_nonrec(input: &str) -> IResult<&str, Type<String>> {
    asn_type_common(&builtin_type_nonrec)(input)
}

fn asn_type_common<'a>(
    builtin_type: &'a dyn Fn(&str) -> IResult<&str, BuiltinType<String>>,
) -> impl 'a + Fn(&str) -> IResult<&str, Type<String>> {
    move |input| {
        map(
            tuple((
                opt(type_tag),
                alt((
                    map(builtin_type, |t| PlainType::Builtin(t)),
                    map(pair(identifier, opt(named_number_list)), |t| {
                        PlainType::Referenced(t.0.to_string(), t.1)
                    }),
                )),
                opt(constraint),
            )),
            |(tag, ty, cstr)| Type::new(ty, cstr, tag),
        )(input)
    }
}

fn builtin_type(input: &str) -> IResult<&str, BuiltinType<String>> {
    alt((
        builtin_type_nonrec,
        builtin_type_sequence,
        builtin_type_sequence_of,
        builtin_type_choice,
    ))(input)
}

/// Workaround for a compiler hang which occurs if asn_type is used inside a production that is
/// called from asn_type. All builtin_type alternates that do not transitively contain an asn_type
/// production go here; alternates which do go in builtin_type directly.
fn builtin_type_nonrec(input: &str) -> IResult<&str, BuiltinType<String>> {
    alt((
        value(BuiltinType::Boolean, kw("BOOLEAN")),
        value(BuiltinType::OctetString, pair(kw("OCTET"), kw("STRING"))),
        value(
            BuiltinType::ObjectIdentifier,
            pair(kw("OBJECT"), kw("IDENTIFIER")),
        ),
        value(BuiltinType::Null, kw("NULL")),
        builtin_type_integer,
    ))(input)
}

fn builtin_type_integer(input: &str) -> IResult<&str, BuiltinType<String>> {
    map(preceded(kw("INTEGER"), opt(named_number_list)), |nnl| {
        BuiltinType::Integer(nnl)
    })(input)
}

fn named_number_list<T>(input: &str) -> IResult<&str, HashMap<String, T>>
where
    T: Num,
{
    let named_number = pair(identifier, delimited(sym("("), signed, sym(")")));
    map(
        delimited(
            sym("{"),
            terminated(separated_list1(sym(","), named_number), opt(sym(","))),
            sym("}"),
        ),
        |nnl| nnl.into_iter().map(|(k, v)| (k.to_string(), v)).collect(),
    )(input)
}

fn builtin_type_sequence_of(input: &str) -> IResult<&str, BuiltinType<String>> {
    map(
        preceded(pair(kw("SEQUENCE"), kw("OF")), asn_type_nonrec),
        |t| BuiltinType::SequenceOf(Box::new(t)),
    )(input)
}

fn named_type_list_nonrec(input: &str) -> IResult<&str, Vec<(String, Type<String>)>> {
    map(
        terminated(
            separated_list1(sym(","), pair(identifier, asn_type_nonrec)),
            opt(sym(",")),
        ),
        |t| {
            t.iter()
                .map(|(name, ty)| (name.to_string(), ty.clone()))
                .collect()
        },
    )(input)
}

/// Extensions, exceptions, optional fields, default values, and COMPONENTS OF are not supported.
fn builtin_type_sequence(input: &str) -> IResult<&str, BuiltinType<String>> {
    map(
        preceded(
            kw("SEQUENCE"),
            delimited(sym("{"), named_type_list_nonrec, sym("}")),
        ),
        |ntl| BuiltinType::Sequence(ntl),
    )(input)
}

fn builtin_type_choice(input: &str) -> IResult<&str, BuiltinType<String>> {
    map(
        preceded(
            kw("CHOICE"),
            delimited(sym("{"), named_type_list_nonrec, sym("}")),
        ),
        |ntl| BuiltinType::Choice(ntl),
    )(input)
}

//////////////////////////////////////////////////////////////////////////////////////////

/// Significant subset of actual constraint grammar. Supports value and size only, and union of
/// range and single value only.
fn constraint(input: &str) -> IResult<&str, Constraint> {
    let size = map(
        preceded(kw("SIZE"), delimited(sym("("), value_constraint, sym(")"))),
        |Constraint { value, .. }| Constraint {
            size: value,
            value: None,
        },
    );

    map(
        delimited(
            sym("("),
            separated_list1(sym(","), alt((size, value_constraint))),
            sym(")"),
        ),
        |cs| {
            cs.into_iter()
                .fold(Constraint::empty(), |acc, v| acc.union(v))
        },
    )(input)
}

fn value_constraint(input: &str) -> IResult<&str, Constraint> {
    let lower = alt((value(None, sym("MIN")), map(signed, Option::Some)));
    let upper = alt((value(None, kw("MAX")), map(signed, Option::Some)));
    let range = map(separated_pair(lower, sym(".."), upper), |t| match t {
        (Some(l), Some(u)) => ConstraintRange::Closed(l, u),
        (Some(l), None) => ConstraintRange::GreaterEq(l),
        (None, Some(u)) => ConstraintRange::LessEq(u),
        (None, None) => ConstraintRange::Full,
    });
    let union_member = alt((range, map(signed, |v| ConstraintRange::Point(v))));
    map(separated_list1(sym("|"), union_member), |ums| {
        Constraint::values(
            ums.iter()
                .cloned()
                .map(ToConstraintRange::to_constraint_range),
        )
    })(input)
}

//////////////////////////////////////////////////////////////////////////////////////////

/// Encoding references are not supported.
fn type_tag(input: &str) -> IResult<&str, TypeTag> {
    let class = map(
        opt(alt((
            value(TypeTagClass::Universal, kw("UNIVERSAL")),
            value(TypeTagClass::Application, kw("APPLICATION")),
            value(TypeTagClass::Private, kw("PRIVATE")),
        ))),
        |t| t.unwrap_or(TypeTagClass::ContextSpecific),
    );
    let kind = map(
        opt(alt((
            value(TypeTagKind::Implicit, kw("IMPLICIT")),
            value(TypeTagKind::Explicit, kw("EXPLICIT")),
        ))),
        |t| t.unwrap_or(TypeTagKind::Unspecified),
    );
    map(
        pair(delimited(sym("["), pair(class, unsigned), sym("]")), kind),
        |((c, t), k)| TypeTag(k, c, t),
    )(input)
}

