            modified_counters: old_timestamps,
            publisher,
        };
        let changed_streams = handler.calculate_changed_streams(fake_streams, new_timestamps);
        assert_eq!(changed_streams, expected_changed_streams);
    }
}

use crate::base::*;

use serde::{Deserialize, Serialize};
