fn test(
    expected: Vec<Chunk<Box<dyn Array>>>,
    type_: &str,
    insert: &str,
    table_name: &str,
) -> Result<()> {
    let connection = ENV.connect_with_connection_string(MSSQL).unwrap();
    setup_empty_table(&connection, table_name, &[type_]).unwrap();
    connection
        .execute(&format!("INSERT INTO {table_name} (a) VALUES {insert}"), ())
        .unwrap();

    // When
    let query = format!("SELECT a FROM {table_name} ORDER BY id");

    let chunks = read(&connection, &query)?.1;

    assert_eq!(chunks, expected);
    Ok(())
}

pub fn read(
    connection: &Connection<'_>,
    query: &str,
) -> Result<(Vec<Field>, Vec<Chunk<Box<dyn Array>>>)> {
    let mut a = connection.prepare(query).unwrap();
    let fields = infer_schema(&a)?;

    let max_batch_size = 100;
    let buffer = buffer_from_metadata(&a, max_batch_size).unwrap();

    let cursor = a.execute(()).unwrap().unwrap();
    let mut cursor = cursor.bind_buffer(buffer).unwrap();

    let mut chunks = vec![];
    while let Some(batch) = cursor.fetch().unwrap() {
        let arrays = (0..batch.num_cols())
            .zip(fields.iter())
            .map(|(index, field)| {
                let column_view = batch.column(index);
                deserialize(column_view, field.data_type.clone())
            })
            .collect::<Vec<_>>();
        chunks.push(Chunk::new(arrays));
    }

    Ok((fields, chunks))
}

use crate::{
    commands::{parsers::append_arguments, CommandData, Data},
    state::{AppendingState, State},
};
use erooster_core::{
    backend::storage::{MailStorage, Storage},
    config::Config,
};
use futures::{channel::mpsc::SendError, Sink, SinkExt};
use nom::{error::convert_error, Finish};
use std::{path::Path, sync::Arc};
use tracing::{debug, error, instrument};

pub struct Append<'a> {
    pub data: &'a Data,
}
impl Append<'_> {
    #[instrument(skip(self, lines, storage, command_data))]
    pub async fn exec<S>(
        &self,
        lines: &mut S,
        storage: Arc<Storage>,
        command_data: &CommandData<'_>,
    ) -> color_eyre::eyre::Result<()>
    where
        S: Sink<String, Error = SendError> + std::marker::Unpin + std::marker::Send,
    {
        let mut write_lock = self.data.con_state.write().await;
        debug!("Append command start");
        if matches!(write_lock.state, State::Authenticated)
            || matches!(write_lock.state, State::Selected(_, _))
        {
            debug!("[Append] User is authenticated");
            debug!(
                "[Append] User added {} arguments",
                command_data.arguments.len()
            );
            assert!(command_data.arguments.len() >= 3);
            let folder = command_data.arguments[0].replace('"', "");
            debug!("[Append] User wants to append to folder: {}", folder);
            let mailbox_path =
                storage.to_ondisk_path(folder.clone(), write_lock.username.clone().unwrap())?;
            let folder = storage.to_ondisk_path_name(folder)?;
            debug!("Appending to folder: {:?}", mailbox_path);
            // Spec violation but thunderbird would prompt a user error otherwise :/
            if !mailbox_path.exists() {
                /*lines
                    .send(format!(
                        "{} NO [TRYCREATE] folder is not yet created",
                        command_data.tag
                    ))
                    .await?;
                return Ok(());*/
                storage.create_dirs(&mailbox_path)?;
                if folder.to_lowercase() == ".sent" {
                    storage.add_flag(&mailbox_path, "\\Sent").await?;
                    storage.add_flag(&mailbox_path, "\\Subscribed").await?;
                } else if folder.to_lowercase() == ".junk" {
                    storage.add_flag(&mailbox_path, "\\Junk").await?;
                    storage.add_flag(&mailbox_path, "\\Subscribed").await?;
                } else if folder.to_lowercase() == ".drafts" {
                    storage.add_flag(&mailbox_path, "\\Drafts").await?;
                    storage.add_flag(&mailbox_path, "\\Subscribed").await?;
                } else if folder.to_lowercase() == ".archive" {
                    storage.add_flag(&mailbox_path, "\\Archive").await?;
                    storage.add_flag(&mailbox_path, "\\Subscribed").await?;
                } else if folder.to_lowercase() == ".trash" {
                    storage.add_flag(&mailbox_path, "\\Trash").await?;
                    storage.add_flag(&mailbox_path, "\\Subscribed").await?;
                }
            }

            let append_args = command_data.arguments[1..].join(" ");
            let append_args_borrow: &str = &append_args;
            debug!("Append args: {}", append_args_borrow);
            match append_arguments(append_args_borrow).finish() {
                Ok((left, (flags, datetime, literal))) => {
                    debug!("[Append] leftover: {}", left);
                    write_lock.state = State::Appending(AppendingState {
                        folder: folder.to_string(),
                        flags: flags.map(|x| x.iter().map(ToString::to_string).collect::<Vec<_>>()),
                        datetime,
                        data: None,
                        datalen: literal.length,
                        tag: command_data.tag.to_string(),
                    });
                    if !literal.continuation {
                        lines.send(String::from("+ Ready for literal data")).await?;
                    }
                }
                Err(e) => {
                    error!(
                        "[Append] Error parsing arguments: {}",
                        convert_error(append_args_borrow, e)
                    );
                    lines
                        .send(format!(
                            "{} BAD failed to parse arguments",
                            command_data.tag
                        ))
                        .await?;
                }
            }
        } else {
            lines
                .send(format!("{} NO invalid state", command_data.tag))
                .await?;
        }
        Ok(())
    }

    #[instrument(skip(self, lines, storage, config, append_data))]
    pub async fn append<S>(
        &self,
        lines: &mut S,
        storage: Arc<Storage>,
        append_data: &str,
        config: Arc<Config>,
        tag: String,
    ) -> color_eyre::eyre::Result<()>
    where
        S: Sink<String, Error = SendError> + std::marker::Unpin + std::marker::Send,
    {
        let mut write_lock = self.data.con_state.write().await;
        let username = write_lock.username.clone().unwrap();
        if let State::Appending(state) = &mut write_lock.state {
            if let Some(buffer) = &mut state.data {
                let mut bytes = format!("{}\r\n", append_data).as_bytes().to_vec();
                buffer.append(&mut bytes);
                if buffer.len() + bytes.len() >= state.datalen {
                    debug!("[Append] Saving data");
                    let folder = &state.folder;
                    let mailbox_path = Path::new(&config.mail.maildir_folders)
                        .join(username)
                        .join(folder.clone());
                    debug!("[Append] Mailbox path: {:?}", mailbox_path);
                    if let Some(flags) = &state.flags {
                        let message_id = storage
                            .store_cur_with_flags(&mailbox_path, buffer, flags.clone())
                            .await?;
                        debug!("Stored message via append: {}", message_id);
                    } else {
                        let message_id = storage
                            .store_cur_with_flags(&mailbox_path, buffer, vec![])
                            .await?;
                        debug!("Stored message via append: {}", message_id);
                    }
                    lines.send(format!("{} OK APPEND completed", tag)).await?;
                }
            } else {
                let mut buffer = Vec::with_capacity(state.datalen);
                let mut bytes = append_data.as_bytes().to_vec();
                buffer.append(&mut bytes);

                state.data = Some(buffer);
            }
        } else {
            lines.send(format!("{} NO invalid state", tag)).await?;
        }
        Ok(())
    }
}

//! `iced` compatible version of the scrollbar theme.



use crate::{
    Theme as Collection,
    color::Color,
    border::Theme as Border,
};

use iced::{
    slider::{
        Handle, HandleShape, Style, StyleSheet,
    },
};

use super::{ Component, Serial, StateSerial };



#[derive(Clone, Copy, Debug)]
pub struct Theme {
    /// Active state.
    pub active: StateTheme,

    /// Hovered state.
    pub hovered: StateTheme,

    /// Dragging state.
    pub dragging: StateTheme,
}

impl Theme {
    /// Gets the background theme with the given key (if it exists).
    pub fn extract(theme: &Collection, name: String) -> Option<Self> {
        match theme.styles.get(&name) {
            Some(stylestr) => match theme.slider.get(&stylestr.0) {
                Some(serial) => {
                    // Destructure the serialized version.
                    let Serial { active, hovered, dragging } = serial;

                    // Get the active state theme.
                    let active = match StateTheme::active(theme, active.clone()) {
                        Some(t) => t,
                        _ => StateTheme::DEFAULT,
                    };

                    // Get the hovered state theme.
                    let hovered = match StateTheme::hovered(theme, hovered.clone()) {
                        Some(t) => t,
                        _ => active.clone(),
                    };

                    // Get the dragging state theme.
                    let dragging = match StateTheme::dragging(theme, dragging.clone()) {
                        Some(t) => t,
                        _ => hovered.clone(),
                    };

                    Some( Theme { active, hovered, dragging } )
                },

                _ => None,
            },

            _ => None,
        }
    }
}

impl StyleSheet for Theme {
    fn active(&self) -> Style {
        self.active.into()
    }

    fn hovered(&self) -> Style {
        self.hovered.into()
    }

    fn dragging(&self) -> Style {
        self.dragging.into()
    }
}



#[derive(Clone, Copy, Debug)]
pub struct StateTheme {
    /// Rail colors.
    pub colors: (Color, Color),

    /// Border of the handle theme.
    pub hborder: Border,

    /// Color of the handle.
    pub hcolor: Color,

    /// Handle shape.
    pub shape: HandleShape,
}

impl StateTheme {
    /// Default state theme.
    pub const DEFAULT: StateTheme = StateTheme { colors: (Color::WHITE, Color::BLACK), hborder: Border::DEFAULT, hcolor: Color::RED, shape: HandleShape::Circle { radius: 1.0 } };

    /// Gets the `StateTheme` from a defined serial.
    pub(self) fn defined(theme: &Collection, serial: StateSerial) -> Self {
        // Destructure the serial.
        let StateSerial { colors, hborder, hcolor, shape } = serial;

        // Get the colors.
        let colora = match theme.color.get(&colors.0) {
            Some(c) => *c,
            _ => Color::WHITE,
        };

        let colorb = match theme.color.get(&colors.1) {
            Some(c) => *c,
            _ => Color::BLACK,
        };

        let hcolor = match theme.color.get(&hcolor) {
            Some(c) => *c,
            _ => Color::BLACK,
        };

        // Get the border theme.
        let hborder = match Border::extract(theme, hborder) {
            Some(b) => b,
            _ => Border::DEFAULT,
        };

        StateTheme { colors: (colora, colorb), hborder, hcolor, shape: shape.convert() }
    }

    /// Gets the `StateTheme` from the active component.
    pub(self) fn active(theme: &Collection, component: Component) -> Option<Self> {
        match component {
            Component::Defined(serial) => Some( Self::defined(theme, serial) ),

            Component::Inherited(name) => match Theme::extract(theme, name) {
                Some(scrollbar) => Some( scrollbar.active.clone() ),
                _ => None,
            },

            Component::None => None,
        }
    }

    /// Gets the `StateTheme` from the hovered component.
    pub(self) fn hovered(theme: &Collection, component: Component) -> Option<Self> {
        match component {
            Component::Defined(serial) => Some( Self::defined(theme, serial) ),

            Component::Inherited(name) => match Theme::extract(theme, name) {
                Some(scrollbar) => Some( scrollbar.hovered.clone() ),
                _ => None,
            },

            Component::None => None,
        }
    }

    /// Gets the `StateTheme` from the dragging component.
    pub(self) fn dragging(theme: &Collection, component: Component) -> Option<Self> {
        match component {
            Component::Defined(serial) => Some( Self::defined(theme, serial) ),

            Component::Inherited(name) => match Theme::extract(theme, name) {
                Some(scrollbar) => Some( scrollbar.dragging.clone() ),
                _ => None,
            },

            Component::None => None,
        }
    }
}

impl core::convert::Into<Style> for StateTheme {
    fn into(self) -> Style {
        Style {
            rail_colors: (self.colors.0.into(), self.colors.1.into()),
            handle: Handle {
                shape: self.shape,
                color: self.hcolor.into(),
                border_width: self.hborder.width,
                border_color: self.hborder.color.into(),
            },
        }
    }
}

