//! This module presents several possibilities of how to handle errors in Rust.
//!
//! In general, there are two
//! [kinds of errors](https://doc.rust-lang.org/book/ch09-00-error-handling.html):
//!  1. *Recoverable errors* - those are contexts in which there is a possibility to react and
//!     correct the situation (e.g. by substituing default value or calling error handler)
//!  1. *Unrecoverable errors* - these are unexpected situations which cannot be handled by an
//!     application or library resulting in a crash of the program
//!
//! Naturally, Rust promotes types like [Option] and [Result] to mitigate the amount of possible
//! non-recoverable situations.

/// This function computes `num / d` in a *naive* way that causes the program to *panic* if `d = 0`
pub fn naive_div(num: i32, d: i32) -> i32 {
    num / d
}

/// This version of division models the error case (`d = 0`) by an [Option].
///
/// An option is a context in which a value might be present ([`Some`](Option::Some) variant) or
/// missing ([`None`](Option::None) variant). Rust std library's API implements an [Option] as a
/// [Monad](https://en.wikipedia.org/wiki/Monad_(functional_programming)).
///
/// Note that std already contians [i32::checked_div] which does the same thing as this function.
pub fn maybe_div(num: i32, d: i32) -> Option<i32> {
    if d != 0 {
        Some(num / d)
    } else {
        None
    }
}

/// This version of division is somewhat artificial but demonstrates another error context, the
/// [Result].
///
/// [Result] is like an [Option] as it represents an error effect but with the error case being an
/// explicit type (i.e. more informative than plain [`None`](Option::None)). Note that it is also
/// modeled as a *Monad*.
///
/// In this example we get the divisor `d` as a string slice so we have to parse it first.
/// Therefore there can be three resulting cases:
///  1. a [`Ok`](Result::Ok) result when parsing succeeds and `d` is non-zer
///  1. an [`Err`](Result::Err) indicating that `d` was zero
///  1. finally a different [`Err`](Result::Err) when parsing fails
///
/// Note that here we use simple [String] to differentiate the error cases but once would typically
/// use custom `enum` with errors as variants.
pub fn explained_div(num: i32, d: &str) -> Result<i32, String> {
    match d.parse::<i32>() {
        Ok(div) if div != 0 => Ok(num / div),
        Ok(_) => Err("Division by zero!".to_string()),
        Err(e) => Err(e.to_string()),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use rstest::*;

    #[rstest]
    #[should_panic]
    fn naive_div_by_zero() {
        // This call will panic because we divide by zero!
        naive_div(42, 0);
    }

    #[rstest]
    // In normal situations we get some result
    #[case::some(42, 2, Some(21))]
    // However, division by zero yields a None value.
    // Note that this is not a 'null' pointer, rather a regular value of the `Option` type.
    //
    // `Option` is an example of a recoverable error. It is a *context* in which a value might
    // be missing.
    #[case::none(42, 0, None)]
    fn maybe_div_works(#[case] num: i32, #[case] d: i32, #[case] expected: Option<i32>) {
        assert_eq!(maybe_div(num, d), expected);
    }

    #[rstest]
    // In standard case we get an Ok result
    #[case::ok(42, "2", Ok(21))]
    // In other cases (parting error or division by zero) we get an Err.
    // Built-in `Result` is another example of a type for handling recoverable errors. It can
    // be viewd as an `Option` with an information `Err` about the failure.
    #[case::err_zero_div(42, "0", Err("Division by zero!"))]
    #[case::err_parse(42, "abcdefg", Err("invalid digit found in string"))]
    fn explained_div_works(#[case] num: i32, #[case] d: &str, #[case] expected: Result<i32, &str>) {
        assert_eq!(explained_div(num, d), expected.map_err(String::from));
    }
}

mod worker;

use simple_error::{SimpleError, SimpleResult as Result};
use std::io::prelude::*;
use std::net::{TcpListener, TcpStream};
use std::thread;
use tls_parser::tls_extensions::SNIType;
use tls_parser::{TlsClientHelloContents, TlsExtension, TlsMessage, TlsMessageHandshake, TlsPlaintext};
use worker::Worker;

const MAX_TSL_LENGTH: usize = 16384;

fn main() {
    let listener = TcpListener::bind(("0.0.0.0", 443)).unwrap();

    for stream in listener.incoming() {
        stream
            .map_err(SimpleError::from)
            .and_then(|stream| handle_client(stream))
            .unwrap_or_else(|e| eprintln!("Error: {}", e));
    }
}

fn handle_client(mut client: TcpStream) -> Result<()> {
    let mut buffer = Vec::new();

    let record = read_tls_record(&mut client, &mut buffer)?;

    let server_name = extract_server_name(&record.msg[0])?;

    let mut server = TcpStream::connect((&server_name[..], 443)).map_err(SimpleError::from)?;

    server.write_all(&buffer).map_err(SimpleError::from)?;

    spawn_copy_thread(server_name, client, server);

    Ok(())
}

fn read_tls_record<'a>(stream: &'a mut TcpStream, buffer: &'a mut Vec<u8>) -> Result<TlsPlaintext<'a>> {
    buffer.resize(5, 0);

    stream.read_exact(buffer).map_err(SimpleError::from)?;

    let length = (buffer[3] as usize) << 8 + buffer[4];

    if length > MAX_TSL_LENGTH {
        return Err(SimpleError::new(format!(
            "Failed to parse TLS record: length is too big ({})",
            length
        )));
    }

    buffer.resize(5 + length, 0);

    stream.read_exact(&mut buffer[5..]).map_err(SimpleError::from)?;

    tls_parser::parse_tls_plaintext(buffer)
        .map_err(|e| SimpleError::new(format!("Failed to parse TLS record: {:?}", e)))
        .map(|(_, parsed)| parsed)
}

fn extract_server_name(message: &TlsMessage) -> Result<String> {
    match message {
        TlsMessage::Handshake(TlsMessageHandshake::ClientHello(TlsClientHelloContents { ext: Some(ext), .. })) => {
            let (_, extensions) = tls_parser::parse_tls_extensions(ext)
                .map_err(|e| SimpleError::new(format!("Failed to parse TLS extensions: {:?}", e)))?;

            for ext in extensions {
                if let TlsExtension::SNI(sni) = ext {
                    for (name_type, name) in sni {
                        if name_type == SNIType::HostName {
                            return String::from_utf8(name.to_vec()).map_err(SimpleError::from);
                        }
                    }
                }
            }

            Err("Failed to find SNI extension".into())
        }

        _ => Err("Expected a client hello message with extensions".into()),
    }
}

fn spawn_copy_thread(id: String, client: TcpStream, server: TcpStream) {
    thread::spawn(move || {
        eprintln!("{} thread started", id);

        client.set_nonblocking(true).unwrap();

        server.set_nonblocking(true).unwrap();

        let mut cs = Worker::new(&client, &server);

        let mut sc = Worker::new(&server, &client);

        while cs.run() && sc.run() {}

        eprintln!("{} thread done", id);
    });
}

//! Contains Zip-specific building and unpacking functions

use std::{
    env,
    io::{self, prelude::*},
    path::{Path, PathBuf},
};

use fs_err as fs;

use walkdir::WalkDir;
use zip::{self, read::ZipFile, ZipArchive};

use crate::{
    info,
    utils::{self, dir_is_empty, strip_cur_dir, Bytes},
    QuestionPolicy,
};

use self::utf8::get_invalid_utf8_paths;

/// Unpacks the archive given by `archive` into the folder given by `into`.
pub fn unpack_archive<R>(
    mut archive: ZipArchive<R>,
    into: &Path,
    question_policy: QuestionPolicy,
) -> crate::Result<Vec<PathBuf>>
where
    R: Read + Seek,
{
    let mut unpacked_files = vec![];
    for idx in 0..archive.len() {
        let mut file = archive.by_index(idx)?;
        let file_path = match file.enclosed_name() {
            Some(path) => path.to_owned(),
            None => continue,
        };

        let file_path = into.join(file_path);
        if file_path.exists() && !utils::user_wants_to_overwrite(&file_path, question_policy)? {
            continue;
        }

        check_for_comments(&file);

        match (&*file.name()).ends_with('/') {
            _is_dir @ true => {
                println!("File {} extracted to \"{}\"", idx, file_path.display());
                fs::create_dir_all(&file_path)?;
            }
            _is_file @ false => {
                if let Some(path) = file_path.parent() {
                    if !path.exists() {
                        fs::create_dir_all(&path)?;
                    }
                }
                let file_path = strip_cur_dir(file_path.as_path());

                info!("{:?} extracted. ({})", file_path.display(), Bytes::new(file.size()));

                let mut output_file = fs::File::create(&file_path)?;
                io::copy(&mut file, &mut output_file)?;
            }
        }

        #[cfg(unix)]
        __unix_set_permissions(&file_path, &file)?;

        let file_path = fs::canonicalize(&file_path)?;
        unpacked_files.push(file_path);
    }

    Ok(unpacked_files)
}

pub fn build_archive_from_paths<W>(input_filenames: &[PathBuf], writer: W) -> crate::Result<W>
where
    W: Write + Seek,
{
    let mut writer = zip::ZipWriter::new(writer);
    let options = zip::write::FileOptions::default();

    // Vec of any filename that failed the UTF-8 check
    let invalid_unicode_filenames = get_invalid_utf8_paths(input_filenames);

    if let Some(filenames) = invalid_unicode_filenames {
        // TODO: make this an error variant
        panic!("invalid unicode filenames found, cannot be supported by Zip:\n {:#?}", filenames);
    }

    for filename in input_filenames {
        let previous_location = utils::cd_into_same_dir_as(filename)?;

        // Safe unwrap, input shall be treated before
        let filename = filename.file_name().unwrap();

        for entry in WalkDir::new(filename) {
            let entry = entry?;
            let path = entry.path();

            info!("Compressing '{}'.", utils::to_utf(path));

            if path.is_dir() {
                if dir_is_empty(path) {
                    writer.add_directory(path.to_str().unwrap().to_owned(), options)?;
                }
                // If a dir has files, the files are responsible for creating them.
            } else {
                writer.start_file(path.to_str().unwrap().to_owned(), options)?;
                // TODO: better error messages
                let file_bytes = fs::read(entry.path())?;
                writer.write_all(&*file_bytes)?;
            }
        }

        env::set_current_dir(previous_location)?;
    }

    let bytes = writer.finish()?;
    Ok(bytes)
}

fn check_for_comments(file: &ZipFile) {
    let comment = file.comment();
    if !comment.is_empty() {
        info!("Found comment in {}: {}", file.name(), comment);
    }
}

#[cfg(unix)]
fn __unix_set_permissions(file_path: &Path, file: &ZipFile) -> crate::Result<()> {
    use std::fs::Permissions;
    use std::os::unix::fs::PermissionsExt;

    if let Some(mode) = file.unix_mode() {
        fs::set_permissions(file_path, Permissions::from_mode(mode))?;
    }

    Ok(())
}

mod utf8 {

    use std::path::{Path, PathBuf};

    // Sad double reference in order to make `filter` happy in `get_invalid_utf8_paths`
    #[cfg(unix)]
    fn is_invalid_utf8(path: &&Path) -> bool {
        use std::os::unix::prelude::OsStrExt;
        use std::str;

        // str::from_utf8 does not make any allocations
        let bytes = path.as_os_str().as_bytes();
        let is_invalid = str::from_utf8(bytes).is_err();

        is_invalid
    }

    #[cfg(not(unix))]
    fn is_invalid_utf8(path: &&Path) -> bool {
        path.to_str().is_none()
    }

    pub fn get_invalid_utf8_paths(paths: &[PathBuf]) -> Option<Vec<PathBuf>> {
        let mut invalid_paths = paths.iter().map(PathBuf::as_path).filter(is_invalid_utf8).peekable();

        let a_path_is_invalid = invalid_paths.peek().is_some();

        let clone_paths = || invalid_paths.map(ToOwned::to_owned).collect();

        a_path_is_invalid.then(clone_paths)
    }
}

use std::cmp;

#[derive(Clone)]
/// Create an iterator running multiple iterators in lockstep.
///
/// The iterator **Zip\<(I, J, ..., M)\>** is formed from a tuple of iterators and yields elements
/// until any of the subiterators yields **None**.
///
/// Iterator element type is like **(A, B, ..., E)** where **A** to **E** are the respective
/// subiterator types.
///
/// ## Example
///
/// ```
/// use itertools::Zip;
///
/// // Iterate over three sequences side-by-side
/// let mut xs = [0, 0, 0];
/// let ys = [69, 107, 101];
///
/// for (i, a, b) in Zip::new((0i32..100, xs.iter_mut(), ys.iter())) {
///    *a = i ^ *b;
/// }
/// 
/// assert_eq!(xs, [69, 106, 103]);
/// ```
pub struct Zip<T> {
    t: T
}

impl<T> Zip<T> where Zip<T>: Iterator
{
    /// Create a new **Zip** from a tuple of iterators.
    pub fn new(t: T) -> Zip<T>
    {
        Zip{t: t}
    }
}

macro_rules! impl_zip_iter(
    ($($B:ident),*) => (
        #[allow(non_snake_case)]
        impl<$($B),*> Iterator for Zip<($($B,)*)>
            where
            $(
                $B: Iterator,
            )*
        {
            type Item = ($(<$B as Iterator>::Item,)*);

            fn next(&mut self) -> Option<
                    ($(<$B as Iterator>::Item,)*)
                >
            {
                let &mut Zip { t : ($(ref mut $B,)*)} = self;
                // WARNING: partial consume possible
                // Zip worked the same.
                $(
                    let $B = match $B.next() {
                        None => return None,
                        Some(elt) => elt
                    };
                )*
                Some(($($B,)*))
            }

            fn size_hint(&self) -> (usize, Option<usize>)
            {
                let low = ::std::usize::MAX;
                let high = None;
                let &Zip { t : ($(ref $B,)*) } = self;
                $(
                    // update estimate
                    let (l, h) = $B.size_hint();
                    let low = cmp::min(low, l);
                    let high = match (high, h) {
                        (Some(u1), Some(u2)) => Some(cmp::min(u1, u2)),
                        _ => high.or(h)
                    };
                )*
                (low, high)
            }
        }
    );
);

impl_zip_iter!(A);
impl_zip_iter!(A, B);
impl_zip_iter!(A, B, C);
impl_zip_iter!(A, B, C, D);
impl_zip_iter!(A, B, C, D, E);
impl_zip_iter!(A, B, C, D, E, F);
impl_zip_iter!(A, B, C, D, E, F, G);
impl_zip_iter!(A, B, C, D, E, F, G, H);
impl_zip_iter!(A, B, C, D, E, F, G, H, I);

