            `Duration::is_{positive|negative|zero}`"
)]
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
pub enum Sign {
    /// A positive value.
    Positive = 1,

    /// A negative value.
    Negative = -1,

    /// A value that is exactly zero.
    Zero = 0,
}

#[cfg(serde)]
impl<'a> serde::Deserialize<'a> for Sign {
    #[inline(always)]
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'a>,
    {
        crate::serde::Sign::deserialize(deserializer)?
            .try_into()
            .map_err(serde::de::Error::custom)
    }
}
impl Default for Sign {
    /// `Sign` defaults to `Zero`.
    ///
    /// ```rust
    /// # use time::Sign;
    /// assert_eq!(Sign::default(), Sign::Zero);
    /// ```
    #[inline(always)]
    fn default() -> Self {
        Zero
    }
}

macro_rules! sign_mul {
    ($($type:ty),+ $(,)?) => {
        $(
            impl Mul<$type> for Sign {
                type Output = $type;

                #[allow(trivial_numeric_casts)]
                #[inline(always)]
                fn mul(self, rhs: $type) -> Self::Output {
                    (self as i8) as $type * rhs
                }
            }

            impl Mul<Sign> for $type {
                type Output = Self;

                #[inline(always)]
                fn mul(self, rhs: Sign) -> Self::Output {
                    rhs * self
                }
            }

            impl MulAssign<Sign> for $type {
                #[inline(always)]
                fn mul_assign(&mut self, rhs: Sign) {
                    if rhs.is_negative() {
                        *self = -*self;
                    }
                }
            }

            impl Div<Sign> for $type {
                type Output = Self;

                #[inline(always)]
                fn div(self, rhs: Sign) -> Self::Output {
                    self * rhs
                }
            }

            impl DivAssign<Sign> for $type {
                #[inline(always)]
                fn div_assign(&mut self, rhs: Sign) {
                    *self *= rhs
                }
            }
        )*
    };
}
sign_mul![i8, i16, i32, i64, i128, f32, f64];

impl Mul<Sign> for Sign {
    type Output = Self;

    #[inline]
    fn mul(self, rhs: Self) -> Self::Output {
        match (self, rhs) {
            (Zero, _) | (_, Zero) => Zero,
            (Positive, Positive) | (Negative, Negative) => Positive,
            (Positive, Negative) | (Negative, Positive) => Negative,
        }
    }
}

impl MulAssign<Sign> for Sign {
    #[inline(always)]
    fn mul_assign(&mut self, rhs: Self) {
        *self = *self * rhs;
    }
}

impl Div<Sign> for Sign {
    type Output = Self;

    #[inline(always)]
    fn div(self, rhs: Self) -> Self::Output {
        self * rhs
    }
}

impl DivAssign<Sign> for Sign {
    #[inline(always)]
    fn div_assign(&mut self, rhs: Self) {
        *self *= rhs
    }
}

impl Neg for Sign {
    type Output = Self;

    #[inline(always)]
    fn neg(self) -> Self::Output {
        self.negate()
    }
}

impl Not for Sign {
    type Output = Self;

    #[inline(always)]
    fn not(self) -> Self::Output {
        self.negate()
    }
}

impl Sign {
    /// Return the opposite of the current sign.
    ///
    /// ```rust
    /// # use time::Sign;
    /// assert_eq!(Sign::Positive.negate(), Sign::Negative);
    /// assert_eq!(Sign::Negative.negate(), Sign::Positive);
    /// assert_eq!(Sign::Zero.negate(), Sign::Zero);
    /// ```
    #[inline(always)]
    pub fn negate(self) -> Self {
        match self {
            Positive => Negative,
            Negative => Positive,
            Zero => Zero,
        }
    }

    /// Is the sign positive?
    ///
    /// ```rust
    /// # use time::Sign;
    /// assert!(Sign::Positive.is_positive());
    /// assert!(!Sign::Negative.is_positive());
    /// assert!(!Sign::Zero.is_positive());
    /// ```
    #[inline(always)]
    pub const fn is_positive(self) -> bool {
        self as u8 == Positive as u8
    }

    /// Is the sign negative?
    ///
    /// ```rust
    /// # use time::Sign;
    /// assert!(!Sign::Positive.is_negative());
    /// assert!(Sign::Negative.is_negative());
    /// assert!(!Sign::Zero.is_negative());
    /// ```
    #[inline(always)]
    pub const fn is_negative(self) -> bool {
        self as u8 == Negative as u8
    }

    /// Is the value exactly zero?
    ///
    /// ```rust
    /// # use time::Sign;
    /// assert!(!Sign::Positive.is_zero());
    /// assert!(!Sign::Negative.is_zero());
    /// assert!(Sign::Zero.is_zero());
    /// ```
    #[inline(always)]
    pub const fn is_zero(self) -> bool {
        self as u8 == Zero as u8
    }
}

#[cfg(test)]
mod test {
    use super::*;

    macro_rules! op_assign {
        ($a:ident $op:tt $b:ident) => {{
            let mut v = $a;
            v $op $b;
            v
        }};
    }

    #[test]
    fn default() {
        assert_eq!(Sign::default(), Zero);
    }

    #[test]
    fn sign_mul_int() {
        assert_eq!(Positive * 2, 2);
        assert_eq!(Negative * 2, -2);
        assert_eq!(Zero * 2, 0);
    }

    #[test]
    #[allow(clippy::float_cmp)]
    fn sign_mul_float() {
        assert_eq!(Positive * 2., 2.);
        assert_eq!(Negative * 2., -2.);
        assert_eq!(Zero * 2., 0.);
    }

    #[test]
    fn sign_mul_sign() {
        assert_eq!(Zero * Positive, Zero);
        assert_eq!(Zero * Negative, Zero);
        assert_eq!(Zero * Zero, Zero);
        assert_eq!(Positive * Zero, Zero);
        assert_eq!(Negative * Zero, Zero);
        assert_eq!(Positive * Positive, Positive);
        assert_eq!(Positive * Negative, Negative);
        assert_eq!(Negative * Positive, Negative);
        assert_eq!(Negative * Negative, Positive);
    }

    #[test]
    fn sign_mul_assign_sign() {
        assert_eq!(op_assign!(Zero *= Positive), Zero);
        assert_eq!(op_assign!(Zero *= Negative), Zero);
        assert_eq!(op_assign!(Zero *= Zero), Zero);
        assert_eq!(op_assign!(Positive *= Zero), Zero);
        assert_eq!(op_assign!(Negative *= Zero), Zero);
        assert_eq!(op_assign!(Positive *= Positive), Positive);
        assert_eq!(op_assign!(Positive *= Negative), Negative);
        assert_eq!(op_assign!(Negative *= Positive), Negative);
        assert_eq!(op_assign!(Negative *= Negative), Positive);
    }

    #[test]
    #[allow(clippy::eq_op)]
    fn sign_div_sign() {
        assert_eq!(Zero / Positive, Zero);
        assert_eq!(Zero / Negative, Zero);
        assert_eq!(Zero / Zero, Zero);
        assert_eq!(Positive / Zero, Zero);
        assert_eq!(Negative / Zero, Zero);
        assert_eq!(Positive / Positive, Positive);
        assert_eq!(Positive / Negative, Negative);
        assert_eq!(Negative / Positive, Negative);
        assert_eq!(Negative / Negative, Positive);
    }

    #[test]
    fn sign_div_assign_sign() {
        assert_eq!(op_assign!(Zero /= Positive), Zero);
        assert_eq!(op_assign!(Zero /= Negative), Zero);
        assert_eq!(op_assign!(Zero /= Zero), Zero);
        assert_eq!(op_assign!(Positive /= Zero), Zero);
        assert_eq!(op_assign!(Negative /= Zero), Zero);
        assert_eq!(op_assign!(Positive /= Positive), Positive);
        assert_eq!(op_assign!(Positive /= Negative), Negative);
        assert_eq!(op_assign!(Negative /= Positive), Negative);
        assert_eq!(op_assign!(Negative /= Negative), Positive);
    }

    #[test]
    fn neg() {
        assert_eq!(-Positive, Negative);
        assert_eq!(-Negative, Positive);
        assert_eq!(-Zero, Zero);
    }

    #[test]
    fn not() {
        assert_eq!(!Positive, Negative);
        assert_eq!(!Negative, Positive);
        assert_eq!(!Zero, Zero);
    }

    #[test]
    fn negate() {
        assert_eq!(Positive.negate(), Negative);
        assert_eq!(Negative.negate(), Positive);
        assert_eq!(Zero.negate(), Zero);
    }

    #[test]
    fn is_positive() {
        assert!(Positive.is_positive());
        assert!(!Negative.is_positive());
        assert!(!Zero.is_positive());
    }

    #[test]
    fn is_negative() {
        assert!(!Positive.is_negative());
        assert!(Negative.is_negative());
        assert!(!Zero.is_negative());
    }

    #[test]
    fn is_zero() {
        assert!(!Positive.is_zero());
        assert!(!Negative.is_zero());
        assert!(Zero.is_zero());
    }
}

use glow::*;
use sdl2::event::Event;
use std::fs::read;
use std::env;
use std::process;
fn main() {
    let args: Vec<String> = env::args().collect();
    let path: &str = &args[1];

    let bitty = match read(path) {
        Ok(data) => data,
        Err(_) => {
            println!("Error: Could not read '{}'", path);
            process::exit(1);
        }
    };
    let bitty = bitty.as_slice();
    let resolution = (bitty.len() as f32).sqrt().round();
    unsafe {
        // OpenGL context creation, SDL2 window setup
        let (gl, shader_version, window, mut event_pump, _context) = {
            let sdl = sdl2::init().unwrap();
            let video = sdl.video().unwrap();
            let gl_attr = video.gl_attr();
            gl_attr.set_context_profile(sdl2::video::GLProfile::Core);
            gl_attr.set_context_version(4, 0);
            let window = video
                .window("bitty", resolution as u32, resolution as u32)
                .opengl()
                .build()
                .unwrap();
            let context = window.gl_create_context().unwrap();
            let gl =
                glow::Context::from_loader_function(|s| video.gl_get_proc_address(s) as *const _);
            let event_pump = sdl.event_pump().unwrap();
            (gl, "#version 430", window, event_pump, context)
        };

        let vao = gl
            .create_vertex_array()
            .unwrap();
        gl.bind_vertex_array(Some(vao));

        let program = gl.create_program().expect("Render error: failed to create program");

        let (vert_shader, frag_shader) = (
            r#"
            const vec2 verts[6] = vec2[6](
                vec2(-1.0f,  1.0f),
                vec2(-1.0f, -1.0f),
                vec2( 1.0f, -1.0f),
                vec2(-1.0f,  1.0f),
                vec2( 1.0f, -1.0f),
                vec2( 1.0f,  1.0f)
            );
            void main() {
                vec2 pos = verts[gl_VertexID];
                gl_Position = vec4(pos, 0.0, 1.0);
            }
            "#, 
            r#"
            layout(std430, binding = 0) buffer data {
                uint bitty[];
            };
            uniform float res;
            uniform vec4 mouse;

            out vec4 col;
            void main(){
                vec2 crd = vec2(gl_FragCoord.x, -gl_FragCoord.y + res);
                float cell = res*(crd.y-1.0) + crd.x; 
                int byte = int(mod(cell, 4.0));
                int i = int(floor(cell/4.0));
                uint value;
                if(byte == 0){
                    value = (bitty[i])&0xff;
                }
                else if(byte==1){
                    value = (bitty[i]>>8)&0xff;
                }
                else if(byte==2){
                    value = (bitty[i]>>16)&0xff;
                }
                else if(byte==3){
                    value = (bitty[i]>>24)&0xff;
                }
                if(mouse.z==1.0){
                    value = (uint((mouse.x/res)*255.)==value) ? 255: 0;
                }
                col = vec4(float(value)/255.);
            }
            "#,
        );

        let shader_sources = [
            (glow::VERTEX_SHADER, vert_shader),
            (glow::FRAGMENT_SHADER, frag_shader),
        ];

        let mut shaders = Vec::with_capacity(shader_sources.len());
        for (shader_type, shader_source) in shader_sources.iter() {
            let shader = gl
                .create_shader(*shader_type)
                .unwrap();
            gl.shader_source(shader, &format!("{}\n{}", shader_version, shader_source));
            gl.compile_shader(shader);
            if !gl.get_shader_compile_status(shader) {
                panic!("Render error: failed to compile shader: {}", gl.get_shader_info_log(shader));
            }
            gl.attach_shader(program, shader);
            shaders.push(shader);
        }

        let data = gl.create_buffer().unwrap();
        gl.bind_buffer(SHADER_STORAGE_BUFFER, Some(data));
        gl.buffer_data_u8_slice(SHADER_STORAGE_BUFFER, bitty,  STATIC_DRAW);
        gl.bind_buffer_base(SHADER_STORAGE_BUFFER, 0, Some(data));
        gl.bind_buffer(SHADER_STORAGE_BUFFER, Some(data));


        gl.link_program(program);
        if !gl.get_program_link_status(program) {
            panic!("Render error: failed to link program: {}", gl.get_program_info_log(program));
        }

        let loc_res = gl.get_uniform_location(program, "res");
        let loc_mouse = gl.get_uniform_location(program, "mouse");

        for shader in shaders {
            gl.detach_shader(program, shader);
            gl.delete_shader(shader);
        }

        gl.use_program(Some(program));
        gl.clear_color(1.0, 0.0, 1.0, 1.0);

        let mut running = true;
        let mut mouse : [f32; 4] = [0.5*resolution, 0.5*resolution, 0.0, 0.0];

        while running {
            {
                for event in event_pump.poll_iter() {
                    match event {
                        Event::Quit { .. } => running = false,
                        Event::MouseButtonDown {mouse_btn, x, y, ..} => {
                            if let sdl2::mouse::MouseButton::Left = mouse_btn {
                                mouse = [x as f32, (-y as f32) + resolution, 1.0, mouse[3]];
                            };
                        },
                        Event::MouseButtonUp {mouse_btn, ..} => {
                            if let sdl2::mouse::MouseButton::Left = mouse_btn {
                                mouse[2] = 0.0;
                            };
                        },
                        Event::MouseMotion {mousestate, x, y, ..} => {
                            if mousestate.left() {
                                mouse = [x as f32, (-y as f32) + resolution, 1.0, mouse[3]];
                            }else{
                                mouse[2] = 0.0;
                            }
                        },
                        _ => {}
                    }
                }
            }

            gl.clear(COLOR_BUFFER_BIT);

            gl.uniform_1_f32(loc_res.as_ref(), resolution);
            gl.uniform_4_f32(loc_mouse.as_ref(), mouse[0], mouse[1], mouse[2], mouse[3]);

            gl.draw_arrays(glow::TRIANGLES, 0, 6);
            window.gl_swap_window();

            if !running {
                gl.delete_program(program);
                gl.delete_vertex_array(vao);
            }
        }
    }
}

///
/// Helper trait to convert struct values to the types returned by the parent trait getters.
///
pub trait TraitStructExtract<'a, T> {
    fn extract(&'a self) -> T;
}
///
/// Specialization that clones the struct field.
///
impl<'a, U: Clone> TraitStructExtract<'a, U> for U {
    #[inline(always)]
    fn extract(&'a self) -> U {
        self.clone()
    }
}
///
/// Specialization that borrows a reference to the struct field.
///
impl<'a, U> TraitStructExtract<'a, &'a U> for U {
    #[inline(always)]
    fn extract(&'a self) -> &'a U {
        self
    }
}
///
/// Specialization that extracts `Option<U>` as `Option<&U>`.
///
impl<'a, U> TraitStructExtract<'a, Option<&'a U>> for Option<U> {
    #[inline(always)]
    fn extract(&'a self) -> Option<&'a U> {
        self.as_ref()
    }
}

