        }
    };
    (@case $self:ident [$zero:expr] $field:ident &$type:ty) => {
        fn $field(&$self) -> &$type {
            &$zero.$field
        }
    };
    (@case $self:ident [$zero:expr] $field:ident $type:ty { $($body:tt)+ }) => {
