macro_rules! field_setter_decls {
    (@case $setter:ident $field:ident Option < HashMap < Option < LanguageTag > , $type:ty > >) => {
        fn $setter(
            self,
            $field: Option<$type>,
            language_tag: Option<LanguageTag>
        ) -> Self;
    };
    (@case $setter:ident $field:ident $type:ty) => {
        fn $setter(
            self,
            $field: $type
        ) -> Self;
    };
    // Main entry point
    (
        $(
            $setter:ident -> $field:ident[$($entry:tt)+],
        )+
    ) => {
        $(
            field_setter_decls![@case $setter $field $($entry)+];
        )+
    };
}

macro_rules! field_setters {
    (@case $self:ident [$zero:expr] $setter:ident $field:ident Option < HashMap < Option < LanguageTag > , $type:ty > >) => {
        fn $setter(
            mut $self,
            $field: Option<$type>,
            language_tag: Option<LanguageTag>
        ) -> Self {
            if let Some(temp) = $field {
                if $zero.$field.is_none() {
                    $zero.$field = Some(HashMap::new());
                }
                if let Some(ref mut hash_map) = $zero.$field {
                    hash_map.insert(language_tag, temp);
                }
            } else {
                let set_to_none =
                    if let Some(ref mut hash_map) = $zero.$field {
                        hash_map.remove(&language_tag);
                        hash_map.is_empty()
                    } else {
                        false
                    };
                if set_to_none {
                    $zero.$field = None;
                }
            }
            $self
        }
    };
    (@case $self:ident [$zero:expr] $setter:ident $field:ident $type:ty) => {
        fn $setter(
            mut $self,
            $field: $type
        ) -> Self {
            $zero.$field = $field;
            $self
        }
    };
    // Main entry point
    (
        $self:ident [$zero:expr] {
            $(
                $setter:ident -> $field:ident[$($entry:tt)+],
            )+
        }
    ) => {
        $(
            field_setters![@case $self [$zero] $setter $field $($entry)+];
        )+
    };
}

// only-x86_64
// compile-flags: -C target-feature=+avx2

#![feature(asm_const, asm_sym)]

use std::arch::asm;

fn main() {
    let mut foo = 0;
    let mut bar = 0;
    unsafe {
        // Bad register/register class

        asm!("{}", in(foo) foo);
        //~^ ERROR invalid register class `foo`: unknown register class
        asm!("", in("foo") foo);
        //~^ ERROR invalid register `foo`: unknown register
        asm!("{:z}", in(reg) foo);
        //~^ ERROR invalid asm template modifier for this register class
        asm!("{:r}", in(xmm_reg) foo);
        //~^ ERROR invalid asm template modifier for this register class
        asm!("{:a}", const 0);
        //~^ ERROR asm template modifiers are not allowed for `const` arguments
        asm!("{:a}", sym main);
        //~^ ERROR asm template modifiers are not allowed for `sym` arguments
        asm!("", in("ebp") foo);
        //~^ ERROR invalid register `ebp`: the frame pointer cannot be used as an operand
        asm!("", in("rsp") foo);
        //~^ ERROR invalid register `rsp`: the stack pointer cannot be used as an operand
        asm!("", in("ip") foo);
        //~^ ERROR invalid register `ip`: the instruction pointer cannot be used as an operand

        asm!("", in("st(2)") foo);
        //~^ ERROR register class `x87_reg` can only be used as a clobber, not as an input or output
        //~| ERROR `i32` cannot be used with this register class
        asm!("", in("mm0") foo);
        //~^ ERROR register class `mmx_reg` can only be used as a clobber, not as an input or output
        //~| ERROR `i32` cannot be used with this register class
        asm!("", in("k0") foo);
        //~^ ERROR register class `kreg0` can only be used as a clobber, not as an input or output
        //~| ERROR `i32` cannot be used with this register class
        asm!("", out("st(2)") _);
        asm!("", out("mm0") _);
        asm!("{}", in(x87_reg) foo);
        //~^ ERROR register class `x87_reg` can only be used as a clobber, not as an input or output
        //~| ERROR `i32` cannot be used with this register class
        asm!("{}", in(mmx_reg) foo);
        //~^ ERROR register class `mmx_reg` can only be used as a clobber, not as an input or output
        //~| ERROR `i32` cannot be used with this register class
        asm!("{}", out(x87_reg) _);
        //~^ ERROR register class `x87_reg` can only be used as a clobber, not as an input or output
        asm!("{}", out(mmx_reg) _);
        //~^ ERROR register class `mmx_reg` can only be used as a clobber, not as an input or output

        // Explicit register conflicts
        // (except in/lateout which don't conflict)

        asm!("", in("eax") foo, in("al") bar);
        //~^ ERROR register `al` conflicts with register `ax`
        //~| ERROR `i32` cannot be used with this register class
        asm!("", in("rax") foo, out("rax") bar);
        //~^ ERROR register `ax` conflicts with register `ax`
        asm!("", in("al") foo, lateout("al") bar);
        //~^ ERROR `i32` cannot be used with this register class
        //~| ERROR `i32` cannot be used with this register class
        asm!("", in("xmm0") foo, in("ymm0") bar);
        //~^ ERROR register `ymm0` conflicts with register `xmm0`
        asm!("", in("xmm0") foo, out("ymm0") bar);
        //~^ ERROR register `ymm0` conflicts with register `xmm0`
        asm!("", in("xmm0") foo, lateout("ymm0") bar);
    }
}

use crate::app::App;
use crate::colors::ColorScheme;
use crate::helpers::ID;
use crate::render::{DrawOptions, Renderable};
use ezgui::{Drawable, GeomBatch, GfxCtx, Line, Prerender, Text};
use geom::{Distance, Polygon, Pt2D};
use map_model::{LaneType, Map, Road, RoadID};
use std::cell::RefCell;

pub struct DrawRoad {
    pub id: RoadID,
    zorder: isize,

    draw_center_line: Drawable,
    label: RefCell<Option<Drawable>>,
}

impl DrawRoad {
    pub fn new(r: &Road, map: &Map, cs: &ColorScheme, prerender: &Prerender) -> DrawRoad {
        let mut draw = GeomBatch::new();
        let center = r.get_current_center(map);
        let width = Distance::meters(0.25);
        // If the road is a one-way (only parking and sidewalk on the off-side), draw a solid line
        // No center line at all if there's a shared left turn lane
        if r.children_backwards
            .iter()
            .all(|(_, lt)| *lt == LaneType::Parking || *lt == LaneType::Sidewalk)
        {
            draw.push(cs.road_center_line, center.make_polygons(width));
        } else if r.children_forwards.is_empty()
            || r.children_forwards[0].1 != LaneType::SharedLeftTurn
        {
            draw.extend(
                cs.road_center_line,
                center.dashed_lines(width, Distance::meters(2.0), Distance::meters(1.0)),
            );
        }

        DrawRoad {
            id: r.id,
            zorder: r.zorder,
            draw_center_line: prerender.upload(draw),
            label: RefCell::new(None),
        }
    }
}

impl Renderable for DrawRoad {
    fn get_id(&self) -> ID {
        ID::Road(self.id)
    }

    fn draw(&self, g: &mut GfxCtx, app: &App, opts: &DrawOptions) {
        g.redraw(&self.draw_center_line);

        if opts.label_roads {
            // Lazily calculate
            let mut label = self.label.borrow_mut();
            if label.is_none() {
                let mut batch = GeomBatch::new();
                let r = app.primary.map.get_r(self.id);

                let mut txt = Text::new().with_bg();
                txt.add(Line(r.get_name()));
                batch.append(
                    txt.render_to_batch(g.prerender)
                        .scale(0.1)
                        .centered_on(r.center_pts.middle()),
                );
                *label = Some(g.prerender.upload(batch));
            }
            // TODO Covered up sometimes. We could fork and force a different z value...
            g.redraw(label.as_ref().unwrap());
        }
    }

    fn get_outline(&self, map: &Map) -> Polygon {
        // Highlight the entire thing, not just an outline
        map.get_r(self.id).get_thick_polygon(map).unwrap()
    }

    fn contains_pt(&self, pt: Pt2D, map: &Map) -> bool {
        map.get_r(self.id)
            .get_thick_polygon(map)
            .unwrap()
            .contains_pt(pt)
    }

    fn get_zorder(&self) -> isize {
        self.zorder
    }
}

