                    let fresh0 = n_unicodes;
                    n_unicodes = n_unicodes + 1;
                    unicodes[fresh0 as usize] = strtol(p, &mut nextptr, 16i32) as i32;
                    p = nextptr;
                    skip_white(&mut p, endptr);
                }
