use crate::partition::PartitionID;
use std::{
    ffi::OsString,
    fmt::{self, Display, Formatter},
    fs::File,
    io::{self, BufRead, BufReader, Error, ErrorKind},
    os::unix::prelude::OsStringExt,
    path::{Path, PathBuf},
    str::FromStr,
};
#[derive(Debug, Default, Clone, Hash, Eq, PartialEq)]
pub struct MountInfo {
    pub source: PathBuf,
    pub dest: PathBuf,
    pub fstype: String,
    pub options: Vec<String>,
}

impl Display for MountInfo {
    fn fmt(&self, fmt: &mut Formatter) -> fmt::Result {
        write!(
            fmt,
            "{} {} {} {}",
            self.source.display(),
            self.dest.display(),
            self.fstype,
            if self.options.is_empty() {
                "defaults".into()
            } else {
                self.options.join(",")
            },
        )
    }
}

impl FromStr for MountInfo {
    type Err = io::Error;

    fn from_str(line: &str) -> Result<Self, Self::Err> {
        let mut parts = line.split_whitespace();

        fn map_err(why: &'static str) -> io::Error {
            Error::new(ErrorKind::InvalidData, why)
        }

        let source = parts.next().ok_or_else(|| map_err("missing source"))?;
        let dest = parts.next().ok_or_else(|| map_err("missing dest"))?;
        let fstype = parts.next().ok_or_else(|| map_err("missing type"))?;
        let options = parts.next().ok_or_else(|| map_err("missing options"))?;

        let _dump = parts.next().map_or(Ok(0), |value| {
            value
                .parse::<i32>()
                .map_err(|_| map_err("dump value is not a number"))
        })?;

        let _pass = parts.next().map_or(Ok(0), |value| {
            value
                .parse::<i32>()
                .map_err(|_| map_err("pass value is not a number"))
        })?;

        let path = Self::parse_value(source)?;
        let path = path
            .to_str()
            .ok_or_else(|| map_err("non-utf8 paths are unsupported"))?;

        let source = if path.starts_with("/dev/disk/by-") {
            Self::fetch_from_disk_by_path(path)?
        } else {
            PathBuf::from(path)
        };

        let path = Self::parse_value(dest)?;
        let path = path
            .to_str()
            .ok_or_else(|| map_err("non-utf8 paths are unsupported"))?;

        let dest = PathBuf::from(path);

        Ok(MountInfo {
            source,
            dest,
            fstype: fstype.to_owned(),
            options: options.split(',').map(String::from).collect(),
        })
    }
}

impl MountInfo {
    /// Attempt to parse a `/proc/mounts`-like line.

    fn fetch_from_disk_by_path(path: &str) -> io::Result<PathBuf> {
        PartitionID::from_disk_by_path(path)
            .map_err(|why| Error::new(ErrorKind::InvalidData, format!("{}: {}", path, why)))?
            .get_device_path()
            .ok_or_else(|| {
                Error::new(
                    ErrorKind::NotFound,
                    format!("device path for {} was not found", path),
                )
            })
    }

    fn parse_value(value: &str) -> io::Result<OsString> {
        let mut ret = Vec::new();

        let mut bytes = value.bytes();
        while let Some(b) = bytes.next() {
            match b {
                b'\\' => {
                    let mut code = 0;
                    for _i in 0 .. 3 {
                        if let Some(b) = bytes.next() {
                            code *= 8;
                            code += u32::from_str_radix(&(b as char).to_string(), 8)
                                .map_err(|err| Error::new(ErrorKind::Other, err))?;
                        } else {
                            return Err(Error::new(ErrorKind::Other, "truncated octal code"));
                        }
                    }
                    ret.push(code as u8);
                }
                _ => {
                    ret.push(b);
                }
            }
        }

        Ok(OsString::from_vec(ret))
    }
}

/// Iteratively parse the `/proc/mounts` file.
pub struct MountIter<R> {
    file: R,
    buffer: String,
}

impl MountIter<BufReader<File>> {
    pub fn new() -> io::Result<Self> {
        Self::new_from_file("/proc/mounts")
    }

    /// Read mounts from any mount-tab-like file.
    pub fn new_from_file<P: AsRef<Path>>(path: P) -> io::Result<Self> {
        Ok(Self::new_from_reader(BufReader::new(File::open(path)?)))
    }
}

impl<R: BufRead> MountIter<R> {
    /// Read mounts from any in-memory buffer.
    pub fn new_from_reader(readable: R) -> Self {
        Self {
            file: readable,
            buffer: String::with_capacity(512),
        }
    }

    /// Iterator-based variant of `source_mounted_at`.
    ///
    /// Returns true if the `source` is mounted at the given `dest`.
    ///
    /// Due to iterative parsing of the mount file, an error may be returned.
    pub fn source_mounted_at<D: AsRef<Path>, P: AsRef<Path>>(
        source: D,
        path: P,
    ) -> io::Result<bool> {
        let source = source.as_ref();
        let path = path.as_ref();

        let mut is_found = false;

        let mounts = MountIter::new()?;
        for mount in mounts {
            let mount = mount?;
            if mount.source == source {
                is_found = mount.dest == path;
                break;
            }
        }

        Ok(is_found)
    }
}

impl<R: BufRead> Iterator for MountIter<R> {
    type Item = io::Result<MountInfo>;

    fn next(&mut self) -> Option<Self::Item> {
        loop {
            self.buffer.clear();
            match self.file.read_line(&mut self.buffer) {
                Ok(read) if read == 0 => return None,
                Ok(_) => {
                    let line = self.buffer.trim_start();
                    if !(line.starts_with('#') || line.is_empty()) {
                        return Some(MountInfo::from_str(line));
                    }
                }
                Err(why) => return Some(Err(why)),
            }
        }
    }
}

use ansi_term::{ANSIString, ANSIStrings, Colour, Style};
#[cfg(feature = "crossterm")]
use crossterm::{cursor, terminal, ClearType, InputEvent, KeyEvent, RawScreen};
use std::io::Write;
use sublime_fuzzy::best_match;

pub enum SelectionResult {
    Selected(String),
    Edit(String),
    NoSelection,
}

pub fn interactive_fuzzy_search(lines: &Vec<&str>, max_results: usize) -> SelectionResult {
    #[derive(PartialEq)]
    enum State {
        Selecting,
        Quit,
        Selected(String),
        Edit(String),
    }
    let mut state = State::Selecting;
    #[cfg(feature = "crossterm")]
    {
        if let Ok(_raw) = RawScreen::into_raw_mode() {
            // User input for search
            let mut searchinput = String::new();
            let mut selected = 0;

            let mut cursor = cursor();
            let _ = cursor.hide();
            let input = crossterm::input();
            let mut sync_stdin = input.read_sync();

            while state == State::Selecting {
                let mut selected_lines = fuzzy_search(&searchinput, &lines, max_results);
                let num_lines = selected_lines.len();
                paint_selection_list(&selected_lines, selected);
                if let Some(ev) = sync_stdin.next() {
                    match ev {
                        InputEvent::Keyboard(k) => match k {
                            KeyEvent::Esc | KeyEvent::Ctrl('c') => {
                                state = State::Quit;
                            }
                            KeyEvent::Up => {
                                if selected > 0 {
                                    selected -= 1;
                                }
                            }
                            KeyEvent::Down => {
                                if selected + 1 < selected_lines.len() {
                                    selected += 1;
                                }
                            }
                            KeyEvent::Char('\n') => {
                                state = if selected_lines.len() > 0 {
                                    State::Selected(selected_lines.remove(selected).text)
                                } else {
                                    State::Edit("".to_string())
                                };
                            }
                            KeyEvent::Char('\t') | KeyEvent::Right => {
                                state = if selected_lines.len() > 0 {
                                    State::Edit(selected_lines.remove(selected).text)
                                } else {
                                    State::Edit("".to_string())
                                };
                            }
                            KeyEvent::Char(ch) => {
                                searchinput.push(ch);
                                selected = 0;
                            }
                            KeyEvent::Backspace => {
                                searchinput.pop();
                                selected = 0;
                            }
                            _ => {}
                        },
                        _ => {}
                    }
                }
                if num_lines > 0 {
                    cursor.move_up(num_lines as u16);
                }
            }
            let (_x, y) = cursor.pos();
            let _ = cursor.goto(0, y - 1);
            let _ = cursor.show();
            let _ = RawScreen::disable_raw_mode();
        }
        terminal().clear(ClearType::FromCursorDown).unwrap();
    }
    match state {
        State::Selected(line) => SelectionResult::Selected(line),
        State::Edit(line) => SelectionResult::Edit(line),
        _ => SelectionResult::NoSelection,
    }
}

pub struct Match {
    text: String,
    char_matches: Vec<(usize, usize)>,
}

pub fn fuzzy_search(searchstr: &str, lines: &Vec<&str>, max_results: usize) -> Vec<Match> {
    if searchstr.is_empty() {
        return lines
            .iter()
            .take(max_results)
            .map(|line| Match {
                text: line.to_string(),
                char_matches: Vec::new(),
            })
            .collect();
    }

    let mut matches = lines
        .iter()
        .enumerate()
        .map(|(idx, line)| (idx, best_match(&searchstr, line)))
        .filter(|(_i, m)| m.is_some())
        .map(|(i, m)| (i, m.unwrap()))
        .collect::<Vec<_>>();
    matches.sort_by(|a, b| b.1.score().cmp(&a.1.score()));

    let results: Vec<Match> = matches
        .iter()
        .take(max_results)
        .map(|(i, m)| Match {
            text: lines[*i].to_string(),
            char_matches: m.continuous_matches(),
        })
        .collect();
    results
}

#[cfg(feature = "crossterm")]
fn highlight(textmatch: &Match, normal: Style, highlighted: Style) -> Vec<ANSIString> {
    let text = &textmatch.text;
    let mut ansi_strings = vec![];
    let mut idx = 0;
    for (match_idx, len) in &textmatch.char_matches {
        ansi_strings.push(normal.paint(&text[idx..*match_idx]));
        idx = match_idx + len;
        ansi_strings.push(highlighted.paint(&text[*match_idx..idx]));
    }
    if idx < text.len() {
        ansi_strings.push(normal.paint(&text[idx..text.len()]));
    }
    ansi_strings
}

#[cfg(feature = "crossterm")]
fn paint_selection_list(lines: &Vec<Match>, selected: usize) {
    let terminal = terminal();
    let size = terminal.terminal_size();
    let width = size.0 as usize;
    let cursor = cursor();
    let (_x, y) = cursor.pos();
    for (i, line) in lines.iter().enumerate() {
        let _ = cursor.goto(0, y + (i as u16));
        let (style, highlighted) = if selected == i {
            (Colour::White.normal(), Colour::Cyan.normal())
        } else {
            (Colour::White.dimmed(), Colour::Cyan.normal())
        };
        let mut ansi_strings = highlight(line, style, highlighted);
        for _ in line.text.len()..width {
            ansi_strings.push(style.paint(' '.to_string()));
        }
        println!("{}", ANSIStrings(&ansi_strings));
    }
    let _ = cursor.goto(0, y + (lines.len() as u16));
    print!(
        "{}",
        Colour::Blue.paint("[ESC to quit, Enter to execute, Tab to edit]")
    );

    let _ = std::io::stdout().flush();
    // Clear additional lines from previous selection
    terminal.clear(ClearType::FromCursorDown).unwrap();
}

