extern crate lockfree;

use lockfree::{
    map::{Map as LfMap, Preview},
    stack::Stack as LfStack,
};
use std::{
    collections::{hash_map::RandomState, HashMap},
    hash::{BuildHasher, Hash, Hasher},
    sync::{Arc, Mutex},
    thread,
    time::{Duration, Instant},
};

fn hash_of(data: &[u8], state: &RandomState) -> u64 {
    let mut hasher = state.build_hasher();
    data.hash(&mut hasher);
    hasher.finish()
}

fn mine_hash(init: &mut Vec<u8>, req: Requirement, state: &RandomState) {
    while hash_of(&init[..], state) % req.divisor != req.remaining {
        let mut i = 0;
        let mut carry = true;

        while carry {
            if i >= init.len() {
                init.push(1);
            } else {
                let (new_val, new_carry) = init[i].overflowing_add(1);
                carry = new_carry;
                init[i] = new_val;
                i += 1;
            }
        }
    }
}

fn measure<S>(nthread: u64, nhash: u64, ndiv: u64) -> Duration
where
    S: Storage + Send + Sync + 'static,
{
    let mut threads = Vec::with_capacity(nthread as usize);

    let storage = Arc::new(S::default());
    let state = RandomState::default();

    let then = Instant::now();

    for i in 0 .. nthread {
        let storage = storage.clone();
        let state = state.clone();
        threads.push(thread::spawn(move || {
            let start = i * nhash / nthread;
            let end = if i + 1 == nthread {
                nhash
            } else {
                (i + 1) * nhash / nthread
            };

            for j in start .. end {
                let mut data = Vec::with_capacity((i + j) as usize);

                for n in 0 .. i + j {
                    data.push(n as u8);
                }

                let divisor = i / ndiv + 1;
                let remaining = j % divisor;
                mine_hash(
                    &mut data,
                    Requirement { divisor, remaining },
                    &state,
                );

                storage.add(Requirement { divisor, remaining }, data.into())
            }
        }))
    }

    for thread in threads {
        thread.join().expect("thread failed");
    }

    let ret = then.elapsed();

    ret
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Hash, PartialOrd, Ord)]
struct Requirement {
    divisor: u64,
    remaining: u64,
}

trait Storage: Default {
    fn add(&self, req: Requirement, data: Arc<[u8]>);
}

impl Storage for LfMap<Requirement, LfStack<Arc<[u8]>>> {
    fn add(&self, req: Requirement, data: Arc<[u8]>) {
        let mut cache = Some(data);

        self.insert_with(req, |_, _, found| {
            let data = match cache.take() {
                Some(data) => data,
                None => return Preview::Discard,
            };

            match found {
                Some((_, stack)) => {
                    stack.push(data);
                    Preview::Discard
                },

                None => {
                    let stack = LfStack::new();
                    stack.push(data.clone());
                    cache = Some(data);
                    Preview::New(stack)
                },
            }
        });
    }
}

impl Storage for Mutex<HashMap<Requirement, Vec<Arc<[u8]>>>> {
    fn add(&self, req: Requirement, data: Arc<[u8]>) {
        let mut map = self.lock().unwrap();

        map.entry(req).or_insert(Vec::new()).push(data);
    }
}

fn main() {
    println!("A program simulating a hash miner.");

    const NHASH: u64 = 0x2000;

    for &nthread in &[2, 4, 8, 16, 32, 64, 128] {
        println!();

        let mut mutexed = Duration::default();
        let mut lockfree = Duration::default();

        for i in 0x40 .. 0x48 {
            mutexed += measure::<Mutex<_>>(nthread, NHASH, i);
            lockfree += measure::<LfMap<_, _>>(nthread, NHASH, i);
        }

        println!(
            "Mutexed structures with {} threads total time: {:?}",
            nthread, mutexed
        );
        println!(
            "Lockfree structures with {} threads total time: {:?}",
            nthread, lockfree
        );
    }
}

use super::Primitive;

/// Additional methods for byte buffers.
pub trait BufExt {
    fn push_val<T: Primitive>(&mut self, value: T);
    fn push_int(&mut self, value: i32);
    fn push_float(&mut self, value: f32);
    fn push_decimal(&mut self, value: f32);
    fn push_hex(&mut self, value: u8);
    fn push_hex_u16(&mut self, value: u16);
}

impl BufExt for Vec<u8> {
    #[inline]
    fn push_val<T: Primitive>(&mut self, value: T) {
        value.write(self);
    }

    #[inline]
    fn push_int(&mut self, value: i32) {
        self.extend(itoa::Buffer::new().format(value).as_bytes());
    }

    #[inline]
    fn push_float(&mut self, value: f32) {
        // Don't write the decimal point if we don't need it.
        // Also, integer formatting is way faster.
        if value as i32 as f32 == value {
            self.push_int(value as i32);
        } else {
            self.push_decimal(value);
        }
    }

    /// Like `push_float`, but forces the decimal point.
    #[inline]
    fn push_decimal(&mut self, value: f32) {
        if value == 0.0 || (value.abs() > 1e-6 && value.abs() < 1e12) {
            self.extend(ryu::Buffer::new().format(value).as_bytes());
        } else {
            #[inline(never)]
            fn write_extreme(buf: &mut Vec<u8>, value: f32) {
                use std::io::Write;
                write!(buf, "{}", value).unwrap();
            }

            write_extreme(self, value);
        }
    }

    #[inline]
    fn push_hex(&mut self, value: u8) {
        fn hex(b: u8) -> u8 {
            if b < 10 { b'0' + b } else { b'A' + (b - 10) }
        }

        self.push(hex(value >> 4));
        self.push(hex(value & 0xF));
    }

    #[inline]
    fn push_hex_u16(&mut self, value: u16) {
        self.push_hex((value >> 8) as u8);
        self.push_hex(value as u8);
    }
}

