///
/// [`futures-channel`'s documentation]: https://docs.rs/futures-channel-preview/0.3.0-alpha.16/futures_channel/mpsc/fn.channel.html
pub fn new<D>(buf: usize) -> (Sender<D>, Receiver<D>) {
    let (sender, receiver) = mpsc::channel(buf);

    (Sender::new(buf, sender), Receiver::new(buf, receiver))
}

#[derive(Debug)]
/// A wrapper around a [`mpsc::Sender`] that stores its state
/// after sending data, closing the channel or disconnecting
/// itself.
///
/// [`mpsc::Sender`]: https://rust-lang-nursery.github.io/futures-api-docs/0.3.0-alpha.15/futures/channel/mpsc/struct.Sender.html
pub struct Sender<D> {
    /// The size of the buffer (as it was provided to
    /// [`bounded`])
    ///
    /// [`bounded`]: ../fn.bounded.html
    pub buf: usize,
    /// Whether the channel has been closed.
    pub closed: bool,
    /// Whether the sender has disconnected itself from the
    /// channel.
    pub disconnected: bool,
    sender: FutSender<D>,
}

#[derive(Debug)]
/// A wrapper around a [`mpsc::Receiver`] that stores its
/// state after trying to receive data or closing the channel.
///
/// [`mpsc::Receiver`]: https://rust-lang-nursery.github.io/futures-api-docs/0.3.0-alpha.15/futures/channel/mpsc/struct.Receiver.html
pub struct Receiver<D> {
    /// The size of the buffer (as it was provided to
    /// [`bounded`])
    ///
    /// [`bounded`]: ../fn.bounded.html
    pub buf: usize,
    /// Whether the channel has been closed.
    pub closed: bool,
    receiver: Option<FutReceiver<D>>,
}

impl<D> Sender<D> {
    pub(crate) fn new(buf: usize, sender: FutSender<D>) -> Sender<D> {
        Sender {
            buf,
            closed: false,
            disconnected: false,
            sender,
        }
    }

    /// Sends `data` over the channel, returning `Ok(())` if
    /// it has been successfully sent, or either
    /// `Err(SendError::Full)` if the channel's buffer is full,
    /// `Err(SendError::Disconnected)` if the  sender has
    /// disconnected itself from the channel or
    /// `Err(SendError::Closed)` if the channel has been closed.
    pub fn send(&mut self, data: D) -> Result<(), SendError<D>> {
        if self.disconnected {
            return Err(SendError::Disconnected(data));
        } else if self.closed {
            return Err(SendError::Closed(data));
        } else if self.sender.is_closed() {
            self.closed = true;
            return Err(SendError::Closed(data));
        }

        match self.sender.try_send(data) {
            Ok(()) => Ok(()),
            Err(err) => {
                if err.is_disconnected() {
                    self.closed = true;
                    Err(SendError::Closed(err.into_inner()))
                } else if err.is_full() {
                    Err(SendError::Full(err.into_inner()))
                } else {
                    unreachable!();
                }
            }
        }
    }

    /// Tries to disconnect the sender from the channel,
    /// returning `Ok(())` if it succeeded, or either
    /// `Err(DiconnectError::Disconnected)` if the sender
    /// already disconnected itself, or
    /// `Err(DisconnectError::Closed)` if the channel was
    /// already closed.
    pub fn disconnect(&mut self) -> Result<(), DisconnectError> {
        if self.disconnected {
            Err(DisconnectError::Disconnected)
        } else if self.closed {
            Err(DisconnectError::Closed)
        } else if self.sender.is_closed() {
            self.closed = true;
            Err(DisconnectError::Closed)
        } else {
            self.sender.disconnect();
            self.disconnected = true;
            Ok(())
        }
    }

    /// Tries to close the channel, returning `Ok(())` if it
    /// succeeded, or either `Err(CloseError::Disconnected)`
    /// if the sender already disconnected itself, or
    /// `Err(CloseError::Closed)` if the channel was already
    /// closed.
    pub fn close(&mut self) -> Result<(), CloseError> {
        if self.disconnected {
            Err(CloseError::Disconnected)
        } else if self.closed {
            Err(CloseError::Closed)
        } else if self.sender.is_closed() {
            self.closed = true;
            Err(CloseError::Closed)
        } else {
            self.sender.close_channel();
            self.closed = true;
            Ok(())
        }
    }
}

impl<D> Receiver<D> {
    pub(crate) fn new(buf: usize, receiver: FutReceiver<D>) -> Receiver<D> {
        Receiver {
            buf,
            closed: false,
            receiver: Some(receiver),
        }
    }

    /// Tries to receive a message over the channel, returning
    /// `Ok(D)` if it has received one, and either
    /// `Err(ReceiveError::Empty)` if it hasn't or
    /// `Err(ReceiveError::Closed)` if the channel has been
    /// closed.
    pub fn try_recv(&mut self) -> Result<D, ReceiveError> {
        if let Some(ref mut receiver) = self.receiver {
            match receiver.try_next() {
                Ok(Some(data)) => Ok(data),
                Ok(None) => {
                    self.receiver = None;
                    self.closed = true;
                    Err(ReceiveError::Closed)
                }
                Err(_) => Err(ReceiveError::Empty),
            }
        } else {
            Err(ReceiveError::Closed)
        }
    }

    /// Tries to close the channel, returning `Ok(())` if it
    /// succeeded, or `Err(CloseError::Closed)` if the channel
    /// was already closed.
    pub fn close(&mut self) -> Result<(), CloseError> {
        if self.closed {
            Err(CloseError::Closed)
        } else if let Some(ref mut receiver) = self.receiver {
            receiver.close();
            self.closed = true;
            Ok(())
        } else {
            unreachable!();
        }
    }
}

impl<D> Unpin for Receiver<D> {}

impl<D> Sink<D> for Sender<D> {
    // FIXME: -`()` +`D` (the issue being that `poll_ready`,
    //   `poll_flush` and `poll_close` can't return `D` since
    //   they don't get any data in the first place).
    type SinkError = SendError<()>;

    fn poll_ready(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Result<(), SendError<()>>> {
        let receiver = self.get_mut();
        Pin::new(&mut receiver.sender).poll_ready(cx).map_err(|_| {
            if receiver.disconnected {
                SendError::Disconnected(())
            } else if receiver.closed {
                SendError::Closed(())
            } else {
                receiver.closed = true;
                SendError::Closed(())
            }
        })
    }

    fn start_send(self: Pin<&mut Self>, msg: D) -> Result<(), SendError<()>> {
        let receiver = self.get_mut();
        Pin::new(&mut receiver.sender).start_send(msg).map_err(|_| {
            if receiver.disconnected {
                SendError::Disconnected(())
            } else if receiver.closed {
                SendError::Closed(())
            } else {
                receiver.closed = true;
                SendError::Closed(())
            }
        })
    }

    fn poll_flush(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Result<(), SendError<()>>> {
        let receiver = self.get_mut();
        Pin::new(&mut receiver.sender).poll_flush(cx).map_err(|_| {
            if receiver.disconnected {
                SendError::Disconnected(())
            } else if receiver.closed {
                SendError::Closed(())
            } else {
                receiver.closed = true;
                SendError::Closed(())
            }
        })
    }

    fn poll_close(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Result<(), SendError<()>>> {
        let receiver = self.get_mut();
        Pin::new(&mut receiver.sender).poll_close(cx).map_err(|_| {
            if receiver.disconnected {
                SendError::Disconnected(())
            } else if receiver.closed {
                SendError::Closed(())
            } else {
                receiver.closed = true;
                SendError::Closed(())
            }
        })
    }
}

impl<D> FusedStream for Receiver<D> {
    fn is_terminated(&self) -> bool {
        self.closed
    }
}

impl<D> Stream for Receiver<D> {
    type Item = D;

    fn poll_next(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Option<D>> {
        if let Some(ref mut receiver) = self.receiver {
            match Pin::new(receiver).poll_next(cx) {
                Poll::Ready(None) => {
                    self.receiver = None;
                    self.closed = true;
                    Poll::Ready(None)
                }
                poll => poll,
            }
        } else if self.closed {
            Poll::Ready(None)
        } else {
            unreachable!();
        }
    }
}

impl<D> Clone for Sender<D> {
    fn clone(&self) -> Sender<D> {
        Sender {
            sender: self.sender.clone(),
            ..*self
        }
    }
}

use crate::macos::ioapic::IoApic;
use crate::macos::vcpu::*;
use crate::vm::HypervisorResult;
use crate::vm::{BootInfo, Parameter, Vm};
use libc;
use libc::c_void;
use log::debug;
use std::net::Ipv4Addr;
use std::path::Path;
use std::path::PathBuf;
use std::ptr;
use std::ptr::read_volatile;
use std::sync::{Arc, Mutex};
use xhypervisor::{create_vm, map_mem, unmap_mem, MemPerm};

pub struct Uhyve {
	offset: u64,
	entry_point: u64,
	mem_size: usize,
	guest_mem: *mut c_void,
	num_cpus: u32,
	path: PathBuf,
	boot_info: *const BootInfo,
	ioapic: Arc<Mutex<IoApic>>,
	verbose: bool,
}

impl std::fmt::Debug for Uhyve {
	fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
		f.debug_struct("Uhyve")
			.field("entry_point", &self.entry_point)
			.field("mem_size", &self.mem_size)
			.field("guest_mem", &self.guest_mem)
			.field("num_cpus", &self.num_cpus)
			.field("path", &self.path)
			.field("boot_info", &self.boot_info)
			.field("ioapic", &self.ioapic)
			.field("verbose", &self.verbose)
			.finish()
	}
}

impl Uhyve {
	pub fn new(kernel_path: PathBuf, specs: &Parameter<'_>) -> HypervisorResult<Uhyve> {
		let mem = unsafe {
			libc::mmap(
				std::ptr::null_mut(),
				specs.mem_size,
				libc::PROT_READ | libc::PROT_WRITE,
				libc::MAP_PRIVATE | libc::MAP_ANON | libc::MAP_NORESERVE,
				-1,
				0,
			)
		};

		assert_ne!(libc::MAP_FAILED, mem, "mmap failed");

		debug!("Allocate memory for the guest at 0x{:x}", mem as usize);

		debug!("Create VM...");
		create_vm()?;

		debug!("Map guest memory...");
		unsafe {
			map_mem(
				std::slice::from_raw_parts(mem as *mut u8, specs.mem_size),
				0,
				&MemPerm::ExecAndWrite,
			)?;
		}

		assert!(specs.gdbport.is_none(), "gdbstub is not supported on macos");

		let hyve = Uhyve {
			offset: 0,
			entry_point: 0,
			mem_size: specs.mem_size,
			guest_mem: mem,
			num_cpus: specs.num_cpus,
			path: kernel_path,
			boot_info: ptr::null(),
			ioapic: Arc::new(Mutex::new(IoApic::new())),
			verbose: specs.verbose,
		};

		hyve.init_guest_mem();

		Ok(hyve)
	}
}

impl Vm for Uhyve {
	fn verbose(&self) -> bool {
		self.verbose
	}

	fn set_offset(&mut self, offset: u64) {
		self.offset = offset;
	}

	fn get_offset(&self) -> u64 {
		self.offset
	}

	fn set_entry_point(&mut self, entry: u64) {
		self.entry_point = entry;
	}

	fn get_entry_point(&self) -> u64 {
		self.entry_point
	}

	fn num_cpus(&self) -> u32 {
		self.num_cpus
	}

	fn guest_mem(&self) -> (*mut u8, usize) {
		(self.guest_mem as *mut u8, self.mem_size)
	}

	fn kernel_path(&self) -> &Path {
		self.path.as_path()
	}

	fn create_cpu(&self, id: u32) -> HypervisorResult<UhyveCPU> {
		Ok(UhyveCPU::new(
			id,
			self.path.clone(),
			self.guest_mem as usize,
			self.ioapic.clone(),
		))
	}

	fn get_ip(&self) -> Option<Ipv4Addr> {
		None
	}

	fn get_gateway(&self) -> Option<Ipv4Addr> {
		None
	}

	fn get_mask(&self) -> Option<Ipv4Addr> {
		None
	}

	fn set_boot_info(&mut self, header: *const BootInfo) {
		self.boot_info = header;
	}

	fn cpu_online(&self) -> u32 {
		if self.boot_info.is_null() {
			0
		} else {
			unsafe { read_volatile(&(*self.boot_info).cpu_online) }
		}
	}
}

impl Drop for Uhyve {
	fn drop(&mut self) {
		debug!("Drop virtual machine");

		unmap_mem(0, self.mem_size).unwrap();

		unsafe {
			libc::munmap(self.guest_mem, self.mem_size);
		}
	}
}

unsafe impl Send for Uhyve {}
unsafe impl Sync for Uhyve {}

use crate::{ config::Config, error::Result };
use ezexec::{ ExecBuilder, lookup::Shell };


/// Opens a `shell` session with the given environment set
#[derive(Debug)]
pub struct ShellSession {
    /// The underlying raw command
    exec: ExecBuilder
}
impl ShellSession {
    /// Creates a new `shell` session with `config` as environment
    pub fn new(config: &Config) -> Result<Self> {
        // Create the shell command and define a PS1 string
        let shell = Shell::find()?;
        let mut exec = ExecBuilder::with_path(&shell, Vec::<String>::new())?;
        exec.set_envs(config.to_env()?);

        Ok(Self { exec })
    }

    /// Creates the shell session
    pub fn exec(self) -> Result {
        eprintln!();
        eprintln!("======= Spawning new subshell: =======");
        Ok(self.exec.spawn_transparent()?.wait()?)
    }
}

use crate::run::WasmRun;
use crate::VmId;
use anyhow::{Context as _, Result};
use log::{debug, error, info, warn};
use std::future::Future;
use tokio::{
    sync::mpsc::{channel, Receiver, Sender},
    task::JoinHandle,
};

pub type CommandSender = Sender<Command>;

#[derive(Debug)]
pub enum Report {
    VmTerminated { id: VmId, reason: ExitReason },
}

#[derive(Debug)]
pub enum ExitReason {
    Exited(i32),
    Stopped,
    InputClosed,
    Panicked,
    Cancelled,
}

pub enum Command {
    // Stop the side VM instance.
    Stop,
    // Send a sidevm message to the instance.
    PushMessage(Vec<u8>),
}

pub struct ServiceRun {
    runtime: tokio::runtime::Runtime,
    report_rx: Receiver<Report>,
}

pub struct Spawner {
    runtime_handle: tokio::runtime::Handle,
    report_tx: Sender<Report>,
}

pub fn service() -> (ServiceRun, Spawner) {
    let runtime = tokio::runtime::Builder::new_multi_thread()
        .worker_threads(4)
        .enable_all()
        .build()
        .unwrap();
    let runtime_handle = runtime.handle().clone();
    let (report_tx, report_rx) = channel(100);
    let run = ServiceRun { runtime, report_rx };
    let spawner = Spawner {
        runtime_handle,
        report_tx,
    };
    (run, spawner)
}

impl ServiceRun {
    pub fn blocking_run(mut self, mut event_handler: impl FnMut(Report)) {
        self.runtime.block_on(async {
            loop {
                match self.report_rx.recv().await {
                    None => {
                        info!(target: "sidevm", "The report channel is closed. Exiting service thread.");
                        break;
                    }
                    Some(report) => {
                        event_handler(report);
                    }
                }
            }
        })
    }
}

impl Spawner {
    pub fn start(
        &self,
        wasm_bytes: &[u8],
        memory_pages: u32,
        id: VmId,
    ) -> Result<(CommandSender, JoinHandle<()>)> {
        let (cmd_tx, mut cmd_rx) = channel(100);
        let (mut wasm_run, env) = WasmRun::run(wasm_bytes, memory_pages, id)
            .context("Failed to create sidevm instance")?;
        let handle = self.runtime_handle.spawn(async move {
            loop {
                tokio::select! {
                    cmd = cmd_rx.recv() => {
                        match cmd {
                            None => {
                                info!(target: "sidevm", "The command channel is closed. Exiting...");
                                break ExitReason::InputClosed;
                            }
                            Some(Command::Stop) => {
                                info!(target: "sidevm", "Received stop command. Exiting...");
                                break ExitReason::Stopped;
                            }
                            Some(Command::PushMessage(msg)) => {
                                debug!(target: "sidevm", "Sending message to sidevm.");
                                match env.push_message(msg).await {
                                    Ok(_) => {}
                                    Err(e) => {
                                        error!(target: "sidevm", "Failed to send message to sidevm: {}", e);
                                        break ExitReason::Panicked;
                                    }
                                }
                            }
                        }
                    }
                    rv = &mut wasm_run => {
                        match rv {
                            Ok(ret) => {
                                info!(target: "sidevm", "The sidevm instance exited with {} normally.", ret);
                                break ExitReason::Exited(ret);
                            }
                            Err(err) => {
                                info!(target: "sidevm", "The sidevm instance exited with error: {}", err);
                                // TODO.kevin: Restart the instance?
                                break ExitReason::Panicked;
                            }
                        }
                    }
                }
            }
        });
        let report_tx = self.report_tx.clone();
        let handle = self.runtime_handle.spawn(async move {
            let reason = match handle.await {
                Ok(r) => r,
                Err(err) => {
                    warn!(target: "sidevm", "The sidevm instance exited with error: {}", err);
                    if err.is_cancelled() {
                        ExitReason::Cancelled
                    } else {
                        ExitReason::Panicked
                    }
                }
            };
            if let Err(err) = report_tx.send(Report::VmTerminated { id, reason }).await {
                warn!(target: "sidevm", "Failed to send report to sidevm service: {}", err);
            }
        });
        Ok((cmd_tx, handle))
    }

    pub fn spawn(&self, fut: impl Future<Output = ()> + Send + 'static) -> JoinHandle<()> {
        self.runtime_handle.spawn(fut)
    }
}

use std::fs::File;
use std::io::{self, BufRead, BufReader};

fn turn_right(direction: char) -> char {
    return match direction {
        'N' => 'E',
        'E' => 'S',
        'S' => 'W',
        'W' => 'N',
        _ => direction,
    };
}

fn turn_left(direction: char) -> char {
    return match direction {
        'N' => 'W',
        'E' => 'N',
        'S' => 'E',
        'W' => 'S',
        _ => direction,
    };
}

fn get_movement(command: &str, direction: char) -> (i32, i32, char) {
    let mov = command.chars().nth(0).unwrap();
    let off = command[1..].parse::<i32>().unwrap();

    return if mov == 'N' {
        (-off, 0, direction)
    } else if mov == 'S' {
        (off, 0, direction)
    } else if mov == 'E' {
        (0, off, direction)
    } else if mov == 'W' {
        (0, -off, direction)
    } else if mov == 'L' {
        let turns = off / 90;
        let mut new_dir = direction;
        for _ in 0..turns {
            new_dir = turn_left(new_dir);
        }
        (0, 0, new_dir)
    } else if mov == 'R' {
        let turns = off / 90;
        let mut new_dir = direction;
        for _ in 0..turns {
            new_dir = turn_right(new_dir);
        }
        (0, 0, new_dir)
    } else {
        match direction {
            'N' => (-off, 0, direction),
            'E' => (0, off, direction),
            'S' => (off, 0, direction),
            'W' => (0, -off, direction),
            _ => (0, 0, direction),
        }
    };
}

fn main() -> io::Result<()> {
    let f = File::open("data/12_input.txt")?;
    let f = BufReader::new(f);

    let mut r = 0;
    let mut c = 0;
    let mut direction = 'E';

    for line in f.lines() {
        let update = get_movement(&line.unwrap(), direction);
        r += update.0;
        c += update.1;
        direction = update.2
    }

    println!("Result: {}", r.abs() + c.abs());

    Ok(())
}

