macro_rules! impl_stream {
    ($stream:ident, $update:ident, $spec:ty) => {
        #[wasm_bindgen]
        pub struct $update {
            #[allow(dead_code)]
            added: Vec<$spec>,
            #[allow(dead_code)]
            deleted: Vec<$spec>,
        }

        #[wasm_bindgen]
        pub struct $stream {
            inner: Rc<
                RefCell<
                    std::pin::Pin<Box<dyn tokio_stream::Stream<Item = (Vec<$spec>, Vec<$spec>)>>>,
                >,
            >,
        }

        #[wasm_bindgen]
        impl $stream {
            pub fn next(&mut self) -> Promise {
                use tokio_stream::StreamExt;

                let rc = self.inner.clone();
                future_to_promise(async move {
                    rc.borrow_mut()
                        .next()
                        .await
                        .ok_or_else(|| {
                            FluvioError::from(format!("{} watch stream closed", stringify!($spec)))
                                .into()
                        })
                        .map(|(added, deleted)| JsValue::from($update { added, deleted }))
                })
            }
        }
    };
}

impl_stream!(AsyncTopicStream, TopicWatchUpdates, TopicMetadata);
impl_stream!(
    AsyncPartitionStream,
    PartitionWatchUpdates,
    PartitionMetadata
);

struct Solution;

impl Solution {
    fn special_array(nums: Vec<i32>) -> i32 {
        let n = nums.len();
        for i in 0..=n {
            if i == nums.iter().filter(|&&x| x >= i as i32).count() {
                return i as i32;
            }
        }
        -1
    }
}

#[test]
fn test() {
    let nums = vec![3, 5];
    let res = 2;
    assert_eq!(Solution::special_array(nums), res);
    let nums = vec![0, 0];
    let res = -1;
    assert_eq!(Solution::special_array(nums), res);
    let nums = vec![0, 4, 3, 0, 4];
    let res = 3;
    assert_eq!(Solution::special_array(nums), res);
}

