//! Websocket extensions as per [RFC 6455][rfc6455].
//!
//! [rfc6455]: https://tools.ietf.org/html/rfc6455#section-9

#[cfg(feature = "deflate")]
pub mod deflate;

use crate::{base::Header, BoxedError, Storage};
use std::{borrow::Cow, fmt};

/// A websocket extension as per RFC 6455, section 9.
///
/// Extensions are invoked during handshake and subsequently during base
/// frame encoding and decoding. The invocation during handshake differs
/// on client and server side.
///
/// # Server
///
/// 1. All extensions should consider themselves as disabled but available.
/// 2. When receiving a handshake request from a client, for each extension
/// with a matching name, [`Extension::configure`] will be applied to the
/// request parameters. The extension may internally enable itself.
/// 3. When sending back the response, for each extension whose
/// [`Extension::is_enabled`] returns true, the extension name and its
/// parameters (as returned by [`Extension::params`]) will be included in the
/// response.
///
/// # Client
///
/// 1. All extensions should consider themselves as disabled but available.
/// 2. When creating the handshake request, all extensions and its parameters
/// (as returned by [`Extension::params`]) will be included in the request.
/// 3. When receiving the response from the server, for every extension with
/// a matching name in the response, [`Extension::configure`] will be applied
/// to the response parameters. The extension may internally enable itself.
///
/// After this handshake phase, extensions have been configured and are
/// potentially enabled. Enabled extensions can then be used for further base
/// frame processing.
pub trait Extension: std::fmt::Debug {
	/// Is this extension enabled?
	fn is_enabled(&self) -> bool;

	/// The name of this extension.
	fn name(&self) -> &str;

	/// The parameters this extension wants to send for negotiation.
	fn params(&self) -> &[Param];

	/// Configure this extension with the parameters received from negotiation.
	fn configure(&mut self, params: &[Param]) -> Result<(), BoxedError>;

	/// Encode a frame, given as frame header and payload data.
	fn encode(&mut self, header: &mut Header, data: &mut Storage) -> Result<(), BoxedError>;

	/// Decode a frame.
	///
	/// The frame header is given, as well as the accumulated payload data, i.e.
	/// the concatenated payload data of all message fragments.
	fn decode(&mut self, header: &mut Header, data: &mut Vec<u8>) -> Result<(), BoxedError>;

	/// The reserved bits this extension uses.
	fn reserved_bits(&self) -> (bool, bool, bool) {
		(false, false, false)
	}
}

impl<E: Extension + ?Sized> Extension for Box<E> {
	fn is_enabled(&self) -> bool {
		(**self).is_enabled()
	}

	fn name(&self) -> &str {
		(**self).name()
	}

	fn params(&self) -> &[Param] {
		(**self).params()
	}

	fn configure(&mut self, params: &[Param]) -> Result<(), BoxedError> {
		(**self).configure(params)
	}

	fn encode(&mut self, header: &mut Header, data: &mut Storage) -> Result<(), BoxedError> {
		(**self).encode(header, data)
	}

	fn decode(&mut self, header: &mut Header, data: &mut Vec<u8>) -> Result<(), BoxedError> {
		(**self).decode(header, data)
	}

	fn reserved_bits(&self) -> (bool, bool, bool) {
		(**self).reserved_bits()
	}
}

/// Extension parameter (used for negotiation).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Param<'a> {
	name: Cow<'a, str>,
	value: Option<Cow<'a, str>>,
}

impl<'a> fmt::Display for Param<'a> {
	fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
		if let Some(v) = &self.value {
			write!(f, "{} = {}", self.name, v)
		} else {
			write!(f, "{}", self.name)
		}
	}
}

impl<'a> Param<'a> {
	/// Create a new parameter with the given name.
	pub fn new(name: impl Into<Cow<'a, str>>) -> Self {
		Param { name: name.into(), value: None }
	}

	/// Access the parameter name.
	pub fn name(&self) -> &str {
		&self.name
	}

	/// Access the optional parameter value.
	pub fn value(&self) -> Option<&str> {
		self.value.as_ref().map(|v| v.as_ref())
	}

	/// Set the parameter to the given value.
	pub fn set_value(&mut self, value: Option<impl Into<Cow<'a, str>>>) -> &mut Self {
		self.value = value.map(Into::into);
		self
	}

	/// Turn this parameter into one that owns its values.
	pub fn acquire(self) -> Param<'static> {
		Param { name: Cow::Owned(self.name.into_owned()), value: self.value.map(|v| Cow::Owned(v.into_owned())) }
	}
}

/// Applies the math in annealing.rs to keyboard layouts.
extern crate rand;

use self::rand::random;
use std::cmp::Ordering;
use std::collections::LinkedList;

use annealing;
use layout;
use penalty;

struct BestLayoutsEntry {
  layout: layout::Layout,
  penalty: f64,
}

impl BestLayoutsEntry {
  fn cmp(&self, other: &BestLayoutsEntry) -> Ordering {
    match self.penalty.partial_cmp(&other.penalty) {
      Some(ord) => ord,
      None => Ordering::Equal,
    }
  }
}

pub fn simulate<'a>(
  quartads: &penalty::QuartadList<'a>,
  len: usize,
  init_layout: &layout::Layout,
  penalties: &Vec<penalty::KeyPenalty<'a>>,
  debug: bool,
  top_layouts: usize,
  num_swaps: usize,
) {
  let penalty = penalty::calculate_penalty(&quartads, len, init_layout, penalties, true);

  if debug {
    println!("Initial layout:");
    print_result(init_layout, &penalty);
  }

  // Keep track of the best layouts we've encountered.
  let mut best_layouts: LinkedList<BestLayoutsEntry> = LinkedList::new();

  let mut accepted_layout = init_layout.clone();
  let mut accepted_penalty = penalty.1;
  for i in annealing::get_simulation_range() {
    // Copy and shuffle this iteration of the layout.
    let mut curr_layout = accepted_layout.clone();
    curr_layout.shuffle(random::<usize>() % num_swaps + 1);

    // Calculate penalty.
    let curr_layout_copy = curr_layout.clone();
    let penalty = penalty::calculate_penalty(&quartads, len, &curr_layout, penalties, false);
    let scaled_penalty = penalty.1;

    // Probabilistically accept worse transitions; always accept better
    // transitions.
    if annealing::accept_transition(scaled_penalty - accepted_penalty, i) {
      if debug {
        println!("Iteration {} accepted with penalty {}", i, scaled_penalty);
      }

      accepted_layout = curr_layout_copy.clone();
      accepted_penalty = scaled_penalty;

      // Insert this layout into best layouts.
      let new_entry = BestLayoutsEntry {
        layout: curr_layout_copy,
        penalty: penalty.1,
      };
      best_layouts = list_insert_ordered(best_layouts, new_entry);

      // Limit best layouts list length.
      while best_layouts.len() > top_layouts {
        best_layouts.pop_back();
      }
    }
  }

  for entry in best_layouts.into_iter() {
    let layout = entry.layout;
    let penalty = penalty::calculate_penalty(&quartads, len, &layout, penalties, true);
    println!("");
    print_result(&layout, &penalty);
  }
}

pub fn refine<'a>(
  quartads: &penalty::QuartadList<'a>,
  len: usize,
  init_layout: &layout::Layout,
  penalties: &Vec<penalty::KeyPenalty<'a>>,
  debug: bool,
  top_layouts: usize,
  num_swaps: usize,
) {
  let penalty = penalty::calculate_penalty(&quartads, len, init_layout, penalties, true);

  println!("Initial layout:");
  print_result(init_layout, &penalty);

  let mut curr_layout = init_layout.clone();
  let mut curr_penalty = penalty.1;

  loop {
    // Test every layout within `num_swaps` swaps of the initial layout.
    let mut best_layouts: LinkedList<BestLayoutsEntry> = LinkedList::new();
    let permutations = layout::LayoutPermutations::new(init_layout, num_swaps);
    let layout::LayoutShuffleMask(layout::KeyMap(ref mask)) = layout::LAYOUT_MASK;
    let non_masked_permutations =
      permutations.filter(|(_, swaps)| swaps.iter().all(|x| mask[*x] == true));
    for (i, (layout, _swaps)) in non_masked_permutations.enumerate() {
      // println!(
      //   "************************ BOOYA {:?}, {} *************************",
      //   _swaps, i
      // );
      let penalty = penalty::calculate_penalty(&quartads, len, &layout, penalties, false);

      if debug {
        println!("Iteration {}: {}", i, penalty.1);
      }

      // Insert this layout into best layouts.
      let new_entry = BestLayoutsEntry {
        layout: layout,
        penalty: penalty.1,
      };
      best_layouts = list_insert_ordered(best_layouts, new_entry);

      // Limit best layouts list length.
      while best_layouts.len() > top_layouts {
        best_layouts.pop_back();
      }
    }

    // Print the top layouts.
    for entry in best_layouts.iter() {
      let ref layout = entry.layout;
      let penalty = penalty::calculate_penalty(&quartads, len, &layout, penalties, true);
      println!("");
      print_result(&layout, &penalty);
    }

    // Keep going until swapping doesn't get us any more improvements.
    let best = best_layouts.pop_front().unwrap();
    if curr_penalty <= best.penalty {
      break;
    } else {
      curr_layout = best.layout;
      curr_penalty = best.penalty;
    }
  }

  println!("");
  println!("Ultimate winner:");
  println!("{}", curr_layout);
}

pub fn print_result<'a>(
  layout: &'a layout::Layout,
  penalty: &'a (f64, f64, Vec<penalty::KeyPenaltyResult<'a>>),
) {
  println!("{}", layout);

  let (ref total, ref scaled, ref penalties) = *penalty;
  println!("total: {}; scaled: {}", total, scaled);
  for penalty in penalties {
    print!("{}  / ", penalty);
    let mut high_keys: Vec<(&str, f64)> = penalty.high_keys.iter().map(|x| (*x.0, *x.1)).collect();
    high_keys.sort_by(|a, b| match b.1.abs().partial_cmp(&a.1.abs()) {
      Some(c) => c,
      None => Ordering::Equal,
    });
    for key in high_keys.iter().take(5) {
      let (k, v) = *key;
      print!(" {}: {};", k, v);
    }
    println!("");
  }
}

// Take ownership of the list and give it back as a hack to make the borrow checker happy :^)
fn list_insert_ordered(
  mut list: LinkedList<BestLayoutsEntry>,
  entry: BestLayoutsEntry,
) -> LinkedList<BestLayoutsEntry> {
  {
    // Find where to add our new entry to, since the list is sorted.
    let mut cursor = list.cursor_front_mut();
    loop {
      {
        if let Some(cur) = cursor.current() {
          let cmp = entry.cmp(cur);
          if cmp == Ordering::Less {
            break;
          }
        } else {
          break;
        }
      }

      cursor.move_next();
    }

    // Add to list.
    cursor.insert_before(entry);
  }
  list
}

//! Data structures for reporting transaction statuses.

use crate::solana::SigResponse;
use crate::transaction::Base64;

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use std::{cmp::Eq, fmt, hash::Hash, path::PathBuf};

const STRFTIME: &str = "%Y-%m-%d %H:%M:%S";

/// Status as reported directly from the network.
#[allow(dead_code)]
#[derive(Serialize, Deserialize, Debug, PartialEq, Clone)]
pub struct RawStatus {
    pub block_height: u64,
    pub block_indep_hash: Base64,
    pub number_of_confirmations: u64,
}

/// Indicates transaction status on the network, from Submitted to Confirmed.
#[derive(Serialize, Deserialize, Debug, Default, PartialEq, Clone, Eq, Hash)]
pub enum StatusCode {
    #[default]
    Submitted,
    Pending,
    Confirmed,
    NotFound,
}

impl std::fmt::Display for StatusCode {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            StatusCode::Submitted => write!(f, "Submitted"),
            StatusCode::Pending => write!(f, "Pending"),
            StatusCode::Confirmed => write!(f, "Confirmed"),
            StatusCode::NotFound => write!(f, "NotFound"),
        }
    }
}
pub struct FilterElements<'a> {
    pub raw_status: &'a Option<RawStatus>,
    pub status: &'a StatusCode,
}
pub trait Filterable {
    fn get_filter_elements(&self) -> FilterElements;
}

/// Data structure for tracking transaction statuses.
#[derive(Serialize, Deserialize, Debug, PartialEq, Clone)]
pub struct Status {
    pub id: Base64,
    pub status: StatusCode,
    pub file_path: Option<PathBuf>,
    pub content_type: String,
    pub created_at: DateTime<Utc>,
    pub last_modified: DateTime<Utc>,
    pub reward: u64,
    #[serde(flatten)]
    pub raw_status: Option<RawStatus>,
    #[serde(flatten)]
    pub sol_sig: Option<SigResponse>,
}

impl Default for Status {
    fn default() -> Self {
        Self {
            id: Base64(vec![]),
            status: StatusCode::default(),
            file_path: None,
            content_type: mime_guess::mime::OCTET_STREAM.to_string(),
            created_at: Utc::now(),
            last_modified: Utc::now(),
            reward: 0,
            raw_status: None,
            sol_sig: None,
        }
    }
}

impl Status {
    pub fn header_string(&self, output_format: &OutputFormat) -> String {
        match output_format {
            OutputFormat::Display => {
                format!(
                    " {:<30}  {:<43}  {:<9}  {}\n{:-<97}",
                    "path", "id", "status", "confirms", ""
                )
            }
            _ => format!("{}", ""),
        }
    }
}

impl Filterable for Status {
    fn get_filter_elements(&self) -> FilterElements {
        FilterElements {
            raw_status: &self.raw_status,
            status: &self.status,
        }
    }
}

impl QuietDisplay for Status {
    fn write_str(&self, _w: &mut dyn fmt::Write) -> fmt::Result {
        Ok(())
    }
}

impl std::fmt::Display for Status {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        writeln!(
            f,
            " {:<30}  {:<43}  {:<9}  {:>8}",
            self.file_path
                .as_ref()
                .map(|f| f.display().to_string())
                .unwrap_or("".to_string()),
            self.id,
            self.status.to_string(),
            self.raw_status
                .as_ref()
                .map(|f| f.number_of_confirmations)
                .unwrap_or(0)
                .to_string(),
        )
    }
}

impl VerboseDisplay for Status {
    fn write_str(&self, w: &mut dyn fmt::Write) -> fmt::Result {
        writeln!(w, "{:<15} {}", "id:", self.id)?;
        writeln!(w, "{:<15} {:?}", "status:", self.status)?;
        if let Some(file_path) = &self.file_path {
            writeln!(
                w,
                "{:<15} {}",
                "file_path:",
                file_path.display().to_string()
            )?;
        };
        writeln!(
            w,
            "{:<15} {}",
            "created_at:",
            self.created_at.format(STRFTIME).to_string()
        )?;
        writeln!(
            w,
            "{:<15} {}",
