use serde_derive::*;

use crate::addon::GameVersion;
use crate::addon::local::LocalAddons;
use crate::util::fs::{part_file_path, remove_if};
use defaults::*;

#[derive(Deserialize,Serialize)]
pub struct Repo {
    pub conf: Conf,
    pub addons: LocalAddons,
}

#[derive(Deserialize,Serialize)]
pub struct Conf {
    pub game_version: GameVersion,
    #[serde(default="default_url_txt")]
    pub url_txt: bool,
    #[serde(default="default_addon_mtime")]
    pub addon_mtime: bool,
    #[serde(default="default_soft_retries")]
    pub soft_retries: usize,
    #[serde(default="default_api_headers")]
    pub api_headers: Vec<(String,String)>,
    #[serde(default="default_api_domain")]
    pub api_domain: String,
}

impl Repo {
    pub fn load(conf: impl AsRef<Path>) -> anyhow::Result<Option<Self>> {
        let f = match std::fs::read_to_string(conf) {
            Ok(f) => f,
            Err(e) if e.kind() == ErrorKind::NotFound => return Ok(None),
            Err(e) => return Err(e.into()),
        };
        match serde_json::from_str(&f) {
            Ok(c) => Ok(Some(c)),
            Err(e) => Err(e.into()),
        }
    }
    pub fn save(&self, conf: impl AsRef<Path>) -> anyhow::Result<()> {
        let conf_part = part_file_path(conf.as_ref());
        let f = file_write(&conf_part)?; //TODO fix, .part
        let f = BufWriter::new(f);
        serde_json::to_writer_pretty(f, self)?;
        remove_if(&conf)?;
        std::fs::rename(conf_part, conf)?;
        Ok(())
    }
    pub fn save_new(&self, conf: impl AsRef<Path>) -> anyhow::Result<()> {
        let f = file_write_new(conf)?; //TODO fix
        let f = BufWriter::new(f);
        serde_json::to_writer_pretty(f, self)?;
        Ok(())
    }
    pub fn sort_deps(&mut self) {
        for a in self.addons.values_mut() {
            if let Some(file) = &mut a.installed {
                file.sort_deps();
            }
        }
    }
}

fn file_write(p: impl AsRef<Path>) -> std::io::Result<File> {
    OpenOptions::new()
        .write(true)
        .create(true)
        .truncate(true)
        .open(p)
}
fn file_write_new(p: impl AsRef<Path>) -> std::io::Result<File> {
    OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(p)
}

use super::*;

pub struct AlignedMut<'a, S: Simd, V: SimdVectorBase<S>> {
    ptr: *mut V::Element,
    len: usize,
    _lt: PhantomData<&'a S>,
}

impl<'a, S: Simd, V: SimdVectorBase<S>> AlignedMut<'a, S, V> {
    #[inline]
    pub unsafe fn new_unchecked(slice: &'a mut [V::Element]) -> Self {
        AlignedMut {
            ptr: slice.as_mut_ptr(),
            len: slice.len(),
            _lt: PhantomData,
        }
    }

    #[inline]
    pub fn new(slice: &'a mut [V::Element]) -> Option<Self> {
        if slice.as_ptr().align_offset(V::ALIGNMENT) != 0 {
            None
        } else {
            Some(unsafe { AlignedMut::new_unchecked(slice) })
        }
    }

    #[inline]
    pub fn iter_mut(self) -> AlignedMutIter<'a, S, V> {
        AlignedMutIter(self)
    }
}

pub struct AlignedMutIter<'a, S: Simd, V: SimdVectorBase<S>>(AlignedMut<'a, S, V>);

impl<'a, S: Simd, V: SimdVectorBase<S>> AlignedMutIter<'a, S, V> {
    /// Returns the remainder of the slice that is being iterated over.
    ///
    /// If the iterator has been exhausted (`next()` returns `None`),
    /// this may still return elements that would not fill an SIMD vector.
    pub fn remainder(&mut self) -> &'a mut [V::Element] {
        unsafe { core::slice::from_raw_parts_mut(self.0.ptr, self.0.len) }
    }
}

impl<'a, S: Simd, V: SimdVectorBase<S>> Iterator for AlignedMutIter<'a, S, V> {
    type Item = &'a mut V;

    #[inline]
    fn next(&mut self) -> Option<&'a mut V> {
        if self.0.len < V::NUM_ELEMENTS {
            None
        } else {
            unsafe {
                let ptr = self.0.ptr;
                self.0.ptr = self.0.ptr.add(V::NUM_ELEMENTS);
                self.0.len -= V::NUM_ELEMENTS;
                Some(&mut *(ptr as *mut V))
            }
        }
    }

    #[inline]
    fn size_hint(&self) -> (usize, Option<usize>) {
        let remaining = self.0.len / V::NUM_ELEMENTS;
        (remaining, Some(remaining))
    }
}

//! ALB and API Gateway request adaptations
//!
//! Typically these are exposed via the `request_context`
//! request extension method provided by [lambda_http::RequestExt](../trait.RequestExt.html)
//!
use crate::ext::{PathParameters, QueryStringParameters, StageVariables};
use aws_lambda_events::alb::{AlbTargetGroupRequest, AlbTargetGroupRequestContext};
use aws_lambda_events::apigw::{
    ApiGatewayProxyRequest, ApiGatewayProxyRequestContext, ApiGatewayV2httpRequest, ApiGatewayV2httpRequestContext,
    ApiGatewayWebsocketProxyRequest, ApiGatewayWebsocketProxyRequestContext,
};
use aws_lambda_events::encodings::Body;
