/// Wraps creating the Deno Js runtime collecting parameters and executing a script.
use deno_core::{op_sync, JsRuntime};
use serde::de::DeserializeOwned;
use serde::Serialize;
use std::io::Write;
use std::sync::mpsc::channel;

pub(crate) struct Js {
    parameters: Vec<(&'static str, String)>,
}

impl Js {
    pub(crate) fn new() -> Js {
        Js {
            parameters: Vec::new(),
        }
    }

    pub(crate) fn with_parameter<T: Serialize>(mut self, name: &'static str, param: T) -> Js {
        let serialized = format!(
            "{} = {}",
            name,
            serde_json::to_string(&param)
                .unwrap_or_else(|_| panic!("unable to serialize {} into JavaScript runtime", name))
        );
        self.parameters.push((name, serialized));
        self
    }

    pub(crate) fn execute<Ok: DeserializeOwned + 'static, Error: DeserializeOwned + 'static>(
        &self,
        name: &'static str,
        source: &'static str,
    ) -> Result<Ok, Error> {
        let mut runtime = JsRuntime::new(Default::default());

        // We'll use this channel to get the results
        let (tx, rx) = channel();

        // The first thing we do is define an op so we can print data to STDOUT,
        // because by default the JavaScript console functions are just stubs (they
        // don't do anything).

        // Register the op for outputting bytes to stdout. It can be invoked with
        // Deno.core.dispatch and the id this method returns or
        // Deno.core.dispatchByName and the name provided.
        runtime.register_op(
            "op_print",
            // The op_fn callback takes a state object OpState,
            // a structured arg of type `T` and an optional ZeroCopyBuf,
            // a mutable reference to a JavaScript ArrayBuffer
            op_sync(|_state, _msg: Option<String>, zero_copy| {
                let mut out = std::io::stdout();

                // Write the contents of every buffer to stdout
                if let Some(buf) = zero_copy {
                    out.write_all(&buf)
                        .expect("failure writing buffered output");
                }

                Ok(()) // No meaningful result
            }),
        );

        runtime.register_op(
            "op_result",
            op_sync(move |_state, value, _zero_copy| {
                tx.send(value).expect("channel must be open");

                Ok(serde_json::json!(null))

                // Don't return anything to JS
            }),
        );

        // The runtime automatically contains a Deno.core object with several
        // functions for interacting with it.
        runtime
            .execute("<init>", include_str!("../js-dist/runtime.js"))
            .expect("unable to initialize router bridge runtime environment");

        runtime
            .execute(
                "url_polyfill.js",
                include_str!("../bundled/url_polyfill.js"),
            )
            .expect("unable to evaluate url_polyfill module");

        runtime
            .execute("<url_polyfill_assignment>", "whatwg_url_1 = url_polyfill;")
            .expect("unable to assign url_polyfill");

        // Load the composition library.
        runtime
            .execute("bridge.js", include_str!("../bundled/bridge.js"))
            .expect("unable to evaluate bridge module");

        for parameter in self.parameters.iter() {
            runtime
                .execute(format!("<{}>", parameter.0).as_str(), &parameter.1)
                .expect("unable to evaluate service list in JavaScript runtime");
        }

        runtime.execute(name, source).unwrap_or_else(|e| {
            panic!(
                "unable to invoke {} in JavaScript runtime \n error: \n {:?}",
                source, e
            )
        });

        rx.recv().expect("channel remains open")
    }
}

use crate::puzzle_input;
use regex::Regex;
use std::cmp;
use std::collections::HashMap;

pub fn run() {
    let input: Vec<String> = puzzle_input::read_all_lines("./input/2021-d05-input.txt");

    let grid = Grid::new(&input, false);
    println!("** Part 1 Final: {:?}", grid.at_least_2());

    let grid2 = Grid::new(&input, true);
    println!("** Part 2 Final: {:?}", grid2.at_least_2());
}

#[derive(Clone, Debug, PartialEq)]
struct Grid {
    data: HashMap<(i32, i32), i32>,
    width: i32,
    height: i32,
}

impl Grid {
    fn new(input: &[String], diagonals: bool) -> Grid {
        lazy_static! {
            static ref LINE_RE: Regex = Regex::new(r"(\d+),(\d+)[^\d]+(\d+),(\d+)").unwrap();
        }

        let mut data: HashMap<(i32, i32), i32> = HashMap::new();
        let mut height: i32 = 0;
        let mut width: i32 = 0;
        for line in input {
            let cap = LINE_RE.captures(line).unwrap();
            let x1 = cap.get(1).unwrap().as_str().parse::<i32>().unwrap();
            let y1 = cap.get(2).unwrap().as_str().parse::<i32>().unwrap();
            let x2 = cap.get(3).unwrap().as_str().parse::<i32>().unwrap();
            let y2 = cap.get(4).unwrap().as_str().parse::<i32>().unwrap();
            height = cmp::max(y1, cmp::max(y2, height));
            width = cmp::max(x1, cmp::max(x2, width));
            if x1 == x2 {
                let b = cmp::min(y1, y2);
                let e = cmp::max(y1, y2) + 1;
                for y in b..e {
                    let counter = data.entry((x1, y)).or_insert(0);
                    *counter += 1;
                }
            } else if y1 == y2 {
                let b = cmp::min(x1, x2);
                let e = cmp::max(x1, x2) + 1;
                for x in b..e {
                    let counter = data.entry((x, y1)).or_insert(0);
                    *counter += 1;
                }
            } else if diagonals && (x1 - x2).abs() == (y1 - y2).abs() {
                let mut x = cmp::min(x1, x2);
                let range = 1 + (x1 - x2).abs();
                let up = if x == x1 { y1 < y2 } else { y2 < y1 };
                let mut y = if x == x1 { y1 } else { y2 };
                for _ in 0..range {
                    let counter = data.entry((x, y)).or_insert(0);
                    *counter += 1;
                    x += 1;
                    y = if up { y + 1 } else { y - 1 };
                }
            }
        }

        Grid {
            data,
            height: height + 1,
            width: width + 1,
        }
    }

    fn at_least_2(&self) -> usize {
        self.data.values().filter(|x| **x >= 2).count()
    }

    #[allow(dead_code)]
    fn dump(&self) {
        for y in 0..self.height {
            for x in 0..self.width {
                if let Some(pt) = self.data.get(&(x, y)) {
                    print!("{}", pt);
                } else {
                    print!(".");
                }
            }
            println!();
        }
        println!();
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test() {
        let input: Vec<String> = puzzle_input::split_string(
            "0,9 -> 5,9
        8,0 -> 0,8
        9,4 -> 3,4
        2,2 -> 2,1
        7,0 -> 7,4
        6,4 -> 2,0
        0,9 -> 2,9
        3,4 -> 1,4
        0,0 -> 8,8
        5,5 -> 8,2",
        );

        let grid = Grid::new(&input, false);
        grid.dump();

        assert_eq!(5, grid.at_least_2());

        let grid2 = Grid::new(&input, true);
        grid2.dump();
        assert_eq!(12, grid2.at_least_2());
    }
}

extern crate xmlparser as xml;

#[derive(PartialEq, Debug)]
pub enum Token<'a> {
    Declaration(&'a str, Option<&'a str>, Option<bool>),
    PI(&'a str, Option<&'a str>),
    Comment(&'a str),
    DtdStart(&'a str, Option<ExternalId<'a>>),
    EmptyDtd(&'a str, Option<ExternalId<'a>>),
    EntityDecl(&'a str, EntityDefinition<'a>),
    DtdEnd,
    ElementStart(&'a str, &'a str),
    Attribute(&'a str, &'a str, &'a str),
    ElementEnd(ElementEnd<'a>),
    Text(&'a str),
    Whitespaces(&'a str),
    Cdata(&'a str),
    Error(String),
}

#[derive(PartialEq, Debug)]
pub enum ElementEnd<'a> {
    Open,
    Close(&'a str, &'a str),
    Empty,
}

#[derive(PartialEq, Debug)]
pub enum ExternalId<'a> {
    System(&'a str),
    Public(&'a str, &'a str),
}

#[derive(PartialEq, Debug)]
pub enum EntityDefinition<'a> {
    EntityValue(&'a str),
    ExternalId(ExternalId<'a>),
}

#[macro_export]
macro_rules! test {
    ($name:ident, $text:expr, $($token:expr),*) => (
        #[test]
        fn $name() {
            let mut p = xml::Tokenizer::from($text);
            $(
                let t = p.next().unwrap();
//                println!("{:?}", t);
                assert_eq!(to_test_token(t), $token);
            )*
            assert!(p.next().is_none());
        }
    )
}

#[inline(never)]
pub fn to_test_token(token: Result<xml::Token, xml::Error>) -> Token {
    match token {
        Ok(xml::Token::Declaration(version, encoding, standalone)) => {
            Token::Declaration(
                version.to_str(),
                encoding.map(|v| v.to_str()),
                standalone,
            )
        }
        Ok(xml::Token::ProcessingInstruction(target, content)) => {
            Token::PI(
                target.to_str(),
                content.map(|v| v.to_str()),
            )
        }
        Ok(xml::Token::Comment(text)) => Token::Comment(text.to_str()),
        Ok(xml::Token::DtdStart(name, external_id)) => {
            Token::DtdStart(
                name.to_str(),
                external_id.map(|v| to_test_external_id(v)),
            )
        }
        Ok(xml::Token::EmptyDtd(name, external_id)) => {
            Token::EmptyDtd(
                name.to_str(),
                external_id.map(|v| to_test_external_id(v)),
            )
        }
        Ok(xml::Token::EntityDeclaration(name, def)) => {
            Token::EntityDecl(
                name.to_str(),
                match def {
                    xml::EntityDefinition::EntityValue(name) => {
                        EntityDefinition::EntityValue(name.to_str())
                    }
                    xml::EntityDefinition::ExternalId(id) => {
                        EntityDefinition::ExternalId(to_test_external_id(id))
                    }
                }
            )
        }
        Ok(xml::Token::DtdEnd) => Token::DtdEnd,
        Ok(xml::Token::ElementStart(prefix, local)) => {
            Token::ElementStart(
                prefix.to_str(),
                local.to_str(),
            )
        }
        Ok(xml::Token::Attribute((prefix, local), value)) => {
            Token::Attribute(
                prefix.to_str(), local.to_str(), value.to_str()
            )
        }
        Ok(xml::Token::ElementEnd(end)) => {
            Token::ElementEnd(
                match end {
                    xml::ElementEnd::Open => ElementEnd::Open,
                    xml::ElementEnd::Close(prefix, local) => {
                        ElementEnd::Close(prefix.to_str(), local.to_str())
                    }
                    xml::ElementEnd::Empty => ElementEnd::Empty,
                }
            )
        }
        Ok(xml::Token::Text(text)) => Token::Text(text.to_str()),
        Ok(xml::Token::Whitespaces(text)) => Token::Whitespaces(text.to_str()),
        Ok(xml::Token::Cdata(text)) => Token::Cdata(text.to_str()),
        Err(ref e) => Token::Error(e.to_string()),
    }
}

fn to_test_external_id(id: xml::ExternalId) -> ExternalId {
    match id {
        xml::ExternalId::System(name) => {
            ExternalId::System(name.to_str())
        }
        xml::ExternalId::Public(name, value) => {
            ExternalId::Public(name.to_str(), value.to_str())
        }
    }
}

