//! Resource structure for babybatch.
use crate::structure::BabyBatchResponse;
use crate::util::errors::*;

/// Primary structure representing a _resource_––where a resource is
/// defined by an api key, a country code, and a page token.
#[derive(Debug)]
pub struct Resource {
    api_key: String,
    country_code: String,
    page_token: String,
}

/// Default implementation for a given `Resource`.
impl Default for Resource {
    fn default() -> Self {
        Resource {
            api_key: String::new(),
            country_code: String::new(),
            page_token: String::new(),
        }
    }
}

impl Resource {
    pub fn new(api_key: &str) -> Self {
        Resource {
            api_key: api_key.to_owned(),
            ..Default::default()
        }
    }

    pub fn country_code(mut self, c: &str) -> Self {
        self.country_code = c.to_owned();
        self
    }

    pub fn page_token(mut self, t: &str) -> Self {
        self.page_token = t.to_owned();
        self
    }

    pub fn set_token(&mut self, t: &str) {
        self.page_token = t.to_owned();
    }

    pub fn request(&self) -> Result<BabyBatchResponse> {
        let mut response = reqwest::get(&Resource::_url(&self))?;
        let response: serde_json::Value = response.json()?;
        let value: &serde_json::Value = &response["nextPageToken"];

        if let Some(page_token) = value.as_str() {
            let page_token = format!("&pageToken={}&", page_token);
            Ok(BabyBatchResponse {
                body: response,
                page_token,
            })
        } else {
            Err(BabyBatchError::NoNextPageToken)
        }
    }

    fn _url(resource: &Resource) -> String {
        const URL: &str = "https://www.googleapis.com/youtube/v3/videos?part";

        if !resource.page_token.is_empty() {
            format!(
        "{URL}=id,statistics,snippet{PAGE_TOKEN}chart=mostPopular&regionCode={COUNTRY_CODE}&maxResults=50&key={API_KEY}",
        URL = URL,
        PAGE_TOKEN = resource.page_token,
        COUNTRY_CODE = resource.country_code,
        API_KEY = resource.api_key)
        } else {
            "".to_owned()
        }
    }
}

use math::SpacialNumericConversion;

use crate::*;

/// Construct a set of [`Sprite`]s from a set of [`riddle_image::Image`]s which share a texture atlas.
///
/// # Example
///
/// ```no_run
/// # use riddle::{common::Color, image::*, platform::*, renderer::*, math::*, *};
/// # fn main() -> Result<(), RiddleError> {
/// # let rdl =  RiddleLib::new()?;
/// # let window = WindowBuilder::new().build(rdl.context())?;
/// let renderer = Renderer::new_from_window(&window)?;
///
/// let img1 = Image::new(100, 100);
/// let img2 = Image::new(50, 50);
///
/// let mut sprite1 = None;
/// let mut sprite2 = None;
///
/// SpriteAtlasBuilder::new()
///     .with_image(img1, &mut sprite1)
///     .with_image(img2, &mut sprite2)
///     .build(&renderer)?;
///
/// assert!(sprite1.is_some());
/// assert!(sprite2.is_some());
/// # Ok(()) }
/// ```
pub struct SpriteAtlasBuilder<'a, Device: WgpuDevice> {
	images: Vec<(image::Image, &'a mut Option<Sprite<Device>>)>,

	mag_filter: FilterMode,
	min_filter: FilterMode,
}

impl<'a, Device> SpriteAtlasBuilder<'a, Device>
where
	Device: WgpuDevice,
{
	/// A new empty atlas builder
	pub fn new() -> Self {
		Self {
			images: vec![],
			mag_filter: Default::default(),
			min_filter: Default::default(),
		}
	}

	/// Add an image to be packed in to the atlas, along with a reference
	/// to the `Option<Sprite>` which will store the sprite when the atlas is built.
	pub fn with_image(mut self, img: image::Image, sprite: &'a mut Option<Sprite<Device>>) -> Self {
		self.images.push((img, sprite));
		self
	}

	/// Specify the min and mag filters used when rendering the created sprites.
	pub fn with_filter_modes(mut self, mag_filter: FilterMode, min_filter: FilterMode) -> Self {
		self.mag_filter = mag_filter;
		self.min_filter = min_filter;
		self
	}

	/// Construct the atlas texture from the given set of images, and update the
	/// `Option<Sprite>` references.
	pub fn build(self, renderer: &Renderer<Device>) -> Result<()> {
		let SpriteAtlasBuilder {
			mut images,
			mag_filter,
			min_filter,
		} = self;

		let packing_images: Vec<&image::Image> = images.iter().map(|(img, _)| img).collect();
		let packed = image::ImagePacker::new().pack(&packing_images[..])?;

		let texture = renderer.wgpu_device().with_device_info(|info| {
			Ok(Texture::from_image(
				info.device,
				info.queue,
				packed.image(),
				mag_filter,
				min_filter,
				TextureType::Plain,
			))
		})?;

		for ((_, output), rect) in images.iter_mut().zip(packed.rects().iter()) {
			**output = Some(Sprite::from_texture_with_bounds(
				renderer,
				&texture,
				rect.clone().convert(),
			)?);
		}

		Ok(())
	}
}

impl<'a, Device> Default for SpriteAtlasBuilder<'a, Device>
where
	Device: WgpuDevice,
{
	fn default() -> Self {
		Self::new()
	}
}

use crate::postgres::protocol::TypeId;
use crate::types::TypeInfo;
use std::borrow::Borrow;
use std::fmt;
use std::fmt::Display;
use std::ops::Deref;
use std::sync::Arc;

/// Type information for a Postgres SQL type.
#[derive(Debug, Clone)]
pub struct PgTypeInfo {
    pub(crate) id: Option<TypeId>,
    pub(crate) name: SharedStr,
}

impl PgTypeInfo {
    pub(crate) fn new(id: TypeId, name: impl Into<SharedStr>) -> Self {
        Self {
            id: Some(id),
            name: name.into(),
        }
    }

    /// Create a `PgTypeInfo` from a type name.
    ///
    /// The OID for the type will be fetched from Postgres on bind or decode of
    /// a value of this type. The fetched OID will be cached per-connection.
    pub const fn with_name(name: &'static str) -> Self {
        Self {
            id: None,
            name: SharedStr::Static(name),
        }
    }

    #[doc(hidden)]
    pub fn type_feature_gate(&self) -> Option<&'static str> {
        match self.id? {
            TypeId::DATE | TypeId::TIME | TypeId::TIMESTAMP | TypeId::TIMESTAMPTZ => Some("chrono"),
            TypeId::UUID => Some("uuid"),
            TypeId::JSON | TypeId::JSONB => Some("json"),
            // we can support decoding `PgNumeric` but it's decidedly less useful to the layman
            TypeId::NUMERIC => Some("bigdecimal"),
            TypeId::CIDR | TypeId::INET => Some("ipnetwork"),

            _ => None,
        }
    }
}

impl Display for PgTypeInfo {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.name)
    }
}

impl PartialEq<PgTypeInfo> for PgTypeInfo {
    fn eq(&self, other: &PgTypeInfo) -> bool {
        // Postgres is strongly typed (mostly) so the rules that make sense here are equivalent
        // to the rules that make sense in [compatible]
        self.compatible(other)
    }
}

impl TypeInfo for PgTypeInfo {
    fn compatible(&self, other: &Self) -> bool {
        if let (Some(self_id), Some(other_id)) = (self.id, other.id) {
            return match (self_id, other_id) {
                (TypeId::CIDR, TypeId::INET)
                | (TypeId::INET, TypeId::CIDR)
                | (TypeId::ARRAY_CIDR, TypeId::ARRAY_INET)
                | (TypeId::ARRAY_INET, TypeId::ARRAY_CIDR) => true,

                // the following text-like types are compatible
                (TypeId::VARCHAR, other)
                | (TypeId::TEXT, other)
                | (TypeId::BPCHAR, other)
                | (TypeId::NAME, other)
                | (TypeId::UNKNOWN, other)
                    if match other {
                        TypeId::VARCHAR
                        | TypeId::TEXT
                        | TypeId::BPCHAR
                        | TypeId::NAME
                        | TypeId::UNKNOWN => true,
                        _ => false,
                    } =>
                {
                    true
                }

                // the following text-like array types are compatible
                (TypeId::ARRAY_VARCHAR, other)
                | (TypeId::ARRAY_TEXT, other)
                | (TypeId::ARRAY_BPCHAR, other)
                | (TypeId::ARRAY_NAME, other)
                    if match other {
                        TypeId::ARRAY_VARCHAR
                        | TypeId::ARRAY_TEXT
                        | TypeId::ARRAY_BPCHAR
                        | TypeId::ARRAY_NAME => true,
                        _ => false,
                    } =>
                {
                    true
                }

                // JSON <=> JSONB
                (TypeId::JSON, other) | (TypeId::JSONB, other)
                    if match other {
                        TypeId::JSON | TypeId::JSONB => true,
                        _ => false,
                    } =>
                {
                    true
                }

                _ => self_id.0 == other_id.0,
            };
        }

        // If the type names match, the types are equivalent (and compatible)
        // If the type names are the empty string, they are invalid type names

        if (&*self.name == &*other.name) && !self.name.is_empty() {
            return true;
        }

        // TODO: More efficient way to do case insensitive comparison
        if !self.name.is_empty() && (&*self.name.to_lowercase() == &*other.name.to_lowercase()) {
            return true;
        }

        false
    }
}

/// Copy of `Cow` but for strings; clones guaranteed to be cheap.
#[derive(Clone, Debug, PartialEq, Hash, Eq)]
pub(crate) enum SharedStr {
    Static(&'static str),
    Arc(Arc<str>),
}

impl Deref for SharedStr {
    type Target = str;

    fn deref(&self) -> &str {
        match self {
            SharedStr::Static(s) => s,
            SharedStr::Arc(s) => s,
        }
    }
}

impl Borrow<str> for SharedStr {
    fn borrow(&self) -> &str {
        &**self
    }
}

impl<'a> From<&'a SharedStr> for SharedStr {
    fn from(s: &'a SharedStr) -> Self {
        s.clone()
    }
}

impl From<&'static str> for SharedStr {
    fn from(s: &'static str) -> Self {
