/// Only applies to Validators. Either provides transactions to consensus [`GetBlockRequest`] or
/// handles rejecting transactions [`RejectNotification`]
pub(crate) fn process_consensus_request(mempool: &Mutex<CoreMempool>, req: ConsensusRequest) {
    // Start latency timer
    let start_time = Instant::now();
    debug!(LogSchema::event_log(LogEntry::Consensus, LogEvent::Received).consensus_msg(&req));

    let (resp, callback, counter_label) = match req {
        ConsensusRequest::GetBlockRequest(max_block_size, transactions, callback) => {
            let exclude_transactions: HashSet<TxnPointer> = transactions
                .iter()
                .map(|txn| (txn.sender, txn.sequence_number))
                .collect();
            let mut txns;
            {
                let mut mempool = mempool.lock();
                // gc before pulling block as extra protection against txns that may expire in consensus
                // Note: this gc operation relies on the fact that consensus uses the system time to determine block timestamp
                let curr_time = diem_infallible::duration_since_epoch();
                mempool.gc_by_expiration_time(curr_time);
                let block_size = cmp::max(max_block_size, 1);
                txns = mempool.get_block(block_size, exclude_transactions);
            }
            counters::mempool_service_transactions(counters::GET_BLOCK_LABEL, txns.len());
            txns.len();
            let pulled_block = txns.drain(..).map(SignedTransaction::into).collect();

            (
                ConsensusResponse::GetBlockResponse(pulled_block),
                callback,
                counters::GET_BLOCK_LABEL,
            )
        }
        ConsensusRequest::RejectNotification(transactions, callback) => {
            counters::mempool_service_transactions(
                counters::COMMIT_CONSENSUS_LABEL,
                transactions.len(),
            );
            process_committed_transactions(mempool, transactions, 0, true);
            (
                ConsensusResponse::CommitResponse(),
                callback,
                counters::COMMIT_CONSENSUS_LABEL,
            )
        }
    };
    // Send back to callback
    let result = if callback.send(Ok(resp)).is_err() {
        error!(LogSchema::event_log(
            LogEntry::Consensus,
            LogEvent::CallbackFail
        ));
        counters::REQUEST_FAIL_LABEL
    } else {
        counters::REQUEST_SUCCESS_LABEL
    };
    let latency = start_time.elapsed();
    counters::mempool_service_latency(counter_label, result, latency);
}

/// Remove transactions that are committed (or rejected) so that we can stop broadcasting them.
pub fn process_committed_transactions(
    mempool: &Mutex<CoreMempool>,
    transactions: Vec<TransactionSummary>,
    block_timestamp_usecs: u64,
    is_rejected: bool,
) {
    let mut pool = mempool.lock();

    for transaction in transactions {
        pool.remove_transaction(
            &transaction.sender,
            transaction.sequence_number,
            is_rejected,
        );
    }

    if block_timestamp_usecs > 0 {
        pool.gc_by_expiration_time(Duration::from_micros(block_timestamp_usecs));
    }
}

/// Processes on-chain reconfiguration notifications.  Restarts validator with the new info.
pub(crate) async fn process_config_update<V>(
    config_update: OnChainConfigPayload,
    validator: Arc<RwLock<V>>,
) where
    V: TransactionValidation,
{
    info!(
        LogSchema::event_log(LogEntry::ReconfigUpdate, LogEvent::Process)
            .reconfig_update(config_update.clone())
    );

    if let Err(e) = validator.write().restart(config_update) {
        counters::VM_RECONFIG_UPDATE_FAIL_COUNT.inc();
        error!(LogSchema::event_log(LogEntry::ReconfigUpdate, LogEvent::VMUpdateFail).error(&e));
    }
}

use crate::color::Color;
use crate::styling::Padding;
use crate::renderer::Renderer;

#[derive(Debug)]
pub struct LabelStyle {
    pub background_color: Option<Color>,
    pub foreground_color: Color,
    pub padding: Padding,
    pub min_width: f32
}

impl Default for LabelStyle {
    fn default() -> Self {
        Self {
            background_color: None,
            foreground_color: Color::BLACK,
            padding: 0.0.into(),
            min_width: 0.0
        }
    }
}

impl Into<LabelStyle> for () {
    fn into(self) -> LabelStyle {
        Default::default()
    }
}

impl Renderer {
    pub fn label<T: Into<LabelStyle>>(&mut self, text: &str, style: T) -> (f32, f32, f32) {
        let style = style.into();

        // This is needed to more correctly position the text vertically.
        // Might change based on font and font size not sure yet.
        let font_sorcery = 2.0;
        let (x, y) = self.pos();
        let (width, height) = self.calculate_text_size(text);
        let rect_width = width.max(style.min_width) + style.padding.left + style.padding.right;
        let rect_height = height + style.padding.top + style.padding.bottom - font_sorcery * 1.5;
        let text_x = x + style.padding.left;
        let text_y = y + style.padding.top - font_sorcery * 2.0;
        self.rectangle((rect_width, rect_height), style.background_color.unwrap_or(self.background_color));
        self.set_cursor(text_x, text_y, |r| {
            r.text(text, style.foreground_color);
        });

        (rect_width, rect_height, text_x + width)
    }

}

use crate::constants::colors::WHITE;
use crate::constants::{Direction, TOLERANCE};
use crate::system::math::{pt, Point};
use ggez::graphics::{
    Color, DrawMode, Drawable, Mesh, MeshBuilder, Rect, Scale, Text, TextFragment,
};
use ggez::{graphics, Context, GameResult};
use std::collections::HashMap;
use std::rc::Rc;

pub struct MeshHelper {
    pub width: f32,
    pub height: f32,
    mesh_cache: HashMap<String, Rc<Mesh>>,
}

impl MeshHelper {
    pub fn new(ctx: &mut Context) -> MeshHelper {
        let (width, height) = MeshHelper::get_screen_size(ctx);
        MeshHelper {
            width,
            height,
            mesh_cache: HashMap::new(),
        }
    }
}

impl MeshHelper {
    pub fn get_screen_size(ctx: &mut Context) -> (f32, f32) {
        return graphics::window(ctx)
            .get_inner_size()
            .map(|physical| (physical.width as f32, physical.height as f32))
            .expect("Failed to get/convert window size");
    }
}

impl MeshHelper {
    pub fn center(&self) -> Point {
        pt(self.width * 0.5, self.height * 0.5)
    }

    pub fn calc_width(&self, percent: f32) -> f32 {
        self.width * percent
    }

    pub fn calc_height(&self, percent: f32) -> f32 {
        self.height * percent
    }

    #[allow(clippy::too_many_arguments)]
    pub fn make_grid(
        &mut self,
        ctx: &mut Context,
        width: f32,
        height: f32,
        cols: usize,
        rows: usize,
        thickness: f32,
        line_color: Color,
        square_colors: Option<[Color; 2]>,
    ) -> GameResult<Rc<Mesh>> {
        self.make_mesh(
            ctx,
            format!(
                "grid_{}_{}_{}_{:?}_{:?}",
                width, height, thickness, line_color, square_colors
            ),
            &(|builder| {
                let xspacing = width / cols as f32;
                let yspacing = height / rows as f32;
                let mut color_idx = 0;

                if let Some(square_colors) = square_colors {
                    for x in 0..cols {
                        for y in 0..rows {
                            let x = x as f32;
                            let y = y as f32;
                            builder.rectangle(
                                DrawMode::fill(),
                                Rect::new(x * xspacing, y * yspacing, xspacing, yspacing),
                                square_colors[color_idx],
                            );
                            color_idx = if color_idx == 0 { 1 } else { 0 }
                        }
                        color_idx = if color_idx == 0 { 1 } else { 0 } //reset for next line
                    }
                }

                for x in 1..cols {
                    let x = x as f32;
                    builder.line(
                        &[pt(x * xspacing, 0.), pt(x * xspacing, height)],
                        thickness,
                        line_color,
                    )?;
                }

                for y in 1..rows {
                    let y = y as f32;
                    builder.line(
                        &[pt(0., y * yspacing), pt(width, y * yspacing)],
                        thickness,
                        line_color,
                    )?;
                }

                Ok(())
            }),
        )
    }

    pub fn make_triangle(
        &mut self,
        ctx: &mut Context,
        width: f32,
        height: f32,
        dir: Direction,
    ) -> GameResult<Rc<Mesh>> {
        self.make_mesh(
            ctx,
            format!("box_{}_{}_{:?}", width, height, dir),
            &(|builder| {
                match dir {
                    Direction::Up => builder.triangles(
                        &[pt(0., height), pt(width, height), pt(width * 0.5, 0.)],
                        WHITE,
                    )?,
                    Direction::Down => builder
                        .triangles(&[pt(0., 0.), pt(width, 0.), pt(width * 0.5, height)], WHITE)?,
                    Direction::Left => builder.triangles(
                        &[pt(width, 0.), pt(width, height), pt(0., height * 0.5)],
                        WHITE,
                    )?,
                    Direction::Right => builder.triangles(
                        &[pt(0., 0.), pt(0., height), pt(width, height * 0.5)],
                        WHITE,
                    )?,
                };

                Ok(())
            }),
        )
    }

    pub fn make_one_time_polyline(
        &mut self,
        ctx: &mut Context,
        pts: Vec<Point>,
        thickness: f32,
    ) -> GameResult<Rc<Mesh>> {
        let mut mesh_builder = MeshBuilder::new();

        mesh_builder.polyline(DrawMode::stroke(thickness), &pts, WHITE)?;

        let mesh = Rc::new(mesh_builder.build(ctx)?);
        Ok(mesh)
    }

    pub fn make_rect(
        &mut self,
        ctx: &mut Context,
        width: f32,
        height: f32,
        mode: DrawMode,
    ) -> GameResult<Rc<Mesh>> {
        self.make_mesh(
            ctx,
            format!("rect_{}_{}_{:?}", width, height, mode),
            &(|builder| {
                builder.rectangle(mode, Rect::new(0., 0., width, height), WHITE);
                Ok(())
            }),
        )
    }

    pub fn make_circle(
        &mut self,
        ctx: &mut Context,
        offset: f32,
        radius: f32,
        mode: DrawMode,
    ) -> GameResult<Rc<Mesh>> {
        self.make_mesh(
            ctx,
            format!("circle_{}_{:?}", radius, mode),
            &(|builder| {
                builder.circle(
                    mode,
                    pt(offset * 0.5, offset * 0.5),
                    radius,
                    TOLERANCE,
                    WHITE,
                );
                Ok(())
            }),
        )
    }

    pub fn draw_white_text(
        &mut self,
        ctx: &mut Context,
        text: &str,
        position: Point,
        font_size: f32,
        centered: bool,
    ) {
        self.draw_text(ctx, text, position, WHITE, font_size, centered);
    }

    pub fn draw_text(
        &mut self,
        ctx: &mut Context,
        text: &str,
        position: Point,
        color: Color,
        font_size: f32,
        centered: bool,
    ) {
        let text = Text::new(TextFragment {
            text: text.to_string(),
            color: Some(color),
            scale: Some(Scale::uniform(font_size)),
            ..TextFragment::default()
        });
        let mut xy = position;
        if centered {
            xy = pt(position.x - (text.width(ctx) as f32 / 2.), position.y);
        }
        self.draw_mesh(ctx, &text, xy);
    }

    #[allow(clippy::map_entry)] //I don't think this fix is practical
    pub fn make_mesh(
        &mut self,
        ctx: &mut Context,
        key: String,
        builder: &dyn Fn(&mut MeshBuilder) -> GameResult<()>,
    ) -> GameResult<Rc<Mesh>> {
        if self.mesh_cache.contains_key(&key) {
            Ok(self.mesh_cache[&key].clone())
        } else {
            let mut mesh_builder = MeshBuilder::new();

            builder(&mut mesh_builder)?;

            let mesh = Rc::new(mesh_builder.build(ctx)?);
            self.mesh_cache.insert(key, mesh.clone());
            Ok(mesh)
        }
    }

    pub fn draw_mesh<D: Drawable>(&mut self, ctx: &mut Context, mesh: &D, xy: Point) {
        graphics::draw(ctx, mesh, (xy,)).expect("couldn't draw");
    }

    pub fn draw_coloured_mesh<D: Drawable>(
        &mut self,
        ctx: &mut Context,
        mesh: &D,
        xy: Point,
        new_colour: Color,
    ) {
        graphics::draw(ctx, mesh, (xy, new_colour)).expect("couldn't draw");
    }

    // pub fn make_shogi_piece(&mut self, ctx: &mut Context, width: f32, height: f32) -> GameResult<Rc<Mesh>> {}
}

//! Mock request dispatcher and credentials for unit testing rusoto AWS service clients
//!
//! All rusoto generated service clients come with a constuctor function named `new_with` which
//! accepts three arguments
//!
//! * A `rusoto_core::DispatchSignedRequest` implementation
//! * A `rusoto_core::credential::ProvideAwsCredentials` implementation
//! * A `rusoto_core::Region`
//!
//! This crate provides mock implementations to satisfy the first two.
//!
//! # Example
//!
//! The following is an example for the `rusoto_s3` crate but should
//! work for all service crates just the same. The code is commented
//! out for illustration but also to avoid a cyclic dependency in this crate.
//!
//! ```rust
//! extern crate rusoto_mock;
//! // extern crate rusoto_s3;
//!
//! use rusoto_mock::{MockCredentialsProvider, MockRequestDispatcher, MockResponseReader};
//!
//! fn main() {
//!    // let s3 = rusoto_s3::S3Client::new_with(
//!    //   MockRequestDispatcher::default().with_body(
//!    //      MockResponseReader::read_response("test-data", "s3-response.json")
//!    //   ),
//!    //   MockCredentialsProvider,
//!    //   Default::default()
//!    // );
//! }
//! ```
#![deny(missing_docs)]
use std::fs::File;
use std::io::Read;
use std::sync::Mutex;
use std::time::Duration;

use async_trait::async_trait;
use futures::FutureExt;
use http::{header::HeaderName, HeaderMap, StatusCode};
use rusoto_core::credential::{AwsCredentials, ProvideAwsCredentials};
use rusoto_core::request::HttpResponse;
use rusoto_core::signature::SignedRequest;
use rusoto_core::{ByteStream, DispatchSignedRequest, HttpDispatchError};
use serde::Serialize;

/// Provides a set of credentials that always resolve
/// successfully
pub struct MockCredentialsProvider;

#[async_trait]
impl ProvideAwsCredentials for MockCredentialsProvider {
    async fn credentials(
        &self,
    ) -> Result<rusoto_core::credential::AwsCredentials, rusoto_core::credential::CredentialsError>
    {
        Ok(AwsCredentials::new("mock_key", "mock_secret", None, None))
    }
}

/// Composes mock API responses
///
/// A Default is provided which returns an successful response with an empty body
///
/// These can be constructed using either a Default implementation or
///  with the [with_status](method.with_status) function.
///
#[derive(Default)]
pub struct MockRequestDispatcher {
    outcome: RequestOutcome,
    body: Vec<u8>,
    headers: HeaderMap<String>,
    request_checker: Option<Box<dyn Fn(&SignedRequest) + Send + Sync>>,
}

enum RequestOutcome {
    Performed(StatusCode),
    Failed(HttpDispatchError),
}

impl Default for RequestOutcome {
    fn default() -> RequestOutcome {
        RequestOutcome::Performed(StatusCode::default())
    }
}

impl MockRequestDispatcher {
    /// Returns a instance that mocks the status code that would
    /// be returned from AWS
    pub fn with_status(status: u16) -> MockRequestDispatcher {
        MockRequestDispatcher {
            outcome: RequestOutcome::Performed(StatusCode::from_u16(status).unwrap()),
            ..MockRequestDispatcher::default()
        }
    }

    /// Mocks the service request failing with a communications error
    pub fn with_dispatch_error(error: HttpDispatchError) -> MockRequestDispatcher {
        MockRequestDispatcher {
            outcome: RequestOutcome::Failed(error),
            ..MockRequestDispatcher::default()
        }
    }

    /// Mocks the service response body what would be
    /// returned from AWS
    pub fn with_body(mut self, body: &str) -> MockRequestDispatcher {
        self.body = body.as_bytes().to_vec();
        self
    }

    /// Mocks the json serialized response body what would be
    /// returned from AWS
    pub fn with_json_body<B>(mut self, body: B) -> MockRequestDispatcher
    where
        B: Serialize,
    {
        self.body = serde_json::to_vec(&body).expect("failed to deserialize into json");
        self
    }

    /// Mocks the signed request checking applied to a request before sending
    /// to AWS
    pub fn with_request_checker<F>(mut self, checker: F) -> MockRequestDispatcher
    where
        F: Fn(&SignedRequest) + Send + Sync + 'static,
    {
        self.request_checker = Some(Box::new(checker));
        self
    }

    /// Mocks a single service header that would be returned from AWS
    pub fn with_header(mut self, key: &str, value: &str) -> MockRequestDispatcher {
        self.headers
            .insert(key.parse::<HeaderName>().unwrap(), value.into());
        self
    }
}

impl DispatchSignedRequest for MockRequestDispatcher {
    fn dispatch(
        &self,
        request: SignedRequest,
        _timeout: Option<Duration>,
    ) -> rusoto_core::request::DispatchSignedRequestFuture {
        if self.request_checker.is_some() {
            self.request_checker.as_ref().unwrap()(&request);
        }
        match self.outcome {
            RequestOutcome::Performed(ref status) => futures::future::ready(Ok(HttpResponse {
                status: *status,
                body: ByteStream::from(self.body.clone()),
                headers: self.headers.clone(),
            }))
            .boxed(),
            RequestOutcome::Failed(ref error) => futures::future::ready(Err(error.clone())).boxed(),
        }
    }
}

/// An interface for producing response body content
pub trait ReadMockResponse {
    /// Return a response body string for a given directory and file name
    fn read_response(dir_name: &str, file_name: &str) -> String;
}

/// Reads response body content from disk
pub struct MockResponseReader;

impl ReadMockResponse for MockResponseReader {
    fn read_response(dir_name: &str, response_name: &str) -> String {
        let file_name = format!("{}/{}", dir_name, response_name);

        let mut input_file = File::open(&file_name).expect("couldn't find file");

        let mut mock_response = String::new();

        input_file
            .read_to_string(&mut mock_response)
            .unwrap_or_else(|_| panic!("Failed to read {:?}", file_name));

        mock_response
    }
}

/// Returns sequential mock API responses consuming a collection of MockRequestDispatch
pub struct MultipleMockRequestDispatcher<I>
where
    I: Iterator<Item = MockRequestDispatcher>,
{
    iterator: Mutex<I>,
}

impl<I> MultipleMockRequestDispatcher<I>
where
    I: Iterator<Item = MockRequestDispatcher>,
{
    /// Constructs a new MultipleMockRequestDispatcher with a collection of MockRequestDispatch as input
    pub fn new<C>(collection: C) -> MultipleMockRequestDispatcher<I>
    where
        C: IntoIterator<Item = MockRequestDispatcher>,
        C: IntoIterator<IntoIter = I>,
    {
        MultipleMockRequestDispatcher {
            iterator: Mutex::new(collection.into_iter()),
        }
    }
}

impl<I> DispatchSignedRequest for MultipleMockRequestDispatcher<I>
where
    I: Iterator<Item = MockRequestDispatcher>,
{
    fn dispatch(
        &self,
        request: SignedRequest,
        _timeout: Option<Duration>,
    ) -> rusoto_core::request::DispatchSignedRequestFuture {
        self.iterator
            .lock()
            .unwrap()
            .next()
            .expect("Ran out of mock responses to return from MultipleMockRequestDispatcher")
            .dispatch(request, _timeout)
    }
}

