use crate::{
    cfgir::absint::*,
    parser::ast::Var,
    shared::{unique_map::UniqueMap, *},
};
use move_ir_types::location::*;

//**************************************************************************************************
// Abstract state
//**************************************************************************************************

#[derive(Clone)]
pub enum LocalState {
    // Local does not have a value
    Unavailable(Loc),
    // Local has a value
    Available(Loc),
    // Available in some branches but not all. If it is a resource, cannot be assigned
    MaybeUnavailable { available: Loc, unavailable: Loc },
}

impl LocalState {
    pub fn is_available(&self) -> bool {
        match self {
            LocalState::Available(_) => true,
            LocalState::Unavailable(_) | LocalState::MaybeUnavailable { .. } => false,
        }
    }
}

#[derive(Clone)]
pub struct LocalStates {
    local_states: UniqueMap<Var, LocalState>,
}

impl LocalStates {
    pub fn initial<T>(function_arguments: &[(Var, T)], local_types: &UniqueMap<Var, T>) -> Self {
        let mut states = LocalStates {
            local_states: UniqueMap::new(),
        };
        for (var, _) in local_types.key_cloned_iter() {
            let local_state = LocalState::Unavailable(var.loc());
            states.set_state(var, local_state)
        }
        for (var, _) in function_arguments {
            let local_state = LocalState::Available(var.loc());
            states.set_state(*var, local_state)
        }
        states
    }

    pub fn get_state(&self, local: &Var) -> &LocalState {
        self.local_states
            .get(local)
            .unwrap_or_else(|| panic!("{:#?}{:#?}", local.loc(), local))
    }

    pub fn set_state(&mut self, local: Var, state: LocalState) {
        self.local_states.remove(&local);
        self.local_states.add(local, state).unwrap();
    }

    pub fn iter(&self) -> impl Iterator<Item = (Var, &LocalState)> {
        self.local_states.key_cloned_iter()
    }

    #[allow(dead_code)]
    pub fn debug(&self) {
        use LocalState as L;
        for (var, state) in self.iter() {
            print!("{}: ", var);
            match state {
                L::Unavailable(_) => println!("Unavailable"),
                L::Available(_) => println!("Available"),
                L::MaybeUnavailable { .. } => println!("MaybeUnavailable"),
            }
        }
    }
}

impl AbstractDomain for LocalStates {
    fn join(&mut self, other: &Self) -> JoinResult {
        use LocalState as L;
        let mut result = JoinResult::Unchanged;
        for (local, other_state) in other.local_states.key_cloned_iter() {
            match (self.get_state(&local), other_state) {
                // equal so nothing to do
                (L::Unavailable(_), L::Unavailable(_))
                | (L::Available(_), L::Available(_))
                | (L::MaybeUnavailable { .. }, L::MaybeUnavailable { .. }) => (),
                // if its partially assigned, stays partially assigned
                (L::MaybeUnavailable { .. }, _) => (),

                // if was partially assigned in other, its now partially assigned
                (_, L::MaybeUnavailable { .. }) => {
                    result = JoinResult::Changed;
                    let state = other_state.clone();
                    self.set_state(local, state)
                }

                // Available in one but not the other, so maybe unavailable
                (L::Available(available), L::Unavailable(unavailable))
                | (L::Unavailable(unavailable), L::Available(available)) => {
                    result = JoinResult::Changed;
                    let available = *available;
                    let unavailable = *unavailable;
                    let state = L::MaybeUnavailable {
                        available,
                        unavailable,
                    };

                    self.set_state(local, state)
                }
            }
        }

        result
    }
}

mod config;
mod logger;
mod profile;
mod slurm;

use std::{fs, path::PathBuf, process::Command};

use anyhow::{Context, Result};
use clap::{AppSettings, Parser};
use log::{debug, info, warn};

use config::{get_config_path, Config};
use profile::Profile;

#[derive(Debug, Parser)]
#[clap(version, about)]
#[clap(global_setting(AppSettings::ArgRequiredElseHelp))]
#[clap(global_setting(AppSettings::HelpExpected))]
#[clap(global_setting(AppSettings::DeriveDisplayOrder))]
struct Cli {
    /// Custom config file location
    #[clap(long, value_name = "PATH")]
    config: Option<PathBuf>,
    /// Profile name to use
    #[clap(long, value_name = "NAME")]
    profile: Option<String>,
    /// Export to sbatch script instead of executing srun command
    #[clap(long, value_name = "PATH")]
    export: Option<PathBuf>,
    #[clap(flatten)]
    args: Profile,
    /// DO NOT execute; just print the command/script on stdout
    #[clap(long)]
    dry_run: bool,
}

fn main() -> Result<()> {
    logger::init().context("cannot initialize logger")?;

    let cli = Cli::parse();
    debug!("command line arguments:\n{:?}", cli);

    let filepath = get_config_path(cli.config).context("cannot find the config file path")?;
    info!("read config from {}", filepath.as_path().display());

    let content = fs::read_to_string(filepath).context("cannot read the content of config file")?;
    let mut config: Config = toml::from_str(&content).context("cannot parse the content")?;
    debug!("config:\n{:?}", config);

    let profile_name = cli
        .profile
        .or({
            warn!("use default profile name in config file");
            config.default
        })
        .context("cannot determine which profile to use")?;
    info!("profile name: {}", profile_name);

    let profile = config
        .profile
        .remove(&profile_name)
        .context(format!("the profile {} does not exist", profile_name))?
        .overwrite(cli.args);
    debug!("profile:\n{}", toml::to_string(&profile)?);

    match cli.export {
        Some(scriptfile) => {
            let script = slurm::sbatch(&profile).context("cannot generate sbatch script")?;
            if cli.dry_run || cfg!(debug_assertions) {
                info!("generated sbatch script:");
                println!("{}", script);
            } else {
                fs::write(&scriptfile, script).context(format!(
                    "cannot write sbatch script to {}",
                    scriptfile.as_path().display()
                ))?;
                info!("sbatch script at {}", scriptfile.as_path().display());
                let mut process = Command::new("sbatch")
                    .arg(scriptfile.as_path())
                    .spawn()
                    .context("failed to execute sbatch")?;
                process.wait().context("sbatch wasn't running")?;
            }
        }
        None => {
            let arguments = slurm::srun(&profile).context("cannot generate srun arguments")?;
            if cli.dry_run || cfg!(debug_assertions) {
                info!("generated srun command:");
                println!("srun {}", arguments.join(" "));
            } else {
                info!("executing srun");
                let mut process = Command::new("srun")
                    .args(arguments)
                    .spawn()
                    .context("failed to execute srun")?;
                process.wait().context("srun wasn't running")?;
            }
        }
    };
    Ok(())
}

