/// Read buffer for connected peer(`PeerMessage`).
///
/// This message can be split into multiple chunks. Encrypted part of
/// the first chunk includes information (`4 bytes`) about whole message's
/// size. We need to process chunks until decrypted accumulated message
/// isn't of that size.
#[derive(Debug, Clone)]
pub struct MessageReadBuffer {
    message_buf: Vec<u8>,
    message_len: usize,
    /// Bytes read for current message.
    read_bytes: usize,
    chunk_reader: ChunkReadBuffer,
}

impl MessageReadBuffer {
    pub fn new() -> Self {
        Self {
            message_buf: vec![],
            message_len: 0,
            read_bytes: 0,
            chunk_reader: ChunkReadBuffer::new(),
        }
    }

    pub fn is_finished(&self) -> bool {
        self.message_len > 0 && self.message_buf.len() >= self.message_len
    }

    /// Returns if more might be available to be read.
    fn _read_from<R: Read>(
        &mut self,
        reader: &mut R,
        crypto: &mut PeerCrypto,
    ) -> Result<PeerMessageResponse, ReadMessageError> {
        loop {
            self.chunk_reader.read_from(reader)?;
            // TODO: As an optimization, stop reading
            // if `message_len < message_buf.len() + chunk_expected_len`.
            // Technically shouldn't happen, but if it does, then peer
            // has issue with encoding/chunking.

            if let Some(chunk) = self.chunk_reader.take_ref_if_ready() {
                let mut decrypted = crypto.decrypt(&chunk.content())?;

                if self.message_len == 0 {
                    self.message_len = PeerMessageResponse::size_from_chunk(&decrypted)?;
                }
                self.message_buf.append(&mut decrypted);

                if self.is_finished() {
                    return self.take_and_decode();
                }
            }
        }
    }

    pub fn read_from<R: Read>(
        &mut self,
        reader: &mut R,
        crypto: &mut PeerCrypto,
    ) -> Result<PeerMessageResponse, ReadMessageError> {
        let mut counted_reader = ReadCounter::new(reader);
        let result = self._read_from(&mut counted_reader, crypto);
        self.read_bytes += counted_reader.result();
        result
    }

    fn take_and_decode(&mut self) -> Result<PeerMessageResponse, ReadMessageError> {
        let result = PeerMessageResponse::from_bytes(&self.message_buf);
        let read_bytes = self.read_bytes;

        self.clear();
        let mut resp = result?;
        resp.set_size_hint(read_bytes);
        Ok(resp)
    }

    pub fn clear(&mut self) {
        self.message_buf.clear();
        self.message_len = 0;
        self.read_bytes = 0;
        self.chunk_reader.clear();
    }
}

/// Counts exactly how many bytes were read from the stream.
struct ReadCounter<'a, R> {
    reader: &'a mut R,
    read_bytes: usize,
}

impl<'a, R> ReadCounter<'a, R> {
    pub fn new(reader: &'a mut R) -> Self {
        Self {
            reader,
            read_bytes: 0,
        }
    }

    pub fn result(self) -> usize {
        self.read_bytes
    }
}

impl<'a, R: Read> Read for ReadCounter<'a, R> {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        let size = self.reader.read(buf)?;
        self.read_bytes += size;
        Ok(size)
    }
}

use crate::prelude::*;

use enso_macro_utils::field_names;
use enso_macro_utils::identifier_sequence;
use enso_macro_utils::index_sequence;
use enso_macro_utils::path_matching_ident;
use syn::Attribute;
use syn::DeriveInput;
use syn::Data;
use syn::DataEnum;
use syn::DataStruct;
use syn::Fields;
use syn::Ident;
use syn::Lit;
use syn::Meta;
use syn::MetaNameValue;
use syn::NestedMeta;
use syn::Variant;
use syn::WhereClause;
use syn::WherePredicate;



// ==============
// === Consts ===
// ==============

/// Name of the custom attribute allowing customizing behavior of the generated `CloneRef`
/// implementation.
const CLONE_REF_ATTR:&str = "clone_ref";

/// Name of the property within customization attribute that allows defining custom bounds for
/// the generated `CloneRef` implementation.
const BOUND_NAME:&str = "bound";



// ============================
// === CloneRef for structs ===
// ============================

/// `clone_ref` function body for a given `struct` definition.
pub fn body_for_struct(ident:&Ident, data:&DataStruct) -> TokenStream {
    match data.fields {
        Fields::Unit =>
            // Foo
            quote!( #ident ),
        Fields::Unnamed(ref fields) => {
            let indices = index_sequence(fields.unnamed.len());
            // Foo(self.0.clone_ref())
            quote!(
                #ident(#(self.#indices.clone_ref()),*)
            )
        }
        Fields::Named(ref fields)  => {
            let names = field_names(fields);
            // Foo { field0 : self.field0.clone_ref() }
            quote!(
                #ident {
                    #(#names : self.#names.clone_ref()),*
                }
            )
        }
    }
}



// ==========================
// === CloneRef for enums ===
// ==========================

/// Prepares a match arm for a single variant that `clone_ref`s such value.
pub fn arm_for_variant(data_ident:&Ident,variant:&Variant) -> TokenStream {
    let fields = &variant.fields;
    let variant_ident = &variant.ident;
    match fields {
        Fields::Unit => {
            // Enum::Var => Enum::Var
            quote!(
                #data_ident::#variant_ident => #data_ident::#variant_ident
            )
        }
        Fields::Named(fields) => {
            let names = field_names(fields);
            // Enum::Var {field0} => Enum::Var {field0 : field0.clone_ref()}
            quote!(
                #data_ident::#variant_ident { #(#names),* } =>
                    #data_ident::#variant_ident {
                        #( #names : #names.clone_ref() ),*
                    }
            )
        }
        Fields::Unnamed(fields) => {
            let names = identifier_sequence(fields.unnamed.len());
            // Enum::Var(field0) => Enum::Var(field0.clone_ref())
            quote!(
                #data_ident::#variant_ident(#(#names),*) =>
                    #data_ident::#variant_ident(
                        #( #names.clone_ref() ),*
                    )
            )
        }
    }
}

/// `clone_ref` function body for a given `enum` definition.
pub fn body_for_enum(ident:&Ident, data:&DataEnum) -> TokenStream {
    if data.variants.is_empty() {
        quote!(panic!("There cannot exist value of empty enum, so its clone_ref must not be called."))
    } else {
        let make_arm = |variant| arm_for_variant(ident,variant);
        let arms     = data.variants.iter().map(make_arm);
        quote!(
            match self { #(#arms),* }
        )
    }
}



// ============================
// === Bounds customization ===
// ============================

/// Checks if the given attribute is our customization attribute.
pub fn is_clone_ref_customization(attr:&Attribute) -> bool {
    path_matching_ident(&attr.path,CLONE_REF_ATTR)
}

/// Checks if the given Meta name-val pair defines user-provided bounds.
pub fn is_custom_bound(name_val:&MetaNameValue) -> bool {
    path_matching_ident(&name_val.path,BOUND_NAME)
}

/// If this is our customization attribute, we retrieve user-provided bounds for the generated
/// `CloneRef` implementation.
///
/// Returns `None` is this is third-party attribute.
/// Panics if this is our attribute but the syntax is not correct.
pub fn clone_ref_bounds(attr:&Attribute) -> Option<Vec<WherePredicate>> {
    // Silently ignore foreign attributes. Be picky only about our one.
    is_clone_ref_customization(attr).then(())?;

    let meta = attr.parse_meta().expect("Failed to parse attribute contents.");
    let list = match meta {
        Meta::List(ml) => ml.nested,
        _              => panic!("Attribute contents does not conform to meta item."),
    };
    if list.len() > 1 {
        panic!("Only a single entry within `{}` attribute is allowed.",CLONE_REF_ATTR);
    }
    let bound_value = match list.first() {
        Some(NestedMeta::Meta(Meta::NameValue(name_val))) => {
            if is_custom_bound(name_val) {
                &name_val.lit
            } else {
                panic!("`{}` attribute can define value only for `{}`.",CLONE_REF_ATTR,BOUND_NAME)
            }
        }
        Some(_) =>
            panic!("`{}` attribute must contain a single name=value assignment.",CLONE_REF_ATTR),
        None =>
            panic!("`{}` attribute must not be empty.",CLONE_REF_ATTR),
    };
    let bound_str = if let Lit::Str(lit_str) = bound_value {
        lit_str
    } else {
        panic!("`{}` value must be a string literal describing `where` predicates.",BOUND_NAME)
    };
    let bounds_text = format!("where {}", bound_str.value());
    let bounds      = syn::parse_str::<WhereClause>(&bounds_text);
    let bounds      = bounds.unwrap_or_else(|_| {
        panic!("Failed to parse user-provided where clause: `{}`.",bounds_text)
    });
    let ret = bounds.predicates.into_iter().collect();
    Some(ret)
}



// ===================
// === Entry Point ===
// ===================

/// Derives `CloneRef` implementation, refer to `crate::derive_clone_ref` for details.
pub fn derive
(input:proc_macro::TokenStream) -> proc_macro::TokenStream {
    let decl   = syn::parse_macro_input!(input as DeriveInput);
    let ident  = &decl.ident;
    let body   = match &decl.data {
        Data::Struct(data_struct) => body_for_struct(ident,data_struct),
        Data::Enum(data_enum)     => body_for_enum(ident,data_enum),
        Data::Union(_)            =>
            panic!("CloneRef cannot be derived for an untagged union input."),
    };

    let (impl_generics, ty_generics, inherent_where_clause_opt) = &decl.generics.split_for_impl();

    // Where clause must contain both user-provided bounds and bounds inherent due to type
    // declaration-level where clause.
    let user_requested_bounds = decl.attrs.iter().filter_map(clone_ref_bounds).flatten();
    let mut where_clause      = enso_macro_utils::new_where_clause(user_requested_bounds);
    for inherent_where_clause in inherent_where_clause_opt {
        where_clause.predicates.extend(inherent_where_clause.predicates.iter().cloned())
    }

    let output = quote!{
        impl #impl_generics CloneRef for #ident #ty_generics
        #where_clause {
            fn clone_ref(&self) -> Self {
                #body
            }
        }

        impl #impl_generics From<& #ident #ty_generics> for #ident #ty_generics
        #where_clause {
            fn from(t:& #ident #ty_generics) -> Self {
                t.clone_ref()
            }
        }
    };
    output.into()
}

use crate::io::{DataSource, ReadState};
use std::path::PathBuf;
use std::fs::File;
use std::io::{Read, Seek, SeekFrom};

pub const BUFFER_SIZE: usize = 65535;

pub struct FileReader {
    path: PathBuf,
    file: File,
    separator: u32,
    buffer: [u8; BUFFER_SIZE],
    buf_pos: u16,
    buf_size: u16,
    references: Vec<FileRef>,
    ref_pos: u32
}

impl FileReader {
    pub fn new(path: String, cache: bool) -> Result<Self, String> {
        let mut pb = PathBuf::from(path);
        if !pb.exists() {
            return Err("File not found".to_string());
        }
        let mut file = match File::open(pb) {
            Ok(x) => x,
            Err(x) => {
                return Err(format!("Opening file failed: {}", x).to_string());
            }
        };
        let mut fr = FileReader {
            path: Default::default(),
            file,
            separator: 13, // New line character,
            buffer: [0u8; BUFFER_SIZE],
            buf_pos: 0,
            buf_size: 0,
            references: Vec::new(),
            ref_pos: 0
        };
        loop {
            fr.references.push(match fr.read_next_line_internal(cache) {
                ReadState::Successful(line) => line,
                ReadState::EndOfData => break,
                ReadState::Error(e) => return Err(e)
            });
        }
        Ok(fr)
    }

    fn refill_buffer(&mut self) -> ReadState<()> {
        self.buf_size = match self.file.read(&mut self.buffer) {
            Ok(x) => {
                if x == 0 {
                    return ReadState::EndOfData;
                }
                x
            }
            Err(e) => return ReadState::Error(format!("Reading line from file failed: {}", e))
        } as u16;
        ReadState::Successful(())
    }

    fn next_byte(&mut self) -> ReadState<u8> {
        if self.buf_pos >= self.buf_size {
            match self.refill_buffer() {
                ReadState::Successful(_) => {}
                ReadState::EndOfData => return ReadState::EndOfData,
                ReadState::Error(x) => return ReadState::Error(x)
            }
        }
        let ret = unsafe { *self.buffer.get_unchecked(self.buf_pos as usize) };
        self.buf_pos += 1;
        ReadState::Successful(ret)
    }

    fn next_utf8_char(&mut self) -> ReadState<u32> {
        let b = match self.next_byte() {
            ReadState::Successful(x) => x,
            ReadState::EndOfData => return ReadState::EndOfData,
            ReadState::Error(x) => return ReadState::Error(x)
        };

        if b >> 7 != 1 {
            return ReadState::Successful(b as u32);
        }
        let mut out = 0u32;
        let mut read = 0u8;
        if b >> 5 == 6 { // 2 bytes inc. this
            out |= (b as u32 & 0x11111) << 6;
            read = 1;
        } else if b >> 4 == 14 { // 3 bytes inc. this
            out |= (b as u32 & 0x1111) << 12;
            read = 2;
        } else if b >> 3 == 30 { // 4 bytes inc. this
            out |= (b as u32 & 0x111) << 18;
            read = 3;
        }

        for i in 0..read {
            let nb = match self.next_byte() {
                ReadState::Successful(x) => x,
                ReadState::EndOfData => return ReadState::EndOfData,
                ReadState::Error(x) => return ReadState::Error(x)
            };
            if nb >> 6 != 2 {
                return ReadState::Successful(0xFFFD); // Encoding this results in [EF, BF, BD] also known as �
            }
            out |= (nb as u32 & 0b111111) << (6 * (2 - i)) as u32;
        }

        ReadState::Successful(out)
    }

    pub(in self) fn read_next_line_internal(&mut self, cache: bool) -> ReadState<FileRef> {
        let starting_pos = match self.file.seek(SeekFrom::Current(0)) {
            Ok(x) => x,
            Err(e) => return ReadState::Error(format!("Failed to get stream position"))
        };
        loop {
            let c = match self.next_utf8_char() {
                ReadState::Successful(x) => x,
                ReadState::EndOfData => {
                    let pos = match self.file.seek(SeekFrom::Current(0)) {
                        Ok(x) => x,
                        Err(e) => return ReadState::Error(format!("Failed to get stream position"))
                    };
                    if starting_pos < pos {
                        let len = pos - starting_pos;
                        return ReadState::Successful(FileRef {
                            pos: starting_pos,
                            len: len as usize,
                            content: if cache {
                                if let Err(e) = file.seek(SeekFrom::Current(-len as i64)) {
                                    return ReadState::Error(format!("Failed setting stream position: {}", e));
                                }
                                let mut buffer = vec![0u8; self.len];
                                match file.read(buffer.as_mut()) {
                                    Ok(x) => {
                                        if x < len as usize {
                                            return ReadState::Error(format!("Reading the file failed, size of returned bytes was to small. Expected: {} Got: {}", self.len, x));
                                        }
                                        Some(buffer)
                                    }
                                    Err(e) => ReadState::Error(format!("Reading the file failed: {}", e))
                                }
                            } else { None }
                        });
                    }
                    return ReadState::EndOfData;
                }
                ReadState::Error(x) => return ReadState::Error(x)
            };
            let len = (match self.file.seek(SeekFrom::Current(0)) {
                Ok(x) => x,
                Err(e) => return ReadState::Error(format!("Failed to get stream position"))
            } - starting_pos) as usize;
            if c == self.separator {
                return ReadState::Successful(FileRef {
                    pos: starting_pos,
                    len,
                    content: if cache {
                        if let Err(e) = file.seek(SeekFrom::Current(-len as i64)) {
                            return ReadState::Error(format!("Failed setting stream position: {}", e));
                        }
                        let mut buffer = vec![0u8; self.len];
                        match file.read(buffer.as_mut()) {
                            Ok(x) => {
                                if x < len as usize {
                                    return ReadState::Error(format!("Reading the file failed, size of returned bytes was to small. Expected: {} Got: {}", self.len, x));
                                }
                                Some(buffer)
                            }
                            Err(e) => ReadState::Error(format!("Reading the file failed: {}", e))
                        }
                    } else { None }
                });
            }
        }
    }
}

impl DataSource for FileReader {
    fn next_line(&mut self) -> ReadState<Vec<u8>> {
        if self.ref_pos >= self.references.len() as u32 {
            return ReadState::EndOfData;
        }
        let r: &FileRef = unsafe { self.references.get_unchecked(self.ref_pos) };
        self.ref_pos += 1;
        ReadState::Successful(match r.read(self) {
            ReadState::Successful(x) => x,
            ReadState::EndOfData => panic!("Reading a FileRef returned EndOfData. This is a invalid state!"),
            ReadState::Error(e) => return ReadState::Error(e)
        })
    }
}

pub struct FileRef {
    pos: u64,
    len: usize,
    content: Option<Vec<u8>>
}

impl FileRef {
    fn read(&self, fr: &mut FileReader) -> ReadState<Vec<u8>> {
        let file = &mut fr.file;
        let cur_pos = match file.seek(SeekFrom::Current(0)) {
            Ok(x) => x,
            Err(e) => return ReadState::Error(format!("Failed reading stream position: {}", e))
        };
        if let Err(e) = file.seek(SeekFrom::Start(self.pos)) {
            return ReadState::Error(format!("Failed setting stream position: {}", e));
        }
        let mut buffer = vec![0u8; self.len];
        match file.read(buffer.as_mut()) {
            Ok(x) => {
                if x < self.len as usize {
                    return ReadState::Error(format!("Reading the file failed, size of returned bytes was to small. Expected: {} Got: {}", self.len, x));
                }
                ReadState::Successful(buffer)
            }
            Err(e) => ReadState::Error(format!("Reading the file failed: {}", e))
        }
    }
}

