        for idx in 0..chunk_count {
            chunk_map.set_ready(chunks[idx as usize].as_ref()).unwrap();
        }
        for idx in 0..chunk_count {
            assert_eq!(
                chunk_map
                    .has_ready(chunks[idx as usize].as_ref(), false)
                    .unwrap(),
                true
            );
        }
    }

