use proc_macro2::TokenStream;
use quote::{ToTokens, TokenStreamExt};
use syn::ItemMod;

use crate::{do_cxx_cpp_generation, parse_file::CppBuildable, CppCodegenOptions, GeneratedCpp};

/// A struct to represent a cxx::bridge (i.e. some manual bindings)
/// found in a file. autocxx knows about them so that we can generate C++
/// for both manual and automatic bindings using the same tooling.
pub struct CxxBridge {
    tokens: TokenStream,
}

impl From<ItemMod> for CxxBridge {
    fn from(itm: ItemMod) -> Self {
        Self {
            tokens: itm.to_token_stream(),
        }
    }
}

impl ToTokens for CxxBridge {
    fn to_tokens(&self, tokens: &mut TokenStream) {
        tokens.append_all(self.tokens.clone());
    }
}

impl CppBuildable for CxxBridge {
    fn generate_h_and_cxx(
        &self,
        cpp_codegen_options: &CppCodegenOptions,
    ) -> Result<GeneratedCpp, cxx_gen::Error> {
        let fp = do_cxx_cpp_generation(self.tokens.clone(), cpp_codegen_options)?;
        Ok(GeneratedCpp(vec![fp]))
    }
}

use chrono::Utc;
use diesel::{insert_into, prelude::*, update};

use log;
use mustache;
use serde::ser::Serialize;

use super::{
    errors::{Error, Result},
    orm::{schema::locales, Connection as Db},
};

pub fn languages(db: &Db) -> Result<Vec<String>> {
    Ok(locales::dsl::locales
        .select(locales::dsl::lang)
        .distinct()
        .load::<String>(db)?)
}

pub fn get(db: &Db, lang: &String, code: &String) -> Result<String> {
    let msg = locales::dsl::locales
        .select(locales::dsl::message)
        .filter(locales::dsl::lang.eq(lang))
        .filter(locales::dsl::code.eq(code))
        .first::<String>(db)?;
    Ok(msg)
}
pub fn set(db: &Db, lang: &String, code: &String, message: &String) -> Result<i64> {
    let now = Utc::now().naive_utc();
    match locales::dsl::locales
        .select(locales::dsl::id)
        .filter(locales::dsl::lang.eq(lang))
        .filter(locales::dsl::code.eq(code))
        .first::<i64>(db)
    {
        Ok(id) => {
            let it = locales::dsl::locales.filter(locales::dsl::id.eq(&id));
            update(it)
                .set((
                    locales::dsl::message.eq(message),
                    locales::dsl::updated_at.eq(&now),
                ))
                .execute(db)?;
            Ok(id)
        }
        Err(_) => {
            let id = insert_into(locales::dsl::locales)
                .values((
                    locales::dsl::lang.eq(lang),
                    locales::dsl::code.eq(code),
                    locales::dsl::message.eq(message),
                    locales::dsl::created_at.eq(&now),
                    locales::dsl::updated_at.eq(&now),
                ))
                .returning(locales::dsl::id)
                .get_result::<i64>(db)?;
            Ok(id)
        }
    }
}

pub fn tr<S: Serialize>(db: &Db, lang: &String, code: &String, args: &Option<S>) -> Result<String> {
    let msg = get(db, lang, code)?;
    if let Some(args) = args {
        let tpl = mustache::compile_str(&msg)?;
        return Ok(tpl.render_to_string(args)?);
    }
    return Ok(msg);
}

pub fn e<S: Serialize>(db: &Db, lang: &String, code: &String, args: &Option<S>) -> Error {
    t(db, lang, code, args).into()
}

pub fn t<S: Serialize>(db: &Db, lang: &String, code: &String, args: &Option<S>) -> String {
    match tr(db, lang, code, args) {
        Ok(msg) => msg,
        Err(e) => {
            log::error!("{:?}", e);
            format!("{}.{}", lang, code)
        }
    }
}

use proc_macro2::TokenStream;
use quote::quote;
use syn::{self, Data, Fields};

use crate::util;

pub fn build_derive_object(ast: syn::DeriveInput, is_internal: bool) -> TokenStream {
    let struct_fields = match ast.data {
        Data::Struct(data) => match data.fields {
            Fields::Named(fields) => fields.named,
            _ => {
                panic!("#[derive(GraphQLObject)] may only be used on regular structs with fields");
            }
        },
        _ => {
            panic!("#[derive(GraphlQLObject)] may only be applied to structs, not to enums");
        }
    };

    // Parse attributes.
    let attrs = match util::ObjectAttributes::from_attrs(&ast.attrs) {
        Ok(a) => a,
        Err(e) => {
            panic!("Invalid #[graphql(...)] attribute: {}", e);
        }
    };
    if !attrs.interfaces.is_empty() {
        panic!("Invalid #[graphql(...)] attribute 'interfaces': #[derive(GraphQLObject) does not support 'interfaces'");
    }
    let ident = &ast.ident;
    let name = attrs.name.unwrap_or_else(|| ident.to_string());

    let fields = struct_fields.into_iter().filter_map(|field| {
        let field_attrs = match util::FieldAttributes::from_attrs(
            field.attrs,
            util::FieldAttributeParseMode::Object,
        ) {
            Ok(attrs) => attrs,
            Err(e) => panic!("Invalid #[graphql] attribute: \n{}", e),
        };

        if field_attrs.skip {
            None
        } else {
            let field_name = field.ident.unwrap();
            let name = field_attrs
                .name
                .clone()
                .unwrap_or_else(|| util::to_camel_case(&field_name.to_string()));

            let resolver_code = quote!(
                &self . #field_name
            );

            Some(util::GraphQLTypeDefinitionField {
                name,
                _type: field.ty,
                args: Vec::new(),
                description: field_attrs.description,
                deprecation: field_attrs.deprecation,
                resolver_code,
                is_type_inferred: true,
                is_async: false,
            })
        }
    });

    let definition = util::GraphQLTypeDefiniton {
        name,
        _type: syn::parse_str(&ast.ident.to_string()).unwrap(),
        context: attrs.context,
        scalar: attrs.scalar,
        description: attrs.description,
        fields: fields.collect(),
        generics: ast.generics,
        interfaces: None,
        include_type_generics: true,
        generic_scalar: true,
        no_async: attrs.no_async,
    };

    let juniper_crate_name = if is_internal { "crate" } else { "juniper" };
    definition.into_tokens(juniper_crate_name)
}

