};

use confique::Config as _;
use tobira_util::prelude::*;


/// The locations where Tobira will look for a configuration file. The first
/// existing file in this list is used.
// TODO: does the absolute path break on Windows? I hope it just results in
// "file not found". Or do we want to have a different path for Windows?
const DEFAULT_PATHS: &[&str] = &["config.toml", "/etc/tobira/config.toml"];

/// Configuration for Tobira.
///
/// All relative paths are relative to the location of this configuration file.
#[derive(Debug, confique::Config)]
pub(crate) struct Config {
    #[config(nested)]
    pub(crate) general: GeneralConfig,

    #[config(nested)]
    pub(crate) db: crate::db::DbConfig,

    #[config(nested)]
    pub(crate) http: crate::http::HttpConfig,

    #[config(nested)]
    pub(crate) log: crate::logger::LogConfig,

    #[config(nested)]
    pub(crate) sync: crate::sync::SyncConfig,

    #[config(nested)]
    pub(crate) theme: crate::theme::ThemeConfig,
}

#[derive(Debug, confique::Config)]
pub(crate) struct GeneralConfig {
    /// The main title of the video portal. Used in the HTML `<title>`, as main
    /// heading on the home page, and potentially more.
    ///
    /// TODO: Make it possible to specify this for different languages.
    pub(crate) site_title: String,
}


impl Config {
    /// Tries to find a config file from a list of possible default config file
    /// locations. The first config file is loaded via [`Self::load_from`].
    pub fn from_default_locations() -> Result<Self> {
        let path = DEFAULT_PATHS.iter()
            .map(Path::new)
            .find(|p| p.exists())
            .ok_or(anyhow!(
                "no configuration file found. Note: we checked the following paths: {}",
                DEFAULT_PATHS.join(", "),
            ))?;

        let config = Self::load_from(path)
            .context(format!("failed to load configuration from '{}'", path.display()))?;

        Ok(config)
    }

    /// Loads the configuration from a specific TOML file.
    pub fn load_from(path: impl AsRef<Path>) -> Result<Self> {
        let path = path.as_ref();
        info!("Loading configuration from '{}'", path.display());

        let mut config = Config::from_file(path)
            .context(format!("failed to read config file '{}'", path.display()))?;

        config.validate().context("failed to validate configuration")?;
        config.fix_paths(path)?;

        Ok(config)
    }

    /// Performs some validation of the configuration to find some
    /// illegal or conflicting values.
    fn validate(&self) -> Result<()> {
        debug!("Validating configuration...");
        self.sync.validate()?;

        Ok(())
    }

    /// Goes through all paths in the configuration and changes relative paths
    /// to be absolute based on the path of the configuration file itself.
    fn fix_paths(&mut self, config_path: &Path) -> Result<()> {
        fn fix_path(base_path: &Path, path: &mut PathBuf) {
            if path.is_relative() {
                *path = base_path.join(&path);
            }
        }

        let absolute_config_path = config_path.canonicalize()
            .context("failed to canonicalize config path")?;
        let base = absolute_config_path.parent()
            .expect("config file path has no parent");

        if let Some(p) = &mut self.http.unix_socket {
            fix_path(&base, p);
        }

        if let Some(p) = &mut self.log.file {
            fix_path(&base, p);
        }

        fix_path(&base, &mut self.theme.logo.large.path);
        fix_path(&base, &mut self.theme.logo.small.path);

        Ok(())
    }
}

/// Writes the generated TOML config template file to the given destination or
/// stdout.
pub(crate) fn write_template(path: Option<&PathBuf>) -> Result<()> {
    use confique::toml::FormatOptions;

    info!(
        "Writing configuration template to '{}'",
        path.map(|p| p.display().to_string()).unwrap_or("<stdout>".into()),
    );

    let template = confique::toml::format::<Config>(FormatOptions::default());
    match path {
        Some(path) => fs::write(path, template)?,
        None => io::stdout().write_all(template.as_bytes())?,
    }

    Ok(())
}

use std::iter::repeat;

use attasm::ast::Arg;
use attasm::ast::Instruction;
use attasm::ast::Label;
use attasm::ast::Line;
use attasm::ast::Literal;
use attasm::ast::Program;
use attasm::ast::Register;

pub fn desugar_literals<'a, 'b>(asm: &'b mut Program<'a>) -> &'b mut Program<'a> {
    // change program lines inplace
    let len = asm.lines().len();
    let lines = std::mem::replace(asm.lines_mut(), Vec::with_capacity(len));
    let new = asm.lines_mut();

    // modify lines inplace to replace `mov $x, %r` with `inc %r` instructions
    for line in lines.into_iter() {
        match line {
            Line::OpLine(ins) => {
                match ins.mnemonic() {
                    "mov" | "add" => match ins.arguments().first() {
                        Some(Arg::Literal(_)) => {
                            let mut new_ins;
                            let (lit, reg) = args!(ins, mov(Arg::Literal, Arg::Register));
                            // clr(r)
                            if ins.mnemonic() == "mov" {
                                new_ins = Instruction::new("clr");
                                new_ins.add_argument(Arg::Register(reg.clone()));
                                new.push(Line::OpLine(new_ins));
                            }
                            // inc(r)
                            new_ins = Instruction::new("inc");
                            new_ins.add_argument(Arg::Register(reg.clone()));
                            match lit {
                                Literal::Dec(n) | Literal::Oct(n) | Literal::Hex(n) => {
                                    new.extend(repeat(new_ins.into()).take(*n));
                                }
                                _ => panic!("unsupported: {}", ins),
                            }
                        }
                        _ => new.push(ins.into()),
                    },
                    _ => new.push(ins.into()),
                };
            }
            _ => new.push(line),
        }
    }

    // return reference to program
    asm
}

pub fn impl_cpy<'a, 'b>(asm: &'b mut Program<'a>) -> &'b mut Program<'a> {
    let len = asm.lines().len();
    let lines = std::mem::replace(asm.lines_mut(), Vec::with_capacity(len));
    let new = asm.lines_mut();

    // counter for private labels
    let mut i = 0;

    for line in lines.into_iter() {
        match line {
            Line::OpLine(ref ins) if ins.mnemonic() == "cpy" => {
                let mut new_ins: Instruction;
                let mut new_label: Label;

                // extract arguments
                let (src, dst) = args!(ins, mov(Arg::Register, Arg::Register));
                let cpy = Register::new("_cpy");

                // Implement `cpy` using {clr, inc, dec, jnz}:
                // clr(%dst)
                new_ins = Instruction::new("clr");
                new_ins.add_argument(dst.clone());
                new.push(new_ins.into());
                // mov(%src, %_cpy)
                new_ins = Instruction::new("mov");
                new_ins.add_argument(src.clone());
                new_ins.add_argument(cpy.clone());
                new.push(new_ins.into());
                // _cpy_i:
                let labelname = format!("_cpy_{}", {
                    i += 1;
                    i
                });
                new_label = Label::new(labelname.clone());
                new.push(new_label.clone().into());
                // inc %src
                new_ins = Instruction::new("inc");
                new_ins.add_argument(src.clone());
                new.push(new_ins.into());
                // inc %dst
                new_ins = Instruction::new("inc");
                new_ins.add_argument(dst.clone());
                new.push(new_ins.into());
                // dec %_cpy
                new_ins = Instruction::new("dec");
                new_ins.add_argument(cpy.clone());
                new.push(new_ins.into());
                // jnz %_cpy,_cpy_{}
                new_ins = Instruction::new("jnz");
                new_ins.add_argument(cpy.clone());
                new_ins.add_argument(new_label.clone());
                new.push(new_ins.into())
            }
            _ => new.push(line),
        }
    }

    asm
}

pub fn impl_mul<'a, 'b>(asm: &'b mut Program<'a>) -> &'b mut Program<'a> {
    let len = asm.lines().len();
    let lines = std::mem::replace(asm.lines_mut(), Vec::with_capacity(len));
    let new = asm.lines_mut();

    // counter for private labels
    let mut i = 0;

    for line in lines.into_iter() {
        match line {
            Line::OpLine(ref ins) if ins.mnemonic() == "mul" => {
                let mut new_ins: Instruction;
                let mut new_label: Label;

                let label_loop = format!("_mov_{}_loop", {
                    i += 1;
                    i
                });
                let label_after = format!("_mov_{}_after", i);

                // extract arguments
                let (src, dst) = args!(ins, mul(Arg::Register, Arg::Register));
                let mul1 = Register::new("_mul1");
                let mul2 = Register::new("_mul2");

                // Implement `mul` using {add, dec, jnz}:
                // FIXME: distributed mov ?
                // mov(%dst, %_mul1)
                new_ins = Instruction::new("mov");
                new_ins.add_argument(dst.clone());
                new_ins.add_argument(mul1.clone());
                new.push(new_ins.into());
                // cpy(%_mul1, %_mul2)
                new_ins = Instruction::new("cpy");
                new_ins.add_argument(mul1.clone());
                new_ins.add_argument(mul2.clone());
                new.push(new_ins.into());
                // _mov_loop:
                new_label = Label::new(label_loop.clone());
                new.push(new_label.into());
                // jz %src, _mov_after
                new_ins = Instruction::new("jz");
                new_ins.add_argument(src.clone());
                new_ins.add_argument(Label::new(label_after.clone()));
                new.push(new_ins.into());
                // dec %src
                new_ins = Instruction::new("dec");
                new_ins.add_argument(src.clone());
                new.push(new_ins.into());
                // add %mul1, %dst
                new_ins = Instruction::new("add");
                new_ins.add_argument(mul1.clone());
                new_ins.add_argument(dst.clone());
                new.push(new_ins.into());
                // cpy %mul2, %mul1
                new_ins = Instruction::new("cpy");
                new_ins.add_argument(mul2.clone());
                new_ins.add_argument(mul1.clone());
                new.push(new_ins.into());
                // jmp _mov_loop
                new_ins = Instruction::new("jmp");
                new_ins.add_argument(Label::new(label_loop.clone()));
                new.push(new_ins.into());
                // _mov_after:
                new_label = Label::new(label_after.clone());
                new.push(new_label.into());
                // clr %mul1
                new_ins = Instruction::new("clr");
                new_ins.add_argument(mul1.clone());
                new.push(new_ins.into());
                // clr %mul2
                new_ins = Instruction::new("clr");
                new_ins.add_argument(mul2.clone());
                new.push(new_ins.into());
            }
            _ => new.push(line),
        }
    }

    asm
}

