#[test]
fn external_and_public_interleaving_works() {
	new_test_ext().execute_with(|| {
		System::set_block_number(0);
		let id = set_balance_proposal_hash_and_note(1);
		assert_ok!(Democracy::external_propose(Origin::signed(2), id.hash, id.asset_id,));
		assert_ok!(propose_set_balance_and_note(6, 2, 2));

		fast_forward_to(2);

		// both waiting: external goes first.
		assert_eq!(
			Democracy::referendum_status(0),
			Ok(ReferendumStatus {
				end: 4,
				proposal_id: set_balance_proposal_hash_and_note(1),
				threshold: VoteThreshold::SuperMajorityApprove,
				delay: 2,
				tally: Tally { ayes: 0, nays: 0, turnout: 0 },
			})
		);
		// replenish external
		let id = set_balance_proposal_hash_and_note(3);
		assert_ok!(Democracy::external_propose(Origin::signed(2), id.hash, id.asset_id,));

		fast_forward_to(4);

		// both waiting: public goes next.
		assert_eq!(
			Democracy::referendum_status(1),
			Ok(ReferendumStatus {
				end: 6,
				proposal_id: set_balance_proposal_hash_and_note(2),
				threshold: VoteThreshold::SuperMajorityApprove,
				delay: 2,
				tally: Tally { ayes: 0, nays: 0, turnout: 0 },
			})
		);
		// don't replenish public

		fast_forward_to(6);

		// it's external "turn" again, though since public is empty that doesn't really matter
		assert_eq!(
			Democracy::referendum_status(2),
			Ok(ReferendumStatus {
				end: 8,
				proposal_id: set_balance_proposal_hash_and_note(3),
				threshold: VoteThreshold::SuperMajorityApprove,
				delay: 2,
				tally: Tally { ayes: 0, nays: 0, turnout: 0 },
			})
		);
		// replenish external
		let id = set_balance_proposal_hash_and_note(5);
		assert_ok!(Democracy::external_propose(Origin::signed(2), id.hash, id.asset_id,));

		fast_forward_to(8);

		// external goes again because there's no public waiting.
		assert_eq!(
			Democracy::referendum_status(3),
			Ok(ReferendumStatus {
				end: 10,
				proposal_id: set_balance_proposal_hash_and_note(5),
				threshold: VoteThreshold::SuperMajorityApprove,
				delay: 2,
				tally: Tally { ayes: 0, nays: 0, turnout: 0 },
			})
		);
		// replenish both
		let id = set_balance_proposal_hash_and_note(7);
		assert_ok!(Democracy::external_propose(Origin::signed(2), id.hash, id.asset_id,));
		assert_ok!(propose_set_balance_and_note(6, 4, 2));

		fast_forward_to(10);

		// public goes now since external went last time.
		assert_eq!(
			Democracy::referendum_status(4),
			Ok(ReferendumStatus {
				end: 12,
				proposal_id: set_balance_proposal_hash_and_note(4),
				threshold: VoteThreshold::SuperMajorityApprove,
				delay: 2,
				tally: Tally { ayes: 0, nays: 0, turnout: 0 },
			})
		);
		// replenish public again
		assert_ok!(propose_set_balance_and_note(6, 6, 2));
		// cancel external
		let h = set_balance_proposal_hash_and_note(7);
		assert_ok!(Democracy::veto_external(Origin::signed(3), h.hash, h.asset_id));

		fast_forward_to(12);

		// public goes again now since there's no external waiting.
		assert_eq!(
			Democracy::referendum_status(5),
			Ok(ReferendumStatus {
				end: 14,
				proposal_id: set_balance_proposal_hash_and_note(6),
				threshold: VoteThreshold::SuperMajorityApprove,
				delay: 2,
				tally: Tally { ayes: 0, nays: 0, turnout: 0 },
			})
		);
	});
}

use std::collections::VecDeque;

use anyhow::Error;

use crate::{
	events::Event,
	module::{ExitStatus, State},
	process::artifact::Artifact,
};

#[derive(Debug)]
pub(crate) struct Results {
	pub(crate) artifacts: VecDeque<Artifact>,
}

impl Results {
	pub(crate) fn new() -> Self {
		Self {
			artifacts: VecDeque::new(),
		}
	}

	pub(crate) fn event(&mut self, event: Event) {
		self.artifacts.push_back(Artifact::Event(event));
	}

	pub(crate) fn error(&mut self, error: Error) {
		self.artifacts.push_back(Artifact::Error(error, None));
	}

	pub(crate) fn error_with_return(&mut self, error: Error, state: State) {
		self.artifacts.push_back(Artifact::Error(error, Some(state)));
	}

	pub(crate) fn exit_status(&mut self, status: ExitStatus) {
		self.artifacts.push_back(Artifact::ExitStatus(status));
	}

	pub(crate) fn state(&mut self, new_state: State) {
		self.artifacts.push_back(Artifact::ChangeState(new_state));
	}

	pub(crate) fn external_command(&mut self, command: String, arguments: Vec<String>) {
		self.artifacts
			.push_back(Artifact::ExternalCommand((command, arguments)));
	}

	pub(crate) fn enqueue_resize(&mut self) {
		self.artifacts.push_back(Artifact::EnqueueResize);
	}

	pub(crate) fn append(&mut self, other: Self) {
		self.artifacts.extend(other.artifacts);
	}

	pub(crate) fn artifact(&mut self) -> Option<Artifact> {
		self.artifacts.pop_front()
	}
}

impl From<Event> for Results {
	fn from(event: Event) -> Self {
		Self {
			artifacts: VecDeque::from(vec![Artifact::Event(event)]),
		}
	}
}

impl From<Error> for Results {
	fn from(error: Error) -> Self {
		Self {
			artifacts: VecDeque::from(vec![Artifact::Error(error, None)]),
		}
	}
}

impl From<ExitStatus> for Results {
	fn from(status: ExitStatus) -> Self {
		Self {
			artifacts: VecDeque::from(vec![Artifact::ExitStatus(status)]),
		}
	}
}

impl From<State> for Results {
	fn from(state: State) -> Self {
		Self {
			artifacts: VecDeque::from(vec![Artifact::ChangeState(state)]),
		}
	}
}

#[cfg(test)]
mod tests {
	use anyhow::anyhow;

	use super::*;

	#[test]
	fn empty() {
		let mut results = Results::new();
		assert!(results.artifact().is_none());
	}

	#[test]
	fn event() {
		let mut results = Results::from(Event::from('a'));
		assert!(matches!(results.artifact(), Some(Artifact::Event(_))));
	}

	#[test]
	fn error() {
		let mut results = Results::new();
		results.error(anyhow!("Test Error"));
		assert!(matches!(results.artifact(), Some(Artifact::Error(_, None))));
	}

	#[test]
	fn error_from() {
		let mut results = Results::from(anyhow!("Test Error"));
		assert!(matches!(results.artifact(), Some(Artifact::Error(_, None))));
	}

	#[test]
	fn error_with_return() {
		let mut results = Results::new();
		results.error_with_return(anyhow!("Test Error"), State::List);
		assert!(matches!(
			results.artifact(),
			Some(Artifact::Error(_, Some(State::List)))
		));
	}

	#[test]
	fn exit_status() {
		let mut results = Results::from(ExitStatus::Good);
		assert!(matches!(
			results.artifact(),
			Some(Artifact::ExitStatus(ExitStatus::Good))
		));
	}

	#[test]
	fn state() {
		let mut results = Results::from(State::List);
		assert!(matches!(results.artifact(), Some(Artifact::ChangeState(State::List))));
	}

	#[test]
	fn external_command() {
		let mut results = Results::new();
		results.external_command(String::from("editor"), vec![String::from("arg1"), String::from("arg2")]);
		assert!(matches!(results.artifact(), Some(Artifact::ExternalCommand(_))));
	}

	#[test]
	fn enqueue_resize() {
		let mut results = Results::new();
		results.enqueue_resize();
		assert!(matches!(results.artifact(), Some(Artifact::EnqueueResize)));
	}

	#[test]
	fn append() {
		let mut results_1 = Results::new();
		results_1.enqueue_resize();
		let mut results_2 = Results::new();
		results_2.state(State::List);
		results_1.append(results_2);
		assert!(matches!(results_1.artifact(), Some(Artifact::EnqueueResize)));
		assert!(matches!(results_1.artifact(), Some(Artifact::ChangeState(State::List))));
	}
}

use nalgebra::Vector3;
use std::collections::HashMap;
use std::hash::BuildHasherDefault;
use std::sync::RwLock;
use twox_hash::XxHash64;

pub trait GetCoords {
    fn x(&self) -> f64;
    fn y(&self) -> f64;
    fn z(&self) -> f64;
}

pub trait IntoVoxelKey {
    fn to_key(&self, voxel_size: f64) -> (i64, i64, i64);
}

#[derive(Copy, Clone)]
pub struct Translation {
    pub x: f64,
    pub y: f64,
    pub z: f64,
}

pub trait TranslatePoint {
    fn translate(&mut self, translation: &Translation);
    fn translate_rev(&mut self, translation: &Translation);
}

pub trait TrimDecimals {
    fn trim_decimals(&mut self, n: i32);
}

pub trait PushPoint {
    fn push_point(&mut self, point: Point);
}

pub trait IntoVoxel<V> {
    fn to_voxel(self, voxel_size: f64) -> V;
}

pub struct Voxel {
    pub x: i64,
    pub y: i64,
    pub z: i64,
    pub irradiation: RwLock<Irradiation>,
    pub normal_vector: NormalVector,
    pub points: Vec<Point>,
}

impl PushPoint for Voxel {
    fn push_point(&mut self, point: Point) {
        self.points.push(point);
    }
}

#[derive(Copy, Clone, Debug)]
pub struct Point {
    pub x: f64,
    pub y: f64,
    pub z: f64,
    pub overlap: bool,
}

impl Point {
    pub fn as_na_vec(&self) -> Vector3<f64> {
        Vector3::from([self.x, self.y, self.z])
    }
}

impl IntoVoxel<Voxel> for Point {
    fn to_voxel(self, voxel_size: f64) -> Voxel {
        let key = self.to_key(voxel_size);
        Voxel {
            x: key.0,
            y: key.1,
            z: key.2,
            irradiation: RwLock::new(Irradiation {
                global_irradiance: 0.,
                beam_component: 0.,
                diffuse_component: 0.,
                illumination_count: 0,
            }),
            normal_vector: NormalVector {
                x: 0.,
                y: 0.,
                z: 0.,
            },
            points: vec![self],
        }
    }
}

impl GetCoords for Point {
    fn x(&self) -> f64 {
        self.x
    }
    fn y(&self) -> f64 {
        self.y
    }
    fn z(&self) -> f64 {
        self.z
    }
}

impl TranslatePoint for Point {
    fn translate(&mut self, translation: &Translation) {
        self.x -= translation.x;
        self.y -= translation.y;
        self.z -= translation.z;
    }

    fn translate_rev(&mut self, translation: &Translation) {
        self.x += translation.x;
        self.y += translation.y;
        self.z += translation.z;
    }
}

impl TrimDecimals for Point {
    fn trim_decimals(&mut self, n: i32) {
        let coef = 10f64.powi(n);
        self.x = (self.x * coef).round() / coef;
        self.y = (self.y * coef).round() / coef;
        self.z = (self.z * coef).round() / coef;
    }
}

impl IntoVoxelKey for Point {
    fn to_key(&self, voxel_size: f64) -> (i64, i64, i64) {
        (
            (self.x / voxel_size).round() as i64,
            (self.y / voxel_size).round() as i64,
            (self.z / voxel_size).round() as i64,
        )
    }
}

#[derive(Copy, Clone, Debug)]
pub struct NormalVector {
    pub x: f64,
    pub y: f64,
    pub z: f64,
}

impl NormalVector {
    pub fn _new() -> NormalVector {
        NormalVector {
            x: 0.,
            y: 0.,
            z: 0.,
        }
    }
    pub fn upright() -> NormalVector {
        NormalVector {
            x: 0.,
            y: 0.,
            z: 1.,
        }
    }
    pub fn as_na_vec(&self) -> Vector3<f64> {
        Vector3::from([self.x, self.y, self.z])
    }
    pub fn from_na_vec(na_vec: &Vector3<f64>) -> Self {
        if na_vec[2] < 0. {
            NormalVector {
                x: -na_vec[0],
                y: -na_vec[1],
                z: -na_vec[2],
            }
        } else {
            NormalVector {
                x: na_vec[0],
                y: na_vec[1],
                z: na_vec[2],
            }
        }
    }
    pub fn angle(&self, vec: &Vector3<f64>) -> f64 {
        self.as_na_vec().angle(vec)
    }
}

#[derive(Copy, Clone, Debug)]
pub struct Irradiation {
    pub global_irradiance: f64,
    pub beam_component: f64,
    pub diffuse_component: f64,
    pub illumination_count: i64,
}

pub type VoxelGrid<V> = HashMap<(i64, i64, i64), V, BuildHasherDefault<XxHash64>>;

#[derive(Debug, Copy, Clone)]
pub struct Key {
    pub x: i64,
    pub y: i64,
    pub z: i64,
}

impl Key {
    pub fn as_tuple(&self) -> (i64, i64, i64) {
        (self.x, self.y, self.z)
    }
}

