mod util;

#[derive(PartialEq, Eq)]
enum Direction {
    Up,
    Down,
    Left,
    Right,
}

#[derive(Debug)]
enum Instruction {
    Vert,
    Horiz,
    Junction,
    Space,
    Letter(char),
}

fn main() -> () {
    let instructions = get_input();
    let (mut row, mut col) = get_starting_point(&instructions);
    let mut dir = Direction::Down;
    let mut letters = Vec::new();
    let mut cont = true;
    let mut num_steps = 0;

    loop {
        if !cont {
            break;
        }
        let this_inst = &instructions[row as usize][col as usize];
        match this_inst {
            Instruction::Vert => {
                let (new_row, new_col) = proceed((row, col), &dir);
                row = new_row;
                col = new_col;
            }
            Instruction::Horiz => {
                let (new_row, new_col) = proceed((row, col), &dir);
                row = new_row;
                col = new_col;
            }
            Instruction::Letter(c) => {
                letters.push(*c);
                let (new_row, new_col) = proceed((row, col), &dir);
                row = new_row;
                col = new_col;
            }
            Instruction::Space => {
                cont = false;
            }
            Instruction::Junction => {
                let (new_dir, new_row, new_col) = compute_junction(&instructions, row, col, &dir);
                dir = new_dir;
                row = new_row;
                col = new_col;
            }
        }
        num_steps += 1;
    }
    println!("num_steps is: {}", num_steps - 1);
}

fn proceed((row, col): (i32, i32), dir: &Direction) -> (i32, i32) {
    match dir {
        Direction::Down => (row + 1, col),
        Direction::Up => (row - 1, col),
        Direction::Left => (row, col - 1),
        Direction::Right => (row, col + 1),
    }
}

fn get_resultant_direction((old_r, old_c): (i32, i32), (new_r, new_c): (i32, i32)) -> Direction {
    if old_r > new_r {
        Direction::Up
    } else if old_r < new_r {
        Direction::Down
    } else {
        if old_c < new_c {
            Direction::Right
        } else if old_c > new_c {
            Direction::Left
        } else {
            panic!("old and new are the same!");
        }
    }
}

fn compute_junction(
    instructions: &Vec<Vec<Instruction>>,
    row: i32,
    col: i32,
    cur_dir: &Direction,
) -> (Direction, i32, i32) {
    let checks = match cur_dir {
        Direction::Down => vec![(row, col - 1), (row + 1, col), (row, col + 1)],
        Direction::Up => vec![(row, col + 1), (row - 1, col), (row, col - 1)],
        Direction::Left => vec![(row - 1, col), (row, col - 1), (row + 1, col)],
        Direction::Right => vec![(row - 1, col), (row, col + 1), (row + 1, col)],
    };

    let mut valid_checks = Vec::new();
    for (r, c) in checks {
        if r >= 0 && r < instructions.len() as i32 {
            if c >= 0 && c < instructions[r as usize].len() as i32 {
                valid_checks.push((r, c));
            }
        }
    }

    for (r, c) in valid_checks {
        match &instructions[r as usize][c as usize] {
            Instruction::Space => {}
            _ => {
                let new_dir = get_resultant_direction((row, col), (r, c));
                return (new_dir, r, c);
            }
        }
    }
    panic!("Multiple choices possible at row: {}, col: {}", row, col);
}

fn get_input() -> Vec<Vec<Instruction>> {
    let mut instructions = Vec::new();
    let lines = util::read_file_lines("input.txt");
    for line in lines {
        let mut row = Vec::new();
        for ch in line.chars() {
            match ch {
                '|' => row.push(Instruction::Vert),
                '-' => row.push(Instruction::Horiz),
                '+' => row.push(Instruction::Junction),
                ' ' => row.push(Instruction::Space),
                _ => row.push(Instruction::Letter(ch)),
            }
        }
        instructions.push(row);
    }

    instructions
}

fn get_starting_point(instructions: &Vec<Vec<Instruction>>) -> (i32, i32) {
    let mut i = 0;
    for ch in &instructions[0] {
        match ch {
            Instruction::Space => {}
            _ => return (0, i),
        }
        i += 1;
    }
    panic!("no stating point found")
}

use crate::event::issue::Issue;
use crate::github::GitHub;
use neovim_lib::{Neovim, NeovimApi, Session};

mod issue;

enum Messages {
    // issue
    ListIssue,
    // pulls
    CreatePullRequest,
    Unknown(String),
}

impl From<String> for Messages {
    fn from(event: String) -> Self {
        match &event[..] {
            "list_issue" => Messages::ListIssue,
            "create_pull_request" => Messages::CreatePullRequest,
            _ => Messages::Unknown(event),
        }
    }
}

pub struct EventHandler {
    nvim: Neovim,
    client: GitHub,
}

impl issue::Issue for EventHandler {}
impl EventHandler {
    pub fn new() -> EventHandler {
        let session = Session::new_parent().unwrap();
        let nvim = Neovim::new(session);
        let token = std::env::var("GHANA_GITHUB_TOKEN")
            .expect("GHANA_GITHUB_TOKEN env variable is required.");
        let client = GitHub::new(token);

        EventHandler { nvim, client }
    }

    pub fn recv(&mut self) {
        let receiver = self.nvim.session.start_event_loop_channel();

        for (event, values) in receiver {
            match Messages::from(event) {
                // issue
                Messages::ListIssue => {
                    self.list_issue();
                    self.nvim
                        .command(&format!("call ghana#rpc#hoge({:?})", values))
                        .unwrap();
                }

                // pulls
                Messages::CreatePullRequest => {
                    // call github.create_pull_request
                    self.nvim
                        .command(&format!("echo \"call pull request: {:?}\"", values))
                        .unwrap();
                }
                Messages::Unknown(event) => {
                    self.nvim
                        .command(&format!("echo \"Unknown command: {}\"", event))
                        .unwrap();
                }
            }
        }
    }
}

use flate2::bufread::ZlibDecoder;
use std::io::prelude::*;
use std;

use crate::pack::internal_type::PackfileType;
use crate::delta::{ OFS_DELTA, REF_DELTA };
use crate::errors::{ Result, ErrorKind };
use crate::id::Id;

pub fn packfile_read<R: BufRead, W: Write>(
    input: &mut R,
    output: &mut W,
    read_bytes: &mut u64
) -> Result<PackfileType> {
    let mut byte = [0u8; 1];
    input.read_exact(&mut byte)?;

    let obj_type = (byte[0] & 0x70) >> 4;
    let mut size = (byte[0] & 0xf) as u64;
    let mut count = 0;
    let mut continuation = byte[0] & 0x80;
    loop {
        if continuation < 1 {
            break
        }

        input.read_exact(&mut byte)?;
        continuation = byte[0] & 0x80;

        size |= ((byte[0] & 0x7f) as u64) << (4 + 7 * count);
        count += 1;
    }

    match obj_type {
        0...4 => {
            let mut deflate_stream = ZlibDecoder::new(input);
            std::io::copy(&mut deflate_stream, output)?;
            *read_bytes = 1 + count + deflate_stream.total_in();
            return Ok(PackfileType::Plain(obj_type));
        },

        OFS_DELTA => {
            input.read_exact(&mut byte)?;
            let mut offset = u64::from(byte[0] & 0x7F);

            while byte[0] & 0x80 > 0 {
                offset += 1;
                offset <<= 7;
                input.read_exact(&mut byte)?;
                offset += u64::from(byte[0] & 0x7F);
                count += 1;
            }

            let mut deflate_stream = ZlibDecoder::new(input);
            let mut instructions = Vec::new();
            deflate_stream.read_to_end(&mut instructions)?;

            *read_bytes = 2 + count + deflate_stream.total_in();
            return Ok(PackfileType::OffsetDelta((offset, instructions)))
        },

        REF_DELTA => {
            let mut ref_bytes = [0u8; 20];
            input.read_exact(&mut ref_bytes)?;
            let id = Id::from(&ref_bytes);

            let mut deflate_stream = ZlibDecoder::new(input);
            let mut instructions = Vec::new();
            deflate_stream.read_to_end(&mut instructions)?;
            *read_bytes = 21 + count + deflate_stream.total_in();
            return Ok(PackfileType::RefDelta((id, instructions)))
        },

        _ => {
            Err(ErrorKind::BadLooseObject.into())
        }
    }
}

//! Example: Calculator
//! -------------------
//!
//! Some components benefit through the use of "Models". Models are a single block of encapsulated state that allow mutative
//! methods to be performed on them. Dioxus exposes the ability to use the model pattern through the "use_model" hook.
//!
//! Models are commonly used in the "Model-View-Component" approach for building UI state.
//!
//! `use_model` is basically just a fancy wrapper around set_state, but saves a "working copy" of the new state behind a
//! RefCell. To modify the working copy, you need to call "get_mut" which returns the RefMut. This makes it easy to write
//! fully encapsulated apps that retain a certain feel of native Rusty-ness. A calculator app is a good example of when this
//! is useful.
//!
//! Do note that "get_mut" returns a `RefMut` (a lock over a RefCell). If two `RefMut`s are held at the same time (ie in a loop)
//! the RefCell will panic and crash. You can use `try_get_mut` or `.modify` to avoid this problem, or just not hold two
//! RefMuts at the same time.

use std::sync::Arc;

