use {
	super::{auto_increment, columns_to_positions, validate, validate_unique},
	crate::{
		data::{get_name, Schema},
		executor::query::query,
		Context, ExecuteError, Payload, Result, Row, StorageInner,
	},
	sqlparser::ast::{Ident, ObjectName, Query},
};

pub async fn insert(
	storages: &mut Vec<(String, &mut StorageInner)>,
	context: &mut Context,
	table_name: &ObjectName,
	columns: &Vec<Ident>,
	source: &Box<Query>,
	expect_data: bool,
) -> Result<Payload> {
	let table_name = get_name(table_name)?;
	let Schema { column_defs, .. } = storages[0]
		.1
		.fetch_schema(table_name)
		.await?
		.ok_or(ExecuteError::TableNotExists)?;

	// TODO: Multi storage
	let (labels, rows) = query(storages, context, *source.clone()).await?;
	let column_positions = columns_to_positions(&column_defs, columns)?;

	let rows = validate(&column_defs, &column_positions, rows)?;
	#[cfg(feature = "auto-increment")]
	let rows = auto_increment(storages[0].1, table_name, &column_defs, rows).await?;
	validate_unique(storages[0].1, table_name, &column_defs, &rows, None).await?;
	let rows: Vec<Row> = rows.into_iter().map(Row).collect();

	let num_rows = rows.len();

	let result = storages[0].1.insert_data(table_name, rows.clone()).await;

	result.map(|_| {
		if expect_data {
			Payload::Select { labels, rows }
		} else {
			Payload::Insert(num_rows)
		}
	})
}

use intcode::Intcode;
use std::fmt;
use std::io;
use std::io::Read;

type Error = Box<dyn std::error::Error>;
type Result<T> = std::result::Result<T, Error>;

fn main() -> Result<()> {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input)?;

    let state: Vec<_> = input
        .split(',')
        .map(|line| line.trim().parse::<i64>().unwrap())
        .collect();

    let mut grid = Grid::new();
    day15a(&state, &mut grid);
    day15b(&mut grid);
    Ok(())
}

const DROID_X: usize = 25;
const DROID_Y: usize = 25;

fn day15a(state: &Vec<i64>, grid: &mut Grid) {
    let mut stack = Vec::new();

    *grid.at_mut(DROID_X, DROID_Y) = TileType::Empty;
    grid.set_distance(DROID_X, DROID_Y, 0);
    stack.push(Continuation {
        pgm: Intcode::new(state),
        x: DROID_X,
        y: DROID_Y,
    });

    while let Some(c) = stack.pop() {
        let distance = grid.get_distance(c.x, c.y) + 1;
        run_continuation(&c.pgm, c.x, c.y - 1, 1, distance, grid, &mut stack);
        run_continuation(&c.pgm, c.x, c.y + 1, 2, distance, grid, &mut stack);
        run_continuation(&c.pgm, c.x - 1, c.y, 3, distance, grid, &mut stack);
        run_continuation(&c.pgm, c.x + 1, c.y, 4, distance, grid, &mut stack);
    }
    println!("{}", grid);
    let oxygen_pos = grid.get_oxygen_position();
    println!(
        "day15a: distance from oxygen system: {}",
        grid.get_distance(oxygen_pos.0, oxygen_pos.1)
    );
}

fn run_continuation(
    pgm: &Intcode,
    x: usize,
    y: usize,
    input: i64,
    distance: u32,
    grid: &mut Grid,
    conts: &mut Vec<Continuation>,
) {
    match grid.at(x, y) {
        TileType::Wall | TileType::OxygenSystem => return,
        TileType::Empty => {
            if grid.get_distance(x, y) <= distance {
                return;
            }
        }
        TileType::Unknown => (),
    }

    let mut pgm = pgm.clone();
    let output = pgm.run(&[input]);

    *grid.at_mut(x, y) = match output[0] {
        0 => TileType::Wall,
        1 => TileType::Empty,
        2 => TileType::OxygenSystem,
        _ => panic!("unknown output {}", output[0]),
    };
    grid.set_distance(x, y, distance);
    if output[0] == 1 {
        conts.push(Continuation { pgm, x, y })
    }
    if output[0] == 2 {
        grid.set_oxygen_position(x, y);
    }
}

struct Continuation {
    pgm: Intcode,
    x: usize,
    y: usize,
}

fn day15b(grid: &mut Grid) {
    for x in 0..grid.w {
        for y in 0..grid.h {
            grid.set_distance(x, y, std::u32::MAX);
        }
    }

    let mut stack = Vec::new();
    let mut distance = 0;
    let oxygen_pos = grid.get_oxygen_position();
    stack.push((oxygen_pos.0, oxygen_pos.1));
    while stack.len() > 0 {
        let mut new_stack = Vec::new();

        while let Some((x, y)) = stack.pop() {
            grid.set_distance(x, y, distance);
            add_empty_tile(x, y - 1, distance + 1, grid, &mut new_stack);
            add_empty_tile(x, y + 1, distance + 1, grid, &mut new_stack);
            add_empty_tile(x - 1, y, distance + 1, grid, &mut new_stack);
            add_empty_tile(x + 1, y, distance + 1, grid, &mut new_stack);
        }
        std::mem::swap(&mut stack, &mut new_stack);
        distance += 1;
    }

    println!("day15b: distance max from oxygen system: {}", distance - 1);
}

fn add_empty_tile(
    x: usize,
    y: usize,
    distance: u32,
    grid: &mut Grid,
    stack: &mut Vec<(usize, usize)>,
) {
    if grid.get_distance(x, y) <= distance {
        return;
    }

    match grid.at(x, y) {
        TileType::Empty => stack.push((x, y)),
        _ => (),
    }
}

#[derive(Clone)]
enum TileType {
    Unknown,
    Empty,
    Wall,
    OxygenSystem,
}

struct Grid {
    map: Vec<TileType>,
    distance: Vec<u32>,
    w: usize,
    h: usize,
    oxygen_x: usize,
    oxygen_y: usize,
}

impl Grid {
    fn new() -> Self {
        let w = 50;
        let h = 50;
        Grid {
            map: vec![TileType::Unknown; w * h],
            distance: vec![std::u32::MAX; w * h],
            w,
            h,
            oxygen_x: 0,
            oxygen_y: 0,
        }
    }

    fn at(&self, x: usize, y: usize) -> &TileType {
        &self.map[y * self.w + x]
    }

    fn at_mut(&mut self, x: usize, y: usize) -> &mut TileType {
        &mut self.map[y * self.w + x]
    }

    fn get_distance(&self, x: usize, y: usize) -> u32 {
        self.distance[y * self.w + x]
    }

    fn set_distance(&mut self, x: usize, y: usize, distance: u32) {
        self.distance[y * self.w + x] = distance;
    }

    fn get_oxygen_position(&mut self) -> (usize, usize) {
        (self.oxygen_x, self.oxygen_y)
    }

    fn set_oxygen_position(&mut self, x: usize, y: usize) {
        self.oxygen_x = x;
        self.oxygen_y = y;
    }
}

impl fmt::Display for Grid {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        for y in 0..self.h {
            for x in 0..self.w {
                if x == DROID_X && y == DROID_Y {
                    write!(f, "D")?;
                } else {
                    write!(
                        f,
                        "{}",
                        match *self.at(x, y) {
                            TileType::Unknown => ' ',
                            TileType::Empty => '.',
                            TileType::Wall => '#',
                            TileType::OxygenSystem => 'O',
                        }
                    )?;
                }
            }
            writeln!(f, "")?;
        }
        Ok(())
    }
}

//! A BGZF writer implementation.
use std::{
    fs::File,
    io::{self, Write},
    path::Path,
};

use bytes::BytesMut;

use crate::{
    CompressionLevel, Compressor, BGZF_BLOCK_SIZE, BGZF_EOF, BUFSIZE, MAX_BGZF_BLOCK_SIZE,
};

/// A BGZF writer.
///
/// # Example
///
/// ```rust
/// use bgzf::{CompressionLevel, Writer};
/// use std::error::Error;
/// use std::io::Write;
///
/// fn main() -> Result<(), Box<dyn Error>> {
///     // Write compressed data
///     let mut destination = vec![];
///     let mut writer = Writer::new(&mut destination, 2.try_into()?);
///     let input = &[b'A'; 100];
///     writer.write_all(input)?;
///     writer.flush()?;
///     drop(writer);
///
///     assert!(destination.len() < input.len());
///     Ok(())
/// }
/// ```
pub struct Writer<W>
where
    W: Write,
{
    /// The internal buffer to use
    uncompressed_buffer: BytesMut,
    /// The buffer to reuse for compressed bytes
    compressed_buffer: Vec<u8>,
    /// The size of the blocks to create
    blocksize: usize,
    /// The compressor to reuse
    compressor: Compressor,
    /// The inner writer
    writer: W,
}

impl<W> Writer<W>
where
    W: Write,
{
    /// Create a new [`Writer`]
    pub fn new(writer: W, compression_level: CompressionLevel) -> Self {
        Self::with_capacity(writer, compression_level, BGZF_BLOCK_SIZE)
    }

    /// Create a writer with a set capacity.
    ///
    /// By default the capacity is [`bgzf::BUFSIZE`]. The capacity bust be less than [`bgzf::BGZF_BLOCK_SIZE`].
    pub fn with_capacity(writer: W, compression_level: CompressionLevel, blocksize: usize) -> Self {
        assert!(blocksize <= BGZF_BLOCK_SIZE);
        let compressor = Compressor::new(compression_level);
        Self {
            uncompressed_buffer: BytesMut::with_capacity(BUFSIZE),
            compressed_buffer: Vec::with_capacity(BUFSIZE),
            blocksize,
            compressor,
            writer,
        }
    }
}

impl Writer<File> {
    /// Create a BGZF writer from a [`Path`].
    pub fn from_path<P>(path: P, compression_level: CompressionLevel) -> io::Result<Self>
    where
        P: AsRef<Path>,
    {
        // TODO: benchmark whether there is any benefit to using a BufWriter
        File::create(path).map(|f| Self::new(f, compression_level))
    }
}

impl<W> Write for Writer<W>
where
    W: Write,
{
    /// Write a buffer into this writer, returning how many bytes were written.
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        self.uncompressed_buffer.extend_from_slice(buf);
        while self.uncompressed_buffer.len() >= self.blocksize {
            let b = self.uncompressed_buffer.split_to(self.blocksize).freeze();
            self.compressor
                .compress(&b[..], &mut self.compressed_buffer)
                .map_err(|e| io::Error::new(io::ErrorKind::Other, e))?;
            self.writer.write_all(&self.compressed_buffer)?;
            self.compressed_buffer.clear();
        }
        Ok(buf.len())
    }

    /// Flush this output stream, ensuring all intermediately buffered contents are sent.
    fn flush(&mut self) -> std::io::Result<()> {
        while !self.uncompressed_buffer.is_empty() {
            let b = self
                .uncompressed_buffer
                .split_to(std::cmp::min(self.uncompressed_buffer.len(), MAX_BGZF_BLOCK_SIZE))
                .freeze();
            self.compressor
                .compress(&b[..], &mut self.compressed_buffer)
                .map_err(|e| io::Error::new(io::ErrorKind::Other, e))?;
            self.writer.write_all(&self.compressed_buffer)?;
            self.compressed_buffer.clear();
            self.writer.write_all(BGZF_EOF)?; // this is an empty block
        }
        self.writer.flush()
    }
}

impl<W> Drop for Writer<W>
where
    W: Write,
{
    fn drop(&mut self) {
        self.flush().unwrap();
    }
}

