use crate::schedule::EncryptionSecret;

// This tests the boundaries of the generations from a SecretTree
#[test]
fn test_boundaries() {
    use crate::config::*;
    use crate::tree::{index::*, secret_tree::*};

    for ciphersuite in Config::supported_ciphersuites() {
        let encryption_secret = EncryptionSecret::from_random(32);
        let mut secret_tree = SecretTree::new(encryption_secret, LeafIndex::from(2u32));
        let secret_type = SecretType::ApplicationSecret;
        assert!(secret_tree
            .secret_for_decryption(&ciphersuite, LeafIndex::from(0u32), secret_type, 0)
            .is_ok());
        assert!(secret_tree
            .secret_for_decryption(&ciphersuite, LeafIndex::from(1u32), secret_type, 0)
            .is_ok());
        assert!(secret_tree
            .secret_for_decryption(&ciphersuite, LeafIndex::from(0u32), secret_type, 1)
            .is_ok());
        assert!(secret_tree
            .secret_for_decryption(&ciphersuite, LeafIndex::from(0u32), secret_type, 1_000)
            .is_ok());
        assert_eq!(
            secret_tree.secret_for_decryption(
                &ciphersuite,
                LeafIndex::from(1u32),
                secret_type,
                1001
            ),
            Err(SecretTreeError::TooDistantInTheFuture)
        );
        assert!(secret_tree
            .secret_for_decryption(&ciphersuite, LeafIndex::from(0u32), secret_type, 996)
            .is_ok());
        assert_eq!(
            secret_tree.secret_for_decryption(
                &ciphersuite,
                LeafIndex::from(0u32),
                secret_type,
                995
            ),
            Err(SecretTreeError::TooDistantInThePast)
        );
        assert_eq!(
            secret_tree.secret_for_decryption(&ciphersuite, LeafIndex::from(2u32), secret_type, 0),
            Err(SecretTreeError::IndexOutOfBounds)
        );
        let encryption_secret = EncryptionSecret::from_random(32);
        let mut largetree = SecretTree::new(encryption_secret, LeafIndex::from(100_000u32));
        assert!(largetree
            .secret_for_decryption(&ciphersuite, LeafIndex::from(0u32), secret_type, 0)
            .is_ok());
        assert!(largetree
            .secret_for_decryption(&ciphersuite, LeafIndex::from(99_999u32), secret_type, 0)
            .is_ok());
        assert!(largetree
            .secret_for_decryption(&ciphersuite, LeafIndex::from(99_999u32), secret_type, 1_000)
            .is_ok());
        assert_eq!(
            largetree.secret_for_decryption(
                &ciphersuite,
                LeafIndex::from(100_000u32),
                secret_type,
                0
            ),
            Err(SecretTreeError::IndexOutOfBounds)
        );
    }
}

// This tests if the generation gets incremented correctly and that the returned
// values are unique.
#[test]
fn increment_generation() {
    use crate::config::Config;
    use crate::tree::{secret_tree::*, *};
    use std::collections::HashMap;

    const SIZE: usize = 100;
    const MAX_GENERATIONS: usize = 10;

    for ciphersuite in Config::supported_ciphersuites() {
        let mut unique_values: HashMap<Vec<u8>, bool> = HashMap::new();
        let encryption_secret = EncryptionSecret::from_random(32);
        let mut secret_tree = SecretTree::new(encryption_secret, LeafIndex::from(SIZE as u32));
        for i in 0..SIZE {
            assert_eq!(
                secret_tree.generation(LeafIndex::from(i as u32), SecretType::HandshakeSecret),
                0
            );
            assert_eq!(
                secret_tree.generation(LeafIndex::from(i as u32), SecretType::ApplicationSecret),
                0
            );
        }
        for i in 0..MAX_GENERATIONS {
            for j in 0..SIZE {
                let (next_gen, (handshake_key, handshake_nonce)) = secret_tree
                    .secret_for_encryption(
                        ciphersuite,
                        LeafIndex::from(j as u32),
                        SecretType::HandshakeSecret,
                    )
                    .expect("Index out of bounds.");
                assert_eq!(next_gen, i as u32);
                assert!(unique_values
                    .insert(handshake_key.as_slice().to_vec(), true)
                    .is_none());
                assert!(unique_values
                    .insert(handshake_nonce.as_slice().to_vec(), true)
                    .is_none());
                let (next_gen, (application_key, application_nonce)) = secret_tree
                    .secret_for_encryption(
                        ciphersuite,
                        LeafIndex::from(j as u32),
                        SecretType::ApplicationSecret,
                    )
                    .expect("Index out of bounds.");
                assert_eq!(next_gen, i as u32);
                assert!(unique_values
                    .insert(application_key.as_slice().to_vec(), true)
                    .is_none());
                assert!(unique_values
                    .insert(application_nonce.as_slice().to_vec(), true)
                    .is_none());
            }
        }
    }
}

use domain::RegistryUsers;
use domain::UsersManager;
use serde::{Deserialize, Serialize};
use validator::Validate;

use crate::errors::RegistryError;
use crate::response::ErrorResponse;
use crate::AppState;

#[derive(Default, Deserialize, Debug, Clone, Validate)]
pub struct RegistryForm {
    #[validate(length(min = 2, max = 20, message = "username length(2-20)"))]
    username: String,
    #[validate(length(min = 8, max = 32, message = "password length(8-32)"))]
    password: String,
}

#[derive(Serialize)]
struct RegistryResponse {
    username: String,
}

#[tracing::instrument(skip(state,registry_form),fields(registry_form.username = %registry_form.username))]
pub async fn registry(
    registry_form: RegistryForm,
    state: AppState,
) -> Result<impl warp::Reply, ErrorResponse> {
    let manager = &state.users_manager;
    if manager
        .get_user_by_username(registry_form.username.clone())
        .await
        .is_ok()
    {
        return Err(ErrorResponse::from(RegistryError::UserExist));
    }

    let roles = vec!["user".to_string()];

    let user = RegistryUsers {
        username: registry_form.username,
        password: registry_form.password,
        roles,
    };

    let user = manager.add_user(user).await?;

    Ok(warp::reply::json(&RegistryResponse {
        username: user.username,
    }))
}

use std::fs::File;
use std::io::{BufRead, BufReader, Error};
use regex::Regex;
use std::collections::{HashMap, VecDeque, HashSet};

type Graph = HashMap<String, Vec<(String, usize)>>;

fn get_input(filename: &str) -> Result<Vec<String>, Error> {
    BufReader::new(File::open(filename).unwrap()).lines().collect()
}

fn process_input(input: Vec<String>) -> (Graph, Graph) {
    let bag_reg = Regex::new(r"^(?:(\w+ \w+) bags contain)").unwrap();
    let content_reg = Regex::new(r"(?:(\d+) (\w+ \w+) bags?[,\.])").unwrap();
    let mut t_bags_graph = Graph::new();
    let mut bags_graph = Graph::new();

    for line in input {
        let cur_bag = bag_reg.captures(&line).unwrap()[1].to_string();

        for caps in content_reg.captures_iter(&line) {
            t_bags_graph
                .entry(caps[2].to_string())
                .or_insert(Vec::new())
                .push((cur_bag.clone(), caps[1].parse().unwrap()));

            bags_graph
                .entry(cur_bag.clone())
                .or_insert(Vec::new())
                .push((caps[2].to_string(), caps[1].parse().unwrap()));
        }
    }

    (t_bags_graph, bags_graph)
}

fn solve_part1(graph: Graph) -> usize {
    let mut Q: VecDeque<String> = VecDeque::new();
    let mut vis: HashSet<String> = HashSet::new();

    Q.push_back("shiny gold".to_string());

    while !Q.is_empty() {
        let node = Q.pop_front().unwrap();

        if !vis.contains(&node) {
            vis.insert(node.clone());

            for (neigh, _) in graph.get(&node).unwrap_or(&vec![]) {
                if !vis.contains(neigh) {
                    Q.push_back(neigh.to_string());
                }
            }
        }
    }

    vis.len() - 1
}

fn solve_part2(graph: Graph) -> usize {
    let mut Q: VecDeque<(String, usize)> = VecDeque::new();
    let mut ans = 0;

    Q.push_back(("shiny gold".to_string(), 1));

    while !Q.is_empty() {
        let (node, cur_val) = Q.pop_front().unwrap();

        for (neigh, cost) in graph.get(&node).unwrap_or(&vec![]) {
            Q.push_back((neigh.to_string(), cur_val * cost))
        }

        ans += cur_val
    }

    ans - 1
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("\n==================================== Day 07 ====================================\n");

    let input : Vec<String> = match get_input("input/day07.in") {
        Ok(content) => content,
        Err(err) => return Err(err.into()),
    };

    let (t_graph, graph) = process_input(input);

    println!("The answer for part1 is: {}", solve_part1(t_graph));
    println!("The answer for part2 is: {}", solve_part2(graph));

    println!("\n================================================================================\n");

    Ok(())
}

