use std::{convert::TryFrom, error::Error, fmt::Debug, fmt::Display};
/// Specifies a kind of test framework, or a composite `all` to capture all framework variants
#[derive(Deserialize, Debug, PartialEq, Clone)]
pub(crate) enum Kind {
    Bench,
    Integration,
    Command,
    Unit,
    All,
    Unknown(String),
}
impl ToString for Kind {
    fn to_string(&self) -> String {
        match self {
            Kind::Bench => "bench".to_string(),
            Kind::Integration => "integration".to_string(),
            Kind::Command => "command".to_string(),
            Kind::Unit => "unit".to_string(),
            Kind::All => "all".to_string(),
            Kind::Unknown(u) => format!("unknown({})", u),
        }
    }
}
impl Default for Kind {
    fn default() -> Self {
        Self::All
    }
}

/// An unknown test kind
#[derive(Debug)]
pub struct Unknown(String);

impl Display for Unknown {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Unknown test kind `{}`, please choose one of `all`, `api`, `bench`, `command`, `integration`, `rest`, or `unit`", self.0)
    }
}

impl Error for Unknown {}

impl TryFrom<&str> for Kind {
    fn try_from(from: &str) -> Result<Self, Unknown> {
        match from.to_lowercase().as_str() {
            "all" => Ok(Kind::All),
            "api" | "command" | "rest" => Ok(Kind::Command),
            "bench" | "benchmark" => Ok(Kind::Bench),
            "it" | "integration" => Ok(Kind::Integration),
            "unit" => Ok(Kind::Unit),
            default => Err(Unknown(default.into())),
        }
    }

    type Error = Unknown;
}

//! Currencylayer Source Provider
//! <https://api.currencylayer.com>
//!

use crate::{config::HttpsConfig, Error, Price, TradingPair};
use iqhttp::{HttpsClient, Query};
use rust_decimal::prelude::FromPrimitive;
use rust_decimal::Decimal;
use serde::{Deserialize, Serialize};
/// Hostname for Currencylayer API
pub const API_HOST: &str = "api.currencylayer.com";

/// Source provider for Currencylayer
pub struct CurrencylayerSource {
    https_client: HttpsClient,
    access_key: String,
}

///Parameters for queries
pub struct CurrencylayerParams {
    source: String,
    currencies: String,
    access_key: String,
}

impl CurrencylayerParams {
    ///Convert params into url query parameters
    pub fn to_request_uri(&self) -> Query {
        let mut query = Query::new();
        query.add("source".to_owned(), self.source.to_string());
        query.add("currencies".to_owned(), self.currencies.to_string());
        query.add("access_key".to_owned(), self.access_key.to_string());

        query
    }
}

impl CurrencylayerSource {
    /// Create a new Currencylayer source provider
    pub fn new(access_key: impl Into<String>, config: &HttpsConfig) -> Result<Self, Error> {
        let https_client = config.new_client(API_HOST)?;
        Ok(Self {
            https_client,
            access_key: access_key.into(),
        })
    }

    /// Get trading pairs
    pub async fn trading_pairs(&self, pair: &TradingPair) -> Result<Price, Error> {
        let params = CurrencylayerParams {
            source: pair.0.to_string(),
            currencies: pair.1.to_string(),
            access_key: self.access_key.clone(),
        };

        let query = params.to_request_uri();
        let resp: Response = self.https_client.get_json("/live", &query).await?;
        let price = resp
            .quotes
            .values()
            .into_iter()
            .last()
            .expect("expected currencylayer to return one value");
        let dec_price = Decimal::from_f64(*price)
            .expect("expected currencylayer response to convert to a decimal");
        Price::new(dec_price)
    }
}

/// Outer struct of the API responses
#[derive(Serialize, Deserialize, Debug)]
pub struct Response {
    success: bool,
    terms: String,
    privacy: String,
    timestamp: i64,
    source: String,
    quotes: std::collections::HashMap<String, f64>,
}

