    fn from(p: GenerateNoiseProperties) -> Self {
        p.to_string()
    }
}

use std::fs::{create_dir_all, read_dir, remove_file, File, OpenOptions};
use std::io::Read;
use std::str::FromStr;

use chrono::prelude::Utc;
use crossbeam::queue::SegQueue;
use uuid::Uuid;

use crate::types::body::IngestBody;
use metrics::Metrics;
use std::path::PathBuf;

use thiserror::Error;

#[derive(Debug, Error)]
pub enum Error {
    #[error(transparent)]
    Io(#[from] std::io::Error),
    #[error(transparent)]
    Serde(#[from] serde_json::Error),
    #[error(transparent)]
    Recv(#[from] crossbeam::RecvError),
    #[error(transparent)]
    Send(#[from] crossbeam::SendError<IngestBody>),
    #[error("{0:?} is not valid utf8")]
    NonUTF8(std::path::PathBuf),
    #[error("{0} is not a valid file name")]
    InvalidFileName(std::string::String),
}

#[derive(Default)]
pub struct Retry {
    waiting: SegQueue<PathBuf>,
}

impl Retry {
    pub fn new() -> Retry {
        create_dir_all("/tmp/logdna/").expect("can't create /tmp/logdna");
        Retry {
            waiting: SegQueue::new(),
        }
    }

    pub fn retry(&self, body: IngestBody) -> Result<(), Error> {
        Metrics::http().increment_retries();
        let file = OpenOptions::new().create(true).write(true).open(format!(
            "/tmp/logdna/{}_{}.retry",
            Utc::now().timestamp(),
            Uuid::new_v4().to_string()
        ))?;
        Ok(serde_json::to_writer(file, &body)?)
    }

    pub fn poll(&self) -> Result<Option<IngestBody>, Error> {
        if self.waiting.is_empty() {
            self.fill_waiting()?
        }

        if let Ok(path) = self.waiting.pop() {
            return Ok(Some(Self::read_from_disk(&path)?));
        }

        Ok(None)
    }

    fn fill_waiting(&self) -> Result<(), Error> {
        let files = read_dir("/tmp/logdna/")?;
        for file in files {
            let path = file?.path();
            if path.is_dir() {
                continue;
            }

            let file_name = path
                .file_name()
                .and_then(|s| s.to_str())
                .map(|s| s.to_string())
                .ok_or_else(|| Error::NonUTF8(path.clone()))?;

            let timestamp: i64 = file_name
                .split('_')
                .map(|s| s.to_string())
                .collect::<Vec<String>>()
                .get(0)
                .and_then(|s| FromStr::from_str(s).ok())
                .ok_or_else(|| Error::InvalidFileName(file_name.clone()))?;

            if Utc::now().timestamp() - timestamp < 15 {
                continue;
            }

            self.waiting.push(path);
        }

        Ok(())
    }

    fn read_from_disk(path: &PathBuf) -> Result<IngestBody, Error> {
        let mut file = File::open(path)?;
        let mut data = String::new();
        file.read_to_string(&mut data)?;
        remove_file(&path)?;
        Ok(serde_json::from_str(&data)?)
    }
}

//! A test to confirm that `bevy` allows minimising the window
//! This is run in CI to ensure that this doesn't regress again.
use bevy::{core_pipeline::clear_color::ClearColorConfig, prelude::*};

fn main() {
    // TODO: Combine this with `resizing` once multiple_windows is simpler than
    // it is currently.
    App::new()
        .insert_resource(WindowDescriptor {
            title: "Minimising".into(),
            ..Default::default()
        })
        .add_plugins(DefaultPlugins)
        .add_system(minimise_automatically)
        .add_startup_system(setup_3d)
        .add_startup_system(setup_2d)
        .run();
}

fn minimise_automatically(mut windows: ResMut<Windows>, mut frames: Local<u32>) {
    if *frames == 60 {
        windows.get_primary_mut().unwrap().set_minimized(true);
    } else {
        *frames += 1;
    }
}

/// A simple 3d scene, taken from the `3d_scene` example
fn setup_3d(
    mut commands: Commands,
    mut meshes: ResMut<Assets<Mesh>>,
    mut materials: ResMut<Assets<StandardMaterial>>,
) {
    // plane
    commands.spawn_bundle(PbrBundle {
        mesh: meshes.add(Mesh::from(shape::Plane { size: 5.0 })),
        material: materials.add(Color::rgb(0.3, 0.5, 0.3).into()),
        ..default()
    });
    // cube
    commands.spawn_bundle(PbrBundle {
        mesh: meshes.add(Mesh::from(shape::Cube { size: 1.0 })),
        material: materials.add(Color::rgb(0.8, 0.7, 0.6).into()),
        transform: Transform::from_xyz(0.0, 0.5, 0.0),
        ..default()
    });
    // light
    commands.spawn_bundle(PointLightBundle {
        point_light: PointLight {
            intensity: 1500.0,
            shadows_enabled: true,
            ..default()
        },
        transform: Transform::from_xyz(4.0, 8.0, 4.0),
        ..default()
    });
    // camera
    commands.spawn_bundle(Camera3dBundle {
        transform: Transform::from_xyz(-2.0, 2.5, 5.0).looking_at(Vec3::ZERO, Vec3::Y),
        ..default()
    });
}

/// A simple 2d scene, taken from the `rect` example
fn setup_2d(mut commands: Commands) {
    commands.spawn_bundle(Camera2dBundle {
        camera: Camera {
            // render the 2d camera after the 3d camera
            priority: 1,
            ..default()
        },
        camera_2d: Camera2d {
            // do not use a clear color
            clear_color: ClearColorConfig::None,
        },
        ..default()
    });
    commands.spawn_bundle(SpriteBundle {
        sprite: Sprite {
            color: Color::rgb(0.25, 0.25, 0.75),
            custom_size: Some(Vec2::new(50.0, 50.0)),
            ..default()
        },
        ..default()
    });
}

