        - Ident: gross
        - Ident: tax
        - Expr:
            - Ident: gross
            - Raw: "-"
            - Ident: tax
        "###);

        let (mat, frame, _) = materialize(find_pipeline(res2), context, None)?;

        assert_yaml_snapshot!(mat.functions, @r###"
        ---
        - Transform:
            From:
              name: table_1
              alias: ~
              declared_at: 35
        - Transform:
            Join:
              side: Inner
              with:
                name: customers
                alias: ~
                declared_at: 36
              filter:
                Using:
                  - Ident: customer_no
        "###);
        assert_yaml_snapshot!(frame.columns, @r###"
        ---
        - Ident: table_1.*
        - Ident: customers.*
        - Ident: customer_no
        "###);

        Ok(())
    }
}

