                Some(Err(err)) if err.is_lagged() => {
                    lagged = true;
                    println!("RX3 lagged");
                }
                Some(Err(err)) => panic!("RX3 error: {}", err),
            }
        }
        assert!(lagged, "RX3 did not lag behind");
    });

    let mut rx3_go_tx = Some(rx3_go_tx);
    for i in 0..128 {
        println!("Sending {}", i);
        let (reply_tx, mut reply_rx) = mpsc::channel(1);
