}
impl std::error::Error for InvalidBlock {}
impl fmt::Display for InvalidBlock {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            InvalidBlock::InvalidTerrain(value) => {
                write!(
                    f,
