use rust_hdl_pcb_core::prelude::*;

fn map_part_number_to_size(part: &str) -> SizeCode {
    match &part[0..=4] {
        "C0603" => SizeCode::I0201,
        "C1005" => SizeCode::I0402,
        "C1608" => SizeCode::I0603,
        "C2012" => SizeCode::I0805,
        "C3216" => SizeCode::I1206,
        "C3225" => SizeCode::I1210,
        "C4532" => SizeCode::I1812,
        "C5750" => SizeCode::I2220,
        _ => panic!("Unrecognized size code {}", part),
    }
}

fn map_part_number_to_voltage(part: &str) -> f64 {
    match &part[8..=9] {
        "0G" => 4.0,
        "0J" => 6.3,
        "1A" => 10.0,
        "1C" => 16.0,
        "1E" => 25.0,
        "1V" => 35.0,
        "1H" => 50.0,
        "1N" => 75.0,
        _ => panic!("No working voltage for {}", part),
    }
}

fn map_part_number_to_dielectric(part: &str) -> DielectricCode {
    // TODO - handle all dielectric codes...
    (&part[5..=7]).parse().unwrap()
}

fn map_part_number_to_pf(part: &str) -> f64 {
    map_three_digit_cap_to_pf(&part[10..=12])
}

fn map_part_number_to_tolerance(part: &str) -> CapacitorTolerance {
    match &part[13..14] {
        "B" => CapacitorTolerance::TenthPF,
        "C" => CapacitorTolerance::QuarterPF,
        "D" => CapacitorTolerance::HalfPF,
        "F" => CapacitorTolerance::OnePercent,
        "G" => CapacitorTolerance::TwoPercent,
        "J" => CapacitorTolerance::FivePercent,
        "K" => CapacitorTolerance::TenPercent,
        "M" => CapacitorTolerance::TwentyPercent,
        _ => panic!("Unknown capacitor tolerance indicator {}", part),
    }
}

pub fn make_tdk_c_series_capacitor(part_number: &str) -> CircuitNode {
    assert_eq!(&part_number[0..1], "C");
    let size = map_part_number_to_size(part_number);
    let tolerance = map_part_number_to_tolerance(part_number);
    let value_pf = map_part_number_to_pf(part_number);
    let value = map_pf_to_label(value_pf);
    let dielectric = map_part_number_to_dielectric(part_number);
    let voltage = map_part_number_to_voltage(part_number);
    let label = format!("{} {} {}V {}", value, tolerance, voltage, dielectric);
    let manufacturer = Manufacturer {
        name: "TDK".to_string(),
        part_number: part_number.to_owned(),
    };
    let description = format!(
        "TDK Commercial C Series MLCC Capacitor SMD {} {}",
        size, label
    );
    make_mlcc(
        label,
        manufacturer,
        description,
        size,
        value_pf,
        dielectric,
        voltage,
        tolerance,
    )
}

use crate::{Object, RealField};
use bbox::BoundingBox;
use num_traits::Float;
use std::sync::mpsc::{sync_channel, Receiver, SyncSender};

#[derive(Clone, Debug)]
pub struct MockObject<S: RealField> {
    value: S,
    normal: na::Vector3<S>,
    bbox: BoundingBox<S>,
    normal_call_sender: Option<SyncSender<na::Point3<S>>>,
}

impl<S: ::std::fmt::Debug + Float + RealField> MockObject<S> {
    pub fn new(value: S, normal: na::Vector3<S>) -> Self {
        Self::new_with_bbox(value, normal, BoundingBox::infinity())
    }
    pub fn new_with_bbox(value: S, normal: na::Vector3<S>, bbox: BoundingBox<S>) -> Self {
        MockObject {
            value,
            normal,
            bbox,
            normal_call_sender: None,
        }
    }
    pub fn add_normal_call_recorder(&mut self, buffer_size: usize) -> Receiver<na::Point3<S>> {
        let (sender, receiver) = sync_channel(buffer_size);
        self.normal_call_sender = Some(sender);
        receiver
    }
}

impl<S: ::std::fmt::Debug + RealField + Float + From<f32>> Object<S> for MockObject<S> {
    fn approx_value(&self, _: &na::Point3<S>, _: S) -> S {
        self.value
    }
    fn normal(&self, p: &na::Point3<S>) -> na::Vector3<S> {
        if let Some(sender) = &self.normal_call_sender {
            sender.send(*p).unwrap();
        }
        self.normal
    }
    fn bbox(&self) -> &BoundingBox<S> {
        &self.bbox
    }
}

use crate::manager::backend::{Backend, Renderer};
use cpal::{
	traits::{DeviceTrait, HostTrait, StreamTrait},
	Device, Stream, StreamConfig,
};

use super::Error;

enum State {
	Empty,
	Uninitialized {
		device: Device,
		config: StreamConfig,
	},
	Initialized {
		_stream: Stream,
	},
}

/// A backend that uses [cpal](https://crates.io/crates/cpal) to
/// connect a [`Renderer`] to the operating system's audio driver.
pub struct CpalBackend {
	state: State,
}

impl Backend for CpalBackend {
	type Settings = ();

	type Error = Error;

	fn setup(_settings: Self::Settings) -> Result<(Self, u32), Self::Error> {
		let host = cpal::default_host();
		let device = host
			.default_output_device()
			.ok_or(Error::NoDefaultOutputDevice)?;
		let config = device.default_output_config()?.config();
		let sample_rate = config.sample_rate.0;
		Ok((
			Self {
				state: State::Uninitialized { device, config },
			},
			sample_rate,
		))
	}

	fn start(&mut self, mut renderer: Renderer) -> Result<(), Self::Error> {
		if let State::Uninitialized { device, config } =
			std::mem::replace(&mut self.state, State::Empty)
		{
			let channels = config.channels;
			let stream = device.build_output_stream(
				&config,
				move |data: &mut [f32], _| {
					renderer.on_start_processing();
					for frame in data.chunks_exact_mut(channels as usize) {
						let out = renderer.process();
						if channels == 1 {
							frame[0] = (out.left + out.right) / 2.0;
						} else {
							frame[0] = out.left;
							frame[1] = out.right;
						}
					}
				},
				move |_| {},
			)?;
			stream.play()?;
			self.state = State::Initialized { _stream: stream };
		} else {
			panic!("Cannot initialize the backend multiple times")
		}
		Ok(())
	}
}

use machine::state::State;

/// octa difference
pub fn odif(state: &mut State, x: u8, y: u8, z: u8) {
    // Load operands
    let op1: u64 = state.gpr[y].into();
    let op2: u64 = state.gpr[z].into();

    // Execute
    let result = op1.saturating_sub(op2);

    // Store result
    state.gpr[x] = result.into();
}

// When starting program, start at state "Init"
// Always allow commands "debug" and "isready"
#[derive(PartialEq, Eq, Copy, Clone, Debug)]
pub enum Mode {
    // * `uci`
    // send all "id" and "option"  messages
    // send one "uciok" message
    // go to mode "Wait"
    Init,
    // * `setoption`
    // maybe initialize stuff
    // set the option
    // stay in mode Wait
    // * `ucinewgame`
    // reset status
    // take note that GUI supports the ucinewgame command
    // go to NewGame mode
    // * `position`
    // if GUI does not support ucinewgame, then:
    //     simulate `ucinewgame` command
    //     reprocess `position` command
    // set up position for same game
    // go to Ready mode
    Wait,
    // * `position`
    // set up position for new game
    // go to Ready mode
    NewGame,
    // * `go`
    // process the arguments
    // start searching
    // go to mode Search
    Ready,
    // * `ponderhit`
    // Execute the ponder move
    // stay in mode Search
    // * `stop`
    // * OR
    // * engine decides on best move
    // stop searching
    // send all "info" data/messages
    // send one "bestmove" message
    // stop search
    // go to mode Wait
    // * engine runs for a while
    // send all "info" data/messages
    Search,
    // For any mode:
    //
    // * `debug`
    // set debug as on or off
    // * `isready`
    // if mode is not Search, then: wait for everything to finish
    // send one "readyok" message
}
impl Mode {
    pub fn new() -> Mode {
        Mode::Init
    }
}

use git_repository as git;
use git_repository::bstr::ByteSlice;

use crate::commit::Message;

#[derive(Debug)]
#[cfg_attr(test, derive(PartialEq, Eq))]
pub enum Addition {
    /// The plain issue ID, like "123".
    IssueId(String),
}

mod additions {
    use std::{borrow::Cow, ops::Range};

    use crate::commit::message::Addition;

    fn cut(mut s: String, Range { start, end }: Range<usize>) -> String {
        let part_to_left = &s[..start];
        let new_start = part_to_left
            .rfind(|c: char| !c.is_whitespace())
            .and_then(|p| {
                part_to_left
                    .is_char_boundary(p + 1)
                    .then(|| p + 1)
                    .or_else(|| part_to_left[p..].chars().next().map(|c| p + c.len_utf8()))
            })
            .unwrap_or(start);
        let new_end = s[end..]
            .find(|c: char| !c.is_whitespace())
            .map(|p| p + end)
            .unwrap_or(end);
        s.replace_range(
            new_start..new_end,
            if new_end != end && new_start != start { " " } else { "" },
        );
        s
    }

    pub fn strip(mut title: Cow<'_, str>) -> (Cow<'_, str>, Vec<Addition>) {
        let mut additions = Vec::new();
        loop {
            let previous_len = title.len();
            let issue_sep = "(#";
            if let Some((pos, end_pos)) = title.find(issue_sep).and_then(|mut pos| {
                pos += issue_sep.len();
                title[pos..].find(')').map(|ep| (pos, ep))
            }) {
                additions.push(Addition::IssueId(title[pos..][..end_pos].to_owned()));
                title = cut(title.into_owned(), (pos - issue_sep.len())..(pos + end_pos + 1)).into();
            };
            if title.len() == previous_len {
                break;
            }
        }
        (title, additions)
    }

    #[cfg(test)]
    mod tests {
        use super::*;

        #[test]
        fn no_addition() {
            let (nt, a) = strip("hello there [abc] (abc)".into());
            assert_eq!(nt, "hello there [abc] (abc)");
            assert_eq!(a, vec![]);
        }

        #[test]
        fn strip_multiple_issue_numbers() {
            let (nt, a) = strip("(#other) foo (#123) hello (#42)".into());
            assert_eq!(nt, "foo hello");
            assert_eq!(
                a,
                vec![
                    Addition::IssueId("other".into()),
                    Addition::IssueId("123".into()),
                    Addition::IssueId("42".into())
                ]
            );
        }
    }
}

impl From<&'_ str> for Message {
    fn from(m: &str) -> Self {
        let (title, kind, body, breaking, breaking_description) = git_conventional::Commit::parse(m)
            .map(|c: git_conventional::Commit<'_>| {
                (
                    c.description().into(),
                    Some(c.type_()),
                    c.body().map(Into::into),
                    c.breaking(),
                    c.breaking_description()
                        .and_then(|d| if d == c.description() { None } else { Some(d) }),
                )
            })
            .unwrap_or_else(|_| {
                let m = git::objs::commit::MessageRef::from_bytes(m.as_bytes());
                (
                    m.summary().as_ref().to_string().into(),
                    None,
                    m.body().map(|b| b.without_trailer().to_str_lossy()),
                    false,
                    None,
                )
            });
        let (title, additions) = additions::strip(title);
        Message {
            title: title.into_owned(),
            kind: as_static_str(kind),
            body: body.map(|b| b.into_owned()),
            breaking,
            breaking_description: breaking_description.map(ToOwned::to_owned),
            additions,
        }
    }
}

/// Note that this depends on `crate::changelog::section::segment::Conventional::as_headline_name()`,
fn as_static_str(kind: Option<git_conventional::Type<'_>>) -> Option<&'static str> {
    kind.map(|kind| match kind.as_str() {
        "feat" | "add" | "added" => "feat",
        "fix" => "fix",
        "revert" | "remove" => "revert",
        "docs" => "docs",
        "style" => "style",
        "refactor" => "refactor",
        "change" => "change",
        "perf" => "perf",
        "test" => "test",
        "chore" => "chore",
        _ => "other",
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn no_conventional_no_additions_no_body() {
        assert_eq!(
            Message::from("hi"),
            Message {
                title: "hi".into(),
                body: None,
                kind: None,
                breaking: false,
                breaking_description: None,
                additions: vec![]
            }
        )
    }

    #[test]
    fn no_conventional_uses_summary() {
        assert_eq!(
            Message::from("hi\nho\nfoo\n\nbody"),
            Message {
                title: "hi ho foo".into(),
                body: Some("body".into()),
                kind: None,
                breaking: false,
                breaking_description: None,
                additions: vec![]
            }
        )
    }

    #[test]
    fn no_conventional_additions() {
        assert_eq!(
            Message::from("hi (#14123)\n\nbody\nother\n\nSigned: bar"),
            Message {
                title: "hi".into(),
                body: Some("body\nother".into()),
                kind: None,
                breaking: false,
                breaking_description: None,
                additions: vec![Addition::IssueId("14123".into())]
            }
        )
    }

    #[test]
    fn conventional_with_additions() {
        assert_eq!(
            Message::from("feat!: hi (#123)\n\nthe body\nBREAKING-CHANGE: breaks\n\nSigned: foobar"),
            Message {
                title: "hi".into(),
                body: Some("the body".into()),
                kind: Some("feat"),
                breaking: true,
                breaking_description: Some("breaks".into()),
                additions: vec![Addition::IssueId("123".into())]
            }
        )
    }
}

