#[doc(hidden)]
use annotation_rs::{Annotation, AnnotationEnumValue};
use std::collections::HashMap;
/// In Yukino entity, every field will be mapping into several column in database. When we work with
/// a Field, we don't need to be concerned about how it is mapped to a Column;the framework will map
/// the operations on the Field to the Column in the appropriate way.

/// Annotation of entity.
/// Declare a struct to be a entity.
#[derive(Annotation, Clone)]
#[mod_path = "yukino::annotations"]
pub struct Entity {
    /// target Table name(and prefix of attached tables). If empty, it will be generated based on the name of the struct(
    /// `CamelCase` style struct name will be convert into `snake_case`).
    pub name: Option<String>,
    /// Index annotations of entity, mapped by index name.
    pub indexes: Option<HashMap<String, Index>>,
}

/// Annotation of Index
/// Define a index in entity
#[derive(Annotation, Clone)]
#[mod_path = "yukino::annotations"]
pub struct Index {
    /// Name of fields contained in the index.
    pub fields: Vec<String>,
    /// Index method. default to be `b_tree`.
    #[field(enum_value = true, default = "b_tree")]
    pub method: IndexMethod,
    /// Is unique index. default to be false.
    #[field(default = false)]
    pub unique: bool,
}

/// Index Method enum
/// Variants may change depending on the platform
/// * "hash" is not support on `sqlite`
/// * "gin", "sp_gin", "gist", "brin" is only available on `postgre-sql`
#[derive(AnnotationEnumValue, Copy, Clone, Debug)]
#[mod_path = "yukino::annotations"]
pub enum IndexMethod {
    BTree,
    #[cfg(any(feature = "mysql", feature = "postgre-sql"))]
    Hash,
    #[cfg(any(feature = "postgre-sql"))]
    Gin,
    #[cfg(any(feature = "postgre-sql"))]
    #[variant_value("sp_gin")]
    SPGin,
    #[cfg(any(feature = "postgre-sql"))]
    Gist,
    #[cfg(any(feature = "postgre-sql"))]
    Brin,
}

#[doc = "Reader of register PARAM"]
pub type R = crate::R<u32, super::PARAM>;
#[doc = "Reader of field `MTXFIFO`"]
pub type MTXFIFO_R = crate::R<u8, u8>;
#[doc = "Reader of field `MRXFIFO`"]
pub type MRXFIFO_R = crate::R<u8, u8>;
impl R {
  #[doc = "Bits 0:3 - Master Transmit FIFO Size"]
  #[inline(always)]
  pub fn mtxfifo(&self) -> MTXFIFO_R {
    MTXFIFO_R::new((self.bits & 0x0f) as u8)
  }
  #[doc = "Bits 8:11 - Master Receive FIFO Size"]
  #[inline(always)]
  pub fn mrxfifo(&self) -> MRXFIFO_R {
    MRXFIFO_R::new(((self.bits >> 8) & 0x0f) as u8)
  }
}

use super::*;
use std::fmt::{self, Display};

pub fn format(graph: &QueryGraph) -> String {
    format!(
        "---- Query Graph ----\nResult Nodes: {}\nMarked Nodes: {}\nRoot Nodes: {}\n\n{}\n----------------------",
        fmt_raw_indices(&graph.result_nodes),
        fmt_node_tuples(&graph.marked_node_pairs),
        fmt_node_list(&graph.root_nodes()),
        stringify_nodes(graph, graph.root_nodes(), &mut Vec::new()).join("\n\n")
    )
}

fn stringify_nodes(graph: &QueryGraph, nodes: Vec<NodeRef>, seen_nodes: &mut Vec<NodeRef>) -> Vec<String> {
    let mut rendered_nodes = vec![];

    for node in nodes {
        if seen_nodes.contains(&node) {
            continue;
        }
        seen_nodes.push(node);
        let mut node_child_info = vec![];

        let children: Vec<NodeRef> = graph
            .outgoing_edges(&node)
            .iter()
            .map(|child_edge| {
                let child_node = graph.edge_target(child_edge);
                node_child_info.push(format!(
                    "Child (edge {}): Node {} - {}",
                    child_edge.id(),
                    child_node.id(),
                    graph.edge_content(child_edge).unwrap()
                ));

                child_node
            })
            .collect();

        rendered_nodes.push(format!(
            "Node {}: {}\n  {}",
            node.id(),
            graph.node_content(&node).unwrap(),
            node_child_info.join("\n  ")
        ));

        rendered_nodes.append(&mut stringify_nodes(graph, children, seen_nodes));
    }

    rendered_nodes
}

impl Display for Flow {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            Self::If(_) => write!(f, "(If (condition func)"),
        }
    }
}

impl Display for Computation {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            Self::Diff(_) => write!(f, "Diff"),
        }
    }
}

impl Display for Node {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            Self::Query(q) => write!(f, "{}", q),
            Self::Flow(flow) => write!(f, "{}", flow),
            Self::Computation(c) => write!(f, "{}", c),
            Self::Empty => write!(f, "Empty"),
        }
    }
}

impl Display for NodeRef {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "Node {}", self.id())
    }
}

impl Display for QueryGraph {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "{}", format(self))
    }
}

impl Display for QueryGraphDependency {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            Self::ExecutionOrder => write!(f, "ExecutionOrder"),
            Self::ParentResult(_) => write!(f, "ParentResult"),
            Self::ParentIds(_) => write!(f, "ParentIds"),
            Self::Then => write!(f, "Then"),
            Self::Else => write!(f, "Else"),
        }
    }
}

fn fmt_raw_indices(i: &[NodeIndex]) -> String {
    let refs: Vec<NodeRef> = i
        .into_iter()
        .map(|node_ix| NodeRef {
            node_ix: node_ix.clone(),
        })
        .collect();

    fmt_node_list(&refs)
}

fn fmt_node_list(v: &[NodeRef]) -> String {
    let inner_string = v
        .into_iter()
        .map(|x| format!("{}", x))
        .collect::<Vec<String>>()
        .join(", ");

    format!("[{}]", inner_string.as_str())
}

fn fmt_node_tuples(t: &[(NodeRef, NodeRef)]) -> String {
    let inner_string = t
        .into_iter()
        .map(|x| format!("({}, {})", x.0, x.1))
        .collect::<Vec<String>>()
        .join(", ");

    format!("[{}]", inner_string.as_str())
}

