use bevy_ecs::prelude::*;

#[derive(Component)]
struct A(f32);

pub struct Benchmark(World, Entity, Box<dyn System<In = Entity, Out = ()>>);

impl Benchmark {
    pub fn new() -> Self {
        let mut world = World::new();

        let entity = world.spawn().insert(A(0.0)).id();
        fn query_system(In(entity): In<Entity>, mut query: Query<&mut A>) {
            for _ in 0..100_000 {
                let mut a = query.get_mut(entity).unwrap();
                a.0 += 1.0;
            }
        }

        let mut system = IntoSystem::into_system(query_system);
        system.initialize(&mut world);
        system.update_archetype_component_access(&world);
        Self(world, entity, Box::new(system))
    }

    pub fn run(&mut self) {
        self.2.run(self.1, &mut self.0);
    }
}

use crate::{
  Error,
  Parser,
  Precedence,
  tokens::{
    Signs,
    Token,
    Tokens,
  },
};

use super::{
  Expression,
  Expressions,
  parse_expression,
  parse_type,
};

#[derive(Debug, Clone, PartialEq)]
pub struct Argument {
  token: Token,
  data_type: Token,
  value: Option<Box<Expressions>>
}

impl Expression for Argument {
  fn new() -> Self {
    Self {
      token: Token::new_empty(),
      data_type: Token::new_empty(),
      value: None,
    }
  }

  fn from_token(token: Token) -> Self {
    Self {
      token,
      data_type: Token::new_empty(),
      value: None,
    }
  }

  fn get_token(&self) -> Token {
    self.token.clone()
  }

  fn string(&self) -> String {
    let argument = format!(
      "{}: {}",
      self.get_token().value,
      self.get_type().value,
    );

    match self.get_value() {
      Some(value) => format!("{} = {}", argument, value.string()),
      None => argument,
    }
  }
}

impl Argument {
  pub fn new_box() -> Box<Expressions> {
    Box::new(Expressions::ARGUMENT(Expression::new()))
  }

  pub fn new_box_from_token(token: Token) -> Box<Expressions> {
    Box::new(Expressions::ARGUMENT(Expression::from_token(token)))
  }

  pub fn new_box_full(token: Token, data_type: Token, value: Option<Box<Expressions>>) -> Box<Expressions> {
    Box::new(Expressions::ARGUMENT(Argument { token, data_type, value }))
  }

  pub fn get_type(&self) -> Token {
    self.data_type.clone()
  }

  pub fn get_value(&self) -> Option<Box<Expressions>> {
    self.value.clone()
  }

  pub fn parse<'a>(
    parser: &'a mut Parser,
    standard_library: bool,
    with_this: bool,
  ) -> Result<Vec<Box<Expressions>>, Error> {
    let mut arguments: Vec<Box<Expressions>> = Vec::new();

    // Check if the next token is a right parentheses.
    if parser.next_token_is(Signs::new(Signs::RIGHTPARENTHESES)) {
      // Get the next token.
      parser.next_token();
    }

    let mut has_default = false;
    while !parser.current_token_is(Signs::new(Signs::RIGHTPARENTHESES)) {
      // Check if the next token is an identifier.
      if !parser.expect_token(Box::new(Tokens::IDENTIFIER)) {
        return Err(Error::from_token(
          String::from("is not a valid identifier."),
          parser.get_next_token(),
        ));
      }

      let mut argument: Argument = Expression::from_token(parser.get_current_token());

      // Check if the next token is a colon.
      if !parser.expect_token(Signs::new(Signs::COLON)) {
        return Err(Error::from_token(
          format!("expect `:`, got `{}` instead.", parser.get_next_token().value),
          parser.get_next_token(),
        ));
      }

      // Get the next token.
      parser.next_token();

      // Parse argument data type.
      match parse_type(parser) {
        Ok(data_type) => {
          // Set the argument data type.
          argument.data_type = data_type;
        },
        Err(_) => {
          return Err(Error::from_token(
            String::from("is not a valid data type."),
            parser.get_current_token(),
          ));
        },
      }

      // Check if the next token is an assign sign.
      if parser.expect_token(Signs::new(Signs::ASSIGN)) {
        has_default = true;

        // Get the next token.
        parser.next_token();

        // Parse default value expression.
        match parse_expression(parser, Precedence::LOWEST, standard_library, with_this) {
          Ok(value) => {
            argument.value = Some(value);
          },
          Err(error) => {
            return Err(error);
          },
        }
      } else if has_default {
        return Err(Error::from_token(
          String::from("the argument must has a default value."),
          parser.get_next_token(),
        ));
      }

      // Check if the next token is a comma.
      if parser.next_token_is(Signs::new(Signs::COMMA)) {
        // Get the next token.
        parser.next_token();
      }

      // Check if the next token is a right parentheses.
      if parser.next_token_is(Signs::new(Signs::RIGHTPARENTHESES)) {
        // Get the next token.
        parser.next_token();
      }

      // Add the argument to the list.
      arguments.push(Box::new(Expressions::ARGUMENT(argument.clone())));
    }

    // Return arguments.
    Ok(arguments)
  }
}

mod short_hex {
    #[test]
    fn display_entire_range_sha1() {
        let id_hex = "0123456789abcdef123456789abcdef123456789";
        let id = git_hash::ObjectId::from_hex(id_hex.as_bytes()).expect("valid input");
        for len in 0..=40 {
            assert_eq!(id.to_hex(len).to_string(), id_hex[..len]);
        }
        assert_eq!(
            id.to_hex(120).to_string(),
            id_hex,
            "values that are too long are truncated"
        );
    }
