//! A module implementing an io type backed by the C runtime's file descriptors, i.e. what's
//! returned from libc::open, even on windows.

use crate::suppress_iph;
use std::{cmp, ffi, fs, io, mem};

#[cfg(windows)]
use libc::commit as fsync;
#[cfg(windows)]
extern "C" {
    #[link_name = "_chsize_s"]
    fn ftruncate(fd: i32, len: i64) -> i32;
}
#[cfg(not(windows))]
use libc::{fsync, ftruncate};

#[inline]
fn cvt<T, I: num_traits::PrimInt>(ret: I, f: impl FnOnce(I) -> T) -> io::Result<T> {
    if ret < I::zero() {
        Err(crate::stdlib::os::errno())
    } else {
        Ok(f(ret))
    }
}

const MAX_RW: usize = if cfg!(any(windows, target_vendor = "apple")) {
    i32::MAX as usize
} else {
    isize::MAX as usize
};

#[derive(Copy, Clone, PartialEq, Eq)]
#[repr(transparent)]
pub struct Fd(pub i32);

impl Fd {
    pub fn open(path: &ffi::CStr, flags: i32, mode: i32) -> io::Result<Self> {
        cvt(unsafe { libc::open(path.as_ptr(), flags, mode) }, Fd)
    }

    #[cfg(windows)]
    pub fn wopen(path: &widestring::WideCStr, flags: i32, mode: i32) -> io::Result<Self> {
        cvt(
            unsafe { suppress_iph!(libc::wopen(path.as_ptr(), flags, mode)) },
            Fd,
        )
    }

    #[cfg(all(any(unix, target_os = "wasi"), not(target_os = "redox")))]
    pub fn openat(&self, path: &ffi::CStr, flags: i32, mode: i32) -> io::Result<Self> {
        cvt(
            unsafe { libc::openat(self.0, path.as_ptr(), flags, mode) },
            Fd,
        )
    }

    pub fn fsync(&self) -> io::Result<()> {
        cvt(unsafe { suppress_iph!(fsync(self.0)) }, drop)
    }

    pub fn close(&self) -> io::Result<()> {
        cvt(unsafe { suppress_iph!(libc::close(self.0)) }, drop)
    }

    pub fn ftruncate(&self, len: i64) -> io::Result<()> {
        cvt(unsafe { suppress_iph!(ftruncate(self.0, len)) }, drop)
    }

    /// NOTE: it's not recommended to use ManuallyDrop::into_inner() to drop the file - it won't
    /// work on all platforms, and will swallow any errors you might want to handle.
    #[allow(unused)] // only used on windows atm
    pub(crate) fn as_rust_file(&self) -> io::Result<mem::ManuallyDrop<fs::File>> {
        #[cfg(windows)]
        let file = {
            use std::os::windows::io::FromRawHandle;
            let handle = self.to_raw_handle()?;
            unsafe { fs::File::from_raw_handle(handle) }
        };
        #[cfg(unix)]
        let file = {
            let fd = self.0;
            use std::os::unix::io::FromRawFd;
            if fd < 0 {
                return Err(io::Error::from_raw_os_error(libc::EBADF));
            }
            unsafe { fs::File::from_raw_fd(fd) }
        };
        #[cfg(target_os = "wasi")]
        let file = {
            let fd = self.0;
            if fd < 0 {
                return Err(io::Error::from_raw_os_error(libc::EBADF));
            }
            // SAFETY: as of now, File is a wrapper around WasiFd, which is a wrapper around
            // wasi::Fd (u32). This isn't likely to change, and if it does change to a different
            // sized integer, mem::transmute will fail.
            unsafe { mem::transmute::<u32, fs::File>(fd as u32) }
        };
        Ok(mem::ManuallyDrop::new(file))
    }

    #[cfg(windows)]
    pub(crate) fn to_raw_handle(&self) -> io::Result<std::os::windows::io::RawHandle> {
        use winapi::um::{handleapi::INVALID_HANDLE_VALUE, winnt::HANDLE};
        extern "C" {
            fn _get_osfhandle(fd: i32) -> libc::intptr_t;
        }
        let handle = unsafe { suppress_iph!(_get_osfhandle(self.0)) } as HANDLE;
        if handle == INVALID_HANDLE_VALUE {
            Err(io::Error::last_os_error())
        } else {
            Ok(handle)
        }
    }
}

impl io::Write for &Fd {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        let count = cmp::min(buf.len(), MAX_RW);
        cvt(
            unsafe { suppress_iph!(libc::write(self.0, buf.as_ptr() as _, count as _)) },
            |i| i as usize,
        )
    }

    #[inline]
    fn flush(&mut self) -> io::Result<()> {
        Ok(())
    }
}

impl io::Write for Fd {
    #[inline]
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        (&*self).write(buf)
    }

    #[inline]
    fn flush(&mut self) -> io::Result<()> {
        (&*self).flush()
    }
}

impl io::Read for &Fd {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        let count = cmp::min(buf.len(), MAX_RW);
        cvt(
            unsafe { suppress_iph!(libc::read(self.0, buf.as_mut_ptr() as _, count as _)) },
            |i| i as usize,
        )
    }
}

impl io::Read for Fd {
    #[inline]
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        (&*self).read(buf)
    }
}

use super::{BTreeMap, Felt, FieldElement, RangeChecker};
use rand_utils::rand_array;
use vm_core::{utils::ToElements, StarkField};

#[test]
fn range_checks() {
    let mut checker = RangeChecker::new();

    let values = [0, 1, 2, 2, 2, 2, 3, 3, 3, 4, 4, 100, 355, 620].to_elements();

    for &value in values.iter() {
        checker.add_value(value.as_int() as u16)
    }

    let trace = checker.into_trace(1024);
    validate_trace(&trace, &values);

    // skip the 8-bit portion of the trace
    let mut i = 0;
    while trace[0][i] == Felt::ZERO {
        i += 1
    }

    // make sure the values are arranged as expected
    validate_row(&trace, i, 0, 1);
    validate_row(&trace, i + 1, 1, 1);
    validate_row(&trace, i + 2, 2, 4);
    validate_row(&trace, i + 3, 3, 2);
    validate_row(&trace, i + 4, 3, 1);
    validate_row(&trace, i + 5, 4, 2);
    validate_row(&trace, i + 6, 100, 1);
    validate_row(&trace, i + 7, 355, 1);
    validate_row(&trace, i + 8, 610, 0);
    validate_row(&trace, i + 9, 620, 1);
}

#[test]
fn range_checks_rand() {
    let mut checker = RangeChecker::new();
    let values = rand_array::<u64, 300>();
    let values = values
        .into_iter()
        .map(|v| Felt::new(v as u16 as u64))
        .collect::<Vec<_>>();

    for &value in values.iter() {
        checker.add_value(value.as_int() as u16);
    }

    let trace_len = checker.trace_len().next_power_of_two();
    let trace = checker.into_trace(trace_len);
    validate_trace(&trace, &values);
}

// HELPER FUNCTIONS
// ================================================================================================

fn validate_row(trace: &[Vec<Felt>], row_idx: usize, value: u64, num_lookups: u64) {
    let (s0, s1) = match num_lookups {
        0 => (Felt::ZERO, Felt::ZERO),
        1 => (Felt::ONE, Felt::ZERO),
        2 => (Felt::ZERO, Felt::ONE),
        4 => (Felt::ONE, Felt::ONE),
        _ => panic!("invalid lookup value"),
    };

    assert_eq!(s0, trace[1][row_idx]);
    assert_eq!(s1, trace[2][row_idx]);
    assert_eq!(Felt::new(value), trace[3][row_idx]);
}

fn validate_trace(trace: &[Vec<Felt>], lookups: &[Felt]) {
    assert_eq!(4, trace.len());

    // trace length must be a power of two
    let trace_len = trace[0].len();
    assert!(trace_len.is_power_of_two());

    // --- validate the 8-bit segment of the trace ----------------------------

    // should start with a ZERO
    assert_eq!(Felt::ZERO, trace[0][0]);
    assert_eq!(Felt::ZERO, trace[3][0]);

    let mut lookups_8bit = BTreeMap::new();

    // values in the 8-bit segment should be 8 bits; also, count the number of lookups
    // for each 8-bit value.
    let mut i = 0;
    let mut prev_value = 0u8;
    while trace[0][i] == Felt::ZERO {
        // make sure the value is an 8-bit value
        let value = trace[3][i].as_int();
        assert!(value <= 255, "not an 8-bit value");
        let value = value as u8;

        // make sure the delta between this and the previous value is either 0 or 1
        let delta = value - prev_value;
        assert!(delta <= 1);

        // keep track of lookup count for each value
        let count = get_lookup_count(&trace, i);
        lookups_8bit
            .entry(value)
            .and_modify(|value| *value += count)
            .or_insert(count);

        i += 1;
        prev_value = value;
    }

    // validate the last row (must be 255)
    let last_value = trace[3][i - 1].as_int();
    assert_eq!(255, last_value);

    // all possible 8-bit values must be in the map
    assert_eq!(256, lookups_8bit.len());

    // --- validate the 16-bit segment of the trace ---------------------------

    let mut lookups_16bit = BTreeMap::new();

    // process the first row
    assert_eq!(Felt::ZERO, trace[3][i]);
    let count = get_lookup_count(&trace, i);
    lookups_16bit.insert(0u16, count);
    i += 1;

    // process all other rows
    let mut prev_value = 0u16;
    while i < trace_len {
        // segment identifier must be set to ONE
        assert_eq!(Felt::ONE, trace[0][i]);

        // make sure the value is a 16-bit value
        let value = trace[3][i].as_int();
        assert!(value <= 65535, "not an 8-bit value");
        let value = value as u16;

        // make sure the delta between this and the previous value is less than 255,
        // and remove the delta from the 8-bit table
        let delta = value - prev_value;
        assert!(delta <= 255);
        let delta = delta as u8;
        lookups_8bit.entry(delta).and_modify(|count| {
            assert!(*count > 0);
            *count -= 1;
        });

        // keep track of lookup count for each value
        let count = get_lookup_count(&trace, i);
        lookups_16bit
            .entry(value)
            .and_modify(|value| *value += count)
            .or_insert(count);

        i += 1;
        prev_value = value;
    }

    // validate the last row (must be 65535)
    let last_value = trace[3][i - 1].as_int();
    assert_eq!(65535, last_value);

    // at the end, 8-bit table should be empty
    for &value in lookups_8bit.values() {
        assert_eq!(0, value);
    }

    // remove all the looked up values from the 16-bit lookup table
    for value in lookups {
        let value = value.as_int();
        assert!(value <= 65535, "not a 16-bit value");
        let value = value as u16;

        assert!(lookups_16bit.contains_key(&value));
        lookups_16bit.entry(value).and_modify(|count| {
            assert!(*count > 0);
            *count -= 1;
        });
    }

    // make sure 16-bit table is empty
    for &value in lookups_16bit.values() {
        assert_eq!(0, value);
    }
}

fn get_lookup_count(trace: &[Vec<Felt>], step: usize) -> usize {
    if trace[1][step] == Felt::ZERO && trace[2][step] == Felt::ZERO {
        0
    } else if trace[1][step] == Felt::ONE && trace[2][step] == Felt::ZERO {
        1
    } else if trace[1][step] == Felt::ZERO && trace[2][step] == Felt::ONE {
        2
    } else if trace[1][step] == Felt::ONE && trace[2][step] == Felt::ONE {
        4
    } else {
        panic!("not a valid count");
    }
}

use std::ffi::CStr;
use std::fmt;

use crate::bindings;

pub type ElementKind = bindings::TfLiteType;
pub type QuantizationParams = bindings::TfLiteQuantizationParams;

pub trait ElemKindOf {
    fn elem_kind_of() -> ElementKind;
}

impl ElemKindOf for f32 {
    fn elem_kind_of() -> ElementKind {
        bindings::TfLiteType::kTfLiteFloat32
    }
}

impl ElemKindOf for u8 {
    fn elem_kind_of() -> ElementKind {
        bindings::TfLiteType::kTfLiteUInt8
    }
}

impl ElemKindOf for i32 {
    fn elem_kind_of() -> ElementKind {
        bindings::TfLiteType::kTfLiteInt32
    }
}

pub struct TensorInfo {
    pub name: String,
    pub element_kind: ElementKind,
    pub dims: Vec<usize>,
}

impl fmt::Debug for TensorInfo {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("TensorInfo")
            .field("name", &self.name)
            .field("element_kind", &self.element_kind)
            .field("dims", &self.dims)
            .finish()
    }
}

impl<'a> From<&'a bindings::TfLiteTensor> for TensorInfo {
    fn from(t: &'a bindings::TfLiteTensor) -> Self {
        Self {
            name: unsafe { CStr::from_ptr(t.name) }.to_str().unwrap().to_string(),
            element_kind: t.type_,
            dims: {
                let slice = unsafe {
                    let dims = &*t.dims;
                    dims.data.as_slice(dims.size as usize)
                };
                slice.iter().map(|n| *n as usize).collect()
            },
        }
    }
}

