use anyhow::{self, Context};
use fidl_fidl_examples_routing_echo::{EchoRequest, EchoRequestStream};
use fuchsia_component::server::ServiceFs;
use futures::prelude::*;

// Wrap protocol requests being served.
enum IncomingRequest {
    Echo(EchoRequestStream),
}

#[fuchsia::main(logging = false)]
async fn main() -> Result<(), anyhow::Error> {
    let mut service_fs = ServiceFs::new_local();

    // Serve the Echo protocol
    service_fs.dir("svc").add_fidl_service(IncomingRequest::Echo);
    service_fs.take_and_serve_directory_handle().context("failed to serve outgoing namespace")?;

    // Attach request handler for incoming requests
    service_fs
        .for_each_concurrent(None, |request: IncomingRequest| async move {
            match request {
                IncomingRequest::Echo(stream) => handle_echo_request(stream).await,
            }
        })
        .await;

    Ok(())
}

// Handler for incoming service requests
async fn handle_echo_request(mut stream: EchoRequestStream) {
    while let Some(event) = stream.try_next().await.expect("failed to serve echo service") {
        let EchoRequest::EchoString { value, responder } = event;
        responder.send(value.as_ref().map(|s| &**s)).expect("failed to send echo response");
    }
}

use std::io::{BufWriter, Write};

use anyhow::Result;
use opencv::{core, prelude::*};

pub trait Printer<T: Write> {
    fn print_img(&self, img: &core::Mat, out: &mut BufWriter<T>) -> Result<()>;
}

pub struct FlatPrinter;

impl<T: Write> Printer<T> for FlatPrinter {
    fn print_img(&self, img: &core::Mat, out: &mut BufWriter<T>) -> Result<()> {
        let size = img.size()?;
        for y in 0..size.height {
            for x in 0..size.width {
                if img.typ() == core::CV_8UC1 {
                    let val = img.at_2d::<u8>(y, x)?;
                    write!(out, "\x1b[48;2;{};{};{}m  ", val, val, val)?;
                } else {
                    let val = img.at_2d::<core::Vec3b>(y, x)?;
                    write!(out, "\x1b[48;2;{};{};{}m  ", val[2], val[1], val[0])?;
                }
            }
            out.write_all(b"\x1b[0m\n")?;
        }
        Ok(())
    }
}

pub struct SuperResolutionPrinter;

impl<T: Write> Printer<T> for SuperResolutionPrinter {
    fn print_img(&self, img: &core::Mat, out: &mut BufWriter<T>) -> Result<()> {
        let size = img.size()?;
        for y in (0..size.height - 1).step_by(2) {
            for x in 0..size.width {
                if img.typ() == core::CV_8UC1 {
                    let upper = img.at_2d::<u8>(y, x)?;
                    let lower = img.at_2d::<u8>(y + 1, x)?;
                    write!(
                        out,
                        "\x1b[38;2;{};{};{}m\x1b[48;2;{};{};{}m▀",
                        upper, upper, upper, lower, lower, lower,
                    )?;
                } else {
                    let upper = img.at_2d::<core::Vec3b>(y, x)?;
                    let lower = img.at_2d::<core::Vec3b>(y + 1, x)?;
                    write!(
                        out,
                        "\x1b[38;2;{};{};{}m\x1b[48;2;{};{};{}m▀",
                        upper[2], upper[1], upper[0], lower[2], lower[1], lower[0],
                    )?;
                }
            }
            out.write_all(b"\x1b[0m\n")?;
        }
        Ok(())
    }
}

use lumi_server_defs::{FilterOptions, DEFAULT_ENTRIES_PER_PAGE};
use yew::prelude::*;
use yew_router::prelude::*;

#[derive(Properties, Clone, Debug, PartialEq, Eq)]
pub struct Props {
    #[prop_or(DEFAULT_ENTRIES_PER_PAGE)]
    pub entries: usize,
}

struct State {
    show_menu: bool,
}

pub struct EntrySelector {
    state: State,
    props: Props,
    link: ComponentLink<Self>,
}

pub enum Msg {
    ShowMenu,
}

impl Component for EntrySelector {
    type Message = Msg;
    type Properties = Props;

    fn create(props: Self::Properties, link: ComponentLink<Self>) -> Self {
        Self {
            props,
            link,
            state: State { show_menu: false },
        }
    }

    fn change(&mut self, props: Self::Properties) -> ShouldRender {
        if self.props == props {
            false
        } else {
            self.props = props;
            true
        }
    }

    fn update(&mut self, msg: Self::Message) -> ShouldRender {
        match msg {
            Msg::ShowMenu => {
                self.state.show_menu = !self.state.show_menu;
            }
        }
        true
    }

    fn view(&self) -> Html {
        let show_menu = self.link.callback(|_| Msg::ShowMenu);
        let route_service = RouteService::<()>::new();
        let query = route_service.get_query();
        let mut chars = query.chars();
        chars.next();
        let query = chars.as_str();
        let current_option: FilterOptions = serde_urlencoded::from_str(&query).unwrap_or_default();
        let current_path = route_service.get_path();

        let menu_items: Vec<_> = [20, 50, 100]
            .iter()
            .map(|n| {
                let n = *n;
                let mut new_option = current_option.clone();
                if n == DEFAULT_ENTRIES_PER_PAGE {
                    new_option.entries = None;
                } else {
                    new_option.entries = Some(n);
                }
                let query = serde_urlencoded::to_string(&new_option).unwrap();
                let dest = if query.len() > 0 {
                    format!("{}?{}", &current_path, query)
                } else {
                    format!("{}", &current_path)
                };
                type Anchor = RouterAnchor<String>;
                let item_class = if new_option.entries == current_option.entries {
                    "entry-number button selected"
                } else {
                    "entry-number button"
                };
                html! {
                    <Anchor route={dest} classes={item_class}>{n}</Anchor>
                }
            })
            .collect();
        let menu_class = if self.state.show_menu {
            "entry-menu"
        } else {
            "entry-menu hide"
        };
        let menu_button = if self.state.show_menu {
            html! {
                <span onclick={show_menu} class="button selected">{self.props.entries}{" rows"}<div class="arrow-up"></div></span>
            }
        } else {
            html! {
                <span onclick={show_menu} class="button">{self.props.entries}{" rows"}<div class="arrow-down"></div></span>
            }
        };
        html! {
            <div class="select-entries">
                {menu_button}
                <div class={menu_class}>
                    {menu_items}
                </div>
            </div>
        }
    }
}

