// Hide the concrete type of the `Mesh` (specifically the graphics backend)
// by use of `Any`. TODO: there has GOT to be a better way to do this. All I really
// want is to be able to make a `Pointer` to a trait that `Mesh` implements,
// and use that to access the `Storage` of the specific type.
pub struct MeshWrapper {
    mesh: Box<dyn any::Any + Send + Sync + 'static>,
}

/// `gfx::Factory` is not `Send`, so we can't send that around
/// between threads. Instead this mesh repository is shared through
/// an `Arc<Mutex<_>>` and new meshes are only ever created from
/// the main thread, which owns the graphics device and therefore
/// also owns the factory. See `create` below for more.
pub struct MeshRepository<R: gfx::Resources> {
    log: Logger,
    mesh_storage: froggy::Storage<MeshWrapper>,
    default_output_color_buffer: gfx::handle::RenderTargetView<R, gfx::format::Srgba8>,
    default_output_stencil_buffer: gfx::handle::DepthStencilView<R, gfx::format::DepthStencil>,
}

impl<R: gfx::Resources> MeshRepository<R> {
    pub fn new(
        default_output_color_buffer: gfx::handle::RenderTargetView<R, gfx::format::Srgba8>,
        default_output_stencil_buffer: gfx::handle::DepthStencilView<R, gfx::format::DepthStencil>,
        parent_log: &Logger,
    ) -> MeshRepository<R> {
        MeshRepository {
            mesh_storage: froggy::Storage::new(),
            default_output_color_buffer,
            default_output_stencil_buffer,
            log: parent_log.new(o!()),
        }
    }

    pub fn create<F: gfx::Factory<R>>(
        &mut self,
        factory: &mut F,
        vertexes: Vec<Vertex>,
        triangle_vertex_indexes: Vec<u32>,
    ) -> froggy::Pointer<MeshWrapper> {
        let mesh = Mesh::new(
            factory,
            vertexes,
            triangle_vertex_indexes,
            self.default_output_color_buffer.clone(),
            self.default_output_stencil_buffer.clone(),
        );
        self.add_mesh(mesh)
    }

    pub fn add_mesh(&mut self, mesh: Mesh<R>) -> froggy::Pointer<MeshWrapper> {
        trace!(self.log, "Adding mesh");
        self.mesh_storage.create(MeshWrapper {
            mesh: Box::new(mesh),
        })
    }

    /// Destroy any unused meshes by asking the `froggy::Storage` to catch
    /// up on its internal bookkeeping.
    pub fn collect_garbage(&mut self) {
        self.mesh_storage.sync_pending()
    }
}

impl<'a, R: gfx::Resources> MeshRepository<R> {
    pub fn get_mut(&'a mut self, mesh_pointer: &froggy::Pointer<MeshWrapper>) -> &'a mut Mesh<R> {
        let mesh_wrapper = &mut self.mesh_storage[&mesh_pointer];
        let any_mesh_with_extra_constraints = &mut *mesh_wrapper.mesh;
        let any_mesh = any_mesh_with_extra_constraints as &mut dyn any::Any;
        any_mesh
            .downcast_mut::<Mesh<R>>()
            .expect("Unless we're mixing graphics backends, this should be impossible.")
    }
}

//! Operations over types.

use super::*;
use syn::punctuated::Punctuated;

fn new_segment(ident: Id, args: Option<GenericArgs>) -> syn::PathSegment {
    let arguments = {
        if let Some(gen_args) = args {
            let mut args = Punctuated::new();
            for arg in gen_args {
                args.push(arg)
            }
            syn::PathArguments::AngleBracketed(syn::AngleBracketedGenericArguments {
                colon2_token: None,
                lt_token: rust::token::Lt {
                    spans: [Span::mixed_site()],
                },
                args,
                gt_token: rust::token::Gt {
                    spans: [Span::mixed_site()],
                },
            })
        } else {
            syn::PathArguments::None
        }
    };

    syn::PathSegment { ident, arguments }
}

fn typ_from_segments(segments: Punctuated<syn::PathSegment, rust::token::Colon2>) -> Typ {
    Typ::Path(syn::TypePath {
        qself: None,
        path: syn::Path {
            leading_colon: None,
            segments,
        },
    })
}

pub fn plain(ident: Id, args: Option<GenericArgs>) -> Typ {
    let segments = {
        let mut segments = Punctuated::new();
        segments.push(new_segment(ident, args));
        segments
    };
    typ_from_segments(segments)
}

pub fn tuple(typs: impl IntoIterator<Item = Typ>) -> Typ {
    Typ::Tuple(syn::TypeTuple {
        paren_token: rust::token::Paren::default(),
        elems: typs.into_iter().collect(),
    })
}

fn internal_ref(lifetime: Option<Lifetime>, typ: Typ, is_mut: bool) -> Typ {
    Typ::Reference(syn::TypeReference {
        and_token: rust::token::And::default(),
        lifetime,
        mutability: if is_mut {
            Some(rust::token::Mut::default())
        } else {
            None
        },
        elem: Box::new(typ),
    })
}
pub fn reference(lifetime: Option<Lifetime>, typ: Typ) -> Typ {
    internal_ref(lifetime, typ, false)
}
pub fn reference_mut(lifetime: Option<Lifetime>, typ: Typ) -> Typ {
    internal_ref(lifetime, typ, true)
}

pub fn simple_path(
    path: impl IntoIterator<Item = Id>,
    ident: Id,
    args: Option<GenericArgs>,
) -> Typ {
    let segments = {
        let mut segments = Punctuated::new();
        for seg in path {
            segments.push(new_segment(seg, None));
        }
        segments.push(new_segment(ident, args));
        segments
    };
    typ_from_segments(segments)
}

pub mod param {
    use super::*;

    pub fn from_id(ident: Id) -> TypParam {
        TypParam {
            attrs: vec![],
            ident,
            colon_token: None,
            bounds: syn::punctuated::Punctuated::new(),
            eq_token: None,
            default: None,
        }
    }
}

pub mod generic_param {
    use super::*;

    pub fn from_id(id: Id) -> GenericParam {
        GenericParam::Type(param::from_id(id))
    }
    pub fn from_lifetime(lifetime: rust::Lifetime) -> GenericParam {
        GenericParam::Lifetime(syn::LifetimeDef {
            attrs: vec![],
            lifetime,
            colon_token: None,
            bounds: syn::punctuated::Punctuated::new(),
        })
    }
}

pub mod generic_arg {
    use super::*;

    pub fn from_typ(typ: Typ) -> GenericArg {
        GenericArg::Type(typ)
    }
    pub fn from_lifetime(lt: Lifetime) -> GenericArg {
        GenericArg::Lifetime(lt)
    }
}

pub mod lib {
    use super::*;

    pub fn empty() -> rust::Typ {
        let path = Some(gen::lib_path());
        let id = Id::new("Empty", gen::span());
        rust::typ::simple_path(path, id, None)
    }

    pub fn zipper(e_typ: rust::Typ) -> rust::Typ {
        let path = Some(gen::lib_path());
        simple_path(
            path,
            gen::trai::lib::zipper(),
            Some(vec![generic_arg::from_typ(e_typ)]),
        )
    }
    pub fn stepper(e_typ: rust::Typ) -> rust::Typ {
        let path = Some(gen::lib_path());
        simple_path(
            path,
            gen::trai::lib::stepper(),
            Some(vec![generic_arg::from_typ(e_typ)]),
        )
    }

    pub fn zip_do(down_typ: rust::Typ, e_typ: rust::Typ, res_typ: rust::Typ) -> rust::Typ {
        let path = Some(gen::lib_path());
        let id = Id::new("ZipDo", gen::span());
        simple_path(
            path,
            id,
            Some(vec![
                generic_arg::from_typ(down_typ),
                generic_arg::from_typ(e_typ),
                generic_arg::from_typ(res_typ),
            ]),
        )
    }
}

pub fn to_expr_ref(typ: rust::Typ) -> Typ {
    Typ::Reference(syn::TypeReference {
        and_token: rust::token::And {
            spans: [gen::span()],
        },
        lifetime: Some(gen::lifetime::expr()),
        mutability: None,
        elem: Box::new(typ),
    })
}

