//! Dev authenticator is a test-only authenticator that produces fake authentication
//! events to be consumed by identity components during tests.

mod storage_unlock;

use crate::storage_unlock::{Mode, StorageUnlockMechanism};
use anyhow::{anyhow, Error};
use fuchsia_async as fasync;
use fuchsia_component::server::ServiceFs;
use futures::StreamExt;
use log::{error, info};
use std::convert::TryFrom;

/// This required command line option (prefixed with `--`) determines the mode of operation.
const MODE_OPTION: &str = "mode";
/// These are the valid arguments for the mode command line option.
const MODE_ARG_ALWAYS_SUCCEED: &str = "ALWAYS_SUCCEED";
const MODE_ARG_ALWAYS_FAIL_AUTHENTICATION: &str = "ALWAYS_FAIL_AUTHENTICATION";

#[fasync::run_singlethreaded]
async fn main() -> Result<(), Error> {
    let mut opts = getopts::Options::new();
    opts.reqopt("", MODE_OPTION, "set the mode of operation", "MODE");
    let args: Vec<String> = std::env::args().collect();
    let options = opts.parse(args)?;
    let mode_arg_str = options.opt_str(MODE_OPTION).expect("Internal getopts error");
    let mode = Mode::try_from(mode_arg_str.as_ref())?;

    fuchsia_syslog::init_with_tags(&["auth"]).expect("Failed to initialize logger");
    info!("Starting dev authenticator");

    let mut fs = ServiceFs::new();
    fs.dir("svc").add_fidl_service(move |stream| {
        fasync::spawn(async move {
            let mechanism = StorageUnlockMechanism::new(mode);
            mechanism
                .handle_requests_from_stream(stream)
                .await
                .unwrap_or_else(|e| error!("Error handling storage unlock stream: {:?}", e));
        });
    });

    fs.take_and_serve_directory_handle().expect("Failed to serve directory");

    fs.collect::<()>().await;
    Ok(())
}

impl TryFrom<&str> for Mode {
    type Error = Error;
    fn try_from(s: &str) -> Result<Mode, Self::Error> {
        match s {
            MODE_ARG_ALWAYS_SUCCEED => Ok(Mode::AlwaysSucceed),
            MODE_ARG_ALWAYS_FAIL_AUTHENTICATION => Ok(Mode::AlwaysFailAuthentication),
            s => Err(anyhow!("Unrecognized mode: {}", s)),
        }
    }
}

use std::collections::HashMap;
use std::sync::RwLock;

use super::event::EventCreator;
use super::events::{EventsDiff, Frame};
use super::hashgraph::Hashgraph;
use super::internal_txs::PeerTx;
use super::node::Node;
use super::peer::Peer;
use super::peers::Peers;

service! {
  HgRpc {
    let node: Arc<super::RwLock<super::Node>>;
    let hg: Arc<super::RwLock<super::Hashgraph>>;
    let peers: Arc<super::RwLock<super::Peers>>;

    fn fast_sync(&mut self, peer_id: u64) -> super::Frame {
      self.hg.read().unwrap().get_last_frame(peer_id)
    }

    fn pull(&mut self, known: super::HashMap<super::EventCreator, u64>) -> super::EventsDiff {
      trace!("RPC: Got events to pull {:?}", known);

      self.hg.read().unwrap().events.events_diff(known, 16)
    }

    fn push(&mut self, events: super::EventsDiff) -> bool {
      trace!(
          "RPC: Got events to push {:?}",
          events.diff.iter().fold(0, |c, v| c + v.1.len())
      );

      let peers = self.hg.read().unwrap().get_last_decided_peers();

      let self_id = peers.clone().self_id;
      let peer = peers.clone().get_by_id(events.sender_id);

      let id = if let Some(p) = peer {
        p.id
      } else {
        warn!("UNKNOWN PEER, {:?}", events.sender_id);
        0
      };


      self.hg.write().unwrap().merge_events(self_id, id, events).unwrap();

      true
    }

    // you are asked to add a new peer. Answer with own pub_key
    fn ask_join(&mut self, peer: super::Peer) -> bool{

      if self.hg.read().unwrap().get_last_decided_peers().len() == 1 {
          let mut  hg = self.hg.write().unwrap();

          hg.add_self_event(vec![], vec![super::PeerTx::new_join(peer)]);

          // force consensus
          hg.add_self_event(vec![], vec![]);
          hg.add_self_event(vec![], vec![]);
          hg.add_self_event(vec![], vec![]);
          hg.add_self_event(vec![], vec![]);
          hg.add_self_event(vec![], vec![]);
          hg.add_self_event(vec![], vec![]);

          return true;
      }

      self.node.write().unwrap().peer_join(peer);

      true
    }
  }
}

