                        // mouse click event handler
                        .on_click(move |states, _| {
                            // Calls clear of the state of MainView
                            states.get_mut::<MainViewState>(id).clear();
                            true
                        })
                        .text("Clear")
                        .build(ctx),
                )
                .build(ctx),
        )
    }
}

