#![no_std]
#![no_main]
#![feature(asm)]
#![feature(const_ptr_offset)]

extern crate deimos_stivale2 as stivale2;

use core::panic::PanicInfo;
use stivale2::system_tags::Tag;

stivale2::header! {
    entry_point(main),
    stack_size(4096),
}

#[panic_handler]
fn panic(_info: &PanicInfo) -> ! {
    loop {
        unsafe {
            asm!("hlt");
        }
    }
}

fn main(info: stivale2::SystemInfo) -> ! {
    for tag in info.tags() {
        match tag {
            Tag::Textmode {
                address,
                rows,
                cols,
                bytes_per_char,
            } => {
                let buffer = address as *mut u8;
                for (i, &b) in info
                    .bootloader_brand()
                    .iter()
                    .chain(b" ")
                    .chain(info.bootloader_version())
                    .enumerate()
                {
                    unsafe {
                        *buffer.offset(i as isize * 2) = b;
                        *buffer.offset(i as isize * 2 + 1) = 0xb;
                    }
                }
            }
            _ => {}
        }
    }
    loop {
        unsafe {
            asm!("hlt");
        }
    }
}

