//#![crate_name = "sesstype"]

//! The sesstype crate provides a representation of (multiparty) session types
//! and utilities to construct and manipulate session types in Rust.
//!
//! For a background of *Multiparty Session Types* (MPST),
//! see [Multiparty Asynchronous Session Types]
//! (https://dl.acm.org/citation.cfm?id=2827695) by Honda, Yoshida and Carbone.
//! This implementation of MPST closely follow the syntax defined in
//! [A Linear Decomposition of Multiparty Sessions for Safe Distributed Programming]
//! (http://mrg.doc.ic.ac.uk/publications/a-linear-decomposition-of-multiparty-sessions-for-safe-distributed-programming/)
//! by Scalas et al.

//#[macro_use]
//extern crate nom;

/// The module provides parser for a simple session type language.
///
/// # Grammar
///
/// Two parser functions are provided for *Global Type* and *Local Type*
/// respectively, as with the parent `sesstype` module, both types share
/// common elements `role` and `message`, and the grammars are shown below:
///
/// ## Common
///
/// ```ignore
/// ident   = [A-Za-z][A-Za-z0-9]*
/// role    = ident
/// message = ident payload
/// payload = "()"
///         | "(" ident ")"
/// ```
///
/// ## Global Types
///
/// ```ignore
/// global   = "(" role "->" role ":" interact ")"
///          | recur
///          | typevar
///          | end
/// interact = sendrecv | "{" sendrecv ("," sendrecv)+ "}"
/// sendrecv = message "." global
/// recur    = "*" ident "." global
/// typevar  = ident
/// end      = "end"
/// ```
///
/// ## Local Types
///
/// ```ignore
/// local    = role branch
///          | role select
///          | lrecur
///          | ltypevar
///          | end
/// branch   = recv | "&{" recv ("," recv)+ "}"
/// recv     = "?" message "." local
/// select   = send | "+{" send ("," send)+ "}"
/// send     = "!" message "." local
/// lrecur   = "*" ident "." local
/// ltypevar = ident
/// lend     = "end"
/// ```
///
pub mod parser;

pub mod projection;

use std::cmp::Eq;
use std::hash::{Hash, Hasher};
use std::rc::Rc;
use std::string::ToString;

/// Payload Type carried by a `Message`.
///
/// A `PayloadType` can be one of:
///
/// - base type: `String` symbol that maps to a data type (e.g. `"bool"`, `"int"`)
/// - closed local type: local session type used for session delegation
///
#[derive(Debug)]
pub enum PayloadType {
    BaseType(String), // String symbol that maps to a base type
    Session(Box<local::Type>), // Closed local type
    Empty,
}

impl PartialEq for PayloadType {
    fn eq(&self, other: &PayloadType) -> bool {
        match (self, other) {
            (&PayloadType::Empty,            &PayloadType::Empty)            => true,
            (&PayloadType::BaseType(ref t1), &PayloadType::BaseType(ref t2)) => *t1 == *t2,
            (&PayloadType::Session(ref s1),  &PayloadType::Session(ref s2))  => s1 == s2,
            _ => false,
        }
    }
}

/// A structure to represent a message passed between `Role`s.
///
/// A `Message` consists of a label, and optionally, a `PayloadType`
/// embedded in the `Message`.
/// Note that the *payload types* are not real types but `String`
/// symbols that map to sorts.
///
/// `Message` should never be shared.
///
#[derive(Debug)]
pub struct Message {
    pub label: String, // label of the message, can be empty
    pub payload: PayloadType, // (optional) payload types string
}

impl Message {
    /// Creates a new `Message` with the given label.
    ///
    /// The `Message` created by this method will have an empty `PayloadType`.
    ///
    /// # Example
    ///
    /// ```
    /// use session_types_extension::mpst::Message;
    ///
    /// let _msg = Message::new("label"); // label()
    /// ```
    ///
    pub fn new(label: &str) -> Message {
        Message {
            label: String::from(label),
            payload: PayloadType::Empty,
        }
    }

    /// Returns the label of the `Message`.
    ///
    /// # Example
    ///
    /// ```
    /// use session_types_extension::mpst::Message;
    ///
    /// let msg = Message::new("label"); // label()
    /// let _msg_label = msg.label(); // "label"
    /// ```
    ///
    pub fn label(&self) -> &String {
        &self.label
    }

    /// Creates a `Message` with a base type payload.
    ///
    /// # Example
    ///
    /// ```
    /// use session_types_extension::mpst::Message;
    ///
    /// let _msg = Message::with_payload_type("label", "int"); // label(int)
    /// ```
    ///
    pub fn with_payload_type(label: &str, payload: &str) -> Message {
        Message {
            label: String::from(label),
            payload: PayloadType::BaseType(String::from(payload)),
        }
    }

    /// Creates a `Message` with a session type payload.
    ///
    /// # Example
    ///
    /// ```
    /// use session_types_extension::mpst::Message;
    /// use session_types_extension::mpst::local;
    ///
    /// let _msg = Message::with_payload_session("label", local::Type::end()); // label(end)
    /// ```
    ///
    pub fn with_payload_session(label: &str, payload: Box<local::Type>) -> Message {
        Message {
            label: String::from(label),
            payload: PayloadType::Session(payload),
        }
    }
}

impl Clone for Message {
    /// Clone a Message
    fn clone(&self) -> Message {
        match self.payload {
            PayloadType::BaseType(ref t) => Message {
                label: self.label.clone(),
                payload: PayloadType::BaseType(t.clone()),
            },
            PayloadType::Session(ref s) => Message {
                label: self.label.clone(),
                payload: PayloadType::Session(s.clone()),
            },
            PayloadType::Empty => Message {
                label: self.label.clone(),
                payload: PayloadType::Empty,
            },
        }
    }
}

impl ToString for Message {
    /// Converts `Message` into a human friendly `String` representation.
    ///
    /// The format of the `String` representation is `Label(payload)`
    ///
    fn to_string(&self) -> String {
        let payload = match self.payload {
            PayloadType::BaseType(ref t) => String::from(t.as_str().clone()),
            PayloadType::Session(ref s) => String::from(s.to_string().clone()),
            PayloadType::Empty => String::from(""),
        };

        format!(
            "{label}({payload})",
            label = self.label.clone(),
            payload = payload
        )
    }
}

impl PartialEq for Message {
    fn eq(&self, other: &Message) -> bool {
        self.label == other.label &&
            self.payload == other.payload
    }
}

impl Eq for Message {}

impl Hash for Message {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.label.hash(state);
    }
}

/// A participant of a multiparty session.
///
/// The `Role` type represents an endpoint participant of a multiparty
/// session, and the `name` is used for uniquely identifying the
/// participant within the session.
///
/// Typical usage of a `Role` is to create once in a session, and reuse
/// the same `Role` variable in the session.
///
#[derive(Debug)]
pub struct Role {
    name: String,
}

impl Role {
    /// Creates a new `Role` with the given name.
    ///
    /// The `Role` returned is a reference counted pointer variable,
    /// and within the same session, all references to the `Role`
    /// should use the same variable.
    ///
    /// # Example
    ///
    /// ```
    /// use session_types_extension::mpst::Role;
    ///
    /// let _alice = Role::new("Alice");
    /// ```
    ///
    pub fn new(name: &str) -> Rc<Role> {
        Rc::new(Role { name: name.to_string() })
    }

    /// Returns the name of the `Role`.
    ///
    /// # Example
    ///
    /// ```
    /// use session_types_extension::mpst::Role;
    ///
    /// let alice = Role::new("Alice");
    /// let _alice_name = alice.name();
    /// ```
    ///
    pub fn name(&self) -> &String {
        &self.name
    }
}

impl ToString for Role {
    fn to_string(&self) -> String {
        self.name.clone()
    }
}

/// The module provides types and utilities for working with global session types.
///
pub mod global {
    use std::collections::HashMap;
    use std::rc::Rc;

    /// Global session types.
    ///
    /// > Definition 2.17
    /// >
    /// > G ::= p → q : { lᵢ(Uᵢ).Gᵢ } where i ∈ I
    /// >     | μt.G
    /// >     | t
    /// >     | end
    ///
    #[derive(Debug)]
    pub enum Type {
        /// Interaction Type between two `Role`s.
        ///
        /// > G ::= p → q : { lᵢ(Uᵢ).Gᵢ } where i ∈ I
        ///
        /// `p` and `q` are sender and receiver `Role`s respectively, and
        /// `g` is a mapping from `Message` to continuation `Type`.
        ///
        /// Each map entry represents a `Message` sent by `p` to `q`,
        /// then the interaction proceeds as the continuation `Type`.
        ///
        /// The `Message` should be distinct across in this Interaction Type.
        ///
        Interact {
            p: Rc<super::Role>,
            q: Rc<super::Role>,
            g: HashMap<super::Message, Box<Type>>,
        },

        /// Recursive Type for representing infinite behaviour.
        ///
        /// > G ::= μt.G
        ///
        /// `t` is the type variable for identifying the recursion, and
        /// `g` is the `Type` for the continuation.
        ///
        Recur { t: String, g: Box<Type> },

        /// Type Variable for use with `Recur` to represent infinite behaviour.
        ///
        /// > G ::= t
        ///
        /// `t` is the previously defined type variable in `Recur`.
        ///
        TypeVar { t: String },

        /// Terminated Type with no continuation.
        ///
        /// > G ::= end
        ///
        End,
    }

    impl Type {
        /// Returns a heap-allocated `Type::Interact` with no interactions.
        ///
        /// `p` and `q` are the sender and receiver `Role`s respectively.
        ///
        pub fn interaction(p: &Rc<super::Role>, q: &Rc<super::Role>) -> Box<Type> {
            Box::new(Type::Interact {
                p: p.clone(),
                q: q.clone(),
                g: HashMap::new(),
            })
        }

        /// Adds a message `m_i` (and its continuation `g_i`) to a
        /// `Type::Interact` and returns the updated Interact Type.
        ///
        /// `interact_type` is the input `Type`, if it is not a
        /// `Type::Interact` it is returned unmodified.
        ///
        pub fn add_message(
            interact_type: Box<Type>,
            m_i: super::Message,
            g_i: Box<Type>,
        ) -> Box<Type> {
            let mut m_interact_type = interact_type;
            match *m_interact_type {
                Type::Interact { ref mut g, .. } => {
                    g.insert(m_i, g_i);
                    ()
                }
                _ => (),
            }

            m_interact_type
        }

        /// Returns a heap-allocated `Type::Recur`.
        ///
        /// `name` is the name given to the recursion scope.
        /// `body` is the recursion body.
        ///
        pub fn recur(name: &str, body: Box<Type>) -> Box<Type> {
            Box::new(Type::Recur {
                t: String::from(name),
                g: body,
            })
        }

        /// Returns a heap-allocated `Type::TypeVar`.
        ///
        /// `name` is the (previously defined) name of the recursion scope.
        ///
        pub fn typevar(name: &str) -> Box<Type> {
            Box::new(Type::TypeVar { t: String::from(name) })
        }

        /// Returns a heap-allocated `Type::End`.
        ///
        /// All types should end in an instance of this.
        pub fn end() -> Box<Type> {
            Box::new(Type::End)
        }
    }

    impl ToString for Type {
        fn to_string(&self) -> String {
            match *self {
                Type::Interact {
                    ref p,
                    ref q,
                    ref g,
                } => {
                    let mut interact_str = format!("{} → {}:", p.to_string(), q.to_string());
                    match g.len() {
                        1 => {
                            for (m_i, g_i) in g {
                                interact_str.push_str(&format!(
                                    "{}.{}",
                                    m_i.to_string(),
                                    g_i.to_string()
                                ))
                            }
                        }
                        _ => {
                            interact_str.push_str("{ ");
                            let mut first = true;
                            for (m_i, g_i) in g {
                                if !first {
                                    interact_str.push_str(", ")
                                }
                                interact_str.push_str(&format!(
                                    "{}.{}",
                                    m_i.to_string(),
                                    g_i.to_string()
                                ));
                                first = false
                            }
                            interact_str.push_str(" }");
                        }
                    }

                    interact_str
                }
                Type::Recur { ref t, ref g } => format!("μ{}.{}", t, g.to_string()),
                Type::TypeVar { ref t } => format!("{}", t),
                Type::End => String::from("end"),
            }
        }
    }
}

/// The module provides types and utilities for working with local session types.
///
pub mod local {
    use std::collections::HashMap;
    use std::rc::Rc;

    /// Local session types.
    ///
    /// > Definition 2.5
    /// >
    /// > S ::= p &ᵢ ? lᵢ(Uᵢ).Sᵢ where i ∈ I
    /// >     | p ⊕ᵢ ! lᵢ(Uᵢ).Sᵢ where i ∈ I
    /// >     | μt.S
    /// >     | t
    /// >     | end
    ///
    #[derive(Debug)]
    pub enum Type {
        /// Branching Type receives a `Message` chosen by a `Role`.
        ///
        /// > S ::= p &ᵢ ? lᵢ(Uᵢ).Sᵢ where i ∈ I
        ///
        /// `p` is the receiver `Role`, and `s` is the mapping of
        /// `Message` to continuation `Type` choices.
        ///
        /// Each map entry represents a choice received by `q`, where the
        /// key of `s` (a `Message`) is the message expected, and the value
        /// is the continuation `Type` of the Branching Type.
        ///
        Branch {
            p: Rc<super::Role>,
            s: HashMap<super::Message, Box<Type>>,
        },

        /// Selection Type sends a `Message` chosen by a `Role`.
        ///
        /// > S ::= p ⊕ᵢ ! lᵢ(Uᵢ).Sᵢ where i ∈ I
        ///
        /// `p` is the sender `Role`, and `s` is the mapping of
        /// `Message` to continuation `Type` choices.
        ///
        /// Each map entry represents a choice sent by `p`, where the key of
        /// `s` (a `Message`) is the message to send, and the value is the
        /// continuation `Type` of the Selection Type.
        ///
        Select {
            p: Rc<super::Role>,
            s: HashMap<super::Message, Box<Type>>,
        },

        /// Recursive Type for representing infinite behaviour.
        ///
        /// > S ::= μt.S
        ///
        /// `t` is the type variable for identifying the recursion, and
        /// `s` is the `Type` for the continuation.
        ///
        Recur { t: String, s: Box<Type> },

        /// Type Variable for use with `Recur` to represent infinite behaviour.
        ///
        /// > S ::= t
        ///
        /// `t` is the previously defined type variable in `Recur`.
        ///
        TypeVar { t: String },

        /// Terminated Type with no continuation.
        ///
        /// > G ::= end
        ///
        End,
    }

    impl Type {
        /// Returns a heap-allocated `Type::Branch` with no interactions.
        ///
        /// `p` is the receiver `Role`.
        ///
        pub fn branch(p: &Rc<super::Role>) -> Box<Type> {
            Box::new(Type::Branch {
                p: p.clone(),
                s: HashMap::new(),
            })
        }

        /// Returns a heap-allocated `Type::Select` with no interactions.
        ///
        /// `p` is the sender `Role`.
        ///
        pub fn select(p: &Rc<super::Role>) -> Box<Type> {
            Box::new(Type::Select {
                p: p.clone(),
                s: HashMap::new(),
            })
        }

        /// Adds a message `m_i` (and its continuation `s_i`) to a
        /// `Type::Branch` or `Type::Select` and returns the updated
        /// Branch Type or Select Type respectively.
        ///
        /// `selbr_type` is the input `Type`, if it is not a
        /// `Type::Branch` or `Type::Select` it is returned unmodified.
        ///
        pub fn add_message(
            selbr_type: Box<Type>,
            m_i: super::Message,
            s_i: Box<Type>,
        ) -> Box<Type> {
            let mut m_selbr_type = selbr_type;
            match *m_selbr_type {
                Type::Branch { ref mut s, .. } => {
                    s.insert(m_i, s_i);
                    ()
                }
                Type::Select { ref mut s, .. } => {
                    s.insert(m_i, s_i);
                    ()
                }
                _ => (),
            }

            m_selbr_type
        }

        /// Returns the number of branches/selects
        /// for the Type::Branch/Type::Select.
        ///
        /// Returns 1 for other Type variants (1 continuation).
        ///
        pub fn len(&self) -> usize {
            match *self {
                Type::Branch { ref s, .. } => s.len(),
                Type::Select { ref s, .. } => s.len(),
                _ => 1,
            }

        }

        /// Returns a heap-allocated `Type::Recur`.
        ///
        /// `name` is the name given to the recursion scope.
        /// `body` is the recursion body.
        ///
        pub fn recur(name: &str, body: Box<Type>) -> Box<Type> {
            Box::new(Type::Recur {
                t: String::from(name),
                s: body,
            })
        }

        /// Returns a heap-allocated `Type::TypeVar`.
        ///
        /// `name` is the (previously defined) name of the recursion scope.
        ///
        pub fn typevar(name: &str) -> Box<Type> {
            Box::new(Type::TypeVar { t: String::from(name) })
        }

        /// Returns a heap-allocated `Type::End`.
        ///
        /// All types should end in an instance of this (or TypeVar).
        ///
        pub fn end() -> Box<Type> {
            Box::new(Type::End)
        }

        /// Deep-compares two local types.
        ///
        /// This compare considers two types the same if the role names
        /// (references) are identical, and Type is structurally equivalent.
        ///
        pub fn deep_eq(&self, other: &Type) -> bool {
            match (self, other) {
                (&Type::Branch { p: ref p1, s: ref s1 }, &Type::Branch { p: ref p2, s: ref s2 })
                    => { let mut equal = Rc::ptr_eq(p1, p2);
                         if s1.len() == s2.len() {
                            for (m_i, s_i) in s1 {
                                let mut found = false;
                                for (m2_i, s2_i) in s2 {
                                    if m_i.label() == m2_i.label() && m_i.payload == m2_i.payload {
                                        found = true;
                                        equal = equal && s_i == s2_i;
                                    }
                                }
                                equal = equal && found;
                            }
                         } else {
                             equal = false
                         }
                         equal
                       },
                (&Type::Select { p: ref p1, s: ref s1 }, &Type::Select { p: ref p2, s: ref s2 })
                    => { let mut equal = Rc::ptr_eq(p1, p2);
                         if s1.len() == s2.len() {
                            for (m_i, s_i) in s1 {
                                let mut found = false;
                                for (m2_i, s2_i) in s2 {
                                    if m_i.label() == m2_i.label() && m_i.payload == m2_i.payload {
                                        found = true;
                                        equal = equal && s_i == s2_i;
                                    }
                                }
                                equal = equal && found;
                            }
                         } else {
                             equal = false
                         }
                         equal
                       },
                (&Type::Recur { t: ref t1, s: ref s1 }, &Type::Recur { t: ref t2, s: ref s2 })
                    => *t1 == *t2 && &*s1 == &*s2,
                (&Type::TypeVar { t: ref t1 }, &Type::TypeVar { t: ref t2 })
                    => *t1 == *t2,
                (&Type::End, &Type::End) => true,
                _ => false
            }
        }
    }

    impl Clone for Box<Type> {
        fn clone(&self) -> Box<Type> {
            match **self {
                Type::Branch { ref p, ref s } => {
                    let mut br = Type::branch(p);
                    for (m_i, s_i) in s {
                        br = Type::add_message(br, m_i.clone(), s_i.clone())
                    }
                    br
                }
                Type::Select { ref p, ref s } => {
                    let mut sel = Type::select(p);
                    for (m_i, s_i) in s {
                        sel = Type::add_message(sel, m_i.clone(), s_i.clone())
                    }
                    sel
                }
                Type::Recur { ref t, ref s } => Type::recur(t, s.clone()),
                Type::TypeVar { ref t } => Type::typevar(&t),
                Type::End => Type::end(),
            }
        }
    }

    impl ToString for Type {
        fn to_string(&self) -> String {
            match *self {
                Type::Branch { ref p, ref s } => {
                    let mut branch_str = format!("{}", p.to_string());
                    match s.len() {
                        1 => {
                            for (m_i, s_i) in s {
                                branch_str.push_str(&format!(
                                    "?{}.{}",
                                    m_i.to_string(),
                                    s_i.to_string()
                                ))
                            }
                        }
                        _ => {
                            branch_str.push_str("&{ ");
                            let mut first = true;
                            for (m_i, s_i) in s {
                                if !first {
                                    branch_str.push_str(", ")
                                }
                                branch_str.push_str(&format!(
                                    "?{}.{}",
                                    m_i.to_string(),
                                    s_i.to_string()
                                ));
                                first = false
                            }
                            branch_str.push_str(" }");
                        }
                    };

                    branch_str
                }
                Type::Select { ref p, ref s } => {
                    let mut select_str = format!("{}", p.to_string());
                    match s.len() {
                        1 => {
                            for (m_i, s_i) in s {
                                select_str.push_str(&format!(
                                    "!{}.{}",
                                    m_i.to_string(),
                                    s_i.to_string()
                                ))
                            }
                        }
                        _ => {
                            select_str.push_str("⊕{ ");
                            let mut first = true;
                            for (m_i, s_i) in s {
                                if !first {
                                    select_str.push_str(", ");
                                }
                                select_str.push_str(&format!(
                                    "!{}.{}",
                                    m_i.to_string(),
                                    s_i.to_string()
                                ));
                                first = false
                            }
                            select_str.push_str(" }");
                        }
                    };

                    select_str
                }
                Type::Recur { ref t, ref s } => format!("μ{}.{}", t, s.to_string()),
                Type::TypeVar { ref t } => format!("{}", t),
                Type::End => String::from("end"),
            }
        }
    }

    impl PartialEq for Type {
        /// Returns true if two local::Type are structurally equivalent.
        ///
        /// Roles are considered the same if their String name are equal,
        /// as this is the more common use of equality in this library.
        /// For equality where Roles are identical references, use the
        /// deep_eq() method.
        ///
        fn eq(&self, other: &Type) -> bool {
            match (self, other) {
                (&Type::Branch { p: ref p1, s: ref s1 }, &Type::Branch { p: ref p2, s: ref s2 })
                    => { let mut equal = p1.name() == p2.name();
                         if s1.len() == s2.len() {
                            for (m_i, s_i) in s1 {
                                let mut found = false;
                                for (m2_i, s2_i) in s2 {
                                    if m_i.label() == m2_i.label() && m_i.payload == m2_i.payload {
                                        found = true;
                                        equal = equal && s_i == s2_i;
                                    }
                                }
                                equal = equal && found;
                            }
                         } else {
                             equal = false
                         }
                         equal
                       },
                (&Type::Select { p: ref p1, s: ref s1 }, &Type::Select { p: ref p2, s: ref s2 })
                    => { let mut equal = p1.name() == p2.name();
                         if s1.len() == s2.len() {
                            for (m_i, s_i) in s1 {
                                let mut found = false;
                                for (m2_i, s2_i) in s2 {
                                    if m_i.label() == m2_i.label() && m_i.payload == m2_i.payload {
                                        found = true;
                                        equal = equal && s_i == s2_i;
                                    }
                                }
                                equal = equal && found;
                            }
                         } else {
                             equal = false
                         }
                         equal
                       },
                (&Type::Recur { t: ref t1, s: ref s1 }, &Type::Recur { t: ref t2, s: ref s2 })
                    => *t1 == *t2 && &*s1 == &*s2,
                (&Type::TypeVar { t: ref t1 }, &Type::TypeVar { t: ref t2 })
                    => *t1 == *t2,
                (&Type::End, &Type::End) => true,
                _ => false
            }
        }
    }
}

use crate::math::*;
use crate::texture::Texture;

use image::*;

#[derive(Clone)]
pub struct ImageTexture {
    image: image::DynamicImage,
    width: i32,
    height: i32,
}

impl Texture for ImageTexture {
    fn value(&self, u: f32, v: f32, _p: &Vec3) -> Vec3 {
        let mut i = (u * self.width as f32) as i32;
        let mut j = ((1.0 - v) * self.height as f32 - 0.001) as i32;
        if i < 0 {
            i = 0;
        }
        if j < 0 {
            j = 0;
        }
        if i > self.width - 1 {
            i = self.width - 1;
        }
        if j > self.height - 1 {
            j = self.height - 1;
        }
        let image::Rgba(data) = self.image.get_pixel(i as u32, j as u32);
        let r = data[0] as f32 / 255.0;
        let g = data[1] as f32 / 255.0;
        let b = data[2] as f32 / 255.0;
        vec3(r, g, b)
    }
}

impl ImageTexture {
    pub fn new(img: image::DynamicImage) -> ImageTexture {
        ImageTexture {
            width: img.dimensions().0 as i32,
            height: img.dimensions().1 as i32,
            image: img,
        }
    }
}

use rt::atomic;
use rt::Execution;
use rt::vv::VersionVec;

use std::marker::PhantomData;
use std::ops;
use std::sync::atomic::Ordering;

#[derive(Debug)]
pub struct Object {
    /// Object kind
    kind: Kind,
}

#[derive(Debug)]
pub struct Set {
    objects: Vec<Object>,
}

#[derive(Debug, Copy, Clone, Eq, PartialEq)]
pub struct Id {
    id: usize,
    _p: PhantomData<::std::rc::Rc<()>>,
}

#[derive(Debug, Copy, Clone)]
pub struct Operation {
    object_id: Id,
    action: Action,
}

#[derive(Debug)]
enum Kind {
    Atomic(Atomic),
    Mutex(Option<Access>),
    Condvar(Option<Access>),
    Thread(Option<Access>),
}

#[derive(Debug, Copy, Clone)]
enum Action {
    /// Atomic load
    Load,

    /// Atomic store
    Store,

    /// Atomic read-modify-write
    Rmw,

    Opaque,
}

#[derive(Debug, Default)]
struct Atomic {
    last_load: Option<Access>,
    last_store: Option<Access>,
    history: atomic::History,
}

#[derive(Debug, Clone)]
pub struct Access {
    pub path_id: usize,
    pub dpor_vv: VersionVec,
}

impl Object {
    pub fn atomic() -> Object {
        Object { kind: Kind::Atomic(Atomic::default()) }
    }

    fn atomic_mut(&mut self) -> &mut Atomic {
        match self.kind {
            Kind::Atomic(ref mut v) => v,
            _ => panic!(),
        }
    }

    pub fn mutex() -> Object {
        Object { kind: Kind::Mutex(None) }
    }

    pub fn condvar() -> Object {
        Object { kind: Kind::Condvar(None) }
    }

    pub fn thread() -> Object {
        Object { kind: Kind::Thread(None) }
    }
}

impl Set {
    pub fn new() -> Set {
        Set { objects: vec![] }
    }

    pub fn insert(&mut self, object: Object) -> Id {
        let id = self.objects.len();
        self.objects.push(object);

        Id::from_usize(id)
    }

    pub fn last_dependent_accesses<'a>(&'a self, operation: Operation)
        -> Box<Iterator<Item = &'a Access> + 'a>
    {
        use self::Action::*;

        match self.objects[operation.object_id.as_usize()].kind {
            Kind::Atomic(ref obj) => {
                match operation.action {
                    Load => Box::new(obj.last_store.iter()),
                    Store => Box::new(obj.last_load.iter()),
                    Rmw => Box::new({
                        obj.last_load.iter().chain(
                            obj.last_store.iter())
                    }),
                    _ => panic!(),
                }
            }
            Kind::Mutex(ref obj) => Box::new(obj.iter()),
            Kind::Condvar(ref obj) => Box::new(obj.iter()),
            Kind::Thread(ref obj) => Box::new(obj.iter()),
        }
    }

    pub fn set_last_access(&mut self, operation: Operation, access: Access) {
        use self::Action::*;

        match self.objects[operation.object_id.as_usize()].kind {
            Kind::Atomic(ref mut obj) => {
                match operation.action {
                    Load => obj.last_load = Some(access),
                    Store => obj.last_store = Some(access),
                    Rmw => {
                        obj.last_load = Some(access.clone());
                        obj.last_store = Some(access);
                    }
                    _ => panic!(),
                }
            }
            Kind::Mutex(ref mut obj) => *obj = Some(access),
            Kind::Condvar(ref mut obj) => *obj = Some(access),
            Kind::Thread(ref mut obj) => *obj = Some(access),
        }
    }

    pub fn clear(&mut self) {
        self.objects.clear();
    }
}

impl ops::Index<Id> for Set {
    type Output = Object;

    fn index(&self, index: Id) -> &Self::Output {
        self.objects.index(index.id)
    }
}

impl ops::IndexMut<Id> for Set {
    fn index_mut(&mut self, index: Id) -> &mut Self::Output {
        self.objects.index_mut(index.id)
    }
}

impl Id {
    pub fn from_usize(id: usize) -> Id {
        Id {
            id,
            _p: PhantomData,
        }
    }

    pub fn as_usize(self) -> usize {
        self.id
    }

    pub fn atomic_init(self, execution: &mut Execution) {
        execution.objects[self].atomic_mut()
            .history.init(&mut execution.threads);
    }

    pub fn atomic_load(self, order: Ordering) -> usize {
        super::branch(|execution| {
            self.set_action(execution, Action::Load);
        });

        super::synchronize(|execution| {
            execution.objects[self]
                .atomic_mut()
                .history
                .load(&mut execution.path,
                      &mut execution.threads,
                      order)
        })
    }

    pub fn atomic_store(self, order: Ordering) {
        super::branch(|execution| {
            self.set_action(execution, Action::Store);
        });

        super::synchronize(|execution| {
            execution.objects[self]
                .atomic_mut()
                .history
                .store(&mut execution.threads, order)
        })
    }

    pub fn atomic_rmw<F, E>(self, f: F, success: Ordering, failure: Ordering)
        -> Result<usize, E>
    where
        F: FnOnce(usize) -> Result<(), E>,
    {
        super::branch(|execution| {
            self.set_action(execution, Action::Rmw);
        });

        super::synchronize(|execution| {
            execution.objects[self]
                .atomic_mut()
                .history
                .rmw(
                    f,
                    &mut execution.threads,
                    success,
                    failure)
        })
    }

    /// Assert that the entire atomic history happens before the current thread.
    /// This is required to safely call `get_mut()`.
    pub fn atomic_get_mut(self) {
        super::branch(|execution| {
            self.set_action(execution, Action::Rmw);
        });

        super::execution(|execution| {
            execution.objects[self]
                .atomic_mut()
                .history
                .happens_before(
                    &execution.threads.active().causality);
        });
    }

    pub fn branch_acquire(self, is_locked: bool) {
        super::branch(|execution| {
            self.set_action(execution, Action::Opaque);

            if is_locked {
                // The mutex is currently blocked, cannot make progress
                execution.threads.active_mut().set_blocked();
            }
        })
    }

    pub fn branch(self) {
        super::branch(|execution| {
            self.set_action(execution, Action::Opaque);
        })
    }

    pub fn branch_park(self, seq_cst: bool) {
        super::branch(|execution| {
            self.set_action(execution, Action::Opaque);

            if seq_cst {
                execution.threads.seq_cst();
            }
        })
    }

    pub fn branch_unpark(self, seq_cst: bool) {
        super::branch(|execution| {
            self.set_action(execution, Action::Opaque);

            if seq_cst {
                execution.threads.seq_cst();
            }
        })
    }

    fn set_action(self, execution: &mut Execution, action: Action) {
        execution.threads.active_mut().operation = Some(Operation {
            object_id: self,
            action,
        });
    }
}

impl Operation {
    pub fn object_id(&self) -> Id {
        self.object_id
    }
}

impl Kind {

}

//! # nRF52840 CryptoCell for Psila
//!
//! Functions for using the CryptoCell in the nRF52840 for the security in
//! Psila. This uses the nrf_cc310 library provided by Nordic in their SDK.
//!
//! Note that there is a CCM* implementation in the CC310 library provided by
//! Nordic. But that implementation requires the last byte of the nonce to
//! only indicate the MIC length and encryption. For the usage in Psila this
//! byte contains more bits of information.

#![no_std]

use nrf52840_pac::CRYPTOCELL;
pub use psila_crypto::{
    BlockCipher, CryptoBackend, Error, BLOCK_SIZE, KEY_SIZE, LENGTH_FIELD_LENGTH,
};

fn clear(slice: &mut [u8]) {
    for v in slice.iter_mut() {
        *v = 0;
    }
}

#[derive(Clone, Debug, PartialEq)]
pub enum EncryptDecrypt {
    /// Encryp operation
    Encrypt = 0,
    /// Decryp operation
    Decrypt = 1,
}

/// Block cipher key type
#[derive(Clone, Debug, PartialEq)]
pub enum KeyType {
    /// 128-bit AES key
    Aes128 = 0,
    /// 192-bit AES key
    Aes192 = 1,
    /// 256-bit AES key
    Aes256 = 2,
    /// 512-bit AES key
    Aes512 = 3,
}

/// Block cipher operation mode
#[derive(Clone, Debug, PartialEq)]
pub enum AesOperationMode {
    /// Electronic codebook
    Ecb = 0,
    /// Chiper block chaining
    Cbc = 1,
    /// Chiper block chaining - message authentication code
    CbcMac = 2,
    /// Counter
    Ctr = 3,
    /// Chiper block chaining - message authentication code with extras
    XCbcMac = 4,
    /// Cipher-based message authentication code
    CMac = 5,
    /// XEX with tweak and ciphertext stealing
    Xts = 6,
    /// Chiper block chaining with ciphertext stealing
    CbcCts = 7,
    /// Output feed-back
    Ofb = 8,
}

/// Padding type
#[derive(Clone, Debug, PartialEq)]
pub enum PaddingType {
    /// None, padded with zeroes
    None = 0,
    /// PKCS7 padding
    Pkcs7 = 1,
}

#[repr(C)]
#[derive(Debug, Copy, Clone)]
struct CryptoCellAesContext {
    buff: [u32; 19usize],
}

extern "C" {
    /// Initialize CryptoCell runtime library
    fn SaSi_LibInit() -> u32;
    /// Finalize library operations
    fn SaSi_LibFini();
    /// Initialize AES context
    fn SaSi_AesInit(
        // The context to initalize
        context: *mut CryptoCellAesContext,
        // Encrypt (0) or decrypt (1)
        decrypt: u32,
        // AES operation mode,
        //   0 - ECB
        //   1 - CBC
        //   2 - CBC-MAC
        //   3 - CTR
        //   4 - XCBC-MAC
        //   5 - CMAC
        //   6 - XTS
        //   7 - CBC-CTS
        //   8 - OFB
        operationMode: u32,
        // Padding type, None (0) or PKCS7 (1)
        paddingType: u32,
    ) -> u32;
    /// Set a key for the AES context
    fn SaSi_AesSetKey(
        // AES context
        context: *mut CryptoCellAesContext,
        // Key type used
        //   0 - User key
        //   1 - Platform key
        //   2 - Customer key
        keyType: u32,
        // Pointer to key struct
        keyData: *const cty::c_void,
        // Size of the key struct
        keyDataSize: usize,
    ) -> u32;
    /// Set IV (or counter) for the AES context
    fn SaSi_AesSetIv(context: *mut CryptoCellAesContext, iv: *const u8) -> u32;
    /// Get IV (or counter) for the AES context
    fn SaSi_AesGetIv(context: *mut CryptoCellAesContext, iv: *mut u8) -> u32;
    /// Process a block of data
    fn SaSi_AesBlock(
        // AES context
        context: *mut CryptoCellAesContext,
        // Data to process
        dataIn: *const u8,
        // Size of data to process
        dataInSize: usize,
        // Pointer to output data
        dataOut: *mut u8,
    ) -> u32;
    /// Finalize a cipher operation
    fn SaSi_AesFinish(
        // AES context
        context: *mut CryptoCellAesContext,
        // Size of data to process
        dataInSize: usize,
        // Data to process
        dataIn: *const u8,
        // Size of data buffer provided
        dataInBufferSize: usize,
        // Pointer to output data
        dataOut: *mut u8,
        // Size of output buffer provided
        DataOutBufferSize: *mut usize,
    ) -> u32;
    /// Clean up a AES context
    fn SaSi_AesFree(
        // AES context
        context: *mut CryptoCellAesContext,
    ) -> u32;
}

/// CryptoCell Key Data
#[repr(C)]
#[derive(Debug, Copy, Clone)]
struct KeyData {
    /// Key data
    pub key: *const u8,
    /// Key length
    pub size: usize,
}

/// CryptoCell AES context
pub struct AesContext {
    context: CryptoCellAesContext,
}

impl AesContext {
    pub fn new(encrypt: EncryptDecrypt, mode: AesOperationMode, padding_type: PaddingType) -> Self {
        let mut context = CryptoCellAesContext { buff: [0u32; 19] };
        let ctx_ptr = &mut context as *mut CryptoCellAesContext;
        let result =
            unsafe { SaSi_AesInit(ctx_ptr, encrypt as u32, mode as u32, padding_type as u32) };
        if result != 0 {
            panic!("Failed to initialize AES context {:08x}", result);
        }

        Self { context }
    }

    fn context(&mut self) -> *mut CryptoCellAesContext {
        &mut self.context as *mut CryptoCellAesContext
    }
}

impl BlockCipher for AesContext {
    /// Set the key to be used in the cipher operation
    fn set_key(&mut self, key: &[u8]) -> Result<(), Error> {
        assert!(key.len() == KEY_SIZE);
        let user_key = KeyData {
            key: key.as_ptr(),
            size: key.len(),
        };
        let result = unsafe {
            SaSi_AesSetKey(
                self.context(),
                0, // User key
                &user_key as *const KeyData as *const cty::c_void,
                core::mem::size_of::<KeyData>(),
            )
        };
        if result != 0 {
            return Err(Error::Other(result));
        }
        Ok(())
    }

    /// Set the IV
    fn set_iv(&mut self, iv: &[u8]) -> Result<(), Error> {
        assert!(iv.len() == 16);
        let result = unsafe { SaSi_AesSetIv(self.context(), iv.as_ptr()) };
        if result != 0 {
            return Err(Error::Other(result));
        }
        Ok(())
    }

    /// Get the IV
    fn get_iv(&mut self, iv: &mut [u8]) -> Result<(), Error> {
        assert!(iv.len() == 16);
        let result = unsafe { SaSi_AesGetIv(self.context(), iv.as_mut_ptr()) };
        if result != 0 {
            return Err(Error::Other(result));
        }
        Ok(())
    }

    /// Process a block of data
    fn process_block(&mut self, input: &[u8], output: &mut [u8]) -> Result<(), Error> {
        assert!(input.len() <= output.len());
        assert!(input.len() <= 65535);
        let result = unsafe {
            SaSi_AesBlock(
                self.context(),
                input.as_ptr(),
                input.len(),
                output.as_mut_ptr(),
            )
        };
        if result != 0 {
            return Err(Error::Other(result));
        }
        Ok(())
    }

    /// Finish the cipher operation
    fn finish(&mut self, input: &[u8], output: &mut [u8]) -> Result<(), Error> {
        assert!(input.len() <= output.len());
        let mut output_length = output.len();
        let result = unsafe {
            SaSi_AesFinish(
                self.context(),
                16,
                input.as_ptr(),
                16,
                output.as_mut_ptr(),
                (&mut output_length) as *mut usize,
            )
        };
        if result != 0 {
            return Err(Error::Other(result));
        }
        Ok(())
    }
}

impl core::ops::Drop for AesContext {
    fn drop(&mut self) {
        unsafe { SaSi_AesFree(self.context()) };
    }
}

pub struct CryptoCellBackend {
    cryptocell: CRYPTOCELL,
    cipher: AesContext,
}

impl core::ops::Drop for CryptoCellBackend {
    fn drop(&mut self) {
        unsafe { SaSi_LibFini() }
        self.cryptocell.enable.write(|w| w.enable().clear_bit());
    }
}

const AAD_B0_LEN: usize = BLOCK_SIZE - LENGTH_FIELD_LENGTH;

impl CryptoCellBackend {
    pub fn new(cryptocell: CRYPTOCELL) -> Self {
        cryptocell.enable.write(|w| w.enable().set_bit());

        if unsafe { SaSi_LibInit() } != 0 {
            panic!("Failed to initialize SaSi library");
        }

        let cipher = AesContext::new(
            EncryptDecrypt::Encrypt,
            AesOperationMode::Ecb,
            PaddingType::None,
        );

        Self { cryptocell, cipher }
    }

    /// Create
    fn make_flag(a_length: usize, big_m: usize, big_l: usize) -> u8 {
        let mut flag = if a_length > 0 { 0x40 } else { 0 };
        flag = if big_m > 0 {
            flag | ((((big_m - 2) / 2) as u8) & 0x07) << 3
        } else {
            flag
        };
        flag |= 0x07 & ((big_l - 1) as u8);
        flag
    }
}

impl CryptoBackend for CryptoCellBackend {
    fn ccmstar_decrypt(
        &mut self,
        key: &[u8],
        nonce: &[u8],
        encrypted: &[u8],
        mic: &[u8],
        aad: &[u8],
        decrypted: &mut [u8],
    ) -> Result<usize, Error> {
        assert!(key.len() == KEY_SIZE);
        assert!(nonce.len() == 13);
        assert!(decrypted.len() >= encrypted.len());

        let enc_full_block_length = (encrypted.len() / BLOCK_SIZE) * BLOCK_SIZE;

        let mut tag = [0; BLOCK_SIZE];
        {
            // Decrypt data
            let mut cipher = AesContext::new(
                EncryptDecrypt::Decrypt,
                AesOperationMode::Ctr,
                PaddingType::None,
            );
            cipher.set_key(key)?;

            let mut block = [0u8; BLOCK_SIZE];
            {
                let (flag, other) = block.split_at_mut(1);
                let (_nonce, _counter) = other.split_at_mut(nonce.len());
                flag[0] = Self::make_flag(0, 0, LENGTH_FIELD_LENGTH);
                _nonce.copy_from_slice(&nonce);
            }

            cipher.set_iv(&block)?;

            let mut block = [0u8; BLOCK_SIZE];
            block[..mic.len()].copy_from_slice(&mic);

            cipher.process_block(&block, &mut tag)?;

            if enc_full_block_length > 0 {
                cipher.process_block(&encrypted[..enc_full_block_length], decrypted)?;
            }

            cipher.finish(
                &encrypted[enc_full_block_length..],
                &mut decrypted[enc_full_block_length..],
            )?;
        }
        let mut output = [0u8; BLOCK_SIZE];
        {
            // Validate MIC using AES128-CBC-MAC
            let mut cipher = AesContext::new(
                EncryptDecrypt::Encrypt,
                AesOperationMode::CbcMac,
                PaddingType::None,
            );
            cipher.set_key(key)?;

            let length_field = encrypted.len() as u16;

            let mut block = [0u8; BLOCK_SIZE];
            {
                let (flag, other) = block.split_at_mut(1);
                let (_nonce, length) = other.split_at_mut(nonce.len());
                flag[0] = Self::make_flag(aad.len(), mic.len(), LENGTH_FIELD_LENGTH);
                _nonce.copy_from_slice(&nonce);
                length[0] = (length_field >> 8) as u8;
                length[1] = (length_field & 0x00ff) as u8;
            }

            cipher.process_block(&block, &mut output)?;

            // Feed the additional data
            let mut block = [0u8; BLOCK_SIZE];
            let aad_length = aad.len() as u16;
            block[0] = (aad_length >> 8) as u8;
            block[1] = (aad_length & 0x00ff) as u8;
            let len = if aad.len() < AAD_B0_LEN {
                aad.len()
            } else {
                AAD_B0_LEN
            };
            block[2..2 + len].copy_from_slice(&aad[..len]);

            cipher.process_block(&block, &mut output)?;

            if aad.len() > AAD_B0_LEN {
                let mut iter = aad[AAD_B0_LEN..].chunks_exact(BLOCK_SIZE);
                loop {
                    match iter.next() {
                        Some(input) => {
                            cipher.process_block(input, &mut output)?;
                        }
                        None => {
                            let input = iter.remainder();
                            if !input.is_empty() {
                                let mut block = [0u8; BLOCK_SIZE];
                                block[..input.len()].copy_from_slice(input);
                                cipher.process_block(&block, &mut output)?;
                            }
                            break;
                        }
                    }
                }
            }

            let block_last = ((encrypted.len() + (BLOCK_SIZE - 1)) / BLOCK_SIZE) - 1;
            let mut block_index = 0;
            let mut iter = decrypted[..encrypted.len()].chunks_exact(BLOCK_SIZE);
            loop {
                match iter.next() {
                    Some(input) => {
                        if block_index < block_last {
                            cipher.process_block(input, &mut output)?;
                        } else {
                            cipher.finish(input, &mut output)?;
                        }
                    }
                    None => {
                        let mut block = [0u8; BLOCK_SIZE];
                        let input = iter.remainder();
                        block[..input.len()].copy_from_slice(input);
                        // Must feed a full block into finish here, otherwise the
                        // result will be wrong
                        cipher.finish(&block, &mut output)?;
                        break;
                    }
                }
                block_index += 1;
            }
        }

        let mut valid = true;
        for (a, b) in tag[..mic.len()].iter().zip(output[..mic.len()].iter()) {
            if a != b {
                valid = false;
                break;
            }
        }

        if valid {
            Ok(encrypted.len())
        } else {
            clear(decrypted);
            Ok(0)
        }
    }

    fn ccmstar_encrypt(
        &mut self,
        key: &[u8],
        nonce: &[u8],
        message: &[u8],
        mic: &mut [u8],
        aad: &[u8],
        output: &mut [u8],
    ) -> Result<usize, psila_crypto::Error> {
        let mut new_mic = [0u8; BLOCK_SIZE];
        let mut buffer = [0u8; 128];
        // Generate a MIC
        {
            let aad_blocks = (aad.len() + LENGTH_FIELD_LENGTH + (BLOCK_SIZE - 1)) / BLOCK_SIZE;
            let mut offset = 0;

            buffer[0] = Self::make_flag(aad.len(), mic.len(), LENGTH_FIELD_LENGTH);
            offset += 1;
            buffer[offset..offset + nonce.len()].copy_from_slice(nonce);
            offset += nonce.len();
            let message_len = message.len() as u16;
            buffer[offset] = (message_len >> 8) as u8;
            buffer[offset + 1] = (message_len & 0x00ff) as u8;
            offset += 2;
            let aad_len = aad.len() as u16;
            buffer[offset] = (aad_len >> 8) as u8;
            buffer[offset + 1] = (aad_len & 0x00ff) as u8;
            offset += 2;
            buffer[offset..offset + aad.len()].copy_from_slice(aad);
            offset += (aad_blocks * BLOCK_SIZE) - 2;
            buffer[offset..offset + message.len()].copy_from_slice(message);
            offset += message.len();

            let mut cipher = AesContext::new(
                EncryptDecrypt::Encrypt,
                AesOperationMode::CbcMac,
                PaddingType::None,
            );
            cipher.set_key(key)?;

            let block_last = ((offset + (BLOCK_SIZE - 1)) / BLOCK_SIZE) - 1;
            let mut block_index = 0;
            let mut iter = buffer[..offset].chunks_exact(BLOCK_SIZE);
            loop {
                match iter.next() {
                    Some(input) => {
                        if block_index < block_last {
                            cipher.process_block(&input, &mut new_mic)?;
                        } else {
                            cipher.finish(&input, &mut new_mic)?;
                            break;
                        }
                    }
                    None => {
                        let mut block = [0u8; BLOCK_SIZE];
                        block[..iter.remainder().len()].copy_from_slice(iter.remainder());
                        cipher.finish(&block, &mut new_mic)?;
                        break;
                    }
                }
                block_index += 1;
            }
        }
        clear(&mut buffer[..]);
        {
            let message_blocks = (message.len() + (BLOCK_SIZE - 1)) / BLOCK_SIZE;
            let mut offset = 0;

            buffer[..message.len()].copy_from_slice(message);
            offset += message_blocks * BLOCK_SIZE;

            let mut block = [0u8; BLOCK_SIZE];
            block[0] = Self::make_flag(0, 0, LENGTH_FIELD_LENGTH);
            block[1..=nonce.len()].copy_from_slice(nonce);

            let mut cipher = AesContext::new(
                EncryptDecrypt::Encrypt,
                AesOperationMode::Ctr,
                PaddingType::None,
            );
            cipher.set_key(key)?;
            cipher.set_iv(&block)?;

            let mut block = [0u8; BLOCK_SIZE];
            let mut tag = [0u8; 16];
            block[..mic.len()].copy_from_slice(&new_mic[..mic.len()]);
            cipher.process_block(&block, &mut tag)?;

            for (o, i) in output[..offset]
                .chunks_mut(BLOCK_SIZE)
                .zip(buffer.chunks(BLOCK_SIZE))
            {
                cipher.process_block(i, o)?;
            }

            mic.copy_from_slice(&tag[..mic.len()]);
        }

        Ok(message.len())
    }

    /// Set the key
    fn aes128_ecb_encrypt_set_key(&mut self, key: &[u8]) -> Result<(), Error> {
        self.cipher.set_key(key)
    }
    /// Process blocks of data
    fn aes128_ecb_encrypt_process_block(
        &mut self,
        input: &[u8],
        output: &mut [u8],
    ) -> Result<(), Error> {
        self.cipher.process_block(input, output)
    }
    /// Process the last bits and bobs and finish
    fn aes128_ecb_encrypt_finish(&mut self, input: &[u8], output: &mut [u8]) -> Result<(), Error> {
        self.cipher.finish(input, output)
    }
}

use crate::{sys, usr};
use crate::api::fs;
use crate::api::console::Style;
use crate::api::io;
use alloc::format;
use alloc::string::{String, ToString};
use alloc::vec::Vec;
use core::cmp;

pub fn main(args: &[&str]) -> usr::shell::ExitCode {
    if args.len() != 2 {
        return usr::shell::ExitCode::CommandError;
    }

    let pathname = args[1];
    let mut editor = Editor::new(pathname);
    editor.run()
}

struct EditorConfig {
    tab_size: usize,
}

pub struct Editor {
    pathname: String,
    lines: Vec<String>,
    x: usize,
    y: usize,
    dx: usize, // Horizontal offset from the start
    dy: usize, // Vertical offset from the top
    config: EditorConfig,
}

impl Editor {
    pub fn new(pathname: &str) -> Self {
        let x = 0;
        let y = 0;
        let dx = 0;
        let dy = 0;
        let mut lines = Vec::new();
        let config = EditorConfig { tab_size: 4 };

        match fs::read_to_string(pathname) {
            Ok(contents) => {
                for line in contents.split('\n') {
                    lines.push(line.into());
                }
            },
            Err(_) => {
                lines.push(String::new());
            }
        };

        let pathname = pathname.into();

        Self { pathname, lines, x, y, dx, dy, config }
    }

    pub fn save(&mut self) -> usr::shell::ExitCode {
        let mut contents = String::new();
        let n = self.lines.len();
        for i in 0..n {
            contents.push_str(&self.lines[i]);
            if i < n - 1 {
                contents.push('\n');
            }
        }

        if fs::write(&self.pathname, contents.as_bytes()).is_ok() {
            let status = format!("Wrote {}L to '{}'", n, self.pathname);
            self.print_status(&status, "Yellow");
            usr::shell::ExitCode::CommandSuccessful
        } else {
            let status = format!("Could not write to '{}'", self.pathname);
            self.print_status(&status, "LightRed");
            usr::shell::ExitCode::CommandError
        }
    }

    fn print_status(&mut self, status: &str, background: &str) {
        let color = Style::color("Black").with_background(background);
        let reset = Style::reset();
        print!("\x1b[{};1H", self.rows() + 1); // Move cursor to the bottom of the screen
        print!("{}{:cols$}{}", color, status, reset, cols = self.cols());
        //print!("\x1b[{};{}H", self.y + 1, self.x + 1); // Move cursor back
    }

    fn print_editing_status(&mut self) {
        let max = 50;
        let mut path = self.pathname.clone();
        if self.pathname.len() > max {
            path.truncate(max - 3);
            path.push_str("...");
        }
        let start = format!("Editing '{}'", path);

        let x = self.dx + self.x + 1;
        let y = self.dy + self.y + 1;
        let n = y * 100 / self.lines.len();
        let end = format!("{},{} {:3}%", y, x, n);

        let width = self.cols() - start.len();
        let status = format!("{}{:>width$}", start, end, width = width);

        self.print_status(&status, "LightGray");
    }

    fn print_screen(&mut self) {
        let mut rows: Vec<String> = Vec::new();
        let a = self.dy;
        let b = self.dy + self.rows();
        for y in a..b {
            rows.push(self.render_line(y));
        }
        println!("\x1b[1;1H{}", rows.join("\n"));
    }

    fn render_line(&self, y: usize) -> String {
        // Render line into a row of the screen, or an empty row when past eof
        let line = if y < self.lines.len() { &self.lines[y] } else { "" };

        let mut row = format!("{:cols$}", line, cols = self.dx);
        let n = self.dx + self.cols();
        if row.len() > n {
            row.truncate(n - 1);
            row.push_str(&truncated_line_indicator());
        } else {
            row.push_str(&" ".repeat(n - row.len()));
        }
        row[self.dx..].to_string()
    }

    fn render_char(&self, c: char) -> Option<String> {
        match c {
            '!'..='~' => Some(c.to_string()), // graphic char
            ' '       => Some(" ".to_string()),
            '\t'      => Some(" ".repeat(self.config.tab_size)),
            _         => None,
        }
    }

    pub fn run(&mut self) -> usr::shell::ExitCode {
        print!("\x1b[2J\x1b[1;1H"); // Clear screen and move cursor to top
        self.print_screen();
        self.print_editing_status();
        print!("\x1b[1;1H"); // Move cursor to the top of the screen

        let mut escape = false;
        let mut csi = false;
        loop {
            let c = io::stdin().read_char().unwrap_or('\0');
            print!("\x1b[?25l"); // Disable cursor
            match c {
                '\x1B' => { // ESC
                    escape = true;
                    continue;
                },
                '[' if escape => {
                    csi = true;
                    continue;
                },
                '\0' => {
                    continue;
                }
                '\x11' => { // Ctrl Q
                    // TODO: Warn if modifications have not been saved
                    print!("\x1b[2J\x1b[1;1H"); // Clear screen and move cursor to top
                    print!("\x1b[?25h"); // Enable cursor
                    break;
                },
                '\x17' => { // Ctrl W
                    self.save();
                    print!("\x1b[?25h"); // Enable cursor
                    continue;
                },
                '\x18' => { // Ctrl X
                    let res = self.save();
                    print!("\x1b[2J\x1b[1;1H"); // Clear screen and move cursor to top
                    print!("\x1b[?25h"); // Enable cursor
                    return res;
                },
                '\n' => { // Newline
                    let line = self.lines[self.dy + self.y].split_off(self.dx + self.x);
                    self.lines.insert(self.dy + self.y + 1, line);
                    if self.y == self.rows() - 1 {
                        self.dy += 1;
                    } else {
                        self.y += 1;
                    }
                    self.x = 0;
                    self.dx = 0;
                    self.print_screen();
                },
                'A' if csi => { // Arrow up
                    if self.y > 0 {
                        self.y -= 1
                    } else if self.dy > 0 {
                        self.dy -= 1;
                        self.print_screen();
                    }
                    self.x = self.next_pos(self.x, self.y);
                },
                'B' if csi => { // Arrow down
                    let is_eof = self.dy + self.y == self.lines.len() - 1;
                    let is_bottom = self.y == self.rows() - 1;
                    if self.y < cmp::min(self.rows(), self.lines.len() - 1) {
                        if is_bottom || is_eof {
                            if !is_eof {
                                self.dy += 1;
                                self.print_screen();
                            }
                        } else {
                            self.y += 1;
                        }
                        self.x = self.next_pos(self.x, self.y);
                    }
                },
                'C' if csi => { // Arrow right
                    let line = &self.lines[self.dy + self.y];
                    if line.is_empty() || self.x + self.dx >= line.len() {
                        print!("\x1b[?25h"); // Enable cursor
                        continue
                    } else if self.x == self.cols() - 1 {
                        self.x = self.dx;
                        self.dx += self.cols();
                        self.print_screen();
                    } else {
                        self.x += 1;
                    }
                },
                'D' if csi => { // Arrow left
                    if self.x + self.dx == 0 {
                        print!("\x1b[?25h"); // Enable cursor
                        continue;
                    } else if self.x == 0 {
                        self.x = self.dx - 1;
                        self.dx -= self.cols();
                        self.print_screen();
                        self.x = self.next_pos(self.x, self.y);
                    } else {
                        self.x -= 1;
                    }
                },
                '\x14' => { // Ctrl T -> Go to top of file
                    self.x = 0;
                    self.y = 0;
                    self.dx = 0;
                    self.dy = 0;
                    self.print_screen();
                },
                '\x02' => { // Ctrl B -> Go to bottom of file
                    self.x = 0;
                    self.y = cmp::min(self.rows(), self.lines.len()) - 1;
                    self.dx = 0;
                    self.dy = self.lines.len() - 1 - self.y;
                    self.print_screen();
                },
                '\x01' => { // Ctrl A -> Go to beginning of line
                    self.x = 0;
                    self.dx = 0;
                    self.print_screen();
                },
                '\x05' => { // Ctrl E -> Go to end of line
                    let n = self.lines[self.dy + self.y].len();
                    let w = self.cols();
                    self.x = n % w;
                    self.dx = w * (n / w);
                    self.print_screen();
                },
                '\x08' => { // Backspace
                    if self.dx + self.x > 0 { // Remove char from line
                        self.lines[self.dy + self.y].remove(self.dx + self.x - 1);
                        if self.x == 0 {
                            self.dx -= self.cols();
                            self.x = self.cols() - 1;
                            self.print_screen();
                        } else {
                            self.x -= 1;
                            let line = self.render_line(self.dy + self.y);
                            print!("\x1b[2K\x1b[1G{}", line);
                        }
                    } else { // Remove newline from previous line
                        if self.y == 0 && self.dy == 0 {
                            print!("\x1b[?25h"); // Enable cursor
                            continue;
                        }

                        // Move cursor below the end of the previous line
                        let n = self.lines[self.dy + self.y - 1].len();
                        let w = self.cols();
                        self.x = n % w;
                        self.dx = w * (n / w);

                        // Move line to the end of the previous line
                        let line = self.lines.remove(self.dy + self.y);
                        self.lines[self.dy + self.y - 1].push_str(&line);

                        // Move cursor up to the previous line
                        if self.y > 0 {
                            self.y -= 1;
                        } else {
                            self.dy -= 1;
                        }

                        self.print_screen();
                    }
                },
                '\x7f' => { // Delete
                    let n = self.lines[self.dy + self.y].len();
                    if self.dx + self.x >= n { // Remove newline from line
                        let line = self.lines.remove(self.dy + self.y + 1);
                        self.lines[self.dy + self.y].push_str(&line);
                        self.print_screen();
                    } else { // Remove char from line
                        self.lines[self.dy + self.y].remove(self.dx + self.x);
                        let line = self.render_line(self.dy + self.y);
                        print!("\x1b[2K\x1b[1G{}", line);
                    }
                },
                c => {
                    if let Some(s) = self.render_char(c) {
                        self.lines[self.dy + self.y].insert_str(self.dx + self.x, &s);
                        self.x += s.len();
                        if self.x >= self.cols() {
                            self.dx += self.cols();
                            self.x -= self.cols();
                            self.print_screen();
                        } else {
                            let line = self.render_line(self.dy + self.y);
                            print!("\x1b[2K\x1b[1G{}", line);
                        }
                    }
                },
            }
            escape = false;
            csi = false;
            self.print_editing_status();
            print!("\x1b[{};{}H", self.y + 1, self.x + 1);
            print!("\x1b[?25h"); // Enable cursor
        }
        usr::shell::ExitCode::CommandSuccessful
    }

    // Move cursor past end of line to end of line or left of the screen
    fn next_pos(&self, x: usize, y: usize) -> usize {
        let eol = self.lines[self.dy + y].len();
        if eol <= self.dx + x {
            if eol <= self.dx {
                0
            } else {
                eol - 1
            }
        } else {
            x
        }
    }

    fn rows(&self) -> usize {
        sys::console::rows() - 1 // Leave out one line for status line
    }

    fn cols(&self) -> usize {
        sys::console::cols()
    }
}

fn truncated_line_indicator() -> String {
    let color = Style::color("Black").with_background("LightGray");
    let reset = Style::reset();
    format!("{}>{}", color, reset)
}

