//! Types for the `m.key.verification.ready` event.

use ruma_events_macros::EventContent;
use ruma_identifiers::DeviceId;
use serde::{Deserialize, Serialize};

use super::{Relation, VerificationMethod};

/// The content of a to-device `m.m.key.verification.ready` event.
///
/// Response to a previously sent `m.key.verification.request` message.
#[derive(Clone, Debug, Deserialize, Serialize, EventContent)]
#[cfg_attr(not(feature = "unstable-exhaustive-types"), non_exhaustive)]
#[ruma_event(type = "m.key.verification.ready", kind = ToDevice)]
pub struct ToDeviceKeyVerificationReadyEventContent {
    /// The device ID which is initiating the request.
    pub from_device: Box<DeviceId>,

    /// The verification methods supported by the sender.
    pub methods: Vec<VerificationMethod>,

    /// An opaque identifier for the verification process.
    ///
    /// Must be unique with respect to the devices involved. Must be the same as the
    /// `transaction_id` given in the `m.key.verification.request` from a
    /// request.
    pub transaction_id: String,
}

impl ToDeviceKeyVerificationReadyEventContent {
    /// Creates a new `ToDeviceKeyVerificationReadyEventContent` with the given device ID,
    /// verification methods and transaction ID.
    pub fn new(
        from_device: Box<DeviceId>,
        methods: Vec<VerificationMethod>,
        transaction_id: String,
    ) -> Self {
        Self { from_device, methods, transaction_id }
    }
}

/// The content of an in-room `m.m.key.verification.ready` event.
///
/// Response to a previously sent `m.key.verification.request` message.
#[derive(Clone, Debug, Deserialize, Serialize, EventContent)]
#[cfg_attr(not(feature = "unstable-exhaustive-types"), non_exhaustive)]
#[ruma_event(type = "m.key.verification.ready", kind = Message)]
pub struct KeyVerificationReadyEventContent {
    /// The device ID which is initiating the request.
    pub from_device: Box<DeviceId>,

    /// The verification methods supported by the sender.
    pub methods: Vec<VerificationMethod>,

    /// Relation signaling which verification request this event is responding
    /// to.
    #[serde(rename = "m.relates_to")]
    pub relates_to: Relation,
}

impl KeyVerificationReadyEventContent {
    /// Creates a new `KeyVerificationReadyEventContent` with the given device ID, methods and
    /// relation.
    pub fn new(
        from_device: Box<DeviceId>,
        methods: Vec<VerificationMethod>,
        relates_to: Relation,
    ) -> Self {
        Self { from_device, methods, relates_to }
    }
}

#[cfg(test)]
mod tests {
    use matches::assert_matches;
    use ruma_identifiers::{event_id, DeviceId};
    use serde_json::{from_value as from_json_value, json, to_value as to_json_value};

    use super::{KeyVerificationReadyEventContent, ToDeviceKeyVerificationReadyEventContent};
    use crate::key::verification::{Relation, VerificationMethod};

    #[test]
    fn serialization() {
        let event_id = event_id!("$1598361704261elfgc:localhost").to_owned();
        let device: Box<DeviceId> = "123".into();

        let json_data = json!({
            "from_device": device,
            "methods": ["m.sas.v1"],
            "m.relates_to": {
                "rel_type": "m.reference",
                "event_id": event_id,
            }
        });

        let content = KeyVerificationReadyEventContent {
            from_device: device.clone(),
            relates_to: Relation { event_id },
            methods: vec![VerificationMethod::SasV1],
        };

        assert_eq!(to_json_value(&content).unwrap(), json_data);

        let json_data = json!({
            "from_device": device,
            "methods": ["m.sas.v1"],
            "transaction_id": "456",
        });

        let content = ToDeviceKeyVerificationReadyEventContent {
            from_device: device,
            transaction_id: "456".to_owned(),
            methods: vec![VerificationMethod::SasV1],
        };

        assert_eq!(to_json_value(&content).unwrap(), json_data);
    }

    #[test]
    fn deserialization() {
        let id = event_id!("$1598361704261elfgc:localhost");
        let device: Box<DeviceId> = "123".into();

        let json_data = json!({
            "from_device": device,
            "methods": ["m.sas.v1"],
            "m.relates_to": {
                "rel_type": "m.reference",
                "event_id": id,
            }
        });

        assert_matches!(
            from_json_value::<KeyVerificationReadyEventContent>(json_data).unwrap(),
            KeyVerificationReadyEventContent {
                from_device,
                relates_to: Relation {
                    event_id
                },
                methods,
            } if from_device == device
                && methods == vec![VerificationMethod::SasV1]
                && event_id == id
        );

        let json_data = json!({
            "from_device": device,
            "methods": ["m.sas.v1"],
            "transaction_id": "456",
        });

        assert_matches!(
            from_json_value::<ToDeviceKeyVerificationReadyEventContent>(json_data).unwrap(),
            ToDeviceKeyVerificationReadyEventContent {
                from_device,
                transaction_id,
                methods,
            } if from_device == device
                && methods == vec![VerificationMethod::SasV1]
                && transaction_id == "456"
        );
    }
}

use std::sync::{mpsc, Arc};
use std::thread;
use std::time::Duration;

use chrono::Utc;
use futures::executor::ThreadPool;
use serde::Deserialize;
use serde_json::{json, Value as JsonValue};
use svc_agent::{
    mqtt::{
        AgentBuilder, AgentNotification, ConnectionMode, IncomingMessage, IncomingResponse,
        OutgoingMessage, OutgoingRequest, OutgoingRequestProperties, QoS,
        ShortTermTimingProperties, SubscriptionTopic,
    },
    request::Dispatcher,
    AccountId, AgentId, Subscription,
};

mod helpers;

const API_VERSION: &str = "v1";

#[derive(Deserialize)]
struct PingResponse {
    message: String,
}

#[test]
fn request_dispatcher() {
    // Thread pool for futures.
    let pool = ThreadPool::new().expect("Failed to build thread pool");

    // Start service.
    let (init_tx, init_rx) = mpsc::channel::<()>();
    thread::spawn(move || helpers::ping_service::run(init_tx));

    init_rx
        .recv_timeout(Duration::from_secs(5))
        .expect("Failed to init");

    // Create client agent.
    let account_id = AccountId::new("ping-client", "test.usr.example.org");
    let agent_id = AgentId::new("test", account_id);

    let builder =
        AgentBuilder::new(agent_id.clone(), API_VERSION).connection_mode(ConnectionMode::Service);

    let (mut agent, rx) = builder
        .start(&helpers::build_agent_config())
        .expect("Failed to start ping client");

    // Subscribe to the unicast responses topic.
    let service_account_id = AccountId::new("ping-service", "test.svc.example.org");
    let subscription = Subscription::unicast_responses_from(&service_account_id);

    agent
        .subscribe(&subscription, QoS::AtLeastOnce, None)
        .expect("Error subscribing to unicast responses");

    match rx.recv_timeout(Duration::from_secs(5)) {
            Ok(AgentNotification::Connack(_)) => (),
            Ok(other) => panic!("Expected to receive connack notification, got {:?}", other),
            Err(err) => panic!("Failed to receive connack notification: {}", err),
    }

    match rx.recv_timeout(Duration::from_secs(5)) {
        Ok(AgentNotification::Suback(_)) => (),
        Ok(other) => panic!("Expected to receive suback notification, got {:?}", other),
        Err(err) => panic!("Failed to receive suback notification: {}", err),
    }

    // Create request dispatcher.
    let dispatcher = Arc::new(Dispatcher::new(&agent));
    let dispatcher_clone = dispatcher.clone();

    // ASynchronous message handling loop.
    pool.spawn_ok(async move {
        while let Ok(AgentNotification::Message(Ok(IncomingMessage::Response(resp)), _)) = rx.recv() {
            // Handle response.
            let message =
                IncomingResponse::convert::<JsonValue>(resp).expect("Couldnt convert message");

            dispatcher_clone
                .response(message)
                .await
                .expect("Failed to dispatch response")
        }
    });

    // Go async to be able to `.await` and publish two requests.
    let (resp_tx, resp_rx) = mpsc::channel::<()>();

    let response_topic = subscription
        .subscription_topic(&agent_id, API_VERSION)
        .expect("Failed to build response topic");

    pool.spawn_ok(async move {
        // The first request is to ensure that the dispatcher is able to handle multiple requests.
        let _future1 = publish_request(&dispatcher, &service_account_id, &response_topic, "req1");
        let future2 = publish_request(&dispatcher, &service_account_id, &response_topic, "req2");
        let response = future2.await;

        assert_eq!(response.payload().message, "pong");
        assert_eq!(response.properties().correlation_data(), "req2");

        // Notify the main thread that we're done.
        resp_tx
            .send(())
            .expect("Failed to notify about received response");
    });

    // Block to synchronize with the above async part.
    resp_rx
        .recv_timeout(Duration::from_secs(5))
        .expect("Failed to await response");
}

async fn publish_request(
    dispatcher: &Dispatcher,
    to: &AccountId,
    response_topic: &str,
    correlation_data: &str,
) -> IncomingResponse<PingResponse> {
    // Build request.
    let reqp = OutgoingRequestProperties::new(
        "ping",
        response_topic,
        correlation_data,
        ShortTermTimingProperties::new(Utc::now()),
    );

    let payload = json!({"message": "ping"});
    let msg = OutgoingRequest::multicast(payload, reqp, to, "v1");

    match msg {
        OutgoingMessage::Request(request) => {
            // Send request and wait for the response.
            dispatcher
                .request(request)
                .await
                .expect("Failed to dispatch request")
        }
        _ => panic!("wrong message type"),
    }
}

use helpers::HashSet;

pub fn p1(s: &str) -> u32 {
  seat_ids(s).max().unwrap()
}

pub fn p2(s: &str) -> u32 {
  let all_ids: HashSet<_> = seat_ids(s).collect();
  let max_possible = seat_id(Seat {
    row: MAX_ROW,
    col: MAX_COL,
  });
  for id in 0..=max_possible {
    if all_ids.contains(&id) {
      continue;
    }
    let id_less_1 = match id.checked_sub(1) {
      None => continue,
      Some(x) => x,
    };
    if all_ids.contains(&id_less_1) && all_ids.contains(&(id + 1)) {
      return id;
    }
  }
  panic!("no solution")
}

fn seat_ids(s: &str) -> impl Iterator<Item = u32> + '_ {
  s.lines().map(|s| seat_id(parse_seat(s)))
}

const MAX_ROW: u32 = 127;
const MAX_COL: u32 = 7;

struct Seat {
  row: u32,
  col: u32,
}

fn parse_seat(s: &str) -> Seat {
  let bs = s.as_bytes();
  let mut idx = 0;
  let mut lo = 0;
  let mut hi = MAX_ROW;
  for _ in 0..7 {
    let mid = (lo + hi) / 2;
    match bs[idx] {
      b'F' => hi = mid,
      b'B' => lo = mid + 1,
      seat => panic!("bad seat: {}", seat),
    }
    idx += 1;
  }
  assert_eq!(lo, hi);
  let row = lo;
  lo = 0;
  hi = MAX_COL;
  for _ in 0..3 {
    let mid = (lo + hi) / 2;
    match bs[idx] {
      b'L' => hi = mid,
      b'R' => lo = mid + 1,
      seat => panic!("bad seat: {}", seat),
    }
    idx += 1;
  }
  assert_eq!(lo, hi);
  Seat { row, col: lo }
}

fn seat_id(s: Seat) -> u32 {
  s.row * (MAX_COL + 1) + s.col
}

#[test]
fn t() {
  let s = include_str!("input/d05.txt");
  assert_eq!(p1(s), 861);
  assert_eq!(p2(s), 633);
}

