///Allocated virtual memory space by pages. returns some vaddr.
pub trait MemorySpaceManager {
    fn new() -> Self;
    fn alloc(&mut self, size: usize) -> Option<(usize, usize)>;
    fn free(&mut self, target: (usize, usize));
    fn kernel_table(&self) -> ManuallyDrop<PageTableImpl> {
        // Only one process can change the kernel table at a time.
        // If you want to change the mapping item, you have to lock the MemorySpaceManager.
        unsafe { PageTableImpl::kernel_table() }
    }
}

/// The most simple strategy: no free and allocate ahead.
/// TODO: A better allocation strategy required.
pub struct LinearManager {
    last_page: usize,
}
use crate::arch::consts::KSEG2_START;

impl MemorySpaceManager for LinearManager {
    fn new() -> LinearManager {
        LinearManager { last_page: 0 }
    }
    fn alloc(&mut self, size: usize) -> Option<(usize, usize)> {
        let mut required_pages = (size + PAGE_SIZE - 1) / PAGE_SIZE;

        let current = self.last_page * PAGE_SIZE + KSEG2_START;
        self.last_page += required_pages;
        Some((current, required_pages * PAGE_SIZE))
    }

    fn free(&mut self, (addr, size): (usize, usize)) {
        //Do nothing.
    }
}

type VirtualMemorySpaceManager = LinearManager;
type LockedVMM = Mutex<VirtualMemorySpaceManager>;
lazy_static! {
    pub static ref KERNELVM_MANAGER: LockedVMM = Mutex::new(VirtualMemorySpaceManager::new());
}

/// Represents a contiguous virtual area: like the ancient const_reloc.
/// Use RAII for exception handling
pub struct VirtualSpace {
    start: usize,
    size: usize,
    areas: Vec<VirtualArea>,
    allocator: &'static LockedVMM,
    page_allocator: ByFrame<GlobalFrameAlloc>,
}

impl VirtualSpace {
    pub fn new(allocator: &'static LockedVMM, size: usize) -> Option<VirtualSpace> {
        let mut vmm = allocator.lock();
        let (start, rsize) = vmm.alloc(size)?;
        Some(VirtualSpace {
            start: start,
            size: rsize,
            areas: Vec::new(),
            allocator: allocator,
            page_allocator: ByFrame::new(GlobalFrameAlloc),
        })
    }
    pub fn start(&self) -> usize {
        self.start
    }
    pub fn size(&self) -> usize {
        self.size
    }

    pub fn add_area(
        &mut self,
        start_addr: usize,
        end_addr: usize,
        attr: &MemoryAttr,
    ) -> &VirtualArea {
        let area = VirtualArea::new(start_addr, end_addr - start_addr, attr, self);
        self.areas.push(area);
        self.areas.last().unwrap()
    }
}

impl Drop for VirtualSpace {
    fn drop(&mut self) {
        for mut v in self.areas.iter_mut() {
            v.unmap(self.allocator, &mut self.page_allocator);
        }
    }
}

pub struct VirtualArea {
    start: usize,
    end: usize,
    attr: MemoryAttr,
}

impl VirtualArea {
    pub fn new(
        page_addr: usize,
        size: usize,
        attr: &MemoryAttr,
        parent: &mut VirtualSpace,
    ) -> VirtualArea {
        let aligned_start_addr = page_addr - page_addr % PAGE_SIZE;
        let mut aligned_end = (page_addr + size + PAGE_SIZE - 1);
        aligned_end = aligned_end - aligned_end % PAGE_SIZE;
        let lock = parent.allocator.lock();
        let mut active_pt = lock.kernel_table();
        for p in Page::range_of(aligned_start_addr, aligned_end) {
            parent
                .page_allocator
                .map(active_pt.deref_mut(), p.start_address(), attr);
        }

        VirtualArea {
            start: aligned_start_addr,
            end: aligned_end,
            attr: attr.clone(),
        }
    }
    pub fn unmap(&mut self, allocator: &LockedVMM, parent: &mut ByFrame<GlobalFrameAlloc>) {
        let lock = allocator.lock();
        let mut active_pt = lock.kernel_table();
        for p in Page::range_of(self.start, self.end) {
            parent.unmap(active_pt.deref_mut(), p.start_address());
        }
    }
}

use three_d::*;

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let window = Window::new(WindowSettings{
        title: "Mandelbrot!".to_string(),
//         max_size: Some((1280, 720)),
        max_size: None,
        ..Default::default()
    })
    .unwrap();
    let context = window.gl().unwrap();

    // Renderer
    let mut camera = CameraControl::new(
            Camera::new_orthographic(
            &context,
            vec3(0.0, 0.0, 1.0),
            vec3(0.0, 0.0, 0.0),
            vec3(0.0, 1.0, 0.0),
            1.2,
            1.2 * window.viewport().unwrap().aspect(),
            10.0,
        ).unwrap(),
    );

    let indices = vec![0, 1, 2, 2, 3, 0];
    let positions = vec![-2.0, -2.0, 0.0, 2.0, -2.0, 0.0, 2.0, 2.0, 0.0, -2.0, 2.0, 0.0];
    let mut mesh = Mesh::new(
        &context,
        &CPUMesh{
            indices: Some(indices),
            positions,
            ..Default::default()
        },
    )
    .unwrap();
    mesh.cull = CullType::Back;
    mesh.transformation = Mat4::from_scale(10.0);
    let program = MeshProgram::new(&context, include_str!("mandelbrot.frag")).unwrap();

    // main loop
    let mut panning = false;
    let mut pick: Option<((f64, f64), Vec3)> = None;
    window
        .render_loop(move |frame_input| {
            let mut redraw = frame_input.first_frame;
            redraw |= camera.set_aspect(frame_input.viewport.aspect()).unwrap();

            for event in frame_input.events.iter() {
                match event {
                    Event::MouseClick{state, button, ..} => {
                        panning = *button == MouseButton::Left && *state == State::Pressed;
                    }
                    Event::MouseMotion{delta, position, ..} => {
                        if panning {
                            let speed = 0.003 * camera.position().z.abs();
                            camera
                                .pan(speed * delta.0 as f32, speed * delta.1 as f32)
                                .unwrap();
                            redraw = true;
                        }
                        if let Some((p, _)) = pick {
                            if (p.0 - position.0).abs() > 2.0 || (p.1 - position.1).abs() > 2.0 {
                                pick = None;
                            }
                        }
                    }
                    Event::MouseWheel{delta, position, ..} => {
                        if pick.is_none() {
                            let p = camera
                                .pick(
                                    (
                                        ((position.0 * frame_input.device_pixel_ratio
                                            - frame_input.viewport.x as f64)
                                            / frame_input.viewport.width as f64)
                                            as f32,
                                        ((position.1 * frame_input.device_pixel_ratio
                                            - frame_input.viewport.y as f64)
                                            / frame_input.viewport.height as f64)
                                            as f32,
                                    ),
                                    10.0,
                                    &[&mesh],
                                )
                                .unwrap();
                            pick = p.map(|pos| (*position, pos));
                        };
                        if let Some((_, pos)) = pick {
                            let distance = pos.distance(*camera.position());
                            camera
                                .zoom_towards(&pos, distance * 0.005 * delta.1 as f32, 0.00001, 10.0)
                                .unwrap();
                            redraw = true;
                        }
                    }
                    _ => {}
                }
            }

            if redraw {
                Screen::write(&context, ClearState::color(0.0, 1.0, 1.0, 1.0), || {
                    mesh.render(
                        &program,
                        RenderStates{
                            write_mask: WriteMask::COLOR,
                            depth_test: DepthTestType::Always,
                            ..Default::default()
                        },
                        frame_input.viewport,
                        &camera,
                    ).unwrap();
                    Ok(())
                }).unwrap();
            }

            if args.len() > 1 {
                // To automatically generate screenshots of the examples, can safely be ignored.
                FrameOutput{
                    screenshot: Some(args[1].clone().into()),
                    exit: true,
                    ..Default::default()
                }
            } else {
                FrameOutput{
                    swap_buffers: redraw,
                    wait_next_event: true,
                    ..Default::default()
                }
            }
        }).unwrap();
}

//! This is basically a copy of some of cargo-edit, which is focused on
//! being a CLI and has a lot of dependencies that can be annoying to upgrade
//! throughout our graph, so for now we just copy some pieces we need

use anyhow::Error;

pub mod dependency;

pub use dependency as dep;

fn merge_inline_table(old_dep: &mut toml_edit::Item, new: &toml_edit::Item) {
    for (k, v) in new
        .as_inline_table()
        .expect("expected an inline table")
        .iter()
    {
        old_dep[k] = toml_edit::value(v.clone());
    }
}

fn str_or_1_len_table(item: &toml_edit::Item) -> bool {
    item.is_str() || item.as_table_like().map(|t| t.len() == 1).unwrap_or(false)
}

fn merge_dependencies(old_dep: &mut toml_edit::Item, new: &dep::Dependency) {
    assert!(!old_dep.is_none());

    let new_toml = new.to_toml().1;

    if str_or_1_len_table(old_dep) {
        // The old dependency is just a version/git/path. We are safe to overwrite.
        *old_dep = new_toml;
    } else if old_dep.is_table_like() {
        for key in &["version", "path", "git"] {
            // remove this key/value pairs
            old_dep[key] = toml_edit::Item::None;
        }
        if let Some(name) = new_toml.as_str() {
            old_dep["version"] = toml_edit::value(name);
        } else {
            merge_inline_table(old_dep, &new_toml);
        }
    } else {
        unreachable!("Invalid old dependency type");
    }

    if let Some(t) = old_dep.as_inline_table_mut() {
        t.fmt()
    }
}

pub struct Manifest {
    pub doc: toml_edit::Document,
}

impl Manifest {
    pub fn get_dep_sections(&self) -> Vec<(Vec<String>, toml_edit::Item)> {
        let mut sections = Vec::new();

        for dependency_type in &["dev-dependencies", "build-dependencies", "dependencies"] {
            // Dependencies can be in the three standard sections...
            if self.doc[dependency_type].is_table_like() {
                sections.push((
                    vec![String::from(*dependency_type)],
                    self.doc[dependency_type].clone(),
                ))
            }

            // ... and in `target.<target>.(build-/dev-)dependencies`.
            let target_sections = self
                .doc
                .as_table()
                .get("target")
                .and_then(toml_edit::Item::as_table_like)
                .into_iter()
                .flat_map(toml_edit::TableLike::iter)
                .filter_map(|(target_name, target_table)| {
                    let dependency_table = &target_table[dependency_type];
                    dependency_table.as_table_like().map(|_| {
                        (
                            vec![
                                "target".to_string(),
                                target_name.to_string(),
                                String::from(*dependency_type),
                            ],
                            dependency_table.clone(),
                        )
                    })
                });

            sections.extend(target_sections);
        }

        sections
    }

    pub fn get_table<'a>(
        &'a mut self,
        table_path: &[String],
    ) -> Result<&'a mut toml_edit::Item, Error> {
        /// Descend into a manifest until the required table is found.
        fn descend<'a>(
            input: &'a mut toml_edit::Item,
            path: &[String],
        ) -> Result<&'a mut toml_edit::Item, Error> {
            if let Some(segment) = path.get(0) {
                let value = input[&segment].or_insert(toml_edit::table());

                if value.is_table_like() {
                    descend(value, &path[1..])
                } else {
                    anyhow::bail!("Unable to find '{}'", segment);
                }
            } else {
                Ok(input)
            }
        }

        descend(&mut self.doc.root, table_path)
    }

    pub fn update_table_named_entry(
        &mut self,
        table_path: &[String],
        item_name: &str,
        dep: &dep::Dependency,
    ) -> Result<(), Error> {
        let table = self.get_table(table_path)?;

        // If (and only if) there is an old entry, merge the new one in.
        if !table[item_name].is_none() {
            merge_dependencies(&mut table[item_name], dep);
            if let Some(t) = table.as_inline_table_mut() {
                t.fmt()
            }
        }

        Ok(())
    }

    pub fn upgrade(&mut self, deps: &[dep::Dependency]) -> Result<(), Error> {
        for (table_path, table) in self.get_dep_sections() {
            let table_like = table.as_table_like().expect("Unexpected non-table");
            for (name, toml_item) in table_like.iter() {
                let dep_name = toml_item
                    .as_table_like()
                    .and_then(|t| t.get("package").and_then(|p| p.as_str()))
                    .unwrap_or(name);

                if let Some(update_dep) = deps.iter().find(|dep| dep.name == dep_name) {
                    self.update_table_named_entry(&table_path, &name, update_dep)?;
                }
            }
        }

        Ok(())
    }
}

impl std::str::FromStr for Manifest {
    type Err = Error;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let doc: toml_edit::Document = s.parse()?;
        Ok(Self { doc })
    }
}

