#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn test_memory_write_stream() {
        let mut msw = MemoryStreamWriter::new();
        let string = "hello world".as_bytes();
        assert!(msw.write(string) == Result::Ok(11));
        assert!(msw.tell() == 11);
        assert!(msw.size() == 11);
        let data = msw.data().as_slice();
        assert!(data.len() == 11);
        for i in 0..string.len() {
            assert!(data[i] == string[i]);
        }
        assert!(msw.seek(5) == Result::Ok(5));
        assert!(msw.write("1234".as_bytes()) == Result::Ok(4));
        assert!(msw.tell() == 9);
        let string = "hello1234ld".as_bytes();
        let data = msw.data().as_slice();
        assert!(data.len() == 11);
        for i in 0..string.len() {
            assert!(data[i] == string[i]);
        }
        assert!(msw.seek(14) == Result::Ok(11));
    }

    #[test]
    fn test_memory_read_stream() {
        let mut msr = MemoryStreamReader::from("hello world".as_bytes());
        assert!(msr.tell() == 0);
        assert!(msr.size() == 11);
        let string = "hello world".as_bytes();
        let mut buff = [0u8; 11];
        assert!(msr.read(&mut buff) == Result::Ok(11));
        for i in 0..string.len() {
            assert!(buff[i] == string[i]);
        }
        assert!(msr.seek(5) == Result::Ok(5));

        let mut buff = [0u8; 4];
        assert!(msr.read(&mut buff) == Result::Ok(4));
        assert!(msr.tell() == 9);
        let string = " wor".as_bytes();
        for i in 0..string.len() {
            assert!(buff[i] == string[i]);
        }
        assert!(msr.seek(14) == Result::Ok(11));

        assert!("0.1234".parse::<f32>().unwrap() == 0.1234_f32);
    }
}

// 给定总玩家数 n，以及按 [玩家编号,对应可传递玩家编号] 关系组成的二维数组 relation。返回信息从小 A (编号 0 ) 经过 k 轮传递到编号为 n-1 的小伙伴处的方案数；若不能到达，返回 0。
// 限制：
// 2 <= n <= 10
// 1 <= k <= 5
// 1 <= relation.length <= 90, 且 relation[i].length == 2
// 0 <= relation[i][0],relation[i][1] < n 且 relation[i][0] != relation[i][1]
pub fn num_ways(n: i32, relation: Vec<Vec<i32>>, k: i32) -> i32 {
    let mut relations:Vec<Vec<i32>> = vec![Vec::new();10];
    for rel in relation.iter() {
        relations[rel[0] as usize].push(rel[1]);
    }

    let mut ways = vec![&0];
    let mut i = 0;
    while i < k {
        ways = ways.iter().flat_map(|&&w|{
            relations.get(w as usize).unwrap()
        }).collect();

        i += 1;
    }

    ways.iter().filter(|&&w| *w == n - 1).count() as i32
}

#[test]
fn num_ways_t1() {
    // 输入：n = 3, relation = [[0,2],[2,1]], k = 2
    // 输出：0
    // 解释：信息不能从小 A 处经过 2 轮传递到编号 2
    assert_eq!(0, num_ways(3, vec![vec![0,2],vec![2,1]], 2));
}

#[test]
fn num_ways_t0() {
    // 输入：n = 5, relation = [[0,2],[2,1],[3,4],[2,3],[1,4],[2,0],[0,4]], k = 3
    // 输出：3
    // 解释：信息从小 A 编号 0 处开始，经 3 轮传递，到达编号 4。共有 3 种方案，分别是 0->2->0->4， 0->2->1->4， 0->2->3->4。
    assert_eq!(3, num_ways(5, vec![vec![0,2],vec![2,1],vec![3,4],vec![2,3],vec![1,4],vec![2,0],vec![0,4]], 3));
}

//! Implements **HTTP basic access authentication**. Stores the credentials like username and password(encrypted) provided by environment variables in memory.

use crate::handlers::error::Error;
use crate::state::State;
use actix_web::dev::ServiceRequest;
use actix_web::web;
use actix_web_httpauth::extractors::basic::BasicAuth;
use serde::{Deserialize, Serialize};
use sha2::Digest;
use std::convert::TryFrom;
use std::convert::TryInto;

pub async fn handle_basic_auth(
    req: ServiceRequest,
    credentials: BasicAuth,
) -> Result<ServiceRequest, actix_web::Error> {
    let state: web::Data<State> = req.app_data().unwrap();
    match credentials.password() {
        Some(cred) => {
            let pwd = sha2::Sha256::digest(cred.as_bytes()).to_vec();
            if credentials.user_id() == state.credentials.username()
                && pwd == state.credentials.password()
            {
                Ok(req)
            } else {
                Err(Error::Unauthorized.into_actix_web_err())
            }
        }
        None => Err(Error::Unauthorized.into_actix_web_err()),
    }
}

/// Default username: ```user```
fn default_user() -> String {
    String::from("user")
}
/// Default password: ```wasd4221```
fn default_pwd() -> String {
    String::from("wasd4221")
}
/// Credentials stored in memory.
#[derive(Debug, serde::Deserialize)]
pub struct Credentials {
    username: String,
    password: Sha256,
}

/// Credentials provided by the environment prefixed by "DEPP_API_".  
/// Example:  
/// ```DEPP_API_USERNAME="tom"```  
/// ```DEPP_API_USERNAME="passwordone"```
#[derive(Debug, serde::Deserialize)]
pub struct CredentialsEnv {
    #[serde(default = "default_user")]
    username: String,
    #[serde(default = "default_pwd")]
    password: String,
}
/// Sha256 Wrapper that supports serialisation.
#[derive(Serialize, Deserialize, Debug, Clone)]
pub struct Sha256(#[serde(with = "hex_serde")] pub Vec<u8>);

impl Credentials {
    pub fn username(&self) -> &str {
        &self.username
    }
    pub fn password(&self) -> Vec<u8> {
        self.password.0.to_vec()
    }
}

pub fn get_credentials() -> Credentials {
    match envy::prefixed("DEPP_API_").from_env::<CredentialsEnv>() {
        Ok(cred) => Credentials {
            username: cred.username,
            password: cred.password.try_into().unwrap(),
        },
        Err(err) => panic!("Bad credentials! err: {}", err),
    }
}

impl TryFrom<String> for Sha256 {
    type Error = failure::Error;

    fn try_from(s: String) -> Result<Sha256, Self::Error> {
        let pwd = sha2::Sha256::digest(&s.as_bytes()).to_vec();
        Ok(Sha256(pwd))
    }
}

