        assert_eq!(part1(&test_input), 112);
        assert_eq!(part2(&test_input), 848);
    }

    #[test]
    fn day17() {
        let input = get_input(2020, 17).unwrap();
        assert_eq!(part1(&input), 324);
        assert_eq!(part2(&input), 1836);
    }
}

use enum_iterator::IntoEnumIterator;
