//! Utilities for the handling of ISO 8601 timestamps.

use std::fmt::{Formatter, Result as FmtResult};

use serde::de::{Deserialize, Error as DeserializeError, Visitor};
use serde::ser::Serialize;
use serde::{Deserializer, Serializer};
use time::{format_description::well_known::Rfc3339, OffsetDateTime, PrimitiveDateTime};

use self::display::TimestampDisplay;

pub mod display;
pub mod error;

/// Representation of a UNIX timestamp.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
pub struct Timestamp(PrimitiveDateTime);

impl Timestamp {
    /// Parse a timestamp from an ISO 8601 datetime string.
    pub fn parse(datetime: &str) -> Result<Self, error::TimestampParseError> {
        const LENGTH: usize = "2022-01-01T00:00:00Z".len();

        if datetime.len() < LENGTH {
            return Err(error::TimestampParseError {
                kind: error::TimestampParseErrorKind::Format,
                source: None,
            });
        }

        OffsetDateTime::parse(datetime, &Rfc3339)
            .map(|offset| PrimitiveDateTime::new(offset.date(), offset.time()))
            .map(Self)
            .map_err(error::TimestampParseError::from_parse)
    }

    pub fn display(self) -> TimestampDisplay {
        TimestampDisplay::new(self)
    }
}

impl<'de> Deserialize<'de> for Timestamp {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        deserializer.deserialize_any(TimestampDeserializerVisitor)
    }
}

impl Serialize for Timestamp {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        serializer.collect_str(&self.display())
    }
}

pub(in crate::datetime) struct TimestampDeserializerVisitor;

impl Visitor<'_> for TimestampDeserializerVisitor {
    type Value = Timestamp;

    fn expecting(&self, f: &mut Formatter<'_>) -> FmtResult {
        f.write_str("an rfc3339 timestamp")
    }

    fn visit_str<E>(self, value: &str) -> Result<Self::Value, E>
    where
        E: DeserializeError,
    {
        Timestamp::parse(value).map_err(DeserializeError::custom)
    }
}

use crate::config::Config;
use chrono::offset::{TimeZone, Utc};
use chrono::{Date, DateTime, NaiveDate};
use chrono_tz::{Tz, TZ_VARIANTS};

pub fn now(config: &Config) -> DateTime<Tz> {
    let tz = timezone_from_str(&config.timezone);
    Utc::now().with_timezone(&tz)
}

/// Return today's date in format 2021-09-16
pub fn today_string(config: &Config) -> String {
    now(config).format("%Y-%m-%d").to_string()
}

/// Return today's date in Utc
pub fn today_date(config: &Config) -> Date<Tz> {
    now(config).date()
}

pub fn datetime_is_today(datetime: DateTime<Tz>, config: &Config) -> bool {
    date_is_today(datetime.date(), config)
}

pub fn date_is_today(date: Date<Tz>, config: &Config) -> bool {
    date.format("%Y-%m-%d").to_string() == today_string(config)
}

pub fn is_date_in_past(date: Date<Tz>, config: &Config) -> bool {
    date.signed_duration_since(today_date(config)).num_days() < 0
}

pub fn format_date(date: &Date<Tz>, config: &Config) -> String {
    if date_is_today(*date, config) {
        String::from("Today")
    } else {
        date.format("%Y-%m-%d").to_string()
    }
}

pub fn format_datetime(datetime: &DateTime<Tz>, config: &Config) -> String {
    let tz = timezone_from_str(&config.timezone);
    if datetime_is_today(*datetime, config) {
        datetime.with_timezone(&tz).format("%H:%M").to_string()
    } else {
        datetime.with_timezone(&tz).to_string()
    }
}

/// Parse DateTime
pub fn datetime_from_str(str: &str, timezone: Tz) -> Result<DateTime<Tz>, String> {
    let datetime = match str.len() {
        19 => timezone
            .datetime_from_str(str, "%Y-%m-%dT%H:%M:%S")
            .expect("could not parse DateTime"),
        20 => Utc
            .datetime_from_str(str, "%Y-%m-%dT%H:%M:%SZ")
            .expect("could not parse DateTime")
            .with_timezone(&Tz::UTC),
        _ => return Err(format!("cannot parse DateTime: {}", str)),
    };

    Ok(datetime)
}

pub fn timezone_from_str(timezone_string: &Option<String>) -> Tz {
    match timezone_string {
        None => Tz::UTC,
        Some(string) => string.parse::<Tz>().unwrap(),
    }
}

/// Parse Date
pub fn date_from_str(str: &str, timezone: Tz) -> Result<Date<Tz>, String> {
    let date = match str.len() {
        10 => {
            let date =
                NaiveDate::parse_from_str(str, "%Y-%m-%d").or(Err("could not parse Date"))?;
            timezone.from_local_date(&date).unwrap()
        }
        19 => timezone
            .datetime_from_str(str, "%Y-%m-%dT%H:%M:%S")
            .or(Err("could not parse DateTime"))?
            .date(),

        20 => timezone
            .datetime_from_str(str, "%Y-%m-%dT%H:%M:%SZ")
            .or(Err("could not parse DateTime"))?
            .date(),
        _ => return Err(format!("cannot parse NaiveDate, unknown length: {}", str)),
    };

    Ok(date)
}

pub fn list_timezones() {
    println!("Timezones:");
    for (num, tz) in TZ_VARIANTS.iter().enumerate() {
        println!("{}: {}", num, tz);
    }
}

pub fn get_timezone(num: usize) -> String {
    TZ_VARIANTS[num].to_string()
}

