// other words, the type from `rc` is `&'a Rc<String>` and the type
// from `&rc` should be `&'x &'a Rc<String>`, where `'x` is something
// small.

use std::rc::Rc;

#[derive(Clone)]
enum Cached<'mir> {
    Ref(&'mir String),
    Owned(Rc<String>),
}

impl<'mir> Cached<'mir> {
    fn get_ref<'a>(&'a self) -> &'a String {
        match *self {
            Cached::Ref(r) => r,
            Cached::Owned(ref rc) => &rc,
        }
    }
}

