// Simple Rx test for embedded-nrf24l01 crate

fn main() {
    let dev = FTx232H::init(0x0403, 0x6014).unwrap();
    let spidev = dev.spi(hal::spi::SpiSpeed::CLK_1MHz).unwrap();
    let ce = dev.pl1().unwrap();
    let cs = dev.pl2().unwrap();

    let mut nrf = NRF24L01::new(ce, cs, spidev).unwrap();
    nrf.set_frequency(120).unwrap();
    nrf.set_rf(&DataRate::R250Kbps, 3 /* 0 dBm */).unwrap();
    nrf.set_crc(CrcMode::OneByte).unwrap();
    nrf.set_auto_retransmit(0b0100, 0b1111).unwrap();
    nrf.set_auto_ack(&[true; 6]).unwrap();

    let addr: [u8; 5] = [0xe5, 0xe4, 0xe3, 0xe2, 0xe1];
    nrf.set_rx_addr(0, &addr).unwrap();
    nrf.set_pipes_rx_lengths(&[None; 6]).unwrap();
    nrf.set_pipes_rx_enable(&[true, false, false, false, false, false])
        .unwrap();
    nrf.flush_tx().unwrap();
    nrf.flush_rx().unwrap();

    let delay = Duration::from_millis(500);
    let mut rx = nrf.rx().unwrap();

    loop {
        let pipe = rx.can_read().unwrap();

        if pipe.is_some() {
            let data = rx.read().unwrap();
            println!("Rx: {:?}", data.as_ref());
        }

        sleep(delay);
    }
}

use tracing::error;
use wgpu::{Adapter, Instance, Surface, TextureFormat};

use crate::renderer;

struct RenderState {
    device: wgpu::Device,
    queue: wgpu::Queue,
    target_format: TextureFormat,
    egui_rpass: renderer::RenderPass,
}

struct SurfaceState {
    surface: Surface,
    width: u32,
    height: u32,
}

/// Everything you need to paint egui with [`wgpu`] on [`winit`].
///
/// Alternatively you can use [`crate::renderer`] directly.
pub struct Painter<'a> {
    power_preference: wgpu::PowerPreference,
    device_descriptor: wgpu::DeviceDescriptor<'a>,
    present_mode: wgpu::PresentMode,
    msaa_samples: u32,

    instance: Instance,
    adapter: Option<Adapter>,
    render_state: Option<RenderState>,
    surface_state: Option<SurfaceState>,
}

impl<'a> Painter<'a> {
    /// Manages [`wgpu`] state, including surface state, required to render egui.
    ///
    /// Only the [`wgpu::Instance`] is initialized here. Device selection and the initialization
    /// of render + surface state is deferred until the painter is given its first window target
    /// via [`set_window()`](Self::set_window). (Ensuring that a device that's compatible with the
    /// native window is chosen)
    ///
    /// Before calling [`paint_and_update_textures()`](Self::paint_and_update_textures) a
    /// [`wgpu::Surface`] must be initialized (and corresponding render state) by calling
    /// [`set_window()`](Self::set_window) once you have
    /// a [`winit::window::Window`] with a valid `.raw_window_handle()`
    /// associated.
    pub fn new(
        backends: wgpu::Backends,
        power_preference: wgpu::PowerPreference,
        device_descriptor: wgpu::DeviceDescriptor<'a>,
        present_mode: wgpu::PresentMode,
        msaa_samples: u32,
    ) -> Self {
        let instance = wgpu::Instance::new(backends);

        Self {
            power_preference,
            device_descriptor,
            present_mode,
            msaa_samples,

            instance,
            adapter: None,
            render_state: None,
            surface_state: None,
        }
    }

    async fn init_render_state(
        &self,
        adapter: &Adapter,
        target_format: TextureFormat,
    ) -> RenderState {
        let (device, queue) =
            pollster::block_on(adapter.request_device(&self.device_descriptor, None)).unwrap();

        let egui_rpass = renderer::RenderPass::new(&device, target_format, self.msaa_samples);

        RenderState {
            device,
            queue,
            target_format,
            egui_rpass,
        }
    }

    // We want to defer the initialization of our render state until we have a surface
    // so we can take its format into account.
    //
    // After we've initialized our render state once though we expect all future surfaces
    // will have the same format and so this render state will remain valid.
    fn ensure_render_state_for_surface(&mut self, surface: &Surface) {
        self.adapter.get_or_insert_with(|| {
            pollster::block_on(self.instance.request_adapter(&wgpu::RequestAdapterOptions {
                power_preference: self.power_preference,
                compatible_surface: Some(surface),
                force_fallback_adapter: false,
            }))
            .unwrap()
        });

        if self.render_state.is_none() {
            let adapter = self.adapter.as_ref().unwrap();
            let swapchain_format = surface.get_preferred_format(adapter).unwrap();

            let rs = pollster::block_on(self.init_render_state(adapter, swapchain_format));
            self.render_state = Some(rs);
        }
    }

    fn configure_surface(&mut self, width_in_pixels: u32, height_in_pixels: u32) {
        let render_state = self
            .render_state
            .as_ref()
            .expect("Render state should exist before surface configuration");
        let format = render_state.target_format;

        let config = wgpu::SurfaceConfiguration {
            usage: wgpu::TextureUsages::RENDER_ATTACHMENT,
            format,
            width: width_in_pixels,
            height: height_in_pixels,
            present_mode: self.present_mode,
        };

        let surface_state = self
            .surface_state
            .as_mut()
            .expect("Surface state should exist before surface configuration");
        surface_state
            .surface
            .configure(&render_state.device, &config);
        surface_state.width = width_in_pixels;
        surface_state.height = height_in_pixels;
    }

    /// Updates (or clears) the [`winit::window::Window`] associated with the [`Painter`]
    ///
    /// This creates a [`wgpu::Surface`] for the given Window (as well as initializing render
    /// state if needed) that is used for egui rendering.
    ///
    /// This must be called before trying to render via
    /// [`paint_and_update_textures`](Self::paint_and_update_textures)
    ///
    /// # Portability
    ///
    /// _In particular it's important to note that on Android a it's only possible to create
    /// a window surface between `Resumed` and `Paused` lifecycle events, and Winit will panic on
    /// attempts to query the raw window handle while paused._
    ///
    /// On Android [`set_window`](Self::set_window) should be called with `Some(window)` for each
    /// `Resumed` event and `None` for each `Paused` event. Currently, on all other platforms
    /// [`set_window`](Self::set_window) may be called with `Some(window)` as soon as you have a
    /// valid [`winit::window::Window`].
    ///
    /// # Safety
    ///
    /// The raw Window handle associated with the given `window` must be a valid object to create a
    /// surface upon and must remain valid for the lifetime of the created surface. (The surface may
    /// be cleared by passing `None`).
    pub unsafe fn set_window(&mut self, window: Option<&winit::window::Window>) {
        match window {
            Some(window) => {
                let surface = self.instance.create_surface(&window);

                self.ensure_render_state_for_surface(&surface);

                let size = window.inner_size();
                let width = size.width as u32;
                let height = size.height as u32;
                self.surface_state = Some(SurfaceState {
                    surface,
                    width,
                    height,
                });
                self.configure_surface(width, height);
            }
            None => {
                self.surface_state = None;
            }
        }
    }

    /// Returns the maximum texture dimension supported if known
    ///
    /// This API will only return a known dimension after `set_window()` has been called
    /// at least once, since the underlying device and render state are initialized lazily
    /// once we have a window (that may determine the choice of adapter/device).
    pub fn max_texture_side(&self) -> Option<usize> {
        self.render_state
            .as_ref()
            .map(|rs| rs.device.limits().max_texture_dimension_2d as usize)
    }

    pub fn on_window_resized(&mut self, width_in_pixels: u32, height_in_pixels: u32) {
        if self.surface_state.is_some() {
            self.configure_surface(width_in_pixels, height_in_pixels);
        } else {
            error!("Ignoring window resize notification with no surface created via Painter::set_window()");
        }
    }

    pub fn paint_and_update_textures(
        &mut self,
        pixels_per_point: f32,
        clear_color: egui::Rgba,
        clipped_primitives: &[egui::ClippedPrimitive],
        textures_delta: &egui::TexturesDelta,
    ) {
        let render_state = match self.render_state.as_mut() {
            Some(rs) => rs,
            None => return,
        };
        let surface_state = match self.surface_state.as_ref() {
            Some(rs) => rs,
            None => return,
        };

        let output_frame = match surface_state.surface.get_current_texture() {
            Ok(frame) => frame,
            Err(wgpu::SurfaceError::Outdated) => {
                // This error occurs when the app is minimized on Windows.
                // Silently return here to prevent spamming the console with:
                // "The underlying surface has changed, and therefore the swap chain must be updated"
                return;
            }
            Err(e) => {
                tracing::warn!("Dropped frame with error: {e}");
                return;
            }
        };
        let output_view = output_frame
            .texture
            .create_view(&wgpu::TextureViewDescriptor::default());

        let mut encoder =
            render_state
                .device
                .create_command_encoder(&wgpu::CommandEncoderDescriptor {
                    label: Some("encoder"),
                });

        // Upload all resources for the GPU.
        let screen_descriptor = renderer::ScreenDescriptor {
            size_in_pixels: [surface_state.width, surface_state.height],
            pixels_per_point,
        };

        for (id, image_delta) in &textures_delta.set {
            render_state.egui_rpass.update_texture(
                &render_state.device,
                &render_state.queue,
                *id,
                image_delta,
            );
        }
        for id in &textures_delta.free {
            render_state.egui_rpass.free_texture(id);
        }

        render_state.egui_rpass.update_buffers(
            &render_state.device,
            &render_state.queue,
            clipped_primitives,
            &screen_descriptor,
        );

        // Record all render passes.
        render_state.egui_rpass.execute(
            &mut encoder,
            &output_view,
            clipped_primitives,
            &screen_descriptor,
            Some(wgpu::Color {
                r: clear_color.r() as f64,
                g: clear_color.g() as f64,
                b: clear_color.b() as f64,
                a: clear_color.a() as f64,
            }),
        );

        // Submit the commands.
        render_state.queue.submit(std::iter::once(encoder.finish()));

        // Redraw egui
        output_frame.present();
    }

    #[allow(clippy::unused_self)]
    pub fn destroy(&mut self) {
        // TODO(emilk): something here?
    }
}

use crate::utils::is_sha;
use std::fs;
use std::fs::File;
use std::io::prelude::*;
use std::io::Result as IOResult;
use std::path::{Path, PathBuf};

#[derive(Debug)]
pub struct Ref {
    pub id: String,
    pub name: String,
}

pub type Refs = Vec<Ref>;

pub(crate) fn create_refs(repo: &str, refs: &[Ref]) -> IOResult<()> {
    let (tags, branches): (Vec<_>, Vec<_>) = refs
        .iter()
        .filter(|r| !r.name.ends_with("^{}"))
        .partition(|r| r.name.starts_with("refs/tags"));

    write_refs(repo, "refs/remotes/origin", &branches)?;
    write_refs(repo, "refs/tags", &tags)?;
    Ok(())
}

pub(crate) fn update_head(repo: &str, refs: &[Ref]) -> IOResult<()> {
    if let Some(head) = refs.iter().find(|r| r.name == "HEAD") {
        let sha1 = &head.id;
        let true_ref = refs.iter().find(|r| r.name != "HEAD" && r.id == *sha1);
        let dir = true_ref.map_or("refs/heads/master", |r| &r.name[..]);
        create_ref(repo, dir, &sha1)?;
        create_sym_ref(repo, "HEAD", dir)?;
    }
    Ok(())
}

fn write_refs(repo: &str, parent_path: &str, refs: &[&Ref]) -> IOResult<()> {
    let mut path = PathBuf::new();
    path.push(parent_path);

    for r in refs {
        let mut full_path = path.clone();
        let simple_name = Path::new(&r.name).file_name().unwrap();
        full_path.push(&simple_name);
        create_ref(repo, full_path.to_str().unwrap(), &r.id)?;
    }
    Ok(())
}

fn create_ref(repo: &str, path: &str, id: &str) -> IOResult<()> {
    let mut full_path = PathBuf::new();
    full_path.push(repo);
    full_path.push(".git");
    full_path.push(path);
    fs::create_dir_all(full_path.parent().unwrap())?;
    let mut file = File::create(full_path)?;
    file.write_fmt(format_args!("{}\n", id))?;
    Ok(())
}

///
/// Creates a symbolic ref in the given repository.
///
fn create_sym_ref(repo: &str, name: &str, the_ref: &str) -> IOResult<()> {
    let mut path = PathBuf::new();
    path.push(repo);
    path.push(".git");
    path.push(name);
    let mut file = File::create(path)?;
    file.write_fmt(format_args!("ref: {}\n", the_ref))?;
    Ok(())
}

pub fn resolve_ref(repo: &str, name: &str) -> IOResult<String> {
    // Check if the name is already a sha.
    let trimmed = name.trim();
    if is_sha(trimmed) {
        Ok(trimmed.to_owned())
    } else {
        read_sym_ref(repo, trimmed)
    }
}

fn read_sym_ref(repo: &str, name: &str) -> IOResult<String> {
    // Read the symbolic ref directly and parse the actual ref out
    let mut path = PathBuf::new();
    path.push(repo);
    path.push(".git");

    if name != "HEAD" {
        if !name.contains('/') {
            path.push("refs/heads");
        } else if !name.starts_with("refs/") {
            path.push("refs/remotes");
        }
    }
    path.push(name);

    // Read the actual ref out
    let mut contents = String::new();
    let mut file = File::open(path)?;
    file.read_to_string(&mut contents)?;

    if contents.starts_with("ref: ") {
        let the_ref = contents.split("ref: ").nth(1).unwrap().trim();
        resolve_ref(repo, &the_ref)
    } else {
        Ok(contents.trim().to_owned())
    }
}

use std::{alloc::Layout, mem};

/// For a given offset determine the total offset until the next alignment
pub const fn next_aligned(num_bytes: usize, alignment: usize) -> usize {
  let remaining = num_bytes % alignment;
  if remaining == 0 {
    num_bytes
  } else {
    num_bytes + (alignment - remaining)
  }
}

/// Get the offset to the start of the `GcArray<T>` data
pub const fn get_offset<H, T>() -> usize {
  next_aligned(mem::size_of::<H>(), mem::align_of::<T>())
}

pub const fn get_array_len_offset<H>() -> usize {
  next_aligned(mem::size_of::<H>(), mem::align_of::<usize>())
}

pub const fn get_array_offset<H, T>() -> usize {
  let len_offset = get_array_len_offset::<H>();
  next_aligned(len_offset + mem::size_of::<usize>(), mem::align_of::<T>())
}

/// Determine the max alignment between the item `T`
/// and the `GcArray` header `Header`
pub const fn max_align<H, T>() -> usize {
  let t_align = mem::align_of::<T>();
  let header_align = mem::align_of::<H>();

  if t_align >= header_align {
    t_align
  } else {
    header_align
  }
}

/// Determine the max alignment between the item `T`
/// and the `GcArray` header `Header`
pub const fn max_array_align<H, T>() -> usize {
  let max_align = max_align::<H, T>();
  let len_align = mem::align_of::<usize>();

  if len_align >= max_align {
    len_align
  } else {
    max_align
  }
}

/// Create a rust `Layout` for a `GcArray` of `len` length.
pub fn make_array_layout<H, T>(len: usize) -> Layout {
  let alignment = max_array_align::<H, T>();

  let num_bytes = if len == 0 {
    get_array_offset::<H, T>()
  } else {
    get_array_offset::<H, T>() + len * mem::size_of::<T>()
  };

  Layout::from_size_align(num_bytes, alignment).unwrap()
}

/// Create a rust `Layout` for a `GcArray` of `len` length.
pub fn make_layout<H, T>() -> Layout {
  let alignment = max_align::<H, T>();

  let header_size = mem::size_of::<H>();
  let num_bytes = next_aligned(header_size, mem::align_of::<T>()) + mem::size_of::<T>();
  Layout::from_size_align(num_bytes, alignment).unwrap()
}

#[cfg(test)]
mod tests {
  use crate::managed::utils::next_aligned;

  use super::*;
  #[test]
  fn next_aligned_test() {
    assert_eq!(next_aligned(9, 4), 12);
    assert_eq!(next_aligned(13, 4), 16);
    assert_eq!(next_aligned(12, 4), 12);
    assert_eq!(next_aligned(13, 1), 13);
    assert_eq!(next_aligned(8, 8), 8);
    assert_eq!(next_aligned(16, 32), 32);
    assert_eq!(next_aligned(16, 512), 512);
  }

  #[repr(align(512))]
  struct OverAligned {
    _data: [u8; 512],
  }

  #[test]
  fn max_align_test() {
    let header_alignment = mem::align_of::<u64>();

    assert!(mem::align_of::<i32>() <= mem::align_of::<u64>());
    assert_eq!(max_align::<u64, i32>(), header_alignment);

    assert!(mem::align_of::<u8>() <= mem::align_of::<u64>());
    assert_eq!(max_align::<u64, u8>(), header_alignment);

    assert!(mem::align_of::<OverAligned>() > mem::align_of::<u64>());
    assert_eq!(
      max_align::<u64, OverAligned>(),
      mem::align_of::<OverAligned>()
    );
  }

  #[test]
  fn max_array_align_test() {
    assert_eq!(max_array_align::<u16, u8>(), mem::align_of::<usize>());
    assert_eq!(max_align::<u128, u8>(), mem::align_of::<u128>());
    assert_eq!(
      max_align::<u128, OverAligned>(),
      mem::align_of::<OverAligned>()
    );
  }

  #[test]
  fn get_offset_test() {
    assert_eq!(get_offset::<u32, u8>(), 4);
    assert_eq!(get_offset::<u32, u32>(), 4);
    assert_eq!(get_offset::<u32, u64>(), 8);
  }

  #[test]
  fn get_array_offset_test() {
    assert_eq!(get_array_offset::<u32, u8>(), mem::size_of::<usize>() * 2);
    assert_eq!(get_array_offset::<u32, u32>(), mem::size_of::<usize>() * 2);
    assert_eq!(get_array_offset::<u32, u128>(), mem::size_of::<usize>() * 2);
  }

  #[test]
  fn get_array_len_offset_test() {
    assert_eq!(get_array_len_offset::<u8>(), mem::size_of::<usize>());
    assert_eq!(get_array_len_offset::<usize>(), mem::size_of::<usize>());
    assert_eq!(get_array_len_offset::<u128>(), mem::size_of::<u128>());
  }

  #[test]
  fn make_array_layout_test() {
    // empty
    //
    let layout = make_array_layout::<u64, i32>(0);

    assert_eq!(layout.align(), mem::align_of::<u64>());
    assert_eq!(
      layout.size(),
      mem::size_of::<u64>() + mem::size_of::<usize>()
    );

    // non-empty, less than
    //
    let layout = make_array_layout::<u64, i32>(512);
    assert!(mem::align_of::<i32>() < mem::align_of::<u64>());
    assert_eq!(layout.align(), mem::align_of::<u64>());
    assert_eq!(
      layout.size(),
      mem::size_of::<u64>() + mem::size_of::<usize>() + 512 * mem::size_of::<i32>()
    );

    // non-empty, equal
    //
    let layout = make_array_layout::<u64, i64>(512);
    assert_eq!(mem::align_of::<i64>(), mem::align_of::<u64>());
    assert_eq!(layout.align(), mem::align_of::<u64>());
    assert_eq!(
      layout.size(),
      mem::size_of::<u64>() + mem::size_of::<usize>() + 512 * mem::size_of::<i64>()
    );

    // non-empty, greater
    let layout = make_array_layout::<u64, OverAligned>(512);
    assert!(mem::align_of::<OverAligned>() > mem::align_of::<u64>());
    assert_eq!(layout.align(), mem::align_of::<OverAligned>());
    assert_eq!(
      layout.size(),
      next_aligned(mem::size_of::<u64>(), mem::align_of::<OverAligned>())
        + 512 * mem::size_of::<OverAligned>()
    );
  }

  #[test]
  fn make_layout_test() {
    // non-empty, less than
    //
    let layout = make_layout::<u64, i32>();
    assert!(mem::align_of::<i32>() < mem::align_of::<u64>());
    assert_eq!(layout.align(), mem::align_of::<u64>());
    assert_eq!(layout.size(), mem::size_of::<u64>() + mem::size_of::<i32>());

    // non-empty, equal
    //
    let layout = make_layout::<u64, i64>();
    assert_eq!(mem::align_of::<i64>(), mem::align_of::<u64>());
    assert_eq!(layout.align(), mem::align_of::<u64>());
    assert_eq!(layout.size(), mem::size_of::<u64>() + mem::size_of::<i64>());

    // non-empty, greater
    let layout = make_layout::<u64, OverAligned>();
    assert!(mem::align_of::<OverAligned>() > mem::align_of::<u64>());
    assert_eq!(layout.align(), mem::align_of::<OverAligned>());
    assert_eq!(
      layout.size(),
      next_aligned(mem::size_of::<u64>(), mem::align_of::<OverAligned>())
        + mem::size_of::<OverAligned>()
    );
  }
}

pub trait StreamExt {
    fn read_u32_be(&self, offset: usize) -> u32;
    fn read_u32_le(&self, offset: usize) -> u32;
    fn write_u32_be(&mut self, offset: usize, value: u32);
}

impl StreamExt for [u8] {
    #[inline]
    fn read_u32_be(&self, offset: usize) -> u32 {
        u32::from_be_bytes(self[offset..offset + 4].try_into().unwrap())
    }

    #[inline]
    fn read_u32_le(&self, offset: usize) -> u32 {
        u32::from_le_bytes(self[offset..offset + 4].try_into().unwrap())
    }

    #[inline]
    fn write_u32_be(&mut self, offset: usize, value: u32) {
        self[offset..offset + 4].copy_from_slice(&value.to_be_bytes());
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn read_u32_be_test() {
        assert_eq!([1, 2, 3, 4].read_u32_be(0), 0x01020304);
        assert_eq!([0x7f, 0xff, 0xee, 0xdd, 0xcc].read_u32_be(1), 0xffeeddcc);
    }

    #[test]
    fn read_u32_le_test() {
        assert_eq!([1, 2, 3, 4].read_u32_le(0), 0x04030201);
        assert_eq!([0x7f, 0xff, 0xee, 0xdd, 0xcc].read_u32_le(1), 0xccddeeff);
    }

    #[test]
    fn test_write_u32_be() {
        let mut v = [0x7fu8, 0xff, 0xee, 0xdd, 0xcc];
        v.write_u32_be(0, 0x01020304);
        assert_eq!(v, [1u8, 2, 3, 4, 0xcc]);
    }
}

use super::IScreenManager;
use kernel::windows_kernel::kernel;
use winapi::um::wincon::ENABLE_PROCESSED_OUTPUT;
use winapi::um::winnt::HANDLE;

use std::any::Any;
use std::io::{self, Write};
use std::rc::Rc;

pub struct WinApiScreenManager {
    pub is_alternate_screen: bool,
    output: HANDLE,
    alternate_handle: HANDLE,
}

impl IScreenManager for WinApiScreenManager {
    fn toggle_is_alternate_screen(&mut self, is_alternate_screen: bool) {
        self.is_alternate_screen = is_alternate_screen;
    }

    fn write_string(&mut self, string: String) -> io::Result<usize>
    {
        self.write(string.as_bytes())
    }

    fn write_str(&mut self, string: &str) -> io::Result<usize>
    {
        self.write(string.as_bytes())
    }

    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        if self.is_alternate_screen {
            kernel::write_char_buffer(&self.alternate_handle, buf)
        } else {
            kernel::write_char_buffer(&self.output, buf)
        }
    }

    fn flush(&mut self) -> io::Result<()> {
        Ok(())
    }

    fn as_any(&mut self) -> &mut Any {
        self
    }
}

// for winapi we have some custom implementation that will be used by windows only. You can get a reference to this implementation by using the any and that cast it to this struct.
impl WinApiScreenManager {
    pub fn new() -> Self {
        WinApiScreenManager {
            output: kernel::get_output_handle(),
            is_alternate_screen: false,
            alternate_handle: kernel::get_output_handle(),
        }
    }

    /// Set the alternate handle to the given handle.
    pub fn set_alternate_handle(&mut self, alternate_handle: HANDLE) {
        self.alternate_handle = alternate_handle;

        // needs to be turned on so that escape characters like \n and \t will be processed.
        kernel::set_console_mode(&self.alternate_handle, ENABLE_PROCESSED_OUTPUT as u32);
    }

    /// get the current screen handle.
    pub fn get_handle(&mut self) -> &HANDLE {
        if self.is_alternate_screen {
            return &self.alternate_handle;

        } else {
            return &self.output;
        }
    }
}

