    #[test]
    fn simple() {
        use self::Tok::*;

        let lexer = Lexer::new("()[]#(#vu8('`,,@.#'#`#,#,@", 0);
        assert_eq!(
            lexer
                .map(|r| r.map(|t| t.1))
                .collect::<Result<Vec<_>, _>>()
                .unwrap(),
            vec![
                LParen,
                RParen,
                LBrack,
                RBrack,
                VectorOpen,
                ByteVectorOpen,
                Quote,
                QuasiQuote,
                Unquote,
                UnquoteSplicing,
                Dot,
                Syntax,
                QuasiSyntax,
