        }}

        #[cfg(vec3a_f32)]
        {{
            Vec3A(Vec3((self.0).{}, (self.0).{}, (self.0).{}))
        }}
    }}"#,
                E[e0], E[e1], E[e2], B[e2], B[e1], B[e0], e0, e1, e2
            )
        },
        |out, e0, e1| {
            write!(
                out,
                r#"
    #[inline]
    fn {}{}(self) -> Vec2 {{
        #[cfg(vec3a_sse2)]
        unsafe {{
            Vec2::from(Vec3A(_mm_shuffle_ps(self.0, self.0, 0b00_00_{}_{})))
        }}

        #[cfg(vec3a_f32)]
        {{
            Vec2((self.0).{}, (self.0).{})
        }}
    }}"#,
                E[e0], E[e1], B[e1], B[e0], e0, e1
            )
        },
    )?;

    write!(out, "\n}}\n")?;

    Ok(())
}

