use std::{
    fs::{self, File},
    io::Write,
    path::Path,
};

mod api_generator;
mod error;
mod rest_spec;

fn main() {
    // This must be run from the src root directory, with cargo run -p api_generator
    let download_dir = fs::canonicalize(PathBuf::from("./api_generator/rest_specs")).unwrap();
    let generated_dir = fs::canonicalize(PathBuf::from("./elasticsearch/src")).unwrap();
    let last_downloaded_version = "./api_generator/last_downloaded_version";

    let mut download_specs = false;
    let mut answer = String::new();
    let default_branch = if Path::new(last_downloaded_version).exists() {
        fs::read_to_string(last_downloaded_version).expect("Could not read branch into string")
    } else {
        String::from("master")
    };
    let mut branch = default_branch.clone();

    while answer != "y" && answer != "n" {
        answer = Input::new()
            .default(String::from("n"))
            .show_default(false)
            .with_prompt("Download rest specifications [y/N]")
            .interact()
            .unwrap()
            .to_lowercase();
        download_specs = answer == "y";
    }

    if download_specs {
        branch = Input::new()
            .default(default_branch.clone())
            .show_default(false)
            .with_prompt(
                format!(
                    "Branch to download specification from [default {}]",
                    default_branch
                )
                .as_str(),
            )
            .interact()
            .unwrap();

        fs::remove_dir_all(&download_dir).unwrap();
        rest_spec::download_specs(&branch, &download_dir);

        File::create(last_downloaded_version)
            .expect("failed to create last_downloaded_version file")
            .write_all(branch.as_bytes())
            .expect("unable to write branch to last_downloaded_version file");
    }

    // only offer to generate if there are downloaded specs
    if download_dir
        .read_dir()
        .map(|mut r| r.next().is_some())
        .unwrap_or(false)
    {
        let mut generate_code = true;
        answer = String::new();
        while answer != "y" && answer != "n" {
            answer = Input::new()
                .default(String::from("y"))
                .show_default(false)
                .with_prompt(
                    format!(
                        "Generate code from rest specifications {} [Y/n]",
                        branch
                    )
                    .as_str(),
                )
                .interact()
                .unwrap()
                .to_lowercase();
            generate_code = answer == "y";
        }

        if generate_code {
            api_generator::generate(&branch, &download_dir, &generated_dir).unwrap();
        }
    }
}

use anyhow::Result;
use clap::Parser;
use std::fs::File;
use std::io::Read;
use std::str::FromStr;

#[derive(Parser)]
#[clap(version = "1.0", author = "Raniz")]
struct Opts {
    #[clap(short, long, default_value = "input")]
    input: String,
    #[clap(short, long)]
    expensive: bool,
}

fn main() -> Result<()> {
    let opts: Opts = Opts::parse();
    let mut input = String::new();
    File::open(opts.input)?.read_to_string(&mut input)?;
    let numbers = input
        .split(',')
        .filter_map(|n| match n.trim() {
            "" => None,
            n => Some(u32::from_str(n)),
        })
        .collect::<std::result::Result<Vec<_>, _>>()?;
    let (target, score) = optimize(&numbers, opts.expensive);
    println!("Best target is {} with a fuel cost of {}", target, score);
    Ok(())
}

fn optimize(numbers: &[u32], expensive: bool) -> (u32, u32) {
    let min = numbers.iter().min().cloned().unwrap();
    let max = numbers.iter().max().cloned().unwrap();
    (min..=max)
        .map(|t| {
            (
                t,
                calc_fuel(
                    numbers,
                    t,
                    if expensive {
                        expensive_cost_function
                    } else {
                        cheap_cost_function
                    },
                ),
            )
        })
        .min_by_key(|(_, score)| *score)
        .unwrap()
}

fn cheap_cost_function(a: u32, b: u32) -> u32 {
    (a as i64 - b as i64).abs() as u32
}

fn expensive_cost_function(a: u32, b: u32) -> u32 {
    let distance = cheap_cost_function(a, b);
    distance * (distance + 1) / 2
}

fn calc_fuel(numbers: &[u32], target: u32, cost_function: fn(u32, u32) -> u32) -> u32 {
    numbers.iter().map(|n| cost_function(*n, target)).sum()
}

