pub struct ChatLoggerBuilder;

impl ChatLoggerBuilder {
    pub fn new() -> ChatLoggerBuilder {
        ChatLoggerBuilder
    }
}

impl AnalyzerBuilder for ChatLoggerBuilder {
    fn build(&self, meta: &crate::ReplayMeta) -> Box<dyn Analyzer> {
        let version = crate::version::Version::from_client_exe(&meta.clientVersionFromExe);
        Box::new(ChatLogger {
            usernames: HashMap::new(),
            version,
        })
    }
}

pub struct ChatLogger {
    usernames: HashMap<i32, String>,
    version: crate::version::Version,
}

impl Analyzer for ChatLogger {
    fn finish(&self) {}

    fn process(&mut self, packet: &Packet<'_, '_>) {
        let decoded = DecodedPacket::from(&self.version, false, packet);
        match decoded.payload {
            DecodedPacketPayload::Chat {
                sender_id,
                audience,
                message,
                ..
            } => {
                println!(
                    "{}: {}: {} {}",
                    decoded.clock,
                    self.usernames.get(&sender_id).unwrap(),
                    audience,
                    message
                );
            }
            DecodedPacketPayload::VoiceLine {
                sender_id, message, ..
            } => {
                println!(
                    "{}: {}: voiceline {:#?}",
                    decoded.clock,
                    self.usernames.get(&sender_id).unwrap(),
                    message
                );
            }
            DecodedPacketPayload::OnArenaStateReceived { players, .. } => {
                for player in players.iter() {
                    self.usernames
                        .insert(player.avatarid.try_into().unwrap(), player.username.clone());
                }
            }
            _ => {}
        }
    }
}

pub struct PutBack<I: Iterator> {
    it: I,
    slot: Option<I::Item>,
}

impl<I: Iterator> Iterator for PutBack<I> {
    type Item = I::Item;

    fn next(&mut self) -> Option<Self::Item> {
        if let Some(s) = self.slot.take() {
            Some(s)
        } else {
            self.it.next()
        }
    }
}

impl<I: Iterator> PutBack<I> {
    pub fn new(it: I) -> Self {
        Self { it, slot: None }
    }

    /// Put an item back into the iterator. Panics if an item is already on-deck.
    pub fn put_back(&mut self, s: I::Item) {
        if self.slot.is_none() {
            self.slot = Some(s);
        } else {
            panic!("PutBack already had a put-back item on-deck!");
        }
    }
}

