/// A hash based on encoding the complete XdnsRecord
pub type XdnsRecordId<T> = <T as frame_system::Config>::Hash;

/// A hash based on encoding the Gateway ID
pub type XdnsGatewayId<T> = <T as frame_system::Config>::Hash;

/// A preliminary representation of a xdns_record in the onchain registry.
#[derive(Clone, Eq, PartialEq, Encode, Decode, RuntimeDebug)]
#[cfg_attr(feature = "std", derive(Serialize, Deserialize))]
pub struct XdnsRecord<AccountId> {
    /// SCALE-encoded url string on where given Consensus System can be accessed
    pub url: Vec<u8>,

    pub gateway_abi: GatewayABIConfig,

    pub gateway_genesis: GatewayGenesisConfig,

    /// Gateway Vendor
    pub gateway_vendor: GatewayVendor,

    /// Gateway Type
    pub gateway_type: GatewayType,

    /// Gateway Id
    pub gateway_id: ChainId,

    pub registrant: Option<AccountId>,

    pub last_finalized: Option<u64>,
}

impl<AccountId: Encode> XdnsRecord<AccountId> {
    pub fn new_from_primitives(
        url: Vec<u8>,
        gateway_abi: GatewayABIConfig,
        modules_encoded: Option<Vec<u8>>,
        signed_extension: Option<Vec<u8>>,
        runtime_version: sp_version::RuntimeVersion,
        extrinsics_version: u8,
        genesis_hash: Vec<u8>,
        gateway_id: ChainId,
        gateway_vendor: GatewayVendor,
        gateway_type: GatewayType,
        registrant: Option<AccountId>,
        last_finalized: Option<u64>,
    ) -> Self {
        let gateway_genesis = GatewayGenesisConfig {
            modules_encoded,
            signed_extension,
            runtime_version,
            extrinsics_version,
            genesis_hash,
        };

        XdnsRecord {
            url,
            gateway_abi,
            gateway_genesis,
            gateway_vendor,
            gateway_type,
            gateway_id,
            registrant,
            last_finalized,
        }
    }

    pub fn new(
        url: Vec<u8>,
        gateway_id: ChainId,
        gateway_abi: GatewayABIConfig,
        gateway_vendor: GatewayVendor,
        gateway_type: GatewayType,
        gateway_genesis: GatewayGenesisConfig,
    ) -> Self {
        XdnsRecord {
            url,
            gateway_id,
            gateway_abi,
            gateway_vendor,
            gateway_type,
            gateway_genesis,
            registrant: None,
            last_finalized: None,
        }
    }

    pub fn assign_registrant(&mut self, registrant: AccountId) {
        self.registrant = Some(registrant)
    }

    /// Function that generates an XdnsRecordId hash based on the gateway id
    pub fn generate_id<T: Config>(&self) -> XdnsRecordId<T> {
        T::Hashing::hash(Encode::encode(&self.gateway_id).as_ref())
    }

    pub fn set_last_finalized(&mut self, last_finalized: u64) {
        self.last_finalized = Some(last_finalized)
    }
}

// Definition of the pallet logic, to be aggregated at runtime definition through
// `construct_runtime`.
#[frame_support::pallet]
pub mod pallet {
    // Import various types used to declare pallet in scope.
    use super::*;
    use crate::WeightInfo;
    use frame_support::pallet_prelude::*;
    use frame_support::traits::Time;
    use frame_system::pallet_prelude::*;
    use sp_std::convert::TryInto;
    use t3rn_primitives::{ChainId, EscrowTrait, GatewayType, GatewayVendor};

    #[pallet::config]
    pub trait Config: pallet_balances::Config + frame_system::Config + EscrowTrait {
        /// The overarching event type.
        type Event: From<Event<Self>> + IsType<<Self as frame_system::Config>::Event>;

        /// Type representing the weight of this pallet
        type WeightInfo: weights::WeightInfo;
    }

    // Simple declaration of the `Pallet` type. It is placeholder we use to implement traits and
    // method.
    #[pallet::pallet]
    #[pallet::generate_store(pub(super) trait Store)]
    pub struct Pallet<T>(_);

    // Pallet implements [`Hooks`] trait to define some logic to execute in some context.
    #[pallet::hooks]
    impl<T: Config> Hooks<BlockNumberFor<T>> for Pallet<T> {
        // `on_initialize` is executed at the beginning of the block before any extrinsic are
        // dispatched.
        //
        // This function must return the weight consumed by `on_initialize` and `on_finalize`.
        fn on_initialize(_n: T::BlockNumber) -> Weight {
            // Anything that needs to be done at the start of the block.
            // We don't do anything here.
            0
        }

        // `on_finalize` is executed at the end of block after all extrinsic are dispatched.
        fn on_finalize(_n: T::BlockNumber) {
            // Perform necessary data/state clean up here.
        }

        // A runtime code run after every block and have access to extended set of APIs.
        //
        // For instance you can generate extrinsics for the upcoming produced block.
        fn offchain_worker(_n: T::BlockNumber) {
            // We don't do anything here.
            // but we could dispatch extrinsic (transaction/unsigned/inherent) using
            // sp_io::submit_extrinsic.
            // To see example on offchain worker, please refer to example-offchain-worker pallet
            // accompanied in this repository.
        }
    }

    #[pallet::call]
    impl<T: Config> Pallet<T> {
        /// Inserts a xdns_record into the on-chain registry. Root only access.
        #[pallet::weight(<T as Config>::WeightInfo::add_new_xdns_record())]
        pub fn add_new_xdns_record(
            origin: OriginFor<T>,
            url: Vec<u8>,
            gateway_id: ChainId,
            gateway_abi: GatewayABIConfig,
            gateway_vendor: GatewayVendor,
            gateway_type: GatewayType,
            gateway_genesis: GatewayGenesisConfig,
        ) -> DispatchResultWithPostInfo {
            ensure_root(origin)?;

            // ToDo: Uncomment when switching into a model with open registration. Sudo access for now.
            // xdns_record.assign_registrant(registrant.clone());
            let registrant = Default::default();

            let mut xdns_record = XdnsRecord::<T::AccountId>::new(
                url,
                gateway_id,
                gateway_abi,
                gateway_vendor,
                gateway_type,
                gateway_genesis,
            );

            let now = TryInto::<u64>::try_into(<T as EscrowTrait>::Time::now())
                .map_err(|_| "Unable to compute current timestamp")?;

            xdns_record.set_last_finalized(now);

            let xdns_record_id = xdns_record.generate_id::<T>();

            if <XDNSRegistry<T>>::contains_key(&xdns_record_id) {
                Err(Error::<T>::XdnsRecordAlreadyExists.into())
            } else {
                <XDNSRegistry<T>>::insert(&xdns_record_id, xdns_record);
                Self::deposit_event(Event::<T>::XdnsRecordStored(registrant, xdns_record_id));
                Ok(().into())
            }
        }

        /// Updates the last_finalized field for an xdns_record from the onchain registry. Root only access.
        #[pallet::weight(<T as Config>::WeightInfo::update_ttl())]
        pub fn update_ttl(
            origin: OriginFor<T>,
            gateway_id: ChainId,
            last_finalized: u64,
        ) -> DispatchResultWithPostInfo {
            ensure_root(origin)?;
            Self::update_gateway_ttl(gateway_id, last_finalized)
        }

        /// Removes a xdns_record from the onchain registry. Root only access.
        #[pallet::weight(<T as Config>::WeightInfo::purge_xdns_record())]
        pub fn purge_xdns_record(
            origin: OriginFor<T>,
            requester: T::AccountId,
            xdns_record_id: XdnsRecordId<T>,
        ) -> DispatchResultWithPostInfo {
            ensure_root(origin)?;

            if !<XDNSRegistry<T>>::contains_key(&xdns_record_id) {
                Err(Error::<T>::UnknownXdnsRecord)?
            } else {
                <XDNSRegistry<T>>::remove(&xdns_record_id);
                Self::deposit_event(Event::<T>::XdnsRecordPurged(requester, xdns_record_id));
                Ok(().into())
            }
        }
    }

    #[pallet::event]
    #[pallet::generate_deposit(pub(super) fn deposit_event)]
    pub enum Event<T: Config> {
        /// \[requester, xdns_record_id\]
        XdnsRecordStored(T::AccountId, XdnsRecordId<T>),
        /// \[requester, xdns_record_id\]
        XdnsRecordPurged(T::AccountId, XdnsRecordId<T>),
        /// \[xdns_record_id\]
        XdnsRecordUpdated(XdnsRecordId<T>),
    }

    // Errors inform users that something went wrong.
    #[pallet::error]
    pub enum Error<T> {
        /// Stored xdns_record has already been added before
        XdnsRecordAlreadyExists,
        /// Access of unknown xdns_record
        UnknownXdnsRecord,
        /// Xdns Record not found
        XdnsRecordNotFound,
    }

    /// The pre-validated composable xdns_records on-chain registry.
    #[pallet::storage]
    #[pallet::getter(fn xdns_registry)]
    pub type XDNSRegistry<T: Config> =
        StorageMap<_, Blake2_128Concat, XdnsRecordId<T>, XdnsRecord<T::AccountId>, OptionQuery>;

    // The genesis config type.
    #[pallet::genesis_config]
    pub struct GenesisConfig<T: Config> {
        pub known_xdns_records: Vec<XdnsRecord<T::AccountId>>,
    }

    /// The default value for the genesis config type.
    #[cfg(feature = "std")]
    impl<T: Config> Default for GenesisConfig<T> {
        fn default() -> Self {
            Self {
                known_xdns_records: Default::default(),
            }
        }
    }

    /// The build of genesis for the pallet.
    /// Populates storage with the known XDNS Records
    #[pallet::genesis_build]
    impl<T: Config> GenesisBuild<T> for GenesisConfig<T> {
        fn build(&self) {
            for xdns_record in self.known_xdns_records.clone() {
                <XDNSRegistry<T>>::insert(xdns_record.generate_id::<T>(), xdns_record);
            }
        }
    }

    impl<T: Config> Pallet<T> {
        /// Locates the best available gateway based on the time they were last finalized.
        /// Priority goes Internal > External > TxOnly, followed by the largest last_finalized value
        pub fn best_available(
            gateway_id: ChainId,
        ) -> Result<XdnsRecord<T::AccountId>, &'static str> {
            // Sort each available gateway pointer based on its GatewayType
            let gateway_pointers = t3rn_primitives::retrieve_gateway_pointers(gateway_id);
            ensure!(gateway_pointers.is_ok(), "No available gateway pointers");
            let mut sorted_gateway_pointers = gateway_pointers.unwrap();
            sorted_gateway_pointers.sort_by(|a, b| a.gateway_type.cmp(&b.gateway_type));

            // Fetch each XdnsRecord and re-sort based on its last_finalized descending
            let mut sorted_gateways: Vec<XdnsRecord<T::AccountId>> = sorted_gateway_pointers
                .into_iter()
                .map(|gateway_pointer| {
                    <XDNSRegistry<T>>::get(T::Hashing::hash(
                        Encode::encode(&gateway_pointer.id).as_ref(),
                    ))
                })
                .filter(|xdns_record| xdns_record.is_some())
                .map(|xdns_record| xdns_record.unwrap())
                .collect();
            sorted_gateways
                .sort_by(|xdns_a, xdns_b| xdns_b.last_finalized.cmp(&xdns_a.last_finalized));

            // Return the first result
            if sorted_gateways.is_empty() {
                return Err("Xdns record not found");
            }

            Ok(sorted_gateways[0].clone())
        }

        pub fn update_gateway_ttl(
            gateway_id: ChainId,
            last_finalized: u64,
        ) -> DispatchResultWithPostInfo {
            let xdns_record_id = T::Hashing::hash(Encode::encode(&gateway_id).as_ref());

            if !XDNSRegistry::<T>::contains_key(xdns_record_id) {
                Err(Error::<T>::XdnsRecordNotFound.into())
            } else {
                XDNSRegistry::<T>::mutate(xdns_record_id, |xdns_record| match xdns_record {
                    None => Err(Error::<T>::XdnsRecordNotFound),
                    Some(record) => {
                        record.set_last_finalized(last_finalized);
                        Ok(())
                    }
                })?;

                Self::deposit_event(Event::<T>::XdnsRecordUpdated(xdns_record_id));
                Ok(().into())
            }
        }
    }
}

use crate::ffi;
use crate::Lame;
use std::os::raw::c_int;

#[derive(Debug)]
pub enum DecodeError {
    OutputBufferTooSmall,
    NoHeader,
    Unknown(c_int),
}

pub trait Decode<S> {
    fn decode(&mut self, mp3buffer: &[u8], pcm_buffer_l: &mut [S], pcm_buffer_r: &mut [S]) -> Result<usize, DecodeError>;
}

impl Decode<i16> for Lame {
    fn decode(&mut self, mp3buffer: &[u8], pcm_buffer_l: &mut [i16], pcm_buffer_r: &mut [i16]) -> Result<usize, DecodeError> {
        let retn = unsafe {
            ffi::hip_decode(self.hip,
                            mp3buffer.as_ptr(), mp3buffer.len(),
                            pcm_buffer_l.as_mut_ptr(), pcm_buffer_r.as_mut_ptr())
        };
        if retn < 0 { return Err(DecodeError::Unknown(retn)); }
        let decoded_samples = retn;

        Ok(decoded_samples as usize)
    }
}

//! Implementation using ordered keys and exponential search.

use ::difference::Semigroup;

use super::{Trie, Cursor, Builder, MergeBuilder, TupleBuilder, advance};

/// A layer of unordered values.
#[derive(Debug, Eq, PartialEq, Clone, Abomonation)]
pub struct OrderedLeaf<K, R> {
    /// Unordered values.
    pub vals: Vec<(K, R)>,
}

impl<K: Ord+Clone, R: Semigroup+Clone> Trie for OrderedLeaf<K, R> {
    type Item = (K, R);
    type Cursor = OrderedLeafCursor;
    type MergeBuilder = OrderedLeafBuilder<K, R>;
    type TupleBuilder = OrderedLeafBuilder<K, R>;
    fn keys(&self) -> usize { self.vals.len() }
    fn tuples(&self) -> usize { <OrderedLeaf<K, R> as Trie>::keys(&self) }
    fn cursor_from(&self, lower: usize, upper: usize) -> Self::Cursor {
        OrderedLeafCursor {
            bounds: (lower, upper),
            pos: lower,
        }
    }
}

/// A builder for unordered values.
pub struct OrderedLeafBuilder<K, R> {
    /// Unordered values.
    pub vals: Vec<(K, R)>,
}

impl<K: Ord+Clone, R: Semigroup+Clone> Builder for OrderedLeafBuilder<K, R> {
    type Trie = OrderedLeaf<K, R>;
    fn boundary(&mut self) -> usize { self.vals.len() }
    fn done(self) -> Self::Trie { OrderedLeaf { vals: self.vals } }
}

impl<K: Ord+Clone, R: Semigroup+Clone> MergeBuilder for OrderedLeafBuilder<K, R> {
    fn with_capacity(other1: &Self::Trie, other2: &Self::Trie) -> Self {
        OrderedLeafBuilder {
            vals: Vec::with_capacity(<OrderedLeaf<K, R> as Trie>::keys(other1) + <OrderedLeaf<K, R> as Trie>::keys(other2)),
        }
    }
    #[inline]
    fn copy_range(&mut self, other: &Self::Trie, lower: usize, upper: usize) {
        self.vals.extend_from_slice(&other.vals[lower .. upper]);
    }
    fn push_merge(&mut self, other1: (&Self::Trie, usize, usize), other2: (&Self::Trie, usize, usize)) -> usize {

        let (trie1, mut lower1, upper1) = other1;
        let (trie2, mut lower2, upper2) = other2;

        self.vals.reserve((upper1 - lower1) + (upper2 - lower2));

        // while both mergees are still active
        while lower1 < upper1 && lower2 < upper2 {

            match trie1.vals[lower1].0.cmp(&trie2.vals[lower2].0) {
                ::std::cmp::Ordering::Less => {
                    // determine how far we can advance lower1 until we reach/pass lower2
                    let step = 1 + advance(&trie1.vals[(1+lower1)..upper1], |x| x.0 < trie2.vals[lower2].0);
                    let step = std::cmp::min(step, 1000);
                    <OrderedLeafBuilder<K, R> as MergeBuilder>::copy_range(self, trie1, lower1, lower1 + step);
                    lower1 += step;
                }
                ::std::cmp::Ordering::Equal => {

                    let mut sum = trie1.vals[lower1].1.clone();
                    sum += &trie2.vals[lower2].1;
                    if !sum.is_zero() {
                        self.vals.push((trie1.vals[lower1].0.clone(), sum));
                    }

                    lower1 += 1;
                    lower2 += 1;
                }
                ::std::cmp::Ordering::Greater => {
                    // determine how far we can advance lower2 until we reach/pass lower1
                    let step = 1 + advance(&trie2.vals[(1+lower2)..upper2], |x| x.0 < trie1.vals[lower1].0);
                    let step = std::cmp::min(step, 1000);
                    <OrderedLeafBuilder<K, R> as MergeBuilder>::copy_range(self, trie2, lower2, lower2 + step);
                    lower2 += step;
                }
            }
        }

        if lower1 < upper1 { <OrderedLeafBuilder<K, R> as MergeBuilder>::copy_range(self, trie1, lower1, upper1); }
        if lower2 < upper2 { <OrderedLeafBuilder<K, R> as MergeBuilder>::copy_range(self, trie2, lower2, upper2); }

        self.vals.len()
    }
}

impl<K: Ord+Clone, R: Semigroup+Clone> TupleBuilder for OrderedLeafBuilder<K, R> {
    type Item = (K, R);
    fn new() -> Self { OrderedLeafBuilder { vals: Vec::new() } }
    fn with_capacity(cap: usize) -> Self { OrderedLeafBuilder { vals: Vec::with_capacity(cap) } }
    #[inline] fn push_tuple(&mut self, tuple: (K, R)) { self.vals.push(tuple) }
}

/// A cursor for walking through an unordered sequence of values.
///
/// This cursor does not support `seek`, though I'm not certain how to expose this.
#[derive(Debug)]
pub struct OrderedLeafCursor {
    pos: usize,
    bounds: (usize, usize),
}

impl<K: Clone, R: Clone> Cursor<OrderedLeaf<K, R>> for OrderedLeafCursor {
    type Key = (K, R);
    fn key<'a>(&self, storage: &'a OrderedLeaf<K, R>) -> &'a Self::Key { &storage.vals[self.pos] }
    fn step(&mut self, storage: &OrderedLeaf<K, R>) {
        self.pos += 1;
        if !self.valid(storage) {
            self.pos = self.bounds.1;
        }
    }
    fn seek(&mut self, _storage: &OrderedLeaf<K, R>, _key: &Self::Key) {
        panic!("seeking in an OrderedLeafCursor; should be fine, panic is wrong.");
    }
    fn valid(&self, _storage: &OrderedLeaf<K, R>) -> bool { self.pos < self.bounds.1 }
    fn rewind(&mut self, _storage: &OrderedLeaf<K, R>) {
        self.pos = self.bounds.0;
    }
    fn reposition(&mut self, _storage: &OrderedLeaf<K, R>, lower: usize, upper: usize) {
        self.pos = lower;
        self.bounds = (lower, upper);
    }
}

