    fn test_to_url() {
        let uri = Uri::parse("spotify:track:1xQE0QHrmJUQweLoMB0ZWC").unwrap();
        let url = uri.to_url();
        assert_eq!(format!("{}", url), "http://open.spotify.com/track/1xQE0QHrmJUQweLoMB0ZWC".to_string());
