                data: AccountData { data: Bytes::new() },
            }),
        },
        Commitment::Confirmed,
    );

    assert_eq!(accounts.map.len(), 1);

    let acc_ref2 = accounts.insert(
        Pubkey::zero(),
        AccountContext {
            context: SolanaContext { slot: 0 },
            value: Some(AccountInfo {
                executable: false,
                lamports: 1,
