               "unexpected argument");
    assert_eq!(parse_err::<Arg1RawIdent>(r#"(some)node "hello""#),
               "no type name expected for this node");
    assert_eq!(parse_err::<Arg1RawIdent>(r#"node"#),
               "additional argument `type` is required");
}


