pub struct EntityBTreeMapKeys<'a, T: 'a>(btree_map::Keys<'a, EntityId, T>);

impl<'a, T: 'a> Iterator for EntityBTreeMapKeys<'a, T> {
    type Item = EntityId;
    fn next(&mut self) -> Option<Self::Item> {
