pub type BoxedValidateIterator<'a> = Box<dyn Iterator<Item = String> + 'a>;

#[cfg(feature = "std")]
pub trait Writes<W: io::Write> {
    fn write_to(&self, writer: &mut W) -> io::Result<()>;
}

#[cfg(feature = "std")]
pub trait Validate<'a> {
    fn validate(&'a self) -> BoxedValidateIterator<'a>;
}

