	#[serde(skip_serializing_if = "Option::is_none")]
	#[serde(rename = "57")]
	pub target_sub_id: Option<String>,
	/// Trading partner LocationID (i.e. geographic location and/or desk) (Can be embedded within encrypted data section.)
	#[serde(skip_serializing_if = "Option::is_none")]
