#[fasync::run_until_stalled]
#[test]
async fn ready_items_are_yielded() -> Result<(), anyhow::Error> {
    let mut stream_map = StreamMap::new();
    let mut expected_output = HashSet::new();

    for i in 0..100usize {
        let (mut sender, receiver) = mpsc::channel::<usize>(1);
        sender.send(i).await?;
        stream_map.insert(i, receiver).await;
        expected_output.insert(i);
    }

    for i in 0..100usize {
        let next_fut = stream_map.next();
        fasync::pin_mut!(next_fut);
        assert_eq!(futures::poll!(next_fut), Poll::Ready(Some(i)));
    }

    Ok(())
}

#[fasync::run(4)]
#[test]
async fn concurrently_ready_items_are_yielded() -> Result<(), anyhow::Error> {
    let mut stream_map = StreamMap::new();
    let mut expected_output = HashSet::new();

    for i in 0..1000usize {
        let (mut sender, receiver) = mpsc::channel::<usize>(1);
        fasync::spawn(async move {
            sender.send(i).await.expect("Sending message");
        });
        stream_map.insert(i, receiver).await;
        expected_output.insert(i);
    }

    for _ in 0..1000usize {
        assert_matches!(stream_map.next().await, Some(_));
    }

    let next_fut = stream_map.next();
    fasync::pin_mut!(next_fut);
    assert_eq!(futures::poll!(next_fut), Poll::Pending);

    Ok(())
}

#[fasync::run_until_stalled]
#[test]
async fn removed_streams_are_terminated() -> Result<(), anyhow::Error> {
    let mut stream_map = StreamMap::new();
    let (mut sender1, receiver1) = mpsc::channel(1);
    let (mut sender2, receiver2) = mpsc::channel(1);
    sender1.send(1u32).await?;
    sender2.send(2u32).await?;

    let insert1 = stream_map.insert(1u32, receiver1).await;
    let insert2 = stream_map.insert(2u32, receiver2).await;

    assert_matches!(insert1, None);
    assert_matches!(insert2, None);
    assert_matches!(stream_map.remove(1u32).await, Some(_));

    for expected in vec![Poll::Ready(Some(2)), Poll::Pending] {
        let next_fut = stream_map.next();
        fasync::pin_mut!(next_fut);
        assert_eq!(futures::poll!(next_fut), expected);
    }

    Ok(())
}

#[fasync::run_until_stalled]
#[test]
async fn with_elem_has_effect() -> Result<(), anyhow::Error> {
    let mut stream_map = StreamMap::new();
    let (_sender, receiver) = mpsc::channel::<u32>(1);

    stream_map.insert(1u32, receiver).await;

    let mut run_for_present_element = false;
    assert!(
        stream_map
            .with_elem(1u32, |_| {
                run_for_present_element = true;
            })
            .await
    );
    assert!(run_for_present_element);

    let mut run_for_absent_element = false;
    assert!(
        !stream_map
            .with_elem(2u32, |_| {
                run_for_absent_element = true;
            })
            .await
    );
    assert!(!run_for_absent_element);

    Ok(())
}

#[test]
fn awoken_for_mutex_guard() -> Result<(), anyhow::Error> {
    let mut stream_map = StreamMap::new();

    let (_sender1, receiver1) = mpsc::channel::<usize>(1);
    block_on(stream_map.insert(0usize, receiver1));

    let (_sender2, receiver2) = mpsc::channel::<usize>(1);
    block_on(stream_map.insert(0usize, receiver2));

    let store_handle = stream_map.store();
    let guard = block_on(store_handle.lock());

    let (waker, wake_count) = new_count_waker();
    let mut ctx = Context::from_waker(&waker);

    let next_fut = stream_map.next();
    fasync::pin_mut!(next_fut);
    assert_eq!(next_fut.poll(&mut ctx), Poll::Pending);

    assert_eq!(wake_count.get(), 0);
    drop(guard);
    assert_eq!(wake_count.get(), 1);

    Ok(())
}

#[fasync::run_singlethreaded]
#[test]
async fn ended_stream_is_removed_from_map() -> Result<(), anyhow::Error> {
    let mut stream_map = StreamMap::new();

    let (sender, receiver) = mpsc::channel::<usize>(1);
    stream_map.insert(0usize, receiver).await;

    let store = stream_map.store();
    let stream_count = || async { store.lock().await.len() };

    let next_fut = stream_map.next();
    fasync::pin_mut!(next_fut);
    assert_eq!(futures::poll!(next_fut), Poll::Pending);
    assert_eq!(stream_count().await, 1);

    drop(sender);
    let next_fut = stream_map.next();
    fasync::pin_mut!(next_fut);
    assert_eq!(futures::poll!(next_fut), Poll::Pending);
    assert_eq!(stream_count().await, 0);

    Ok(())
}

#[derive(Clone, Copy, Debug, PartialEq, PartialOrd, Ord, Eq, Hash)]
struct TestStream(Option<usize>);

impl FusedStream for TestStream {
    fn is_terminated(&self) -> bool {
        self.0.is_none()
    }
}

impl Stream for TestStream {
    type Item = usize;
    fn poll_next(mut self: Pin<&mut Self>, _cx: &mut Context<'_>) -> Poll<Option<Self::Item>> {
        Poll::Ready(self.0.take())
    }
}

#[fasync::run_singlethreaded(test)]
async fn for_each_stream() {
    let mut stream_map: StreamMap<usize, TestStream> = StreamMap::new();

    stream_map.insert(0, TestStream(Some(0))).await;
    stream_map.insert(1, TestStream(Some(1))).await;
    stream_map.insert(2, TestStream(Some(2))).await;

    let mut seen = hashset! {};
    stream_map
        .for_each_stream(|key: usize, stream: &TestStream| {
            seen.insert((key, *stream));
        })
        .await;

    assert_eq!(
        seen,
        hashset! {(0, TestStream(Some(0))), (1, TestStream(Some(1))), (2, TestStream(Some(2)))}
    );
}

#[fasync::run_singlethreaded(test)]
async fn for_each_stream_mut() {
    let mut stream_map = StreamMap::new();

    stream_map.insert(0, TestStream(Some(0))).await;
    stream_map.insert(1, TestStream(Some(1))).await;
    stream_map.insert(2, TestStream(Some(2))).await;

    stream_map
        .for_each_stream_mut(|k, v| {
            *v = TestStream(Some(k + 1));
        })
        .await;

    let mut seen = hashset! {};
    stream_map
        .for_each_stream(|key: usize, stream: &TestStream| {
            seen.insert((key, *stream));
        })
        .await;

    assert_eq!(
        seen,
        hashset! {(0, TestStream(Some(1))), (1, TestStream(Some(2))), (2, TestStream(Some(3)))}
    );
}

#[fasync::run_singlethreaded(test)]
async fn contains_key() {
    let mut stream_map = StreamMap::new();

    stream_map.insert(0usize, TestStream(Some(0))).await;

    assert!(stream_map.contains_key(0).await);
    assert!(!stream_map.contains_key(1).await);

    stream_map.remove(0usize).await;
    assert!(!stream_map.contains_key(0).await);
}

use crate::derives::attrs::{Attrs, Kind, Name, DEFAULT_CASING, DEFAULT_ENV_CASING};
use crate::derives::{from_argmatches, into_app, spanned::Sp};

use proc_macro2::{Ident, Span, TokenStream};
use proc_macro_error::{abort, abort_call_site};
use quote::{quote, quote_spanned};
use syn::{
    punctuated::Punctuated, spanned::Spanned, Attribute, DataEnum, FieldsUnnamed, Token, Variant,
};

pub fn gen_for_enum(name: &Ident, attrs: &[Attribute], e: &DataEnum) -> TokenStream {
    let attrs = Attrs::from_struct(
        Span::call_site(),
        attrs,
        Name::Derived(name.clone()),
        Sp::call_site(DEFAULT_CASING),
        Sp::call_site(DEFAULT_ENV_CASING),
    );

    let from_subcommand = gen_from_subcommand(name, &e.variants, &attrs);
    let augment_subcommands = gen_augment_subcommands(&e.variants, &attrs);

    quote! {
        #[allow(dead_code, unreachable_code, unused_variables)]
        #[allow(
            clippy::style,
            clippy::complexity,
            clippy::pedantic,
            clippy::restriction,
            clippy::perf,
            clippy::deprecated,
            clippy::nursery,
            clippy::cargo
        )]
        #[deny(clippy::correctness)]
        impl ::clap::Subcommand for #name {
            #augment_subcommands
            #from_subcommand
        }
    }
}

fn gen_augment_subcommands(
    variants: &Punctuated<syn::Variant, Token![,]>,
    parent_attribute: &Attrs,
) -> proc_macro2::TokenStream {
    use syn::Fields::*;

    let subcommands = variants.iter().map(|variant| {
        let attrs = Attrs::from_struct(
            variant.span(),
            &variant.attrs,
            Name::Derived(variant.ident.clone()),
            parent_attribute.casing(),
            parent_attribute.env_casing(),
        );
        let kind = attrs.kind();
        match &*kind {
            Kind::Flatten => match variant.fields {
                Unnamed(FieldsUnnamed { ref unnamed, .. }) if unnamed.len() == 1 => {
                    let ty = &unnamed[0];
                    quote! {
                        let app = <#ty as ::clap::Subcommand>::augment_subcommands(app);
                    }
                }
                _ => abort!(
                    variant,
                    "`flatten` is usable only with single-typed tuple variants"
                ),
            },

            _ => {
                let app_var = Ident::new("subcommand", Span::call_site());
                let arg_block = match variant.fields {
                    Named(ref fields) => {
                        into_app::gen_app_augmentation(&fields.named, &app_var, &attrs)
                    }
                    Unit => quote!( #app_var ),
                    Unnamed(FieldsUnnamed { ref unnamed, .. }) if unnamed.len() == 1 => {
                        let ty = &unnamed[0];
                        quote_spanned! { ty.span()=>
                            {
                                <#ty as ::clap::IntoApp>::augment_clap(#app_var)
                            }
                        }
                    }
                    Unnamed(..) => {
                        abort!(variant, "non single-typed tuple enums are not supported")
                    }
                };

                let name = attrs.cased_name();
                let from_attrs = attrs.top_level_methods();
                let version = attrs.version();
                quote! {
                    let app = app.subcommand({
                        let #app_var = ::clap::App::new(#name);
                        let #app_var = #arg_block;
                        #app_var#from_attrs#version
                    });
                }
            }
        }
    });

    let app_methods = parent_attribute.top_level_methods();
    let version = parent_attribute.version();
    quote! {
        fn augment_subcommands<'b>(app: ::clap::App<'b>) -> ::clap::App<'b> {
            let app = app #app_methods;
            #( #subcommands )*;
            app #version
        }
    }
}

fn gen_from_subcommand(
    name: &syn::Ident,
    variants: &Punctuated<Variant, Token![,]>,
    parent_attribute: &Attrs,
) -> proc_macro2::TokenStream {
    use syn::Fields::*;
    let (flatten_variants, variants): (Vec<_>, Vec<_>) = variants
        .iter()
        .map(|variant| {
            let attrs = Attrs::from_struct(
                variant.span(),
                &variant.attrs,
                Name::Derived(variant.ident.clone()),
                parent_attribute.casing(),
                parent_attribute.env_casing(),
            );
            (variant, attrs)
        })
        .partition(|(_, attrs)| {
            let kind = attrs.kind();
            match &*kind {
                Kind::Flatten => true,
                _ => false,
            }
        });

    let match_arms = variants.iter().map(|(variant, attrs)| {
        let sub_name = attrs.cased_name();
        let variant_name = &variant.ident;
        let constructor_block = match variant.fields {
            Named(ref fields) => from_argmatches::gen_constructor(&fields.named, &attrs),
            Unit => quote!(),
            Unnamed(ref fields) if fields.unnamed.len() == 1 => {
                let ty = &fields.unnamed[0];
                quote!( ( <#ty as ::clap::FromArgMatches>::from_arg_matches(matches) ) )
            }
            Unnamed(..) => abort_call_site!("{}: tuple enums are not supported", variant.ident),
        };

        quote! {
            (#sub_name, Some(matches)) => {
                Some(#name :: #variant_name #constructor_block)
            }
        }
    });
    let child_subcommands = flatten_variants.iter().map(|(variant, _attrs)| {
        let variant_name = &variant.ident;
        match variant.fields {
            Unnamed(ref fields) if fields.unnamed.len() == 1 => {
                let ty = &fields.unnamed[0];
                quote! {
                    if let Some(res) = <#ty as ::clap::Subcommand>::from_subcommand(other.0, other.1) {
                        return Some(#name :: #variant_name (res));
                    }
                }
            }
            _ => abort!(
                variant,
                "`flatten` is usable only with single-typed tuple variants"
            ),
        }
    });

    quote! {
        fn from_subcommand<'b>(
            name: &'b str,
            sub: Option<&'b ::clap::ArgMatches>) -> Option<Self>
        {
            match (name, sub) {
                #( #match_arms ),*,
                other => {
                    #( #child_subcommands )*;
                    None
                }
            }
        }
    }
}

use std::path::Path;
use std::str::FromStr;

use common::{
    parse_break_test, parse_codepoint_association, CodepointIter, Codepoints,
    UcdFile, UcdFileByCodepoint,
};
use error::Error;

/// A single row in the `auxiliary/SentenceBreakProperty.txt` file.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct SentenceBreak {
    /// The codepoint or codepoint range for this entry.
    pub codepoints: Codepoints,
    /// The property value assigned to the codepoints in this entry.
    pub value: String,
}

impl UcdFile for SentenceBreak {
    fn relative_file_path() -> &'static Path {
        Path::new("auxiliary/SentenceBreakProperty.txt")
    }
}

impl UcdFileByCodepoint for SentenceBreak {
    fn codepoints(&self) -> CodepointIter {
        self.codepoints.into_iter()
    }
}

impl FromStr for SentenceBreak {
    type Err = Error;

    fn from_str(line: &str) -> Result<SentenceBreak, Error> {
        let (codepoints, value) = parse_codepoint_association(line)?;
        Ok(SentenceBreak { codepoints: codepoints, value: value.to_string() })
    }
}

/// A single row in the `auxiliary/SentenceBreakTest.txt` file.
///
/// This file defines tests for the sentence break algorithm.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct SentenceBreakTest {
    /// Each string is a UTF-8 encoded group of codepoints that make up a
    /// single sentence.
    pub sentences: Vec<String>,
    /// A human readable description of this test.
    pub comment: String,
}

impl UcdFile for SentenceBreakTest {
    fn relative_file_path() -> &'static Path {
        Path::new("auxiliary/SentenceBreakTest.txt")
    }
}

impl FromStr for SentenceBreakTest {
    type Err = Error;

    fn from_str(line: &str) -> Result<SentenceBreakTest, Error> {
        let (groups, comment) = parse_break_test(line)?;
        Ok(SentenceBreakTest { sentences: groups, comment: comment })
    }
}

#[cfg(test)]
mod tests {
    use super::{SentenceBreak, SentenceBreakTest};

    #[test]
    fn parse_single() {
        let line = "11445         ; Extend # Mc       NEWA SIGN VISARGA\n";
        let row: SentenceBreak = line.parse().unwrap();
        assert_eq!(row.codepoints, 0x11445);
        assert_eq!(row.value, "Extend");
    }

    #[test]
    fn parse_range() {
        let line = "FE31..FE32    ; SContinue # Pd   [2] PRESENTATION FORM FOR VERTICAL EM DASH..PRESENTATION FORM FOR VERTICAL EN DASH\n";
        let row: SentenceBreak = line.parse().unwrap();
        assert_eq!(row.codepoints, (0xFE31, 0xFE32));
        assert_eq!(row.value, "SContinue");
    }

    #[test]
    fn parse_test() {
        let line = "÷ 2060 × 5B57 × 2060 × 002E × 2060 ÷ 5B57 × 2060 × 2060 ÷	#  ÷ [0.2] WORD JOINER (Format_FE) × [998.0] CJK UNIFIED IDEOGRAPH-5B57 (OLetter) × [5.0] WORD JOINER (Format_FE) × [998.0] FULL STOP (ATerm) × [5.0] WORD JOINER (Format_FE) ÷ [11.0] CJK UNIFIED IDEOGRAPH-5B57 (OLetter) × [5.0] WORD JOINER (Format_FE) × [5.0] WORD JOINER (Format_FE) ÷ [0.3]";

        let row: SentenceBreakTest = line.parse().unwrap();
        assert_eq!(
            row.sentences,
            vec![
                "\u{2060}\u{5B57}\u{2060}\u{002E}\u{2060}",
                "\u{5B57}\u{2060}\u{2060}",
            ]
        );
        assert!(row.comment.contains("[5.0] WORD JOINER (Format_FE)"));
    }
}

use super::traits::Instrument;
use crate::definitions::Money;
use crate::patterns::LazyObject;
use crate::pricingengines::{Arguments, PricingEngine, Results};
use crate::time::Date;
use std::collections::HashMap;

#[derive(Default, Clone)]
pub struct Base<PE: PricingEngine> {
    lazy: LazyObject,
    npv: Money,
    error_estimate: Money,
    valuation_date: Date,
    additional_results: HashMap<String, Money>,
    engine: PE,
    has_engine: bool,
}

impl<PE> Instrument for Base<PE>
where
    PE: PricingEngine,
{
    type E = PE;
    /// returns the net present value of the instrument.
    fn npv(&mut self) -> Money {
        self.calculate();
        assert!(self.npv != Money::default());
        self.npv
    }
    /// returns the error estimate on the NPV when available.
    fn error_estimate(&mut self) -> Money {
        self.calculate();
        assert!(self.error_estimate != Money::default());
        self.error_estimate
    }
    /// returns the date the net present value refers to.
    fn valuation_date(&mut self) -> Date {
        self.calculate();
        assert!(self.valuation_date != Date::default());
        self.valuation_date
    }
    /// returns any additional result returned by the pricing engine.
    fn result(&mut self, tag: String) -> Result<Money, &str> {
        self.calculate();
        let m = self.additional_results.get(&tag);
        if m.is_none() {
            return Err("not found");
        }
        Ok(*m.unwrap())
    }
    /// returns any additional result returned by the pricing engine.
    fn additional_results(&self) -> &HashMap<String, Money> {
        &self.additional_results
    }
    /// returns whether the instrument might have value greater than zero.
    fn is_expired(&self) -> bool {
        false
    }
    /// set the pricing engine to be used.
    fn set_pricing_engine(&mut self, engine: Self::E) {
        if self.has_engine {
            // TODO: unregister.
            self.engine = engine;
            self.has_engine = true;
        }
        if self.has_engine {
            // TODO: register.
            //registerWith(engine_);
        }
        // trigger (lazy) recalculation and notify observers
        self.lazy.update();
    }
    /// When a derived argument structure is defined for an
    /// instrument, this method should be overridden to fill
    /// it. This is mandatory in case a pricing engine is used.
    fn setup_arguments<A: Arguments>(&self, _args: A) {
        unimplemented!();
    }
    /// When a derived result structure is defined for an
    /// instrument, this method should be overridden to read from
    /// it. This is mandatory in case a pricing engine is used.
    fn fetch_results<R: Results>(&mut self, results: R) {
        let r = results.get();
        self.npv = r.value;
        self.error_estimate = r.error_estimate;
        self.valuation_date = r.valuation_date;
        self.additional_results = r.additional_results.clone();
    }

    fn calculate(&mut self) {
        if !self.lazy.calculated {
            if self.is_expired() {
                self.setup_expired();
                self.lazy.calculated = true;
            } else {
                self.lazy.calculate();
            }
        }
    }
    ///
    fn setup_expired(&mut self) {
        self.npv = Money::default();
        self.error_estimate = Money::default();
        self.valuation_date = Date::default();
        self.additional_results.clear();
    }
    ///
    fn perform_calculations(&mut self) {
        assert!(self.has_engine);
        self.engine.reset();
        self.setup_arguments(self.engine.get_arguments());
        self.engine.get_arguments().validate();
        self.engine.calculate();
        self.fetch_results(self.engine.get_results());
    }
}

use super::driver::*;
use super::XlsxError;
use quick_xml::events::{BytesDecl, Event};
use quick_xml::Writer;
use std::io;
use std::result;
use structs::SharedStringTable;

const SHARED_STRINGS: &'static str = "sharedStrings.xml";

pub(crate) fn write<W: io::Seek + io::Write>(
    shared_string_table: &SharedStringTable,
    arv: &mut zip::ZipWriter<W>,
) -> result::Result<(), XlsxError> {
    if shared_string_table.get_shared_string_item().len() == 0 {
        return Ok(());
    }

    let mut writer = Writer::new(io::Cursor::new(Vec::new()));
    // XML header
    let _ = writer.write_event(Event::Decl(BytesDecl::new(
        b"1.0",
        Some(b"UTF-8"),
        Some(b"yes"),
    )));
    write_new_line(&mut writer);

    shared_string_table.write_to(&mut writer);

    let _ = make_file_from_writer(SHARED_STRINGS, arv, writer, Some("xl"))?;
    Ok(())
}

