                App::new()
                    .app_data(web::Data::new(tmp_state.clone()))
                    .service(index)
            })
            .bind(new_url.clone())
            {
                server = Some(ser);
                url = Some(new_url);
                break;
            }
        }

        let server = server.expect("Could not bind to port from 9000 to 9999");
        let (abort_handle, abort_registration) = AbortHandle::new_pair();
        let future = Abortable::new(server.run(), abort_registration);
        tokio::spawn(future);
        let address = format!("http://{}/", &url.unwrap());
        (address, abort_handle)
    }

    #[actix_rt::test]
    async fn run_client() {
        let (address, abort_handle) = run_server(State {
            key_pairs: vec![Random.generate()],
        });
        // Get address is ok,  unlock address is ok, recover address from signature is also ok
        let client = JsonRpcSigner::new(address, None, None, None).await.unwrap();
        let msg = b"some_text_message";
        if let TxEthSignature::EthereumSignature(signature) =
            client.sign_message(msg).await.unwrap()
        {
            assert!(is_signature_from_address(&signature, msg, client.address().unwrap()).unwrap())
        } else {
            panic!("Wrong signature type")
        }
        let transaction_signature = client
            .sign_transaction(RawTransaction {
                chain_id: 0,
                nonce: Default::default(),
                to: None,
                value: Default::default(),
                gas_price: Default::default(),
                gas: Default::default(),
                data: vec![],
            })
            .await
            .unwrap();
        assert_ne!(transaction_signature.len(), 0);
        abort_handle.abort();
    }
}

use types::Address;
use crypto::ToBase58Check;
use crate::api::{
    GetContractDelegate, GetContractDelegateResult,
    TransportError, GetContractDelegateError, GetContractDelegateErrorKind,
};
use crate::http_api::HttpApi;

fn get_contract_delegate_url(base_url: &str, addr: &Address) -> String {
    format!(
        "{}/chains/main/blocks/head/context/contracts/{}/delegate",
        base_url,
        addr.to_base58check(),
    )
}

impl From<ureq::Error> for GetContractDelegateErrorKind {
    fn from(error: ureq::Error) -> Self {
        match error {
            ureq::Error::Transport(error) => {
                Self::Transport(TransportError(Box::new(error)))
            }
            ureq::Error::Status(code, resp) => {
                let status_text = resp.status_text().to_string();
                Self::Unknown(format!(
                    "Http status: ({}, {}){}",
                    code,
                    status_text,
                    match resp.into_string() {
                        Ok(s) => format!(", message: {}", s),
                        Err(_) => "".to_string(),
                    },
                ))
            }
        }
    }
}

impl From<std::io::Error> for GetContractDelegateErrorKind {
    fn from(error: std::io::Error) -> Self {
        Self::Transport(TransportError(Box::new(error)))
    }
}

#[inline]
fn build_error<E>(address: &Address, kind: E) -> GetContractDelegateError
    where E: Into<GetContractDelegateErrorKind>,
{
    GetContractDelegateError {
        address: address.clone(),
        kind: kind.into(),
    }
}

impl GetContractDelegate for HttpApi {
    fn get_contract_delegate(&self, addr: &Address) -> GetContractDelegateResult {
        Ok(self.client.get(&get_contract_delegate_url(&self.base_url, addr), &"HttpApi > get_contract_delegate")
           .call()
           .map(|resp| resp.into_json())
           .or_else(|err| {
               match &err {
                   // will return 404 status if `addr` hasn't an active delegation.
                   ureq::Error::Status(404, _) => Ok(Ok(None)),
                   _ => Err(build_error(addr, err))
               }
           })?
           .map_err(|err| build_error(addr, err))?)
    }
}

