        #[test]
        fn did_syntax_tests() {
            let _err = DidUrl::from_str("did:indy:onlynamespace").unwrap_err();

            assert_eq!(
                DidUrl::from_str("did:indy:idunion:BDrEcHc8Tb4Lb2VyQZWEDE").unwrap(),
                DidUrl {
                    namespace: String::from("idunion"),
                    id: DidValue::new("BDrEcHc8Tb4Lb2VyQZWEDE", None),
