                    id: DidValue::new("6cgbu8ZPoWTnR5Rv5JcSMB", None),
                    path: None,
                    query: HashMap::new(),
                    url: String::from("did:indy:sovrin:staging:6cgbu8ZPoWTnR5Rv5JcSMB"),
