        .await?
        .assert_table("Test", |table| table.assert_does_not_have_column("Int"))?;

    let rows = api.select("Test").column("id").column("name").send_debug().await?;
    assert_eq!(rows, &[&[r#"Text("abc")"#, r#"Text("george")"#]]);

    Ok(())
}

