/// async-std 1 runtime
#[derive(Default, Clone)]
pub struct Runtime {}

impl crate::Runtime for Runtime {
    fn sleep(&self, duration: Duration) -> BoxFuture<'static, ()> {
        Box::pin(async_std_1::task::sleep(duration))
