#[derive(Debug)]
pub struct Token {
    inner: String,
}

impl Token {
    pub fn new(inner: &str) -> Self {
        Self {
            inner: inner.to_owned(),
        }
    }
}

impl Deref for Token {
    type Target = str;

    fn deref(&self) -> &str {
        &self.inner
    }
}

