                Some(file_path) => {
                    let path = PathBuf::from(file_path)
                    .parent()
                    .unwrap()
                    .join("left4dead2")
                    .join("addons");
                    if !path.exists() {
                        println!("A valid directory was not specified. Exiting.");
                        std::process::exit(1);
                    }
