    fn tile_no_walk() -> Tile {
        Tile {
            height: 0,
            depth: 0,
            slope_type: 0,
            surface_type: 0,
            slope_height: 0,
            no_cursor: true,
            no_walk: true,
        }
    }

    fn make_simple_map() -> Arena {
        let tile = Tile {
            height: 0,
            depth: 0,
            slope_type: 0,
            surface_type: 0,
            slope_height: 0,
            no_cursor: false,
            no_walk: false,
        };
        let mut tiles = vec![];
        for _i in 0..100 {
            tiles.push(tile);
        }
        let mut upper = vec![];
        upper.resize(100, tile_no_walk());
        Arena {
            lower: tiles,
            upper,
            width: 10,
            height: 10,
            starting_locations: vec![],
        }
    }

    #[test]
    pub fn matches_diamond() {
        let arena = make_simple_map();
        let mut pathfinder = Pathfinder::new(&arena);
        let center = Panel::coords(5, 5, false);
        for movement in 0..4 {
            let movement_info = MovementInfo {
                movement,
                horizontal_jump: 0,
                vertical_jump: 0,
                fly_teleport: false,
                water_ok: false,
            };
            pathfinder.calculate_reachable(&movement_info, center);
            for panel in center.diamond(movement) {
                assert_eq!(pathfinder.is_reachable(panel), true);
            }
        }
    }

    fn make_impassible_map() -> Arena {
        let walk = Tile {
            height: 0,
            depth: 0,
            slope_type: 0,
            surface_type: 0,
            slope_height: 0,
            no_cursor: false,
            no_walk: false,
        };
        let no_walk = tile_no_walk();
        let mut tiles = vec![];
        for _i in 0..2 {
            tiles.push(walk);
        }
        tiles.push(no_walk);
        for _i in 0..2 {
            tiles.push(walk);
        }
        let mut upper = vec![];
        upper.resize(5, no_walk);
        Arena {
            lower: tiles,
            upper,
            width: 5,
            height: 1,
            starting_locations: vec![],
        }
    }

    fn make_high_slope_map() -> Arena {
        let walk = Tile {
            height: 0,
            depth: 0,
            slope_type: SLOPE_FLAT_0,
            surface_type: 0,
            slope_height: 0,
            no_cursor: false,
            no_walk: false,
        };
        let up_east = Tile {
            height: 0,
            depth: 0,
            slope_type: SLOPE_INCLINE_E,
            surface_type: 0,
            slope_height: 8,
            no_cursor: false,
            no_walk: false,
        };
        let up_west = Tile {
            height: 0,
            depth: 0,
