    fn make_bridge_map() -> Arena {
        let walk = Tile {
            height: 0,
            depth: 0,
            slope_type: SLOPE_FLAT_0,
            surface_type: 0,
            slope_height: 0,
            no_cursor: false,
            no_walk: false,
        };
        let up_east = Tile {
            height: 0,
            depth: 0,
            slope_type: SLOPE_INCLINE_E,
            surface_type: 0,
            slope_height: 8,
            no_cursor: false,
            no_walk: false,
        };
        let up_west = Tile {
            height: 0,
            depth: 0,
            slope_type: SLOPE_INCLINE_W,
            surface_type: 0,
            slope_height: 8,
            no_cursor: false,
            no_walk: false,
        };
        let middle = Tile {
            height: 8,
            depth: 0,
            slope_type: SLOPE_FLAT_0,
            surface_type: 0,
            slope_height: 0,
            no_cursor: false,
            no_walk: false,
        };
        let tiles = vec![walk, up_east, walk, walk, up_west, walk];
        let mut upper = vec![];
        upper.resize(6, tile_no_walk());
