use core_command::command;
use core_exception::{ErrorCode, Result};
use serde_json::Value;

pub fn parse_sql_stmts(data: &str) -> Result<Vec<command::Statement>> {
    fn parse_parameter_val(jv: &Value) -> Result<command::parameter::Value> {
        let cv = match jv {
            Value::Bool(bv) => command::parameter::Value::B(*bv),
            Value::Number(nv) => {
                if nv.is_f64() {
                    let fv = nv.as_f64().unwrap();
                    command::parameter::Value::D(fv)
                } else if nv.is_i64() {
                    let iv = nv.as_i64().unwrap();
                    command::parameter::Value::I(iv)
                } else if nv.is_u64() {
                    let uv = nv.as_u64().unwrap();
                    command::parameter::Value::I(uv as i64)
                } else {
                    return Err(ErrorCode::BadRequest("invalid sql request"));
                }
            }
            Value::String(sv) => command::parameter::Value::S(String::from(sv)),
            _ => return Err(ErrorCode::BadRequest("invalid sql request")),
        };
        Ok(cv)
    }

    fn parse_parameter(jv: &Value, params: &mut Vec<command::Parameter>) -> Result<()> {
        match jv {
            Value::Object(ov) => {
                // named parameter
                for (k, v) in ov {
                    let pv = parse_parameter_val(&v)?;
                    let p = command::Parameter {
                        name: String::from(k),
                        value: Some(pv),
                    };
                    params.push(p);
                }
            }
            _ => {
                let pv = parse_parameter_val(&*jv)?;
                let p = command::Parameter {
                    value: Some(pv),
                    ..Default::default()
                };
                params.push(p);
            }
        };
        Ok(())
    }

    let v: Value = serde_json::from_str(data)?;
    let mut stmts = vec![];

    match v {
        Value::Array(arr) => {
            for item in arr.iter() {
                let stmt = match item {
                    Value::Array(arr1) => {
                        if arr1.len() < 1 {
                            return Err(ErrorCode::BadRequest("need SQL statment"));
                        }
                        let mut stmt = command::Statement::default();
                        match arr1[0].as_str() {
                            Some(sql) => stmt.sql = String::from(sql),
                            None => return Err(ErrorCode::BadRequest("need SQL statment")),
                        };
                        for item1 in arr1[1..].iter() {
                            parse_parameter(item1, &mut stmt.parameters)?
                        }
                        stmt
                    }
                    Value::String(sv) => command::Statement {
                        sql: String::from(sv),
                        ..Default::default()
                    },
                    _ => return Err(ErrorCode::BadRequest("invalid sql request")),
                };
                stmts.push(stmt);
            }
        }
        _ => return Err(ErrorCode::BadRequest("invalid sql request")),
    }
    Ok(stmts)
}

use amethyst::{
    ecs::*,
    input::{InputEvent, StringBindings},
    shrev::{EventChannel, ReaderId},
    ui::*,
};

pub struct ButtonInfo {
    pub name: &'static str,
    pub text: &'static str,
    pub action: &'static str,
}

const DEFAULT_BUTTON: ButtonInfo = ButtonInfo {
    name: "",
    text: "",
    action: "",
};

impl Default for &ButtonInfo {
    fn default() -> Self {
        &DEFAULT_BUTTON
    }
}

// centralize the button strings here (used in both button creation and response logic)
// NOTE name and text will need to be kept in alignment with main_game.ron; action will need to be kept in alignment with input.ron
pub const MENU_BUTTON: ButtonInfo = ButtonInfo {
    name: "menu button",
    text: "Menu",
    action: "Menu",
};
pub const PAUSE_BUTTON: ButtonInfo = ButtonInfo {
    name: "pause button",
    text: "Pause",
    action: "TogglePause",
};
pub const SLOW_DOWN_BUTTON: ButtonInfo = ButtonInfo {
    name: "slow down button",
    text: "Slow Down",
    action: "SlowDown",
};
pub const SPEED_UP_BUTTON: ButtonInfo = ButtonInfo {
    name: "speed up button",
    text: "Speed Up",
    action: "SpeedUp",
};

pub const BUTTON_INFOS: [&ButtonInfo; 4] = [
    &MENU_BUTTON,
    &PAUSE_BUTTON,
    &SLOW_DOWN_BUTTON,
    &SPEED_UP_BUTTON,
];

#[derive(Default)]
struct Button {
    info: &'static ButtonInfo,
    entity: Option<Entity>,
}

#[derive(Default)]
pub struct MainGameUiSystem {
    ui_reader_id: Option<ReaderId<UiEvent>>,
    input_reader_id: Option<ReaderId<InputEvent<StringBindings>>>,
    buttons: Vec<Button>,
    pause_button_text: Option<Entity>,
}

// implementation-specific, hidden way of producing the name of a button's child text widget, given the button name
fn make_ui_text_name(button_name: &str) -> String {
    format!("{}_btn_txt", button_name)
}

impl<'s> MainGameUiSystem {
    fn find_ui_elements(&mut self, finder: &UiFinder) {
        if self.buttons.is_empty() {
            self.buttons = BUTTON_INFOS
                .iter()
                .map(|info| Button {
                    info,
                    entity: finder.find(info.name),
                })
                .collect::<Vec<Button>>();
            self.pause_button_text = finder.find(&make_ui_text_name(PAUSE_BUTTON.name));
        }
    }

    // translate ui button clicks into input actions for registered buttons
    fn translate_click(
        &self,
        clicked: Entity,
        input_events: &mut Write<'s, EventChannel<InputEvent<StringBindings>>>,
    ) {
        if let Some(button) = self
            .buttons
            .iter()
            .find(|button| button.entity == Some(clicked))
        {
            input_events.single_write(InputEvent::ActionPressed(button.info.action.to_string()));
        }
    }

    fn handle_action(&self, action: &str, ui_texts: &mut WriteStorage<'s, UiText>) {
        // only one action handled right now; change to 'match' when we handle more
        if action != PAUSE_BUTTON.action {
            return;
        }

        // toggle text between 'Play' and 'Pause' depending on what the next click will do
        const PAUSE_TEXT: &str = PAUSE_BUTTON.text;
        const PLAY_TEXT: &str = "Play";
        if let Some(text_entity) = self.pause_button_text {
            if let Some(ui_text) = ui_texts.get_mut(text_entity) {
                if ui_text.text == PAUSE_TEXT {
                    ui_text.text = PLAY_TEXT.to_string();
                } else if ui_text.text == PLAY_TEXT {
                    ui_text.text = PAUSE_TEXT.to_string();
                }
            }
        }
    }
}

impl<'s> System<'s> for MainGameUiSystem {
    type SystemData = (
        UiFinder<'s>,
        Read<'s, EventChannel<UiEvent>>,
        WriteStorage<'s, UiText>,
        Write<'s, EventChannel<InputEvent<StringBindings>>>,
    );

    fn setup(&mut self, res: &mut Resources) {
        Self::SystemData::setup(res);
        self.ui_reader_id = Some(res.fetch_mut::<EventChannel<UiEvent>>().register_reader());
        self.input_reader_id = Some(
            res.fetch_mut::<EventChannel<InputEvent<StringBindings>>>()
                .register_reader(),
        );
    }

    fn run(&mut self, (ui_finder, ui_events, mut ui_texts, mut input_events): Self::SystemData) {
        self.find_ui_elements(&ui_finder);

        ui_events
            .read(self.ui_reader_id.as_mut().unwrap())
            // filter for Clicks; change to 'match' when other UiEventType variants need to be handled
            .filter(|event| event.event_type == UiEventType::Click)
            .for_each(|event| self.translate_click(event.target, &mut input_events));

        input_events
            .read(self.input_reader_id.as_mut().unwrap())
            .for_each(|event| {
                // change from if-let to match when more InputEvent variants need to be handled
                if let InputEvent::ActionPressed(action_name) = event {
                    self.handle_action(action_name, &mut ui_texts);
                }
            });
    }
}

use crate::TxPool;
use ckb_error::{AnyError, OtherError};
use ckb_types::{
    core::TransactionView,
    packed::{TransactionVec, TransactionVecReader},
    prelude::*,
};
use std::{
    fs::OpenOptions,
    io::{Read as _, Write as _},
};

/// The version of the persisted tx-pool data.
pub(crate) const VERSION: u32 = 1;

impl TxPool {
    pub(crate) fn load_from_file(&self) -> Result<Vec<TransactionView>, AnyError> {
        let mut persisted_data_file = self.config.persisted_data.clone();
        persisted_data_file.set_extension(format!("v{}", VERSION));

        if persisted_data_file.exists() {
            let mut file = OpenOptions::new()
                .read(true)
                .open(&persisted_data_file)
                .map_err(|err| {
                    let errmsg = format!(
                        "Failed to open the tx-pool persisted data file [{:?}], cause: {}",
                        persisted_data_file, err
                    );
                    OtherError::new(errmsg)
                })?;
            let mut buffer = Vec::new();
            file.read_to_end(&mut buffer).map_err(|err| {
                let errmsg = format!(
                    "Failed to read the tx-pool persisted data file [{:?}], cause: {}",
                    persisted_data_file, err
                );
                OtherError::new(errmsg)
            })?;

            let persisted_data = TransactionVecReader::from_slice(&buffer)
                .map_err(|err| {
                    let errmsg = format!(
                        "The tx-pool persisted data file [{:?}] is broken, cause: {}",
                        persisted_data_file, err
                    );
                    OtherError::new(errmsg)
                })?
                .to_entity();

            Ok(persisted_data
                .into_iter()
                .map(|tx| tx.into_view())
                .collect())
        } else {
            Ok(Vec::new())
        }
    }

    pub(crate) fn save_into_file(&mut self) -> Result<(), AnyError> {
        let mut persisted_data_file = self.config.persisted_data.clone();
        persisted_data_file.set_extension(format!("v{}", VERSION));

        let mut file = OpenOptions::new()
            .create(true)
            .write(true)
            .truncate(true)
            .open(&persisted_data_file)
            .map_err(|err| {
                let errmsg = format!(
                    "Failed to open the tx-pool persisted data file [{:?}], cause: {}",
                    persisted_data_file, err
                );
                OtherError::new(errmsg)
            })?;

        let txs = TransactionVec::new_builder()
            .extend(self.drain_all_transactions().iter().map(|tx| tx.data()))
            .build();

        file.write_all(txs.as_slice()).map_err(|err| {
            let errmsg = format!(
                "Failed to write the tx-pool persisted data into file [{:?}], cause: {}",
                persisted_data_file, err
            );
            OtherError::new(errmsg)
        })?;
        file.sync_all().map_err(|err| {
            let errmsg = format!(
                "Failed to sync the tx-pool persisted data file [{:?}], cause: {}",
                persisted_data_file, err
            );
            OtherError::new(errmsg)
        })?;
        Ok(())
    }
}

use super::{
    entity::{Master, Password},
    Decrypted, Encrypted, EntryKey, KyEnv, KyError, KyResult, KyTable, MASTER,
};
use crate::lib::Cipher;
use csv::{Reader, Writer};
use serde::{Deserialize, Serialize};
use std::{fs::File, path::Path};

/// Row represent a csv row.
/// NOTE: don't change the sequence of fields because it's same as 1Password csv export
#[derive(Debug, Serialize, Deserialize)]
struct Row {
    title: EntryKey,
    website: String,
    username: String,
    password: String,
    notes: String,
    expires: String,
}

pub struct Vault<'a> {
    src: &'a Path,
}

impl<'a> Vault<'a> {
    pub fn new(src: &'a Path) -> Self {
        Self { src }
    }

    pub fn backup(&self, dest: &'a Path) -> KyResult<File> {
        let mut tar = tar::Builder::new(Vec::new());

        tar.append_dir_all(".", self.src)?;

        let tarred = tar.into_inner()?;

        let mut data = std::io::Cursor::new(tarred);

        let mut encoder = {
            let target = std::fs::File::create(dest)?;
            zstd::Encoder::new(target, 5)?
        };

        std::io::copy(&mut data, &mut encoder)?;

        let f = encoder.finish()?;

        Ok(f)
    }

    pub fn restore(&self, dest: &'a Path) -> KyResult<()> {
        let decoder = {
            let file = File::open(self.src)?;
            zstd::Decoder::new(file)?
        };

        let mut tar = tar::Archive::new(decoder);

        tar.unpack(dest)?;

        Ok(())
    }

    pub fn export(
        dest: &'a Path,
        master: &Master,
        entries: Vec<(Encrypted, Encrypted)>,
    ) -> KyResult<()> {
        let mut wtr = Writer::from_path(dest).map_err(|_| KyError::ExportCreate)?;
        let master_cipher = Cipher::for_master(master);

        for (k, v) in entries.into_iter() {
            let key = master_cipher.decrypt(&k)?.into();
            let key_cipher = Cipher::for_key(master, &key)?;
            let val = Password::decrypt(&key_cipher, &v)?;
            let key_ref = key.as_ref().to_string();

            wtr.serialize(Row {
                title: key,
                website: val.website,
                username: val.username,
                password: val.password,
                notes: val.notes,
                expires: val.expires,
            })
            .map_err(|_| KyError::Export(key_ref))?;
        }

        Ok(())
    }

    pub fn import(src: &Path, master: &Master, env: &KyEnv) -> KyResult<()> {
        let mut rdr = Reader::from_path(src).map_err(|_| KyError::ImportRead)?;
        let iter = rdr.deserialize();

        let common_db = env.get_table(KyTable::Common)?;
        let pwd_db = env.get_table(KyTable::Password)?;

        let mut wtxn = env.write_txn()?;

        let hashed = master.hash()?;

        common_db.set(&mut wtxn, &Encrypted::from(MASTER), &hashed)?;

        let master_cipher = Cipher::for_master(master);

        for (i, entry) in iter.enumerate() {
            let k: Row = entry.map_err(|_| KyError::Import(i))?;

            let key_cipher = Cipher::for_key(master, &k.title)?;

            let val = Password {
                username: k.username,
                password: k.password,
                website: k.website,
                expires: k.expires,
                notes: k.notes,
            }
            .encrypt(&key_cipher)?;

            let key = master_cipher.encrypt(&Decrypted::from(&k.title))?;

            pwd_db.set(&mut wtxn, &key, &val)?;
        }

        wtxn.commit()?;

        Ok(())
    }
}

use fall_tree::{TextRange, Node, File, TextSuffix};
use fall_tree::search::{ancestors, find_leaf_at_offset, find_covering_node};


pub fn extend_selection(file: &File, range: TextRange) -> Option<TextRange> {
    let lang = file.language();
    let is_ws = |node: Node| lang.node_type_info(node.ty()).whitespace_like;
    if range.is_empty() {
        let offset = range.start();
        let mut leaves = find_leaf_at_offset(file.root(), offset);
        if let Some(leaf) = leaves.clone().find(|&node| !is_ws(node)) {
            return Some(leaf.range());
        }
        let ws = leaves.next()?;
        let ws_suffix = file.text().slice(
            TextRange::from_to(offset, ws.range().end())
        );
        if ws.text().contains("\n") && !ws_suffix.contains("\n") {
            if let Some(line_end) = file.text()
                .slice(TextSuffix::from(ws.range().end()))
                .find("\n")
            {
                let range = TextRange::from_len(ws.range().end(), line_end);
                return Some(find_covering_node(file.root(), range).range());
            }
        }
        return Some(ws.range());
    };
    let node = find_covering_node(file.root(), range);

    match ancestors(node).skip_while(|n| n.range() == range).next() {
        None => None,
        Some(parent) => Some(parent.range()),
    }
}

use rayquaza::{
    camera::Camera2D,
    color::Color,
    input::{Key, MouseButton},
    math::{clamp, Rectangle, Vector2},
    misc::random_value,
    result::Result,
    window::WindowBuilder,
};

const WORLD_WIDTH: i32 = 30000;
const BUILDING_COUNT: i32 = WORLD_WIDTH / BUILDING_WIDTH;
const BUILDING_WIDTH: i32 = 100;
const PLAYER_SPEED: f32 = 240.0;
const ROTATION_SPEED: f32 = 100.0;

struct Building {
    rectangle: Rectangle,
    color: Color,
}

fn main() -> Result {
    let window = WindowBuilder::new()
        .title("2D camera")
        .resizable()
        .vsync()
        .msaa_4x()
        .build()?;
    let mut player = Rectangle::new(WORLD_WIDTH as f32 / 2.0, 0.0, 40.0, 40.0);
    let mut buildings = Vec::with_capacity(BUILDING_COUNT as usize);
    for index in 0..BUILDING_COUNT {
        let height = random_value(100, 800);
        let rectangle = Rectangle::new(
            index as f32 * BUILDING_WIDTH as f32,
            player.height - height as f32,
            BUILDING_WIDTH as f32,
            height as f32,
        );
        let color = Color::new(
            random_value(127, 220) as u8,
            random_value(127, 220) as u8,
            random_value(127, 220) as u8,
            255,
        );
        buildings.push(Building { rectangle, color });
    }
    let mut camera = Camera2D::new(
        Vector2::new(window.width() as f32 / 2.0, window.height() as f32 / 2.0),
        Vector2::new(
            player.x + player.width / 2.0,
            player.y + player.height / 2.0,
        ),
        0.0,
        1.0,
    );
    while !window.should_close() {
        if window.is_key_down(Key::Right) {
            player.x = clamp(
                player.x as f32 + PLAYER_SPEED * window.frame_time(),
                0.0,
                WORLD_WIDTH as f32 - player.width,
            );
        }
        if window.is_key_down(Key::Left) {
            player.x = clamp(
                player.x as f32 - PLAYER_SPEED * window.frame_time(),
                0.0,
                WORLD_WIDTH as f32 - player.height,
            );
        }
        if window.is_mouse_button_down(MouseButton::Left) {
            camera.rotation += ROTATION_SPEED * window.frame_time();
        }
        if window.is_mouse_button_down(MouseButton::Right) {
            camera.rotation -= ROTATION_SPEED * window.frame_time();
        }
        if window.is_key_pressed(Key::R) {
            camera.zoom = 1.0;
            camera.rotation = 0.0;
        }
        camera.offset = Vector2::new(window.width() as f32 / 2.0, window.height() as f32 / 2.0);
        camera.target = Vector2::new(
            player.x + player.width / 2.0,
            player.y + player.height / 2.0,
        );
        camera.zoom = clamp(
            camera.zoom + camera.zoom * window.mouse_wheel_move() as f32 * 0.25,
            0.1,
            3.0,
        );
        window.draw(|canvas| {
            canvas.clear_background(Color::SKYBLUE);
            canvas.mode_2d(camera, |canvas| {
                canvas.draw_rectangle(0, player.height as i32, WORLD_WIDTH, 20000, Color::DARKGRAY);
                buildings.iter().for_each(|building| {
                    canvas.draw_rectangle_rec(building.rectangle, building.color);
                });
                canvas.draw_rectangle_rec(player, Color::RED);
            });
            canvas.draw_rectangle(10, 10, 250, 115, Color::DARKBLUE.fade(0.5));
            canvas.draw_rectangle_lines_ex(
                Rectangle::new(10.0, 10.0, 250.0, 115.0),
                2,
                Color::DARKBLUE,
            );
            canvas.draw_text("Controls:", 20, 20, 10, Color::WHITE);
            canvas.draw_text("- Right / Left keys to move", 40, 40, 10, Color::WHITE);
            canvas.draw_text("- Mouse wheel to zoom in-out", 40, 60, 10, Color::WHITE);
            canvas.draw_text("- Mouse buttons to rotate", 40, 80, 10, Color::WHITE);
            canvas.draw_text(
                "- R key to reset zoom and rotation",
                40,
                100,
                10,
                Color::WHITE,
            );
        });
    }
    Ok(())
}

//! Type definition for red node (syntax node).
//!
//! See <https://github.com/rust-analyzer/rust-analyzer/blob/master/docs/dev/syntax.md>

use std::{fmt::Display, hash::Hash, sync::Arc};

use super::green::GreenNode;

#[derive(Debug, Clone)]
pub struct SyntaxNode(Arc<SyntaxData>);

#[derive(Clone)]
pub struct SyntaxNodeDisplay<'a>(&'a SyntaxNode);

#[derive(Clone)]
pub struct SyntaxNodeDisplayRecursive<'a>(&'a SyntaxNode);

#[derive(Clone)]
pub struct SyntaxNodeDisplayShort<'a>(&'a SyntaxNode);

impl std::ops::Deref for SyntaxNode {
    type Target = Arc<SyntaxData>;

    fn deref(&self) -> &Self::Target {
        &self.0
    }
}

#[derive(Debug, Clone, Hash)]
pub struct SyntaxData {
    offset: usize,
    parent: Option<SyntaxNode>,
    green: Arc<GreenNode>,
}

impl SyntaxData {
    /// Get a reference to the syntax data's green.
    pub fn green(&self) -> &GreenNode {
        self.green.as_ref()
    }
}

impl SyntaxNode {
    pub fn new_root(root: Arc<GreenNode>) -> SyntaxNode {
        SyntaxNode(Arc::new(SyntaxData {
            offset: 0,
            parent: None,
            green: root,
        }))
    }

    pub fn parent(&self) -> Option<SyntaxNode> {
        self.parent.clone()
    }

    pub fn children(&self) -> impl Iterator<Item = SyntaxNode> + '_ {
        let mut offset = self.offset;
        self.green.children().iter().map(move |green_child| {
            let child_offset = offset;
            offset += green_child.text_len();
            SyntaxNode(Arc::new(SyntaxData {
                offset: child_offset,
                parent: Some(self.clone()),
                green: Arc::clone(green_child),
            }))
        })
    }

    pub fn children_recursive(&self) -> Vec<SyntaxNode> {
        Some(self.clone())
            .into_iter()
            .chain(self.children().flat_map(|c| c.children_recursive()))
            .collect()
    }

    pub fn text_len(&self) -> usize {
        self.green.text_len()
    }

    pub fn range(&self) -> (usize, usize) {
        (self.offset, self.offset + self.text_len())
    }

    pub fn includes(&self, index: usize) -> bool {
        index >= self.offset && index < self.offset + self.text_len()
    }

    fn dig_child(&self, index: usize) -> Option<SyntaxNode> {
        if !self.includes(index) {
            return None;
        }
        for child in self.children() {
            if child.includes(index) {
                return Some(child);
            }
        }
        None
    }

    /// その SyntaxNode の子要素のうち、その byte 目にある red node の列を取得する。
    pub fn dig(&self, index: usize) -> Vec<SyntaxNode> {
        if let Some(n) = self.dig_child(index) {
            n.dig(index).into_iter().chain(Some(self.clone())).collect()
        } else {
            vec![self.clone()]
        }
    }
    // pub fn dig(&self, index: usize) -> impl Iterator<Item = SyntaxNode> + '_ {
    //     self.dig_child(index)
    //         .map(|n| n.dig(index))
    //         .into_iter()
    //         .flatten()
    //         .chain(Some(self.clone()))
    //     // if let Some(n) = self.dig_child(index) {
    //     //     n.dig(index).into_iter().chain(Some(self.clone())).collect()
    //     // } else {
    //     //     vec![self.clone()]
    //     // }
    // }

    /// そのノードが表すテキストを取得する。
    pub fn text(&self) -> String {
        self.green.text()
    }
}

impl PartialEq for SyntaxNode {
    fn eq(&self, other: &Self) -> bool {
        self.offset == other.offset && Arc::ptr_eq(&self.green, &other.green)
    }
}

impl Eq for SyntaxNode {}

impl Hash for SyntaxNode {
    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
        self.0.hash(state);
    }
}

impl<'a> std::ops::Deref for SyntaxNodeDisplay<'a> {
    type Target = &'a SyntaxNode;

    fn deref(&self) -> &Self::Target {
        &self.0
    }
}

impl<'a> std::ops::Deref for SyntaxNodeDisplayRecursive<'a> {
    type Target = &'a SyntaxNode;

    fn deref(&self) -> &Self::Target {
        &self.0
    }
}

impl<'a> std::ops::Deref for SyntaxNodeDisplayShort<'a> {
    type Target = &'a SyntaxNode;

    fn deref(&self) -> &Self::Target {
        &self.0
    }
}

impl<'a> Display for SyntaxNodeDisplayShort<'a> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let (start, end) = self.range();
        if self.green.is_node() {
            write!(f, "[{}] ({}:{})", self.green().kind().as_str(), start, end)?;
        } else {
            write!(
                f,
                r#"<{}> ({}:{})"#,
                self.green().kind().as_str(),
                start,
                end
            )?;
        }
        if self.text_len() < 40 && !self.text().contains('\n') {
            write!(f, r#" "{}""#, self.text())?;
        }
        Ok(())
    }
}

impl<'a> Display for SyntaxNodeDisplay<'a> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        writeln!(f, "{}", self.display_short())?;
        for child in self.children() {
            writeln!(f, "  {}", child.display_short())?;
        }
        Ok(())
    }
}

impl<'a> SyntaxNodeDisplayRecursive<'a> {
    fn print_aux(&self, indent: usize) -> String {
        let mut s = String::new();
        s.push_str(&format!(
            "{}{}\n",
            " ".repeat(indent * 2),
            self.display_short()
        ));
        for child in self.children() {
            s.push_str(&child.display_recursive().print_aux(indent + 1));
        }
        s
    }
}

impl<'a> Display for SyntaxNodeDisplayRecursive<'a> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.print_aux(0))
    }
}

