        assert_eq!(task.parent(), Some(root.clone()));
        assert_eq!(task.text_len(), 7);
        assert_eq!(task.text(), "(A) foo".to_owned());
        assert_eq!(text.offset, 4);
        assert_eq!(text.parent(), Some(task));
        assert_eq!(text.text_len(), 3);
