#[macro_export]
macro_rules! selectors {
    (
        $(
            $(#[$attr:meta])*
            $name:ident $( : $ty:ty)?
        ),* $(,)?
    ) => {
        $(
            $(#[$attr])*
            pub const $name: ::druid::Selector<$($ty)?> = ::druid::Selector::new(concat!(
                module_path!(),
                "::",
                stringify!($name),
                "@",
                line!(),
                ":",
                column!()
            ));
        )*
    };
}

#[macro_export]
macro_rules! builder {
    ($name:ident: $ty:ty) => {
        pub fn $name(mut self, it: $ty) -> Self {
            self . $name = it.into();
            self
        }
    };

    (@internal $name:ident: $ty:ty = $($components:ident).*) => {
        pub fn $name(mut self, it: $ty) -> Self {
            self $(.$components)* . $name = it.into();
            self
        }
    };

    (box $name:ident: $ty:ty) => {
        pub fn $name(mut self, it: $ty) -> Self {
            self . $name = Box::new(it);
            self
        }
    };

    ($(@internal)? $first:ident $(.$component_rest:ident)*: $ty:ty $(= $($place:ident).*)?) => {
        builder! {
            @internal $($component_rest).*: $ty = $($($place.)* )? $first
        }
    };
    // (@into $($components:ident.)* $last:ident: $ty:ty) => {
    //     pub fn $last(mut self, it: impl Into<$ty>) -> Self {
    //         self.$($components.)* $last = it.into();
    //         self
    //     }
    // };

}

