}

#[derive(Debug, StructOpt)]
#[structopt(name = "packing")]
struct Args {
    /// Pass many times for more log output
    ///
    /// By default, it'll only report errors. Passing `-v` one time also prints
    /// warnings, `-vv` enables info logging, `-vvv` debug, and `-vvvv` trace.
    #[structopt(long, short, parse(from_occurrences))]
    verbosity: u8,

    #[structopt(subcommand)]
    shape: Shapes,

    /// The defining symmetry of the unit cell
    #[structopt(possible_values = &WallpaperGroups::variants())]
    wallpaper: WallpaperGroups,

    /// The potential which is being optimised
    #[structopt(short, long, possible_values = &Force::variants(), default_value = "Hard")]
    potential: Force,

    /// Where to save the best packed structure
    #[structopt(long, parse(from_os_str))]
    outfile: PathBuf,

    /// An initial configuration which is the starting point for optimisation
    #[structopt(long, parse(from_os_str))]
    start_config: Option<PathBuf>,

    /// The number of independent starting configurations to optimise
    #[structopt(long, default_value = "100")]
    replications: u64,

    #[structopt(flatten)]
    optimisation: BuildOptimiser,
}

#[derive(Debug, StructOpt)]
enum Shapes {
    #[structopt(name = "polygon")]
    Polygon {
        /// The number of equally spaced sides
        #[structopt(long, default_value = "4")]
        sides: usize,
    },
    #[structopt(name = "trimer")]
    Trimer {
        /// The distance from the central particle to the outer particles
        #[structopt(short, long, default_value = "1.")]
        distance: f64,
        /// The angle between the two outer particles in degrees
        #[structopt(short, long, default_value = "120")]
        angle: f64,
        /// The radius of the outer small particles
        #[structopt(short, long, default_value = "0.637556")]
        radius: f64,
    },
    #[structopt(name = "circle")]
    Circle {},
}

fn analyse_state(
    outfile: path::PathBuf,
    start_configs: u64,
    state: impl State,
    optimiser: &BuildOptimiser,
) -> Result<(), Error> {
    let final_state = (0..start_configs)
        .into_par_iter()
        // Create collection of quickly optimised initial states
        .map(|index| {
            let result = optimiser
                .clone()
                .steps(100)
                .kt_start(0.)
                .seed(index)
                .convergence(None)
                .build()
                .optimise_state(state.clone());
            (index, result)
        })
        // Perform Monte carlo optimisation
        .map(|(index, opt_state)| {
            let result = optimiser
                .clone()
                .seed(index)
                .build()
                .optimise_state(opt_state);
            (index, result)
        })
        // Final optimsation to help find the minimum
        .map(|(index, opt_state)| {
            optimiser
                .clone()
                .kt_start(0.)
                .seed(index)
                .build()
                .optimise_state(opt_state)
        })
        .max()
        .ok_or_else(|| anyhow!("Error in running optimisation."))?;

    info!(
        "Final score: {}",
        final_state
            .score()
            .ok_or_else(|| anyhow!("State has become corrupted"))?
    );

    let serialised = serde_json::to_string(&final_state)?;

    File::create(outfile.with_extension("json"))?.write_all(&serialised.as_bytes())?;
    svg::save(outfile.with_extension("svg"), &final_state.as_svg())?;

    Ok(())
}

#[paw::main]
fn main(args: Args) -> Result<(), Error> {
    let log_level = match args.verbosity {
        0 => LevelFilter::Info,
        1 => LevelFilter::Debug,
        2 => LevelFilter::Trace,
        _ => LevelFilter::Trace,
    };
    env_logger::Builder::new().filter_level(log_level).init();

    debug!("Logging Level: {}", log_level);

    let wg: WallpaperGroup = args.wallpaper.try_into()?;

    match (args.shape, args.potential) {
        (
            Shapes::Trimer {
                distance,
                angle,
                radius,
            },
            Force::LJ,
        ) => analyse_state(
            args.outfile,
            args.replications,
            PotentialState2::from_group(LJShape2::from_trimer(radius, angle, distance), &wg)?,
            &args.optimisation,
        ),
        (
            Shapes::Trimer {
                distance,
                angle,
                radius,
            },
            Force::Hard,
        ) => analyse_state(
            args.outfile,
            args.replications,
            PackedState2::from_group(MolecularShape2::from_trimer(radius, angle, distance), &wg)?,
            &args.optimisation,
        ),
        (Shapes::Circle {}, Force::LJ) => analyse_state(
            args.outfile,
            args.replications,
            PotentialState2::from_group(LJShape2::circle(), &wg)?,
            &args.optimisation,
        ),
        (Shapes::Circle {}, Force::Hard) => analyse_state(
            args.outfile,
            args.replications,
            PackedState2::from_group(MolecularShape2::circle(), &wg)?,
            &args.optimisation,
        ),
        (Shapes::Polygon { sides }, Force::Hard) => analyse_state(
            args.outfile,
            args.replications,
            PackedState2::from_group(LineShape::polygon(sides)?, &wg)?,
            &args.optimisation,
        ),
        (Shapes::Polygon { .. }, Force::LJ) => {
            bail!("Polygon with a LJ potential is not yet implemented")
        }
    }
}

use crate::*;

pub struct Resolver {
    env: Env
}

impl Resolver {
    pub fn new() -> Resolver {
        Resolver {
            env: Env::new()
        }
    }

    fn access(&mut self, name: &Token) -> Result<u32, &'static str> {
        let mut id = -1;
        for i in (0..self.env.locals.len()) {
            let local = self.env.get(i);
            if local.name.val == name.val{
                id = i as i32;
            }
        }
        if id < 0 {
            return Err("Usage of an undefined variable");
        }
        else {
            let mut id: u32 = id as u32;
            return Ok(id)
        }
    }

    pub fn resolve(&mut self, program: Program) -> Result<Program, &'static str> {
        self.resolve_stmts(program)
    }

    fn resolve_stmts(&mut self, stmts: Vec<Stmt>) -> Result<Vec<Stmt>, &'static str> {
        let mut resolved = Vec::<Stmt>::new();
        for stmt in stmts {
            resolved.push(self.resolve_stmt(stmt)?)
        }
        Ok(resolved)
    }

    fn resolve_stmt(&mut self, stmt: Stmt) -> Result<Stmt, &'static str> {
        match stmt {
            Stmt::MutDecl(name, val) => {
                let val = self.resolve_expr(*val)?;
                if self.env.is_redefined(&name) {
                    return Err("Tried to redeclare a variable in the same scope");
                }
                self.env.add(name.clone());
                Ok(Stmt::MutDecl(name, Box::new(val)))
            },
            Stmt::Expr(expr) => {
                Ok(Stmt::Expr(Box::new(self.resolve_expr(*expr)?)))
            },
            _ => panic!()
        }
    }

    fn resolve_expr(&mut self, expr: Expr) -> Result<Expr, &'static str> {
        match expr {
            Expr::Binary(left, op, right) => {
                if op.t == TokenType::Equal {
                    let right = self.resolve_expr(*right)?;
                    if let Expr::Access(l) = *(left.clone()) {
                        let id = self.access(&l)?;
                        return Ok(Expr::ResolvedAssign(l, id, Box::new(right)));
                    }
                    else {
                        let err = "Invalid assignment target. Expected an identifier";
                        error(op.clone(), err);
                        return Err(err);
                    }
                }
                let left = self.resolve_expr(*left)?;
                let right = self.resolve_expr(*right)?;
                Ok(Expr::Binary(Box::new(left), op, Box::new(right)))
            },
            Expr::Access(name) => {
                let id = self.access(&name)?;
                Ok(Expr::ResolvedAccess(name, id))
            },
            Expr::Block(stmts) => {
                self.env.open();
                let mut stmts = self.resolve_stmts(stmts)?;
                let pop_count = self.env.close();
                Ok(Expr::ResolvedBlock(stmts, pop_count))
            },
            Expr::Unary(op, right) => {
                let right = self.resolve_expr(*right)?;
                Ok(Expr::Unary(op, Box::new(right)))
            },
            Expr::IfElse(cond, ib, eb) => {
                let cond = self.resolve_expr(*cond)?;
                let ib = self.resolve_expr(*ib)?;
                let mut eb = eb;
                if let Some(eb_expr) = eb {
                    eb = Some(Box::new(self.resolve_expr(*eb_expr)?));
                }
                Ok(Expr::IfElse(Box::new(cond), Box::new(ib), eb))
            },
            _ => Ok(expr)
        }
    }
}

use super::*;
use crate::AlfredError;
use chrono::prelude::Local;

pub fn run(x: SubCommand) {
    debug!("Starting in run");
    let print_config;
    let mut config: Config;

    #[allow(clippy::option_map_unit_fn)]
    match x {
        SubCommand::Config {
            display,
            auth_token,
            number_pins,
            number_tags,
            shared,
            toread,
            fuzzy,
            tags_only,
            auto_update,
            suggest_tags,
            check_bookmarked_page,
            show_url_vs_tags,
        } => {
            print_config = display;
            config = Config::setup().unwrap_or_else(|err| {
                if_chain! {
                    if auth_token.is_some();
                    if let Some(t) = err.as_fail().downcast_ref::<AlfredError>();
                    if let AlfredError::MissingConfigFile = *t;
                    then {
                        let mut config = Config::new();
                        config.auth_token = auth_token.as_ref().unwrap().clone();
                        config
                    } else {
                        crate::show_error_alfred(err.to_string());
                        process::exit(1);
                    }
                }
            });
            auth_token.map(|val| config.auth_token = val);
            number_pins.map(|val| config.pins_to_show = val);
            number_tags.map(|val| config.tags_to_show = val);
            shared.map(|val| config.private_new_pin = !val);
            toread.map(|val| config.toread_new_pin = val);
            fuzzy.map(|val| config.fuzzy_search = val);
            tags_only.map(|val| config.tag_only_search = val);
            auto_update.map(|val| config.auto_update_cache = val);
            suggest_tags.map(|val| config.suggest_tags = val);
            check_bookmarked_page.map(|val| config.page_is_bookmarked = val);
            show_url_vs_tags.map(|val| config.show_url_vs_tags = val);
        }
        _ => unreachable!(),
    }

    if let Err(e) = config.save() {
        error!("Couldn't save config file: {:?}", e);
    } else {
        debug!(
            "Saved new configs to {} in: {}",
            crate::workflow_config::CONFIG_FILE_NAME,
            config.data_dir().to_string_lossy()
        );
    }

    if print_config {
        show_config(&config);
    }
}

