#[macro_use]
extern crate lazy_static;

use std::os::raw::{c_double, c_float, c_int};
use std::sync::Mutex;

mod browser;
mod engine;
mod utils;
mod world;
use engine::EngineState;
use world::{Tile, WorldState};

// Imported js functions. Note, some are used in other modules (browser, utils).
extern "C" {
    fn js_update();
    fn js_draw_fps(layer_id: c_int, fps: c_double);
    fn js_path_count(layer_id: c_int, count: c_int);
    fn js_draw_circle(
        layer_id: c_int,
        px: c_double,
        py: c_double,
        radius: c_double,
        ch: c_int,
        cs: c_int,
        cl: c_int,
        ca: c_float,
    );
    fn js_draw_tile(
        layer_id: c_int,
        px: c_double,
        py: c_double,
        size: c_double,
        ch: c_int,
        cs: c_int,
        cl: c_int,
        ca: c_float,
    );
}

// Learned about this pattern from rocket_wasm on github
// https://github.com/aochagavia/rocket_wasm/blob/d0ca51beb9c7c351a1f0266206edfd553bf078d3/src/lib.rs
// QUESTION: is there a better way/place to store state???
lazy_static! {
    static ref WORLD_STATE: Mutex<WorldState> = Mutex::new(WorldState::new());
    static ref ENGINE_STATE: Mutex<EngineState> = Mutex::new(EngineState::new());
}

// Maps to WASM_ASTAR.layers on the client side
enum Layer {
    TileBg = 0,
    Main = 1,
    Fps = 2,
}

#[no_mangle]
pub extern "C" fn init(debug: i32, render_interval_ms: i32, window_width: u32, window_height: u32) {
    utils::log("Initializing Rust/WASM");
    // Requires block curlies so lifetime of world ends which causes unlock
    // and allows initial_draw() to gain control of the lock.
    // Otherwise, this generic client error occurs: "RuntimeError: unreachable executed"
    // QUESTION: is there a better way to do this?
    browser::create_layer("TileBg", Layer::TileBg as i32);
    browser::create_layer("Main", Layer::Main as i32);
    browser::create_layer("Fps", Layer::Fps as i32);
    {
        let world = &mut WORLD_STATE.lock().unwrap();
        world.window_width = window_width;
        world.window_height = window_height;
        world.debug = if debug == 1 { true } else { false };
        utils::log_fmt(format!("Debug Mode: {}", world.debug));
        if world.debug {
            browser::start_interval_tick(render_interval_ms);
        } else {
            browser::request_next_tick();
        }
    }
    initial_draw();
}

#[no_mangle]
pub extern "C" fn tick(elapsed_time: f64) {
    browser::clear_screen(Layer::Main as i32);
    update(elapsed_time);
    draw(elapsed_time);
    browser::request_next_tick();
}

#[no_mangle]
pub extern "C" fn key_down(key_code: u32) {
    let engine = &mut ENGINE_STATE.lock().unwrap();
    engine.set_key_down(key_code);
}

#[no_mangle]
pub extern "C" fn key_up(key_code: u32) {
    let engine = &mut ENGINE_STATE.lock().unwrap();
    engine.set_key_up(key_code);
}

#[no_mangle]
pub extern "C" fn mouse_move(x: i32, y: i32) {
    let engine = &mut ENGINE_STATE.lock().unwrap();
    let world = &mut WORLD_STATE.lock().unwrap();
    engine.mouse_move(x, y);
    world.set_player_pos(x as f64, y as f64);
}

fn update(elapsed_time: f64) {
    handle_input();
    let engine = &mut ENGINE_STATE.lock().unwrap();
    engine.update(elapsed_time);
    let world = &mut WORLD_STATE.lock().unwrap();
    world.set_start_node();
    world.calc_astar();
    unsafe {
        js_update();
    }
}

fn handle_input() {
    let world = &mut WORLD_STATE.lock().unwrap();
    let engine = &mut ENGINE_STATE.lock().unwrap();
    if !engine.was_key_down(engine::KeyCode::Spacebar)
        && engine.is_key_down(engine::KeyCode::Spacebar)
        && !world.recent_regen
    {
        world.reset();
        browser::clear_screen(Layer::Main as i32);
        // Horrible check until i implement event callbacks for key presses
        world.recent_regen = true;
    } else if !engine.is_key_down(engine::KeyCode::Spacebar) {
        world.recent_regen = false;
    }

    let mut x_dir = 0;
    let mut y_dir = 0;
    if engine.is_key_down(engine::KeyCode::ArrowUp) {
        y_dir = -1;
    } else if engine.is_key_down(engine::KeyCode::ArrowDown) {
        y_dir = 1;
    }
    if engine.is_key_down(engine::KeyCode::ArrowLeft) {
        x_dir = -1;
    } else if engine.is_key_down(engine::KeyCode::ArrowRight) {
        x_dir = 1;
    }
    world.update_player(x_dir, y_dir);
}

fn initial_draw() {
    let world = &mut WORLD_STATE.lock().unwrap();
    if world.window_width < 600 {
        world.width = 350 * world.quality;
        world.height = 450 * world.quality;
        world.reset();
    }
    browser::set_screen_size(world.width, world.height, world.quality);
    browser::set_layer_size(
        Layer::TileBg as i32,
        world.width,
        world.height,
        world.quality,
    );
    browser::set_layer_size(Layer::Main as i32, world.width, world.height, world.quality);
    browser::set_layer_size(Layer::Fps as i32, 200, 70, world.quality);
    draw_background(world);
}

fn draw(elapsed_time: f64) {
    let world = &mut WORLD_STATE.lock().unwrap();
    if world.recent_regen {
        draw_background(world);
    }
    draw_path(world, &world.tiles[world.end_id as usize]);
    draw_tile_with_color(
        Layer::Main,
        &world.tiles[world.start_id as usize],
        &engine::Color::new(32, 100, 60, 0.3),
    );
    draw_tile_with_color(
        Layer::Main,
        &world.tiles[world.end_id as usize],
        &engine::Color::new(112, 89, 61, 1.0),
    );
    let path_count = get_path_count(world, &world.tiles[world.end_id as usize], 0);
    draw_path_count(path_count);
    // draw_player(world);
    draw_fps(elapsed_time);
}

fn draw_background(world: &WorldState) {
    for t in world.tiles.iter() {
        draw_tile(Layer::TileBg, &t);
    }
}

fn draw_path(world: &WorldState, t: &Tile) {
    let half_tile = (world.tile_size / 2) as f64;
    unsafe {
        js_draw_circle(
            Layer::Main as i32,
            t.transform.pos_x + half_tile,
            t.transform.pos_y + half_tile,
            t.transform.scale_x / 5_f64,
            280,
            100,
            73,
            1_f32,
        );
    }
    if t.parent_id >= 0 {
        draw_path(world, &world.tiles[t.parent_id as usize]);
    }
}

fn get_path_count(world: &WorldState, t: &Tile, counter: i32) -> i32 {
    if t.parent_id >= 0 {
        get_path_count(world, &world.tiles[t.parent_id as usize], counter + 1)
    } else {
        counter
    }
}

fn draw_tile(layer: Layer, t: &Tile) {
    draw_tile_with_color(layer, &t, &t.color);
}

fn draw_tile_with_color(layer: Layer, t: &Tile, c: &engine::Color) {
    unsafe {
        js_draw_tile(
            layer as i32,
            t.transform.pos_x,
            t.transform.pos_y,
            t.transform.scale_x,
            c.h as i32,
            c.s as i32,
            c.l as i32,
            c.a,
        );
    }
}

fn draw_player(world: &WorldState) {
    let half_tile = (world.tile_size / 2) as f64;
    unsafe {
        js_draw_circle(
            Layer::Main as i32,
            world.player.pos_x + half_tile,
            world.player.pos_y + half_tile,
            (world.tile_size / 4) as f64,
            32,
            100,
            55,
            1_f32,
        );
    }
}

fn draw_path_count(path_count: i32) {
    unsafe {
        js_path_count(Layer::Main as i32, path_count);
    }
}

fn draw_fps(elapsed_time: f64) {
    let engine = &mut ENGINE_STATE.lock().unwrap();
    let fps = engine.fps;
    engine.render_fps(elapsed_time, 150, || {
        browser::clear_screen(Layer::Fps as i32);
        unsafe {
            js_draw_fps(Layer::Fps as i32, fps);
        }
    });
}

//! Demonstrates how to run a basic Discovery v5 Service.
//!
//! This example creates a discv5 service which searches for peers every 30 seconds. On
//! creation, the local ENR created for this service is displayed in base64. This can be used to
//! allow other instances to connect and join the network. The service can be stopped by pressing
//! Ctrl-C.
//!
//! To add peers to the network, create multiple instances of this service adding the ENR of a
//! participating node in the command line. The nodes should discover each other over a period of
//! time. (It is probabilistic that nodes to find each other on any given query).
//!
//! A single instance listening on a UDP socket `127.0.0.1:9000` (with an ENR that has an empty IP
//! and UDP port) can be created via:
//!
//! ```
//! sh cargo run --example find_nodes
//! ```
//!
//! As the associated ENR has no IP/Port it is not displayed, as it cannot be used to connect to.
//!
//! An ENR IP address (to allow another nodes to dial this service), port and ENR node can also be
//! passed as command line options. Therefore, a second instance, in a new terminal, can be run on
//! port 9001 and connected to another node with a valid ENR:
//!
//! ```
//! sh cargo run --example find_nodes -- 127.0.0.1 9001 <GENERATE_KEY> <BASE64_ENR>
//! ```
//!
//! where `<BASE64_ENR>` is the base64 ENR given from executing the first node with an IP and port
//! given in the CLI.
//! `<GENERATE_KEY>` is a boolean (`true` or `false`) specifying if a new key should be generated.
//! These steps can be repeated to add further nodes to the test network.
//!
//! The parameters are optional.
//!
//!  For a simple CLI discovery service see [discv5-cli](https://github.com/AgeManning/discv5-cli)

use discv5::{enr, enr::CombinedKey, Discv5, Discv5Config, Discv5Event};
use futures::prelude::*;
use hex_literal::*;
use std::{
    net::{Ipv4Addr, SocketAddr},
    time::Duration,
};

#[tokio::main]
async fn main() {
    env_logger::init();

    // if there is an address specified use it
    let address = {
        if let Some(address) = std::env::args().nth(1) {
            address.parse::<Ipv4Addr>().unwrap()
        } else {
            Ipv4Addr::new(127, 0, 0, 1)
        }
    };

    let port = {
        if let Some(udp_port) = std::env::args().nth(2) {
            u16::from_str_radix(&udp_port, 10).unwrap()
        } else {
            9000
        }
    };

    // A fixed key for testing
    let raw_key = hex!("b71c71a67e1177ad4e901695e1b4b9ee17ae16c6668d313eac2f96dbcda3f291");
    let secret_key = secp256k1::SecretKey::parse_slice(&raw_key).unwrap();
    let mut enr_key = CombinedKey::from(secret_key);

    // use a random key if specified
    if let Some(generate_key) = std::env::args().nth(3) {
        if generate_key.parse::<bool>().unwrap() {
            enr_key = CombinedKey::generate_secp256k1();
        }
    }

    // construct a local ENR
    let enr = {
        let mut builder = enr::EnrBuilder::new("v4");
        // if an IP was specified, use it
        if std::env::args().nth(1).is_some() {
            builder.ip(address.into());
        }
        // if a port was specified, use it
        if std::env::args().nth(2).is_some() {
            builder.udp(port);
        }
        builder.build(&enr_key).unwrap()
    };

    // if the ENR is useful print it
    println!("Node Id: {}", enr.node_id());
    if enr.udp_socket().is_some() {
        println!("Base64 ENR: {}", enr.to_base64());
        println!("IP: {}, UDP_PORT:{}", enr.ip().unwrap(), enr.udp().unwrap());
    } else {
        println!("ENR is not printed as no IP:PORT was specified");
    }

    // default configuration
    let config = Discv5Config::default();

    // the address to listen on
    let socket_addr = SocketAddr::new(address.into(), port);

    // construct the discv5 service, initializing an unused transport layer
    let mut discv5 = Discv5::new(enr, enr_key, config, socket_addr).unwrap();

    // if we know of another peer's ENR, add it known peers
    if let Some(base64_enr) = std::env::args().nth(4) {
        match base64_enr.parse::<enr::Enr<enr::CombinedKey>>() {
            Ok(enr) => {
                println!(
                    "ENR Read. ip: {:?}, udp_port {:?}, tcp_port: {:?}",
                    enr.ip(),
                    enr.udp(),
                    enr.tcp()
                );
                if let Err(e) = discv5.add_enr(enr) {
                    println!("ENR was not added: {}", e);
                }
            }
            Err(e) => panic!("Decoding ENR failed: {}", e),
        }
    }
    // construct a 30 second interval to search for new peers.
    let mut query_interval = tokio::time::interval(Duration::from_secs(30));

    loop {
        tokio::select! {
            _ = query_interval.next() => {
                // pick a random node target
                let target_random_node_id = enr::NodeId::random();
                println!("Connected Peers: {}", discv5.connected_peers());
                println!("Searching for peers...");
                // execute a FINDNODE query
                discv5.find_node(target_random_node_id);
            }
            event = discv5.next() => {
                if let Some(event) = event {
                    if let Discv5Event::FindNodeResult { closer_peers, query_id,  .. } = event {
                        if !closer_peers.is_empty() {
                            println!("Query with id {} Completed. Nodes found: {}", *query_id, closer_peers.len());
                            for n in closer_peers {
                                println!("Node: {}", n);
                            }
                        } else {
                            println!("Query Completed. No peers found.")
                        }
                    }
                }
            }
        }
    }
}

