    assert_eq!(message_type(subscribe_header), MqttType::Subscribe);
}

#[test]
fn suback_type() {
    let subscribe_header = &[0x90, 3, 0, 7, 1][0..];
    assert_eq!(message_type(subscribe_header), MqttType::SubAck);
}

