//! Pings the Parsec service.

pub use crate::cli::ParsecToolApp;
use crate::error::ParsecToolError;
use crate::subcommands::ParsecToolSubcommand;
use parsec_client::core::interface::requests::ProviderID;
use parsec_client::core::operation_client::OperationClient;
use parsec_interface::operations::ping;
use parsec_interface::operations::{NativeOperation, NativeResult};
use std::convert::TryFrom;
use structopt::StructOpt;

/// Pings the Parsec service.
#[derive(Debug, StructOpt)]
#[structopt(name = "ping")]
pub struct PingSubcommand {}

impl TryFrom<&PingSubcommand> for NativeOperation {
    type Error = ParsecToolError;

    fn try_from(_ping_subcommand: &PingSubcommand) -> Result<NativeOperation, Self::Error> {
        // Trivially converted to a `NativeOperation`.
        Ok(NativeOperation::Ping(ping::Operation {}))
    }
}

impl ParsecToolSubcommand<'_> for PingSubcommand {
    /// Pings the Parsec service and prints the wire protocol version.
    fn run(&self, matches: &ParsecToolApp) -> Result<(), ParsecToolError> {
        info!("Pinging Parsec service...");

        let client = OperationClient::new();
        let native_result = client.process_operation(
            NativeOperation::try_from(self)?,
            ProviderID::Core,
            &matches.authentication_data(),
        )?;

        if let NativeResult::Ping(result) = native_result {
            success!(
                "Service wire protocol version is {}.{}.",
                result.wire_protocol_version_maj,
                result.wire_protocol_version_min,
            );
            Ok(())
        } else {
            Err(ParsecToolError::UnexpectedNativeResult(native_result))
        }
    }
}

use std::collections::VecDeque;

use serde::Deserialize;

use super::event::Event;
use crate::{cmap::options::ConnectionPoolOptions, error::ErrorKind};

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TestFile {
    version: u8,
    pub description: String,
    pub pool_options: Option<ConnectionPoolOptions>,
    operations: VecDeque<ThreadedOperation>,
    pub error: Option<Error>,
    pub events: Vec<Event>,
    #[serde(default)]
    pub ignore: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct ThreadedOperation {
    #[serde(flatten)]
    type_: Operation,

    thread: Option<String>,
}

#[derive(Debug, Deserialize)]
#[serde(tag = "name")]
#[serde(rename_all = "camelCase")]
pub enum Operation {
    Start {
        target: String,
    },
    Wait {
        ms: u64,
    },
    WaitForThread {
        target: String,
    },
    WaitForEvent {
        event: String,
        count: usize,
    },
    CheckOut {
        label: Option<String>,
    },
    CheckIn {
        connection: String,
    },
    Clear,
    Close,

    // In order to execute a `Start` operation, we need to know all of the operations that should
    // execute in the context of that thread. To achieve this, we preprocess the operations
    // specified by the test file to replace each instance of `Start` operation with a
    // `StartHelper` with the corresponding operations. `StartHelper` won't ever actually occur in
    // the original set of operations specified.
    StartHelper {
        target: String,
        operations: Vec<Operation>,
    },
}

#[derive(Debug, Deserialize)]
pub struct Error {
    #[serde(rename = "type")]
    pub type_: String,
    message: String,
    address: Option<String>,
}

impl Error {
    pub fn assert_matches(&self, error: &crate::error::Error, description: &str) {
        match error.kind.as_ref() {
            ErrorKind::WaitQueueTimeoutError { .. } => {
                assert_eq!(self.type_, "WaitQueueTimeoutError", "{}", description);
            }
            _ => {
                panic!("Expected {}, but got {:?}", self.type_, error);
            }
        }
    }
}

impl TestFile {
    pub fn process_operations(&mut self) -> Vec<Operation> {
        let mut processed_ops = Vec::new();

        while let Some(operation) = self.operations.pop_front() {
            match operation.type_ {
                // When a `Start` operation is encountered, search the rest of the operations for
                // any that occur in the context of the corresponding thread, remove them from the
                // original set of operations, and add them to the newly created `StartHelper`
                // operation.
                Operation::Start { target } => {
                    let start_helper = Operation::StartHelper {
                        operations: remove_by(&mut self.operations, |op| {
                            op.thread.as_ref() == Some(&target)
                        })
                        .into_iter()
                        .map(|op| op.type_)
                        .collect(),
                        target,
                    };

                    processed_ops.push(start_helper);
                }
                other => processed_ops.push(other),
            }
        }

        processed_ops
    }
}

// Removes all items in the `VecDeque` that fulfill the predicate and return them in order as a new
// `Vec`.
fn remove_by<T, F>(vec: &mut VecDeque<T>, pred: F) -> Vec<T>
where
    F: Fn(&T) -> bool,
{
    let mut i = 0;
    let mut removed = Vec::new();

    while i < vec.len() {
        if pred(&vec[i]) {
            removed.push(vec.remove(i).unwrap());
        } else {
            i += 1;
        }
    }

    removed
}

use super::compile_expression;
use crate::analyzer::bodies::check_argument_types;
use crate::context::CompilerContext;
use crate::errors;
use crate::source::SourceOrigin;
use crate::{ast, program};
use std::rc::Rc;

pub fn compile_index_expr(
    expression: ast::IndexExpr,
    context: &mut CompilerContext,
) -> program::Expression {
    let collection = compile_expression(*expression.collection, None, context);
    let collection_type = Rc::clone(collection.type_());

    let index = compile_expression(*expression.index, None, context);

    if collection.is_error() || index.is_error() {
        return program::Expression::error(expression.span);
    }

    let method = collection_type.borrow().lookup_method("index");
    let method = match method {
        Ok(method) => method,
        Err(error) => {
            let error = error.into_direct_lookup_error(SourceOrigin::Plain(expression.span));
            context.errors.push(error);
            return program::Expression::error(expression.span);
        }
    };
    let arguments = vec![collection, index];

    if check_argument_types(&method, &arguments, expression.span, context).is_err() {
        return program::Expression::error(expression.span);
    }

    // TODO(#6): currently this will cause a compiler panic if `index` is a void method.
    let pointer = program::Expression::new(
        program::Call {
            function: method,
            arguments,
            location: SourceOrigin::Plain(expression.span),
        },
        context.program.types_mut(),
    );

    if pointer.type_().borrow().is_pointer() {
        program::Expression::new(
            program::DerefExpr {
                pointer: Box::new(pointer),
                location: SourceOrigin::DereferencedIndex(expression.span),
            },
            context.program.types_mut(),
        )
    } else {
        let error = errors::index_method_returns_not_pointer(
            &collection_type.borrow().name,
            &pointer.type_().borrow().name,
            SourceOrigin::Plain(expression.span),
        );
        context.errors.push(error);
        program::Expression::error(expression.span)
    }
}

