    let mut input_reader: Box<BufRead> = if args.input_option.is_some() {
        let input_path = args.input_option.unwrap();
        let input_file = File::open(&input_path).chain_err(|| {
            format!("Can't open input file: {}", input_path.display())
        })?;
        Box::new(BufReader::new(input_file))
    } else {
        Box::new(BufReader::new(stdin_handle.lock()))
    };

    // Setup a buffered output reader
    // Use output file if providd, otherwise use stdout
    let mut output_writer: Box<Write> = if args.output_option.is_some() {
        let output_path = args.output_option.unwrap();
        let output_file = File::create(&output_path).chain_err(|| {
            format!("Cant create output file: {}", output_path.display())
        })?;
        Box::new(BufWriter::new(output_file))
    } else {
        Box::new(stdout_handle.lock())
    };

    // Read all the input into a buffer
    let mut input_buffer = String::new();
    input_reader.read_to_string(&mut input_buffer).chain_err(
        || "Couldn't read input contents",
    )?;

    // Parse the json object
    let json_object = json::parse(&input_buffer)?;

    // Stringify the json
    let output = if args.not_pretty {
        json::stringify(json_object)
    } else {
        json::stringify_pretty(json_object, args.indent_spaces)
    };

    // Write to output
    output_writer.write_all(output.as_bytes())?;

    Ok(())
});

error_chain! {
    foreign_links {
        IO(std::io::Error);
        Json(json::JsonError);
    }
}

//! Helper routines for the asynchronous functions

use std::future::Future;
use std::time::Duration;

/// Spawns a background thread using which ever asynchronous runtime the library is built with
pub fn spawn<T>(future: T)
where T: Future + Send + 'static, T::Output: Send + 'static,
{
    #[cfg(feature = "tokio")]
    if tokio::runtime::Handle::try_current().is_ok() {
        tokio::spawn(future);
    } else {
        std::thread::Builder::new()
            .spawn(move || {
                let rt = tokio::runtime::Builder::new_current_thread()
                    .enable_all()
                    .build()
                    .unwrap();
                rt.block_on(future);
            })
            .expect("failed to spawn thread");
    }

    #[cfg(feature = "async-std")]
    if async_std::task::try_current().is_some() {
        async_std::task::spawn(future);
    } else {
        std::thread::Builder::new()
            .spawn(move || {
                async_std::task::block_on(future);
            })
            .expect("failed to spawn thread");
    }
}

/// Safely executing blocking code using which ever asynchronous runtime the library is built with
pub fn spawn_block_on<F>(mut task: F)
where F: FnMut() -> () + 'static + Send,
{
    #[cfg(feature = "tokio")]
    if tokio::runtime::Handle::try_current().is_ok() {
        tokio::task::spawn_blocking(move || {
            task();
        });
        return;
    }

    #[cfg(feature = "async-std")]
    if async_std::task::try_current().is_some() {
        std::thread::Builder::new()
            .spawn(task)
            .expect("failed to spawn thread");
        return;
    }

    task();
}

/// Executes a future with a specific timeout using which ever asynchronous runtime the library is built with
#[cfg(test)]
#[must_use = "this `Option` should be handled"]
pub async fn timeout<F>(duration: Duration, future: F) -> Option<F::Output>
where F: Future
{
    #[cfg(feature = "tokio")]
    return match tokio::time::timeout(duration, future).await {
        Ok(a) => Some(a),
        Err(_) => None
    };

    #[cfg(feature = "async-std")]
    return match async_std::future::timeout(duration, future).await {
        Ok(a) => Some(a),
        Err(_) => None
    };
}

/// Sleeps for a fixed period of time (without blocking asynchronous runtimes)
pub async fn sleep(duration: Duration)
{
    #[cfg(feature = "tokio")]
    tokio::time::sleep(duration).await;

    #[cfg(feature = "async-std")]
    async_std::task::sleep(duration).await;
}

use proc_macro2::Span;
use syn::{Result, TypePath};

pub(super) enum _FieldType {
    Bool(TypePath),
    Primitive(TypePath),
    Custom(TypePath),
}

impl _FieldType {
    pub(super) fn from(ty: TypePath, width: u32, width_span: Span) -> Result<_FieldType> {
        if let Some(ty_name) = ty.path.get_ident() {
            match ty_name.to_string().as_str() {
                "bool" => {
                    if width != 1 {
                        Err(syn::Error::new(
                            width_span,
                            format!("Field size must be 1 for bool"),
                        ))
                    } else {
                        Ok(_FieldType::Bool(ty))
                    }
                }
                "u8" | "u16" | "u32" | "u64" => Ok(_FieldType::Primitive(ty)),
                _ => Ok(_FieldType::Custom(ty)),
            }
        } else {
            Ok(_FieldType::Custom(ty))
        }
    }
}

