use proc_macro::{TokenStream};
use quote::quote;
use syn::{parse, DeriveInput, Data, parse_str, Ident, self};

#[proc_macro_derive(Builder, attributes(builder))]
pub fn derive(input: TokenStream) -> TokenStream {
    let ast: DeriveInput = parse(input).unwrap();
    let name = &ast.ident;
    let bn = format!("{}Builder", name);
    let builder_name: Ident = parse_str(&bn).unwrap();
    let mut tokens = TokenStream::new();
    match ast.data {
        Data::Struct(s) => {
            tokens.extend(construct_builder(&builder_name, &s));
            tokens.extend(add_builder_method_to_target(&name, &builder_name, &s));
            tokens.extend(impl_builder(&name, &builder_name, &s));
        }
        _ => unimplemented!()
    }
    tokens
}


fn construct_builder(builder_name: &Ident, s: &syn::DataStruct) -> TokenStream {
    let mut builder_fields = vec![];
    for f in s.fields.iter() {
        let ty = &f.ty;
        let field_name = &f.ident.as_ref().unwrap();

        if let Some(ty) = try_extract_option(ty) {
            builder_fields.push(quote!{
                #field_name: std::option::Option<#ty>,
            });
        } else if let Some(_) = try_extract_vec(ty) {
            builder_fields.push(quote!{
                #field_name: #ty,
            });
        } else {
            builder_fields.push(quote!{
                #field_name: std::option::Option<#ty>,
            });
        }
    }

    let builder = quote! {
        #[derive(Clone)]
        pub struct #builder_name {
            #(#builder_fields)*
        }
    };
    builder.into()
}

fn add_builder_method_to_target(name: &Ident, builder_name: &Ident, s: &syn::DataStruct)  -> TokenStream {
    let mut builder_init = vec![];
    for f in s.fields.iter() {
        let ty = &f.ty;
        let field_name = &f.ident.as_ref().unwrap();
        if let Some(_) = try_extract_vec(ty) {
            builder_init.push(quote!{
                #field_name: vec![],
            });
        } else {
            builder_init.push(quote!{
                #field_name: std::option::Option::None,
            });
        }

    }

    let builder = quote! {
        impl #name {
            pub fn builder() -> #builder_name {
                #builder_name {
                    #(#builder_init)*
                }
            }
        }
    };
    builder.into()
}


// Option<T> -> T
fn try_extract_option(ty: &syn::Type) -> Option<&syn::Type> {
    return try_extract_first_generic_param(ty, "Option");
}


// Vec<T> -> T
fn try_extract_vec(ty: &syn::Type) -> Option<&syn::Type> {
    return try_extract_first_generic_param(ty, "Vec");
}

fn try_extract_first_generic_param<'a, 'b>(ty: &'a syn::Type, ident: &'b str) -> Option<&'a syn::Type> {
    match ty {
        syn::Type::Path(pth) => {
            if let Some(i) = pth.path.segments.first() {
                if  i.ident == ident {
                    match &i.arguments {
                        syn::PathArguments::AngleBracketed(args) => {
                            if let Some(a) = args.args.first() {
                                match a {
                                    syn::GenericArgument::Type(ty) => {
                                        return Some(ty)
                                    },
                                    _ => {},
                                }
                            }
                        },
                        _ => {},
                    };
                }
            }
        },
        _ => {},
    }
    return None;
}

fn impl_builder(name: &Ident, builder_name: &Ident, s: &syn::DataStruct) -> TokenStream {
    let mut tokens = TokenStream::new();
    tokens.extend(impl_builder_set_funcs(builder_name, s));
    tokens.extend(impl_builder_dot_build(name, builder_name, s));
    tokens
}

fn impl_builder_set_funcs(builder_name: &Ident, s: &syn::DataStruct) -> TokenStream {
    let mut tokens = TokenStream::new();
    for f in s.fields.iter() {
        if let Some(t) = try_impl_field_repeat(builder_name, f) {
            tokens.extend(t);
        } else {
            tokens.extend(impl_field_setter(builder_name, f));
        }
    }
    tokens
}

fn impl_field_setter(builder_name: &Ident, f: &syn::Field) -> TokenStream {
    let ty = if let Some(ty) = try_extract_option(&f.ty) {
        ty
    } else {
        &f.ty
    };
    let field_name = &f.ident.as_ref().unwrap();
    if let Some(_) = try_extract_vec(ty) {
        let expanded = quote! {
            impl #builder_name {
                pub fn #field_name(&mut self, #field_name: #ty) -> Self {
                    self.#field_name = #field_name;
                    self.clone()
                }
            }
        };
        expanded.into()
    } else {
        let expanded = quote! {
            impl #builder_name {
                pub fn #field_name(&mut self, #field_name: #ty) -> Self {
                    self.#field_name = std::option::Option::Some(#field_name);
                    self.clone()
                }
            }
        };
        expanded.into()
    }
}

fn try_impl_field_repeat(builder_name: &Ident, f: &syn::Field) -> Option<TokenStream> {
    let field_name = &f.ident.as_ref().unwrap();
    if let Some(ty) = try_extract_vec(&f.ty) {
        for attr in f.attrs.iter() {
            match parse_each_attr_value(attr) {
                Ok(v) => {
                    if let Some(field_each) = v {
                        let expanded = quote!{
                            impl #builder_name {
                                pub fn #field_each(&mut self, #field_each: #ty) -> Self {
                                    self.#field_name.push(#field_each);
                                    self.clone()
                                }
                            }
                        };
                        return Some(expanded.into());
            }
                },
                Err(v) => {
                    return Some(v.to_compile_error().into());
                },
            };
        }
    }
    None
}

fn parse_each_attr_value(attr: &syn::Attribute) -> Result<Option<Ident>, syn::Error> {
    if let Some(seg) = attr.path.segments.first() {
        if seg.ident == "builder" {
            let args = attr.parse_args()?;
            if let syn::Meta::NameValue(values) = args {
                let arg_name = &values.path.segments.first().unwrap().ident;
                if arg_name == "each" {
                    if let syn::Lit::Str(name) = values.lit {
                        let ident: Ident = parse_str(&name.value())?;
                        return Ok(Some(ident));
                    }
                } else {
                    let start = attr.path.segments.first().unwrap().ident.span();
                    return Err(syn::Error::new(start, "expected `builder(each = \"...\")`".to_owned()));
                }
            }
        }
    }
    return Ok(None)
}

// pub fn build() -> Result<T, String>
fn impl_builder_dot_build(name: &Ident, builder_name: &Ident, s: &syn::DataStruct) -> TokenStream {
    let mut checks = vec![];
    let mut fields = vec![];

    for f in s.fields.iter() {
        let ty = &f.ty;
        let field_name = &f.ident.as_ref().unwrap();
        if let Some(_) = try_extract_option(ty) {
            checks.push(quote!{
                let #field_name = self.#field_name;
            });
        } else if let Some(_) = try_extract_vec(ty) {
            checks.push(quote!{
                let #field_name = self.#field_name;
            });
        } else {
            checks.push(quote!{
                let #field_name = match self.#field_name {
                    std::option::Option::Some(f) => f,
                    std::option::Option::None => return std::option::Option::None,
                }
            });
        }
        fields.push(quote!{
           #field_name: #field_name,
        });
    }

    let tokens = quote! {
        impl #builder_name {
            pub fn build(self) -> std::option::Option<#name> {
                #(#checks);*;

                let ret = #name {
                    #(#fields)*
                };
                std::option::Option::Some(ret)

            }
        }
    };
    tokens.into()
}

//! Types for sending data back to the language client.

use std::fmt::Display;
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::Arc;

use futures::sync::mpsc::Sender;
use futures::{Future, Sink};
use jsonrpc_core::types::{request, Id, Version};
use log::{error, trace};
use lsp_types::notification::{Notification, *};
use lsp_types::request::{ApplyWorkspaceEdit, RegisterCapability, Request, UnregisterCapability};
use lsp_types::*;
use serde::Serialize;
use serde_json::Value;

/// Sends notifications from the language server to the client.
#[derive(Debug)]
pub struct Printer {
    buffer: Sender<String>,
    initialized: Arc<AtomicBool>,
    request_id: AtomicU64,
}

impl Printer {
    pub(super) const fn new(buffer: Sender<String>, initialized: Arc<AtomicBool>) -> Self {
        Printer {
            buffer,
            initialized,
            request_id: AtomicU64::new(0),
        }
    }

    /// Notifies the client to log a particular message.
    ///
    /// This corresponds to the [`window/logMessage`] notification.
    ///
    /// [`window/logMessage`]: https://microsoft.github.io/language-server-protocol/specification#window_logMessage
    pub fn log_message<M: Display>(&self, typ: MessageType, message: M) {
        self.send_message(make_notification::<LogMessage>(LogMessageParams {
            typ,
            message: message.to_string(),
        }));
    }

    /// Notifies the client to display a particular message in the user interface.
    ///
    /// This corresponds to the [`window/showMessage`] notification.
    ///
    /// [`window/showMessage`]: https://microsoft.github.io/language-server-protocol/specification#window_showMessage
    pub fn show_message<M: Display>(&self, typ: MessageType, message: M) {
        self.send_message(make_notification::<ShowMessage>(ShowMessageParams {
            typ,
            message: message.to_string(),
        }));
    }

    /// Notifies the client to log a telemetry event.
    ///
    /// This corresponds to the [`telemetry/event`] notification.
    ///
    /// [`telemetry/event`]: https://microsoft.github.io/language-server-protocol/specification#telemetry_event
    pub fn telemetry_event<S: Serialize>(&self, data: S) {
        match serde_json::to_value(data) {
            Err(e) => error!("invalid JSON in `telemetry/event` notification: {}", e),
            Ok(value) => {
                if !value.is_null() && !value.is_array() && !value.is_object() {
                    let value = Value::Array(vec![value]);
                    self.send_message(make_notification::<TelemetryEvent>(value));
                } else {
                    self.send_message(make_notification::<TelemetryEvent>(value));
                }
            }
        }
    }

    /// Register a new capability with the client.
    ///
    /// This corresponds to the [`client/registerCapability`] request.
    ///
    /// [`client/registerCapability`]: https://microsoft.github.io/language-server-protocol/specification#client_registerCapability
    pub fn register_capability(&self, registrations: Vec<Registration>) {
        // FIXME: Check whether the request succeeded or failed.
        let id = self.request_id.fetch_add(1, Ordering::SeqCst);
        self.send_message_initialized(make_request::<RegisterCapability>(
            id,
            RegistrationParams { registrations },
        ))
    }

    /// Unregister a capability with the client.
    ///
    /// This corresponds to the [`client/unregisterCapability`] request.
    ///
    /// [`client/unregisterCapability`]: https://microsoft.github.io/language-server-protocol/specification#client_unregisterCapability
    pub fn unregister_capability(&self, unregisterations: Vec<Unregistration>) {
        // FIXME: Check whether the request succeeded or failed.
        let id = self.request_id.fetch_add(1, Ordering::SeqCst);
        self.send_message_initialized(make_request::<UnregisterCapability>(
            id,
            UnregistrationParams { unregisterations },
        ))
    }

    /// Requests a workspace resource be edited on the client side and returns whether the edit was
    /// applied.
    ///
    /// This corresponds to the [`workspace/applyEdit`] request.
    ///
    /// [`workspace/applyEdit`]: https://microsoft.github.io/language-server-protocol/specification#workspace_applyEdit
    pub fn apply_edit(&self, edit: WorkspaceEdit) -> bool {
        // FIXME: Check whether the request succeeded or failed and retrieve apply status.
        let id = self.request_id.fetch_add(1, Ordering::SeqCst);
        self.send_message_initialized(make_request::<ApplyWorkspaceEdit>(
            id,
            ApplyWorkspaceEditParams { edit },
        ));
        true
    }

    /// Submits validation diagnostics for an open file with the given URI.
    ///
    /// This corresponds to the [`textDocument/publishDiagnostics`] notification.
    ///
    /// [`textDocument/publishDiagnostics`]: https://microsoft.github.io/language-server-protocol/specification#textDocument_publishDiagnostics
    pub fn publish_diagnostics(&self, uri: Url, diagnostics: Vec<Diagnostic>) {
        self.send_message_initialized(make_notification::<PublishDiagnostics>(
            PublishDiagnosticsParams::new(uri, diagnostics),
        ));
    }

    fn send_message(&self, message: String) {
        tokio_executor::spawn(
            self.buffer
                .clone()
                .send(message)
                .map(|_| ())
                .map_err(|_| error!("failed to send message")),
        );
    }

    fn send_message_initialized(&self, message: String) {
        if self.initialized.load(Ordering::SeqCst) {
            self.send_message(message)
        } else {
            trace!("server not initialized, supressing message: {}", message);
        }
    }
}

/// Constructs a JSON-RPC request from its corresponding LSP type.
fn make_request<N>(id: u64, params: N::Params) -> String
where
    N: Request,
    N::Params: Serialize,
{
    // Since these types come from the `lsp-types` crate and validity is enforced via the
    // `Request` trait, the `unwrap()` calls below should never fail.
    let output = serde_json::to_string(&params).unwrap();
    let params = serde_json::from_str(&output).unwrap();
    serde_json::to_string(&request::MethodCall {
        jsonrpc: Some(Version::V2),
        id: Id::Num(id),
        method: N::METHOD.to_owned(),
        params,
    })
    .unwrap()
}

/// Constructs a JSON-RPC notification from its corresponding LSP type.
fn make_notification<N>(params: N::Params) -> String
where
    N: Notification,
    N::Params: Serialize,
{
    // Since these types come from the `lsp-types` crate and validity is enforced via the
    // `Notification` trait, the `unwrap()` calls below should never fail.
    let output = serde_json::to_string(&params).unwrap();
    let params = serde_json::from_str(&output).unwrap();
    serde_json::to_string(&request::Notification {
        jsonrpc: Some(Version::V2),
        method: N::METHOD.to_owned(),
        params,
    })
    .unwrap()
}

#[cfg(test)]
mod tests {
    use futures::{future, sync::mpsc, Stream};
    use serde_json::json;
    use tokio::runtime::current_thread;

    use super::*;

    fn assert_printer_messages<F: FnOnce(Printer)>(f: F, expected: String) {
        let (tx, rx) = mpsc::channel(1);
        let printer = Printer::new(tx, Arc::new(AtomicBool::new(true)));

        current_thread::block_on_all(
            future::lazy(move || {
                f(printer);
                rx.collect()
            })
            .and_then(move |messages| {
                assert_eq!(messages, vec![expected]);
                Ok(())
            }),
        )
        .unwrap();
    }

    #[test]
    fn log_message() {
        let (typ, message) = (MessageType::Log, "foo bar".to_owned());
        let expected = make_notification::<LogMessage>(LogMessageParams {
            typ,
            message: message.clone(),
        });

        assert_printer_messages(|p| p.log_message(typ, message), expected);
    }

    #[test]
    fn show_message() {
        let (typ, message) = (MessageType::Log, "foo bar".to_owned());
        let expected = make_notification::<ShowMessage>(ShowMessageParams {
            typ,
            message: message.clone(),
        });

        assert_printer_messages(|p| p.show_message(typ, message), expected);
    }

    #[test]
    fn telemetry_event() {
        let null = json!(null);
        let expected = make_notification::<TelemetryEvent>(null.clone());
        assert_printer_messages(|p| p.telemetry_event(null), expected);

        let array = json!([1, 2, 3]);
        let expected = make_notification::<TelemetryEvent>(array.clone());
        assert_printer_messages(|p| p.telemetry_event(array), expected);

        let object = json!({});
        let expected = make_notification::<TelemetryEvent>(object.clone());
        assert_printer_messages(|p| p.telemetry_event(object), expected);

        let anything_else = json!("hello");
        let wrapped = Value::Array(vec![anything_else.clone()]);
        let expected = make_notification::<TelemetryEvent>(wrapped);
        assert_printer_messages(|p| p.telemetry_event(anything_else), expected);
    }

    #[test]
    fn publish_diagnostics() {
        let uri: Url = "file:///path/to/file".parse().unwrap();
        let diagnostics = vec![Diagnostic::new_simple(Default::default(), "example".into())];

        let params = PublishDiagnosticsParams::new(uri.clone(), diagnostics.clone());
        let expected = make_notification::<PublishDiagnostics>(params);

        assert_printer_messages(|p| p.publish_diagnostics(uri, diagnostics), expected);
    }
}

