#[derive(Clone)]
pub struct HCaptchaConfig {
    pub site_key: String,
    pub secret: String,
}

/// 反馈表单页面
async fn feed(Extension(cfg): Extension<HCaptchaConfig>) -> Result<Html<String>, String> {
    let tpl = FeedTemplate {
        site_key: cfg.site_key,
    };
    let html = tpl.render().map_err(|err| err.to_string())?;
    Ok(Html(html))
}

/// 反馈信息处理
async fn feed_action(
    Extension(cfg): Extension<HCaptchaConfig>,
    Form(frm): Form<SubmitFeed>,
) -> Result<Html<String>, String> {
    // 人机验证
    let result = hcaptcha_verify::verify(frm.hcaptcha_response, cfg.secret).await?;
    if !result {
        return Err("Please verify your hcaptcha".to_string());
    };

    let tpl = FeedActionTemplate {
        feed: Feed {
            nickname: frm.nickname,
            email: frm.email,
            message: frm.message,
        },
    };
    let html = tpl.render().map_err(|err| err.to_string())?;
    Ok(Html(html))
}

#[tokio::main]
async fn main() {
    let app = Router::new()
        .route("/feed", routing::get(feed).post(feed_action))
        .layer(AddExtensionLayer::new(HCaptchaConfig {
            site_key: String::from(HCAPTCHA_SITE_KEY),
            secret: String::from(HCAPTCHA_SECRET_KEY),
        }));

    axum::Server::bind(&"127.0.0.1:9527".parse().unwrap())
        .serve(app.into_make_service())
        .await
        .unwrap();
}

use crate::os_input_output::ClientOsApi;
use crate::InputInstruction;
use std::collections::HashMap;
use terminfo::{capability as cap, Database as TerminfoDatabase};
use termion::input::TermReadEventsAndRaw;
use zellij_utils::channels::SenderWithContext;
use zellij_utils::input::mouse::MouseEvent;
use zellij_utils::termion;

fn keys_to_adjust() -> HashMap<Vec<u8>, Vec<u8>> {
    let mut keys_to_adjust = HashMap::new();
    if let Ok(terminfo_db) = TerminfoDatabase::from_env() {
        // TODO: there might be more adjustments we can do here, but I held off on them because I'm
        // not sure they're a thing in these modern times. It should be pretty straightforward to
        // implement them if they are...
        if let Some(adjusted_home_key) = terminfo_db
            .get::<cap::KeyHome>()
            .and_then(|k| k.expand().to_vec().ok())
        {
            keys_to_adjust.insert(vec![27, 91, 72], adjusted_home_key);
        }
        if let Some(adjusted_end_key) = terminfo_db
            .get::<cap::KeyEnd>()
            .and_then(|k| k.expand().to_vec().ok())
        {
            keys_to_adjust.insert(vec![27, 91, 70], adjusted_end_key);
        }
    }
    keys_to_adjust
}

fn bracketed_paste_end_position(stdin_buffer: &[u8]) -> Option<usize> {
    let bracketed_paste_end = vec![27, 91, 50, 48, 49, 126]; // \u{1b}[201~
    let mut bp_position = 0;
    let mut position = None;
    for (i, byte) in stdin_buffer.iter().enumerate() {
        if Some(byte) == bracketed_paste_end.get(bp_position) {
            position = Some(i);
            bp_position += 1;
            if bp_position == bracketed_paste_end.len() {
                break;
            }
        } else {
            bp_position = 0;
            position = None;
        }
    }
    if bp_position == bracketed_paste_end.len() {
        position
    } else {
        None
    }
}

pub(crate) fn stdin_loop(
    os_input: Box<dyn ClientOsApi>,
    send_input_instructions: SenderWithContext<InputInstruction>,
) {
    let mut pasting = false;
    let bracketed_paste_start = vec![27, 91, 50, 48, 48, 126]; // \u{1b}[200~
    let csi_mouse_sgr_start = vec![27, 91, 60];
    let adjusted_keys = keys_to_adjust();
    loop {
        let mut stdin_buffer = os_input.read_from_stdin();
        if pasting
            || (stdin_buffer.len() > bracketed_paste_start.len()
                && stdin_buffer
                    .iter()
                    .take(bracketed_paste_start.len())
                    .eq(&bracketed_paste_start))
        {
            match bracketed_paste_end_position(&stdin_buffer) {
                Some(paste_end_position) => {
                    let starts_with_bracketed_paste_start = stdin_buffer
                        .iter()
                        .take(bracketed_paste_start.len())
                        .eq(&bracketed_paste_start);

                    let ends_with_bracketed_paste_end = true;

                    let mut pasted_input: Vec<u8> =
                        stdin_buffer.drain(..=paste_end_position).collect();
                    if starts_with_bracketed_paste_start {
                        drop(pasted_input.drain(..6)); // bracketed paste start
                    }
                    drop(pasted_input.drain(pasted_input.len() - 6..)); // bracketed paste end

                    send_input_instructions
                        .send(InputInstruction::PastedText((
                            starts_with_bracketed_paste_start,
                            pasted_input,
                            ends_with_bracketed_paste_end,
                        )))
                        .unwrap();
                    pasting = false;
                }
                None => {
                    let starts_with_bracketed_paste_start = stdin_buffer
                        .iter()
                        .take(bracketed_paste_start.len())
                        .eq(&bracketed_paste_start);
                    if starts_with_bracketed_paste_start {
                        drop(stdin_buffer.drain(..6)); // bracketed paste start
                    }

                    send_input_instructions
                        .send(InputInstruction::PastedText((
                            starts_with_bracketed_paste_start,
                            stdin_buffer,
                            false,
                        )))
                        .unwrap();
                    pasting = true;
                    continue;
                }
            }
        }
        if stdin_buffer.is_empty() {
            continue;
        }
        for key_result in stdin_buffer.events_and_raw() {
            let (key_event, raw_bytes) = key_result.unwrap();
            let raw_bytes = adjusted_keys.get(&raw_bytes).cloned().unwrap_or(raw_bytes);
            if let termion::event::Event::Mouse(me) = key_event {
                let mouse_event = zellij_utils::input::mouse::MouseEvent::from(me);
                if let MouseEvent::Hold(_) = mouse_event {
                    // as long as the user is holding the mouse down (no other stdin, eg.
                    // MouseRelease) we need to keep sending this instruction to the app,
                    // because the app itself doesn't have an event loop in the proper
                    // place
                    let mut poller = os_input.stdin_poller();
                    send_input_instructions
                        .send(InputInstruction::KeyEvent(
                            key_event.clone(),
                            raw_bytes.clone(),
                        ))
                        .unwrap();
                    loop {
                        let ready = poller.ready();
                        if ready {
                            break;
                        }
                        send_input_instructions
                            .send(InputInstruction::KeyEvent(
                                key_event.clone(),
                                raw_bytes.clone(),
                            ))
                            .unwrap();
                    }
                    continue;
                }
            }

            // FIXME: termion does not properly parse some csi sgr mouse sequences
            // like ctrl + click.
            // As a workaround, to avoid writing these sequences to tty stdin,
            // we discard them.
            if let termion::event::Event::Unsupported(_) = key_event {
                if raw_bytes.len() > csi_mouse_sgr_start.len()
                    && raw_bytes[0..csi_mouse_sgr_start.len()] == csi_mouse_sgr_start
                {
                    continue;
                }
            }

            send_input_instructions
                .send(InputInstruction::KeyEvent(key_event, raw_bytes))
                .unwrap();
        }
    }
}

use crate::{generated::css_classes::C, Msg as GlobalMsg};
use seed::{prelude::*, *};
use zia::Context;

pub struct Model {
    context: Context,
    input: String,
    output: String,
}

impl Default for Model {
    fn default() -> Self {
        Self {
            context: Context::new(),
            input: String::new(),
            output: String::new(),
        }
    }
}

#[derive(Clone)]
pub enum Msg {
    Input(String),
    Submit,
    Nothing,
}

pub fn update(msg: Msg, model: &mut Model) {
    match msg {
        Msg::Input(s) => model.input = s,
        Msg::Submit => {
            model.output = model.context.execute(&model.input);
            model.input = String::new();
        },
        Msg::Nothing => {},
    };
}

pub fn view(model: &Model) -> impl View<GlobalMsg> {
    div![
        class![C.flex, C.flex_col, C.justify_center, C.flex_1,],
        vec![
            input![
                class![C.border_primary, C.border_2],
                attrs! {At::Type => "text", At::Name => "input", At::Value => model.input},
                input_ev(Ev::Input, |s| GlobalMsg::Home(Msg::Input(s))),
                keyboard_ev("keydown", |ev| if ev.key_code() == 13 {
                    GlobalMsg::Home(Msg::Submit)
                } else {
                    GlobalMsg::Home(Msg::Nothing)
                }),
            ],
            p![model.output]
        ]
    ]
}

use byteorder::{ReadBytesExt, WriteBytesExt};
use std::error::Error;
use std::io::prelude::*;

use backend::Backend;
use types::{self, FromSql, ToSql, IsNull};

impl<DB: Backend<RawValue=[u8]>> FromSql<types::Float, DB> for f32 {
    fn from_sql(bytes: Option<&[u8]>) -> Result<Self, Box<Error+Send+Sync>> {
        let mut bytes = not_none!(bytes);
        debug_assert!(bytes.len() <= 4, "Received more than 4 bytes while decoding \
                      an f32. Was a double accidentally marked as float?");
        bytes.read_f32::<DB::ByteOrder>().map_err(|e| Box::new(e) as Box<Error+Send+Sync>)
    }
}

impl<DB: Backend> ToSql<types::Float, DB> for f32 {
    fn to_sql<W: Write>(&self, out: &mut W) -> Result<IsNull, Box<Error+Send+Sync>> {
        out.write_f32::<DB::ByteOrder>(*self)
            .map(|_| IsNull::No)
            .map_err(|e| Box::new(e) as Box<Error+Send+Sync>)
    }
}

impl<DB: Backend<RawValue=[u8]>> FromSql<types::Double, DB> for f64 {
    fn from_sql(bytes: Option<&[u8]>) -> Result<Self, Box<Error+Send+Sync>> {
        let mut bytes = not_none!(bytes);
        debug_assert!(bytes.len() <= 8, "Received more than 8 bytes while decoding \
                      an f64. Was a numeric accidentally marked as dobule?");
        bytes.read_f64::<DB::ByteOrder>().map_err(|e| Box::new(e) as Box<Error+Send+Sync>)
    }
}

impl<DB: Backend> ToSql<types::Double, DB> for f64 {
    fn to_sql<W: Write>(&self, out: &mut W) -> Result<IsNull, Box<Error+Send+Sync>> {
        out.write_f64::<DB::ByteOrder>(*self)
            .map(|_| IsNull::No)
            .map_err(|e| Box::new(e) as Box<Error+Send+Sync>)
    }
}

/**
 * gba crate has its own logging macros, but I wanted a little more info in it
 *  & compiling out lower-level statements in release
 */
use core::fmt::{Arguments, Write};
use gba::mgba::{MGBADebug, MGBADebugLevel};

// FIXME: load-bearing logs in some places due to optimization errors, can't disable some of these...
#[cfg(not(debug_assertions))]
pub const STATIC_MAX_LEVEL: MGBADebugLevel = MGBADebugLevel::Info;
#[cfg(debug_assertions)]
pub const STATIC_MAX_LEVEL: MGBADebugLevel = MGBADebugLevel::Debug;

pub const STATIC_LEVEL_NAMES: [&str; 5] = ["F", "E", "W", "I", "D"];

#[instruction_set(arm::t32)]
pub fn internal_write_log(mgba: &mut MGBADebug, args: Arguments) {
    if let Some(s) = args.as_str() {
        let _ = mgba.write_str(s);
    } else {
        let _ = mgba.write_fmt(args);
    }
}

#[macro_export]
macro_rules! log {
    (target: $target:expr, $lvl:expr, $message:expr) => ({
        let lvl = $lvl;
        if lvl as u16 <= $crate::logging::STATIC_MAX_LEVEL as u16 {
            if let Some(mut mgba) = gba::mgba::MGBADebug::new() {
                $crate::logging::internal_write_log(&mut mgba, format_args!(
                    "[{}] ({}) {}",
                    $crate::logging::STATIC_LEVEL_NAMES[lvl as usize],
                    $target,
                    $message
                ));
                mgba.send(lvl);
            }
        }
    });
    (target: $target:expr, $lvl:expr, $($arg:tt)+) => ({
        let lvl = $lvl;
        if lvl as u16 <= $crate::logging::STATIC_MAX_LEVEL as u16 {
            if let Some(mut mgba) = gba::mgba::MGBADebug::new() {
                $crate::logging::internal_write_log(&mut mgba, format_args!(
                    "[{}] ({}) ",
                    $crate::logging::STATIC_LEVEL_NAMES[lvl as usize],
                    $target
                ));
                $crate::logging::internal_write_log(&mut mgba, format_args!($($arg)+));
                mgba.send(lvl);
            }
        }
    });
    ($lvl:expr, $($arg:tt)+) => ($crate::log!(target: module_path!(), $lvl, $($arg)+))
}

#[macro_export]
macro_rules! debug {
    (target: $target:expr, $($arg:tt)+) => (
        $crate::log!(target: $target, gba::mgba::MGBADebugLevel::Debug, $($arg)+);
    );
    ($($arg:tt)+) => (
        $crate::log!(gba::mgba::MGBADebugLevel::Debug, $($arg)+);
    )
}

#[macro_export]
macro_rules! info {
    (target: $target:expr, $($arg:tt)+) => (
        $crate::log!(target: $target, gba::mgba::MGBADebugLevel::Info, $($arg)+);
    );
    ($($arg:tt)+) => (
        $crate::log!(gba::mgba::MGBADebugLevel::Info, $($arg)+);
    )
}

#[macro_export]
macro_rules! warn {
    (target: $target:expr, $($arg:tt)+) => (
        $crate::log!(target: $target, gba::mgba::MGBADebugLevel::Warning, $($arg)+);
    );
    ($($arg:tt)+) => (
        $crate::log!(gba::mgba::MGBADebugLevel::Warning, $($arg)+);
    )
}

#[macro_export]
macro_rules! error {
    (target: $target:expr, $($arg:tt)+) => (
        $crate::log!(target: $target, gba::mgba::MGBADebugLevel::Error, $($arg)+);
    );
    ($($arg:tt)+) => (
        $crate::log!(gba::mgba::MGBADebugLevel::Error, $($arg)+);
    )
}

#[macro_export]
macro_rules! fatal {
    (target: $target:expr, $($arg:tt)+) => (
        $crate::log!(target: $target, gba::mgba::MGBADebugLevel::Fatal, $($arg)+);
        panic!();
    );
    ($($arg:tt)+) => (
        $crate::log!(gba::mgba::MGBADebugLevel::Fatal, $($arg)+);
        panic!();
    )
}

