#[no_mangle]
pub unsafe extern "C" fn chain_controller_chain_head(
    chain_controller: *mut c_void,
    block: *mut *const u8,
    block_len: *mut usize,
    block_cap: *mut usize,
) -> ErrorCode {
    check_null!(chain_controller);

    let controller = (*(chain_controller
        as *mut ChainController<PyExecutor, PyPermissionVerifier>))
        .light_clone();

    if let Some(chain_head) = controller.chain_head().map(proto::block::Block::from) {
        match chain_head.write_to_bytes() {
            Ok(payload) => {
                *block_cap = payload.capacity();
                *block_len = payload.len();
                *block = payload.as_slice().as_ptr();

                mem::forget(payload);

                ErrorCode::Success
            }
            Err(err) => {
                warn!("Failed to serialize Block proto to bytes: {}", err);
                ErrorCode::Unknown
            }
        }
    } else {
        *block = ptr::null();
        *block_len = 0;
        ErrorCode::Success
    }
}

struct PyChainObserver {
    py_observer: PyObject,
}

impl PyChainObserver {
    fn new(py_observer: PyObject) -> Self {
        PyChainObserver { py_observer }
    }
}

impl ChainObserver for PyChainObserver {
    fn chain_update(&mut self, block: &Block, receipts: &[TransactionReceipt]) {
        let gil_guard = Python::acquire_gil();
        let py = gil_guard.python();

        self.py_observer
            .call_method(py, "chain_update", (block, receipts), None)
            .map(|_| ())
            .map_err(|py_err| {
                pylogger::exception(py, "Unable to call observer.chain_update", py_err);
                ()
            })
            .unwrap_or(())
    }
}

impl ToPyObject for TransactionReceipt {
    type ObjectType = PyObject;

    fn to_py_object(&self, py: Python) -> PyObject {
        let txn_receipt_protobuf_mod = py
            .import("sawtooth_validator.protobuf.transaction_receipt_pb2")
            .expect("Unable to import transaction_receipt_pb2");
        let py_txn_receipt_class = txn_receipt_protobuf_mod
            .get(py, "TransactionReceipt")
            .expect("Unable to get TransactionReceipt");

        let py_txn_receipt = py_txn_receipt_class
            .call(py, cpython::NoArgs, None)
            .expect("Unable to instantiate TransactionReceipt");
        py_txn_receipt
            .call_method(
                py,
                "ParseFromString",
                (cpython::PyBytes::new(py, &self.write_to_bytes().unwrap()).into_object(),),
                None,
            )
            .expect("Unable to ParseFromString");

        py_txn_receipt
    }
}

use crate::lock::with_mutex;
use crate::radixmap::RadixMap;

use std::sync::atomic::{AtomicU64, Ordering::*};

use asc::Asc;
use parking_lot::Mutex;
use tokio::sync::Notify;

pub struct WaterMark {
    level: AtomicU64,
    queue: Mutex<RadixMap<Asc<Notify>>>,
}

impl WaterMark {
    #[inline]
    #[must_use]
    pub const fn new(lv: u64) -> Self {
        Self {
            level: AtomicU64::new(lv),
            queue: Mutex::new(RadixMap::new()),
        }
    }

    #[inline]
    pub fn bump_level(&self, lv: u64) {
        let prev = self.level.fetch_max(lv, Relaxed);
        if prev < lv {
            self.flush_queue(lv);
        }
    }

    fn flush_queue(&self, lv: u64) {
        with_mutex(&self.queue, |q: _| {
            q.drain_less_equal(lv, |_, n| n.notify_waiters())
        })
    }

    #[inline]
    #[must_use]
    pub fn level(&self) -> u64 {
        self.level.load(SeqCst)
    }

    #[inline]
    #[must_use]
    pub fn until(&self, lv: u64) -> WaterMarkUntil<'_> {
        let notify = with_mutex(&self.queue, |q| {
            let (_, n) = q.init_with(lv, || Asc::new(Notify::new()));
            Asc::clone(n)
        });
        WaterMarkUntil { watermark: self, until: lv, notify }
    }
}

pub struct WaterMarkUntil<'a> {
    watermark: &'a WaterMark,
    until: u64,
    notify: Asc<Notify>,
}

impl WaterMarkUntil<'_> {
    #[inline]
    #[must_use]
    pub fn level(&self) -> u64 {
        self.watermark.level.load(SeqCst)
    }

    #[inline]
    pub async fn wait(&self) {
        if self.level() >= self.until {
            return;
        }

        loop {
            self.notify.notified().await;
            if self.level() >= self.until {
                return;
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    use crate::clone;

    use tokio::task::spawn;

    #[tokio::test(flavor = "current_thread")]
    async fn tokio() {
        let wm = Asc::new(WaterMark::new(0));
        {
            clone!(wm);
            wm.until(0).wait().await;
        }
        assert_eq!(wm.level(), 0);

        let h1 = {
            clone!(wm);
            spawn(async move { wm.until(10000).wait().await })
        };

        let h2 = {
            clone!(wm);
            spawn(async move { wm.until(100).wait().await })
        };

        wm.bump_level(200);
        h2.await.unwrap();
        assert_eq!(wm.level(), 200);

        wm.bump_level(10000);
        h1.await.unwrap();
        assert_eq!(wm.level(), 10000);
    }
}

