#[cfg(test)]
impl DummyInfrastructure {
    async fn delay_if_configured(&self) {
        if let Some(delay) = &self.delay {
            tokio::time::sleep(delay.clone()).await;
        }
    }
}

#[cfg(test)]
#[async_trait]
impl Infrastructure for DummyInfrastructure {
    async fn get_services(&self) -> Result<MultiMap<String, Service>, failure::Error> {
        let mut s = MultiMap::new();

        let services = self.services.lock().unwrap();
        for (app, configs) in services.iter_all() {
            for config in configs {
                let service = ServiceBuilder::new()
                    .id(format!("{}-{}", app.clone(), config.service_name()))
                    .app_name(app.clone())
                    .config(config.clone())
                    .service_status(ServiceStatus::Running)
                    .started_at(
                        DateTime::parse_from_rfc3339("2019-07-18T07:30:00.000000000Z")
                            .unwrap()
                            .with_timezone(&Utc),
                    )
                    .build()
                    .unwrap();

                s.insert(app.clone(), service);
            }
        }

        Ok(s)
    }

    async fn deploy_services(
        &self,
        _status_id: &String,
        app_name: &String,
        configs: &Vec<ServiceConfig>,
        _container_config: &ContainerConfig,
    ) -> Result<Vec<Service>, failure::Error> {
        self.delay_if_configured().await;

        let mut services = self.services.lock().unwrap();

        if let Some(running_services) = services.get_vec_mut(app_name) {
            let service_names = configs
                .iter()
                .map(|c| c.service_name())
                .collect::<HashSet<&String>>();

            running_services.retain(|config| !service_names.contains(config.service_name()));
        }

        for config in configs {
            info!("started {} for {}.", config.service_name(), app_name);
            services.insert(app_name.clone(), config.clone());
        }
        Ok(vec![])
    }

    async fn stop_services(
        &self,
        _status_id: &String,
        app_name: &String,
    ) -> Result<Vec<Service>, failure::Error> {
        self.delay_if_configured().await;

        let mut services = self.services.lock().unwrap();
        match services.remove(app_name) {
            Some(services) => Ok(services
                .into_iter()
                .map(|sc| {
                    ServiceBuilder::new()
                        .app_name(app_name.clone())
                        .id(sc.service_name().clone())
                        .config(sc)
                        .started_at(
                            DateTime::parse_from_rfc3339("2019-07-18T07:25:00.000000000Z")
                                .unwrap()
                                .with_timezone(&Utc),
                        )
                        .build()
                        .unwrap()
                })
                .collect()),
            None => Ok(vec![]),
        }
    }

    async fn get_logs(
        &self,
        app_name: &String,
        service_name: &String,
        _from: &Option<DateTime<FixedOffset>>,
        _limit: usize,
    ) -> Result<Option<Vec<(DateTime<FixedOffset>, String)>>, failure::Error> {
        Ok(Some(vec![
            (
                DateTime::parse_from_rfc3339("2019-07-18T07:25:00.000000000Z").unwrap(),
                format!("Log msg 1 of {} of app {}\n", service_name, app_name),
            ),
            (
                DateTime::parse_from_rfc3339("2019-07-18T07:30:00.000000000Z").unwrap(),
                format!("Log msg 2 of {} of app {}\n", service_name, app_name),
            ),
            (
                DateTime::parse_from_rfc3339("2019-07-18T07:35:00.000000000Z").unwrap(),
                format!("Log msg 3 of {} of app {}\n", service_name, app_name),
            ),
        ]))
    }

    async fn change_status(
        &self,
        _app_name: &String,
        _service_name: &String,
        _status: ServiceStatus,
    ) -> Result<Option<Service>, failure::Error> {
        Ok(None)
    }
}

use std::char;

pub trait ToBraille {
    /// Get the unicode braille symbol for any given map of bits
    ///
    /// # Examples
    ///
    /// ```
    /// assert_eq!(0b10011101.to_braille() == '⢵');
    /// ```
    fn to_braille(&self) -> char;
}

impl ToBraille for u8 {
    fn to_braille(&self) -> char {
        // Braille in unicode works weirdly so we have to warp the bits
        // around.
        //
        // If you number each bit of a byte like 0b12345678 then a braille
        // character looks like:
        //
        //      8  5
        //      7  4
        //      6  3
        //      2  1
        //
        // This is the core reason for all the weird bitwise reordering.
        //
        // See https://en.wikipedia.org/wiki/Braille_Patterns for more info
        let warped_dotmap: u8 =
            (self >> 7 & 0b00000001u8) | // Moving X_______ to _______X
            (self >> 3 & 0b00001000u8) | // Moving _X______ to ____X___
            (self >> 4 & 0b00000010u8) | // Moving __X_____ to ______X_
            (self >> 0 & 0b00010000u8) | // Moving ___X____ to ___X____
            (self >> 1 & 0b00000100u8) | // Moving ____X___ to _____X__
            (self << 3 & 0b00100000u8) | // Moving _____X__ to __X_____
            (self << 5 & 0b01000000u8) | // Moving ______X_ to _X______
            (self << 7 & 0b10000000u8);  // Moving _______X to X_______
        char::from_u32(10240 + warped_dotmap as u32).unwrap()
    }
}


#[cfg(test)]
mod tests {
    use super::ToBraille;

    #[test]
    fn test_u8_to_braille() {
        assert_eq!(0b00000000.to_braille(), '⠀');
        assert_eq!(0b11111111.to_braille(), '⣿');

        assert_eq!(0b00001111.to_braille(), '⣤');
        assert_eq!(0b11110000.to_braille(), '⠛');
        assert_eq!(0b10011001.to_braille(), '⢕');
        assert_eq!(0b10101010.to_braille(), '⡇');
        assert_eq!(0b01010101.to_braille(), '⢸');

        assert_eq!(0b10011101.to_braille(), '⢵');
    }
}

