pub mod rv32m;

use std::fmt::Debug;
use cpu::CPU;

pub trait Instruction: Debug {
    fn execute(&self, cpu: &mut CPU);
    fn to_raw(&self) -> u32;
}

pub fn parse(instruction: u32) -> Option<Box<Instruction>> {
    match encoding::get_opcode(instruction) {
        0x03 => rv32i::Load::parse(instruction).map(|i| Box::new(i) as Box<Instruction>),
        // 0x07 => load_fp::LoadFp::parse(instruction).map(|i| Box::new(i) as Box<Instruction>),
        // 0x0F => misc_mem::MiscMem::parse(instruction).map(|i| Box::new(i) as Box<Instruction>),
        0x13 => rv32i::OpImm::parse(instruction).map(|i| Box::new(i) as Box<Instruction>),
        0x17 => rv32i::Auipc::parse(instruction).map(|i| Box::new(i) as Box<Instruction>),
        0x23 => rv32i::Store::parse(instruction).map(|i| Box::new(i) as Box<Instruction>),
        // 0x27 => store_fp::StoreFp::parse(instruction).map(|i| Box::new(i) as Box<Instruction>),
        // 0x2F => amo::Amo::parse(instruction).map(|i| Box::new(i) as Box<Instruction>),
        0x33 => {
            match encoding::get_funct7(instruction) {
                0x00 | 0x20 => {
                    rv32i::Op::parse(instruction).map(|i| Box::new(i) as Box<Instruction>)
                }
                0x01 => rv32m::Op::parse(instruction).map(|i| Box::new(i) as Box<Instruction>),
                _ => None,
            }
        }
        0x37 => rv32i::Lui::parse(instruction).map(|i| Box::new(i) as Box<Instruction>),
        // 0x43 => madd::Madd::parse(instruction).map(|i| Box::new(i) as Box<Instruction>),
        // 0x47 => msub::Msub::parse(instruction).map(|i| Box::new(i) as Box<Instruction>),
        // 0x4B => nmsub::Nmsub::parse(instruction).map(|i| Box::new(i) as Box<Instruction>),
        // 0x4F => nmadd::Nmadd::parse(instruction).map(|i| Box::new(i) as Box<Instruction>),
        // 0x53 => op_fp::OpFp::parse(instruction).map(|i| Box::new(i) as Box<Instruction>),
        0x63 => rv32i::Branch::parse(instruction).map(|i| Box::new(i) as Box<Instruction>),
        0x67 => rv32i::Jalr::parse(instruction).map(|i| Box::new(i) as Box<Instruction>),
        0x6F => rv32i::Jal::parse(instruction).map(|i| Box::new(i) as Box<Instruction>),
        // 0x73 => system::System::parse(instruction).map(|i| Box::new(i) as Box<Instruction>),
        op => {
            println!("unknown opcode: {:02x}", op);
            None
        }
    }
}

use crate::exceptions::runtime_exceptions::{ExpectedInstructionArgument, TypeException};
use crate::instructions::op_codes::JexOpCode;
use crate::instructions::types::JexInstruction;
use crate::types::JexMachine;
use extendable_vm::{ByteReadable, Exception, Instruction, InstructionFn, InstructionPointer};

pub const POP_INSTRUCTION: JexInstruction = Instruction {
    op_code: JexOpCode::Pop as u8,
    name: "POP",
    instruction_fn: InstructionFn::Raw {
        byte_arity: 0,
        instruction_fn: pop_instruction,
    },
};

pub const GET_LOCAL_INSTRUCTION: JexInstruction = Instruction {
    op_code: JexOpCode::GetLocal as u8,
    name: "GET_LOCAL",
    instruction_fn: InstructionFn::Raw {
        byte_arity: 1,
        instruction_fn: get_local_instruction,
    },
};

pub const SET_LOCAL_INSTRUCTION: JexInstruction = Instruction {
    op_code: JexOpCode::SetLocal as u8,
    name: "SET_LOCAL",
    instruction_fn: InstructionFn::Raw {
        byte_arity: 1,
        instruction_fn: set_local_instruction,
    },
};

pub const GET_GLOBAL_INSTRUCTION: JexInstruction = Instruction {
    op_code: JexOpCode::GetGlobal as u8,
    name: "GET_GLOBAL",
    instruction_fn: InstructionFn::Raw {
        byte_arity: 1,
        instruction_fn: get_global_instruction,
    },
};

pub const DEFINE_GLOBAL_INSTRUCTION: JexInstruction = Instruction {
    op_code: JexOpCode::DefineGlobal as u8,
    name: "DEFINE_GLOBAL",
    instruction_fn: InstructionFn::Raw {
        byte_arity: 1,
        instruction_fn: define_global_instruction,
    },
};

pub const SET_GLOBAL_INSTRUCTION: JexInstruction = Instruction {
    op_code: JexOpCode::SetGlobal as u8,
    name: "SET_GLOBAL",
    instruction_fn: InstructionFn::Raw {
        byte_arity: 1,
        instruction_fn: set_global_instruction,
    },
};

fn pop_instruction(
    machine: &mut JexMachine,
    mut _args: InstructionPointer,
) -> Result<(), Exception> {
    machine.pop_operand()?;
    Ok(())
}

fn get_local_instruction(
    machine: &mut JexMachine,
    mut args: InstructionPointer,
) -> Result<(), Exception> {
    let relative_slot = machine.read(&mut args).ok_or(ExpectedInstructionArgument)?;
    let last_frame_start = machine.peek_frame()?.start_slot;
    let absolute_slot = last_frame_start + usize::from(relative_slot);
    let value = machine.get_operand(absolute_slot)?.clone();
    machine.push_operand(value);
    Ok(())
}

fn set_local_instruction(
    machine: &mut JexMachine,
    mut args: InstructionPointer,
) -> Result<(), Exception> {
    let relative_slot = machine.read(&mut args).ok_or(ExpectedInstructionArgument)?;
    let absolute_slot = machine.peek_frame()?.start_slot + usize::from(relative_slot);
    let value = machine.pop_operand()?;
    machine.set_operand(absolute_slot, value)?;
    Ok(())
}

fn get_global_instruction(
    machine: &mut JexMachine,
    mut args: InstructionPointer,
) -> Result<(), Exception> {
    let identifier_const_id = machine.read(&mut args).ok_or(ExpectedInstructionArgument)?;
    let identifier = machine
        .code
        .get_constant(args.chunk_id, usize::from(identifier_const_id))?;
    let identifier_string = identifier.as_string()?;
    let value = machine.globals.get(&identifier_string).cloned();
    if let Some(value) = value {
        machine.push_operand(value);
        Ok(())
    } else {
        Err(Exception::from(TypeException(format!(
            "Global with identifier {} not found",
            identifier_string
        ))))
    }
}

fn define_global_instruction(
    machine: &mut JexMachine,
    mut args: InstructionPointer,
) -> Result<(), Exception> {
    let identifier_const_id = machine.read(&mut args).ok_or(ExpectedInstructionArgument)?;
    let identifier = machine
        .code
        .get_constant(args.chunk_id, usize::from(identifier_const_id))?
        .as_string()?;
    let value = machine.pop_operand()?;
    machine.globals.insert(identifier, value);
    Ok(())
}

fn set_global_instruction(
    machine: &mut JexMachine,
    args: InstructionPointer,
) -> Result<(), Exception> {
    define_global_instruction(machine, args)
}

