    InternalError(&'static str),
    #[fail(display = "Incorrect usage: {}", _0)]
    UsageError(String),
    #[fail(display = "{}", _0)]
    ParseError(#[cause] parser::ParseError),
    #[fail(display = "{}", _0)]
    ValidationError(#[cause] ValidationError),
    #[fail(display = "{}", _0)]
