#[derive(Debug, thiserror::Error)]
pub enum Error {
    #[error("Builder failed to create the message. A required field on the contact is missing. (name = {name})")]
    MissingField {
        name: &'static str,
        channel_type: ChannelType,
        context: Option<&'static str>,
    },

    #[error("The channel does not have a template registered for this notification.")]
    MissingTemplate {
        notification_id: String,
        channel_type: ChannelType,
        context: Option<&'static str>,
    },

    #[error("The contact isn't valid.")]
    InvalidContact {
        source: anyhow::Error,
        context: Option<&'static str>,
        channel_type: ChannelType,
    },

    #[error("The channel failed to send the message.")]
    Send {
        source: anyhow::Error,
        context: Option<&'static str>,
        channel_type: ChannelType,
        provider_id: &'static str,
    },
}

//! An interface for interacting with the Rust [playground](https://play.rust-lang.org/)
//!
//! # examples
//!
//! ```no_run
//! // recess interfaces
//! extern crate recess;
//! // tokio async io
//! extern crate tokio_core;
//! // futures combinators
//! extern crate futures;
//!
//! use recess::{Client, CompileRequest};
//! use futures::Future;
//! use tokio_core::reactor::Core;
//!
//! fn main() {
//!   let mut core = Core::new().unwrap();
//!   let client = Client::new(
//!      &core.handle(),
//!   );
//!
//!   let work = client.compile(CompileRequest::builder(
//!              r#"fn main() { println!("{}", 1); }"#
//!            )
//!           .build().unwrap())
//!        .and_then(|result| {
//!            println!("{}", result.stdout);
//!            println!("{}", result.stderr);
//!            Ok(())
//!        });
//!
//!   println!("{:#?}", core.run(work))
//! }
//! ```
//!
//! # Cargo features
//!
//! This crate has one Cargo feature, `tls`, which adds HTTPS support via the `Client::new`
//! constructor. This feature is enabled by default.
#![warn(missing_docs)]

