use std::sync::Arc;

use common_arrow::arrow::bitmap::MutableBitmap;
use common_exception::ErrorCode;
use common_exception::Result;

use crate::prelude::*;

pub struct MutableStructColumn {
    pub data_type: DataTypeImpl,
    pub inner_columns: Vec<Box<dyn MutableColumn>>,
}

impl MutableStructColumn {
    pub fn from_data(data_type: DataTypeImpl, inner_columns: Vec<Box<dyn MutableColumn>>) -> Self {
        Self {
            data_type,
            inner_columns,
        }
    }

    #[inline]
    pub fn append_value(&mut self, struct_value: StructValue) {
        for (i, value) in struct_value.values.iter().enumerate() {
            self.inner_columns[i]
                .append_data_value(value.clone())
                .unwrap();
        }
    }

    #[inline]
    pub fn pop_value(&mut self) -> Option<StructValue> {
        if self.inner_columns[0].len() > 0 {
            let mut values = Vec::with_capacity(self.inner_columns.len());
            for inner_column in self.inner_columns.iter_mut() {
                let value = inner_column.pop_data_value().unwrap();
                values.push(value);
            }
            return Some(StructValue::new(values));
        }
        None
    }
}

impl Default for MutableStructColumn {
    fn default() -> Self {
        Self::with_capacity_meta(0, ColumnMeta::Struct {
            inner_names: vec!["default".to_string()],
            inner_types: vec![UInt64Type::new_impl()],
        })
    }
}

impl MutableColumn for MutableStructColumn {
    fn data_type(&self) -> DataTypeImpl {
        self.data_type.clone()
    }

    fn as_any(&self) -> &dyn std::any::Any {
        self
    }

    fn as_mut_any(&mut self) -> &mut dyn std::any::Any {
        self
    }

    fn append_default(&mut self) {
        for inner in self.inner_columns.iter_mut() {
            inner.append_default();
        }
    }

    fn validity(&self) -> Option<&MutableBitmap> {
        None
    }

    fn shrink_to_fit(&mut self) {
        for inner in self.inner_columns.iter_mut() {
            inner.shrink_to_fit();
        }
    }

    fn len(&self) -> usize {
        if self.inner_columns.is_empty() {
            return 0;
        }
        self.inner_columns[0].len()
    }

    fn to_column(&mut self) -> ColumnRef {
        Arc::new(self.finish())
    }

    fn append_data_value(&mut self, value: DataValue) -> Result<()> {
        match &value {
            DataValue::Struct(struct_) => {
                if struct_.len() != self.inner_columns.len() {
                    return Err(ErrorCode::BadDataValueType(format!(
                        "DataValue Error: Cannot convert {:?} to Struct, length mismatch",
                        value,
                    )));
                }

                for (inner, value) in self.inner_columns.iter_mut().zip(struct_.iter()) {
                    inner.append_data_value(value.clone())?;
                }
            }
            _ => {
                return Err(ErrorCode::BadDataValueType(format!(
                    "DataValue Error: Cannot convert {:?} to Struct",
                    value,
                )))
            }
        }
        Ok(())
    }

    fn pop_data_value(&mut self) -> Result<DataValue> {
        let mut values: Vec<DataValue> = Vec::with_capacity(self.inner_columns.len());
        for inner in self.inner_columns.iter_mut() {
            values.push(inner.pop_data_value()?);
        }
        Ok(DataValue::Struct(values))
    }
}

impl ScalarColumnBuilder for MutableStructColumn {
    type ColumnType = StructColumn;

    fn with_capacity(_capacity: usize) -> Self {
        panic!("Must use with_capacity_meta.")
    }

    fn with_capacity_meta(capacity: usize, meta: ColumnMeta) -> Self {
        match meta {
            ColumnMeta::Struct {
                inner_names,
                inner_types,
            } => {
                let mut inner_columns = Vec::with_capacity(inner_types.len());
                for inner_type in inner_types.iter() {
                    inner_columns.push(inner_type.create_mutable(capacity));
                }
                let data_type = StructType::new_impl(inner_names, inner_types);

                Self {
                    data_type,
                    inner_columns,
                }
            }
            _ => panic!("must be ColumnMeta::Struct"),
        }
    }

    fn push(&mut self, value: <Self::ColumnType as ScalarColumn>::RefItem<'_>) {
        match value {
            StructValueRef::Indexed { column, idx } => {
                let value = column.get(idx);
                if let DataValue::Struct(vals) = value {
                    for (i, v) in vals.iter().enumerate() {
                        self.inner_columns[i].append_data_value(v.clone()).unwrap();
                    }
                }
            }
            StructValueRef::ValueRef { val } => {
                for (i, v) in val.values.iter().enumerate() {
                    self.inner_columns[i].append_data_value(v.clone()).unwrap();
                }
            }
        }
    }

    fn finish(&mut self) -> Self::ColumnType {
        self.shrink_to_fit();
        let columns: Vec<ColumnRef> = self
            .inner_columns
            .iter_mut()
            .map(|inner| inner.to_column())
            .collect();

        StructColumn::from_data(columns, self.data_type.clone())
    }
}

use std::{fs, io, process, rc::Rc};

use crate::{downcast_any, evaluator::objects::string::Str};

use super::objects::{
    array::Array, eval_error::EvalError, float::Float, integer::Integer, ObjectRef, Type,
};

pub(super) fn len(args: &[ObjectRef]) -> ObjectRef {
    if args.len() != 1 {
        return Rc::new(EvalError::new("expected only one argument".to_string()));
    }
    let first = args.first().unwrap();
    match first.get_type() {
        Type::Array => {
            let arr_sz = downcast_any!(first => Array).values.borrow().len();
            Rc::new(Integer::new(arr_sz as isize))
        }
        Type::String => {
            let str_sz = downcast_any!(first => Str).value.len();
            Rc::new(Integer::new(str_sz as isize))
        }
        typ => Rc::new(EvalError::new(format!(
            "unsuported operation len of {}",
            typ
        ))),
    }
}

pub(super) fn puts(args: &[ObjectRef]) -> ObjectRef {
    let mut buffer = String::with_capacity(50);
    for arg in args {
        buffer.push_str(&arg.to_string())
    }
    print!("{}", buffer);
    Rc::new(Str::new(buffer))
}

pub(super) fn putsln(args: &[ObjectRef]) -> ObjectRef {
    let mut buffer = String::with_capacity(50);
    for arg in args {
        buffer.push_str(&arg.to_string())
    }
    println!("{}", buffer);
    Rc::new(Str::new(buffer))
}

pub(super) fn eputs(args: &[ObjectRef]) -> ObjectRef {
    let mut buffer = String::with_capacity(50);
    for arg in args {
        buffer.push_str(&arg.to_string())
    }
    eprint!("{}", buffer);
    Rc::new(Str::new(buffer))
}

pub(super) fn eputsln(args: &[ObjectRef]) -> ObjectRef {
    let mut buffer = String::with_capacity(50);
    for arg in args {
        buffer.push_str(&arg.to_string())
    }
    eprint!("{}", buffer);
    Rc::new(Str::new(buffer))
}

pub(super) fn exit(args: &[ObjectRef]) -> ObjectRef {
    if args.len() != 1 {
        return Rc::new(EvalError::new("expected only one argument".to_string()));
    }
    let first = args.first().unwrap();
    if first.get_type() != Type::Int {
        return Rc::new(EvalError::new("only use int values".to_string()));
    }
    process::exit(downcast_any!(first => Integer).value as i32)
}

pub(super) fn to_int(args: &[ObjectRef]) -> ObjectRef {
    if args.len() != 1 {
        return Rc::new(EvalError::new("expected only one argument".to_string()));
    }
    let first = args.first().unwrap();
    match first.get_type() {
        Type::String => {
            let string = downcast_any!(first => Str);
            if let Ok(value) = string.value.parse::<isize>() {
                Rc::new(Integer::new(value))
            } else {
                Rc::new(EvalError::new(format!(
                    "{} is not parseable to int",
                    string.value
                )))
            }
        }
        Type::Float => {
            let float = downcast_any!(first => Float);
            Rc::new(Integer::new(float.value as isize))
        }
        Type::Int => Rc::clone(first),
        _ => Rc::new(EvalError::new("this type is not parseable".to_string())),
    }
}

pub(super) fn to_float(args: &[ObjectRef]) -> ObjectRef {
    if args.len() != 1 {
        return Rc::new(EvalError::new("expected only one argument".to_string()));
    }
    let first = args.first().unwrap();
    match first.get_type() {
        Type::String => {
            let string = downcast_any!(first => Str);
            if let Ok(value) = string.value.parse::<f64>() {
                Rc::new(Float::new(value))
            } else {
                Rc::new(EvalError::new(format!(
                    "{} is not parseable to float",
                    string.value
                )))
            }
        }
        Type::Int => {
            let int = downcast_any!(first => Integer);
            Rc::new(Float::new(int.value as f64))
        }
        Type::Float => Rc::clone(first),
        _ => Rc::new(EvalError::new("this type is not parseable".to_string())),
    }
}

pub(super) fn to_string(args: &[ObjectRef]) -> ObjectRef {
    if args.len() != 1 {
        return Rc::new(EvalError::new("expected only one argument".to_string()));
    }
    Rc::new(Str::new(format!("{}", args.first().unwrap())))
}

pub(super) fn read(args: &[ObjectRef]) -> ObjectRef {
    if !args.is_empty() {
        return Rc::new(EvalError::new(
            "invalid number of arguments, expected 0 arguments".to_string(),
        ));
    }
    let mut buffer: String = String::new();
    io::stdin().read_line(&mut buffer).unwrap();
    Rc::new(Str::new(buffer))
}

pub(super) fn read_file_as_string(args: &[ObjectRef]) -> ObjectRef {
    if args.len() != 1 {
        return Rc::new(EvalError::new(
            "invalid number of arguments, expected 1 arguments".to_string(),
        ));
    }
    let first = &args[0];
    let path = if first.get_type() != Type::String {
        return Rc::new(EvalError::new("file path has to be a string".to_string()));
    } else {
        &downcast_any!(first => Str).value
    };
    match fs::read_to_string(path) {
        Ok(value) => Rc::new(Str::new(value)),
        Err(e) => Rc::new(EvalError::new(e.to_string())),
    }
}

