        assert_eq!(r.coeff, (&d).checked_div(i).unwrap().coeff);
        assert_eq!(r.coeff, d.checked_div(&i).unwrap().coeff);
        assert_eq!(r.coeff, (&d).checked_div(&i).unwrap().coeff);
        let z = CheckedDiv::checked_div(i, d).unwrap();
        assert_eq!(z.coeff, i * ten_pow(13) / coeff);
        assert_eq!(z.coeff, CheckedDiv::checked_div(&i, d).unwrap().coeff);
        assert_eq!(z.coeff, CheckedDiv::checked_div(i, &d).unwrap().coeff);
