// https://leetcode-cn.com/problems/heaters/
// Runtime: 8 ms
// Memory Usage: 2.3 MB
pub fn find_radius(houses: Vec<i32>, mut heaters: Vec<i32>) -> i32 {
    heaters.sort_unstable();
    let n = heaters.len();
    houses
        .iter()
        .map(|h| (h, heaters.binary_search(h)))
        .map(|(h, min_dist)| match min_dist {
            Ok(_) => 0,
            Err(i) => match i {
                0 => heaters[i] - h,
                x if x == n => h - heaters[i - 1],
                _ => (heaters[i] - h).min(h - heaters[i - 1]),
            },
        })
        .max()
        .unwrap_or(i32::MAX)
}
// binary_search
#[test]
fn test1_475() {
    assert_eq!(find_radius(vec![1, 2, 3], vec![2]), 1);
    assert_eq!(find_radius(vec![1, 2, 3, 4], vec![1, 4]), 1);
}

use session::game::{GameState, Session, SocialState};
use session::game::chunk::Ref;
use std::io::Result;
use protocol::*;
use protocol::messages::game::friend::*;
use protocol::variants::{
    IgnoredInformationsVariant,
    SessionIgnoredInformations
};
use protocol::messages::game::basic::BasicNoOperationMessage;
use server::{social, SERVER};
use character::social::RelationInformations;

impl Session {
    pub fn friend_added_success(&mut self, infos: (i32, RelationInformations)) {
        let (f_id, infos) = (infos.0, infos.1.as_friend());
        let buf = FriendAddedMessage {
            friend_added: infos.clone(),
        }.unwrap();
        write!(SERVER, self.base.token, buf);

        let account = self.account.as_mut().unwrap();
        let _ = account.social.friends.insert(f_id);
        let _ = self.friends_cache.insert(f_id, infos);
    }

    pub fn ignored_added_success(&mut self, infos: (i32, RelationInformations),
                                 for_session: bool) {
        let (i_id, infos) = (infos.0, infos.1.as_ignored());
        let buf = IgnoredAddedMessage {
            ignore_added: infos.clone(),
            session: for_session,
        }.unwrap();
        write!(SERVER, self.base.token, buf);

        if !for_session {
            let account = self.account.as_mut().unwrap();
            let _ = account.social.ignored.insert(i_id);
            let _ = self.ignored_cache.insert(i_id, infos);
        } else {
            let _ = self.ignored_cache.insert(
                i_id,
                IgnoredInformationsVariant::SessionIgnoredInformations(
                    SessionIgnoredInformations {
                        name: infos.name().to_string(),
                    }
                )
            );
        }
    }
}

#[register_handlers]
impl Session {
    pub fn handle_friends_get_list<'a>(&mut self, _: Ref<'a>, _: FriendsGetListMessage)
                                       -> Result<()> {
        match self.state {
            GameState::InContext(_) => (),
            _ => return Ok(()),
        };

        let buf = FriendsListMessage {
            friends_list: self.friends_cache.values().cloned().collect(),
        }.unwrap();

        write!(SERVER, self.base.token, buf);

        Ok(())
    }

    pub fn handle_friend_set_warn_on_connection<'a>(&mut self, _: Ref<'a>,
                                                    msg: FriendSetWarnOnConnectionMessage)
                                                    -> Result<()> {
        match self.state {
            GameState::InContext(_) => (),
            _ => return Ok(()),
        };

        let account = self.account.as_mut().unwrap();
        account.social.warn_on_connection = msg.enable;

        let buf = BasicNoOperationMessage.unwrap();
        write!(SERVER, self.base.token, buf);

        Ok(())
    }

    pub fn handle_friend_set_warn_on_level_gain<'a>(&mut self, _: Ref<'a>,
                                                    msg: FriendSetWarnOnLevelGainMessage)
                                                    -> Result<()> {
        match self.state {
            GameState::InContext(_) => (),
            _ => return Ok(()),
        };

        let account = self.account.as_mut().unwrap();
        account.social.warn_on_level_gain = msg.enable;

        let buf = BasicNoOperationMessage.unwrap();
        write!(SERVER, self.base.token, buf);

        Ok(())
    }

    pub fn handle_ignored_get_list<'a>(&mut self, _: Ref<'a>, _: IgnoredGetListMessage)
                                       -> Result<()> {
        match self.state {
            GameState::InContext(_) => (),
            _ => return Ok(()),
        };

        let buf = IgnoredListMessage {
            ignored_list: self.ignored_cache.values().filter_map(|i| {
                match *i {
                    IgnoredInformationsVariant::SessionIgnoredInformations(_) => None,
                    _ => Some(i.clone()),
                }
            }).collect(),
        }.unwrap();

        write!(SERVER, self.base.token, buf);

        Ok(())
    }

    pub fn handle_friend_add_request<'a>(&mut self, _: Ref<'a>, msg: FriendAddRequestMessage)
                                         -> Result<()> {
         match self.state {
             GameState::InContext(_) => (),
             _ => return Ok(()),
         };

         let account = self.account.as_ref().unwrap();

         let friends_count = account.social.friends.len();
         if (account.is_subscriber() && friends_count >= 100)
             || (!account.is_subscriber() && friends_count >= 50) {
             let buf = FriendAddFailureMessage {
                 reason: 1,
             }.unwrap();
             write!(SERVER, self.base.token, buf);
             return Ok(());
         }

         let name = msg.name;
         SERVER.with(|s| {
             social::add_relation(
                 &s.server,
                 self.base.token,
                 account.id,
                 name,
                 SocialState::Friend,
                |session, infos| session.friend_added_success(infos)
            );
        });
         Ok(())
    }

    pub fn handle_friend_delete_request<'a>(&mut self, _: Ref<'a>,
                                            msg: FriendDeleteRequestMessage) -> Result<()> {
        match self.state {
            GameState::InContext(_) => (),
            _ => return Ok(()),
        };

        // do not call account.social.is_friend_with because we can only delete friends
        // which are on the server
        if !self.friends_cache.contains_key(&msg.account_id) {
            let buf = FriendDeleteResultMessage {
                success: false,
                name: String::new()
            }.unwrap();
            write!(SERVER, self.base.token, buf);
            return Ok(());
        }

        let account_id = {
            let account = self.account.as_mut().unwrap();
            let _ = account.social.friends.remove(&msg.account_id);
            account.id
        };

        let infos = self.friends_cache.remove(&msg.account_id).unwrap();
        let buf = FriendDeleteResultMessage {
            success: true,
            name: infos.name().to_string(),
        }.unwrap();
        write!(SERVER, self.base.token, buf);

        SERVER.with(|s| {
            social::delete_relation(
                &s.server,
                self.base.token,
                account_id,
                msg.account_id,
                SocialState::Friend,
            );
        });
        Ok(())
    }

    pub fn handle_ignored_add_request<'a>(&mut self, _: Ref<'a>, msg: IgnoredAddRequestMessage)
                                         -> Result<()> {
         match self.state {
             GameState::InContext(_) => (),
             _ => return Ok(()),
         };

         let account = self.account.as_ref().unwrap();

         let ignored_count = account.social.ignored.len();
         if (account.is_subscriber() && ignored_count >= 100)
             || (!account.is_subscriber() && ignored_count >= 50) {
             let buf = IgnoredAddFailureMessage {
                 reason: 1,
             }.unwrap();
             write!(SERVER, self.base.token, buf);
             return Ok(());
         }

         let name = msg.name;
         let for_session = msg.session;
         SERVER.with(|s| {
             social::add_relation(
                 &s.server,
                 self.base.token,
                 account.id,
                 name,
                 SocialState::Ignored,
                 move |session, infos| {
                     session.ignored_added_success(infos, for_session)
                 }
             );
        });
         Ok(())
    }

    pub fn handle_ignored_delete_request<'a>(&mut self, _: Ref<'a>,
                                             msg: IgnoredDeleteRequestMessage) -> Result<()> {
        match self.state {
            GameState::InContext(_) => (),
            _ => return Ok(()),
        };

        // same as in handle_friend_delete_request
        if !self.ignored_cache.contains_key(&msg.account_id) {
            let buf = IgnoredDeleteResultMessage {
                success: Flag(false),
                session: Flag(msg.session),
                name: String::new()
            }.unwrap();
            write!(SERVER, self.base.token, buf);
            return Ok(());
        }

        if !msg.session {
            let account = self.account.as_mut().unwrap();
            let _ = account.social.ignored.remove(&msg.account_id);
        }

        let infos = self.ignored_cache.remove(&msg.account_id).unwrap();
        let buf = IgnoredDeleteResultMessage {
            success: Flag(true),
            session: Flag(msg.session),
            name: infos.name().to_string(),
        }.unwrap();
        write!(SERVER, self.base.token, buf);

        SERVER.with(|s| {
            social::delete_relation(
                &s.server,
                self.base.token,
                self.account.as_ref().unwrap().id,
                msg.account_id,
                SocialState::Ignored,
            );
        });
        Ok(())
    }
}

use crate::{Error, PrefixContext};

const LLVM_MCA_TOOL_ID: &str = "llvm-mcatrunk";

enum Compilation {
    Success {
        asm: String,
        stderr: String,
        llvm_mca: Option<String>,
    },
    Error {
        stderr: String,
    },
}

#[derive(Debug, serde::Deserialize)]
struct GodboltOutputSegment {
    text: String,
}

#[derive(Debug, serde::Deserialize)]
struct GodboltOutput(Vec<GodboltOutputSegment>);

impl GodboltOutput {
    pub fn full_with_ansi_codes_stripped(&self) -> Result<String, Error> {
        let mut complete_text = String::new();
        for segment in self.0.iter() {
            complete_text.push_str(&segment.text);
            complete_text.push('\n');
        }
        Ok(String::from_utf8(strip_ansi_escapes::strip(
            complete_text.trim(),
        )?)?)
    }
}

#[derive(Debug, serde::Deserialize)]
struct GodboltResponse {
    code: u8,
    stdout: GodboltOutput,
    stderr: GodboltOutput,
    asm: GodboltOutput,
    tools: Vec<GodboltTool>,
}

#[derive(Debug, serde::Deserialize)]
struct GodboltTool {
    id: String,
    code: u8,
    stdout: GodboltOutput,
    stderr: GodboltOutput,
}

// Transforms human readable rustc version (e.g. "1.34.1") into compiler id on godbolt (e.g. "r1341")
// Full list of version<->id can be obtained at https://godbolt.org/api/compilers/rust
// Ideally we'd also check that the version exists, and give a nice error message if not, but eh.
fn translate_rustc_version(version: &str) -> Result<std::borrow::Cow<'_, str>, Error> {
    if ["nightly", "beta"].contains(&version) {
        return Ok(version.into());
    }
    // very crude sanity checking
    if !version.chars().all(|c| c.is_digit(10) || c == '.') {
        return Err(
            "the `rustc` argument should be a version specifier. E.g. `nightly` `beta` or `1.45.2`"
                .into(),
        );
    }
    Ok(format!("r{}", version.replace(".", "")).into())
}

/// Compile a given Rust source code file on Godbolt using the latest nightly compiler with
/// full optimizations (-O3)
/// Returns a multiline string with the pretty printed assembly
async fn compile_rust_source(
    http: &reqwest::Client,
    source_code: &str,
    rustc: &str,
    flags: &str,
    run_llvm_mca: bool,
) -> Result<Compilation, Error> {
    let rustc = translate_rustc_version(rustc)?;

    let tools = if run_llvm_mca {
        serde_json::json! {
            [{"id": LLVM_MCA_TOOL_ID}]
        }
    } else {
        serde_json::json! {
            []
        }
    };

    let request = http
        .post(&format!(
            "https://godbolt.org/api/compiler/{}/compile",
            rustc
        ))
        .header(reqwest::header::ACCEPT, "application/json") // to make godbolt respond in JSON
        .json(&serde_json::json! { {
            "source": source_code,
            "options": {
                "userArguments": flags,
                "tools": tools,
            },
        } })
        .build()?;

    let response: GodboltResponse = http.execute(request).await?.json().await?;

    // TODO: use the extract_relevant_lines utility to strip stderr nicely
    Ok(if response.code == 0 {
        Compilation::Success {
            asm: response.asm.full_with_ansi_codes_stripped()?,
            stderr: response.stderr.full_with_ansi_codes_stripped()?,
            llvm_mca: match response
                .tools
                .iter()
                .find(|tool| tool.id == LLVM_MCA_TOOL_ID)
            {
                Some(llvm_mca) => Some(llvm_mca.stdout.full_with_ansi_codes_stripped()?),
                None => None,
            },
        }
    } else {
        Compilation::Error {
            stderr: response.stderr.full_with_ansi_codes_stripped()?,
        }
    })
}

async fn save_to_shortlink(
    http: &reqwest::Client,
    code: &str,
    rustc: &str,
    flags: &str,
    run_llvm_mca: bool,
) -> Result<String, Error> {
    #[derive(serde::Deserialize)]
    struct GodboltShortenerResponse {
        url: String,
    }

    let tools = if run_llvm_mca {
        serde_json::json! {
            [{"id": LLVM_MCA_TOOL_ID}]
        }
    } else {
        serde_json::json! {
            []
        }
    };

    let response = http
        .post("https://godbolt.org/api/shortener")
        .json(&serde_json::json! { {
            "sessions": [{
                "language": "rust",
                "source": code,
                "compilers": [{
                    "id": rustc,
                    "options": flags,
                    "tools": tools,
                }],
            }]
        } })
        .send()
        .await?;

    Ok(response.json::<GodboltShortenerResponse>().await?.url)
}

#[derive(PartialEq, Clone, Copy)]
enum GodboltMode {
    Asm,
    LlvmIr,
    Mca,
}

fn rustc_version_and_flags(params: &poise::KeyValueArgs, mode: GodboltMode) -> (&str, String) {
    let rustc = params.get("rustc").unwrap_or(&"nightly");
    let mut flags = params
        .get("flags")
        .unwrap_or("-Copt-level=3 --edition=2018")
        .to_owned();

    if mode == GodboltMode::LlvmIr {
        flags += " --emit=llvm-ir -Cdebuginfo=0";
    }

    (rustc, flags)
}

async fn generic_godbolt(
    ctx: PrefixContext<'_>,
    params: poise::KeyValueArgs,
    code: poise::CodeBlock,
    mode: GodboltMode,
) -> Result<(), Error> {
    let run_llvm_mca = mode == GodboltMode::Mca;

    let (rustc, flags) = rustc_version_and_flags(&params, mode);

    let (lang, text, note);
    let godbolt_result =
        compile_rust_source(&ctx.data.http, &code.code, rustc, &flags, run_llvm_mca).await?;
    match godbolt_result {
        Compilation::Success {
            asm,
            stderr,
            llvm_mca,
        } => {
            lang = match mode {
                GodboltMode::Asm => "x86asm",
                GodboltMode::Mca => "rust",
                GodboltMode::LlvmIr => "llvm",
            };
            text = match mode {
                GodboltMode::Mca => {
                    let llvm_mca = llvm_mca.ok_or("No llvm-mca result was sent by Godbolt")?;
                    strip_llvm_mca_result(&llvm_mca).to_owned()
                }
                GodboltMode::Asm | GodboltMode::LlvmIr => asm,
            };
            note = if stderr.is_empty() {
                ""
            } else {
                "Note: compilation produced warnings\n"
            };
        }
        Compilation::Error { stderr } => {
            lang = "rust";
            text = stderr;
            note = "";
        }
    };

    if text.trim().is_empty() {
        poise::say_prefix_reply(ctx, format!("``` ```{}", note)).await?;
    } else {
        super::reply_potentially_long_text(
            ctx,
            &format!("```{}\n{}", lang, text),
            &format!("\n```{}", note),
            &format!(
                "Output too large. Godbolt link: <{}>",
                save_to_shortlink(&ctx.data.http, &code.code, rustc, &flags, run_llvm_mca).await?,
            ),
        )
        .await?;
    }

    Ok(())
}

/// View assembly using Godbolt
///
/// Compile Rust code using <https://rust.godbolt.org>. Full optimizations are applied unless \
/// overriden.
