        manager.state.tags.add_new("B24", Layout::default());
        manager.state.tags.add_new("C", Layout::default());
        manager.state.tags.add_new("6D4", Layout::default());
        manager.state.tags.add_new("E39", Layout::default());
        manager.state.tags.add_new("F67", Layout::default());
        assert!(!manager.command_handler(&Command::GoToTag {
            tag: 0,
            swap: false
        }));
        assert!(!manager.command_handler(&Command::GoToTag {
            tag: 999,
            swap: false
        }));
    }

    #[test]
    fn go_to_tag_should_go_to_tag_and_set_history() {
        let mut manager = Manager::new_test(vec![
            "A15".to_string(),
            "B24".to_string(),
            "C".to_string(),
            "6D4".to_string(),
            "E39".to_string(),
            "F67".to_string(),
        ]);
        manager.screen_create_handler(Screen::default());
        manager.screen_create_handler(Screen::default());

        assert!(manager.command_handler(&Command::GoToTag {
            tag: 6,
            swap: false
        }));
        let current_tag = manager.state.focus_manager.tag(0).unwrap();
        assert_eq!(current_tag, 6);

        assert!(manager.command_handler(&Command::GoToTag {
            tag: 2,
            swap: false
        }));
        let current_tag = manager.state.focus_manager.tag(0).unwrap_or_default();
        assert_eq!(current_tag, 2);

        assert!(manager.command_handler(&Command::GoToTag {
            tag: 3,
            swap: false
        }));
        let current_tag = manager.state.focus_manager.tag(0).unwrap_or_default();
        assert_eq!(current_tag, 3);

        assert!(manager.command_handler(&Command::GoToTag {
            tag: 4,
            swap: false
        }));
        let current_tag = manager.state.focus_manager.tag(0).unwrap_or_default();
        assert_eq!(current_tag, 4);

        // test tag history
        assert_eq!(manager.state.focus_manager.tag(1).unwrap_or_default(), 3);
        assert_eq!(manager.state.focus_manager.tag(2).unwrap_or_default(), 2);
        assert_eq!(manager.state.focus_manager.tag(3).unwrap_or_default(), 6);
    }

    #[test]
    fn focus_tag_change_should_go_to_previous_and_next_tag() {
        let mut manager = Manager::new_test(vec![
            "A15".to_string(),
            "B24".to_string(),
            "C".to_string(),
            "6D4".to_string(),
            "E39".to_string(),
            "F67".to_string(),
        ]);
        manager.screen_create_handler(Screen::default());
        let state = &mut manager.state;

        state.focus_tag(&2);
        assert_eq!(state.focus_manager.tag(0).unwrap(), 2);

        focus_tag_change(state, 1);
        assert_eq!(state.focus_manager.tag(0).unwrap(), 3);

        focus_tag_change(state, -1);
        assert_eq!(state.focus_manager.tag(0).unwrap(), 2);

        focus_tag_change(state, 2);
        assert_eq!(state.focus_manager.tag(0).unwrap(), 4);

        focus_tag_change(state, -5);
        assert_eq!(state.focus_manager.tag(0).unwrap(), 5);

        focus_tag_change(state, 3);
        assert_eq!(state.focus_manager.tag(0).unwrap(), 2);

        focus_tag_change(state, 13);
        assert_eq!(state.focus_manager.tag(0).unwrap(), 3);
    }

    #[test]
    fn focus_window_top() {
        let mut manager = Manager::new_test(vec![]);
        manager.screen_create_handler(Screen::default());

        manager.window_created_handler(
            Window::new(WindowHandle::MockHandle(1), None, None),
            -1,
            -1,
        );
        manager.window_created_handler(
            Window::new(WindowHandle::MockHandle(2), None, None),
            -1,
            -1,
        );
        manager.window_created_handler(
            Window::new(WindowHandle::MockHandle(3), None, None),
            -1,
            -1,
        );

        let expected = manager.state.windows[0].clone();
        let initial = manager.state.windows[1].clone();

        manager.state.focus_window(&initial.handle);

        manager.command_handler(&Command::FocusWindowTop { swap: false });
        let actual = manager
            .state
            .focus_manager
            .window(&manager.state.windows)
            .unwrap()
            .handle;
        assert_eq!(expected.handle, actual);

        manager.command_handler(&Command::FocusWindowTop { swap: false });
        let actual = manager
            .state
            .focus_manager
            .window(&manager.state.windows)
            .unwrap()
            .handle;
        assert_eq!(expected.handle, actual);

        manager.command_handler(&Command::FocusWindowTop { swap: true });
        let actual = manager
            .state
            .focus_manager
            .window(&manager.state.windows)
            .unwrap()
            .handle;
        assert_eq!(initial.handle, actual);
    }

    #[test]
    fn move_window_top() {
        let mut manager = Manager::new_test(vec![]);
        manager.screen_create_handler(Screen::default());

        manager.window_created_handler(
            Window::new(WindowHandle::MockHandle(1), None, None),
            -1,
            -1,
        );
        manager.window_created_handler(
            Window::new(WindowHandle::MockHandle(2), None, None),
            -1,
            -1,
        );
        manager.window_created_handler(
            Window::new(WindowHandle::MockHandle(3), None, None),
            -1,
            -1,
        );

        let expected = manager.state.windows[0].clone();
        let initial = manager.state.windows[1].clone();

        manager.state.focus_window(&initial.handle);

        manager.command_handler(&Command::MoveWindowTop { swap: false });
        assert_eq!(manager.state.windows[0].handle, initial.handle);

        manager.command_handler(&Command::MoveWindowTop { swap: false });
        assert_eq!(manager.state.windows[0].handle, initial.handle);

        manager.command_handler(&Command::MoveWindowTop { swap: true });
        assert_eq!(manager.state.windows[0].handle, expected.handle);
    }
}

use sway_types::Span;

use crate::{
    error::{err, ok},
    CompileError, CompileResult,
};

use super::patstack::PatStack;

/// A `Matrix` is a `Vec<PatStack>` that is implemented with special methods
/// particular to the match exhaustivity algorithm.
///
/// The number of rows of the `Matrix` is equal to the number of `PatStack`s and
/// the number of columns of the `Matrix` is equal to the number of elements in
/// the `PatStack`s. Each `PatStack` should contains the same number of
/// elements.
#[derive(Clone, Debug)]
pub(crate) struct Matrix {
    rows: Vec<PatStack>,
}

impl Matrix {
    /// Creates an empty `Matrix`.
    pub(crate) fn empty() -> Self {
        Matrix { rows: vec![] }
    }

    /// Creates a `Matrix` with one row from a `PatStack`.
    pub(crate) fn from_pat_stack(pat_stack: PatStack) -> Self {
        Matrix {
            rows: vec![pat_stack],
        }
    }

    /// Pushes a `PatStack` onto the `Matrix`.
    pub(crate) fn push(&mut self, row: PatStack) {
        self.rows.push(row);
    }

    /// Appends a `Vec<PatStack>` onto the `Matrix`.
    pub(crate) fn append(&mut self, rows: &mut Vec<PatStack>) {
        self.rows.append(rows);
    }

    /// Returns a reference to the rows of the `Matrix`.
    pub(crate) fn rows(&self) -> &Vec<PatStack> {
        &self.rows
    }

    /// Returns the rows of the `Matrix`.
    pub(crate) fn into_rows(self) -> Vec<PatStack> {
        self.rows
    }

    /// Returns the number of rows *m* and the number of columns *n* of the
    /// `Matrix` in the form (*m*, *n*).
    pub(crate) fn m_n(&self, span: &Span) -> CompileResult<(usize, usize)> {
        let warnings = vec![];
        let mut errors = vec![];
        let first = match self.rows.first() {
            Some(first) => first,
            None => return ok((0, 0), warnings, errors),
        };
        let n = first.len();
        for row in self.rows.iter().skip(1) {
            if row.len() != n {
                errors.push(CompileError::Internal(
                    "found invalid matrix size",
                    span.clone(),
                ));
                return err(warnings, errors);
            }
        }
        ok((self.rows.len(), n), warnings, errors)
    }

    /// Reports if the `Matrix` is equivalent to a vector (aka a single
    /// `PatStack`).
    pub(crate) fn is_a_vector(&self) -> bool {
        self.rows.len() == 1
    }

    /// Checks to see if the `Matrix` is a vector, and if it is, returns the
    /// single `PatStack` from its elements.
    pub(crate) fn unwrap_vector(&self, span: &Span) -> CompileResult<PatStack> {
        let warnings = vec![];
        let mut errors = vec![];
        if !self.is_a_vector() {
            errors.push(CompileError::Internal(
                "found invalid matrix size",
                span.clone(),
            ));
            return err(warnings, errors);
        }
        match self.rows.first() {
            Some(first) => ok(first.clone(), warnings, errors),
            None => {
                errors.push(CompileError::Internal(
                    "found invalid matrix size",
                    span.clone(),
                ));
                err(warnings, errors)
            }
        }
    }

    /// Computes Σ, where Σ is a `PatStack` containing the first element of
    /// every row of the `Matrix`.
    pub(crate) fn compute_sigma(&self, span: &Span) -> CompileResult<PatStack> {
        let mut warnings = vec![];
        let mut errors = vec![];
        let mut pat_stack = PatStack::empty();
        for row in self.rows.iter() {
            let first = check!(
                row.first(span),
                return err(warnings, errors),
                warnings,
                errors
            );
            pat_stack.push(first)
        }
        ok(pat_stack.flatten().filter_out_wildcards(), warnings, errors)
    }
}

use std::io::{stdin, Read};

fn process_row_part_1(row: &Vec<u32>) -> u32 {
    let mut min: u32 = row[0];
    let mut max: u32 = row[0];

    for x in 1..row.len() {
        if row[x] < min {
            min = row[x];
        }
        if row[x] > max {
            max = row[x];
        }
    }

    max - min
}

fn process_row_part_2(row: &Vec<u32>) -> u32 {
    let mut result = 0;

    for x in row {
        let row_clone = row.to_owned();
        for y in row_clone {
            if *x == y {
                continue;
            }
            if *x % y == 0 {
                result = *x / y;
                break;
            }
        }
    }

    result
}

fn process_rows<F>(rows: &[Vec<u32>], f: F) -> u32
where
    F: Fn(&Vec<u32>) -> u32,
{
    let mut sum: u32 = 0;

    for row in rows {
        sum += f(row);
    }

    sum
}

fn parse_line(line: &str) -> Vec<u32> {
    let digits: Vec<u32> = line.split_whitespace()
        .map(|s| s.parse().unwrap())
        .collect();

    digits
}

fn main() {
    let mut input = String::new();

    stdin().read_to_string(&mut input).unwrap();
    //    println!("input = {:#?}", input);

    let rows: Vec<Vec<u32>> = input.lines().map(|line| parse_line(line)).collect();
    //    println!("rows = {:?}", rows);

    let result = process_rows(&rows, process_row_part_1);
    println!("result, part 1 = {}", result);

    let result = process_rows(&rows, process_row_part_2);
    println!("result, part 2 = {}", result);
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn part_1_process_row_provided_tests() {
        assert_eq!(8, process_row_part_1(&vec![5, 1, 9, 5]));
        assert_eq!(4, process_row_part_1(&vec![7, 5, 3]));
        assert_eq!(6, process_row_part_1(&vec![2, 4, 6, 8]));
    }

    #[test]
    fn part_2_process_row_provided_tests() {
        assert_eq!(4, process_row_part_2(&vec![5, 9, 2, 8]));
        assert_eq!(3, process_row_part_2(&vec![9, 4, 7, 3]));
        assert_eq!(2, process_row_part_2(&vec![3, 8, 6, 5]));
    }
}

