fn type_to_u8<S>(x: &Type, s: &mut S) -> Result<(), S::Error>
    where S: Serializer
{
    let ret = match *x {
        Type::Zero => None,
        _ => Some(x.clone() as u8),
    };

    Serialize::serialize(&ret, s)
}

