use crate::material::{
    ColoredMaterial, ColoredMaterialDeviceLayout, Material, MaterialDeviceLayout,
};
use ash::vk;
use glam::Vec4;

use std::mem::size_of;
use std::ops::Range;
use vk_mem as vma;

pub struct TextureRepo {
    pub materials: Vec<Material>,
    pub colored_materials: Vec<ColoredMaterial>,
}

pub struct TextureRepoUploadState {
    pub image: vk::Image,
    pub image_view: vk::ImageView,
    pub image_allocation: vma::Allocation,
    pub image_allocation_info: vma::AllocationInfo,
    pub staging_buffer: vk::Buffer,
    pub staging_buffer_allocation: vma::Allocation,
    pub staging_buffer_allocation_info: vma::AllocationInfo,
    pub sampler: vk::Sampler,
    pub image_len: u32,

    pub buffer: vk::Buffer,
    pub buffer_allocation: vma::Allocation,
    pub buffer_allocation_info: vma::AllocationInfo,
    pub regular_material_range: Range<u32>,
    pub colored_material_range: Range<u32>,
}
impl TextureRepo {
    pub fn new() -> Self {
        TextureRepo {
            materials: Vec::new(),
            colored_materials: Vec::new(),
        }
    }
    pub fn upload(
        self,
        device: &ash::Device,
        allocator: &vma::Allocator,
        command_buffer: vk::CommandBuffer,
        graphics_queue_family: u32,
    ) -> TextureRepoUploadState {
        let (image, image_allocation, image_allocation_info) = allocator
            .create_image(
                &vk::ImageCreateInfo::builder()
                    .flags(vk::ImageCreateFlags::empty())
                    .image_type(vk::ImageType::TYPE_2D)
                    .format(vk::Format::R8G8B8A8_UNORM)
                    .extent(vk::Extent3D {
                        width: 16,
                        height: 16,
                        depth: 1,
                    })
                    .mip_levels(1)
                    .array_layers((self.materials.len() + self.colored_materials.len()) as u32)
                    .samples(vk::SampleCountFlags::TYPE_1)
                    .tiling(vk::ImageTiling::OPTIMAL)
                    .usage(vk::ImageUsageFlags::TRANSFER_DST | vk::ImageUsageFlags::SAMPLED)
                    .sharing_mode(vk::SharingMode::EXCLUSIVE)
                    .initial_layout(vk::ImageLayout::UNDEFINED)
                    .build(),
                &vma::AllocationCreateInfo {
                    usage: vma::MemoryUsage::GpuOnly,
                    flags: vma::AllocationCreateFlags::DEDICATED_MEMORY,
                    ..Default::default()
                },
            )
            .unwrap();
        let (staging_buffer, staging_buffer_allocation, staging_buffer_allocation_info) = allocator
            .create_buffer(
                &vk::BufferCreateInfo::builder()
                    .size(image_allocation_info.get_size() as u64)
                    .usage(vk::BufferUsageFlags::TRANSFER_SRC)
                    .build(),
                &vma::AllocationCreateInfo {
                    usage: vma::MemoryUsage::CpuOnly,
                    flags: vma::AllocationCreateFlags::MAPPED,
                    ..Default::default()
                },
            )
            .unwrap();
        let staging_ptr = staging_buffer_allocation_info.get_mapped_data();

        let indices = {
            // Copy data into the buffer
            let mut current_offset: usize = 0;
            let mut indices: Vec<usize> =
                Vec::with_capacity(self.materials.len() + self.colored_materials.len());
            for material in self.materials.iter() {
                let rgba8img = material.diffuse.as_rgba8().unwrap();
                unsafe {
                    std::ptr::copy_nonoverlapping(
                        rgba8img.as_ptr(),
                        staging_ptr.add(current_offset),
                        rgba8img.len(),
                    );
                }
                indices.push(current_offset);
                current_offset += rgba8img.len();
            }
            for material in self.colored_materials.iter() {
                let rgba8img = material.diffuse.as_rgba8().unwrap();
                unsafe {
                    std::ptr::copy_nonoverlapping(
                        rgba8img.as_ptr(),
                        staging_ptr.add(current_offset),
                        rgba8img.len(),
                    );
                }
                indices.push(current_offset);
                current_offset += rgba8img.len();
            }
            indices
        };

        let buffer_copies: Vec<_> = indices
            .iter()
            .enumerate()
            .map(|(i, &indice)| {
                vk::BufferImageCopy {
                    buffer_offset: indice as u64,
                    // If either of these values is zero, that aspect of the buffer memory is
                    // considered to be tightly packed according to the imageExtent.
                    buffer_row_length: 0,
                    buffer_image_height: 0,
                    image_subresource: vk::ImageSubresourceLayers {
                        aspect_mask: vk::ImageAspectFlags::COLOR,
                        mip_level: 0,
                        base_array_layer: i as u32,
                        layer_count: 1, // TODO: copy everyting in one BufferImageCopy?
                    },
                    image_offset: vk::Offset3D { x: 0, y: 0, z: 0 },
                    image_extent: vk::Extent3D {
                        width: 16,
                        height: 16,
                        depth: 1,
                    },
                }
            })
            .collect();
        unsafe {
            let image_memory_barrier = vk::ImageMemoryBarrier::builder()
                .old_layout(vk::ImageLayout::UNDEFINED)
                .new_layout(vk::ImageLayout::TRANSFER_DST_OPTIMAL)
                .image(image)
                .src_access_mask(vk::AccessFlags::empty())
                .dst_access_mask(vk::AccessFlags::TRANSFER_WRITE)
                .src_queue_family_index(graphics_queue_family)
                .dst_queue_family_index(graphics_queue_family)
                .subresource_range(vk::ImageSubresourceRange {
                    aspect_mask: vk::ImageAspectFlags::COLOR,
                    base_mip_level: 0,
                    level_count: 1,
                    base_array_layer: 0,
                    layer_count: (self.materials.len() + self.colored_materials.len()) as u32,
                })
                .build();
            device.cmd_pipeline_barrier(
                command_buffer,
                vk::PipelineStageFlags::TOP_OF_PIPE,
                vk::PipelineStageFlags::TRANSFER,
                vk::DependencyFlags::empty(),
                &[],
                &[],
                &[image_memory_barrier],
            );
            let mut image_memory_barrier2 = image_memory_barrier.clone();
            image_memory_barrier2.src_access_mask = vk::AccessFlags::TRANSFER_WRITE;
            image_memory_barrier2.dst_access_mask = vk::AccessFlags::SHADER_READ;
            image_memory_barrier2.new_layout = vk::ImageLayout::SHADER_READ_ONLY_OPTIMAL;
            image_memory_barrier2.old_layout = vk::ImageLayout::TRANSFER_DST_OPTIMAL;

            device.cmd_copy_buffer_to_image(
                command_buffer,
                staging_buffer,
                image,
                vk::ImageLayout::TRANSFER_DST_OPTIMAL,
                &buffer_copies,
            );
            device.cmd_pipeline_barrier(
                command_buffer,
                vk::PipelineStageFlags::TRANSFER,
                vk::PipelineStageFlags::FRAGMENT_SHADER,
                vk::DependencyFlags::empty(),
                &[],
                &[],
                &[image_memory_barrier2],
            );
        }
        let sampler = unsafe {
            device
                .create_sampler(
                    &vk::SamplerCreateInfo::builder()
                        .mag_filter(vk::Filter::NEAREST)
                        .min_filter(vk::Filter::NEAREST)
                        .mipmap_mode(vk::SamplerMipmapMode::NEAREST)
                        .address_mode_u(vk::SamplerAddressMode::REPEAT)
                        .address_mode_v(vk::SamplerAddressMode::REPEAT)
                        .address_mode_w(vk::SamplerAddressMode::REPEAT)
                        .build(),
                    None,
                )
                .unwrap()
        };
        let image_view = unsafe {
            device
                .create_image_view(
                    &vk::ImageViewCreateInfo::builder()
                        .image(image)
                        .view_type(vk::ImageViewType::TYPE_2D_ARRAY)
                        .format(vk::Format::R8G8B8A8_UNORM)
                        .components(vk::ComponentMapping {
                            r: vk::ComponentSwizzle::R,
                            g: vk::ComponentSwizzle::G,
                            b: vk::ComponentSwizzle::B,
                            a: vk::ComponentSwizzle::A,
                        })
                        .subresource_range(vk::ImageSubresourceRange {
                            aspect_mask: vk::ImageAspectFlags::COLOR,
                            base_mip_level: 0,
                            level_count: 1,
                            base_array_layer: 0,
                            layer_count: (self.materials.len() + self.colored_materials.len())
                                as u32,
                        })
                        .build(),
                    None,
                )
                .unwrap()
        };

        let (buffer, buffer_allocation, buffer_allocation_info) = allocator
            .create_buffer(
                &vk::BufferCreateInfo::builder()
                    .flags(vk::BufferCreateFlags::empty())
                    .size(
                        (self.materials.len() * size_of::<MaterialDeviceLayout>()
                            + self.colored_materials.len()
                                * size_of::<ColoredMaterialDeviceLayout>())
                            as u64,
                    )
                    .sharing_mode(vk::SharingMode::EXCLUSIVE)
                    .usage(vk::BufferUsageFlags::STORAGE_BUFFER)
                    .build(),
                &vma::AllocationCreateInfo {
                    usage: vma::MemoryUsage::CpuToGpu,
                    flags: vma::AllocationCreateFlags::MAPPED,
                    required_flags: Default::default(),
                    preferred_flags: Default::default(),
                    memory_type_bits: 0,
                    pool: None,
                    user_data: None,
                },
            )
            .unwrap();
        let mut buffer_ptr = buffer_allocation_info.get_mapped_data() as *mut MaterialDeviceLayout;
        unsafe {
            for (i, material) in self.materials.iter().enumerate() {
                let material_ref = &mut *buffer_ptr;
                material_ref.scale = material.scale;
                material_ref.diffuse = i as u16;
                buffer_ptr = buffer_ptr.add(1);
            }
            let mut buffer_ptr = buffer_ptr as *mut ColoredMaterialDeviceLayout;
            for (i, material) in self.colored_materials.iter().enumerate() {
                let material_ref = &mut *buffer_ptr;
                material_ref.diffuse = (i + self.materials.len()) as u16;
                material_ref.scale = material.scale;
                material_ref.palette = material
                    .color_palette
                    .map(|vec| Vec4::new(vec.x, vec.y, vec.z, 1.0));
                buffer_ptr = buffer_ptr.add(1);
            }
        }

        let barrier = (self.materials.len() * size_of::<MaterialDeviceLayout>()) as u32;
        TextureRepoUploadState {
            image,
            image_allocation,
            image_allocation_info,
            staging_buffer,
            staging_buffer_allocation,
            staging_buffer_allocation_info,
            sampler,
            image_view,
            image_len: (self.materials.len() + self.colored_materials.len()) as u32,
            buffer,
            buffer_allocation,
            buffer_allocation_info,
            regular_material_range: 0..barrier,
            colored_material_range: barrier
                ..(barrier
                    + (self.colored_materials.len() * size_of::<ColoredMaterialDeviceLayout>())
                        as u32),
        }
    }
}

use regex::Regex;
use std::collections::VecDeque;
use itertools::Itertools;
use crate::helpers::Grid;

#[derive(Debug, Eq, PartialEq, Ord, PartialOrd)]
pub struct Point2D {
    x: usize,
    y: usize
}

#[derive(Debug, Eq, PartialEq)]
enum Fold {
  Horizontal { y: usize},
  Vertical { x: usize }
}

#[derive(Debug, Eq, PartialEq)]
pub struct Origami {
    points: Vec<Point2D>,
    folds: VecDeque<Fold>
}

impl Origami {
    pub fn step(&mut self) {
      let f = self.folds.pop_front().unwrap();
      let mut new_points: Vec<Point2D> = self.points.iter().map(|p| 
        match f {
            Fold::Horizontal { y } => Point2D { x: p.x, y: if p.y > y { p.y - 2*(p.y - y) } else { p.y }},
            Fold::Vertical   { x } => Point2D { x: if p.x > x { p.x - 2*(p.x - x) } else { p.x }, y: p.y},               
        }
      ).collect();
      new_points.sort();
      new_points.dedup();
      self.points = new_points;
    }

    pub fn run(&mut self) {
        loop {
            if self.folds.is_empty() { return };
            self.step();
        }
    }

    pub fn print(&self) {
      let num_cols = self.points.iter().map(|p| p.x).max().unwrap();
      let num_rows = self.points.iter().map(|p| p.y).max().unwrap();
      let mut grid = Grid::new(num_rows + 1, num_cols + 1, '.');
      for p in self.points.iter() {
          grid.set_cell(p.y, p.x, '#');
      }
      println!("grid: \n");
      grid.print();
    }
}

pub fn parse_origami(input: &Vec<String>) -> Origami {
    let mut points = vec![];
    let mut folds = VecDeque::new();
    let re_point = Regex::new(r"^(\d+),(\d+)$").unwrap();
    let re_fold = Regex::new(r"^fold along (x|y)=(\d+)$").unwrap();
    for line in input {
      if let Some(mdp) = re_point.captures(&line) {
        let x: usize = mdp[1].parse().unwrap();
        let y: usize = mdp[2].parse().unwrap();
        points.push(Point2D { x: x, y: y });
      }
      else if let Some(mdf) = re_fold.captures(&line) {
        let val: usize = mdf[2].parse().unwrap();
        let fold = match &mdf[1] {
            "x" => Fold::Vertical { x: val },
            _ => Fold::Horizontal { y: val }
        };
        folds.push_back(fold);
      }
    }
    return Origami { points: points, folds: folds };
}

pub fn solve() {
    //let filename = "a13_transparent_origami/example_input.txt";
    let filename = "a13_transparent_origami/input.txt";
    let v = crate::helpers::read_string_list((&filename).to_string());   
    let mut origami = parse_origami(&v);
    origami.step();
    let result1 = origami.points.len();
    origami.run();
    origami.print();
    let result2 = "AHPRPAUZ";
    println!("13 - transparent origami: {} {}", result1, result2);
}

//! Code generation for rocket-sync-db-pools.

#![recursion_limit="256"]
#![warn(rust_2018_idioms)]

#[macro_use]
extern crate quote;

mod database;

use devise::{syn, proc_macro2};
use proc_macro::TokenStream;

/// Generates a request guard and fairing for retrieving a database connection.
///
/// The syntax for the `databases` macro is:
///
/// <pre>
/// macro := 'database' '( DATABASE_NAME ')'
///
/// DATABASE_NAME := string literal
/// </pre>
///
/// The attribute accepts a single string parameter that indicates the name of
/// the database. This corresponds to the database name set as the database's
/// configuration key:
///
/// The macro generates a [`FromRequest`] implementation for the decorated type,
/// allowing the type to be used as a request guard. This implementation
/// retrieves a connection from the database pool or fails with a
/// `Status::ServiceUnavailable` if connecting to the database times out.
///
/// The macro also generates three inherent methods on the decorated type:
///
///   * `fn fairing() -> impl Fairing`
///
///      Returns a fairing that initializes the associated database connection
///      pool.
///
///   * `async fn get_one<P: Phase>(&Rocket<P>) -> Option<Self>`
///
///     Retrieves a connection wrapper from the configured pool. Returns `Some`
///     as long as `Self::fairing()` has been attached.
///
///   * `async fn run<R: Send + 'static>(&self, impl FnOnce(&mut Db) -> R + Send + 'static) -> R`
///
///     Runs the specified function or closure, providing it access to the
///     underlying database connection (`&mut Db`). Returns the value returned
///     by the function or closure.
///
/// [`FromRequest`]: rocket::request::FromRequest
#[proc_macro_attribute]
pub fn database(attr: TokenStream, input: TokenStream) -> TokenStream {
    crate::database::database_attr(attr, input)
        .unwrap_or_else(|diag| diag.emit_as_item_tokens().into())
}

use std::iter::Iterator;
use std::vec::Vec;

pub struct BufferedIterator<T, TIter: Iterator<Item = T>> {
	itr: TIter,
	buf: Vec<T>,
}

impl<T, TIter: Iterator<Item = T>> BufferedIterator<T, TIter> {
	pub fn new(itr: TIter) -> BufferedIterator<T, TIter> {
		BufferedIterator {
			itr,
			buf: Vec::new(),
		}
	}

	pub fn pop(&mut self) -> Option<T> {
		if self.buf.is_empty() {
			self.itr.next()
		} else {
			self.buf.pop()
		}
	}

	pub fn push(&mut self, item: T) {
		self.buf.push(item);
	}
}

use std::io::{self, Read};

#[allow(dead_code)]
fn jumping_on_clouds(n: usize, clouds: Vec<u8>) -> usize {
    println!("n = {}, clouds = {:?}", n, clouds);
    let mut min_steps = n;

    let mut queue: Vec<(usize, usize)> = vec![(0, 0)];
    while let Some((len, i)) = queue.pop() {
        println!("queue has {}, {}", len, i);
        // possible steps are +1 or +2
        if i + 1 < n && clouds[i + 1] == 0 {
            queue.push((len + 1, i + 1));
        }
        if i + 2 < n && clouds[i + 2] == 0 {
            queue.push((len + 1, i + 2))
        }
        if i == n - 1 {
            println!("end of the line...");
            if len < min_steps {
                println!("new record {}!", len);
                min_steps = len;
            }
        }
    }
    min_steps
}

fn _main() -> io::Result<()> {
    let mut buffer = String::new();
    io::stdin().read_to_string(&mut buffer)?;

    let tokens: Vec<&str> = buffer.split("\n").collect();
    let n: usize = tokens[0].parse().unwrap();
    let clouds = tokens[1].split(" ").map(|c| c.parse().unwrap()).collect();

    let out = jumping_on_clouds(n, clouds);
    println!("{}", out);

    Ok(())
}

