        let expected_errnos = if sock_type == libc::SOCK_STREAM && how == libc::SHUT_RDWR {
            vec![libc::EPIPE]
        } else {
            vec![]
        };

        // second write() may have an error
        test_utils::check_system_call!(
            || {
                let buf: [u8; 4] = [1, 2, 3, 4];
                write_once(fd_client, &buf) as libc::c_int
            },
            &expected_errnos,
        )?;

        // check that write() returns the same errno if the buf length is 0
        test_utils::check_system_call!(
            || {
                let buf: [u8; 0] = [];
                write_once(fd_client, &buf) as libc::c_int
            },
            &expected_errnos,
        )?;

        Ok(())
    })
}

/// Test that the FIN is not sent until the buffer is cleared after shutdown() on both sockets.
fn test_tcp_fin_correctness(domain: libc::c_int, flag: libc::c_int) -> Result<(), String> {
    let (fd_client, fd_server) = setup_stream_sockets(domain, flag);

    test_utils::run_and_close_fds(&[fd_client, fd_server], || {
        const NUM_BYTES: usize = 120000;
        let buf = [0u8; NUM_BYTES];

        // run shutdown(SHUT_WR) on the client's socket to send a FIN
        check_shutdown_call(
            &ShutdownArguments {
                fd: fd_client,
                how: libc::SHUT_WR,
            },
            &[],
        )?;

        // write data from the server
        write_all(fd_server, &buf);

        // run shutdown(SHUT_WR) on the server's socket to send a FIN
        check_shutdown_call(
            &ShutdownArguments {
                fd: fd_server,
                how: libc::SHUT_WR,
            },
            &[],
        )?;

        // shadow needs to run events
        assert_eq!(unsafe { libc::usleep(10000) }, 0);

        // read at the client until an EOF
        let read_buf = read_all(fd_client);

        test_utils::result_assert_eq(
            NUM_BYTES,
            read_buf.len(),
            "Bytes written and read do not match.",
        )?;

        Ok(())
    })
}

fn check_shutdown_call(
    args: &ShutdownArguments,
    expected_errnos: &[libc::c_int],
) -> Result<(), String> {
    test_utils::check_system_call!(
        move || unsafe { libc::shutdown(args.fd, args.how) },
        expected_errnos,
    )?;

    Ok(())
}

use thiserror::Error;

/// Reductive error type.
#[derive(Error, Debug)]
#[non_exhaustive]
pub enum ReductiveError {
    #[error("The number of quantization attempts per iteration must be >= 1")]
    IncorrectNAttempts,

    #[error("The number of quantization iterations must be >= 1")]
    IncorrectNIterations,

    #[error(
        "The number of subquantizers bits must be between 1 and {}",
        max_subquantizer_bits
    )]
    IncorrectNSubquantizerBits { max_subquantizer_bits: u32 },

    #[error(
        "The number of columns ({}) is not exactly dividable by the number of subquantizers ({})",
        n_subquantizers,
        n_columns
    )]
    IncorrectNumberSubquantizers {
        n_subquantizers: usize,
        n_columns: usize,
    },

    #[error(
        "The number of subquantizers must be between 1 and {}, was {}",
        max_subquantizers,
        n_subquantizers
    )]
    NSubquantizersOutsideRange {
        n_subquantizers: usize,
        max_subquantizers: usize,
    },

    #[error("Cannot initialize random number generator for quantization")]
    ConstructRng(#[source] rand::Error),
}

