use std::path::Path;

use crate::{
    clamp,
    helpers::loader::{self, ImageHolder},
    perlin::Perlin,
    ray::Point,
    render::Color,
};

pub trait Texture: Send + Sync {
    fn value(&self, u: f64, v: f64, p: &Point) -> Color;
}

#[derive(Clone)]
pub struct SolidColor {
    color_value: Color,
}

impl SolidColor {
    pub fn new(color_value: Color) -> Self {
        Self { color_value }
    }
}

impl Texture for SolidColor {
    fn value(&self, _u: f64, _v: f64, _p: &Point) -> Color {
        self.color_value
    }
}

pub struct CheckerTexture<O, E> {
    odd: O,
    even: E,
}

impl CheckerTexture<SolidColor, SolidColor> {
    pub fn with_color(even: Color, odd: Color) -> Self {
        Self::with_texture(SolidColor::new(even), SolidColor::new(odd))
    }
}
impl<O, E> CheckerTexture<O, E>
where
    O: Texture,
    E: Texture,
{
    pub fn with_texture(even: E, odd: O) -> Self {
        Self { odd, even }
    }
}

impl<O, E> Texture for CheckerTexture<O, E>
where
    O: Texture,
    E: Texture,
{
    fn value(&self, u: f64, v: f64, p: &Point) -> Color {
        let calc = |v: f64| f64::sin(10.0 * v);
        let sines = calc(p.x()) * calc(p.y()) * calc(p.z());
        if sines < 0.0 {
            self.odd.value(u, v, p)
        } else {
            self.even.value(u, v, p)
        }
    }
}

pub struct NoiseTexture {
    noise: Perlin,
    scale: f64,
}

impl NoiseTexture {
    pub fn new() -> Self {
        Self::with_scale(1.0)
    }

    pub fn with_scale(scale: f64) -> Self {
        Self {
            noise: Perlin::new(),
            scale,
        }
    }
}

impl Texture for NoiseTexture {
    fn value(&self, _u: f64, _v: f64, p: &Point) -> Color {
        Color::new(1.0, 1.0, 1.0)
            * 0.5
            * (1.0 + f64::sin(self.scale * p.z() + 10.0 * self.noise.turb(p)))
    }
}

impl Default for NoiseTexture {
    fn default() -> Self {
        Self::new()
    }
}

#[derive(Default, Debug)]
pub struct ImageTexture {
    img: Option<ImageHolder>,
}

impl ImageTexture {
    pub fn new<P: AsRef<Path>>(path: P) -> anyhow::Result<Self> {
        let img = loader::read(path)?;
        Ok(Self { img: Some(img) })
    }
}

impl Texture for ImageTexture {
    fn value(&self, u: f64, v: f64, _p: &Point) -> Color {
        match self.img {
            None => [0.0, 1.0, 1.0].into(), // If we have no texture data, then return solid cyan as a debugging aid.
            Some(ref img) => {
                // Clamp input texture coordinates to [0,1] x [1,0]
                let u = clamp(u, 0.0, 1.0);
                let v = 1.0 - clamp(v, 0.0, 1.0); // Flip V to image coordinates

                let calc = |index, base: usize| {
                    let res = index * (base as f64);
                    assert!(res >= 0.0, "The value is below zero");

                    let res = res as usize;

                    // Clamp integer mapping, since actual coordinates should be less than 1.0
                    if res >= base {
                        base - 1
                    } else {
                        res
                    }
                };

                let i = calc(u, img.width());
                let j = calc(v, img.height());

                const COLOR_SCALE: f64 = 1.0 / 255.0;

                COLOR_SCALE * img[j][i]
            }
        }
    }
}

use fred::monitor::{self, Config};
use fred::prelude::*;
use futures::stream::StreamExt;
use std::time::Duration;
use tokio::time::sleep;

#[tokio::main]
async fn main() -> Result<(), RedisError> {
  pretty_env_logger::init();

  let monitor_jh = tokio::spawn(async move {
    let config = Config::default();
    let mut monitor_stream = monitor::run(config).await?;

    while let Some(command) = monitor_stream.next().await {
      // the Display trait prints results in the same format as redis-cli
      println!("{}", command);
    }

    Ok::<(), RedisError>(())
  });

  let config = RedisConfig::default();
  let client = RedisClient::new(config);
  let _ = client.connect(None);
  if let Err(error) = client.wait_for_connect().await {
    println!("Client failed to connect with error: {:?}", error);
  }

  for idx in 0..50 {
    let _ = client.set("foo", idx, Some(Expiration::EX(10)), None, false).await?;
  }
  let _ = client.quit().await?;

  sleep(Duration::from_secs(1)).await;
  monitor_jh.abort();
  Ok(())
}

