mod tests {
    use super::*;

    #[test]
    fn stem_works() {
        let url = "/d/a.html";
        assert_eq!("/d/", stem(url));
    }

    #[test]
    fn complete_works() {
        let page = "https://www.biquge.biz/d/";
        let full = "https://www.biquge.biz/d/a.html";

        let url = "/d/a.html";
        assert_eq!(full, &complete(url, page));

        let url = "a.html";
        assert_eq!(full, &complete(url, page));

        let url = full;
        assert_eq!(full, &complete(url, page));

        let page = "https://www.biquge.biz/d/index.html";
        let url = "a.html";
        assert_eq!(full, &complete(url, page));
    }
}

//! Day 3

use bitvec::prelude::*;

trait Solution {
    fn part_1(&self) -> usize;
    fn part_2(&self) -> usize;
}
impl Solution for str {
    fn part_1(&self) -> usize {
        count_trees(
            &parsers::input(self).expect("Failed to parse the input"),
            (3, 1),
        )
    }
    fn part_2(&self) -> usize {
        let map = &parsers::input(self).expect("Failed to parse the input");
        [(1, 1), (3, 1), (5, 1), (7, 1), (1, 2)]
            .iter()
            .map(|&slope| count_trees(&map, slope))
            .product()
    }
}

fn trajectory<'a>(
    start: (usize, usize),
    map: &'a [impl AsRef<BitSlice>],
    slope: (usize, usize),
) -> impl Iterator<Item = bool> + 'a {
    let (from_left, from_top) = start;
    let (right_step, down_step) = slope;
    map.iter()
        .skip(from_top)
        .step_by(down_step)
        .scan(from_left, move |st, row| {
            let ix = *st;
            *st = (*st + right_step) % row.as_ref().len();
            Some(row.as_ref()[ix])
        })
}

fn count_trees(map: &[impl AsRef<BitSlice>], slope: (usize, usize)) -> usize {
    trajectory((0, 0), &map, slope).filter(|v| *v).count()
}

