use fere::prelude::{fere_resources::Texture, *};
use fere_window::*;
use rand::prelude::*;
use rayon::prelude::*;
use std::sync::Arc;

struct Scene {
    renderer: Fere,
    world: Option<Box<World>>,
    resources: Arc<Resources>,

    frame_count: usize,
}

struct Resources {
    triangle: Arc<Texture>,
}

#[derive(Clone, Debug)]
struct Particle {
    pos: Vec3,
    speed: Vec3,
    acc: Vec3,
    color: IVec3,
    size: f32,
}

struct World {
    particles: Vec<Particle>,
    time: usize,
}

fn gen_color(x: f32) -> IVec3 {
    let r = (x * 0.9 + 0.4).cos() + 1.0;
    let b = (x * 0.8 + 0.3).cos() + 1.0;
    let g = (x * 0.7 + 0.2).cos() + 1.0;
    let r = 128 + (127.0 * r * 0.5) as i32;
    let g = 128 + (127.0 * g * 0.5) as i32;
    let b = 128 + (127.0 * b * 0.5) as i32;
    IVec3::new(r, g, b)
}

fn cos(x: f32) -> f32 {
    x.cos()
}

fn posco(x: f32) -> f32 {
    1.0 + x.cos() * 0.5
}

impl World {
    fn new() -> Self {
        let mut rng = thread_rng();
        Self {
            particles: Vec::new(),
            time: rng.gen_range(0..100),
        }
    }

    fn update(&mut self) {
        let params = [(1.0, 2.0), (3.0, 2.0), (4.0, 1.0), (2.0, 2.0)];

        if self.time % 2 == 0 {
            let t = self.time as f32 * 0.1;

            let sp_pos: Vec<_> = params
                .iter()
                .map(|(a, b)| {
                    let a = *a;
                    let b = *b;
                    let x = cos(cos(t * (0.4 + posco(a)) * 0.4) * (cos(a) + 1.1)) * 200.0
                        + cos(cos(t * 0.3 * cos(b))) * 10.0;
                    let y = cos(cos(t * (0.4 + posco(a)) * 0.4) * (cos(b) + 1.1)) * 200.0
                        + cos(cos(t * 0.3 * cos(a))) * 10.0;
                    let z = 0.0;
                    Vec3::new(x, y, z)
                })
                .collect();

            for (s, sp) in sp_pos.iter().enumerate() {
                for i in 0..30 {
                    let at = (i as f32) / 30.0;
                    let angle = (((t * 2.1 + cos(sp.x)) as i32 * 3 + (i as i32) * 5) as f32)
                        .to_radians()
                        + 3.0 * cos(params[s].0);
                    let speed = Vec3::new(angle.cos(), angle.sin(), 0.0) * (2.0 + at);
                    for j in 0..3 {
                        self.particles.push(Particle {
                            pos: *sp,
                            speed,
                            acc: Vec3::new(-speed.y, speed.x, 0.0) * (0.02 + (j as f32) * 0.01),
                            color: gen_color(t + at * 3.0),
                            size: 0.5,
                        });
                    }
                }
            }
        }
        self.particles.par_iter_mut().for_each(|x| {
            x.speed += x.acc;
            x.pos += x.speed;
        });

        self.particles.retain(|x| length(&x.pos) < 700.0);
        println!("{}", self.particles.len());
        self.time += 1;
    }
}

impl Program for Scene {
    fn new() -> Self {
        let mut config: FereConfigs = serde_yaml::from_str(
            &std::fs::read_to_string("./examples/examples/basic_fere_configs.yml").unwrap(),
        )
        .unwrap();
        config.video_record = true;
        let mut renderer = Fere::new(config);
        renderer.start_recording(5555).unwrap();
        let world = Some(Box::new(World::new()));
        Scene {
            renderer,
            resources: Arc::new(Resources {
                triangle: fere_examples::read_texture("triangle.png"),
            }),
            world,
            frame_count: 0,
        }
    }

    fn update(&mut self) -> String {
        let cpos = Vec3::new(0.0, 0.0, 300.0);
        let screen_size = self.renderer.configs().resolution;
        let mut camera = SetCamera::new(
            cpos,
            Vec3::new(0.0, 0.0, 0.0),
            Vec3::new(0.0, 1.0, 0.0),
            (90.0_f32).to_radians(),
            screen_size.x as f32 / screen_size.y as f32,
            0.1,
            1000.0,
        );
        camera.trans();

        let (frame, renderer) = self.renderer.new_frame(FrameConfig {
            camera,
            show_lightvolume_outline: false,
        });

        let resources = Arc::clone(&self.resources);
        self.world.as_mut().unwrap().update();
        let world = self.world.take().unwrap();

        let render_thread = std::thread::spawn(|| render(frame, resources, world));
        self.renderer.end_frame(renderer.render());
        self.world = Some(render_thread.join().unwrap());

        self.frame_count += 1;
        if self.frame_count == 200 {
            self.renderer.end_recording().unwrap();
            return "exit".to_owned();
        }

        "continue".to_owned()
    }
}

fn render(mut frame: Frame, resources: Arc<Resources>, world: Box<World>) -> Box<World> {
    for p in &world.particles {
        frame.push(rops::DrawBillboard {
            texture: Arc::clone(&resources.triangle),
            depth_test: false,
            depth_write: false,
            pos: p.pos,
            size: Vec2::from_element(p.size),
            rotation: f32::atan2(p.speed.y, p.speed.x) - (90.0_f32).to_radians(),
            blend_mode: (),
            color: Vec4::new(
                p.color.x as f32 / 255.0,
                p.color.y as f32 / 255.0,
                p.color.z as f32 / 255.0,
                0.5,
            ),
        });
    }
    frame.end();
    world
}

fn main() {
    run::<Scene>(
        serde_yaml::from_str(
            &std::fs::read_to_string("./examples/examples/window_config.yml").unwrap(),
        )
        .unwrap(),
    );
}

fn intro() {
    macro_rules! cake {
        () => {
            42
        };
    }

    assert_eq!(cake!(), 42);
}

fn syntax_designators() {
    //desognators: block, expr (expressions), ident (variable/function name), item, literal (literal constants), pat (pattern), path, stmt (statement), tt (token tree), ty (type), vis (visibility qualifier)

    macro_rules! create_function {
        ($func_name:ident) => {
            fn $func_name() {
                println!("You called {}", stringify!($func_name))
            }
        };
    }

    create_function!(cake);
    cake();

    macro_rules! print_result {
        ($expression:expr) => {
            println!("{:?} = {:?}", stringify!($expression), $expression);
        };
    }

    print_result!(1 + 2);
}

fn syntax_overload() {
    macro_rules! test {
        ($left:expr, and $right:expr) => {
            println!(
                "{:?} and {:?} is {:?}",
                stringify!($left),
                stringify!($right),
                $left && $right
            )
        };
        ($left:expr; or $right:expr) => {
            println!(
                "{:?} or {:?} is {:?}",
                stringify!($left),
                stringify!($right),
                $left || $right
            )
        };
    }

    test!(1i32 + 1 == 2i32, and 2i32 * 2 == 4i32);
    test!(true; or false);
}

fn syntax_repeat() {
    macro_rules! find_min {
          // Base case:
          ($x:expr) => ($x);
          // `$x` followed by at least one `$y,`
          ($x:expr, $($y:expr),+) => (
              // Call `find_min!` on the tail `$y`
              std::cmp::min($x, find_min!($($y),+))
          )
      }

    assert_eq!(find_min!(1u32), 1);
    assert_eq!(find_min!(1u32 + 2, 2u32), 2);
    assert_eq!(find_min!(5u32, 2u32 * 3, 4u32), 4);
}

pub fn main() {
    intro();
    syntax_designators();
    syntax_overload();
    syntax_repeat();
}

use std::{ops::Range, rc::Rc};

use num::{ToPrimitive, Zero};

use crate::{
    vm::{error::Result, machine::PathElement, QueryExecutionError},
    Array, Number, Object, Value,
};

fn number_to_isize(n: Number) -> isize {
    n.to_isize().unwrap_or(if n > Zero::zero() {
        isize::MAX
    } else {
        isize::MIN
    })
}

fn parse_and_shift_index<F: Fn(Value) -> QueryExecutionError>(
    array_length: usize,
    index: &Value,
    err: F,
) -> Result<Option<usize>> {
    let i = match index {
        Value::Number(i) => *i,
        value => return Err(err(value.clone())),
    };
    let i = number_to_isize(i);
    let idx = if i < 0 {
        let shifted = i + (array_length as isize);
        if shifted < 0 {
            return Ok(None);
        } else {
            shifted as usize
        }
    } else {
        i as usize
    };
    Ok(Some(idx))
}

pub(crate) fn index(value: Value, index: Value) -> Result<(Value, PathElement)> {
    match value {
        Value::Null
            if matches!(
                index,
                Value::String(_) | Value::Number(_) | Value::Object(_)
            ) =>
        {
            Ok((Value::Null, PathElement::Any(index)))
        }
        value @ (Value::Null | Value::Boolean(_) | Value::Number(_)) => {
            Err(QueryExecutionError::IndexOnNonIndexable(value))
        }
        Value::String(s) => {
            let len = s.chars().count();
            let idx = parse_and_shift_index(len, &index, QueryExecutionError::ArrayIndexByNonInt)?;
            Ok((
                idx.and_then(|i| s.chars().nth(i))
                    .map(|c| Value::string(String::from(c)))
                    .unwrap_or_else(|| Value::string("".to_string())),
                PathElement::Any(index),
            ))
        }
        Value::Array(array) => {
            let idx = parse_and_shift_index(
                array.len(),
                &index,
                QueryExecutionError::ArrayIndexByNonInt,
            )?;
            Ok((
                idx.and_then(|i| array.get(i).cloned())
                    .unwrap_or(Value::Null),
                PathElement::Any(index),
            ))
        }
        Value::Object(map) => {
            let i = match index {
                Value::String(i) => i,
                value => return Err(QueryExecutionError::ObjectIndexByNonString(value)),
            };
            Ok((
                map.get(&i).cloned().unwrap_or(Value::Null),
                PathElement::Object(i),
            ))
        }
    }
}

pub(crate) fn calculate_slice_index(
    length: usize,
    start: Option<&Value>,
    end: Option<&Value>,
) -> Result<Range<usize>> {
    if start.is_none() && end.is_none() {
        return Err(QueryExecutionError::UnboundedRange);
    }
    let start = if let Some(start) = start {
        parse_and_shift_index(length, start, QueryExecutionError::SliceByNonInt)?
            .unwrap_or(0)
            .clamp(0, length)
    } else {
        0
    };
    let end = if let Some(end) = end {
        parse_and_shift_index(length, end, QueryExecutionError::SliceByNonInt)?
            .unwrap_or(0)
            .clamp(start, length)
    } else {
        length
    };
    Ok(start..end)
}

pub(crate) fn slice(
    value: Value,
    start: Option<Value>,
    end: Option<Value>,
) -> Result<(Value, PathElement)> {
    let path_element = {
        let mut obj = Object::new();
        if let Some(start) = &start {
            obj.insert(Rc::new("start".to_string()), start.clone());
        }
        if let Some(end) = &end {
            obj.insert(Rc::new("end".to_string()), end.clone());
        }
        PathElement::Any(obj.into())
    };
    let length = match &value {
        Value::Null => {
            return Ok((Value::Null, path_element)); // Why jq doesn't check `start` and `end` type...
        }
        Value::Boolean(_) | Value::Number(_) | Value::Object(_) => {
            return Err(QueryExecutionError::SliceOnNonArrayNorString(value));
        }
        Value::String(s) => s.chars().count(),
        Value::Array(v) => v.len(),
    };
    let range = calculate_slice_index(length, start.as_ref(), end.as_ref())?;
    match value {
        Value::String(s) => Ok((
            Value::string(
                s.chars()
                    .enumerate()
                    .filter(|(i, _)| range.contains(i))
                    .map(|(_, c)| c)
                    .collect::<String>(),
            ),
            path_element,
        )),
        Value::Array(array) => Ok((
            (&array[range]).iter().cloned().collect::<Array>().into(),
            path_element,
        )),
        _ => unreachable!(),
    }
}

use super::{BeaconStateError, ChainSpec, Epoch, Validator};
use safe_arith::SafeArith;
use serde_derive::{Deserialize, Serialize};
use std::collections::HashMap;

/// Map from exit epoch to the number of validators known to be exiting/exited at that epoch.
#[derive(Debug, Default, Clone, PartialEq, Serialize, Deserialize)]
pub struct ExitCache {
    initialized: bool,
    exits_per_epoch: HashMap<Epoch, u64>,
}

impl ExitCache {
    /// Ensure the cache is built, and do nothing if it's already initialized.
    pub fn build(
        &mut self,
        validators: &[Validator],
        spec: &ChainSpec,
    ) -> Result<(), BeaconStateError> {
        if self.initialized {
            Ok(())
        } else {
            self.force_build(validators, spec)
        }
    }

    /// Add all validators with a non-trivial exit epoch to the cache.
    pub fn force_build(
        &mut self,
        validators: &[Validator],
        spec: &ChainSpec,
    ) -> Result<(), BeaconStateError> {
        self.initialized = true;
        validators
            .iter()
            .filter(|validator| validator.exit_epoch != spec.far_future_epoch)
            .try_for_each(|validator| self.record_validator_exit(validator.exit_epoch))
    }

    /// Check that the cache is initialized and return an error if it isn't.
    pub fn check_initialized(&self) -> Result<(), BeaconStateError> {
        if self.initialized {
            Ok(())
        } else {
            Err(BeaconStateError::ExitCacheUninitialized)
        }
    }

    /// Record the exit of a single validator in the cache.
    ///
    /// Must only be called once per exiting validator.
    pub fn record_validator_exit(&mut self, exit_epoch: Epoch) -> Result<(), BeaconStateError> {
        self.check_initialized()?;
        self.exits_per_epoch
            .entry(exit_epoch)
            .or_insert(0)
            .increment()?;
        Ok(())
    }

    /// Get the greatest epoch for which validator exits are known.
    pub fn max_epoch(&self) -> Result<Option<Epoch>, BeaconStateError> {
        self.check_initialized()?;
        Ok(self.exits_per_epoch.keys().max().cloned())
    }

    /// Get the number of validators exiting/exited at a given epoch, or zero if not known.
    pub fn get_churn_at(&self, epoch: Epoch) -> Result<u64, BeaconStateError> {
        self.check_initialized()?;
        Ok(self.exits_per_epoch.get(&epoch).cloned().unwrap_or(0))
    }
}

// C-compatible API for lexical conversion routines.

use crate::lib::slice;
use lexical_core;

// HELPERS

/// Calculate the difference between two pointers.
#[inline]
pub fn distance<T>(first: *const T, last: *const T)
    -> usize
{
    debug_assert!(last >= first, "range must be positive.");
    let f = first as usize;
    let l = last as usize;
    l - f
}

/// Convert a mutable pointer range to a mutable slice safely.
#[inline]
pub(crate) unsafe fn slice_from_range_mut<'a, T>(first: *mut T, last: *mut T)
    -> &'a mut [T]
{
    assert!(first <= last && !first.is_null() && !last.is_null());
    slice::from_raw_parts_mut(first, distance(first, last))
}

// FROM LEXICAL

/// Macro to generate complete parser from a pointer range.
macro_rules! lexical_from_range {
    (
        fn $name:ident,
        callback => $callback:ident,
        type => $type:ty,
        args => $($argname:ident : $argtype:ty ;)*,
        condition => $($condition:tt)*
    ) => (
        #[doc(hidden)]
        #[no_mangle]
        $($condition)*
        pub unsafe extern fn $name(first: *const u8, last: *const u8 $(,$argname : $argtype)*)
            -> $crate::result::Result<$type>
        {
            assert!(first <= last && !first.is_null() && !last.is_null());
            let bytes = $crate::lib::slice::from_raw_parts(first, distance(first, last));
            lexical_core::$callback(bytes $(,$argname)*).into()
        }
    );
}

// Macro to generate the partial parser from a pointer range.
macro_rules! lexical_partial_from_range {
    (
        fn $name:ident,
        callback => $callback:ident,
        type => $type:ty,
        args => $($argname:ident : $argtype:ty ;)*,
        condition => $($condition:tt)*
    ) => (
        #[doc(hidden)]
        #[no_mangle]
        $($condition)*
        pub unsafe extern fn $name(first: *const u8, last: *const u8 $(,$argname : $argtype)*)
            -> $crate::result::Result<$crate::result::Tuple<$type, usize>>
        {
            assert!(first <= last && !first.is_null() && !last.is_null());
            let bytes = $crate::lib::slice::from_raw_parts(first, distance(first, last));
            match lexical_core::$callback(bytes $(,$argname)*) {
                Ok(v)  => Ok(v.into()),
                Err(e) => Err(e),
            }.into()
        }
    );
}

// Macro to generate parsers implementing the FromLexical trait.
macro_rules! from_lexical {
    (
        type => $type:ty,
        decimal => $decimal_name:ident,
        partial_decimal => $partial_decimal_name:ident,
        radix => $radix_name:ident,
        partial_radix => $partial_radix_name:ident
    ) => (
        // Decimal.
        lexical_from_range!(
            fn $decimal_name,
            callback => parse,
            type => $type,
            args =>,
            condition =>
        );

        // Partial decimal.
        lexical_partial_from_range!(
            fn $partial_decimal_name,
            callback => parse_partial,
            type => $type,
            args =>,
            condition =>
        );

        // Radix.
        lexical_from_range!(
            fn $radix_name,
            callback => parse_radix,
            type => $type,
            args => radix: u8 ;,
            condition => #[cfg(feature = "radix")]
        );

        // Partial radix.
        lexical_partial_from_range!(
            fn $partial_radix_name,
            callback => parse_partial_radix,
            type => $type,
            args => radix: u8 ;,
            condition => #[cfg(feature = "radix")]
        );
    );
}

// Macro to generate parsers implementing the FromLexicalLossy trait.
macro_rules! from_lexical_lossy {
    (
        type => $type:ty,
