pub struct DeployOptions<'a> {
    pub targets: Vec<&'a str>,
    pub profile: &'a str,
    pub verbosity: Verbosity,
    pub deployer_args: Vec<&'a str>,
}

impl<'a> DeployOptions<'a> {
    pub fn new(m: &'a clap::ArgMatches, config: &Config) -> Result<Self> {
        let profile_name = m.value_of("profile").unwrap();
        match config.profile(profile_name) {
            Ok(_) => (),
            Err(ProfileError {
                kind: ProfileErrorKind::MissingKey("credential"),
                ..
            }) if config
                .profile_raw(profile_name)
                .and_then(|t| t.get("gateway"))
                .and_then(|gw| gw.as_str())
                .map(|gw| gw == DEFAULT_GATEWAY_URL)
                .unwrap_or_default() =>
            {
                print_need_deploy_key_message!(profile_name);
                return Err(anyhow::anyhow!(
                    "`profile.{}.credential` must be set to deploy on the Oasis Devnet.",
                    profile_name
                ));
            }
            Err(e) => return Err(e.into()),
        }
        Ok(Self {
            profile: profile_name,
            targets: m.values_of("TARGETS").unwrap_or_default().collect(),
            verbosity: Verbosity::from(
                m.occurrences_of("verbose") as i64 - m.occurrences_of("quiet") as i64,
            ),
            deployer_args: m.values_of("deployer_args").unwrap_or_default().collect(),
        })
    }
}

impl<'a> super::ExecSubcommand for DeployOptions<'a> {
    fn exec(self) -> Result<()> {
        let workspace = Workspace::populate()?;
        let targets = workspace.collect_targets(&self.targets)?;
        let build_opts = super::BuildOptions {
            targets: self.targets.clone(),
            debug: false,
            verbosity: self.verbosity,
            stack_size: None,
            wasi: false,
            builder_args: Vec::new(),
        };
        super::build(&workspace, &targets, build_opts)?;
        deploy(&targets, self)
    }
}

pub fn deploy(targets: &[&Target], opts: DeployOptions) -> Result<()> {
    let mut found_deployable = false;
    for target in targets.iter().filter(|t| t.is_deployable()) {
        let proj = &target.project;
        match &proj.kind {
            ProjectKind::JavaScript { .. } | ProjectKind::TypeScript { .. } => {
                if opts.verbosity > Verbosity::Quiet {
                    print_status_in(
                        Status::Deploying,
                        &target.name,
                        proj.manifest_path.parent().unwrap(),
                    );
                }
                found_deployable = true;
                deploy_javascript(target, &opts)?
            }
            ProjectKind::Rust => {}
            _ => {}
        }
    }
    if !found_deployable {
        warn!("no deployable services found. Does your `package.json` contain a `deploy` script?");
    }
    Ok(())
}

fn deploy_javascript(target: &Target, opts: &DeployOptions) -> Result<()> {
    emit!(cmd.deploy.start, {
        "project_type": "js",
        "deployer_args": opts.deployer_args,
    });

    let mut args = Vec::new();
    if !opts.deployer_args.is_empty() {
        args.push("--");
        args.extend(opts.deployer_args.iter());
    }

    let mut envs = BTreeMap::new();
    envs.insert(
        OsString::from("OASIS_PROFILE"),
        OsString::from(&opts.profile),
    );
    if let Err(e) = BuildTool::for_target(target).deploy(args, envs, opts.verbosity) {
        emit!(cmd.deploy.error);
        return Err(e);
    }

    emit!(cmd.deploy.done);
    Ok(())
}

//! Rotates a character towards a direction.

use amethyst::{
    core::Transform,
    ecs::{World, WorldExt},
};

use crate::{
    animations::AnimationTable,
    common::Direction,
    map::{MapHandler, PlayerCoordinates},
    overworld::entities::character::{Character, CharacterAnimation, CharacterId, PlayerEntity},
};

use super::{BoxedGameEvent, ExecutionConditions, GameEvent};

#[derive(Clone)]
pub struct CharacterRotateEvent {
    character_id: CharacterId,
    direction_type: DirectionType,
}

#[derive(Clone)]
enum DirectionType {
    Fixed(Direction),
    TowardsPlayer,
}

impl DirectionType {
    fn get_direction(&self, world: &World, character_id: CharacterId) -> Option<Direction> {
        match self {
            DirectionType::Fixed(direction) => Some(direction.clone()),
            DirectionType::TowardsPlayer => {
                let npc_entity = world
                    .read_resource::<MapHandler>()
                    .get_character_by_id(character_id);

                let npc_position = world
                    .read_storage::<Transform>()
                    .get(npc_entity)
                    .map(PlayerCoordinates::from_transform)
                    .unwrap();

                let player_entity = world.read_resource::<PlayerEntity>();

                let player_position = world
                    .read_storage::<Transform>()
                    .get(player_entity.0)
                    .map(PlayerCoordinates::from_transform)
                    .unwrap();

                npc_position.get_direction_to(&player_position)
            },
        }
    }
}

impl CharacterRotateEvent {
    /// Instantiates a CharacterRotateEvent that rotates a character towards
    /// a given direction.
    pub fn new(character_id: CharacterId, direction: Direction) -> CharacterRotateEvent {
        CharacterRotateEvent {
            character_id,
            direction_type: DirectionType::Fixed(direction),
        }
    }

    /// Instantiates a CharacterRotateEvent that rotates a character towards
    /// the human player.
    pub fn towards_player(character_id: CharacterId) -> CharacterRotateEvent {
        CharacterRotateEvent {
            character_id,
            direction_type: DirectionType::TowardsPlayer,
        }
    }
}

impl GameEvent for CharacterRotateEvent {
    fn boxed_clone(&self) -> BoxedGameEvent {
        Box::new(self.clone())
    }

    fn get_execution_conditions(&self) -> ExecutionConditions {
        ExecutionConditions {
            requires_disabled_input: false,
            ..ExecutionConditions::default()
        }
    }

    fn start(&mut self, _world: &mut World) {}

    fn tick(&mut self, world: &mut World, _disabled_inputs: bool) {
        let entity = world
            .read_resource::<MapHandler>()
            .get_character_by_id(self.character_id);

        if let Some(direction) = self.direction_type.get_direction(world, self.character_id) {
            world
                .write_storage::<AnimationTable<CharacterAnimation>>()
                .get_mut(entity)
                .unwrap()
                .change_animation(CharacterAnimation::Idle(direction.clone()));

            world
                .write_storage::<Character>()
                .get_mut(entity)
                .unwrap()
                .facing_direction = direction;
        }
    }

    fn is_complete(&self, _world: &mut World) -> bool {
        true
    }
}

