// READER

type PeakableLines<T> = Peekable<Lines<T>>;

/// Parse the start header line.
#[inline(always)]
fn parse_start_line<T: BufRead>(lines: &mut PeakableLines<T>, _: &mut Record)
    -> Result<()>
{
    // Verify the start header line.
    let line = none_to_error!(lines.next(), InvalidInput)?;
    bool_to_error!(line == "BEGIN IONS", InvalidInput);

    Ok(())
}

/// Parse the title header line.
#[inline(always)]
fn parse_title_line<T: BufRead>(lines: &mut PeakableLines<T>, record: &mut Record)
    -> Result<()>
{
    type Title = MsConvertMgfTitleRegex;

    // Verify and parse the title line.
    let line = none_to_error!(lines.next(), InvalidInput)?;
    let captures = none_to_error!(Title::extract().captures(&line), InvalidInput);
    record.file = capture_as_string(&captures, Title::FILE_INDEX);

    let num = capture_as_str(&captures, Title::NUM_INDEX);
    record.num = from_string(num)?;

    Ok(())
}

/// Parse the RT header line.
#[inline(always)]
fn parse_rt_line<T: BufRead>(lines: &mut PeakableLines<T>, record: &mut Record)
    -> Result<()>
{
    type Rt = MsConvertMgfRtRegex;

    // Verify and parse the RT line.
    let line = none_to_error!(lines.next(), InvalidInput)?;
    let captures = none_to_error!(Rt::extract().captures(&line), InvalidInput);

    let rt = capture_as_str(&captures, Rt::RT_INDEX);
    record.rt = from_string(rt)?;

    Ok(())
}

/// Parse the pepmass header line.
#[inline(always)]
fn parse_pepmass_line<T: BufRead>(lines: &mut PeakableLines<T>, record: &mut Record)
    -> Result<()>
{
    type PepMass = MsConvertMgfPepMassRegex;

    // Verify and parse the pepmass line.
    let line = none_to_error!(lines.next(), InvalidInput)?;
    let captures = none_to_error!(PepMass::extract().captures(&line), InvalidInput);

    let mz = capture_as_str(&captures, PepMass::PARENT_MZ_INDEX);
    record.parent_mz = from_string(mz)?;

    let intensity = optional_capture_as_str(&captures, PepMass::PARENT_INTENSITY_INDEX);
    record.parent_intensity = nonzero_from_string(intensity)?;

    Ok(())
}

/// Parse the charge header line.
#[inline(always)]
fn parse_charge_line<T: BufRead>(lines: &mut PeakableLines<T>, record: &mut Record)
    -> Result<()>
{
    type Charge = MsConvertMgfChargeRegex;

    // Check if the following line is an error or a charge line.
    let is_err: bool;
    let is_charge: bool;
    {
        let peeked_line = none_to_error!(lines.peek(), InvalidInput);
        match peeked_line {
            Err(_) => {
                is_err = true;
                is_charge = false;
            },
            Ok(ref v) => {
                is_err = false;
                is_charge = v.starts_with("CHARGE=");
            }
        }
    }

    // Process the optional charge line.
    if is_err {
        // Return an error if the line
        return Err(From::from(lines.next().unwrap().unwrap_err()));
    } else if is_charge {
        // Verify and parse the charge line
        let line = lines.next().unwrap()?;
        let captures = none_to_error!(Charge::extract().captures(&line), InvalidInput);
        let z: i8 = from_string(capture_as_str(&captures, Charge::PARENT_Z_INDEX))?;
        let sign = capture_as_str(&captures, Charge::PARENT_Z_SIGN_INDEX);
        match sign {
            "-" => record.parent_z = -z,
            "+" => record.parent_z = z,
            // The capture group recognizes exactly "-" or "+".
            _   => unreachable!(),
        }
    } else {
        // Do not consume the peeked value!
        record.parent_z = 1;
    }

    Ok(())
}

/// Parse the charge header line.
#[inline(always)]
fn parse_spectra<T: BufRead>(lines: &mut PeakableLines<T>, record: &mut Record)
    -> Result<()>
{
    for result in lines {
        let line = result?;
        if line == "END IONS" {
            break;
        }

        // Parse the line data
        let mut items = line.split(' ');
        let mz = none_to_error!(items.next(), InvalidInput);
        let intensity = none_to_error!(items.next(), InvalidInput);
        bool_to_error!(items.next().is_none(), InvalidInput);

        record.peaks.push(Peak {
            mz: from_string(mz)?,
            intensity: from_string(intensity)?,
            z: 0,
        });
    }

    Ok(())
}

/// Import record from MGF.
pub(crate) fn record_from_msconvert_mgf<T: BufRead>(reader: &mut T)
    -> Result<Record>
{
    let mut lines = reader.lines().peekable();
    let mut record = Record::with_peak_capacity(50);

    parse_start_line(&mut lines, &mut record)?;
    parse_title_line(&mut lines, &mut record)?;
    parse_rt_line(&mut lines, &mut record)?;
    parse_pepmass_line(&mut lines, &mut record)?;
    parse_charge_line(&mut lines, &mut record)?;
    parse_spectra(&mut lines, &mut record)?;

    record.peaks.shrink_to_fit();
    Ok(record)
}

// READER -- DEFAULT

/// Create default record iterator from reader.
#[inline(always)]
pub(crate) fn iterator_from_msconvert_mgf<T: BufRead>(reader: T)
    -> MgfRecordIter<T>
{
    MgfRecordIter::new(reader, b"BEGIN IONS", MgfKind::MsConvert)
}

use arcdps::imgui::ImString;
use windows::Win32::{
    Foundation::PSTR,
    UI::{
        Input::KeyboardAndMouse::{GetKeyNameTextA, MapVirtualKeyA},
        WindowsAndMessaging::MAPVK_VK_TO_VSC,
    },
};

/// Converts a keycode to the key's name.
pub fn keycode_to_name(keycode: u32) -> Option<ImString> {
    let scan_code = unsafe { MapVirtualKeyA(keycode, MAPVK_VK_TO_VSC) };

    const SIZE: i32 = 4;
    let mut buffer = ImString::with_capacity(SIZE as usize);

    let result = unsafe {
        GetKeyNameTextA(
            (scan_code << 16) as i32,
            PSTR(buffer.as_mut_ptr() as *mut u8),
            SIZE,
        )
    };

    if result > 0 {
        Some(buffer)
    } else {
        None
    }
}

extern crate rust_hyper;

// init slog out of band to make actual code logger agnostic
#[macro_use]
extern crate slog;
extern crate slog_async;
extern crate slog_envlogger;
extern crate slog_scope;
extern crate slog_stdlog;
extern crate slog_term;

fn main() -> Result<(), Box<::std::error::Error>> {
    // (max) when the guard is dropped, the global logger will reset. So
    // since rust_hyper::run() never returns...it will never reset :-)
    let _guard = init_logger();

    rust_hyper::run()
}

fn init_logger() -> slog_scope::GlobalLoggerGuard {
    use slog::Drain;

    let decorator = slog_term::TermDecorator::new().stderr().build();
    let fmt = slog_term::FullFormat::new(decorator).build().fuse();
    let drain = slog_async::Async::new(slog_envlogger::new(fmt))
        .build()
        .fuse();
    let root_logger = slog::Logger::root(drain.fuse(), o!());

    slog_stdlog::init().unwrap();
    slog_scope::set_global_logger(root_logger)
}

use crate::{Settings, services::BlobService};
use async_stream::try_stream;
use futures::Stream;
use futures::io::Read;

use std::pin::Pin;
use tonic::{Request, Response, Status, Streaming};
use tracing::{error, info};

pub mod blob {
    tonic::include_proto!("blob");
}
pub use blob::blob_handler_server::BlobHandlerServer;
use blob::{blob_data::Data, blob_handler_server::BlobHandler, BlobData, BlobInfo, FileInfo};

#[derive(Debug)]
pub struct BlobProvider {
    blob_service: BlobService,
}

impl BlobProvider {
    pub fn new(settings: &Settings) -> Self {
        BlobProvider {
            blob_service: BlobService::new(settings.upload_path.clone()).unwrap(),
        }
    }
}

#[tonic::async_trait]
impl BlobHandler for BlobProvider {
    type DownloadStream =
        Pin<Box<dyn Stream<Item = Result<BlobData, Status>> + Send + Sync + 'static>>;

    #[tracing::instrument]
    async fn download(
        &self,
        request: Request<BlobInfo>,
    ) -> Result<Response<Self::DownloadStream>, Status> {
        let blob_id = request.into_inner().blob_id;
        info!("Requested download of: {}", &blob_id);
        let service = self.blob_service.clone();


        let mut stream =
        service.reader(&blob_id)
        .await
        .map_err(map_service_error)?;

        let m = stream.read::<Option<Vec<u8>>>().await.unwrap();

        let output = try_stream! {
            let mut stream =
                service.reader(&blob_id)
                .await
                .map_err(map_service_error)?;

            while let Some(chunk) = stream.read::<Option<Vec<u8>>>().await
                .unwrap_or_else(|err| { error!("Service Error: {}", err); None })
            {
                yield BlobData { data: Some(Data::ChunkData(chunk)), };
            }

            yield BlobData {
                data: Some(
                    Data::Info(
                        FileInfo {
                            extension: ".jpeg".to_string(),
                            file_name: blob_id.to_string(),
                            meta_text: "Meta text".to_string(),
                        }
                    )
                )
            };
        };

        Ok(Response::new(Box::pin(output) as Self::DownloadStream))
    }

    #[tracing::instrument]
    async fn upload(
        &self,
        stream: Request<Streaming<BlobData>>,
    ) -> Result<Response<BlobInfo>, Status> {
        info!("Uploading image to server");

        let mut blob = self
            .blob_service
            .writer()
            .create_blob()
            .await
            .map_err(map_service_error)?;

        let mut file_info: Option<FileInfo> = None;
        let mut s = stream.into_inner();
        while let Some(req) = s.message().await? {
            if let Some(d) = req.data {
                match d {
                    Data::Info(info) => file_info = Some(info),
                    Data::ChunkData(chunk) => {
                        blob.append(chunk).await.map_err(map_service_error)?
                    }
                }
            }
        }

        match file_info {
            Some(f) => {
                let blob_id = blob
                    .finalize(&f.extension)
                    .await
                    .map_err(map_service_error)?;
                info!("Upload finished, file {}", &blob_id);
                Ok(Response::new(BlobInfo { blob_id }))
            }
            None => {
                info!("No FileInfo received, aborting");
                blob.abort().await.map_err(map_service_error)?;
                Err(tonic::Status::aborted("No FileInfo was received!"))
            }
        }
    }
}

pub fn map_service_error<E: std::error::Error>(se: E) -> tonic::Status {
    Status::unavailable(format!("Service error: {}", se))
}

