use std::convert::Infallible;
use std::net::SocketAddr;
use std::sync::{Arc, RwLock};
use std::thread;

use anyhow::Result;
use hyper::service::{make_service_fn, service_fn};
use hyper::{Body, Method, Request, Response, Server, StatusCode};
use log::{error, info};

use crate::zenith::*;

// Service function to handle all available routes.
async fn routes(req: Request<Body>, state: Arc<RwLock<ComputeState>>) -> Response<Body> {
    match (req.method(), req.uri().path()) {
        // Timestamp of the last Postgres activity in the plain text.
        (&Method::GET, "/last_activity") => {
            info!("serving /last_active GET request");
            let state = state.read().unwrap();

            // Use RFC3339 format for consistency.
            Response::new(Body::from(state.last_active.to_rfc3339()))
        }

        // Has compute setup process finished? -> true/false
        (&Method::GET, "/ready") => {
            info!("serving /ready GET request");
            let state = state.read().unwrap();
            Response::new(Body::from(format!("{}", state.ready)))
        }

        (&Method::GET, "/check_writability") => {
            info!("serving /check_writability GET request");
            let res = crate::checker::check_writability(&state).await;
            match res {
                Ok(_) => Response::new(Body::from("true")),
                Err(e) => Response::new(Body::from(e.to_string())),
            }
        }

        // Return the `404 Not Found` for any other routes.
        _ => {
            let mut not_found = Response::new(Body::from("404 Not Found"));
            *not_found.status_mut() = StatusCode::NOT_FOUND;
            not_found
        }
    }
}

// Main Hyper HTTP server function that runs it and blocks waiting on it forever.
#[tokio::main]
async fn serve(state: Arc<RwLock<ComputeState>>) {
    let addr = SocketAddr::from(([0, 0, 0, 0], 3080));

    let make_service = make_service_fn(move |_conn| {
        let state = state.clone();
        async move {
            Ok::<_, Infallible>(service_fn(move |req: Request<Body>| {
                let state = state.clone();
                async move { Ok::<_, Infallible>(routes(req, state).await) }
            }))
        }
    });

    info!("starting HTTP server on {}", addr);

    let server = Server::bind(&addr).serve(make_service);

    // Run this server forever
    if let Err(e) = server.await {
        error!("server error: {}", e);
    }
}

/// Launch a separate Hyper HTTP API server thread and return its `JoinHandle`.
pub fn launch_http_server(state: &Arc<RwLock<ComputeState>>) -> Result<thread::JoinHandle<()>> {
    let state = Arc::clone(state);

    Ok(thread::Builder::new()
        .name("http-endpoint".into())
        .spawn(move || serve(state))?)
}

use bson::{from_bson, Bson};
use bson::oid::ObjectId;
use mongodb::{self, ThreadedClient};
use mongodb::db::{Database, ThreadedDatabase};
use na::{DMatrix, DVector};
use serde_enum;
use std::error;
use std::fmt::{self, Display, Formatter};

use db::{self, Weighting};
use cfg;
use model::Metric;

#[derive(Serialize, Deserialize)]
pub struct SampleWeight {
    pub name: String,
    pub weight: f32,
}

#[derive(Debug)]
struct SampleSet {
    num: usize,
    ids: Vec<ObjectId>,
}

#[derive(Debug)]
pub enum Error {
    MissingWeights,
}

impl Display for Error {
    fn fmt(&self, f: &mut Formatter) -> Result<(), fmt::Error> {
        write!(f, "{}", error::Error::description(self))
    }
}

impl error::Error for Error {
    fn description(&self) -> &str {
        match *self {
            Error::MissingWeights => "missing weights",
        }
    }
}

pub fn calculate_sample_weights(
    task: &str,
    token: &str,
    metric: &Metric,
    db_client: &mongodb::Client,
) -> Result<Vec<SampleWeight>, Error> {
    let db = db_client.db(db::NAME);

    let sample_set = get_sample_set(task, &db);
    let mut weight_matrix = make_weight_matrix(token, metric, &sample_set, &db)?;
    normalize_weight_matrix(&mut weight_matrix, sample_set.num);
    let criteria_weights = calculate_criteria_weights(&weight_matrix, sample_set.num);

    Ok(make_sample_weights(&criteria_weights, &sample_set.ids))
}

pub fn print_stats(task: &str, token: &str, metric: &Metric, cfg: &cfg::Db) -> Result<(), Error> {
    let db_client = db::connect(cfg);
    let db = db_client.db(db::NAME);

    let sample_set = get_sample_set(task, &db);
    println!("N: {}", sample_set.num);

    let mut weight_matrix = make_weight_matrix(token, metric, &sample_set, &db)?;
    println!("Weight matrix: {}", weight_matrix);

    normalize_weight_matrix(&mut weight_matrix, sample_set.num);
    println!("Normalized weight matrix: {}", weight_matrix);

    let criteria_weights = calculate_criteria_weights(&weight_matrix, sample_set.num);
    println!("Criteria weights: {}", criteria_weights);

    let sample_weights = make_sample_weights(&criteria_weights, &sample_set.ids);
    for &SampleWeight { ref name, weight } in &sample_weights {
        println!("{} <= {}", name, weight);
    }

    Ok(())
}

fn get_sample_set(task: &str, db: &Database) -> SampleSet {
    let sample_docs: Vec<_> = db.collection(db::COLLECTION_SAMPLE)
        .find(Some(doc!{ "task": task }), None)
        .unwrap()
        .collect::<Result<_, _>>()
        .unwrap();
    let ids: Vec<ObjectId> = sample_docs
        .into_iter()
        .map(|doc| {
            doc.get_object_id("_id")
                .expect("Failed deserializing documents")
                .clone()
        })
        .collect();
    let num = ids.len();

    SampleSet { num: num, ids: ids }
}

fn make_weight_matrix(
    token: &str,
    metric: &Metric,
    sample_set: &SampleSet,
    db: &Database,
) -> Result<DMatrix<f32>, Error> {
    let SampleSet { num, ref ids, .. } = *sample_set;

    let metric_str = serde_enum::to_string(&metric).unwrap();

    let mut weight_matrix = DMatrix::<f32>::identity(num, num);
    for col in 0..num {
        for row in (col + 1)..num {
            let a = &ids[col];
            let b = &ids[row];

            let doc = db.collection(db::COLLECTION_WEIGHT)
                .find_one(
                    Some(doc! {
                        "token": token,
                        "metric": &metric_str,
                        "a": a.clone(),
                        "b": b.clone(),
                    }),
                    None,
                )
                .expect("Failed quering DB");

            if let Some(doc) = doc {
                // Weight was found in column major order.
                let weight: Weighting =
                    from_bson(Bson::from(doc)).expect("Failed deserializing weight");
                weight_matrix
                    .columns_mut(col, 1)
                    .rows_mut(row, 1)
                    .fill(weight.weight);
                weight_matrix
                    .columns_mut(row, 1)
                    .rows_mut(col, 1)
                    .fill(1.0 / weight.weight);
            } else {
                // Alternatively weight is in row major order.
                let doc = db.collection(db::COLLECTION_WEIGHT)
                    .find_one(
                        Some(doc! {
                            "token": token,
                            "metric": &metric_str,
                            "a": b.clone(),
                            "b": a.clone(),
                        }),
                        None,
                    )
                    .expect("Failed quering DB");

                if let Some(doc) = doc {
                    let weight: Weighting =
                        from_bson(Bson::from(doc)).expect("Failed deserializing weight");
                    weight_matrix
                        .columns_mut(col, 1)
                        .rows_mut(row, 1)
                        .fill(1.0 / weight.weight);
                    weight_matrix
                        .columns_mut(row, 1)
                        .rows_mut(col, 1)
                        .fill(weight.weight);
                } else {
                    return Err(Error::MissingWeights);
                }
            }
        }
    }

    Ok(weight_matrix)
}

fn normalize_weight_matrix(weight_matrix: &mut DMatrix<f32>, num: usize) {
    // Normalize on columns
    for col in 0..num {
        let sum: f32 = weight_matrix.columns(col, 1).iter().sum();
        let normalization = 1.0 / sum;
        for weight in weight_matrix.columns_mut(col, 1).iter_mut() {
            *weight *= normalization;
        }
    }
}

fn calculate_criteria_weights(weight_matrix: &DMatrix<f32>, num: usize) -> DVector<f32> {
    // Calculate mean of each row
    DVector::<f32>::from_iterator(
        num,
        (0..num).map(|row| {
            weight_matrix.rows(row, 1).iter().sum::<f32>() / num as f32
        }),
    )
}

fn make_sample_weights(criteria_weights: &DVector<f32>, ids: &[ObjectId]) -> Vec<SampleWeight> {
    let mut sample_weights: Vec<_> = criteria_weights
        .iter()
        .enumerate()
        .map(|(i, w)| {
            SampleWeight {
                name: ids[i].to_hex(),
                weight: *w,
            }
        })
        .collect();
    sample_weights.sort_by(|a, b| b.weight.partial_cmp(&a.weight).unwrap());
    sample_weights
}

//! The yksom run-time. The run-time uses trait objects but stores them as thin pointers (using the
//! experimental [natrob library](https://github.com/softdevteam/natrob). This allows integer
//! tagging to be used. The [`Val`](vm::val::Val) struct stores tagged integers / pointers to boxed
//! objects. The [`Obj`](vm::objects::Obj) trait is the "supertype" trait of all objects, but it is
//! not intended that most parts of the VM call [`Obj`](vm::objects::Obj) directly: one should use
//! the identically named methods on [`Val`](vm::val::Val). As this suggests, users should, in most
//! cases, either operate directly on a [`Val`](vm::val::Val) or
//! [`Val::downcast`](vm::val::Val::downcast) (or
//! [`Val::try_downcast`](vm::val::Val::try_downcast)) it to a concrete implementation of `Obj`.

pub mod core;
