    let mut replicate_args: Vec<&str> = Vec::with_capacity(3 + delayed_command.len()); // key + ts + id + [command]
    replicate_args.push(&schedule_key);
    replicate_args.push(&timestamp_str);
    replicate_args.push(&task_id);
    replicate_args.extend(delayed_command.iter().map(|x| x.as_str()));
    ctx.replicate("SCHEDULE.REPLICATE", &replicate_args);

    open_key_and_update_timer(&ctx, schedule_key, None);

    Ok(task_id)
}

///
/// SCHEDULE.REPLICATE key task_id timestamp CMD...
///
pub fn replicate(ctx: &Context, args: Vec<String>) -> RedisResult {
    ctx.log_notice(format!("{:?}", args).as_str());

    let mut args = args.into_iter().skip(1);
    let schedule_key = args.next_string()?;
    let timestamp = args.next_u64()?;
    let task_id = args.next_string()?;
    let delayed_command: Vec<String> = args.collect();

    let command_keys = ctx.get_command_keys(&delayed_command)?;
    if ctx.is_keys_position_request() {
        let offset = 4; // (0)SCHEDULE.REPLICATE (1)KEY (2)task_id (3)DELAY [CMD] ==
        ctx.key_at_pos(1);
        for key_pos in command_keys {
            ctx.key_at_pos(offset + key_pos);
        }
        return Ok(RedisValue::NoReply);
    }

    let task_id =
        add_task_helper_to_schedule(ctx, schedule_key, timestamp, delayed_command, Some(task_id))?;
    Ok(RedisValue::BulkString(task_id))
}

///
/// SCHEDULE.ADD key delay CMD...
///
pub fn add(ctx: &Context, args: Vec<String>) -> RedisResult {
    ctx.log_notice(format!("{:?}", args).as_str());
    let now = SystemTime::now().duration_since(UNIX_EPOCH)?;

    let mut args = args.into_iter().skip(1);
    let schedule_key = args.next_string()?;
    let delay = args.next_u64()?;
    let timestamp = now.as_secs() + delay;
    let delayed_command: Vec<String> = args.collect();

    let command_keys = ctx.get_command_keys(&delayed_command)?;
    if ctx.is_keys_position_request() {
        let offset = 3; // (0)SCHEDULE.ADD (1)KEY (2)DELAY [CMD] ==
        ctx.key_at_pos(1);
        for key_pos in command_keys {
            ctx.key_at_pos(offset + key_pos);
        }
        return Ok(RedisValue::NoReply);
    }

    let task_id = add_task_helper_to_schedule(ctx, schedule_key, timestamp, delayed_command, None)?;
    Ok(RedisValue::BulkString(task_id))
}

///
/// SCHEDULE.REM key task-id
///
pub fn rem(ctx: &Context, args: Vec<String>) -> RedisResult {
    ctx.log_notice(format!("{:?}", args).as_str());

    let mut args = args.into_iter().skip(1);
    let key = args.next_string()?;
    let task_id = args.next_string()?;
    let key = ctx.open_key_writable(&key);

    match key.get_value::<ScheduleDataType>(&SCHEDULE_DATA_TYPE)? {
        Some(value) => {
            value.del_task(task_id);
            ctx.replicate_verbatim();
            Ok(RedisValue::Null)
        }
        None => Ok(RedisValue::Null),
    }
}

///
/// Helper function to execute task from a schedule,
///
/// This function will propagate two items into the AOF:
///     1. SCHEDULE.REM (remove this task from the schedule)
///     2. [COMMAND] (the command this task executed)
///
/// Important: This function will not create/update timers, this
/// is something that must be handled by the caller
///
fn execute_schedule_task(ctx: &Context, schedule_key: String, task_id: String) -> RedisResult {
    let key = ctx.open_key_writable(&schedule_key);

    if let Some(value) = key.get_value::<ScheduleDataType>(&SCHEDULE_DATA_TYPE)? {
        let task = value.del_task(task_id.clone());
        if let Some(task) = task {
            exec_task(ctx, &task.args).map_err(|error| {
                let msg = format!(
                    "Failed to execute task (key={}, id={}, task={:?}); Error={:#?}",
                    schedule_key, task_id, task, error
                );
                ctx.log_warning(&msg);
                error
            })?;

            let mut args_iter = task.args.iter();
            let cmd = args_iter.next().unwrap().as_str();
            let args: Vec<&str> = args_iter.map(|x| x.as_str()).collect();
            ctx.replicate("SCHEDULE.REM", &[&schedule_key, &task_id]);
            ctx.replicate(cmd, &args);
        }
        Ok(RedisValue::Null)
    } else {
        Ok(RedisValue::Null)
    }
}

///
/// SCHEDULE.EXEC key task-id
///
pub fn exec(ctx: &Context, args: Vec<String>) -> RedisResult {
    ctx.log_notice(format!("{:?}", args).as_str());

    let mut args = args.iter().skip(1);
    let schedule_key = args.next_string()?;
    let task_id = args.next_string()?;

    execute_schedule_task(ctx, schedule_key.clone(), task_id)?;
    open_key_and_update_timer(&ctx, schedule_key, None);

    Ok(RedisValue::Null)
}

///
/// SCHEDULE.EXECDUE key timestamp
///
pub fn exec_due(ctx: &Context, args: Vec<String>) -> RedisResult {
    ctx.log_notice(format!("{:?}", args).as_str());

    let mut args = args.iter().skip(1);
    let schedule_key = args.next_string()?;
    let timestamp = args.next_u64()?;

    let key = ctx.open_key(&schedule_key); // Open as read, SCHEDULE.EXEC will open to write
    let value = key.get_value::<ScheduleDataType>(&SCHEDULE_DATA_TYPE);
    if let Ok(Some(value)) = value {
        for (task_timestamp, task_id) in value.timetable_iter() {
            if *task_timestamp > timestamp {
                break;
            }
            execute_schedule_task(ctx, schedule_key.clone(), task_id.to_string())?;
        }
    }

    open_key_and_update_timer(&ctx, schedule_key, None);
    Ok(RedisValue::Null)
}

///
/// SCHEDULE.SCAN key
///
pub fn scan(ctx: &Context, args: Vec<String>) -> RedisResult {
    let mut args = args.into_iter().skip(1);
    let key = args.next_string()?;
    let key = ctx.open_key(&key);

    match key.get_value::<ScheduleDataType>(&SCHEDULE_DATA_TYPE)? {
        Some(value) => {
            let ret: Vec<RedisValue> = value
                .to_vec()
                .drain(..)
                .map(|(timestamp, task_id, args)| {
                    RedisValue::Array(vec![
                        RedisValue::from(timestamp.to_string()),
                        RedisValue::from(task_id),
                        RedisValue::from(args),
                    ])
                })
                .collect();
            Ok(RedisValue::Array(ret))
        }
        None => Ok(RedisValue::Null),
    }
}

///
/// SCHEDULE.INCRBY KEY TASK-ID SECONDS
///
pub fn incrby(ctx: &Context, args: Vec<String>) -> RedisResult {
    ctx.log_notice(format!("{:?}", args).as_str());
    let now = SystemTime::now().duration_since(UNIX_EPOCH)?;

    let mut args = args.into_iter().skip(1);
    let schedule_key = args.next_string()?;
    let task_id = args.next_string()?;
    let inc_size = args.next_u64()?;
    let key = ctx.open_key_writable(&schedule_key);

    match key.get_value::<ScheduleDataType>(&SCHEDULE_DATA_TYPE)? {
        Some(value) => {
            let new_timestamp = value.incr(task_id, inc_size);
            ctx.replicate_verbatim();
            match new_timestamp {
                Some(new_timestamp) => {
                    update_timer(&ctx, schedule_key, value, now);
                    Ok(RedisValue::BulkString(new_timestamp.to_string()))
                }
                _ => Ok(RedisValue::Null),
            }
        }
        None => Ok(RedisValue::Null),
    }
}

///
/// SCHEDULE.DECRBY KEY TASK-ID SECONDS
///
pub fn decrby(ctx: &Context, args: Vec<String>) -> RedisResult {
    ctx.log_notice(format!("{:?}", args).as_str());
    let now = SystemTime::now().duration_since(UNIX_EPOCH)?;

    let mut args = args.into_iter().skip(1);
    let schedule_key = args.next_string()?;
    let task_id = args.next_string()?;
    let inc_size = args.next_u64()?;
    let key = ctx.open_key_writable(&schedule_key);

    match key.get_value::<ScheduleDataType>(&SCHEDULE_DATA_TYPE)? {
        Some(value) => {
            let new_timestamp = value.decr(task_id, inc_size);
            ctx.replicate_verbatim();
            match new_timestamp {
                Some(new_timestamp) => {
                    update_timer(&ctx, schedule_key, value, now);
                    Ok(RedisValue::BulkString(new_timestamp.to_string()))
                }
                _ => Ok(RedisValue::Null),
            }
        }
        None => Ok(RedisValue::Null),
    }
}

use crate::draughts::moves::{Capture, Move};
use crate::draughts::rules::VALUE_CAPTURE;
use crate::draughts::Square::*;
use crate::draughts::{Board, PastMove, Square};
use crate::system::Player;
use crate::tree::Leaf;

pub(super) fn calc_valid_moves<F>(board: &Board, origin: usize, moves_for_square: F) -> Vec<Move>
where
    F: Fn(&Board, usize, bool) -> Vec<Move>,
{
    debug_log_start!("Calculating valid moves for {}", origin);
    if board[origin] == Square::Empty {
        debug_log_end!("Board square empty");
        return vec![];
    }

    let mut first_leaf = create_move_tree(board, origin, &moves_for_square);
    let mut move_lists = vec![];
    first_leaf.print(0, "");
    loop {
        let move_list = first_leaf.list();
        debug_log!("Pruned and got {:?}", move_list);
        if !move_list.is_empty() {
            move_lists.push(move_list);
        }
        if first_leaf.prune() {
            break;
        }
    }
    if move_lists.is_empty() {
        debug_log_end!("No moves found");
        return vec![];
    }
    let longest = move_lists.iter().map(|list| list.len()).max().unwrap();
    debug_log!(
        "Found {} potential moves, longest: {}",
        move_lists.len(),
        longest
    );
    move_lists = move_lists
        .into_iter()
        .filter(|list| list.len() == longest)
        .collect();

    if longest > 1 {
        debug_log_end!("Found {} multijumps", move_lists.len());
        move_lists
            .into_iter()
            .map(|list| {
                let mut captures: Vec<Capture> = list
                    .iter()
                    .map(|mov| {
                        if let Move::Jump {
                            origin: _,
                            capture,
                            value: _,
                        } = mov
                        {
                            capture
                        } else {
                            panic!("Invalid move");
                        }
                    })
                    .cloned()
                    .collect();
                captures.reverse();
                let value = captures.len() * VALUE_CAPTURE;
                Move::MultiJump {
                    origin,
                    captures,
                    value,
                }
            })
            .collect()
    } else {
        debug_log_end!("Found {} steps/jumps", move_lists.len());
        move_lists
            .into_iter()
            .map(|mut list| list.remove(0))
            .collect()
    }
}

pub(super) fn create_move_tree<F>(board: &Board, origin: usize, moves_for_square: &F) -> Leaf<Move>
where
    F: Fn(&Board, usize, bool) -> Vec<Move>,
{
    debug_log!("Creating move tree from {}", origin);
    let mut first_leaf = make_leaf(board, origin, false, moves_for_square);
    let any_captures = first_leaf.contents.iter().any(|(mov, _)| mov.is_jump());
    if any_captures {
        debug_log!("At least one capture found");
        first_leaf.contents = first_leaf
            .contents
            .into_iter()
            .filter(|(mov, _)| mov.is_jump())
            .collect();
        debug_log!(
            "{} moves remaining after filtering",
            first_leaf.contents.len()
        );
    }
    first_leaf
}

pub(super) fn make_leaf<F>(
    board: &Board,
    origin: usize,
    capture_only: bool,
    moves_for_square: &F,
) -> Leaf<Move>
where
    F: Fn(&Board, usize, bool) -> Vec<Move>,
{
    debug_log!(
        "Creating leaf from {}, capture_only: {}",
        origin,
        capture_only
    );
    let potential_moves = moves_for_square(board, origin, capture_only);
    debug_log!("Found potential {} moves", potential_moves.len());
    let moves: Vec<(Move, Option<Leaf<Move>>)> = potential_moves
        .iter()
        .map(|mov| {
            let leaf = match mov {
                Move::Step { .. } => None,
                Move::Jump {
                    origin: _,
                    capture,
                    value: _,
                } => {
                    let mut new_board = board.clone();
                    new_board[capture.capturing] = Square::Empty;
                    let piece = new_board[origin];
                    new_board[origin] = Square::Empty;
                    new_board[capture.dest] = piece;
                    Some(make_leaf(&new_board, capture.dest, true, moves_for_square))
                }
                Move::MultiJump { .. } => panic!("Invalid move found at {}", origin),
            };
            (mov.clone(), leaf)
        })
        .collect();
    debug_log!(
        "Result: {} moves with {} leaves",
        moves.len(),
        moves.iter().filter(|pair| pair.1.is_some()).count()
    );
    Leaf::new(moves)
}

pub(super) fn check_moves<F>(move_history: &[PastMove], count: usize, predicate: F) -> bool
where
    F: Fn(&PastMove) -> bool,
{
    if move_history.len() >= count {
        move_history.iter().rev().take(count).all(predicate)
    } else {
        false
    }
}

pub(super) fn get_man_count(board: &Board, player: Player) -> usize {
    let piece = match player {
        Player::Human => HumanMan,
        Player::Computer => ComputerMan,
    };
    get_count(board, piece)
}

pub(super) fn get_king_count(board: &Board, player: Player) -> usize {
    let piece = match player {
        Player::Human => HumanKing,
        Player::Computer => ComputerKing,
    };
    get_count(board, piece)
}

pub(super) fn get_piece_count(board: &Board, player: Player) -> usize {
    get_man_count(board, player) + get_king_count(board, player)
}

fn get_count(board: &Board, piece: Square) -> usize {
    board.iter().filter(|&square| square == &piece).count()
}

/*!
# GMT mount control model

A unified Actor client for both the mount controller and the mount drive models from the [mount-ctrl] crate.

The [Mount] client is enabled with the `mount-ctrl` feature.

# Example

Mount actor:
```
use dos_actors::clients::mount::Mount;
use dos_actors::prelude::*;
let mut mount: Actor<_> = Mount::new().into();

```

[mount-ctrl]: https://docs.rs/mount-ctrl
*/

use crate::{
    io::{Data, Read, Write},
    Update,
};
use mount_ctrl::controller;
use mount_ctrl::drives;
use std::{ptr, sync::Arc};

pub struct Mount<'a> {
    drive: drives::Controller<'a>,
    control: controller::Controller<'a>,
}
impl<'a> Mount<'a> {
    pub fn new() -> Self {
        Self {
            drive: drives::Controller::new(),
            control: controller::Controller::new(),
        }
    }
}

pub enum MountEncoders {}
impl<'a> Read<Vec<f64>, MountEncoders> for Mount<'a> {
    fn read(&mut self, data: Arc<Data<Vec<f64>, MountEncoders>>) {
        if let controller::U::MountFB(val) = &mut self.control.mount_fb {
            assert_eq!(
                data.len(),
                val.len(),
                "data size ({}) do not match MountFb size ({})",
                data.len(),
                val.len()
            );
            unsafe { ptr::copy_nonoverlapping((**data).as_ptr(), val.as_mut_ptr(), val.len()) }
        }
        if let drives::U::Mountpos(val) = &mut self.drive.mount_pos {
            assert_eq!(
                data.len(),
                val.len(),
                "data size ({}) do not match Mountpos size ({})",
                data.len(),
                val.len()
            );
            unsafe { ptr::copy_nonoverlapping((**data).as_ptr(), val.as_mut_ptr(), val.len()) }
        }
    }
}
pub enum MountSetPoint {}
impl<'a> Read<Vec<f64>, MountSetPoint> for Mount<'a> {
    fn read(&mut self, data: Arc<Data<Vec<f64>, MountSetPoint>>) {
        if let controller::U::MountSP(val) = &mut self.control.mount_sp {
            assert_eq!(
                data.len(),
                val.len(),
                "data size ({}) do not match MountFb size ({})",
                data.len(),
                val.len()
            );
            unsafe { ptr::copy_nonoverlapping((**data).as_ptr(), val.as_mut_ptr(), val.len()) }
        }
    }
}
impl<'a> Update for Mount<'a> {
    fn update(&mut self) {
        self.control.next();
        if let (controller::Y::Mountcmd(src), drives::U::Mountcmd(dst)) =
            (&self.control.mount_cmd, &mut self.drive.mount_cmd)
        {
            assert_eq!(
                src.len(),
                dst.len(),
                "control.mount_cmd size ({}) do not match drive.mount_cmd size ({})",
                src.len(),
                dst.len()
            );
            unsafe { ptr::copy_nonoverlapping(src.as_ptr(), dst.as_mut_ptr(), dst.len()) }
        }
        self.drive.next();
    }
}
pub enum MountTorques {}
impl<'a> Write<Vec<f64>, MountTorques> for Mount<'a> {
    fn write(&mut self) -> Option<Arc<Data<Vec<f64>, MountTorques>>> {
        let drives::Y::MountT(val) = &self.drive.mount_t;
        let mut data = vec![0f64; val.len()];
        unsafe { ptr::copy_nonoverlapping(val.as_ptr(), data.as_mut_ptr(), data.len()) }
        Some(Arc::new(Data::new(data)))
    }
}

use super::privkey::Privkey;
use super::pubkey::Pubkey;
use super::SECP256K1;
use rand::{self, Rng, SeedableRng};
use secp256k1::{PublicKey, SecretKey};

/// A random secp keypair generator
pub struct Generator {
    rng: Box<dyn rand::RngCore>,
}

impl Default for Generator {
    fn default() -> Self {
        Self::new()
    }
}

impl Generator {
    /// Create a new Generator
    ///
    /// Default random number generator is `rand::rngs::ThreadRng`
    pub fn new() -> Self {
        let rng = rand::thread_rng();
        Generator { rng: Box::new(rng) }
    }

    /// Non crypto safe prng, should only used in tests
    pub fn non_crypto_safe_prng(seed: u64) -> Self {
        let rng = rand::rngs::SmallRng::seed_from_u64(seed);
        Generator { rng: Box::new(rng) }
    }

    /// Generate a SecretKey
    fn gen_secret_key(&mut self) -> SecretKey {
        let mut seed = vec![0; 32];
        loop {
            self.rng.fill(seed.as_mut_slice());
            if let Ok(key) = SecretKey::from_slice(&seed) {
                return key;
            }
        }
    }

    /// Generate a Privkey
    pub fn gen_privkey(&mut self) -> Privkey {
        self.gen_secret_key().into()
    }

    /// Generate a keypair
    pub fn gen_keypair(&mut self) -> (Privkey, Pubkey) {
        let secret_key = self.gen_secret_key();
        let pubkey = PublicKey::from_secret_key(&*SECP256K1, &secret_key);

        (secret_key.into(), pubkey.into())
    }

    /// Shortcuts construct temporary Generator, and generate a Privkey
    pub fn random_privkey() -> Privkey {
        Generator::new().gen_privkey()
    }

    /// Shortcuts construct temporary Generator, and generate a keypair
    pub fn random_keypair() -> (Privkey, Pubkey) {
        Generator::new().gen_keypair()
    }

    /// Shortcuts construct temporary Generator, and generate a SecretKey
    pub fn random_secret_key() -> SecretKey {
        Generator::new().gen_secret_key()
    }
}

#![allow(dead_code)]
pub struct Solution;

impl Solution {
    pub fn magical_string(n: i32) -> i32 {
        if n <= 3 {
            return 1;
        }
        let n = n as usize;
        let mut f = vec![0; n];
        f[0] = 1;
        f[1] = 2;
        f[2] = 2;
        let mut i = 3;
        let mut j = 2;
        while i < n {
            f[i] = f[i - 1] ^ 3;
            if i + 1 < n && f[j] == 2 {
                f[i + 1] = f[i];
                i += 1;
            }
            i += 1;
            j += 1;
        }
        f.into_iter().filter(|&x| x == 1).count() as i32
    }
}

#[cfg(test)]
mod tests {
