    #[test]
    fn test_magical_string() {
        assert_eq!(Solution::magical_string(6), 3);
        assert_eq!(Solution::magical_string(1), 1);
    }
}

use std::collections::{HashMap, VecDeque};

type OpFn = fn(VecDeque<String>) -> String;

fn inc(args:VecDeque<String>) -> String {
    println!("args {:?}",args);
    let iargs:Vec<i32> = args.iter().map(|s| s.parse().unwrap()).collect();
    "(".to_string() + &iargs.iter().map(|x| (x+1).to_string() ).
        collect::<Vec<String>>().join(",") + ")"
}

fn plus(args:VecDeque<String>) -> String {
    println!("args {:?}",args);
    let iargs:Vec<i32> = args.iter().map(|s| s.parse().unwrap()).collect();
    iargs.iter().fold(0,|acc,&x|acc+x).to_string()
}

fn minus(args:VecDeque<String>) -> String {
    let mut iargs:Vec<i32> = args.iter().map(|s| s.parse().unwrap()).collect();
    let first = iargs.pop().unwrap();
    iargs.iter().fold(first,|acc,&x|acc-x).to_string()
}

fn multiply(args:VecDeque<String>) -> String {
    let iargs:Vec<i32> = args.iter().map(|s| s.parse().unwrap()).collect();
    iargs.iter().fold(1,|acc,&x|acc*x).to_string()
}

fn tokenize(lisp_code:&String) -> Vec<&str> {
    lisp_code.split_whitespace().collect()
}

fn evaluate(code:String,ops:HashMap<String,OpFn>) -> String {
    let tokens = tokenize(&code);
    println!("tokens {:?}",tokens);

    let mut stack:Vec<String> = Vec::new();
    for token_ref in tokens{
        let token = token_ref.to_string();

        if token == "("{
            // do nothing by design
        }else if token==")"{
            let mut queue:VecDeque<String> = VecDeque::new();
            loop{
                let t = match stack.pop(){
                    None => break,
                    Some(t) => t
                };
                queue.push_front(t.clone());
                if ops.contains_key(&t){
                    break;
                }
            }
            let op = queue.pop_front().unwrap();
            let result = ops.get(&op).unwrap()(queue);
            println!("sub_eval result is == {:?}",result);
            stack.push(result);
        } else{
            stack.push(token);
        }
    }

    assert!(stack.len()==1);
    stack.pop().unwrap()
}

fn ops() -> HashMap<String,OpFn>{
    let mut ops:HashMap<String,OpFn> = HashMap::new();
    ops.insert(String::from("+"),plus);
    ops.insert(String::from("-"),minus);
    ops.insert(String::from("*"),multiply);
    ops.insert(String::from("inc"),inc);
    ops
}

fn main() {
    let lisp_code = "( + 1 2 ( + 3 4 ) )".to_string();
    let result = evaluate(lisp_code.to_string(),ops());
    println!("{} == {:?}", &lisp_code, result);
}

#[test]
fn evaluate_test(){
    assert_eq!(evaluate("( + 1 2 ( + 3 4 ) )".to_string(),ops()),"10");
}

#[test]
fn plus_test(){
    assert_eq!(plus(VecDeque::from(vec!["1".to_string(),"2".to_string(),"3".to_string()])),"6");
}

#[test]
fn minus_test(){
    assert_eq!(minus(VecDeque::from(vec!["4".to_string(),"10".to_string()])),"6");
}

#[test]
fn multiply_test(){
    assert_eq!(multiply(VecDeque::from(vec!["6".to_string(),"10".to_string()])),"60");
}

#[test]
fn inc_test(){
    assert_eq!(inc(VecDeque::from(vec!["1".to_string(),"2".to_string(),"3".to_string()])),"(2,3,4)");
    assert_eq!(inc(VecDeque::from(vec!["1".to_string()])),"(2)");
    assert_eq!(evaluate("( inc 2 3 )".to_string(),ops()),"(3,4)");
}

use std::sync::mpsc::Receiver;
use std::sync::Mutex;
use std::time::{SystemTime, Duration};
use crate::concentrator;

use libconcentratord::signals::Signal;
use libloragw_sx1301::{hal, reg, wrapper};

lazy_static! {
    static ref PREV_CONCENTRATOR_COUNT: Mutex<u32> = Mutex::new(hal::get_trigcnt().unwrap());
    static ref PREV_UNIX_TIME: Mutex<Duration> = Mutex::new(
        SystemTime::now()
            .duration_since(SystemTime::UNIX_EPOCH)
            .unwrap()
    );
}

pub fn timesync_loop(stop_receive: Receiver<Signal>) {
    debug!("Starting timesync loop");

    loop {
        // The timesync is in a separate function to make sure that the
        // mutex guard is dereferenced as soon as the function returns.
        timesync();

        // Instead of a 60s sleep, we receive from the stop channel with a
        // timeout of 60 seconds.
        match stop_receive.recv_timeout(Duration::from_secs(60)) {
            Ok(v) => {
                debug!("Received stop signal, signal: {}", v);
                break;
            }
            _ => {}
        };
    }

    debug!("Timesync loop ended");
}

pub fn get_concentrator_count() -> u32 {
    let prev_concentrator_count = PREV_CONCENTRATOR_COUNT.lock().unwrap();
    let prev_unix_time = PREV_UNIX_TIME.lock().unwrap();

    let unix_diff = SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .unwrap()
        - *prev_unix_time;

    return prev_concentrator_count.wrapping_add(unix_diff.as_micros() as u32);
}

fn timesync() {
    debug!("Disabling GPS mode for concentrator counter");
    reg::reg_w(wrapper::LGW_GPS_EN, 0).unwrap();

    let mut prev_concentrator_count = PREV_CONCENTRATOR_COUNT.lock().unwrap();
    let mut prev_unix_time = PREV_UNIX_TIME.lock().unwrap();

    let concentrator_count = hal::get_trigcnt().unwrap();
    let unix_time = SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .unwrap();

    let unix_time_diff = unix_time - *prev_unix_time;
    let concentrator_diff = {
        let diff: i64;

        if concentrator_count > *prev_concentrator_count {
            diff = (concentrator_count - *prev_concentrator_count) as i64;
        } else {
            diff =
                (concentrator_count as i64) + ((1 << 32) - 1) - (*prev_concentrator_count as i64);
        }

        diff
    };

    let drift = (unix_time_diff.as_micros() as i64) - concentrator_diff;

    *prev_unix_time = unix_time;
    *prev_concentrator_count = concentrator_count;

    concentrator::timestamp::update_counter(concentrator_count);

    debug!("Current concentrator count_us: {}", concentrator_count);
    debug!("Concentrator drift, drift_us: {}", drift);

    debug!("Enabling GPS mode for concentrator counter");
    reg::reg_w(wrapper::LGW_GPS_EN, 1).unwrap();
}

use futures_lite::Stream;
use hyper::Client;
use tokio::sync::mpsc;

use crate::{errors::Error, streams::twitter_stream::TwitterStream, types::*};

pub struct SampledStream {
    tweet_stream: mpsc::Receiver<Tweet>,
    exit_notifier: mpsc::Sender<()>,
}

impl SampledStream {
    pub async fn new(token: &str, parameters: StreamParameters) -> Result<Self, Error> {
        Self::with_buffer_size(token, parameters, 64).await
    }

    pub async fn with_buffer_size(
        token: &str,
        parameters: StreamParameters,
        buffer_size: usize,
    ) -> Result<Self, Error> {
        let client = Client::new();

        let token = if token.starts_with("Bearer ") {
            token.to_owned()
        } else {
            format!("Bearer {}", token)
        };

        let (tweet_stream, exit_notifier) = TwitterStream::create(
            "/2/tweets/sample/stream",
            token,
            client,
            parameters,
            buffer_size,
        )
        .await?;

        Ok(Self {
            tweet_stream,
            exit_notifier,
        })
    }
}

impl Stream for SampledStream {
    type Item = Tweet;

    fn poll_next(
        mut self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
    ) -> std::task::Poll<Option<Self::Item>> {
        self.tweet_stream.poll_recv(cx)
    }
}

impl AsRef<mpsc::Receiver<Tweet>> for SampledStream {
    fn as_ref(&self) -> &mpsc::Receiver<Tweet> {
        &self.tweet_stream
    }
}

impl AsMut<mpsc::Receiver<Tweet>> for SampledStream {
    fn as_mut(&mut self) -> &mut mpsc::Receiver<Tweet> {
        &mut self.tweet_stream
    }
}

impl Drop for SampledStream {
    fn drop(&mut self) {
        let _ = self.exit_notifier.send(());
    }
}

