    let result = fut.await;
    match result.kind {
        Ok(success) => {
            let server_allocated: Arc<ServerAllocResult> =
                success.lookup_output("server_reserve")?;
            Ok(server_allocated.server_id)
        }
        Err(failure) => Err(failure.error_source),
    }
