use std::{path::Path, time::Duration};

use crate::{
    dut_definition::{DefinitionSource, DutDefinition},
    tests::{
        stepping::test_stepping, test_flashing, test_hw_breakpoints, test_memory_access,
        test_register_access,
    },
};
use anyhow::{bail, Context, Result};

use clap::{App, Arg};

mod dut_definition;
mod tests;

fn main() -> Result<()> {
    pretty_env_logger::init();

    let app = App::new("smoke tester")
        .arg(
            Arg::with_name("dut_definitions")
                .long("dut-definitions")
                .value_name("DIRECTORY")
                .takes_value(true)
                .conflicts_with_all(&["chip", "probe", "single_dut"])
                .required(true),
        )
        .arg(
            Arg::with_name("chip")
                .long("chip")
                .takes_value(true)
                .value_name("CHIP")
                .conflicts_with_all(&["dut_definitions", "single_dut"])
                .required(true),
        )
        .arg(
            Arg::with_name("probe")
                .long("probe")
                .takes_value(true)
                .value_name("PROBE")
                .required(false),
        )
        .arg(
            Arg::with_name("single_dut")
                .long("single-dut")
                .value_name("FILE")
                .takes_value(true)
                .required(true)
                .conflicts_with_all(&["chip", "dut_definitions"]),
        );

    let matches = app.get_matches();

    let definitions = if let Some(dut_definitions) = matches.value_of("dut_definitions") {
        let definitions = DutDefinition::collect(dut_definitions)?;
        println!("Found {} target definitions.", definitions.len());
        definitions
    } else if let Some(single_dut) = matches.value_of("single_dut") {
        vec![DutDefinition::from_file(Path::new(single_dut))?]
    } else {
        // Chip needs to be specified
        let chip = matches.value_of("chip").unwrap(); // If dut-definitions is not present, chip must be present

        if let Some(probe) = matches.value_of("probe") {
            vec![DutDefinition::new(chip, probe)?]
        } else {
            vec![DutDefinition::autodetect_probe(chip)?]
        }
    };

    let num_duts = definitions.len();

    let mut tests_ok = true;

    for (i, definition) in definitions.iter().enumerate() {
        print!("DUT [{}/{}] - Starting test", i + 1, num_duts,);

        if let DefinitionSource::File(path) = &definition.source {
            print!(" - {}", path.display());
        }

        println!();

        match handle_dut(definition) {
            Ok(()) => {
                println!("DUT [{}/{}] - Tests Passed", i + 1, num_duts,);
            }
            Err(e) => {
                tests_ok = false;

                println!("DUT [{}/{}] - Error message: {:#}", i + 1, num_duts, e);
                println!("DUT [{}/{}] - Tests Failed", i + 1, num_duts,);
            }
        }
    }

    if tests_ok {
        Ok(())
    } else {
        bail!("Not all tests succesful");
    }
}

fn handle_dut(definition: &DutDefinition) -> Result<()> {
    let probe = definition.open_probe()?;

    println!("Probe: {:?}", probe.get_name());
    println!("Chip:  {:?}", &definition.chip.name);

    let mut session = probe
        .attach(definition.chip.clone())
        .context("Failed to attach to chip")?;

    let target = session.target();

    let memory_regions = target.memory_map.clone();

    let cores = session.list_cores();

    for (core_index, core_type) in cores {
        println!("Core {}: {:?}", core_index, core_type);

        let target = session.target();
        let core_name = target.cores[core_index].name.clone();

        let mut core = session.core(core_index)?;

        println!("Halting core..");

        core.reset_and_halt(Duration::from_millis(500))?;

        test_register_access(&mut core)?;

        test_memory_access(&mut core, &core_name, &memory_regions)?;

        test_hw_breakpoints(&mut core, &memory_regions)?;

        test_stepping(&mut core, &memory_regions)?;

        // Ensure core is not running anymore.
        core.reset_and_halt(Duration::from_millis(200))?;
    }

    if let Some(flash_binary) = &definition.flash_test_binary {
        test_flashing(&mut session, flash_binary)?;
    }

    Ok(())
}

use super::*;
use bitflags::bitflags;
use zircon_object::vm::*;

impl Syscall<'_> {
    /// creates a new mapping in the virtual address space of the calling process.
    /// - `addr` - The starting address for the new mapping
    /// - `len` - specifies the length of the mapping
    /// - `prot ` - describes the desired memory protection of the mapping
    /// - `flags` - determines whether updates to the mapping are visible to other processes mapping the same region,
    ///     and whether updates are carried through to the underlying file.
    /// - `fd` - mapping file descriptor
    /// - `offset` - offset in the file
    pub async fn sys_mmap(
        &self,
        addr: usize,
        len: usize,
        prot: usize,
        flags: usize,
        fd: FileDesc,
        offset: u64,
    ) -> SysResult {
        let prot = MmapProt::from_bits_truncate(prot);
        let flags = MmapFlags::from_bits_truncate(flags);
        info!(
            "mmap: addr={:#x}, size={:#x}, prot={:?}, flags={:?}, fd={:?}, offset={:#x}",
            addr, len, prot, flags, fd, offset
        );

        let proc = self.zircon_process();
        let vmar = proc.vmar();

        if flags.contains(MmapFlags::FIXED) {
            // unmap first
            vmar.unmap(addr, len)?;
        }
        let vmar_offset = flags.contains(MmapFlags::FIXED).then(|| addr - vmar.addr());
        if flags.contains(MmapFlags::ANONYMOUS) {
            if flags.contains(MmapFlags::SHARED) {
                return Err(LxError::EINVAL);
            }
            let vmo = VmObject::new_paged(pages(len));
            let addr = vmar.map(vmar_offset, vmo.clone(), 0, vmo.len(), prot.to_flags())?;
            Ok(addr)
        } else {
            let file = self.linux_process().get_file(fd)?;
            let mut buf = vec![0; len];
            let len = file.read_at(offset, &mut buf).await?;
            let vmo = VmObject::new_paged(pages(len));
            vmo.write(0, &buf[..len])?;
            let addr = vmar.map(vmar_offset, vmo.clone(), 0, vmo.len(), prot.to_flags())?;
            Ok(addr)
        }
    }

    /// changes the access protections for the calling process's memory pages
    /// containing any part of the address range in the interval [addr, addr+len-1]
    /// TODO: unimplemented
    pub fn sys_mprotect(&self, addr: usize, len: usize, prot: usize) -> SysResult {
        let prot = MmapProt::from_bits_truncate(prot);
        info!(
            "mprotect: addr={:#x}, size={:#x}, prot={:?}",
            addr, len, prot
        );
        warn!("mprotect: unimplemented");
        Ok(0)
    }

    /// Deletes the mappings for the specified address range, and causes further references to addresses
    /// within the range to generate invalid memory references.
    pub fn sys_munmap(&self, addr: usize, len: usize) -> SysResult {
        info!("munmap: addr={:#x}, size={:#x}", addr, len);
        let proc = self.thread.proc();
        let vmar = proc.vmar();
        vmar.unmap(addr, len)?;
        Ok(0)
    }
}

bitflags! {
    /// for the flag argument in mmap()
    pub struct MmapFlags: usize {
        #[allow(clippy::identity_op)]
        /// Changes are shared.
        const SHARED = 1 << 0;
        /// Changes are private.
        const PRIVATE = 1 << 1;
        /// Place the mapping at the exact address
        const FIXED = 1 << 4;
        /// The mapping is not backed by any file. (non-POSIX)
        const ANONYMOUS = MMAP_ANONYMOUS;
    }
}

/// MmapFlags `MMAP_ANONYMOUS` depends on arch
#[cfg(target_arch = "mips")]
const MMAP_ANONYMOUS: usize = 0x800;
#[cfg(not(target_arch = "mips"))]
const MMAP_ANONYMOUS: usize = 1 << 5;

bitflags! {
    /// for the prot argument in mmap()
    pub struct MmapProt: usize {
        #[allow(clippy::identity_op)]
        /// Data can be read
        const READ = 1 << 0;
        /// Data can be written
        const WRITE = 1 << 1;
        /// Data can be executed
        const EXEC = 1 << 2;
    }
}

impl MmapProt {
    /// convert MmapProt to MMUFlags
    fn to_flags(self) -> MMUFlags {
        let mut flags = MMUFlags::USER;
        if self.contains(MmapProt::READ) {
            flags |= MMUFlags::READ;
        }
        if self.contains(MmapProt::WRITE) {
            flags |= MMUFlags::WRITE;
        }
        if self.contains(MmapProt::EXEC) {
            flags |= MMUFlags::EXECUTE;
        }
        // FIXME: hack for unimplemented mprotect
        if self.is_empty() {
            flags = MMUFlags::READ | MMUFlags::WRITE;
        }
        flags
    }
}

use std::any::Any;
use std::collections::HashMap;
use std::fmt::{self, Formatter};

/// Depot if for store temp data of current request. Each handler can read or write data to it.
///
/// # Example
///
/// ```no_run
/// use salvo_core::prelude::*;
///
/// #[fn_handler]
/// async fn set_user(req: &mut Request, depot: &mut Depot, res: &mut Response, ctrl: &mut FlowCtrl) {
///     depot.insert("user", "client");
///     ctrl.call_next(req, depot, res).await;
/// }
/// #[fn_handler]
/// async fn hello_world(depot: &mut Depot) -> String {
///     format!("Hello {}", depot.get::<&str>("user").map(|s|*s).unwrap_or_default())
/// }
/// #[tokio::main]
/// async fn main() {
///     let router = Router::new().hoop(set_user).handle(hello_world);
///     Server::new(TcpListener::bind("0.0.0.0:7878")).serve(router).await;
/// }
/// ```
#[derive(Default)]
pub struct Depot {
    data: HashMap<String, Box<dyn Any + Send>>,
}

impl Depot {
    /// Creates an empty ```Depot```.
    ///
    /// The depot is initially created with a capacity of 0, so it will not allocate until it is first inserted into.
    #[inline]
    pub fn new() -> Depot {
        Depot { data: HashMap::new() }
    }

    /// Creates an empty ```Depot``` with the specified capacity.
    ///
    /// The depot will be able to hold at least capacity elements without reallocating. If capacity is 0, the depot will not allocate.
    #[inline]
    pub fn with_capacity(capacity: usize) -> Depot {
        Depot {
            data: HashMap::with_capacity(capacity),
        }
    }
    /// Returns the number of elements the depot can hold without reallocating.
    #[inline]
    pub fn capacity(&self) -> usize {
        self.data.capacity()
    }
    /// Inserts a key-value pair into the depot.
    #[inline]
    pub fn insert<K, V>(&mut self, key: K, value: V)
    where
        K: Into<String>,
        V: Any + Send + Sync,
    {
        self.data.insert(key.into(), Box::new(value));
    }

    /// Check is there a value stored in depot with this key.
    #[inline]
    pub fn contains_key(&self, key: &str) -> bool {
        self.data.contains_key(key)
    }

    /// Immutably borrows value from depot, returing none if value is not present in depot.
    #[inline]
    pub fn get<V>(&self, key: &str) -> Option<&V>
    where
        V: Any + Send,
    {
        self.data.get(key).and_then(|b| b.downcast_ref::<V>())
    }

    /// Mutably borrows value from depot, returing none if value is not present in depot.
    #[inline]
    pub fn get_mut<V>(&mut self, key: &str) -> Option<&mut V>
    where
        V: Any + Send,
    {
        self.data.get_mut(key).and_then(|b| b.downcast_mut::<V>())
    }

    /// Take value from depot container.
    #[inline]
    pub fn remove<V>(&mut self, key: &str) -> Option<V>
    where
        V: Any + Send,
    {
        self.data.remove(key).and_then(|b| b.downcast::<V>().ok()).map(|b| *b)
    }

    /// Transfer all data to a new instance.
    #[inline]
    pub fn transfer(&mut self) -> Depot {
        let mut data = HashMap::with_capacity(self.data.len());
        for (k, v) in self.data.drain() {
            data.insert(k, v);
        }
        Depot { data }
    }
}

impl fmt::Debug for Depot {
    #[inline]
    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
        f.debug_struct("Depot").field("keys", &self.data.keys()).finish()
    }
}

#[cfg(test)]
mod test {
    use super::*;

    #[test]
    fn test_depot() {
        let mut depot = Depot::with_capacity(6);
        assert!(depot.capacity() >= 6);

        depot.insert("one", "ONE".to_owned());
        assert!(depot.contains_key("one"));

        assert_eq!(depot.get::<String>("one").unwrap(), &"ONE".to_owned());
        assert_eq!(depot.get_mut::<String>("one").unwrap(), &mut "ONE".to_owned());
    }

    #[test]
    fn test_transfer() {
        let mut depot = Depot::with_capacity(6);
        depot.insert("one", "ONE".to_owned());

        let depot = depot.transfer();
        assert_eq!(depot.get::<String>("one").unwrap(), &"ONE".to_owned());
    }
}

