//! Contains a structure to map from strings to integer symbols based on
//! string interning.
use hashbrown::HashMap;

use crate::string::PackedStringArray;
use num_traits::{AsPrimitive, FromPrimitive, Zero};
use snafu::Snafu;
use std::convert::TryFrom;

#[derive(Debug, Snafu)]
pub enum Error {
    #[snafu(display("duplicate key found {}", key))]
    DuplicateKeyFound { key: String },
}

/// A String dictionary that builds on top of `PackedStringArray` adding O(1)
/// index lookups for a given string
///
/// Heavily inspired by the string-interner crate
#[derive(Debug)]
pub struct StringDictionary<K> {
    hash: ahash::RandomState,
    /// Used to provide a lookup from string value to key type
    ///
    /// Note: K's hash implementation is not used, instead the raw entry
    /// API is used to store keys w.r.t the hash of the strings themselves
    ///
    dedup: HashMap<K, (), ()>,
    /// Used to store strings
    storage: PackedStringArray<K>,
}

impl<K: AsPrimitive<usize> + FromPrimitive + Zero> Default for StringDictionary<K> {
    fn default() -> Self {
        Self {
            hash: ahash::RandomState::new(),
            dedup: Default::default(),
            storage: PackedStringArray::new(),
        }
    }
}

impl<K: AsPrimitive<usize> + FromPrimitive + Zero> StringDictionary<K> {
    pub fn new() -> Self {
        Default::default()
    }

    /// Returns the id corresponding to value, adding an entry for the
    /// id if it is not yet present in the dictionary.
    pub fn lookup_value_or_insert(&mut self, value: &str) -> K {
        use hashbrown::hash_map::RawEntryMut;

        let hasher = &self.hash;
        let storage = &mut self.storage;
        let hash = hash_str(hasher, value);

        let entry = self
            .dedup
            .raw_entry_mut()
            .from_hash(hash, |key| value == storage.get(key.as_()).unwrap());

        match entry {
            RawEntryMut::Occupied(entry) => *entry.into_key(),
            RawEntryMut::Vacant(entry) => {
                let index = storage.append(value);
                let key =
                    K::from_usize(index).expect("failed to fit string index into dictionary key");
                *entry
                    .insert_with_hasher(hash, key, (), |key| {
                        let string = storage.get(key.as_()).unwrap();
                        hash_str(hasher, string)
                    })
                    .0
            }
        }
    }

    /// Returns the ID in self.dictionary that corresponds to `value`, if any.
    pub fn lookup_value(&self, value: &str) -> Option<K> {
        let hash = hash_str(&self.hash, value);
        self.dedup
            .raw_entry()
            .from_hash(hash, |key| value == self.storage.get(key.as_()).unwrap())
            .map(|(&symbol, &())| symbol)
    }

    /// Returns the str in self.dictionary that corresponds to `id`
    pub fn lookup_id(&self, id: K) -> Option<&str> {
        self.storage.get(id.as_())
    }

    pub fn size(&self) -> usize {
        self.storage.size() + self.dedup.len() * std::mem::size_of::<K>()
    }

    pub fn values(&self) -> &PackedStringArray<K> {
        &self.storage
    }

    pub fn into_inner(self) -> PackedStringArray<K> {
        self.storage
    }
}

fn hash_str(hasher: &ahash::RandomState, value: &str) -> u64 {
    use std::hash::{BuildHasher, Hash, Hasher};
    let mut state = hasher.build_hasher();
    value.hash(&mut state);
    state.finish()
}

impl<K> TryFrom<PackedStringArray<K>> for StringDictionary<K>
where
    K: AsPrimitive<usize> + FromPrimitive + Zero,
{
    type Error = Error;

    fn try_from(storage: PackedStringArray<K>) -> Result<Self, Error> {
        use hashbrown::hash_map::RawEntryMut;

        let hasher = ahash::RandomState::new();
        let mut dedup: HashMap<K, (), ()> = HashMap::with_capacity_and_hasher(storage.len(), ());
        for (idx, value) in storage.iter().enumerate() {
            let hash = hash_str(&hasher, value);

            let entry = dedup
                .raw_entry_mut()
                .from_hash(hash, |key| value == storage.get(key.as_()).unwrap());

            match entry {
                RawEntryMut::Occupied(_) => {
                    return Err(Error::DuplicateKeyFound {
                        key: value.to_string(),
                    })
                }
                RawEntryMut::Vacant(entry) => {
                    let key =
                        K::from_usize(idx).expect("failed to fit string index into dictionary key");

                    entry.insert_with_hasher(hash, key, (), |key| {
                        let string = storage.get(key.as_()).unwrap();
                        hash_str(&hasher, string)
                    });
                }
            }
        }

        Ok(Self {
            hash: hasher,
            dedup,
            storage,
        })
    }
}

#[cfg(test)]
mod test {
    use super::*;
    use std::convert::TryInto;

    #[test]
    fn test_dictionary() {
        let mut dictionary = StringDictionary::<i32>::new();

        let id1 = dictionary.lookup_value_or_insert("cupcake");
        let id2 = dictionary.lookup_value_or_insert("cupcake");
        let id3 = dictionary.lookup_value_or_insert("womble");

        let id4 = dictionary.lookup_value("cupcake").unwrap();
        let id5 = dictionary.lookup_value("womble").unwrap();

        let cupcake = dictionary.lookup_id(id4).unwrap();
        let womble = dictionary.lookup_id(id5).unwrap();

        let arrow_expected = arrow::array::StringArray::from(vec!["cupcake", "womble"]);
        let arrow_actual = dictionary.values().to_arrow();

        assert_eq!(id1, id2);
        assert_eq!(id1, id4);
        assert_ne!(id1, id3);
        assert_eq!(id3, id5);

        assert_eq!(cupcake, "cupcake");
        assert_eq!(womble, "womble");

        assert!(dictionary.lookup_value("foo").is_none());
        assert!(dictionary.lookup_id(-1).is_none());
        assert_eq!(arrow_expected, arrow_actual);
    }

    #[test]
    fn from_string_array() {
        let mut data = PackedStringArray::<u64>::new();
        data.append("cupcakes");
        data.append("foo");
        data.append("bingo");

        let dictionary: StringDictionary<_> = data.try_into().unwrap();

        assert_eq!(dictionary.lookup_value("cupcakes"), Some(0));
        assert_eq!(dictionary.lookup_value("foo"), Some(1));
        assert_eq!(dictionary.lookup_value("bingo"), Some(2));

        assert_eq!(dictionary.lookup_id(0), Some("cupcakes"));
        assert_eq!(dictionary.lookup_id(1), Some("foo"));
        assert_eq!(dictionary.lookup_id(2), Some("bingo"));
    }

    #[test]
    fn from_string_array_duplicates() {
        let mut data = PackedStringArray::<u64>::new();
        data.append("cupcakes");
        data.append("foo");
        data.append("bingo");
        data.append("cupcakes");

        let err = TryInto::<StringDictionary<_>>::try_into(data).expect_err("expected failure");
        assert!(matches!(err, Error::DuplicateKeyFound { key } if &key == "cupcakes"))
    }
}

use anyhow::Result;
use colored::Colorize;
use pest::Parser;
use std::collections::HashMap;
use std::fs::File;
use std::io::prelude::*;
use std::io::BufReader;
use std::path::Path;

#[derive(Parser)]
#[grammar = "template.pest"]
struct BombadilParser;

pub(crate) struct Variables {
    /// holds the values defined in template.toml
    pub variables: HashMap<String, String>,
}

impl Variables {
    /// Deserialize a toml file struct Variables
    pub(crate) fn from_toml(path: &Path) -> Result<Self> {
        let file = File::open(path);

        if let Err(err) = file {
            eprintln!("{} {:?} : {}", "Could not open var file".red(), path, err);
            Ok(Self::default())
        } else {
            let mut buf_reader = BufReader::new(file.unwrap());
            let mut contents = String::new();

            buf_reader
                .read_to_string(&mut contents)
                .map_err(|err| anyhow!("Cannot read var file {:?} : {}", &path, err))?;

            let variables: HashMap<String, String> = toml::from_str(&contents)
                .map_err(|err| anyhow!("parse error in {:?} :  {}", path, err))?;

            Ok(Self { variables })
        }
    }

    /// Read file in the given path and return its content
    /// with variable replaced by their values.
    pub(crate) fn to_dot(&self, path: &Path) -> Result<String> {
        // Read file content
        let file = File::open(path)?;
        let mut buf_reader = BufReader::new(file);
        let mut contents = String::new();
        buf_reader.read_to_string(&mut contents)?;

        let pairs = BombadilParser::parse(Rule::file, &contents)
            .expect("Unable to parse template file")
            .next()
            .unwrap();

        let mut output = String::new();

        for pair in pairs.into_inner() {
            match pair.as_rule() {
                Rule::variable => {
                    let var_name = pair.into_inner().next().unwrap().as_str().trim();

                    let value = self.variables.get(var_name).cloned().unwrap_or_else(|| {
                        let err = format!("Undefined variable : {} in {:?}", var_name, path);
                        eprintln!("{}", err.yellow());
                        "undefined variable".to_string()
                    });

                    output.push_str(&value);
                }
                Rule::raw_content => output.push_str(pair.as_str()),
                _ => (),
            }
        }

        Ok(output)
    }

    pub(crate) fn extend(&mut self, vars: Variables) {
        self.variables.extend(vars.variables);
    }
}

impl Default for Variables {
    fn default() -> Self {
        Self {
            variables: Default::default(),
        }
    }
}

#[cfg(test)]
mod test {
    use crate::templating::Variables;
    use std::collections::HashMap;
    use std::path::Path;

    #[test]
    fn should_inject_variables() {
        let mut map = HashMap::new();
        map.insert("red".to_string(), "red_value".to_string());

        let string = Variables { variables: map }
            .to_dot(Path::new("tests/dotfiles_simple/template"))
            .unwrap();

        assert_eq!(string, "color: red_value");
    }

    #[test]
    fn should_fail_on_non_utf8_file() {
        let content = Variables {
            variables: HashMap::new(),
        }
        .to_dot(Path::new("tests/dotfiles_non_utf8/ferris.png"));

        assert!(content.is_err());
    }

    #[test]
    fn extend_should_overwrite_vars() {
        let mut vars = HashMap::new();
        vars.insert("white".to_string(), "#000000".to_string());

        let mut extends = HashMap::new();
        extends.insert("white".to_string(), "#FFFFFF".to_string());

        let mut vars = Variables { variables: vars };

        let extends = Variables { variables: extends };

        vars.extend(extends);

        assert_eq!(vars.variables.len(), 1);
        assert_eq!(vars.variables.get("white"), Some(&"#FFFFFF".to_string()));
    }
}

extern crate proc_macro;

use proc_macro::TokenStream;

use serde_json::Value;

/// 将相连的若干的 list 分割
fn split_to_vec(input: &str) -> Vec<&str> {
    let mut start = 0;
    let mut cnt = 0;
    let mut ret = vec![];
    for (idx, c) in input.chars().enumerate() {
        match c {
            '[' => {
                if cnt == 0 {
                    start = idx;
                }
                cnt += 1;
            }
            ']' => {
                cnt -= 1;
                if cnt == 0 {
                    ret.push(&input[start..=idx]);
                    start = idx + 1;
                }
            }
            _ => (),
        }
    }
    ret
}

/// 将名字转换为 Rust 风格的命名
/// 除第一个单词外, 其余大写字母替换为 下划线 + 小写字母 的组合
fn turn_to_legal_name(name: &str) -> String {
    let mut ret = String::new();
    let mut skiped_first = false;
    for c in name.chars() {
        if c.is_ascii_uppercase() && skiped_first {
            ret.push('_');
            ret.push(c.to_ascii_lowercase());
        } else {
            ret.push(c);
        }
        if c == ',' {
            skiped_first = true;
        }
    }
    ret
}

/// 转换为 Rust 语法的参数
trait ToArgs {
    fn to_args(&self) -> String;
}

impl ToArgs for Value {
    fn to_args(&self) -> String {
        let array = self.as_array().unwrap();
        if array.is_empty() {
            "".to_owned()
        } else {
            array
                .iter()
                .map(|value| {
                    if value.is_string() {
                        format!("{}.to_owned()", value)
                    } else {
                        value.to_string()
                    }
                })
                .collect::<Vec<_>>()
                .join(", ")
        }
    }
}

fn json_to_code(input: TokenStream) -> String {
    let input = input.to_string();
    let v = split_to_vec(&input);
    let (funcs, args, rets) = (v[0], v[1], v[2]);

    // 反序列化 json
    // 这个地方有个坑点, "-123" 在先前 to_string 的时候会变成 "- 123", 所以单独替换一下 "- " => "-"
    let funcs = serde_json::from_str::<Value>(&turn_to_legal_name(funcs)).unwrap();
    let args = serde_json::from_str::<Value>(&args.replace("- ", "-")).unwrap();
    let rets = serde_json::from_str::<Value>(&rets.replace("- ", "-")).unwrap();

    let mut code = String::new();
    code.push_str(&format!(
        "let mut obj = {}::new({});\n",
        funcs[0].as_str().unwrap(),
        args[0].to_args(),
    ));

    for i in 1..funcs.as_array().unwrap().len() {
        let mut stmt = format!("obj.{}({})", funcs[i].as_str().unwrap(), args[i].to_args());
        if !rets[i].is_null() {
            stmt = format!(
                r##"assert_eq!({}, {}, r#"{}"#)"##,
                stmt,
                rets[i].to_string(),
                stmt
            );
        }
        stmt.push_str(";\n");
        code.push_str(&stmt);
    }
    code
}

/// Generate code from leetcode json
///
/// # Example
///
/// ```ignore
/// leetcode_test!(
///     ["Trie", "insert", "search"]
///     [[], ["apple"], ["apple"]]
///     [null, null, true]
/// )
/// ```
///
/// this will be expaned to
///
/// ``` ignore
/// let mut obj = Trie::new();
/// obj.insert("apple".to_owned());
/// assert_eq!(obj.search("apple".to_owned()), true);
/// ```
#[proc_macro]
pub fn leetcode_test(input: TokenStream) -> TokenStream {
    json_to_code(input).parse().unwrap()
}

#[proc_macro]
pub fn leetcode_test_debug(input: TokenStream) -> TokenStream {
    format!(r###"r##"{}"##"###, json_to_code(input))
        .parse()
        .unwrap()
}

