use ControlMessage;
use bip_peer::PeerInfo;
use bip_peer::messages::ExtendedMessage;
use bip_peer::messages::builders::ExtendedMessageBuilder;
use error::UberError;
use futures::Async;
use futures::Poll;
use futures::Stream;
use futures::task;
use futures::task::Task;
use std::collections::{HashMap, VecDeque};

/// Enumeration of extended messages that can be sent to the extended module.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum IExtendedMessage {
    Control(ControlMessage),
    RecievedExtendedMessage(PeerInfo, ExtendedMessage),
}

/// Enumeration of extended messages that can be received from the extended module.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum OExtendedMessage {
    SendExtendedMessage(PeerInfo, ExtendedMessage),
}

/// Trait for a module to take part in constructing the extended message for a peer.
pub trait ExtendedListener {
    /// Extend the given extended message builder for the given peer.
    fn extend(&self, _info: &PeerInfo, _builder: ExtendedMessageBuilder) -> ExtendedMessageBuilder {
        _builder
    }

    /// One or both sides of a peer connection had their extended information updated.
    ///
    /// This can be called multiple times for any given peer as extension information updates.
    fn on_update(&mut self, _info: &PeerInfo, _extended: &ExtendedPeerInfo) {}
}

/// Container for both the local and remote `ExtendedMessage`.
pub struct ExtendedPeerInfo {
    ours: Option<ExtendedMessage>,
    theirs: Option<ExtendedMessage>,
}

impl ExtendedPeerInfo {
    pub fn new(ours: Option<ExtendedMessage>, theirs: Option<ExtendedMessage>) -> ExtendedPeerInfo {
        ExtendedPeerInfo {
            ours: ours,
            theirs: theirs,
        }
    }

    pub fn update_ours(&mut self, message: ExtendedMessage) {
        self.ours = Some(message);
    }

    pub fn update_theirs(&mut self, message: ExtendedMessage) {
        self.theirs = Some(message);
    }

    pub fn our_message(&self) -> Option<&ExtendedMessage> {
        self.ours.as_ref()
    }

    pub fn their_message(&self) -> Option<&ExtendedMessage> {
        self.theirs.as_ref()
    }
}

//------------------------------------------------------------------------------//

pub struct ExtendedModule {
    builder: ExtendedMessageBuilder,
    peers: HashMap<PeerInfo, ExtendedPeerInfo>,
    out_queue: VecDeque<OExtendedMessage>,
    opt_task: Option<Task>,
}

impl ExtendedModule {
    pub fn new(builder: ExtendedMessageBuilder) -> ExtendedModule {
        ExtendedModule {
            builder: builder,
            peers: HashMap::new(),
            out_queue: VecDeque::new(),
            opt_task: None,
        }
    }

    pub fn process_message<D>(&mut self, message: IExtendedMessage, d_modules: &mut [Box<D>])
    where
        D: ExtendedListener + ?Sized,
    {
        match message {
            IExtendedMessage::Control(ControlMessage::PeerConnected(info)) => {
                let mut builder = self.builder.clone();

                for d_module in d_modules.iter() {
                    let temp_builder = builder;
                    builder = d_module.extend(&info, temp_builder);
                }

                let ext_message = builder.build();
                let ext_peer_info = ExtendedPeerInfo::new(Some(ext_message.clone()), None);

                for d_module in d_modules {
                    d_module.on_update(&info, &ext_peer_info);
                }

                self.peers.insert(info, ext_peer_info);
                self.out_queue
                    .push_back(OExtendedMessage::SendExtendedMessage(info, ext_message));
            },
            IExtendedMessage::Control(ControlMessage::PeerDisconnected(info)) => {
                self.peers.remove(&info);
            },
            IExtendedMessage::RecievedExtendedMessage(info, ext_message) => {
                let ext_peer_info = self.peers.get_mut(&info).unwrap();
                ext_peer_info.update_theirs(ext_message);

                for d_module in d_modules {
                    d_module.on_update(&info, &ext_peer_info);
                }
            },
            _ => {
                ()
            },
        }

        self.check_stream_unblock();
    }

    fn check_stream_unblock(&mut self) {
        if !self.out_queue.is_empty() {
            if let Some(task) = self.opt_task.take() {
                task.notify();
            }
        }
    }
}

impl Stream for ExtendedModule {
    type Item = OExtendedMessage;
    type Error = UberError;

    fn poll(&mut self) -> Poll<Option<OExtendedMessage>, UberError> {
        let opt_message = self.out_queue.pop_front();

        if let Some(message) = opt_message {
            Ok(Async::Ready(Some(message)))
        } else {
            self.opt_task = Some(task::current());

            Ok(Async::NotReady)
        }
    }
}

extern crate clap;
extern crate keepass;
extern crate rpassword;
extern crate termcolor;

mod diff;

use clap::{App, Arg};
use diff::{group::Group, Diff, DiffDisplay};
use keepass::{result::Error, result::Result, Database};

use termcolor::{Color, ColorChoice, ColorSpec, StandardStream, WriteColor};

use std::path::Path;
use std::{fs::File, io::Read};

fn main() -> Result<()> {
    let matches = App::new("keepass-diff")
    .version("0.3.0")
    .about("Shows differences between two .kdbx files")
    .author("Joern Bernhardt")
    .arg(
      Arg::with_name("INPUT-A")
        .help("Sets the first file")
        .required(true)
        .index(1),
    )
    .arg(
      Arg::with_name("INPUT-B")
        .help("Sets the second file")
        .required(true)
        .index(2),
    )
    .arg(
      Arg::with_name("no-color")
        .short("C")
        .long("no-color")
        .help("Disables color output")
        .takes_value(false),
    )
    .arg(
      Arg::with_name("password-a")
        .long("password-a")
        .help("Sets the password for the first file (will be asked for if omitted)")
        .takes_value(true),
    )
    .arg(
      Arg::with_name("password-b")
        .long("password-b")
        .help("Sets the password for the second file (will be asked for if omitted)")
        .takes_value(true),
    )
    .arg(
      Arg::with_name("passwords")
        .long("passwords")
        .help("Sets the password for both files (if it's the same for both files)")
        .takes_value(true),
    )
    .arg(
      Arg::with_name("no-password-a")
        .long("no-password-a")
        .help("Sets no password for the first file (and will not ask for it)")
        .takes_value(false),
    )
    .arg(
      Arg::with_name("no-password-b")
        .long("no-password-b")
        .help("Sets no password for the second file (and will not ask for it)")
        .takes_value(false),
    )
    .arg(
      Arg::with_name("no-passwords")
        .long("no-passwords")
        .help("Sets no password for both files (and will not ask for both files)")
        .takes_value(false),
    )
    .arg(
      Arg::with_name("keyfile-a")
        .long("keyfile-a")
        .help("Sets the key file for the first file")
        .takes_value(true),
    )
    .arg(
      Arg::with_name("keyfile-b")
        .long("keyfile-b")
        .help("Sets the key file for the second file")
        .takes_value(true),
    )
    .arg(
      Arg::with_name("keyfiles")
        .long("keyfiles")
        .help("Sets the same key file for both files (keyfile-a and keyfile-b would take precedence if set as well)")
        .takes_value(true),
    )
    .get_matches();

    match (matches.value_of("INPUT-A"), matches.value_of("INPUT-B")) {
        (Some(file_a), Some(file_b)) => {
            let pass_a = match (
                matches.value_of("password-a"),
                matches.value_of("passwords"),
                matches.is_present("no-password-a"),
                matches.is_present("no-passwords"),
            ) {
                (Some(password), _, _, _) => Some(String::from(password)),
                (_, Some(password), _, _) => Some(String::from(password)),
                (_, _, true, _) => None,
                (_, _, _, true) => None,
                _ => {
                    print!("Password for file {}: ", file_a);
                    let password = rpassword::prompt_password_stdout("")
                        .map(|s| if s == "" { None } else { Some(s) })
                        .unwrap_or(None);
                    password
                }
            };
            let pass_b = match (
                matches.value_of("password-b"),
                matches.value_of("passwords"),
                matches.is_present("no-password-b"),
                matches.is_present("no-passwords"),
            ) {
                (Some(password), _, _, _) => Some(String::from(password)),
                (_, Some(password), _, _) => Some(String::from(password)),
                (_, _, true, _) => None,
                (_, _, _, true) => None,
                _ => {
                    print!("Password for file {}: ", file_b);
                    let password_option: Option<String> = rpassword::prompt_password_stdout("")
                        .map(|s| if s == "" { None } else { Some(s) })
                        .unwrap_or(None);
                    password_option
                }
            };
            let keyfile_a: Option<&str> = matches
                .value_of("keyfile-a")
                .or(matches.value_of("keyfiles"));
            let keyfile_b: Option<&str> = matches
                .value_of("keyfile-b")
                .or(matches.value_of("keyfiles"));
            let use_color: bool = !matches.is_present("no-color");

            let db_a = kdbx_to_group(file_a, pass_a, keyfile_a).expect("Error opening database A");
            let db_b = kdbx_to_group(file_b, pass_b, keyfile_b).expect("Error opening database B");

            let delta = db_a.diff(&db_b);

            println!(
                "{}",
                DiffDisplay {
                    inner: delta,
                    depth: 0,
                    use_color
                }
            );
        }
        _ => println!("Need two .kdbx files as arguments"),
    }

    Ok(())
}

pub fn kdbx_to_group(
    file: &str,
    password: Option<String>,
    keyfile_path: Option<&str>,
) -> Result<Group> {
    let mut keyfile = keyfile_path.map(|path| File::open(Path::new(path)).unwrap());
    File::open(Path::new(file))
        .map_err(|e| Error::from(e))
        .and_then(|mut db_file| {
            let db = Database::open(
                &mut db_file,
                password.as_ref().map(|s| s.as_str()),
                keyfile.as_mut().map(|f| f as &mut dyn Read),
            );
            db
        })
        .map(|db: Database| Group::from_keepass(&db.root))
}

pub fn set_fg(color: Option<Color>) {
    let mut stdout = StandardStream::stdout(ColorChoice::Always);
    stdout.set_color(ColorSpec::new().set_fg(color)).expect("Setting colors in your console failed. Please use the --no-color flag to disable colors if the error persists.");
}

/// An authentication request.
///
/// This currently exists as an enum due to an [issue in serde][1].
///
/// [1]: https://github.com/serde-rs/serde/issues/271
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "snake_case", tag = "kind")]
pub enum AuthRequest {
    AuthRequest { username: String },
}

/// An authentication response.
///
/// This is a response to [`AuthRequest`].
///
/// This currently exists as an enum due to an [issue in serde][1].
///
/// [1]: https://github.com/serde-rs/serde/issues/271
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "snake_case", tag = "kind")]
pub enum AuthResponse {
    AuthResponse {
        /// Whether or not authentication was successful.
        ///
        /// The `Ok` is the username.
        /// The `Err` is a string representation of why the authentication failed.
        #[serde(flatten)]
        result: Result<String, String>,
    },
}

#[cfg(test)]
mod tests {
    use super::*;

    use serde_json;

    #[test]
    fn test_serde_auth_request_message() {
        let msg = AuthRequest::AuthRequest {
            username: "wiz".into(),
        };

        let expected_value = json!({
            "kind": "auth_request",
            "username": "wiz",
        });

        let serialized = serde_json::to_string(&msg).unwrap();

        assert_eq!(serde_json::to_value(&msg).unwrap(), expected_value);
        assert_eq!(
            serde_json::from_str::<AuthRequest>(&serialized).unwrap(),
            msg
        );
    }

    #[test]
    fn test_serde_auth_response_message() {
        let tests = vec![
            (
                AuthResponse::AuthResponse {
                    result: Ok("wiz".into()),
                },
                json!({
                    "kind": "auth_response",
                    "Ok": "wiz",
                }),
            ),
            (
                AuthResponse::AuthResponse {
                    result: Err("Invalid username.".into()),
                },
                json!({
                    "kind": "auth_response",
                    "Err": "Invalid username.",
                }),
            ),
        ];

        for (msg, expected_value) in tests {
            let serialized = serde_json::to_string(&msg).unwrap();
            assert_eq!(serde_json::to_value(&msg).unwrap(), expected_value);
            assert_eq!(
                serde_json::from_str::<AuthResponse>(&serialized).unwrap(),
                msg
            );
        }
    }
}

extern crate bind_rs;
use bind_rs::bind::*;
use bind_rs::reader::*;
use bind_rs::reader_writer::ReaderWriterM;
use bind_rs::writer::*;
use std::cell::RefCell;
use std::collections::BTreeMap;

#[derive(Debug)]
struct Transfer {
    from: String,
    to: String,
    amount: i64,
    from_val: i64,
    to_val: i64,
}

type Book = RefCell<BTreeMap<String, i64>>;

trait MonadBalance<'a>: Monad<'a> {
    fn transfer(from: String, to: String, amount: i64) -> Self::Repr<()>;
}

impl<'a, M: Monad<'a>> MonadBalance<'a> for M
where
    M: MonadReader<'a, Book> + MonadWriter<'a, Vec<Transfer>>,
{
    fn transfer(from: String, to: String, amount: i64) -> Self::Repr<()> {
        Self::ask_ref().bind(move |book_refcell| {
            let mut book_refmut = book_refcell.borrow_mut();
            *book_refmut.entry(from.clone()).or_insert(0) -= amount;
            let from_val = *book_refmut.get(&from).expect("must exist");
            *book_refmut.entry(to.clone()).or_insert(0) += amount;
            let to_val = *book_refmut.get(&to).expect("must exist");
            Self::write(vec![Transfer {
                from,
                to,
                amount,
                from_val,
                to_val,
            }])
        })
    }
}

fn some_transfers<'a, M: MonadBalance<'a>>() -> M::Repr<()> {
    M::transfer("Alice".to_string(), "Bob".to_string(), 100)
        .bind(|_| M::transfer("Bob".to_string(), "Eve".to_string(), 10))
        .bind(|_| M::transfer("Eve".to_string(), "Alice".to_string(), 5))
}

fn main() {
    let storage: Book = RefCell::new(
        vec![("Alice".to_string(), 1000), ("Bob".to_string(), 500)]
            .into_iter()
            .collect(),
    );
    let (trace, _) = some_transfers::<'_, ReaderWriterM<Book, Vec<Transfer>>>().run(&storage);
    println!("transfer history: {:#?}", trace);
    println!("storage: {:#?}", storage);
}

use block_buffer::block_padding::{Padding, PadError, UnpadError};
use byte_tools::zero;

macro_rules! impl_padding {
    ($name:ident, $pad:expr) => {
        // it does not work with empty enum as it required to have Default impl
        // for it for some unclear reason.
        #[derive(Copy, Clone, Default)]
        pub struct $name;

        impl Padding for $name {
            #[inline(always)]
            fn pad_block(block: &mut [u8], pos: usize) -> Result<(), PadError> {
                if pos >= block.len() { Err(PadError)? }
                block[pos] = $pad;
                zero(&mut block[pos+1..]);
                let n = block.len();
                block[n-1] |= 0x80;
                Ok(())
            }

            #[inline(always)]
            fn unpad(_data: &[u8]) -> Result<&[u8], UnpadError> {
                unimplemented!();
            }
        }
    }
}

impl_padding!(Keccak, 0x01);
impl_padding!(Sha3, 0x06);
impl_padding!(Shake, 0x1f);

//! Implementations of reserved IANA `SD-ID`'s

use std::fmt;

/// The SD-ID "origin" MAY be used to indicate the origin of a syslog
/// message.  The following parameters can be used.  All parameters are
/// OPTIONAL.
/// 
/// Specifying any of these parameters is primarily an aid to log
/// analyzers and similar applications.
/// 
/// Notes: 
/// * Documentation text copied from: 
/// [RFC5424 Section 7.2](https://tools.ietf.org/html/rfc5424#section-7.2)
/// * No automatic bounds checking is currently done for these fields. 
/// Check the documentation for the length limits.
#[derive(Debug)]
pub enum Origin {
    /// The "ip" parameter denotes an IP address that the originator knows it
    /// had at the time of originating the message.  It MUST contain the
    /// textual representation of an IP address as outlined in [Section 
    /// 6.2.4](https://tools.ietf.org/html/rfc5424#section-6.2.4).
    /// 
    /// This parameter can be used to provide identifying information in
    /// addition to what is present in the HOSTNAME field.  It might be
    /// especially useful if the host's IP address is included in the message
    /// while the HOSTNAME field still contains the FQDN.  It is also useful
    /// for describing all IP addresses of a multihomed host.
    ///
    /// If an originator has multiple IP addresses, it MAY either list one of
    /// its IP addresses in the "ip" parameter or it MAY include multiple
    /// "ip" parameters in a single "origin" structured data element.
    Ip(String),
    /// The "enterpriseId" parameter MUST be a 'SMI Network Management
    /// Private Enterprise Code', maintained by IANA, whose prefix is
    /// iso.org.dod.internet.private.enterprise (1.3.6.1.4.1).  The number
    /// that follows MUST be unique and MUST be registered with IANA as per
    /// [RFC 2578](https://tools.ietf.org/html/rfc2578).
    /// 
    /// An enterprise is only authorized to assign
    /// values within the iso.org.dod.internet.private.enterprise.<private
    /// enterprise number> subtree assigned by IANA to that enterprise.  The
    /// enterpriseId MUST contain only a value from the
    /// iso.org.dod.internet.private.enterprise.<private enterprise number>
    /// subtree.  In general, only the IANA-assigned private enterprise
    /// number is needed (a single number).  An enterprise might decide to
    /// use sub-identifiers below its private enterprise number.  If sub-
    /// identifiers are used, they MUST be separated by periods and be
    /// represented as decimal numbers.  An example for that would be
    /// "32473.1.2".  Please note that the ID "32473.1.2" is just an example
    /// and MUST NOT be used.  The complete up-to-date list of Private
    /// Enterprise Numbers (PEN) is maintained by IANA.
    /// 
    /// By specifying a private enterprise number, the vendor allows more
    /// specific processing of the message.
    EnterpriseId(String),
    /// The "software" parameter uniquely identifies the software that
    /// generated the message.  If it is used, "enterpriseId" SHOULD also be
    /// specified, so that a specific vendor's software can be identified.
    /// The "software" parameter is not the same as the APP-NAME header
    /// field.  It MUST always contain the name of the generating software,
    /// whereas APP-NAME can contain anything else, including an operator-
    /// configured value.
    /// 
    /// The "software" parameter is a string.  It MUST NOT be longer than 48
    /// characters.
    Software(String),
    /// The "swVersion" parameter uniquely identifies the version of the
    /// software that generated the message.  If it is used, the "software"
    /// and "enterpriseId" parameters SHOULD be provided, too.
    /// 
    /// The "swVersion" parameter is a string.  It MUST NOT be longer than 32
    /// characters.
    Version(String),
}

impl fmt::Display for Origin {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        use self::Origin::*;
        let val = match self {
            Ip(s) => format!(r#" ip="{}""#, s),
            EnterpriseId(s) => format!(r#" enterpriseId="{}""#, s),
            Software(s) => format!(r#" software="{}""#, s),
            Version(s) => format!(r#" swVersion="{}""#, s),
        };
        write!(f, "{}", val)
    }
}

/// The SD-ID "timeQuality" MAY be used by the originator to describe its
/// notion of system time.  
/// 
/// This SD-ID SHOULD be written if the
/// originator is not properly synchronized with a reliable external time
/// source or if it does not know whether its time zone information is
/// correct.  The main use of this structured data element is to provide
/// some information on the level of trust it has in the TIMESTAMP
/// described in [Section 6.2.3](https://tools.ietf.org/html/rfc5424#section-6.2.3).  All parameters are OPTIONAL.
/// 
/// Notes: 
/// * Documentation text copied from: 
/// [RFC5424 Section 7.1](https://tools.ietf.org/html/rfc5424#section-7.1)
/// * No automatic bounds checking is currently done for these fields. 
#[derive(Debug, Copy, Clone)]
pub enum TimeQuality {
    /// The "tzKnown" parameter indicates whether the originator knows its
    /// time zone.  If it does, the value "1" MUST be used.  If the time zone
    /// information is in doubt, the value "0" MUST be used.  If the
    /// originator knows its time zone but decides to emit time in UTC, the
    /// value "1" MUST be used (because the time zone is known).
    TzKnown(bool),
    /// The "isSynced" parameter indicates whether the originator is
    /// synchronized to a reliable external time source, e.g., via NTP.  If
    /// the originator is time synchronized, the value "1" MUST be used.  If
    /// not, the value "0" MUST be used.
    IsSynced(bool),
    /// The "syncAccuracy" parameter indicates how accurate the originator
    /// thinks its time synchronization is.  It is an integer describing the
    /// maximum number of microseconds that its clock may be off between
    /// synchronization intervals.
    /// 
    /// If the value "0" is used for "isSynced", this parameter MUST NOT be
    /// specified.  If the value "1" is used for "isSynced" but the
    /// "syncAccuracy" parameter is absent, a collector or relay can assume
    /// that the time information provided is accurate enough to be
    /// considered correct.  The "syncAccuracy" parameter MUST be written
    /// only if the originator actually has knowledge of the reliability of
    /// the external time source.  In most cases, it will gain this in-depth
    /// knowledge through operator configuration.
    SyncAccuracy(u32),
}

impl fmt::Display for TimeQuality {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        use self::TimeQuality::*;
        let val = match self {
            TzKnown(s) => if *s {
                r#" tzKnown="1""#.to_string()
            } else {
                r#" tz_known="0""#.to_string()
            },
            IsSynced(s) => if *s {
                r#" isSynced="1""#.to_string()
            } else {
                r#" isSynced="0""#.to_string()
            },
            SyncAccuracy(s) => format!(r#" syncAccuracy="{}""#, s),
        };
        write!(f, "{}", val)
    }
}

