use std::ffi::{c_void, CString};

use snafu::Snafu;
use spdk_sys::{
    spdk_get_thread,
    spdk_set_thread,
    spdk_thread,
    spdk_thread_create,
    spdk_thread_destroy,
    spdk_thread_exit,
    spdk_thread_get_by_id,
    spdk_thread_is_exited,
    spdk_thread_poll,
    spdk_thread_send_msg,
};

use crate::core::{cpu_cores::CpuMask, Cores};
use std::ptr::NonNull;

#[derive(Debug, Snafu)]
pub enum Error {
    #[snafu(display("Event spawned from a non-spdk thread"))]
    InvalidThread {},
}

#[derive(Debug, PartialEq, Clone, Copy)]
/// struct that wraps an SPDK thread. The name thread is chosen poorly and
/// should not be confused with an actual thread. Consider it more to be
/// analogous to a container to which you can submit work and poll it to drive
/// the submitted work to completion.
pub struct Mthread(NonNull<spdk_thread>);

impl From<*mut spdk_thread> for Mthread {
    fn from(t: *mut spdk_thread) -> Self {
        let t = NonNull::new(t).expect("thread may not be NULL");
        Mthread(t)
    }
}

impl Mthread {
    pub fn get_init() -> Mthread {
        Mthread(
            NonNull::new(unsafe { spdk_thread_get_by_id(1) })
                .expect("No init thread allocated"),
        )
    }

    ///
    /// With the given thread as context, execute the closure on that thread.
    ///
    /// Any function can be executed here however, this should typically be used
    /// to execute functions that reference any FFI to SPDK.

    pub fn new(name: String, core: u32) -> Option<Self> {
        let name = CString::new(name).unwrap();

        NonNull::new(unsafe {
            let mut mask = CpuMask::new();
            mask.set_cpu(core, true);
            spdk_thread_create(name.as_ptr(), mask.as_ptr())
        })
        .map(Mthread)
    }

    pub fn id(&self) -> u64 {
        unsafe { (self.0.as_ref()).id }
    }
    ///
    /// # Note
    ///
    /// Avoid any blocking calls as it will block the whole reactor. Also, avoid
    /// long-running functions. In general if you follow the nodejs event loop
    /// model, you should be good.
    pub fn with<T, F: FnOnce() -> T>(self, f: F) -> T {
        let th = Self::current();
        self.enter();
        let out = f();
        if let Some(t) = th {
            t.enter();
        }
        out
    }

    #[inline]
    pub fn poll(&self) {
        let _ = unsafe { spdk_thread_poll(self.0.as_ptr(), 0, 0) };
    }

    #[inline]
    pub fn enter(&self) {
        unsafe { spdk_set_thread(self.0.as_ptr()) };
    }

    #[inline]
    pub fn exit(&self) {
        unsafe { spdk_set_thread(std::ptr::null_mut()) };
    }

    pub fn current() -> Option<Mthread> {
        NonNull::new(unsafe { spdk_get_thread() }).map(Mthread)
    }

    pub fn name(&self) -> &str {
        unsafe {
            std::ffi::CStr::from_ptr(&self.0.as_ref().name[0])
                .to_str()
                .unwrap()
        }
    }

    pub fn into_raw(self) -> *mut spdk_thread {
        self.0.as_ptr()
    }

    /// destroy the given thread waiting for it to become ready to destroy
    pub fn destroy(self) {
        debug!("destroying thread {}...{:p}", self.name(), self.0);
        unsafe {
            spdk_set_thread(self.0.as_ptr());
            // set that we *want* to exit, but we have not exited yet
            spdk_thread_exit(self.0.as_ptr());

            // now wait until the thread is actually exited the internal
            // state is updated by spdk_thread_poll()
            while !spdk_thread_is_exited(self.0.as_ptr()) {
                spdk_thread_poll(self.0.as_ptr(), 0, 0);
            }
            spdk_thread_destroy(self.0.as_ptr());
        }

        debug!("thread {:p} destroyed", self.0);
    }

    #[allow(clippy::not_unsafe_ptr_arg_deref)]
    pub fn send_msg(
        &self,
        f: extern "C" fn(ctx: *mut c_void),
        arg: *mut c_void,
    ) {
        let rc = unsafe { spdk_thread_send_msg(self.0.as_ptr(), Some(f), arg) };
        assert_eq!(rc, 0);
    }

    /// send the given thread 'msg' in xPDK speak.
    pub fn msg<F, T>(&self, t: T, f: F)
    where
        F: FnMut(T),
        T: std::fmt::Debug + 'static,
    {
        // context structure which is passed to the callback as argument
        struct Ctx<F, T: std::fmt::Debug> {
            closure: F,
            args: T,
        }

        // helper routine to unpack the closure and its arguments
        extern "C" fn trampoline<F, T>(arg: *mut c_void)
        where
            F: FnMut(T),
            T: 'static + std::fmt::Debug,
        {
            let mut ctx = unsafe { Box::from_raw(arg as *mut Ctx<F, T>) };
            (ctx.closure)(ctx.args);
        }

        let ctx = Box::new(Ctx {
            closure: f,
            args: t,
        });

        let rc = unsafe {
            spdk_thread_send_msg(
                self.0.as_ptr(),
                Some(trampoline::<F, T>),
                Box::into_raw(ctx).cast(),
            )
        };
        assert_eq!(rc, 0);
    }

    /// spawns a thread and setting its affinity to the inverse cpu set of
    /// mayastor
    pub fn spawn_unaffinitized<F, T>(f: F) -> std::thread::JoinHandle<T>
    where
        F: FnOnce() -> T + Send + 'static,
        T: Send + 'static,
    {
        std::thread::spawn(|| {
            Self::unaffinitize();
            f()
        })
    }

    pub fn unaffinitize() {
        unsafe {
            let mut set: libc::cpu_set_t = std::mem::zeroed();
            for i in 0 .. libc::sysconf(libc::_SC_NPROCESSORS_ONLN) {
                libc::CPU_SET(i as usize, &mut set)
            }

            Cores::count()
                .into_iter()
                .for_each(|i| libc::CPU_CLR(i as usize, &mut set));

            libc::sched_setaffinity(
                0,
                std::mem::size_of::<libc::cpu_set_t>(),
                &set,
            );

            info!("pthread started on core {}", libc::sched_getcpu());
        }
    }
}

use gdk::ScrollDirection;
use gtk::prelude::*;
use gtk::{Orientation, Overlay, Rectangle, Window, WindowType};
use glib::SignalHandlerId;
use glib::translate::{ToGlib, from_glib};

use std::cell::RefCell;
use std::rc::Rc;

use crate::{wm, NAME};
use crate::components::{Component, ComponentParams, load_component};
use crate::config::ConfigGroup;
use crate::wm::ipc::commands::Selectors;

pub struct Bar {
    config: ConfigGroup,
    components: Vec<Box<dyn Component>>,
    overlay: Overlay,
    container: gtk::Box,
    event_ids: Vec<SignalHandlerId>,
    window: Window,
}

impl Bar {
    pub fn new(
        config: ConfigGroup,
        wm_util: &wm::WMUtil,
        monitor: &Rectangle,
        existing_window: Option<Window>,
    ) -> Bar {
        // TODO: check if the type differs to existing window
        let reserve_space = config.get_bool_or("reserve-space", true);
        let window_type = if reserve_space {
            WindowType::Toplevel
        } else {
            WindowType::Popup
        };

        // use existing or create new window
        let is_new = existing_window.is_none();
        let window = if let Some(existing) = existing_window {
            existing
        } else {
            let window = Window::new(window_type);
            wm_util.add_gtk_window(&window);
            window
        };

        // set base values
        window.set_default_size(monitor.width, 1);
        if is_new {
            window.set_title(NAME);
            #[allow(deprecated)]
            window.set_wmclass(NAME, NAME);
            window.set_type_hint(gdk::WindowTypeHint::Dock);
            window.set_keep_below(true);
            window.stick();

            wm::gtk::set_transparent(&window);
        }

        // init container
        let container = gtk::Box::new(Orientation::Horizontal, 0);
        WidgetExt::set_name(&container, &config.name);
        WidgetExt::set_name(&window, &config.name);

        // create overlay
        let overlay = Overlay::new();

        // attach scrollevent
        let monitor_index = config.get_int_or("monitor", 0) as i32;
        let viewport = gtk::Viewport::new(None, None);
        // set gdk::EventMask::SCROLL_MASK and disable 'smooth' scrolling
        viewport.add_events(2097152);
        // when scrolling, change workspace
        if config.get_bool_or("workspace-scroll", false) {
            viewport.connect_scroll_event(clone!(wm_util move |_vp, e| {
                let direction = e.get_direction();
                let is_next = direction == ScrollDirection::Down;
                wm_util.cycle_workspace(is_next, monitor_index);
                Inhibit(true)
            }));
        }
        viewport.set_shadow_type(gtk::ShadowType::None);

        // connect everything up
        overlay.add(&container);
        viewport.add(&overlay);
        window.add(&viewport);

        // set position
        let is_top = config.get_str_or("position", "top") == "top";
        let &Rectangle { x, y, height, .. } = monitor;
        let is_set = Rc::new(RefCell::new(false));
        let size_id = window.connect_size_allocate(clone!((is_set, wm_util)
            move |window, rect| {
                let xpos = x;
                let ypos = if !is_top {
                    y + (height - rect.height)
                } else {
                    y
                };

                if !*is_set.borrow() || (xpos, ypos) != window.get_position() {
                    *is_set.borrow_mut() = true;
                    window.move_(xpos, ypos);
                    if reserve_space {
                        wm_util.set_padding(is_top, rect.height);
                    }
                    // set_strut crashes here :/
                }
            }
        ));

        // set .focused
        let focus_id = window.connect_enter_notify_event(clone!(container
            move |_, _| {
                if let Some(ctx) = container.get_style_context() {
                    StyleContextExt::add_class(&ctx, "focused");
                }
                Inhibit(false)
            })
        );
        let unfocus_id = window.connect_leave_notify_event(clone!(container
             move |_, _| {
                 if let Some(ctx) = container.get_style_context() {
                     StyleContextExt::remove_class(&ctx, "focused");
                 }
                 Inhibit(false)
             })
        );

        let event_ids = vec![size_id, focus_id, unfocus_id];

        // show window (needs to do this at least once)
        window.show_all();
        if config.get_bool_or("hidden", false) {
            window.hide();
        }

        // create Bar
        let bar = Bar {
            config,
            components: Vec::new(),
            overlay,
            container,
            window,
            event_ids,
        };

        if is_new && bar.config.get_bool_or("disable-shadow", true) {
            wm::gtk::disable_shadow(&bar.window);
        }

        // TODO: do this after load_components
        if reserve_space {
            wm::gtk::set_strut(
                &bar.window,
                is_top,
                Rectangle {
                    x: monitor.x,
                    y: monitor.y,
                    width: monitor.width,
                    height: bar.window.get_size().1,
                },
            );
        }

        bar
    }

    fn unload(&self) {
        // destroy components
        for component in self.components.iter() {
            component.destroy();
        }
        // remove events
        let window = self.window.clone();
        self.event_ids.iter().for_each(move |id| {
            // immutable signal copy
            window.disconnect(from_glib(id.to_glib()));
        });
        // remove widgets
        self.window.get_children().iter().for_each(|w| w.destroy());
    }

}

impl wm::Window for Bar {
    fn destroy(&self) {
        self.unload();
        self.window.destroy();
    }

    fn show(&self) {
        self.window.show();
    }

    fn hide(&self) {
        self.window.hide();
    }

    fn relayout(&self) {
        self.window.resize(1, 1);
    }

    fn to_window(&self) -> Window {
        self.unload();
        self.window.clone()
    }

    fn get_container(&self) -> &gtk::Box {
        &self.container
    }

    fn get_overlay(&self) -> &gtk::Overlay {
        &self.overlay
    }

    fn get_monitor_index(&self) -> usize {
        self.config.get_int_or("monitor", 0) as _
    }

    fn add_component(&mut self, component: Box<dyn Component>) {
        self.components.push(component);
    }

    fn load_component(&mut self, config: ConfigGroup, container: &gtk::Box, wm_util: &wm::WMUtil) {
        load_component(ComponentParams {
            container,
            config,
            window: Box::new(self),
            wm_util,
        });
    }

    fn matches_selectors(&self, selectors: &Selectors) -> bool {
        selectors.contains_id(&self.config.name) || {
            let class = self.config.get_string("class");
            class.is_some() && selectors.contains_class(&class.unwrap())
        }
    }
}

