use tiled::Map;

use crate::data::{get_map_tile, load_map_file};
use crate::game::constants::{MAP_FILE_PATH, TILES_PCS_H, TILES_PCS_W};
use crate::shaders::TileMapData;

const TILEMAP_BUF_LENGTH: usize = TILES_PCS_H * TILES_PCS_H;
const QUARTER_BUF_LENGTH: usize = TILEMAP_BUF_LENGTH / 4;

fn calc_index(x_pos: usize, y_pos: usize) -> usize {
  (y_pos * TILES_PCS_W) + x_pos
}

fn populate_tile_map<'a>(tiles: &'a mut Vec<TileMapData>, map: &Map) -> &'a mut Vec<TileMapData> {
  for y_pos in 0..TILES_PCS_H {
    for x_pos in 0..TILES_PCS_W {
      let map_val = get_map_tile(map, 0, x_pos, y_pos) - 1;
      let idx = calc_index(x_pos, y_pos);

      if idx < QUARTER_BUF_LENGTH {
        tiles[idx] =
          TileMapData::new([map_val as f32, 0.0, 0.0, 0.0]);
      } else if idx < QUARTER_BUF_LENGTH * 2 {
        tiles[idx - QUARTER_BUF_LENGTH] =
          TileMapData::new([tiles[idx - QUARTER_BUF_LENGTH].data[0], map_val as f32, 0.0, 0.0]);
      } else if idx < QUARTER_BUF_LENGTH * 3 {
        tiles[idx - QUARTER_BUF_LENGTH * 2] =
          TileMapData::new([tiles[idx - QUARTER_BUF_LENGTH * 2].data[0], tiles[idx - QUARTER_BUF_LENGTH * 2].data[1], map_val as f32, 0.0]);
      } else {
        tiles[idx - QUARTER_BUF_LENGTH * 3] =
          TileMapData::new([tiles[idx - QUARTER_BUF_LENGTH * 3].data[0], tiles[idx - QUARTER_BUF_LENGTH * 3].data[1], tiles[idx - QUARTER_BUF_LENGTH * 3].data[2], map_val as f32]);
      }
    }
  }
  tiles
}

pub struct Terrain {
  pub tiles: Vec<TileMapData>,
  pub tile_sets: [Map; 1],
  pub curr_tile_set_idx: usize,
}

impl Terrain {
  pub fn new() -> Terrain {
    let mut map_data = Vec::with_capacity(TILEMAP_BUF_LENGTH);

    for _ in 0..TILEMAP_BUF_LENGTH {
      map_data.push(TileMapData::new_empty());
    }

    let map_a = load_map_file(MAP_FILE_PATH);

    Terrain {
      tiles: populate_tile_map(&mut map_data, &map_a).to_vec(),
      tile_sets: [map_a],
      curr_tile_set_idx: 0,
    }
  }
}

use crate::plan::AllocationSemantics;
use crate::plan::CopyContext;
use crate::util::{Address, ObjectReference};
use crate::vm::VMBinding;

/// VM-specific methods for object model.
///
/// MMTk requires *at least one byte* (or possibly a few bits in certain plans) for MMTk as per-object metadata.
/// MMTk currently assumes the available byte/bits are in the *header words* --
/// this is a strict requirement, and we are looking to revamp the design and support VMs that do not have header words for objects.
///
/// Note that depending on the selected GC plan, only a subset of the methods provided here will be used.
pub trait ObjectModel<VM: VMBinding> {
    /// The offset of the GC byte from the object reference, in number of bytes.
    ///
    /// Notes:
    ///  - This value is only effective when the `side_gc_header` feature of `mmtk-core` is set.
    ///  - It is recommanded that GC byte is the low-order byte of the word that contains it. \
    /// E.g. in a 64-bits little endian system, the recommanded offset is `8*K`.
    ///
    const GC_BYTE_OFFSET: isize = 0;

    /// Copy an object and return the address of the new object. Usually in the implementation of this method,
    /// `alloc_copy()` and `post_copy()` from a plan's [`CopyContext`](../trait.CopyContext.html) are used for copying.
    ///
    /// Arguments:
    /// * `from`: The address of the object to be copied.
    /// * `semantics`: The allocation semantic to use.
    /// * `copy_context`: The `CopyContext` for the GC thread.
    fn copy(
        from: ObjectReference,
        semantics: AllocationSemantics,
        copy_context: &mut impl CopyContext,
    ) -> ObjectReference;

    /// Copy an object. This is required
    /// for delayed-copy collectors such as compacting collectors. During the
    /// collection, MMTk reserves a region in the heap for an object as per
    /// requirements found from `ObjectModel` and then asks `ObjectModel` to
    /// determine what the object's reference will be post-copy. Return the address
    /// past the end of the copied object.
    ///
    /// Arguments:
    /// * `from`: The address of the object to be copied.
    /// * `to`: The target location.
    /// * `region: The start of the region that was reserved for this object.
    fn copy_to(from: ObjectReference, to: ObjectReference, region: Address) -> Address;

    /// Return the reference that an object will be referred to after it is copied
    /// to the specified region. Used in delayed-copy collectors such as compacting
    /// collectors.
    ///
    /// Arguments:
    /// * `from`: The object to be copied.
    /// * `to`: The region to be copied to.
    fn get_reference_when_copied_to(from: ObjectReference, to: Address) -> ObjectReference;

    /// Return the size used by an object.
    ///
    /// Arguments:
    /// * `object`: The object to be queried.
    fn get_current_size(object: ObjectReference) -> usize;

    /// Get the type descriptor for an object.
    ///
    /// FIXME: Do we need this? If so, determine lifetime, return byte[]
    ///
    /// Arguments:
    /// * `reference`: The object to be queried.
    fn get_type_descriptor(reference: ObjectReference) -> &'static [i8];

    /// Return the lowest address of the storage associated with an object.
    ///
    /// Arguments:
    /// * `object`: The object to be queried.
    fn object_start_ref(object: ObjectReference) -> Address;

    /// Return an address guaranteed to be inside the storage associated
    /// with an object.
    ///
    /// Arguments:
    /// * `object`: The object to be queried.
    // FIXME: this doesn't seem essential. E.g. `get_object_end_address` or `object_start_ref` can cover its functionality.
    fn ref_to_address(object: ObjectReference) -> Address;

    /// Dump debugging information for an object.
    ///
    /// Arguments:
    /// * `object`: The object to be dumped.
    fn dump_object(object: ObjectReference);
}

use super::cu_ast::{
    BinOp, BufferKind, Expr, Item, ParamDecl, ScalarTy, Stmt, TemplParam, TemplateArg, Ty, UnOp,
};
use crate::codegen::cu_ast::{GpuAddrSpace, Lit};
use std::fmt::Formatter;

// function cuda_fmt takes Formatter and recursively formats
// trait CudaFormat has function cuda_fmt so that cuda_fmt_vec can be implemented (alias for fmt_vec)
// implement Display for CuAst by calling cuda_fmt in fmt passing the formatter and completely handing
// over the computation

pub(super) fn print(program: &[Item]) -> String {
    use std::fmt::Write;

    let mut code = String::new();
    for i in program {
        let res = writeln!(&mut code, "{}", i);
        if res.is_err() {
            panic!("{:?}", res);
        }
    }
    clang_format(&code)
}

fn clang_format(code: &str) -> String {
    use std::io::Write;
    use std::process::{Command, Stdio};
    let mut clang_fmt_cmd = Command::new("clang-format")
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .expect("failed to execute `clang-format`");
    if let Some(mut stdin) = clang_fmt_cmd.stdin.take() {
        stdin
            .write_all(code.as_bytes())
            .expect("Could not write to standard input stream.")
    }
    let clang_fmt_output = clang_fmt_cmd
        .wait_with_output()
        .expect("failed to execute `clang-format`");
    String::from_utf8(clang_fmt_output.stdout).expect("cannot read clang-format output as String")
}

impl std::fmt::Display for Item {
    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
        match self {
            Item::Include(path) => write!(f, "#include \"{}\"", path),
            Item::FunDef {
                name,
                templ_params,
                params,
                ret_ty,
                body,
                is_dev_fun,
            } => {
                if !templ_params.is_empty() {
                    write!(f, "template<")?;
                    fmt_vec(f, templ_params, ", ")?;
                    writeln!(f, ">")?;
                }
                writeln!(
                    f,
                    "{}auto {}(",
                    if *is_dev_fun { "__device__ " } else { "" },
                    name
                )?;
                fmt_vec(f, params, ",\n")?;
                writeln!(f, "\n) -> {} {{", ret_ty)?;
                write!(f, "{}", body)?;
                writeln!(f, "\n}}")
            }
        }
    }
}

impl std::fmt::Display for Stmt {
    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
        use Stmt::*;
        match self {
            Skip => Ok(()),
            VarDecl {
                name,
                ty,
                addr_space,
                expr,
            } => {
                if let Some(addrs) = addr_space {
                    write!(f, "{} ", addrs)?;
                }
                write!(f, "{} {}", ty, name)?;
                if let Ty::CArray(_, n) = ty {
                    write!(f, "[{}]", n)?;
                }
                if let Some(expr) = expr {
                    write!(f, " = {}", expr)?;
                }
                write!(f, ";")
            }
            Block(stmt) => {
                writeln!(f, "{{")?;
                writeln!(f, "{}", stmt)?;
                write!(f, "}}")
            }
            Seq(stmt) => {
                let (last, leading) = stmt.split_last().unwrap();
                for stmt in leading {
                    writeln!(f, "{}", stmt)?;
                }
                write!(f, "{}", last)
            }
            Expr(expr) => {
                if let super::cu_ast::Expr::Empty = expr {
                    Ok(())
                } else {
                    write!(f, "{};", expr)
                }
            }
            If { cond, body } => {
                writeln!(f, "if ({})", cond)?;
                write!(f, "{}", body)
            }
            IfElse {
                cond,
                true_body,
                false_body,
            } => {
                write!(f, "if ({}) ", cond)?;
                write!(f, "{} else {}", true_body, false_body)
            }
            While { cond, stmt } => {
                writeln!(f, "while ({})", cond)?;
                write!(f, "{}", stmt)
            }
            ForLoop {
                init,
                cond,
                iter,
                stmt,
            } => write!(f, "for ({} {}; {}) {}", init, cond, iter, stmt),
            Label(l) => write!(f, "{}:", l),
            Return(expr) => {
                write!(f, "return")?;
                if let Some(e) = expr {
                    write!(f, " {}", e)?;
                }
                write!(f, ";")
            }
        }
    }
}

impl std::fmt::Display for Expr {
    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
        use Expr::*;
        match self {
            Empty => Ok(()),
            Ident(name) => write!(f, "{}", name),
            Lit(l) => write!(f, "{}", l),
            Assign {
                lhs: l_val,
                rhs: r_val,
            } => write!(f, "{} = {}", l_val, r_val),
            Lambda {
                params,
                body,
                ret_ty,
                is_dev_fun,
            } => {
                let dev_qual = if *is_dev_fun { "__device__" } else { "" };
                writeln!(f, "[] {} (", dev_qual)?;
                fmt_vec(f, &params, ",\n")?;
                writeln!(f, ") -> {} {{", ret_ty)?;
                writeln!(f, "{}", &body)?;
                write!(f, "}}")
            }
            FunCall {
                fun,
                template_args,
                args,
            } => {
                write!(f, "{}", fun)?;
                if !template_args.is_empty() {
                    write!(f, "<")?;
                    fmt_vec(f, template_args, ", ")?;
                    write!(f, ">")?;
                }
                write!(f, "(")?;
                fmt_vec(f, args, ", ")?;
                write!(f, ")")
            }
            UnOp { op, arg } => write!(f, "{}{}", op, arg),
            BinOp { op, lhs, rhs } => write!(f, "{} {} {}", lhs, op, rhs),
            ArraySubscript { array, index } => write!(f, "{}[{}]", array, index),
            Proj { tuple, n } => write!(f, "{}.{}", tuple, n),
            InitializerList { elems } => {
                write!(f, "{{")?;
                fmt_vec(f, elems, ", ")?;
                write!(f, "}}")
            }
            Ref(expr) => write!(f, "&{}", expr),
            Deref(expr) => write!(f, "*{}", expr),
            Tuple(elems) => {
                write!(f, "descend::tuple{{")?;
                fmt_vec(f, elems, ", ")?;
                write!(f, "}}")
            }
            Nat(n) => write!(f, "{}", n),
        }
    }
}

impl std::fmt::Display for Lit {
    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
        match self {
            Lit::Bool(b) => write!(f, "{}", b),
            Lit::I32(i) => write!(f, "{}", i),
            Lit::U32(u) => write!(f, "{}", u),
            Lit::F32(fl) => write!(f, "{}", fl),
        }
    }
}

impl std::fmt::Display for ParamDecl {
    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
        write!(f, "{} {}", self.ty, self.name)
    }
}

impl std::fmt::Display for TemplateArg {
    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
        match self {
            TemplateArg::Expr(expr) => write!(f, "{}", expr),
            TemplateArg::Ty(ty) => write!(f, "{}", ty),
        }
    }
}

impl std::fmt::Display for TemplParam {
    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
        match self {
            TemplParam::Value { param_name, ty } => write!(f, "{} {}", ty, param_name),
            TemplParam::TyName { name } => write!(f, "typename {}", name),
        }
    }
}

impl std::fmt::Display for UnOp {
    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Not => write!(f, "!"),
            Self::Neg => write!(f, "-"),
        }
    }
}

impl std::fmt::Display for BinOp {
    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
        let str = match self {
            Self::Add => "+",
            Self::Sub => "-",
            Self::Mul => "*",
            Self::Div => "/",
            Self::Mod => "%",
            Self::And => "&&",
            Self::Or => "||",
            Self::Eq => "==",
            Self::Lt => "<",
            Self::Le => "<=",
            Self::Gt => ">",
            Self::Ge => ">=",
            Self::Neq => "!=",
        };
        write!(f, "{}", str)
    }
}

impl std::fmt::Display for GpuAddrSpace {
    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
        match self {
            GpuAddrSpace::Global => write!(f, ""),
            GpuAddrSpace::Shared => write!(f, "__shared__"),
            GpuAddrSpace::Constant => write!(f, "__constant__"),
        }
    }
}

impl std::fmt::Display for Ty {
    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
        use Ty::*;
        match self {
            // TODO print __restrict__
            Ptr(ty, Some(addr_space)) => write!(f, "{} {} *", addr_space, ty),
            Ptr(ty, None) => write!(f, "{} *", ty),
            PtrConst(ty, Some(addr_space)) => write!(f, "{} const {} *", addr_space, ty),
            PtrConst(ty, None) => write!(f, "const {} *", ty),
            Const(ty) => match ty.as_ref() {
                Ptr(_, _) => write!(f, "{} const", ty),
                PtrConst(_, _) => write!(f, "{} const", ty),
                _ => write!(f, "const {}", ty),
            },
            Array(ty, size) => write!(f, "descend::array<{}, {}>", ty, size),
            // Does not print the entire type because that would be impossible since C arrays
            //  are declared by appending the size to a variable.
            CArray(ty, _) => write!(f, "{}", ty),
            Tuple(tys) => {
                write!(f, "descend::tuple<")?;
                fmt_vec(f, tys, ", ")?;
                write!(f, ">")
            }
            Buffer(ty, buff_kind) => match buff_kind {
                BufferKind::CpuHeap => write!(f, "HeapBuffer<{}>", ty),
                BufferKind::GpuGlobal => write!(f, "GpuBuffer<{}>", ty),
                BufferKind::Ident(name) => write!(f, "{}", name),
            },
            Scalar(sty) => write!(f, "{}", sty),
            Atomic(at) => write!(f, "descend::Atomic<{}>", at),
            Ident(name) => write!(f, "{}", name),
        }
    }
}

impl std::fmt::Display for ScalarTy {
    fn fmt(&self, f: &mut Formatter<'_>) -> std::fmt::Result {
        use ScalarTy::*;
        match self {
            Auto => write!(f, "auto"),
            Void => write!(f, "void"),
            I32 => write!(f, "descend::i32"),
            U32 => write!(f, "descend::u32"),
            F32 => write!(f, "descend::f32"),
            SizeT => write!(f, "std::size_t"),
            Bool => write!(f, "bool"),
            Memory => write!(f, "descend::Memory"),
            Gpu => write!(f, "descend::Gpu"),
        }
    }
}

fn fmt_vec<D: std::fmt::Display>(f: &mut Formatter<'_>, v: &[D], sep: &str) -> std::fmt::Result {
    if let Some((last, leading)) = v.split_last() {
        for p in leading {
            write!(f, "{}{}", p, sep)?;
        }
        write!(f, "{}", last)
    } else {
        Ok(())
    }
}

