use crate::{
    common::JorupConfig,
    utils::{blockchain::Blockchain, runner::RunnerControl},
};
use structopt::StructOpt;
use thiserror::Error;

/// Get running node's info
#[derive(Debug, StructOpt)]
pub struct Command {
    /// The blockchain to run jormungandr for
    blockchain: String,
}

#[derive(Debug, Error)]
pub enum Error {
    #[error("Cannot run the node without valid blockchain")]
    NoValidBlockchain(#[source] crate::utils::blockchain::Error),
    #[error("Unable to start the runner controller")]
    CannotStartRunnerController(#[source] crate::utils::runner::Error),
    #[error("Cannot collect node's info")]
    CannotCollectInfo(#[source] crate::utils::runner::Error),
}

impl Command {
    pub fn run(self, mut cfg: JorupConfig) -> Result<(), Error> {
        let blockchain =
            Blockchain::load(&mut cfg, &self.blockchain).map_err(Error::NoValidBlockchain)?;
        blockchain.prepare().map_err(Error::NoValidBlockchain)?;

        let mut runner =
            RunnerControl::load(&blockchain).map_err(Error::CannotStartRunnerController)?;

        runner.settings().map_err(Error::CannotCollectInfo)?;
        runner.info().map_err(Error::CannotCollectInfo)
    }
}

use std::time::{Duration, UNIX_EPOCH};

use chrono::{DateTime, Utc};

use yahoo_finance_api as yahoo;

#[cfg(not(feature = "blocking"))]
#[tokio::main]
async fn main() {
    let conn   = yahoo::YahooConnector::new();
    let ticker = "TSLA";
    let start  = DateTime::parse_from_rfc3339("2020-08-28T00:00:00.00Z").unwrap().with_timezone(&Utc);
    let end    = DateTime::parse_from_rfc3339("2020-09-02T00:00:00.00Z").unwrap().with_timezone(&Utc);
    let hist  = conn.get_quote_history(ticker, start, end).await.unwrap();

    // Get the clean history
    println!("{}", ticker);
    println!("QUOTES");
    for quote in hist.quotes().unwrap() {
        let time = DateTime::<Utc>::from(UNIX_EPOCH + Duration::from_secs(quote.timestamp));
        println!("{} | {:.2} | {:.2}", time, quote.open, quote.close);
    }

    // Get any splits that occured during the requested period
    println!("SPLITS");
    for split in hist.splits().unwrap() {
        let date = DateTime::<Utc>::from(UNIX_EPOCH + Duration::from_secs(split.date));
        println!("{} | {} : {}", date, split.numerator, split.denominator);
    }
}

