//! Module for IO of the gcode file format

use crate::*;

use std::{
    fmt,
    io::{BufRead, Error as ioError},
    iter::FusedIterator,
    marker::PhantomData,
};

use super::{types::*, utils::*};

//------------------------------------------------------------------------------

/// Iterator to incrementally load a .gcode file
pub struct GcodeIterator<P, R>
where
    P: IsBuildable3D,
    R: BufRead,
{
    read: R,
    is_done: bool,
    i_line: usize,
    line_buffer: Vec<u8>,
    //start_pushed: bool, //@todo this was removed, why always push 0/0/0?
    ra: RelativeAbsolute,
    x: f64,
    y: f64,
    z: f64,
    phantom_p: PhantomData<P>,
}

impl<P, R> GcodeIterator<P, R>
where
    P: IsBuildable3D,
    R: BufRead,
{
    pub fn new(read: R) -> Self {
        Self {
            read,
            is_done: false,
            i_line: 0,
            line_buffer: Vec::new(),
            //start_pushed: false, //@todo this was removed, why always push 0/0/0?
            ra: RelativeAbsolute::Absolute,
            x: 0.0,
            y: 0.0,
            z: 0.0,
            phantom_p: PhantomData,
        }
    }
}

impl<P, R> Iterator for GcodeIterator<P, R>
where
    P: IsBuildable3D,
    R: BufRead,
{
    type Item = GcodeResult<P>;
    #[inline(always)]
    fn next(&mut self) -> Option<Self::Item> {
        if self.is_done {
            return None;
        }
        while let Ok(line) = fetch_line(&mut self.read, &mut self.line_buffer) {
            self.i_line += 1;

            if line.len() >= 4 && line[0] == b'G' {
                if line[2] == b' ' && (line[1] == b'1' || line[1] == b'2' || line[1] == b'3') {
                    // Move according to absolute/relative
                    let mut any_changed = false;
                    match command(&line[3..])
                        .ok_or(GcodeError::Command)
                        .line(self.i_line, line)
                    {
                        Err(e) => {
                            self.is_done = true;
                            return Some(Err(e));
                        }
                        Ok([opt_x, opt_y, opt_z]) => {
                            if let Some(new_x) = opt_x {
                                any_changed = true;
                                match self.ra {
                                    RelativeAbsolute::Absolute => self.x = new_x,
                                    RelativeAbsolute::Relative => self.x += new_x,
                                }
                            }

                            if let Some(new_y) = opt_y {
                                any_changed = true;
                                match self.ra {
                                    RelativeAbsolute::Absolute => self.y = new_y,
                                    RelativeAbsolute::Relative => self.y += new_y,
                                }
                            }

                            if let Some(new_z) = opt_z {
                                any_changed = true;
                                match self.ra {
                                    RelativeAbsolute::Absolute => self.z = new_z,
                                    RelativeAbsolute::Relative => self.z += new_z,
                                }
                            }

                            if any_changed {
                                return Some(Ok(P::new(self.x, self.y, self.z)));
                            }
                        }
                    }
                } else if line[1] == b'9' && line[3] == b' ' {
                    // G9x
                    if line[2] == b'0' {
                        // G90
                        self.ra = RelativeAbsolute::Absolute;
                    } else if line[2] == b'1' {
                        // G91
                        self.ra = RelativeAbsolute::Relative;
                    } else if line[2] == b'2' {
                        // G92
                        // Move according absolute
                        let mut any_changed = false;
                        match command(&line[4..])
                            .ok_or(GcodeError::Command)
                            .line(self.i_line, line)
                        {
                            Err(e) => {
                                self.is_done = true;
                                return Some(Err(e));
                            }
                            Ok([opt_x, opt_y, opt_z]) => {
                                if let Some(new_x) = opt_x {
                                    any_changed = true;
                                    self.x = new_x
                                }

                                if let Some(new_y) = opt_y {
                                    any_changed = true;
                                    self.y = new_y
                                }

                                if let Some(new_z) = opt_z {
                                    any_changed = true;
                                    self.z = new_z
                                }

                                if any_changed {
                                    return Some(Ok(P::new(self.x, self.y, self.z)));
                                }
                            }
                        }
                    }
                }
            }
        }
        self.is_done = true;

        None
    }
}

impl<P, R> FusedIterator for GcodeIterator<P, R>
where
    P: IsBuildable3D,
    R: BufRead,
{
}

//------------------------------------------------------------------------------

/// Loads a IsPushable<Is3D> as x y z coordinates from gcode
pub fn load_gcode_points<IP, P, R>(read: R, ip: &mut IP) -> GcodeResult<()>
where
    IP: IsPushable<P>,
    P: IsBuildable3D,
    R: BufRead,
{
    let iterator = GcodeIterator::new(read);

    for p in iterator {
        ip.push(p?)
    }

    Ok(())
}

//------------------------------------------------------------------------------

fn command(line: &[u8]) -> Option<[Option<f64>; 3]> {
    let mut n_found = 0;
    let mut x = None;
    let mut y = None;
    let mut z = None;
    let words = line.split(|x| *x == b' ');

    for word in words {
        if n_found == 3 {
            break;
        }

        let n = word.len();

        if n == 0 {
            continue;
        }

        if word[0] == b';' {
            break;
        }

        if n < 2 {
            continue;
        }

        match word[0] {
            b'X' => {
                x = Some(from_ascii(&word[1..])?);
                n_found += 1
            }
            b'Y' => {
                y = Some(from_ascii(&word[1..])?);
                n_found += 1
            }
            b'Z' => {
                z = Some(from_ascii(&word[1..])?);
                n_found += 1
            }
            _ => (),
        }
    }

    Some([x, y, z])
}

enum RelativeAbsolute {
    Relative,
    Absolute,
}

/// Error type for .gcode file operations
pub enum GcodeError {
    AccessFile,
    Command,
}

/// Result type for .gcode file operations
pub type GcodeResult<T> = IOResult<T, GcodeError>;

impl fmt::Debug for GcodeError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            Self::Command => write!(f, "Unable to parse command"),
            Self::AccessFile => write!(f, "Unable to access file"),
        }
    }
}

impl fmt::Display for GcodeError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "{:?}", self)
    }
}

impl From<ioError> for GcodeError {
    fn from(_error: ioError) -> Self {
        GcodeError::AccessFile
    }
}

use std::path::Path;

use dprint_cli_core::types::ErrBox;

use crate::environment::Environment;
use crate::utils::{is_absolute_pattern, is_negated_glob, to_absolute_glob, to_absolute_globs, GlobMatcher, GlobMatcherOptions};

use super::configuration::ResolvedConfig;
use super::CliArgs;

pub struct FileMatcher {
  glob_matcher: GlobMatcher,
}

impl FileMatcher {
  pub fn new(config: &ResolvedConfig, args: &CliArgs, environment: &impl Environment) -> Result<Self, ErrBox> {
    let cwd = environment.cwd();
    let cwd_str = cwd.to_string_lossy();
    let patterns = get_all_file_patterns(config, args, &cwd_str);
    let glob_matcher = GlobMatcher::new(
      &patterns,
      &GlobMatcherOptions {
        // issue on windows where V:/ was not matching for pattern with v:/
        case_insensitive: true,
      },
    )?;

    Ok(FileMatcher { glob_matcher })
  }

  pub fn matches(&self, file_path: &Path) -> bool {
    let mut file_path = file_path.to_string_lossy().to_string();
    process_file_pattern_slashes(&mut file_path);
    self.glob_matcher.is_match(&file_path)
  }
}

pub fn get_all_file_patterns(config: &ResolvedConfig, args: &CliArgs, cwd: &str) -> Vec<String> {
  let mut file_patterns = get_include_file_patterns(config, args, cwd);
  file_patterns.append(&mut get_exclude_file_patterns(config, args, cwd));
  return file_patterns;
}

fn get_include_file_patterns(config: &ResolvedConfig, args: &CliArgs, cwd: &str) -> Vec<String> {
  let mut file_patterns = Vec::new();

  file_patterns.extend(if args.file_patterns.is_empty() {
    to_absolute_globs(
      process_config_patterns(process_file_patterns_slashes(&config.includes)),
      &config.base_path.to_string_lossy(),
    )
  } else {
    // resolve CLI patterns based on the current working directory
    to_absolute_globs(process_cli_patterns(process_file_patterns_slashes(&args.file_patterns)), cwd)
  });

  return file_patterns;
}

fn get_exclude_file_patterns(config: &ResolvedConfig, args: &CliArgs, cwd: &str) -> Vec<String> {
  let mut file_patterns = Vec::new();

  file_patterns.extend(
    if args.exclude_file_patterns.is_empty() {
      to_absolute_globs(
        process_config_patterns(process_file_patterns_slashes(&config.excludes)),
        &config.base_path.to_string_lossy(),
      )
    } else {
      // resolve CLI patterns based on the current working directory
      to_absolute_globs(process_cli_patterns(process_file_patterns_slashes(&args.exclude_file_patterns)), cwd)
    }
    .into_iter()
    .map(|exclude| if exclude.starts_with("!") { exclude } else { format!("!{}", exclude) }),
  );

  if !args.allow_node_modules {
    // glob walker will not search the children of a directory once it's ignored like this
    let node_modules_exclude = String::from("!**/node_modules");
    let exclude_node_module_patterns = vec![
      to_absolute_glob(&node_modules_exclude, cwd),
      to_absolute_glob(&node_modules_exclude, &config.base_path.to_string_lossy()),
    ];
    for node_modules_exclude in exclude_node_module_patterns {
      if !file_patterns.contains(&node_modules_exclude) {
        file_patterns.push(node_modules_exclude);
      }
    }
  }
  return file_patterns;
}

fn process_file_patterns_slashes(file_patterns: &Vec<String>) -> Vec<String> {
  file_patterns
    .iter()
    .map(|p| {
      let mut p = p.to_string();
      process_file_pattern_slashes(&mut p);
      p
    })
    .collect()
}

fn process_file_pattern_slashes(file_pattern: &mut String) {
  // Convert all backslashes to forward slashes.
  // It is true that this means someone cannot specify patterns that
  // match files with backslashes in their name on Linux, however,
  // it is more desirable for this CLI to work the same way no matter
  // what operation system the user is on and for the CLI to match
  // backslashes as a path separator.
  *file_pattern = file_pattern.replace("\\", "/");
}

fn process_cli_patterns(file_patterns: Vec<String>) -> Vec<String> {
  file_patterns.into_iter().map(|pattern| process_cli_pattern(pattern)).collect()
}

fn process_cli_pattern(file_pattern: String) -> String {
  if is_absolute_pattern(&file_pattern) {
    file_pattern
  } else if file_pattern.starts_with("./") || file_pattern.starts_with("!./") {
    file_pattern
  } else {
    // make all cli specified patterns relative
    if is_negated_glob(&file_pattern) {
      format!("!./{}", &file_pattern[1..])
    } else {
      format!("./{}", file_pattern)
    }
  }
}

fn process_config_patterns(file_patterns: Vec<String>) -> Vec<String> {
  file_patterns.into_iter().map(|pattern| process_config_pattern(pattern)).collect()
}

fn process_config_pattern(file_pattern: String) -> String {
  // make config patterns that start with `/` be relative
  if file_pattern.starts_with("/") {
    format!(".{}", file_pattern)
  } else if file_pattern.starts_with("!/") {
    format!("!.{}", &file_pattern[1..])
  } else {
    file_pattern
  }
}

#[cfg(test)]
mod test {
  use super::*;

  #[test]
  fn it_should_process_cli_pattern() {
    assert_eq!(process_cli_pattern("/test".to_string()), "/test");
    assert_eq!(process_cli_pattern("C:/test".to_string()), "C:/test");
    assert_eq!(process_cli_pattern("./test".to_string()), "./test");
    assert_eq!(process_cli_pattern("test".to_string()), "./test");
    assert_eq!(process_cli_pattern("**/test".to_string()), "./**/test");

    assert_eq!(process_cli_pattern("!/test".to_string()), "!/test");
    assert_eq!(process_cli_pattern("!C:/test".to_string()), "!C:/test");
    assert_eq!(process_cli_pattern("!./test".to_string()), "!./test");
    assert_eq!(process_cli_pattern("!test".to_string()), "!./test");
    assert_eq!(process_cli_pattern("!**/test".to_string()), "!./**/test");
  }

  #[test]
  fn it_should_process_config_pattern() {
    assert_eq!(process_config_pattern("/test".to_string()), "./test");
    assert_eq!(process_config_pattern("./test".to_string()), "./test");
    assert_eq!(process_config_pattern("test".to_string()), "test");
    assert_eq!(process_config_pattern("**/test".to_string()), "**/test");

    assert_eq!(process_config_pattern("!/test".to_string()), "!./test");
    assert_eq!(process_config_pattern("!./test".to_string()), "!./test");
    assert_eq!(process_config_pattern("!test".to_string()), "!test");
    assert_eq!(process_config_pattern("!**/test".to_string()), "!**/test");
  }
}

//! Small example program that retrieves the information for an entity's upload.
//!
//! For this to work you must set 3 env
//! vars, `SG_SERVER`, `SG_SCRIPT_NAME`, and `SG_SCRIPT_KEY`.
//!
//! Set the `SG_SERVER` environment variable to the url for your ShotGrid server, eg:
//!
//! ```text
//! export SG_SERVER=https://shotgrid.example.com
//! ```
//!
//! `shotgrid_rs` also looks at the `CA_BUNDLE` environment variable for when
//! you need a custom CA loaded to access your ShotGrid server, for example:
//!
//! ```text
//! export CA_BUNDLE=/etc/ssl/my-ca-certs.crt
//! ```
//!
//! Usage:
//!
//! ```text
//! $ cargo run --example upload note 12345 tester path/to/file.ext [optional display name]
//! ```

use shotgrid_rs::Client;
use std::env;
use std::path::PathBuf;

#[tokio::main]
async fn main() -> shotgrid_rs::Result<()> {
    dotenv::dotenv().ok();

    let server = env::var("SG_SERVER").expect("SG_SERVER");
    let script_name = env::var("SG_SCRIPT_NAME").expect("SG_SCRIPT_NAME");
    let script_key = env::var("SG_SCRIPT_KEY").expect("SG_SCRIPT_KEY");

    let entity = env::args().nth(1).unwrap();
    let entity_id: i32 = env::args()
        .nth(2)
        .map(|s| s.parse().expect("Entity ID"))
        .expect("Entity ID");
    let file_path: PathBuf = env::args().nth(3).expect("File Path").into();
    let display_name = env::args().nth(4);

    let sg = Client::new(server, Some(&script_name), Some(&script_key)).expect("SG Client");
    let session = sg.authenticate_script().await?;
    let fh = std::fs::OpenOptions::new()
        .read(true)
        .open(&file_path)
        .unwrap();

    let filename = file_path.file_name().as_ref().unwrap().to_string_lossy();

    session
        .upload(&entity, entity_id, Some("attachments"), &filename)
        .display_name(display_name)
        .send(fh)
        .await?;

    Ok(())
}

use std::rc::Rc;
use std::cell::RefCell;
use std::any::{Any, TypeId};
use std::collections::HashMap;

use super::glwrap::Program;


thread_local! {
	static SHARED_DATA: RefCell<SharedData> = RefCell::new(SharedData::new());
}


pub struct SharedData {
	data: HashMap<(TypeId, String), Rc<dyn Any>>,
}

impl SharedData {

	fn new() -> SharedData {
		SharedData {
			data: HashMap::new(),
		}
	}

	pub fn get<T: Any>(name: &str) -> Option<Rc<T>> {
		// Check if the shared data exists
		let res = SHARED_DATA.with(|sd| {
			if let Some(v) = sd.borrow().data.get(&(TypeId::of::<T>(), String::from(name))) {
				Some(Rc::clone(v))
			}
			else {
				None
			}
		});

		if let Some(v) = res {
			Some(v.downcast::<T>().unwrap())
		}
		else {
			None
		}
	}

	pub fn add<T: Any>(name: &str, v: T) -> Rc<T> {
		// Add a shared data
		let rc: Rc<dyn Any> = Rc::new(v);

		SHARED_DATA.with(|sd| {
			sd.borrow_mut().data.insert((TypeId::of::<T>(), String::from(name)), Rc::clone(&rc));
		});

		rc.downcast::<T>().unwrap()
	}

	pub fn get_or<T: Any, F>(name: &str, make: F) -> Rc<T>
	where
		F: FnOnce() -> T
	{
		// Try to get, otherwise call the function to make and add
		if let Some(r) = SharedData::get(name) {
			r
		}
		else {
			SharedData::add(name, make())
		}
	}

	pub fn clear() {
		// Clear all the data

		// To avoid problems with possible double-borrows, replace the content of
		// the RefCell with a new, empty SharedData, and clear after
		let mut sd = SHARED_DATA.with(|sd| {
			sd.replace(SharedData::new())
		});

		sd.data.clear();
	}

	//
	// Built-in data
	//

	pub fn program_grid() -> Rc<Program> {
		SharedData::get_or("built_in*grid_program", || {
			Program::from_sources(
				include_str!("../shaders/grid.vert"),
				include_str!("../shaders/grid.frag"),
			).unwrap()
		})
	}

	pub fn program_quad() -> Rc<Program> {
		SharedData::get_or("built_in*quad_program", || {
			Program::from_sources(
				include_str!("../shaders/quad.vert"),
				include_str!("../shaders/quad.frag"),
			).unwrap()
		})
	}

	pub fn program_simplequad() -> Rc<Program> {
		SharedData::get_or("built_in*simplequad_program", || {
			Program::from_sources(
				include_str!("../shaders/simplequad.vert"),
				include_str!("../shaders/simplequad.frag"),
			).unwrap()
		})
	}

	pub fn program_rect() -> Rc<Program> {
		SharedData::get_or("built_in*rect_program", || {
			Program::from_sources(
				include_str!("../shaders/rect.vert"),
				include_str!("../shaders/rect.frag"),
			).unwrap()
		})
	}
}

use crate::runtime::engine::Engine;
use crate::runtime::error::Error;
use crate::runtime::gc::{ GcRef, GcTrace };
use crate::runtime::primitives::{ Array, Class };
use crate::runtime::r#return::Return;
use crate::runtime::utilities::variable::Variable;
use crate::runtime::value::Value;

pub struct Parameters<'a> {
    elements: Box<[Variable<'a>]>,
    rest: Option<Variable<'a>>,
}

impl<'a> Parameters<'a> {
    pub fn new(elements: Box<[Variable<'a>]>, rest: Option<Variable<'a>>) -> Self {
        Self {
            elements,
            rest,
        }
    }

    pub fn get_rest_array(&self, engine: &Engine<'a>) -> Option<GcRef<Class<'a>>> {
        self.rest.as_ref()
            .and_then(|parameter| parameter.r#type)
            .and_then(|class| class.is_generic(engine.environment.array).then_some(class))
    }

    pub fn get_rest_array_type(&self, engine: &Engine<'a>) -> Option<GcRef<Class<'a>>> {
        self.get_rest_array(engine).map(|class| class.constructor().unwrap().arguments[0].get_gc::<Class>(engine))
    }

    pub fn validate(&self, engine: &Engine<'a>, arguments: &[Value<'a>]) -> Return<()> {
        let condition = if self.rest.is_some() {
            arguments.len() < self.elements.len()
        } else {
            arguments.len() != self.elements.len()
        };

        if condition {
            return Err(error_arguments(self.elements.len(), arguments.len()));
        }

        for (parameter, argument) in self.elements.iter().zip(arguments.iter().copied()) {
            parameter.check(argument)?;
        }

        if let Some(r#type) = self.get_rest_array_type(engine) {
            for argument in arguments[self.elements.len()..].iter().copied() {
                argument.cast(r#type)?;
            }
        }

        Ok(())
    }

    pub fn build(&self, engine: &mut Engine<'a>, arguments: &[Value<'a>]) {
        for (parameter, argument) in self.elements.iter().zip(arguments.iter().copied()) {
            parameter.build(engine).set_value(argument);
        }

        if let Some(parameter) = self.rest.as_ref() {
            let elements = arguments[self.elements.len()..].iter()
                .copied()
                .map(|argument| engine.new_reference(argument))
                .collect();

            let array = if let Some(class) = self.get_rest_array(engine) {
                engine.new_array_value(class, elements)
            } else {
                engine.new_array_any_value(elements)
            };

            parameter.build(engine).set_value(array);
        }
    }
}

impl GcTrace for Parameters<'_> {
    fn trace(&mut self) {
        for element in self.elements.iter_mut() {
            element.trace();
        }

        if let Some(rest) = self.rest.as_mut() {
            rest.trace();
        }
    }
}

pub fn length(arguments: usize, parameters: usize) -> Return<()> {
    if arguments != parameters {
        return Err(error_arguments(parameters, arguments));
    }

    Ok(())
}

pub fn pack<'a>(engine: &mut Engine<'a>, values: &mut [Value<'a>]) -> Value<'a> {
    let elements = values.iter()
        .copied()
        .map(|value| engine.new_constant(value))
        .collect();

    engine.new_array_any_value(elements)
}

pub fn unpack<'a>(engine: &Engine<'a>, value: Value<'a>) -> Return<Box<[Value<'a>]>> {
    value.get_gn::<Array>(engine).elements().iter()
        .copied()
        .map(|element| element.read())
        .collect()
}

fn error_arguments(parameters: usize, arguments: usize) -> Error {
    Error::new_runtime(&format!("Provided {} arguments while the function expects {} parameters.", arguments, parameters))
}

use anyhow::Result;
use async_graphql::{Context, FieldResult, InputObject, Object, SimpleObject};

use dftk_common::models::speaker::{PartialSpeaker, Speaker, SpeakerId, SpeakerKey};
