use actix::prelude::*;
use std::io;
use flexbuffers;
use futures::io::Error;
use bytes::{BytesMut, BufMut, Buf};
use byteorder::{NetworkEndian, ByteOrder};
use serde::{Serialize, Deserialize};
use crate::remote::RemoteWrapper;
use tokio_util::codec::{Decoder, Encoder};

const PREFIX: &[u8] = b"ACTIX/1.0\r\n";
const ENDIAN_LENGTH: usize = 4;

#[derive(Message, Deserialize, Serialize)]
#[rtype(result = "()")]
pub enum ClusterMessage {
    Request(u16, bool), // bool = is_seed?
    Response,
    Message(RemoteWrapper),
    Decline
}

impl ClusterMessage {
    pub fn split(&self) -> (Vec<u8>, Vec<u8>) {
        (match &self {
            Self::Message(wrapper) => wrapper.message_buffer.clone(),
            _ => panic!("split should not be used if not ClusterMessage::Message")
        }, flexbuffers::to_vec(&self).unwrap())
    }

    pub fn set_buffer(&mut self, bytes: Vec<u8>) {
        match self {
            Self::Message(ref mut wrapper) => { wrapper.message_buffer = bytes },
            _ => panic!("set_buffer should not be used if not ClusterMessage::Message")
        }
    }
}

pub struct ConnectCodec {
    prefix: bool
}

impl ConnectCodec {
    pub fn new() -> ConnectCodec {
        ConnectCodec {prefix: false}
    }
}

impl Decoder for ConnectCodec {
    type Item = ClusterMessage;
    type Error = Error;

    fn decode(&mut self, src: &mut BytesMut) -> Result<Option<Self::Item>, Self::Error> {
        if !self.prefix {
            if src.len() < 11 {
                return Ok(None)
            }
            if &src[..11] == PREFIX {
                let _s = src.split_to(11);
                self.prefix = true;
            } else {
                return Err(io::Error::new(io::ErrorKind::Other, "Prefix mismatch"))
            }
        }

        let size = {
            if src.len() < ENDIAN_LENGTH {
                return Ok(None)
            }
            NetworkEndian::read_u32(src.as_ref()) as usize
        };

        if src.len() >= size + (ENDIAN_LENGTH * 2) {
            src.advance(ENDIAN_LENGTH);
            let header_size = NetworkEndian::read_u32(src.as_ref()) as usize;
            src.advance(ENDIAN_LENGTH);

            if size > header_size {
                let header = src.split_to(header_size);
                let buf = src.split_to(size - header_size);
                let mut cluster_message = flexbuffers::from_slice::<ClusterMessage>(&header).unwrap();
                cluster_message.set_buffer(buf.to_vec());
                Ok(Some(cluster_message))
            } else {
                let buf = src.split_to(size);
                Ok(Some(flexbuffers::from_slice::<ClusterMessage>(&buf).unwrap()))
            }
        } else {
            Ok(None)
        }
    }
}

impl Encoder<ClusterMessage> for ConnectCodec {
    type Error = Error;

    fn encode(&mut self, item: ClusterMessage, dst: &mut BytesMut) -> Result<(), Self::Error> {
        match &item {
            ClusterMessage::Request(_, _) => dst.extend_from_slice(PREFIX),
            ClusterMessage::Response => dst.extend_from_slice(PREFIX),
            ClusterMessage::Message(_) => {
                let (buffer, header) = item.split();
                let buffer_ref: &[u8] = buffer.as_ref();
                let header_ref: &[u8] = header.as_ref();

                dst.reserve(header_ref.len() + buffer_ref.len() + (ENDIAN_LENGTH * 2));
                dst.put_u32((header_ref.len() + buffer_ref.len()) as u32);
                dst.put_u32(header_ref.len() as u32);
                dst.put(header_ref);
                dst.put(buffer_ref);

                return Ok(());
            },
            _ => {}
        }

        let msg = flexbuffers::to_vec(&item).unwrap();

        let msg_ref: &[u8] = msg.as_ref();

        dst.reserve(msg_ref.len() + (ENDIAN_LENGTH * 2));
        dst.put_u32(msg_ref.len() as u32);
        dst.put_u32(msg_ref.len() as u32);
        dst.put(msg_ref);
        Ok(())
    }
}

use super::*;

use ciborium_io::Write;

/// An encoder for serializing CBOR items
///
/// This structure wraps a writer and provides convenience functions for
/// writing `Header` objects to the wire.
pub struct Encoder<W: Write>(W);

impl<W: Write> From<W> for Encoder<W> {
    #[inline]
    fn from(value: W) -> Self {
        Self(value)
    }
}

impl<W: Write> Write for Encoder<W> {
    type Error = W::Error;

    fn write_all(&mut self, data: &[u8]) -> Result<(), Self::Error> {
        self.0.write_all(data)
    }

    fn flush(&mut self) -> Result<(), Self::Error> {
        self.0.flush()
    }
}

impl<W: Write> Encoder<W> {
    /// Push a `Header` to the wire
    #[inline]
    pub fn push(&mut self, header: Header) -> Result<(), W::Error> {
        let title = Title::from(header);

        let major = match title.0 {
            Major::Positive => 0,
            Major::Negative => 1,
            Major::Bytes => 2,
            Major::Text => 3,
            Major::Array => 4,
            Major::Map => 5,
            Major::Tag => 6,
            Major::Other => 7,
        };

        let minor = match title.1 {
            Minor::This(x) => x,
            Minor::Next1(..) => 24,
            Minor::Next2(..) => 25,
            Minor::Next4(..) => 26,
            Minor::Next8(..) => 27,
            Minor::More => 31,
        };

        self.0.write_all(&[major << 5 | minor])?;
        self.0.write_all(title.1.as_ref())
    }

    /// Serialize a byte slice as CBOR
    ///
    /// Optionally, segment the output into `segment` size segments. Note that
    /// if `segment == Some(0)` it will be silently upgraded to `Some(1)`. This
    /// minimum value is highly inefficient and should not be relied upon.
    #[inline]
    pub fn bytes(
        &mut self,
        value: &[u8],
        segment: impl Into<Option<usize>>,
    ) -> Result<(), W::Error> {
        let max = segment.into().unwrap_or_else(|| value.len());
        let max = core::cmp::max(max, 1);

        if max >= value.len() {
            self.push(Header::Bytes(Some(value.len())))?;
            self.write_all(value)?;
        } else {
            self.push(Header::Bytes(None))?;

            for chunk in value.chunks(max) {
                self.push(Header::Bytes(Some(chunk.len())))?;
                self.write_all(chunk)?;
            }

            self.push(Header::Break)?;
        }

        Ok(())
    }

    /// Serialize a string slice as CBOR
    ///
    /// Optionally, segment the output into `segment` size segments. Note that
    /// since care is taken to ensure that each segment is itself a valid UTF-8
    /// string, if `segment` contains a value of less than 4, it will be
    /// silently upgraded to 4. This minimum value is highly inefficient and
    /// should not be relied upon.
    #[inline]
    pub fn text(&mut self, value: &str, segment: impl Into<Option<usize>>) -> Result<(), W::Error> {
        let max = segment.into().unwrap_or_else(|| value.len());
        let max = core::cmp::max(max, 4);

        if max >= value.len() {
            self.push(Header::Text(Some(value.len())))?;
            self.write_all(value.as_bytes())?;
        } else {
            self.push(Header::Text(None))?;

            let mut bytes = value.as_bytes();
            while !bytes.is_empty() {
                let mut len = core::cmp::min(bytes.len(), max);
                while len > 0 && core::str::from_utf8(&bytes[..len]).is_err() {
                    len -= 1
                }

                let (prefix, suffix) = bytes.split_at(len);
                self.push(Header::Text(Some(prefix.len())))?;
                self.write_all(prefix)?;
                bytes = suffix;
            }

            self.push(Header::Break)?;
        }

        Ok(())
    }
}

//! @ When node |cur_p| is a glue node, we look at |prev_p| to see whether or not
//! a breakpoint is legal at |cur_p|, as explained above.
//
// @<If node |cur_p| is a legal breakpoint, call...@>=
pub(crate) macro If_node_cur_p_is_a_legal_breakpoint__call_try_break__then_update_the_active_widths_by_including_the_glue_in_glue_ptr_cur_p($globals:expr, $prev_p:expr, $auto_breaking:expr) {{
    /// miscellaneous nodes of temporary interest
    let q: pointer;

    // if auto_breaking then
    if $auto_breaking {
        // begin if is_char_node(prev_p) then try_break(0,unhyphenated)
        if is_char_node!($globals, $prev_p) {
            try_break($globals, 0, unhyphenated.into())?;
        }
        // else if precedes_break(prev_p) then try_break(0,unhyphenated)
        else if precedes_break!($globals, $prev_p) {
            try_break($globals, 0, unhyphenated.into())?;
        }
        // else if (type(prev_p)=kern_node)and(subtype(prev_p)<>explicit) then
        else if r#type!($globals, $prev_p) == kern_node
            && subtype!($globals, $prev_p) as integer != kern_node_subtype::explicit as integer
        {
            // try_break(0,unhyphenated);
            try_break($globals, 0, unhyphenated.into())?;
        }
        // end;
    }
    // check_shrinkage(glue_ptr(cur_p)); q:=glue_ptr(cur_p);
    check_shrinkage!($globals, glue_ptr!($globals, $globals.cur_p));
    q = glue_ptr!($globals, $globals.cur_p);
    // act_width:=act_width+width(q);@|
    act_width!($globals) += width!($globals, q);
    // active_width[2+stretch_order(q)]:=@|
    //   active_width[2+stretch_order(q)]+stretch(q);@/
    $globals.active_width[2 + stretch_order!($globals, q)] += stretch!($globals, q);
    // active_width[6]:=active_width[6]+shrink(q)
    $globals.active_width[6] += shrink!($globals, q);

    use crate::pascal::integer;
    use crate::section_0115::pointer;
    use crate::section_0133::r#type;
    use crate::section_0133::subtype;
    use crate::section_0134::is_char_node;
    use crate::section_0135::width;
    use crate::section_0148::precedes_break;
    use crate::section_0149::glue_ptr;
    use crate::section_0150::shrink;
    use crate::section_0150::stretch;
    use crate::section_0150::stretch_order;
    use crate::section_0155::kern_node;
    use crate::section_0155::kern_node_subtype;
    use crate::section_0819::unhyphenated;
    use crate::section_0825::check_shrinkage;
    use crate::section_0829::try_break;
    use crate::section_0866::act_width;
}}

