#[test]
fn test_if_expression() {
    let input = "if (x < y) { x }";

    let l = Lexer::new(input.chars().collect());
    let mut p = Parser::new(l);
    let program = p.parse_program();
    check_errors(&program.errors);

    assert_eq!(program.statements.len(), 1);
    let stmt = &program.statements[0];
    if let Statement::Expression {
        token: _,
        expression,
    } = stmt
    {
        match expression {
            Expression::If {
                token: _,
                condition,
                consequence,
                alternative,
            } => {
                test_infix_expression(condition, "x", "<", "y");
                assert_eq!(None, *alternative);

                match consequence.as_ref() {
                    Statement::Block {
                        token: _,
                        statements,
                    } => {
                        assert_eq!(statements.len(), 1);
                        let s = &statements[0];
                        match s {
                            Statement::Expression {
                                token: _,
                                expression,
                            } => {
                                test_identifier(expression, "x");
                            }
                            _ => assert!(false, "statements[0] is not an Expression Statement"),
                        }
                    }
                    _ => assert!(
                        false,
                        "consequence is not a Block Statement, got {}",
                        consequence
                    ),
                }
            }
            _ => assert!(
                false,
                "stmt.expression is not an If Expression!, got {}",
                stmt
            ),
        }
    } else {
        assert!(false, "stmt is not an Expression Statement!");
    }
}

#[test]
fn test_if_else_expression() {
    let input = "if (x < y) { x } else { y }";

    let l = Lexer::new(input.chars().collect());
    let mut p = Parser::new(l);
    let program = p.parse_program();
    check_errors(&program.errors);

    assert_eq!(program.statements.len(), 1);
    let stmt = &program.statements[0];
    if let Statement::Expression {
        token: _,
        expression,
    } = stmt
    {
        match expression {
            Expression::If {
                token: _,
                condition,
                consequence,
                alternative,
            } => {
                test_infix_expression(condition, "x", "<", "y");

                match consequence.as_ref() {
                    Statement::Block {
                        token: _,
                        statements,
                    } => {
                        assert_eq!(statements.len(), 1);
                        let s = &statements[0];
                        match s {
                            Statement::Expression {
                                token: _,
                                expression,
                            } => {
                                test_identifier(expression, "x");
                            }
                            _ => assert!(
                                false,
                                "consequence.statements[0] is not an Expression Statement"
                            ),
                        }
                    }
                    _ => assert!(
                        false,
                        "consequence is not a Block Statement, got {}",
                        consequence
                    ),
                }

                match alternative {
                    Some(b) => match b.as_ref() {
                        Statement::Block {
                            token: _,
                            statements,
                        } => {
                            assert_eq!(statements.len(), 1);
                            let s = &statements[0];
                            match s {
                                Statement::Expression {
                                    token: _,
                                    expression,
                                } => {
                                    test_identifier(expression, "y");
                                }
                                _ => assert!(
                                    false,
                                    "alternative.statements[0] is not an Expression Statement"
                                ),
                            }
                        }
                        _ => assert!(false, "alternative is not a Block Statement, got {}", b),
                    },
                    _ => assert!(false, "alternative is None"),
                }
            }
            _ => assert!(
                false,
                "stmt.expression is not an If Expression!, got {}",
                stmt
            ),
        }
    } else {
        assert!(false, "stmt is not an Expression Statement!");
    }
}

#[test]
fn test_parse_function_literal() {
    let input = "fn(x, y) { x + y }";

    let l = Lexer::new(input.chars().collect());
    let mut p = Parser::new(l);
    let program = p.parse_program();
    check_errors(&program.errors);

    assert_eq!(program.statements.len(), 1);
    let expr_stmt = &program.statements[0];
    if let Statement::Expression {
        token: _,
        expression,
    } = expr_stmt
    {
        match expression {
            Expression::FunctionLiteral {
                token: _,
                parameters,
                body,
            } => {
                test_literal_expression(&parameters[0], expression_from_literal("x"));
                test_literal_expression(&parameters[1], expression_from_literal("y"));

                match body.as_ref() {
                    Statement::Block {
                        token: _,
                        statements,
                    } => {
                        assert_eq!(statements.len(), 1);
                        let s = &statements[0];
                        match s {
                            Statement::Expression {
                                token: _,
                                expression,
                            } => {
                                test_infix_expression(expression, "x", "+", "y");
                            }
                            _ => assert!(
                                false,
                                "function body statement is not an Expression Statement, got {}",
                                s
                            ),
                        }
                    }
                    _ => assert!(false, "body is not a Block Statement, got {}", body),
                }
            }
            _ => assert!(
                false,
                "expression is not a FunctionLiteral Expression, got {}",
                expression
            ),
        }
    } else {
        assert!(
            false,
            "program.statements[0] is not an Expression Statement!"
        );
    }
}

#[test]
fn test_function_parameter_parsing() {
    let tests = vec![
        ("fn() {};", vec![]),
        ("fn(x) {};", vec!["x"]),
        ("fn(x, y, z) {};", vec!["x", "y", "z"]),
    ];

    for (input, expected_params) in tests.iter() {
        let l = Lexer::new(input.chars().collect());
        let mut p = Parser::new(l);
        let program = p.parse_program();
        check_errors(&program.errors);

        assert_eq!(program.statements.len(), 1);
        let stmt = &program.statements[0];

        if let Statement::Expression {
            token: _,
            expression,
        } = stmt
        {
            match expression {
                Expression::FunctionLiteral {
                    token: _,
                    parameters,
                    body: _,
                } => {
                    assert_eq!(parameters.len(), expected_params.len());

                    for (expr, expected) in parameters.iter().zip(expected_params.iter()).next() {
                        test_literal_expression(expr, expression_from_literal(expected));
                    }
                }
                _ => assert!(
                    false,
                    "stmt.expression is not a FunctionLiteral, got {}",
                    stmt
                ),
            }
        } else {
            assert!(false, "stmt is not an Expression Statement!");
        }
    }
}

