fn gcd(a: usize, b: usize) -> usize {
        if b == 0usize {
            a
        } else {
            gcd(b, a % b)
        }
}

fn calc_sum(a: usize, b: usize, c: usize, d: usize) -> usize {
    let CB = gcd(c,b);
    let AB = gcd(a,b);
    let DA = gcd(d,a);
    let CD = gcd(c,d);
    let G = CB + AB + DA + CD;
    let square = a*b + b*c + c*d + d*a;
    let B2 = square - G + 2;
//    if B2 < 0 {
//        println!("square-{}", square);
//        println!("G-{}", G);
//        println!("{}-{}", B2, B2/2);
//        println!("{} {} {} {}", a, b, c, d);
