use std::iter::{FromIterator, IntoIterator};
use std::ops::{Add, Sub, Mul};
use std::slice::Iter;

/// Matrix4 is a 4x4 matrix stored in row-major format
#[derive(Debug, PartialEq, Copy, Clone)]
pub struct Matrix4 {
    mat: [f32; 16],
}

impl Matrix4 {
    /// Return the zero matrix
    pub fn zero() -> Matrix4 {
        Matrix4 { mat: [0f32; 16] }
    }
    /// Return the identity matrix
    pub fn identity() -> Matrix4 {
        Matrix4 { mat:
            [1f32, 0f32, 0f32, 0f32,
             0f32, 1f32, 0f32, 0f32,
             0f32, 0f32, 1f32, 0f32,
             0f32, 0f32, 0f32, 1f32]
        }
    }
    /// Create the matrix using the values passed
    pub fn new(mat: [f32; 16]) -> Matrix4 {
        Matrix4 { mat: mat }
    }
    /// Access the element at row `i` column `j`
    pub fn at(&self, i: usize, j: usize) -> &f32 {
        &self.mat[4 * i + j]
    }
    /// Mutably access the element at row `i` column `j`
    pub fn at_mut(&mut self, i: usize, j: usize) -> &mut f32 {
        &mut self.mat[4 * i + j]
    }
    /// Compute and return the transpose of this matrix
    pub fn transpose(&self) -> Matrix4 {
        let mut res = Matrix4::zero();
        for i in 0..4 {
            for j in 0..4 {
                *res.at_mut(i, j) = *self.at(j, i);
            }
        }
        res
    }
    /// Compute and return the inverse of this matrix
    pub fn inverse(&self) -> Matrix4 {
        //MESA's matrix inverse, tweaked for row-major matrices
        let mut inv = Matrix4::zero();
        inv.mat[0] = self.mat[5] * self.mat[10] * self.mat[15]
            - self.mat[5]  * self.mat[11] * self.mat[14]
            - self.mat[9]  * self.mat[6]  * self.mat[15]
            + self.mat[9]  * self.mat[7]  * self.mat[14]
            + self.mat[13] * self.mat[6]  * self.mat[11]
            - self.mat[13] * self.mat[7]  * self.mat[10];

        inv.mat[4] = -self.mat[4]  * self.mat[10] * self.mat[15]
            + self.mat[4]  * self.mat[11] * self.mat[14]
            + self.mat[8]  * self.mat[6]  * self.mat[15]
            - self.mat[8]  * self.mat[7]  * self.mat[14]
            - self.mat[12] * self.mat[6]  * self.mat[11]
            + self.mat[12] * self.mat[7]  * self.mat[10];

        inv.mat[8] = self.mat[4]  * self.mat[9] * self.mat[15]
            - self.mat[4]  * self.mat[11] * self.mat[13]
            - self.mat[8]  * self.mat[5] * self.mat[15]
            + self.mat[8]  * self.mat[7] * self.mat[13]
            + self.mat[12] * self.mat[5] * self.mat[11]
            - self.mat[12] * self.mat[7] * self.mat[9];

        inv.mat[12] = -self.mat[4]  * self.mat[9] * self.mat[14]
            + self.mat[4]  * self.mat[10] * self.mat[13]
            + self.mat[8]  * self.mat[5] * self.mat[14]
            - self.mat[8]  * self.mat[6] * self.mat[13]
            - self.mat[12] * self.mat[5] * self.mat[10]
            + self.mat[12] * self.mat[6] * self.mat[9];

        inv.mat[1] = -self.mat[1]  * self.mat[10] * self.mat[15]
            + self.mat[1]  * self.mat[11] * self.mat[14]
            + self.mat[9]  * self.mat[2] * self.mat[15]
            - self.mat[9]  * self.mat[3] * self.mat[14]
            - self.mat[13] * self.mat[2] * self.mat[11]
            + self.mat[13] * self.mat[3] * self.mat[10];

        inv.mat[5] = self.mat[0]  * self.mat[10] * self.mat[15]
            - self.mat[0]  * self.mat[11] * self.mat[14]
            - self.mat[8]  * self.mat[2] * self.mat[15]
            + self.mat[8]  * self.mat[3] * self.mat[14]
            + self.mat[12] * self.mat[2] * self.mat[11]
            - self.mat[12] * self.mat[3] * self.mat[10];

        inv.mat[9] = -self.mat[0]  * self.mat[9] * self.mat[15]
            + self.mat[0]  * self.mat[11] * self.mat[13]
            + self.mat[8]  * self.mat[1] * self.mat[15]
            - self.mat[8]  * self.mat[3] * self.mat[13]
            - self.mat[12] * self.mat[1] * self.mat[11]
            + self.mat[12] * self.mat[3] * self.mat[9];

        inv.mat[13] = self.mat[0]  * self.mat[9] * self.mat[14]
            - self.mat[0]  * self.mat[10] * self.mat[13]
            - self.mat[8]  * self.mat[1] * self.mat[14]
            + self.mat[8]  * self.mat[2] * self.mat[13]
            + self.mat[12] * self.mat[1] * self.mat[10]
            - self.mat[12] * self.mat[2] * self.mat[9];

        inv.mat[2] = self.mat[1]  * self.mat[6] * self.mat[15]
            - self.mat[1]  * self.mat[7] * self.mat[14]
            - self.mat[5]  * self.mat[2] * self.mat[15]
            + self.mat[5]  * self.mat[3] * self.mat[14]
            + self.mat[13] * self.mat[2] * self.mat[7]
            - self.mat[13] * self.mat[3] * self.mat[6];

        inv.mat[6] = -self.mat[0]  * self.mat[6] * self.mat[15]
            + self.mat[0]  * self.mat[7] * self.mat[14]
            + self.mat[4]  * self.mat[2] * self.mat[15]
            - self.mat[4]  * self.mat[3] * self.mat[14]
            - self.mat[12] * self.mat[2] * self.mat[7]
            + self.mat[12] * self.mat[3] * self.mat[6];

        inv.mat[10] = self.mat[0]  * self.mat[5] * self.mat[15]
            - self.mat[0]  * self.mat[7] * self.mat[13]
            - self.mat[4]  * self.mat[1] * self.mat[15]
            + self.mat[4]  * self.mat[3] * self.mat[13]
            + self.mat[12] * self.mat[1] * self.mat[7]
            - self.mat[12] * self.mat[3] * self.mat[5];

        inv.mat[14] = -self.mat[0]  * self.mat[5] * self.mat[14]
            + self.mat[0]  * self.mat[6] * self.mat[13]
            + self.mat[4]  * self.mat[1] * self.mat[14]
            - self.mat[4]  * self.mat[2] * self.mat[13]
            - self.mat[12] * self.mat[1] * self.mat[6]
            + self.mat[12] * self.mat[2] * self.mat[5];

        inv.mat[3] = -self.mat[1] * self.mat[6] * self.mat[11]
            + self.mat[1] * self.mat[7] * self.mat[10]
            + self.mat[5] * self.mat[2] * self.mat[11]
            - self.mat[5] * self.mat[3] * self.mat[10]
            - self.mat[9] * self.mat[2] * self.mat[7]
            + self.mat[9] * self.mat[3] * self.mat[6];

        inv.mat[7] = self.mat[0] * self.mat[6] * self.mat[11]
            - self.mat[0] * self.mat[7] * self.mat[10]
            - self.mat[4] * self.mat[2] * self.mat[11]
            + self.mat[4] * self.mat[3] * self.mat[10]
            + self.mat[8] * self.mat[2] * self.mat[7]
            - self.mat[8] * self.mat[3] * self.mat[6];

        inv.mat[11] = -self.mat[0] * self.mat[5] * self.mat[11]
            + self.mat[0] * self.mat[7] * self.mat[9]
            + self.mat[4] * self.mat[1] * self.mat[11]
            - self.mat[4] * self.mat[3] * self.mat[9]
            - self.mat[8] * self.mat[1] * self.mat[7]
            + self.mat[8] * self.mat[3] * self.mat[5];

        inv.mat[15] = self.mat[0] * self.mat[5] * self.mat[10]
            - self.mat[0] * self.mat[6] * self.mat[9]
            - self.mat[4] * self.mat[1] * self.mat[10]
            + self.mat[4] * self.mat[2] * self.mat[9]
            + self.mat[8] * self.mat[1] * self.mat[6]
            - self.mat[8] * self.mat[2] * self.mat[5];

        let mut det = self.mat[0] * inv.mat[0] + self.mat[1] * inv.mat[4]
            + self.mat[2] * inv.mat[8] + self.mat[3] * inv.mat[12];
        assert!(det != 0f32);
        det = 1f32 / det;

        for x in &mut inv.mat {
            *x *= det;
        }
        inv
    }
    /// Return an iterator over the matrix's elements. The iterator goes
    /// row by row through the matrix.
    pub fn iter(&self) -> Iter<f32> {
        self.mat.iter()
    }
    pub fn has_nans(&self) -> bool {
        for x in &self.mat {
            if x.is_nan() {
                return true;
            }
        }
        false
    }
}

impl FromIterator<f32> for Matrix4 {
    /// Create the matrix using the values from the iterator. The iterator should return
    /// the rows of the matrix one after another. The first 16 values returned will
    /// be used to set the matrix elements. If fewer than 16 values are returned the
    /// remaining entries will be 0
    fn from_iter<T: IntoIterator<Item = f32>>(it: T) -> Matrix4 {
        let mut m = Matrix4::zero();
        for (r, x) in m.mat.iter_mut().zip(it.into_iter()) {
            *r = x;
        }
        m
    }
}

impl<'a> FromIterator<&'a f32> for Matrix4 {
    /// Create the matrix using the values from the iterator. The iterator should return
    /// the rows of the matrix one after another. The first 16 values returned will
    /// be used to set the matrix elements. If fewer than 16 values are returned the
    /// remaining entries will be 0
    fn from_iter<T: IntoIterator<Item = &'a f32>>(it: T) -> Matrix4 {
        let mut m = Matrix4::zero();
        for (r, x) in m.mat.iter_mut().zip(it.into_iter()) {
            *r = *x;
        }
        m
    }
}

impl Add for Matrix4 {
    type Output = Matrix4;
    /// Add two matrices together
    fn add(self, rhs: Matrix4) -> Matrix4 {
        self.mat.iter().zip(rhs.mat.iter()).map(|(&x, &y)| x + y).collect()
    }
}

impl Sub for Matrix4 {
    type Output = Matrix4;
    /// Subtract two matrices
    fn sub(self, rhs: Matrix4) -> Matrix4 {
        self.mat.iter().zip(rhs.mat.iter()).map(|(&x, &y)| x - y).collect()
    }
}

impl Mul for Matrix4 {
    type Output = Matrix4;
    /// Multiply two matrices
    fn mul(self, rhs: Matrix4) -> Matrix4 {
        let mut res = Matrix4::zero();
        for i in 0..4 {
            for j in 0..4 {
                *res.at_mut(i, j) = *self.at(i, 0) * *rhs.at(0, j)
                    + *self.at(i, 1) * *rhs.at(1, j)
                    + *self.at(i, 2) * *rhs.at(2, j)
                    + *self.at(i, 3) * *rhs.at(3, j);
            }
        }
        res
    }
}

impl Mul<f32> for Matrix4 {
    type Output = Matrix4;
    /// Multiply the matrix by a scalar
    fn mul(self, rhs: f32) -> Matrix4 {
        self.mat.iter().map(|&x| x * rhs).collect()
    }
}

impl Mul<Matrix4> for f32 {
    type Output = Matrix4;
    /// Multiply the matrix by a scalar
    fn mul(self, rhs: Matrix4) -> Matrix4 {
        rhs.mat.iter().map(|&x| x * self).collect()
    }
}

#[test]
fn test_add() {
    let mut a = Matrix4::identity();
    *a.at_mut(0, 1) = 1f32;
    let mut b = Matrix4::identity();
    *b.at_mut(2, 3) = 3f32;
    let c = Matrix4::new([2f32, 1f32, 0f32, 0f32,
                          0f32, 2f32, 0f32, 0f32,
                          0f32, 0f32, 2f32, 3f32,
                          0f32, 0f32, 0f32, 2f32]);
    assert!(a + b == c);
}
#[test]
fn test_sub() {
    let mut a = Matrix4::identity();
    *a.at_mut(0, 1) = 1f32;
    let mut b = Matrix4::identity();
    *b.at_mut(2, 3) = 3f32;
    let c = Matrix4::new([0f32, 1f32, 0f32, 0f32,
                          0f32, 0f32, 0f32, 0f32,
                          0f32, 0f32, 0f32, -3f32,
                          0f32, 0f32, 0f32, 0f32]);
    assert!(a - b == c);
}
#[test]
fn test_mul() {
    assert!(Matrix4::identity() * Matrix4::identity() == Matrix4::identity());
    let a = Matrix4::new([1f32,  2f32,  1f32,  0f32,
                         3f32,  1f32,  4f32,  2f32,
                         1f32,  2f32, -5f32,  4f32,
                         3f32,  2f32,  4f32,  1f32]);
    let b = Matrix4::new([8f32,  0f32,  2f32,  3f32,
                          -2f32,  1f32,  0f32,  1f32,
                          5f32, -2f32,  3f32,  1f32,
                          0f32,  0f32,  4f32,  1f32]);
    let c = Matrix4::new([9f32,   0f32,   5f32,   6f32,
                          42f32,  -7f32,  26f32,  16f32,
                          -21f32,  12f32,   3f32,   4f32,
                          40f32,  -6f32,  22f32,  16f32]);
    assert!(a * b == c);
}

use cmake::Config;

fn get_physx_target_os_name() -> String {
    let os = env::var("CARGO_CFG_TARGET_OS").unwrap();
    match os.as_str() {
        // CARGO_CFG_TARGET_OS uses "linux", "windows", and "macos"
        // PhysX uses "linux", "windows", and "mac"
        "macos" => "mac".to_owned(),
        _ => os,
    }
}

// Find the time of the most recent modification among all the files in a directory
fn most_recent_modification_time_in_dir(path: &PathBuf) -> Option<std::time::SystemTime> {
    use std::fs;

    fs::read_dir(&path).ok().and_then(|entries| {
        entries
            .filter_map(std::result::Result::ok)
            .filter_map(|entry| {
                let meta = entry.metadata().ok();
                meta.and_then(|meta| {
                    if meta.is_dir() {
                        None
                    } else {
                        meta.modified().ok()
                    }
                })
            })
            .max()
    })
}

// Get the sub-directory of the CMAKE build result which contains static libs.
// The CMAKE files in PhysX compute a compiler-dependent path, which can look like some of the following:
//
// "bin/linux.clang/debug"
// "bin/win.x86_64.vc141.md/debug"
// "bin/win.x86_64.vc142.md/profile"
// "bin/mac.x86_64/debug"
//
// In order not to have to replicate the CMAKE logic, we will inspect all paths with the structure
// "bin/*/debug" or "bin/*/profile", depending on the build profile passed to CMAKE.
// Among those directories, we choose the one containing the most recently modified files.
// This is to ensure that we find the correct folder even if it contains stale results from different compilers.
fn locate_output_lib_dir(mut cmake_build_out: PathBuf, build_profile: &str) -> String {
    use std::fs;

    // Always within the "bin" folder of the CMAKE output
    cmake_build_out.push("bin");

    if let Ok(entries) = fs::read_dir(&cmake_build_out) {
        // Get all sub-directories in "bin"
        let out_dirs = entries
            .filter_map(std::result::Result::ok)
            .filter(|entry| entry.metadata().map(|m| m.is_dir()).unwrap_or(false));

        // Find the ones containing "debug" or "profile", and pick the most recently modified.
        let out_dir = out_dirs
            .filter_map(|out_dir| {
                let mut out_dir = out_dir.path();
                out_dir.push(build_profile);

                let newest_in_dir = most_recent_modification_time_in_dir(&out_dir)?;
                Some((out_dir, newest_in_dir))
            })
            .max_by_key(|(_, m)| *m)
            .map(|(d, _)| d);

        out_dir
            .expect("could not locate output directory for PhysX static libs")
            .display()
            .to_string()
    } else {
        panic!("Could not inspect cmake build output directory");
    }
}

fn cmake_compile(target_env: Environment) {
    let physx_root_dir = env::current_dir().unwrap().join("PhysX/physx");
    let physx_parent_dir = physx_root_dir.parent().unwrap();

    // Based on PhysX/physx/generate_projects.sh
    env::set_var(
        "PHYSX_ROOT_DIR",
        &physx_root_dir.to_string_lossy().into_owned(),
    );
    env::set_var(
        "PM_PxShared_PATH",
        physx_parent_dir
            .join("pxshared")
            .to_string_lossy()
            .into_owned(),
    );
    env::set_var(
        "PM_CMakeModules_PATH",
        physx_parent_dir
            .join("externals/cmakemodules")
            .to_string_lossy()
            .into_owned(),
    );
    env::set_var(
        "PM_opengllinux_PATH",
        physx_parent_dir
            .join("externals/opengl-linux")
            .to_string_lossy()
            .into_owned(),
    );
    env::set_var("PM_PATHS", env::var("PM_opengllinux_PATH").unwrap());

    let output_dir = env::var("OUT_DIR").unwrap();

    let target_os = get_physx_target_os_name();
    let target_os = target_os.as_str();
    let mut physx_cfg = Config::new("PhysX/physx/source/compiler/cmake");

    if target_os == "linux" {
        physx_cfg.define("CMAKE_LIBRARY_ARCHITECTURE", "x86_64-unknown-linux-gnu");
    }

    if target_env.static_crt {
        physx_cfg.define("NV_USE_STATIC_WINCRT", "True");
    }

    let compiler = target_env
        .target_compiler
        .unwrap_or_else(|| "clang++".to_owned());

    let physx = physx_cfg
        .define("PX_OUTPUT_LIB_DIR", &output_dir)
        .define("PX_OUTPUT_BIN_DIR", &output_dir)
        .define("PX_OUTPUT_ARCH", "x86")
        .define("PX_BUILDSNIPPETS", "False")
        .define("PX_BUILDSAMPLES", "False")
        .define("PX_GENERATE_STATIC_LIBRARIES", "True")
        .define("PX_GENERATE_GPU_PROJECTS", "False")
        .define("TARGET_BUILD_PLATFORM", target_os)
        // We don't care about the C compiler as it is never used for PhysX
        //.define("CMAKE_C_COMPILER", "clang")
        .define("CMAKE_CXX_COMPILER", compiler)
        .define("CMAKE_BUILD_TYPE", &target_env.mode)
        .profile(&target_env.mode)
        .build();

    let lib_dir = locate_output_lib_dir(physx, &target_env.mode);
    println!("cargo:rustc-link-search=native={}", lib_dir);

    println!("cargo:rustc-link-lib=static=PhysXVehicle_static_64");
    println!("cargo:rustc-link-lib=static=PhysX_static_64");
    println!("cargo:rustc-link-lib=static=PhysXCooking_static_64");
    println!("cargo:rustc-link-lib=static=PhysXPvdSDK_static_64");
    println!("cargo:rustc-link-lib=static=PhysXCommon_static_64");
    println!("cargo:rustc-link-lib=static=PhysXFoundation_static_64");
    println!("cargo:rustc-link-lib=static=PhysXCharacterKinematic_static_64");
    println!("cargo:rustc-link-lib=static=PhysXExtensions_static_64");
}

